pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items are wasted.
    // Penalize "unusable" residuals (too small for any plausible follow-up item) heavily.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 20 {
        // Dead space zone: gap too small to be useful later.
        score += 12.0 * (20 - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly or well in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 6.0; // next item can still use the gap
        } else {
            // next item cannot use the gap: the residual becomes dead weight
            score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open,
    // but allow opening a new bin early in the stream or when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += bin_pressure * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (avoids wasting a fresh bin on a poor fit later).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a "tight" bin;
    // filling tight bins to completion is good. If residual is far above mean, deprioritize.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for filling larger-residual bins when few bins exist (keeps small gaps consolidated).
    if open_bins_count <= 2 {
        score -= 0.1 * bin_residual as f64;
    }

    // New-bin candidate adjustment: opening a new bin should only win when the current item
    // would leave a large, awkward gap in an existing bin.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; the dead-space penalties above make bad fits lose to it
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (1/2, 1/3, 1/4) — leftovers near these fractions
    // are more reusable by future items, so reward them.
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;
    let pr = post_residual as f64;

    // Distance to nearest harmonic anchor; closeness => subtract bonus.
    let d_half = (pr - half).abs();
    let d_third = (pr - third).abs();
    let d_quarter = (pr - quarter).abs();
    let d_min = d_half.min(d_third).min(d_quarter);
    score -= (cap * 0.15) * (1.0 - d_min / half).max(0.0);

    // Integer-division dead-space penalty: residual in the awkward
    // (1, 10) band is nearly unusable given min item size.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot ever fit, penalize mildly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 20.0 * (1.0 - ((pr - ni) / cap).abs());
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, discourage opening
    // a new bin (subtract), scaled by how full the bin already is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - bin_residual as f64 / cap);
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the stream is early or open bins are many and
    // fragmented (mean residual low relative to capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = open_bins_count as f64 / 8.0;
        let new_bin_bonus = 25.0 * (1.0 - progress) + 30.0 * fragmentation + pressure * 10.0;
        // Base cost of a fresh bin keeps it from winning on good fits.
        score = score.min(0.0) + cap * 0.55 - new_bin_bonus;
    }

    // Modulo tie-break on item class: items in coarse size classes pair
    // better with residuals of matching class; small deterministic nudge.
    let cls = (item_size / 10) as f64;
    let prc = (post_residual / 10) as f64;
    score -= 0.5 * ((cls - prc).abs() < 1.5) as u8 as f64;

    // Mild pressure to prefer fewer open bins when fragmentation is low.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).clamp(0.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here later; mild reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * tight;
        } else {
            // next item cannot use this residual; penalize dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: avoid leaving unusually
    // large residual relative to other bins (poor space utilization).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs() + (if dev > 0.0 { 0.5 } else { 0.0 }) * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 0 {
        // new-bin candidate: baseline is post_residual = capacity - item_size.
        // Favor new bin only if item is large relative to capacity (leaves small residual)
        // or few bins are open.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 200.0 * item_frac;
        if open_bins_count > 4 {
            score -= 50.0;
        }
    }

    // Progress-based tie-break: later in stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small nudge to prefer bins with less residual overall.
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Unusable gap: too small for the next item and typical small items.
        let unusable = next_item_size == 0 || (next_item_size > 0 && (post_residual as u32) < next_item_size);
        if unusable {
            score += 30.0 + dead * 1.5; // heavy penalty for creating dead space
        } else {
            score -= 5.0; // gap is still usable by the lookahead item: reward
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Open-bins pressure: discourage spreading across many bins when few fit options exist.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0; // last-chance bin: strongly prefer using it
    }
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: only attractive when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset if current bins would waste space.
        score = 25.0 + (item_size as f64 * 0.1);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Slight preference for bins below mean residual (balances load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Aggressive 2-step lookahead: reward when next item fits into post_residual
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let chain_fit = next_item_size as f64 / post_residual as f64;
                score -= 60.0 * chain_fit;
                // Bonus if chained placement leaves near-zero residual
                let chain_post = post_residual - next_item_size;
                if chain_post == 0 {
                    score -= 250.0;
                } else if chain_post <= 10 {
                    score -= 80.0;
                }
            } else {
                // Next item cannot chain: penalize proportional to leftover dead space
                score += 25.0 * (next_item_size as f64 / post_residual as f64);
            }
        }

        // Penalize small unusable residuals (dead space)
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral baseline, penalize opening when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin early in stream or when few open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 || open_bins_count < 3 {
            score -= 100.0;
        }
        // Prefer new bin if mean residual is small (existing bins are full)
        if mean_residual < item_size as f64 {
            score -= 200.0;
        }
    }

    // Mild pressure to consolidate into fewer bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, reward below instead
    }

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize "unusable" small gaps: residual that few future items could use.
    let gap_uselessness = if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64 * 8.0
    } else if post_residual < 20 {
        (20 - post_residual) as f64 * 3.0
    } else {
        0.0
    };
    score += gap_uselessness;

    // If the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (30.0 - slack.min(30) as f64) * 2.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty proportional to wasted potential
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins give bad fits.
    if bin_residual == bin_capacity {
        // mild default preference against opening new bins
        score += 25.0;
        // but if many open bins exist and mean residual is small (fragmented),
        // opening fresh is more attractive
        score -= open_bins_count as f64 * 1.5;
        score += (mean_residual - 50.0).max(0.0) * 0.5;
    } else {
        // open-bin pressure: discourage spreading across too many bins when residual is high
        score += open_bins_count as f64 * 0.3;
        // reward using bins whose residual is close to mean (balance)
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;
    }

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual > 10 && post_residual < 20 {
        score += 8.0; // risky mid-gap zone
    }

    // Reward tight fits (small but not zero residual is good; zero is perfect).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins deviating below mean residual (filler bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // New-bin candidate: neutral baseline with mild penalty so it's chosen only
    // when all open bins score badly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 0.35 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin pairs well with a large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual non-linearly.
    let cap = bin_capacity as f64;
    let tight = post_residual as f64 / cap;
    score += 18.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small dead space that cannot plausibly fit typical items is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Post-residual useless for the known next item: penalize proportionally.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > 0.0 {
        let frag = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * frag;
    }
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive early in stream or when the item is huge
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let open_bonus = (open_bins_count as f64) * 3.0;
        score = 100.0 + fit_quality * 20.0 - desperation * 60.0 - open_bonus * (1.0 - progress) - 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= ~10 units) are pure waste. Penalize hard.
    let dead_threshold = 9.0;
    if post > 0.0 && post <= dead_threshold {
        score += 60.0 * (1.0 - post / dead_threshold); // up to +60 for 1-unit slivers
    }

    // Small residual above dead threshold but below next item: still likely waste
    if next_item_size > 0 && post > 0.0 && (post as u32) < next_item_size {
        score += 15.0 * (1.0 - post / cap);
    }

    // Reward perfect / near-perfect fits strongly
    if post == 0 {
        score -= 100.0;
    } else if (post as u32) == next_item_size && next_item_size > 0 {
        score -= 40.0; // leaves exactly the room the next item needs
    }

    // Reward tight fit relative to bin capacity
    score -= 25.0 * (item_size as f64 / cap) * (bin_residual as f64 / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins whose residual is close to what we consume (avoid fragmenting fat bins)
    score += 0.3 * (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: only attractive when existing bins would create bad dead space
    if bin_residual == bin_capacity {
        // neutral-ish baseline; dead-space penalties above on real bins make poor
        // fits lose, while good fits (small post_residual) beat this.
        score = 45.0 + 2.0 * open_bins_count as f64 * 0.2 - 10.0 * (item_size as f64 / cap);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0 * (next_item_size as f64 / cap);
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative at all
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any item (min size 1,
    // but tiny gaps < 12 are statistically hard to fill) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 25.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this bin is the only one that fits the item, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement; if post_residual is too small for next item,
    // penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // Mean residual coupling: if this bin's residual is well below the mean,
    // it is a good candidate to fill (reduces spread of residuals).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate scoring: an empty bin has high residual; make it
    // attractive only when the item is large relative to capacity or when
    // no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Large items are fine to start a new bin with.
        if item_size >= 60 {
            score -= 40.0;
        }
        // If this is the last chance bin, opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 1000.0;
        }
        // Dead space that cannot fit the next item is wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 2.5 * (next_item_size - post_residual) as f64;
        }
        // Non-linear penalty on tiny gaps (worst kind of dead space).
        let gap = post_residual as f64;
        score += 20.0 * (-gap / 10.0).exp();
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 5.0; // discourage new bin when existing space suffices
        } else {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for zero or tiny post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 500.0 - (post_residual as f64) * 20.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) == nxt {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how snugly
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 150.0 * snug;
        } else {
            // next item will NOT fit here: penalize wasted residual
            let waste = nxt - post_residual as f64;
            score += 50.0 * waste.min(90.0);
        }
        // coupling with mean residual: bin already deviates from fleet mean
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.3 * dev;
    }

    // Penalize large dead space that nothing can use later (min item 1).
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }
    // Dead-space penalty grows with residual size but cap vs new-bin alternative.
    score += 0.5 * (post_residual as f64).powf(1.2) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or fit is bad; otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        // neutral base for empty bin; make it competitive but not dominant
        score = 40.0 + post_residual as f64;
        if open_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Slight preference for bins with low residual among fitting bins.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 and integer division bands
    let pr = post_residual;
    let class = pr % 10;
    let band = pr / 10; // 0..=10

    // Reward small post_residual, especially "harmonic" residues that pair well
    // with common item sizes (multiples of 10, and sizes 1..100 unknown distribution).
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if class == 0 {
        score -= 15.0; // post_residual is a multiple of 10: reusable by round sizes
    } else if class <= 3 {
        score += 8.0; // awkward sliver
    }

    // Dead-space penalty: residuals below the minimum item size are unusable
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to wasted capacity
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when open bins
    // would create bad fits (mean residual low means bins are nearly full).
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55;
        // open new bin more readily when existing residuals are small/fragmented
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score = base + (1.0 - fragmentation) * 10.0
            - (open_bins_count as f64) * 0.5
            + (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Mild tie-break: prefer tighter bins (smaller bin_residual) among equals
    score += (bin_residual as f64) * 0.02;

    // Integer-division threshold: bins whose residual band is high (>=5, i.e. >=50 free)
    // are less precious; slightly deprioritize urgency there.
    if band >= 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * next_item_size as f64;
            // exact match of post_residual to next item is ideal
            score -= 30.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Penalize small unusable residuals (dead space that nothing can fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins that are tighter (below mean residual)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // baseline penalty so new bins are opened only when beneficial
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening a fresh bin lets both items pack together
            score -= 10.0;
        }
    }

    // Mild late-stream consolidation: favor existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer-division thresholds (capacity fractions).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space classes: tiny leftovers (<=10) are almost unusable given
    // item sizes >= 1 but practically hard to fill -> strong penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: excellent
    } else if post_residual <= 10 {
        score += 55.0; // likely dead space
    } else if post_residual <= 25 {
        score += 18.0; // awkward class
    } else if post_residual <= 50 {
        score -= 5.0; // half-bin class: still useful
    } else {
        score -= 12.0; // large residual: very reusable
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common
    // item-size classes (e.g. multiples of 10) pair well with future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Coupling with lookahead item: reward residuals that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // exact harmonic match: next item fills residual to a clean class
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 15.0;
            } else if after_next <= 10 {
                score += 12.0; // would create dead space for the item after
            }
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // mean residual across open bins is already tight (items are big) or
    // many bins exist and this item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < 30.0;
        let many_open = open_bins_count as f64 > 20.0 + 40.0 * progress;
        if item_size >= 70 || (tight && item_size >= 50) || many_open {
            score -= 20.0;
        } else {
            score += 30.0; // prefer existing bins early on
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the pool balanced, avoids extreme fragmentation).
    score += 0.15 * (mean_residual - frac * cap).abs().min(50.0);

    // Mild progression-aware tie-break: later in the stream, compact more.
    score += 0.02 * (1.0 - step_index as f64 / total_items.max(1) as f64) * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly usable by the lookahead item.
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64)).powi(4);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: penalize unless no good fit exists or stream is early.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let tightness = (post_residual as f64 / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score += 90.0 * scarcity * (1.0 - tightness.clamp(0.0, 1.0));
        score += 45.0 * (1.0 - scarcity);
    }

    // Prefer bins whose residual is close to the mean (balanced usage), scaled by openness.
    let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
    score += 12.0 * dev * (open_bins_count.min(20) as f64).ln().max(1.0);

    // Late in the stream, be more conservative: avoid creating tiny unusable residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (below the minimum size of 1, but practically
    // below a "useful gap" threshold) are heavily penalized.
    let useful_threshold = 10.0f64.min(bin_capacity as f64);
    if (post_residual as f64) < useful_threshold && post_residual > 0 {
        score += 40.0 + 2.0 * (useful_threshold - post_residual as f64);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item
    // (k=2 lookahead exploitation).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Gap cannot hold next item: mild penalty scaled by gap smallness.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage closing out bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Alignment with mean residual: bins far below the mean residual create
    // fragmented outliers; penalize deviation.
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let spread_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - 8.0 + spread_pressure.min(20.0);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is clearly right
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: small gaps (< 10, the minimum item size)
    // are permanently unusable -> heavy penalty scaled by how "wasted" they are.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Moderately small gaps are risky too (few future items fit).
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 2.5;
    }

    // Post-residual that exactly fits the lookahead item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + post_residual as f64 * 0.5;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is below average (tighter bins get filled first),
    // keeping larger residuals available for larger future items.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.8;

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // relative to residuals or no good fit exists; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > mean_residual as u32 { 40.0 } else { 0.0 };
        let desperate = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += 25.0 - large_item_bonus + desperate;
    }

    // Slight late-stream tightening: waste matters more near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (good fits).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize dead space that can never fit typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // limited usability
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize wasting residual the next item could have used elsewhere.
            score += 0.10 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // New-bin candidate logic: an empty bin is attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, amortized by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // An empty bin guarantees the next item fits too.
            score -= 8.0;
        }
    }

    // Global pressure: when many bins are open with high mean residual,
    // prefer consolidating into existing space rather than spreading.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.5 * open_bins_count as f64;
        // Prefer bins below mean residual (tighter bins get used first).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead);
    } else if dead < 20.0 {
        // gaps 10..19 can hold small items but are still wasteful
        score += 6.0 * (20.0 - dead);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward fitting item into a bin whose residual matches next item too (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space that next item cannot use
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 3.0 * pressure;

    // New-bin candidate: penalize unless current bins are mostly full / tight
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let tight = mean_fill / bin_capacity as f64;
        if tight < 0.7 {
            score += 80.0; // keep using open bins while they have room
        } else {
