            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how snugly
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 150.0 * snug;
        } else {
            // next item will NOT fit here: penalize wasted residual
            let waste = nxt - post_residual as f64;
            score += 50.0 * waste.min(90.0);
        }
        // coupling with mean residual: bin already deviates from fleet mean
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.3 * dev;
    }

    // Penalize large dead space that nothing can use later (min item 1).
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }
    // Dead-space penalty grows with residual size but cap vs new-bin alternative.
    score += 0.5 * (post_residual as f64).powf(1.2) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or fit is bad; otherwise keep existing bins preferred.
    if bin_residual == bin_capacity {
        // neutral base for empty bin; make it competitive but not dominant
        score = 40.0 + post_residual as f64;
        if open_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * progress;
    }

    // Slight preference for bins with low residual among fitting bins.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a non-linear term.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 18.0 * tight * tight;

    // Reward filling the bin heavily relative to its prior residual.
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * fill_ratio.min(1.0);

    // Last-chance bonus: if this is the only bin that fits, prefer it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_tight = (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 6.0 * (1.0 - lookahead_tight);
    } else if next_item_size > post_residual {
        // If next item won't fit here, mildly penalize leaving a useless gap.
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when no good alternative exists.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin when many bins already fit the item.
        score += 10.0 + 2.5 * (fitting_bins_count.saturating_sub(1)) as f64;
        // Penalize opening new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * (1.0 - progress);
        // If current item nearly fills a fresh bin, opening is fine.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 9.0;
        }
        // If the only fitting bin is this new one, neutralize penalty.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Prefer bins with residual below the mean (consolidate small spaces).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Global pressure: when many open bins exist, prefer reusing them.
    score -= 0.15 * (open_bins_count as f64).min(20.0);

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post_residual, but with diminishing returns via quadratic shaping.
    let mut score = pr * (1.0 + 0.002 * pr);

    // Non-linear coupling: post_residual relative to capacity, shaped by stream progress.
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (low post_residual) more strongly later in the stream,
    // when closing out bins matters more than keeping flexibility.
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (penalty grows with stream progress).
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Penalize bins that are far below mean residual early on (keep balanced flexibility),
    // smoothly decaying as the stream progresses.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // Lookahead: reward leaving room for the next item; smooth quadratic gap measure.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap;
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - gap / cap);
        }
    }

    // Slight preference for consolidating into fewer bins as stream advances.
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 500.0;
        return score;
    }

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets (eighths of capacity).
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let pr = post_residual as f64;
    let class = (pr / eighth).floor(); // 0..7

    // Dead space: leftover too small to ever be useful for typical items.
    // Penalize tiny non-zero leftovers heavily (class 0 => 1..=12 units).
    if pr < 13.0 {
        score += 90.0;
    }
    // Class 1 (13..=24): marginal slot, mildly penalize.
    if class == 1.0 {
        score += 25.0;
    }
    // Sweet-spot classes: leftover in mid ranges is reusable.
    if class >= 2.0 && class <= 4.0 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item cannot fit into the post-residual,
    // this placement "wastes" the bin for the immediate future.
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 20.0;
        } else {
            // Next item fits: reward proportionally to how snugly.
            score -= 10.0 * (1.0 - pr / cap);
        }
        // Harmonic pairing: post_residual + next_item_size exactly fills capacity.
        if post_residual + next_item_size == bin_capacity {
            score -= 120.0;
        }
        // Integer-division threshold: leftover divisible into useful chunks of 10.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate (residual == capacity): penalize so it's chosen only
    // when all open bins look bad; ease penalty late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 60.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Prefer filling bins below the mean residual (balancing toward closure).
    score += 0.3 * (pr - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 9) are effectively wasted capacity.
    // Penalize them quadratically on top of the base score.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Residuals in the "hard to reuse" band 10..=20 are mildly risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward tight fits strongly: filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 40.0;
    }

    // If the residual left behind can exactly host the lookahead item,
    // reward that chaining opportunity.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.25 * next_item_size as f64;
    }
    // If the leftover is just barely too small for the next item, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few bins,
    // opening a new one is relatively cheaper.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * open_pressure;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only let the new bin win when the current fit is bad and open bins
    // are few; otherwise make the new bin unattractive.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if bad_fit && open_bins_count < 6 {
            score -= 12.0; // allow opening a fresh bin
        } else {
            score += 30.0; // discourage abandoning open bins
        }
    }

    // Mean-residual coupling: prefer bins that are below average fullness
    // when the mean residual is high (spread into emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Slight early-stream preference for keeping bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item fits now AND next item exactly fills the remainder.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item still fits into the post residual (good 2-step chaining).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0 + (post_residual - next_item_size) as f64 * 0.15;
    }
    // Next item cannot use the leftover: dead space unless residual is tiny.
    else if next_item_size > 0 && post_residual > 0 {
        let waste = post_residual as f64;
        score += waste * 0.5;
        if waste < 5.0 {
            score -= 30.0; // negligible sliver, acceptable
        }
    }

    // Prefer bins whose residual was already below average (tight packing).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize the empty new-bin candidate unless it enables a perfect next fit
    // or no existing bin can fit the item.
    if bin_residual == bin_capacity {
        let perfect_next = next_item_size > 0 && next_item_size == bin_capacity - item_size;
        if !perfect_next {
            score += 200.0 + open_bins_count as f64 * 10.0;
            if next_item_size > 0 && next_item_size > bin_capacity - item_size {
                score -= 100.0; // next item won't fit after this anyway, new bin more attractive
            }
        } else {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let residual = bin_residual as f64;
    if residual > 0.0 {
        let fill_ratio = item_size as f64 / residual;
        score -= 12.0 * fill_ratio * fill_ratio;
    }

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) < nr && post_residual > 0 {
            // wasted sliver relative to next item
            score += 0.6 * (post_residual as f64) * (1.0 - (post_residual as f64) / nr);
        } else if post_residual as f64 >= nr {
            // reward leaving room exactly sized for the next item
            let slack = post_residual as f64 - nr;
            score -= 8.0 / (1.0 + slack);
        }
    } else {
        // last item: minimize post residual aggressively
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin when decent fits exist,
    // but allow it when open bins would leave very poor fits.
    if bin_residual == bin_capacity {
        let open_penalty = 30.0 + 2.0 * open_bins_count as f64;
        let desperation = if post_residual == 0 { 0.0 } else { 1.0 };
        score += open_penalty * desperation;
        if next_item_size > 0 && (bin_residual as f64 - next_item_size as f64) < 0.0 {
            score += 10.0;
        }
    }

    // Time horizon: early in stream, be conservative about fragmenting bins;
    // late in stream, pack greedily into existing bins.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 1.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global fragmentation pressure: if mean residual is low, squeeze harder.
    score -= 0.05 * (mean_residual - post_residual as f64);

    // Small bonus for exact fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post_residual, with non-linear penalty for large waste
    let mut score = r + 40.0 * rn * rn * cap;

    // Smooth coupling of waste with stream progress: tolerate waste early, penalize late
    score += 30.0 * rn * (progress * progress);

    // Reward tight fits (near-full bins) via smooth saturation term
    let tight = 1.0 - rn;
    score -= 15.0 * tight * tight * tight;

    // Lookahead coupling: bonus if next item fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // Last-chance bin: strongly reward using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Prefer filling bins when many are open; new-bin candidate gets slight penalty
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress * (open_bins_count as f64).sqrt();
    }

    // Mean-residual deviation: favor bins whose residual is close to the item need
    let dev = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Dead-space penalty: leftover that nothing (>=1) can use is worst.
    if post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual < quarter {
        score += 15.0; // small class
    } else if post_residual < half {
        score -= 10.0; // medium class is reusable
    } else {
        score -= 25.0; // large leftover is valuable
    }

    // Perfect fit reward via integer-division harmonic classes.
    if post_residual == 0 {
        score -= 100.0;
    } else if bin_capacity % post_residual == 0 {
        // leftover exactly divides capacity => future items can tile it perfectly
        score -= 20.0;
    }

    // Lookahead coupling: does next item fit the post-residual class?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // exact follow-up match
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap); // tighter follow-up is better
            // harmonic divisibility bonus
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize wasting a reusable class on it
            if post_residual >= half {
                score += 10.0;
            }
        }
    } else {
        // last item: prefer filling as much as possible
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = (bin_capacity - item_size.min(bin_capacity)) as f64 + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        } else if fitting_bins_count == 1 {
            // competing with a last-chance bin: only open if item is small and wastes little
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 25.0; // new bin can host the pair compactly
        }
    }

    // Progress-aware tightening: late in stream, conserve open bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / cap);

    // Mild preference to spread load when many bins are open with big residuals.
    if open_bins_count > 4 && post_residual >= half {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small gaps that no plausible item (>= ~5) can use are "dead".
    // Penalize them super-linearly so the packer avoids creating them.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead zone: residual too small to ever be filled by a typical item.
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap); // hard wall: avoid unusable slivers
        } else if gap < 25.0 {
            score += 8.0 * (25.0 - gap); // soft penalty: risky gap
        }
        // Perfect fit reward: zero waste is ideal.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // --- Lookahead coupling: if the next item fits the post-residual,
    // this placement chains nicely; reward it. If next item nearly fits
    // but post_residual is slightly too small, penalize the near-miss.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 20.0; // just barely blocked the next item
        }
    }

    // --- Open-bin pressure: discourage spreading across many bins when
    // residual capacity is plentiful; encourage filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += 0.8 * pressure * (1.0 - 0.3 * progress);

    // --- Last-chance bin: if this is the ONLY bin that fits, strongly
    // prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the item fits poorly everywhere else, i.e. when
    // placing in an existing bin would create large dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; rises with number of open bins
        // (consolidation pressure) but falls late in the stream.
        score = 40.0 + 6.0 * open_bins_count as f64 - 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        if item_size as f64 / bin_capacity as f64 > 0.6 {
            score -= 15.0;
        }
    } else {
        // Reward tight fits in existing bins: score ~ post_residual already
        // does best-fit; add a mild extra tilt toward exactness.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post_residual (tightest fit).

    // --- 2-step lookahead: reward leaving exactly room for the next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect chain: post_residual == next_item_size -> big reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if pr >= nxt {
            // Enough room for next item, but imperfect: mild reward scaled by closeness.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize dead space relative to its size.
            score += 10.0 * (nxt - pr) / nxt.max(1.0);
        }
    } else {
        // Last item: pure tightness fit, reward small post_residual strongly.
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if no open bin offers a decent fit.
        // Penalize new bins when good alternatives exist (post_residual small in some bin).
        let decent_fit_exists = post_residual as f64 >= item_size as f64 * 0.5
            && mean_residual > item_size as f64;
        if decent_fit_exists || (fitting_bins_count > 1 && next_item_size > 0) {
            score += 55.0;
        } else {
            // Few/no alternatives: slight preference to open fresh bin to keep
            // large contiguous space, but only early in the stream.
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score -= 10.0 * (1.0 - progress);
        }
    }

    // --- Mean residual coupling: bins far below mean residual are "ragged";
    // filling them up (small post_residual) is extra valuable ---
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        if ratio < 1.0 {
            score -= 8.0 * (1.0 - ratio);
        } else {
            score += 5.0 * (ratio - 1.0).min(2.0);
        }
    }

    // --- Many open bins: encourage consolidation into existing bins ---
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.35;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 9.0;
    }

    // Penalize wasting an almost-full bin on a small item.
    if item_size < bin_residual / 2 && bin_residual < bin_capacity / 3 {
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).max(0.0);
        score -= 2.5 * consolidation * (1.0 + progress);
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 45.0 + 6.0 * open_pressure - 30.0 * poor_fit - 12.0 * progress;
        // If next item is large, a fresh bin is more tolerable early.
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild time-horizon modulation: late in the stream, favor tighter packing.
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (pr / cap).powi(2);
    let mut score = pr;
    // non-linear polynomial coupling of post_residual with stream progress
    score -= 30.0 * tightness * (0.5 + 0.5 * progress) * (pr / cap);
    // reward near-perfect fits quadratically
    score -= 20.0 * (1.0 - pr / cap).powi(3);
    // penalize dead space that only fits the smallest items
    if pr < 10.0 && pr > 0.0 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }
    // lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (pr - nx) / cap).powi(2);
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }
    // late stream: prefer consolidating into fewer bins
    score += progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * 10.0;
    // mild preference toward bins near mean residual
    score += 0.05 * (pr - mean_residual).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well does leftover space align
    // with typical item sizes? Residuals that are multiples of common
    // small sizes (10, 20, 25, 50) are more reusable.
    let pr = post_residual;
    let reusable = (pr % 10 == 0) as f64 * 6.0
        + (pr % 25 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 50 == 0) as f64 * 3.0;
    score -= reusable;

    // Penalize dead space: residuals too small for the minimum item class.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            // fractional fit quality of next item into leftover
            let fit = next_item_size as f64 / pr as f64;
            score -= 10.0 * fit;
        } else {
            // next item won't fit here; slight penalty scaled by wasted fraction
            score += 5.0 * (pr as f64 / cap);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when current bins would leave very poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // and how fragmented existing bins are.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.55 * cap + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, must open
        }
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 8.0; // existing bins are too full anyway
        }
        return score;
    }

    // Tightness reward: filling a bin nearly exactly is excellent.
    let fill_frac = item_size as f64 / bin_residual as f64;
    if fill_frac > 0.9 {
        score -= 15.0;
    } else if fill_frac > 0.7 {
        score -= 8.0;
    }

    // Mild pressure to prefer fuller bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Small gap: only useful if the lookahead item can use it.
        if next_item_size > post_residual {
            score += 18.0;
        } else {
            score -= 6.0;
        }
    } else if post_residual <= 30 {
        // Mid gap: mildly prefer, especially if next item fits.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Large residual left behind: good, keep flexible space.
        score -= 4.0;
    }

    // Reward tight fits (fill ratio of the placement).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // ones and encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).sqrt();
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 8.0 + 2.0 * pressure;
        // But allow a new bin if all existing fits would create dead space.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else {
        score -= 1.5 * pressure;
    }

    // Prefer bins whose residual is below the mean (consolidate fuller bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Early in stream: slightly prefer keeping large residuals for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.03 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual leaves room for next item but with waste; mild reward.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here; penalize dead space creation.
        let dead = next_item_size as f64 - post_residual as f64;
        score += 0.6 * dead;
    }

    // Very small post_residual = near-perfect packing (classic best-fit boost).
    if post_residual < 5 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Compare residual against mean residual of open bins: prefer using bins
    // with less residual (tighter bins) to preserve roomier bins.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a good existing fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is more attractive late in the stream when many
        // bins are open and mean residual is small.
        score -= 0.05 * open_bins_count as f64;
        score += 0.2 * mean_residual;
    }

    // Slight progression pressure: early on, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 40.0 * tight;

    // Penalize dead space that no future item could plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny unusable sliver: fine, item filled almost everything
    }
    if post_residual > 0 && post_residual < 10 {
        score -= 0.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to waste
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // the current fit is poor or we are early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bins when item fits well elsewhere; allow when item is large
        // or many bins already open (spread load).
        let mut new_penalty = 45.0 * (1.0 - fit_ratio);
        if open_bins_count == 0 {
            new_penalty -= 100.0; // must open first bin
        }
        if open_bins_count > 8 {
            new_penalty += 10.0;
        }
        score += new_penalty - 20.0 * progress;
    }

    // Global state: prefer filling bins whose residual is far below mean
    // (concentrate waste in few bins).
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= 4.0 * (mean_residual - residual_f) / bin_capacity as f64;
    } else {
        score += 2.0 * (residual_f - mean_residual) / bin_capacity as f64;
    }

    // Mild pressure to close bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Non-linear coupling: squared post-residual term to aggressively
    // avoid leaving medium-sized gaps.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize small post-residuals (dead space) with a smooth cubic bump
    score += 60.0 * (1.0 - norm_pr).powi(3) * (1.0 - norm_pr).powi(3) * 0.5;

    // Reward tight fits more strongly as stream progresses
    score -= 40.0 * progress * (1.0 - norm_pr);

    // Lookahead coupling: favor bins whose post-residual fits next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 25.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 15.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin gets strong reward to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 5.0 * (open_bins_count as f64).ln() * (1.0 - norm_pr);

    // New-bin candidate: neutral baseline with slight progress-dependent penalty
    if bin_residual == bin_capacity {
        score = 100.0 + 60.0 * progress + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class of post_residual by integer division into capacity fractions.
        let q = post_residual / 10; // decile class
        match q {
            0 => score -= 150.0,            // residual 1..9: nearly dead space, good packing
            1 => score -= 90.0,             // 10..19
            2 => score -= 60.0,             // 20..29
            3 => score -= 35.0,             // 30..39
            4 => score -= 20.0,             // 40..49
            5 => score -= 10.0,             // 50..59
            _ => {}
        }
        // Modulo coupling: residuals that are multiples of 10 are "harmonic"
        // and likely to be filled by future items (sizes often multiples of 10).
        if post_residual % 10 == 0 {
            score -= 25.0;
        } else if post_residual % 5 == 0 {
            score -= 12.0;
        }
        // Penalize awkward odd residuals in the 40..70 dead zone.
        if post_residual > 35 && post_residual < 70 {
            score += 15.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Harmonic class of the leftover after the lookahead item.
            let post2 = post_residual - next_item_size;
            score -= (post2 as f64) * 0.8;
            if post2 % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize small useful residuals less
            // than large ones (dead space argument).
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins
    // would leave large dead space and the new bin keeps harmony.
    if bin_residual == bin_capacity {
        if post_residual == bin_capacity {
            // Opening new bin: baseline competitive score.
            score = (bin_capacity as f64) - 30.0;
            if fitting_bins_count == 0 {
                score -= 500.0; // no alternative: must open
            }
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.5;
    // Slight progression term: late in the stream, prefer tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;
    // Mean residual context: if average residual is small, reward tight fits more.
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are pure waste — penalize them quadratically.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 25.0 * ((dead_threshold - post_residual) as f64).powi(2);
    } else {
        // Prefer tight fits: reward small (usable) post residuals.
        score -= 0.5 * ((dead_threshold - post_residual.min(dead_threshold)) as f64).abs();
    }

    // Penalize post_residual that cannot accommodate the lookahead item,
    // since the next item will then need another bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: this bin can also serve the next item.
            score -= 3.0;
        } else if post_residual > 0 {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer using existing ones
    // (subtract) to avoid spreading; with few bins, mild bonus to fill.
    let pressure = open_bins_count as f64 / 8.0;
    if bin_residual != bin_capacity {
        // Existing bin: reward reuse more strongly as open bins grow.
        score -= pressure * 2.0;
    } else {
        // New bin candidate: penalize opening when pressure is high.
        score += 6.0 + pressure * 3.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Late in the stream, consolidation matters more: favor tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Align with mean residual: bins far below mean residual are poor choices
    // unless the fit is exact.
    if post_residual as f64 > mean_residual {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the NEXT item can fit into the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack left over that remains usable for the next item.
            score -= 40.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Dead space: leftover cannot host the next item.
            score += 60.0 + 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual of open bins: prefer bins tighter than average.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when existing bins would waste space badly.
    if bin_residual == bin_capacity {
        let waste_existing = if next_item_size > 0 {
            (post_residual as f64) + (bin_residual as f64 - item_size as f64)
        } else {
            post_residual as f64
        };
        let poor_fit = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        if poor_fit {
            score -= 80.0; // opening fresh bin beats creating dead space
        } else {
            score += 150.0; // discourage needless new bins
        }
        let _ = waste_existing;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 25 {
        score -= 15.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Penalize dead space that no future item can plausibly fill.
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / 50.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: mild penalty scaled by leftover size
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, avoid opening new bins: penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * prog;
        score += 0.1 * open_bins_count as f64;
    }

    // Diversify: early on, allow some new bins when current bins are quite full.
    if bin_residual == bin_capacity && mean_residual < 15.0 && prog < 0.5 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth coupling with stream progress: later in stream -> penalize large residuals more
    score += progress * 20.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Reward tight fits: subtract when post_residual is small, scaled by progress
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize opening new bins when existing bins fit well
    if bin_residual == bin_capacity {
        score += 10.0 + 40.0 * (1.0 - progress) * (1.0 - pr_norm);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Mild penalty for leaving residuals that match nothing typical (mean residual mismatch)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Encourage consolidating many open bins
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class decomposition of post_residual ----
    // Classify dead space by capacity fractions and modulo arithmetic.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Integer division thresholds: how many "eighth slots" remain
    let eighth_slots = post_residual / (bin_capacity / 8).max(1);
    let quarter_slots = post_residual / (bin_capacity / 4).max(1);

    // Penalize residuals that are unusable: below the smallest plausible item
    // and not aligned to a useful harmonic class.
    let min_item = 10.0f64.min(c);
    if pr > 0.0 && pr < min_item {
        score += 25.0; // pure dead space
    }

    // Modulo arithmetic on post_residual: residuals near multiples of 25
    // (harmonic quarter classes) are more reusable by future items.
    let m25 = post_residual % 25;
    let m50 = post_residual % 50;
    let alignment_bonus = if m25 == 0 {
        12.0
    } else if m50 == 0 {
        8.0
    } else if m25 <= 3 || m25 >= 22 {
        4.0
    } else {
        0.0
    };
    score -= alignment_bonus;

    // Quarter-slot count: bins with many usable quarter slots are valuable.
    score -= quarter_slots as f64 * 2.0;
    // But too many tiny eighth slots with no quarter slot means fragmentation.
    if quarter_slots == 0 && eighth_slots >= 1 && pr < quarter {
        score += 6.0;
    }

    // ---- Lookahead coupling: does next item fit into post_residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly consumes a class.
            let slack = (post_residual - next_item_size) as f64;
            let match_quality = if post_residual == next_item_size {
                30.0
            } else if slack < eighth {
                18.0
            } else if slack < quarter {
                10.0
            } else {
                4.0
            };
            score -= match_quality;
        } else {
            // Next item won't fit here: this placement strands the residual
            // unless the residual itself is small (nearly full bin is fine).
            let stranded = if pr > quarter { 10.0 } else { 3.0 };
            score += stranded;
        }
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin can take the item; avoid opening a new bin.
        score -= 20.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Empty bin: only attractive if no open bin fits well or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += scarcity;
        score += progress * 5.0; // mild late-stream reluctance to sprawl
        score -= 5.0; // base attractiveness of a fresh bin
    }

    // ---- Tightness reward: closer packing is better ----
    let fill_ratio = (bin_capacity - post_residual) as f64 / c;
    score -= fill_ratio * 8.0;

    // ---- Mean residual coupling: prefer bins below mean residual when
    //      mean is high (consolidate), above mean when mean is low ----
    if mean_residual > quarter * 2.0 {
        score -= (mean_residual - pr) * 0.05;
    } else {
        score += (mean_residual - pr).abs() * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are nearly unusable dead space.
    if post_residual < 10 {
        score -= 60.0; // perfect or near-perfect fill is excellent
    } else if post_residual <= 20 {
        score -= 25.0; // tight fit, likely still fillable by small items
    } else if post_residual <= 40 {
        score += 8.0; // mid gap: moderate dead-space risk
    } else {
        score += 20.0; // large gap: wasteful unless bin was huge anyway
    }

    // Dead space is worse if the gap cannot fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // gap remains useful for next item
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5; // unusable for lookahead
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // New bin is attractive only if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference to fill older bins first as the stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (-diff / 25.0).exp(); // strong reward for perfect 2-step fit
        // Penalize residuals that can never be used (below minimum item size 1 is fine,
        // but very small residuals are dead space unless next item matches).
        if post_residual > 0 && diff > 0.0 {
            score += 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // If next item fits exactly, big bonus; if next item won't fit, mild penalty.
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is terrible (huge dead space).
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        score += 20.0; // base cost of opening a new bin
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 35.0; // new bin sets up perfect next placement
        }
        if waste < 20.0 {
            score += 50.0; // opening a bin for near-perfect fit elsewhere is wasteful
        }
    }

    // Late in stream: consolidate, avoid proliferation of open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.2 * next_item_size as f64;
    }
    // Penalize leaving a residual slightly below the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, consolidate into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    // Global state: many open bins with high mean residual -> favor filling them.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 + 0.05 * mean_residual;
    }

    // New-bin candidate: only attractive when item is large or no good fits exist.
    if bin_residual == bin_capacity {
        score += 30.0 - 0.25 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1)

    // Base: penalize leftover space, with non-linear (quadratic + cubic) coupling
    // to stream progress: early on, moderate leftovers are fine (flexibility);
    // late in the stream, dead space becomes increasingly costly.
    let mut score = post * (1.0 + 0.9 * progress + 1.3 * progress * progress);

    // Cubic shaping: strongly punish very large leftovers as the stream matures
    score += 30.0 * pr * pr * pr * (0.4 + progress);

    // Reward tight fits: small post_residual gets a smooth bonus
    let tightness = 1.0 - pr;
    score -= 12.0 * tightness * tightness * (1.0 + 0.6 * progress);

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement smoothly; otherwise penalize proportionally
    // to how much the next item misses the remaining space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 + progress);
        } else {
            let miss = (nxt - post) / cap;
            score += 14.0 * miss * miss * (1.0 + 0.8 * progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the fleet mean — placing into a below-mean-residual bin keeps
    // larger residuals around for future big items (smooth quadratic term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 3.0 * dev;

    // New-bin candidate: make it attractive only when few bins fit the item
    // or the stream is young (flexibility is valuable early); otherwise
    // discourage opening bins when a reasonable fit exists.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let openness = 1.0 / (1.0 + 0.35 * fit_pressure);
        score -= 20.0 * openness * (1.0 - 0.5 * progress);
        // mild base cost so new bins are not chosen over decent fits late
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes (residual 0 is perfect)
    if post_residual == 0 {
        score -= 1000.0; // perfect closure, always best
        return score;
    }

    // Integer-division threshold classes on post_residual (capacity=100):
    // class 0: 1..=9 (dead space), class 1: 10..=24, class 2: 25..=49, class 3: 50..=100
    let residual_class = match post_residual {
        0 => 0u32,
        1..=9 => 0,
        10..=24 => 1,
        25..=49 => 2,
        _ => 3,
    };
    score -= residual_class as f64 * 12.0;

    // Dead-space penalty: tiny residuals waste capacity
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Modulo arithmetic: residuals that are multiples of common size classes
    // (10/20/25/50) are more reusable by future items.
    let reusable = (post_residual % 10 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 6.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains into this bin: strong reward
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 + 10.0 * fit_frac;
        } else {
            // next item cannot use this bin's leftover
            score += 5.0;
            // if next item exactly matches bin_residual class boundary, mild penalty
            if next_item_size % 10 == 0 && post_residual % 10 != 0 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin early in the stream
    // or when open bins are sparse; the empty-bin call has bin_residual == capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * (1.0 - progress);
        // opening a new bin is more acceptable if existing bins are fragmented
        score -= (mean_residual / bin_capacity as f64) * 10.0;
    } else {
        // reward using existing bins, more when many are open
        score -= (open_bins_count.min(20) as f64) * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Mild preference for filling below-mean-residual bins (balance consolidation)
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Harmonic class of item size: items near multiples of 25 pack flexibly,
    // reward placing them anywhere reasonable; awkward sizes (prime-ish) prefer tight bins.
    if item_size % 25 == 0 || item_size % 10 == 0 {
        score -= 3.0;
    } else if post_residual - item_size < 15 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size are dead space; penalize them hard.
    if post_residual < 10 && post_residual > 0 {
        // tiny unusable sliver -> strong penalty scaled by how close we got
        score += 60.0 - 6.0 * post_residual as f64;
    } else if post_residual == 0 {
        // perfect fit: reward strongly
        score -= 80.0;
    } else {
        // usable but wasteful gap: penalize proportionally to waste
        score += 0.25 * post_residual as f64;
    }

    // Reward tight fits generally (post_residual small relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // --- Lookahead (k=2): prefer bins whose leftover can host next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover still useful -> reward
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // leftover blocks next item -> mild penalty
            score += 8.0;
        }
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // this is the only bin that fits; avoid opening a new bin unless fit is terrible
        score -= 25.0;
    }

    // --- Open bins pressure: discourage spreading across many bins ---
    score += 2.5 * open_bins_count as f64;

    // Prefer bins with residuals near the mean (keeps residuals balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline; only attractive when current item is large
        // or no open bin fits well. Base cost of opening a new bin:
        score += 45.0;
        // Large items are hard to place later -> new bin more acceptable
        if item_size > 70 {
            score -= 40.0;
        } else if item_size > 50 {
            score -= 20.0;
        }
        // If many bins already open, opening yet another is costly
        score += 1.5 * open_bins_count as f64;
        // Early in stream, opening bins is fine (future flexibility)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (post_residual == 0 or tiny).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let gap = post - next;
            if gap == 0.0 {
                score -= 500.0; // perfect 2-step chain
            } else if gap <= 10.0 {
                score -= 150.0;
            } else {
                score -= (100.0 * next / post.max(1.0)).min(80.0);
            }
        } else {
            // Next item won't fit in the leftover: penalize proportionally to wasted space.
            score += 0.5 * (next - post).min(post);
        }
    }

    // Compare post residual to mean residual: leaving less than average is good.
    if mean_residual > 0.0 {
        let diff = (post_residual as f64 - mean_residual) / mean_residual;
        score += 20.0 * diff;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when good open bins exist and item is small.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        let pressure = open_bins_count as f64;
        score += 50.0 + 0.3 * waste as f64;
        // Late in the stream, be more reluctant to open new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 100.0 * progress * (pressure / (pressure + 5.0));
        }
        // If next item is small, a new bin can absorb two items; soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual_max_helper(bin_capacity, item_size) {
            score -= 60.0;
        }
    }

    // Slight preference for tighter bins (best-fit bias).
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

#[inline]
fn post_residual_max_helper(cap: u32, item: u32) -> u32 {
    cap.saturating_sub(item)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly favor bins that get fully or nearly filled
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Lookahead: penalize residuals that cannot host the next item (dead space),
    // but only if the leftover is small enough to be "wasted"
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // dead space relative to lookahead: smaller leftover = less valuable waste
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * waste + 10.0;
        } else {
            // leftover can host next item: reward proportionally to how snugly it fits
            let snug = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 25.0 * snug;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Many open bins: discourage spreading; prefer tightening existing bins
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: bins far from the mean residual get a mild pull
    // toward the average (keeps residual distribution coherent)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early stream: be more willing to open new bins (avoid premature tight packing
    // with large items); late stream: pack tightly into existing bins
    let new_bin_bias = (1.0 - progress) * 30.0;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: base attractiveness = capacity worth of room,
        // adjusted by stream position and how big the item is
        score = bin_capacity as f64 - new_bin_bias - (item_size as f64 * 0.3);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // new bin can also host the next item
        }
        if fitting_bins_count >= 3 {
            score += 25.0; // plenty of alternatives; opening new bin less attractive
        }
    }

    // Slight penalty for very large items going into nearly-full bins (fragmentation risk)
    if item_size >= 70 && post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Base: prefer minimal leftover space, with non-linear emphasis.
    let mut score = pr * (1.0 + 0.8 * pr / cap) + 0.35 * (pr * pr) / cap;

    // Smooth stream-progress coupling: later in the stream, waste is costlier.
    let progress_gain = 1.0 + 1.2 * progress * progress;
    score *= progress_gain;

    // Lookahead: reward residuals that can still host the next item,
    // penalize residuals that become dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 3.0 * (1.0 - pr / cap) * (nxt / cap);
        } else {
            score += 2.5 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Mild preference for keeping the number of open bins bounded.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Coupling with mean residual: bins far from the fleet mean are
    // slightly deprioritized to keep residuals balanced.
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: give it a calibrated baseline so it wins only
    // when every open bin would leave large unusable waste.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "usable"
    // residue classes (multiples of common item sizes) are less penalized.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: leftover that no plausible item (1..=100) can fill well.
    // Residues in [1,9] are nearly unusable -> strong penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0 * (10.0 - post);
    }

    // Harmonic bonus: post_residual divisible by 10 or 25 aligns with common
    // size grids, making future fits easier.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Odd/prime-ish residues are harder to fill later.
    if post_residual % 2 == 1 && post_residual > 0 {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial fit reward scaled by how much of the residual the next item consumes.
        let frac = next_item_size as f64 / post;
        score -= 12.0 * frac;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to wasted alignment.
        score += 4.0;
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (large post residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fit leaves
    // very awkward residue relative to mean residual.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; neutral-ish baseline, penalized so
        // that reasonable fits into open bins win.
        score += 20.0;
        // But if all open bins would leave bad residue, new bin is attractive:
        let mean_frac = (post_residual as f64 - mean_residual) / cap;
        if mean_frac > 0.0 {
            score -= 10.0 * mean_frac;
        }
        // Early in stream, new bins are cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // Tightness reward: filling a bin past 75% of capacity is good.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    if fill > 0.75 {
        score -= 10.0 * (fill - 0.75);
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 5.0;
    }
    // "Awkward gap" zone: residual too small for mid/large items but not zero.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading, encourage filling.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins with residual below the mean residual (filling the emptiest-ish
    // bins keeps the fleet of open bins tight).
    score += (mean_residual - post_residual as f64) * 0.4;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item does NOT fit the post-residual, mildly penalize (dead space for lookahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate: only attractive when current bins are very full/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / bin_capacity as f64).min(1.0);
        // Low base: opening a bin is costly unless open bins are nearly full.
        score = 55.0 + 60.0 * pressure - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // reward small leftover after the lookahead item
            let look_waste = next_post as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - look_waste);
            if next_post == 0 {
                score -= 15.0; // perfect 2-item chain
            }
        } else {
            // next item won't fit here; penalize proportionally to how much space is stranded
            let stranded = post_residual as f64;
            score += 0.15 * stranded;
            // if stranded space is smaller than the smallest plausible item, heavy dead-space penalty
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of wasted space
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev.signum() * dev.abs().sqrt();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current fit is terrible
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // if many open bins and this fit is loose, discourage new bin further
        if post_residual as f64 > mean_residual + 20.0 {
            score += 15.0;
        }
        // early in stream, new bins are fine
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Encourage consolidation when many bins are open
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Penalize dead space quadratically, normalized by capacity.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste * waste;
    }

    // Exact-fit detection: item fills bin exactly.
    let tight = (post_residual as f64) <= 5.0;
    if tight {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    // (chaining items into the same bin).
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            let chain_quality = 1.0 - ((post_residual - next_item_size) as f64) / bin_capacity as f64;
            score -= 20.0 + 15.0 * chain_quality;
        } else {
            // Next item won't fit here; leaving large post_residual is wasted
            // unless it could combine with future items. Mild penalty scaled by
            // how much space is stranded.
            let stranded = post_residual as f64;
            if stranded < next_item_size as f64 {
                score += 0.15 * stranded;
            }
        }
    } else {
        // Last item in stream: strongly prefer zero-waste placement.
        score += 2.0 * post_residual as f64;
    }

    // Global state coupling: when mean residual across open bins is low,
    // conserve open bins (avoid opening new bins unnecessarily); when mean
    // residual is high, spreading items is fine.
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.05 * mean_gap;

    // Time horizon: early in stream, be more willing to open new bins /
    // spread (future items can fill leftovers); late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * progress * if post_residual == 0 { 1.0 } else { 0.0 };

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit (post_residual
    // small) — the waste penalty above already pushes it down for poor fits,
    // but add a mild consolidation pressure scaled by open bins count.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    // Small stochastic-free diversity term: prefer bins whose residual differs
    // from the mean (keeps a portfolio of residual sizes).
    let diversity = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * diversity;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * 4.0; // peaks mid-range residual
    let coupling = poly * (0.5 + progress);

    let mut score = pr;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= coupling * cap * 0.6;

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 && (pr as u32) < next_item_size {
        score += (next_item_size as f64 - pr) * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open relative to progress (fragmentation pressure)
    let frag = open_bins_count as f64 / (1.0 + progress * 50.0);
    score += (norm_pr - mean_residual / cap).abs() * 5.0 + frag * 0.05;

    // New-bin candidate: prefer opening a new bin only when residuals are large
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: exact-fill is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small post_residual classes (residual mod 10): prefer tiny leftovers
    let r_mod = post_residual % 10;
    score -= (10 - r_mod) as f64 * 0.8;

    // Dead-space penalty: residual too small for any plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic pairing: does next item fit exactly in post_residual?
    if next_item_size == post_residual && post_residual > 0 {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: reward proportional to tightness
        let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 40.0 * tight;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: penalize small leftover that strands capacity
        score += 25.0;
    }

    // Integer-division threshold: post_residual in [50,100) means bin is half-empty;
    // prefer keeping bins that stay "harmonically balanced" (residual < half)
    let half = bin_capacity / 2;
    if post_residual >= half {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = open_bins_count as f64 * 0.5;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 180.0 - open_pressure - mean_gap * 0.3 - progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 300.0; // no open bin fits: new bin is correct
        }
    }

    // Prefer filling bins with larger existing load (tighter bins first)
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold a typical
    // future item are nearly worthless — penalize them hard.
    let min_useful = 10.0f64.min(bin_capacity as f64); // smallest conceivable item
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 60.0; // dead space: gap that can never be filled
    }

    // Non-linear penalty on small-but-not-quite-dead gaps (e.g. 1..=15):
    // these are the classic waste makers in online packing.
    if post_residual > 0 && post_residual <= 15 {
        score += (16 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit gets a strong extra reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening a new
    // one (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 * (open_bins_count as f64).sqrt();
        // But if no open bin fits well (large post_residual on the new bin
        // call is 0 by construction, so this only triggers via fitting count),
        // allow opening when the stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    } else {
        // Placing into an existing bin slightly reduces open-bin pressure.
        score -= 3.0;
    }

    // Prefer bins whose residual deviates favorably from the mean: a bin with
    // residual below mean absorbs the item while keeping mean gaps usable.
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // Lookahead: if the next item exactly matches the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item would fit in post residual, mild bonus.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: mild penalty for blocking.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 30.0;

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Partial lookahead match: next item fits well into the post residual.
    else if next_item_size > 0 && next_item_size < post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64).powi(4) * 25.0;
    }
    // Penalize if the next item would NOT fit in the residual (dead space risk).
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last chance: only one bin fits, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when all open bins would leave big dead space
    // or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let min_open_residual_penalty = if open_bins_count == 0 { 0.0 } else {
            ((item_size as f64) - (bin_capacity as f64 - mean_residual)).max(0.0)
        };
        score += 35.0 - min_open_residual_penalty.min(30.0);
        // Late in the stream, slightly discourage opening bins (waste).
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Mild penalty for leaving tiny unusable residuals (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), used to modulate lookahead weight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Core fit quality: reward tight fits (low post_residual) ----
    // Non-linear: dead space below a threshold is heavily rewarded.
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    } else {
        // Penalize residuals that are too small to be useful for future items (min size 1, but
        // practically small slivers are dead space).
        let dead = (post_residual as f64 / cap).powf(2.0);
        score += 15.0 * dead;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        // The next item fits here after this placement: strong reward, scaled by how tight
        // the future fit is and by how far along the stream we are.
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 12.0 * (1.0 - slack / cap) * (0.6 + 0.4 * progress);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: mild penalty, stronger later in the stream
        // when we want bins closing out cleanly.
        score += 4.0 * progress * (post_residual as f64 / cap);
    }

    // ---- Last-chance logic: if this is the only fitting bin, strongly prefer using it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost so it's only chosen when open bins fit poorly.
        score += 30.0;
        // More open bins -> slight extra reluctance to open yet another one.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / cap) * 10.0;
    } else {
        // Prefer placing into bins with larger residuals when fits are comparable
        // (keeps small bins available for small items): reward using big-residual bins.
        score -= 6.0 * (bin_residual as f64 / cap);
        // Slight preference for bins below the mean residual (balancing across bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // ---- Waste aversion: placing a small item into a nearly-empty bin wastes capacity ----
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 && bin_residual != bin_capacity {
        score += 8.0 * (1.0 - fill_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of post-residual with stream progress:
    // late in the stream, waste is more costly -> amplify small residuals' value
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score -= 12.0 * (1.0 - norm_pr) * (prog2 + 0.5 * prog3);

    // Penalty for dead space that no future item can plausibly use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            let gap = (nxt - pr) / cap;
            score += 25.0 * gap * gap;
        } else {
            // smooth reward: residual closely matches next item
            let fit = 1.0 - (pr - nxt).abs() / cap;
            score -= 10.0 * fit * fit * fit;
        }
    } else {
        // last item: strongly prefer zero residual
        score += 5.0 * norm_pr * norm_pr;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Slight preference to fill fuller bins relative to fleet mean residual
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // Mild pressure against opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space
    // in terms of the smallest item class (sizes 1..100, class width 10).
    let post_class = (post_residual / 10) as f64; // 0..10
    let next_class = (next_item_size / 10) as f64; // 0..10

    // Reward residuals that form a "harmonic" fit with the next item:
    // if next item divides the post residual nicely (post_residual % next_item_size small),
    // the bin stays efficient downstream.
    if next_item_size > 0 && post_residual >= next_item_size {
        let rem = post_residual % next_item_size;
        score -= (10.0 - rem as f64) * 0.6; // perfect divisibility (rem=0) gets max reward
        // exact future fit: next item consumes the residual fully or leaves a tiny class-0 remnant
        if rem == 0 {
            score -= 25.0;
        } else if rem <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow in this bin: penalize by its wasted-class gap
        score += (next_class - post_class).max(0.0) * 1.5;
    }

    // Integer-division thresholds on post_residual: dead space classes.
    // Residuals in [1,9] are near-unusable -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Capacity-fraction coupling: reward leaving a residual that is a clean
    // fraction of capacity (25, 50, 75) since many item mixes reuse those.
    match post_residual {
        0 => score -= 10.0,
        25 | 50 | 75 => score -= 12.0,
        20 | 40 | 60 | 80 => score -= 6.0,
        10 | 30 | 70 | 90 => score -= 3.0,
        _ => {}
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + post_class * 2.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when no open bin
    // offers a good (small-residual, harmonic) fit. Scale slightly with stream progress:
    // late in the stream, packing tight matters more, so make new bins costlier.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 20.0 * progress;
        // if the next item is large, a fresh bin gives it room
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Tight fits (small post_residual but nonzero) are generally good: best-fit bias
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Coupling with mean residual: if this bin's post-residual is far below the
    // mean residual of open bins, we are compacting well -> reward.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Open-bin pressure: many open bins -> favor filling existing ones tighter.
    score -= (open_bins_count as f64).ln().max(0.0) * (10.0 - post_class) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual > 10 && post_residual < 20 {
        score += 8.0; // risky mid-gap zone
    }

    // Reward tight fits (small but not zero residual is good; zero is perfect).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: prefer bins deviating below mean residual (filler bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
    }

    // New-bin candidate: neutral baseline with mild penalty so it's chosen only
    // when all open bins score badly (poor fits / dead space).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 0.35 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin pairs well with a large next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match: strong bonus.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            // Penalize proportional to mismatch, amplified for small post_residual (dead space).
            score += gap * 0.35;
            if post_residual < next_item_size {
                // next item cannot follow here: dead-space penalty grows as residual shrinks.
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
        // Small post_residual that cannot host next item is wasteful unless near zero.
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin fits well (handled implicitly),
    // otherwise penalize opening new bins, more so early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - progress);
        // Perfect 2-step fill for a fresh bin is still fine.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 55.0;
        }
    }

    // Mild preference for filling nearly-full bins (low residual).
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Coupling: many open bins -> discourage spreading, prefer tight fits.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Penalize dead space: residual too small to ever hold a minimum item.
    if post_residual < 1 {
        score += 1000.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // mild bonus proportional to how well next item uses leftover
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fit;
        } else {
            // next item won't fit here; penalize larger wasted residual
            score += 5.0;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // neutral base for new bin; penalize slightly so tight fits beat it,
        // but keep it competitive vs bad fits.
        score += 25.0;
        // If many bins are open and mean residual is large, opening a new bin
        // is wasteful; penalize more.
        score += 0.15 * mean_residual;
        // Late in the stream, opening new bins is costlier.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * t;
    }

    // Global pressure: when few bins fit the item overall, discourage spreading.
    if fitting_bins_count >= 2 && bin_residual < bin_capacity {
        score -= 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidate small gaps).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.3 * dev;
    }

    // Small dynamic time-horizon term: early on, encourage packing diversity;
    // later, consolidate aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * t * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);
    score += 25.0 * norm_post * norm_post * norm_post * (1.0 - progress);
    score -= 30.0 * norm_item * (1.0 - norm_item) * progress.sin() * 0.5;

    // Dead-space penalty: very small post residuals are either great (tight fit) or wasteful
    if norm_post < 0.1 {
        score -= 20.0 * (0.1 - norm_post) * (1.0 + progress);
    } else if norm_post > 0.5 {
        score += 15.0 * (norm_post - 0.5) * (1.0 - progress);
    }

    // Last-chance bonus: avoid opening a new bin when only one bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (nxt / cap) * (1.0 - 0.5 * progress);
        } else {
            score += 8.0 * (1.0 - nxt / cap) * progress;
        }
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: mildly penalize early, allow late in the stream
    if bin_residual == bin_capacity {
        score += 30.0 - 40.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveal
    // "friendly" leftovers that many item sizes can still use.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are multiples of common item classes (10, 20, 25, 50).
    let harmonics: [u32; 4] = [10, 20, 25, 50];
    let mut harmonic_bonus = 0.0;
    for (i, &h) in harmonics.iter().enumerate() {
        if post_residual % h == 0 && post_residual > 0 {
            harmonic_bonus += 6.0 - 1.5 * i as f64;
        }
    }
    score -= harmonic_bonus;

    // Penalize awkward dead space: small but nonzero residuals (1..10) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.2;
    }

    // Fraction-of-capacity threshold on post_residual via integer division.
    // Perfect fill: post_residual in [0, cap/20] is excellent.
    if post_residual <= bin_capacity / 20 {
        score -= 8.0;
    }
    // Half-filled zone: post_residual around cap/2 is a valuable class.
    let half = bin_capacity / 2;
    if post_residual.abs_diff(half) <= 5 {
        score -= 4.0;
    }
    // Residual just above cap/2 wastes space (only items <= residual fit).
    if post_residual > half && post_residual < (3 * bin_capacity) / 4 {
        score += 3.0;
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match for the next item is ideal.
            if post_residual == next_item_size {
                score -= 10.0;
            } else {
                let leftover2 = post_residual - next_item_size;
                // Reward if the double-leftover stays in a good harmonic class.
                if leftover2 % 10 == 0 || leftover2 % 25 == 0 {
                    score -= 5.0;
                }
                score -= (leftover2 as f64).sqrt() * 0.5;
            }
        } else {
            // Next item won't fit here; penalize more if this bin was the only option.
            score += (next_item_size - post_residual) as f64 * 0.15;
            if fitting_bins_count == 1 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (mean residual low relative to item size) or late in the stream.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let reluctance = 18.0 + 25.0 * fragmentation + 10.0 * progress;
        score += reluctance;
        // A fresh bin is fine if the item is huge and nothing tight exists.
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 12.0;
        }
    }

    // Mild global pressure: prefer bins with residual closest to item (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.05;

    // Small penalty for spreading across many open bins early on.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward for zero dead space.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize "unusable" small gaps: gaps too small for the smallest
        // plausible item (<= 10) are dead space.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
        // Gaps that can't fit the lookahead item are less useful.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Reward tight fits generally (small post_residual relative to item).
    score += post_residual as f64 / (item_size as f64 + 1.0) * 5.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, favor filling existing ones
    // over creating dead space; when few bins, consolidation matters more.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins with residuals below the mean (filling the emptiest-ish bins
    // consolidates), but only mildly to keep dead-space penalty dominant.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: mildly penalize so it's chosen only when all open
    // bins would create dead space (their penalties push them above this).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less dead space is exponentially better.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Aggressive 2-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fill: this bin takes next item exactly
        } else if post_residual > next_item_size {
            // leftover after next item: penalize by resulting dead space
            let after = post_residual - next_item_size;
            score += (after as f64 / bin_capacity as f64).powi(2) * 30.0;
        } else {
            // next item can't follow into this bin: mild penalty
            score += 8.0;
        }
    }

    // Reward bins whose residual is already below average (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Last-chance bonus: only one bin fits, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist that fit well.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 20.0; // new bin can host a pair later, still okay-ish
        } else {
            score += 35.0; // avoid fragmentation via new bin
        }
        // Early in stream, new bins are cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // Many open bins: prefer filling them rather than opening more.
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
