pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 8.0 * coupling;

    // Reward tight fits (low post_residual) more strongly as stream progresses.
    let tightness = 1.0 - pr_norm;
    score -= 6.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if next item could have used this residual better.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Next item still fits here after placement: mild reward.
            score -= 2.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space creation, scaled by progress.
            score += 4.0 * pr_norm * (0.3 + 0.7 * progress);
        }
    }

    // Prefer bins with below-average residual (consolidate waste).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 3.0 * dev * dev.abs();

    // Mild bias against opening new bins early, stronger later in stream.
    if bin_residual == bin_capacity {
        score += 10.0 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "clean"
    // residue classes (multiples of 10) leave space reusable by typical items.
    let class = post_residual % 10;
    if class == 0 {
        score -= 6.0; // perfectly aligned residual
    } else if class <= 3 {
        score += 4.0; // tiny dead space, hard to reuse
    } else {
        score += class as f64 * 0.5;
    }

    // Integer division threshold: post_residual bucketed by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 8.0; // nearly full bin is fine, but don't waste a whole bin class
    } else if frac > 0.5 {
        score -= 3.0; // keeping large residual is valuable
    }

    // Coupling with next item: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item divides residual into aligned classes
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 2.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 1.2;
        if tight && open_bins_count > 0 {
            score += 25.0; // prefer existing bins when they're reasonably full
        } else {
            score += 2.0;
        }
    }

    // Progress coupling: later in stream, be more conservative about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // Prefer bins below mean residual slightly (balance load toward filling)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to fit typical
    // future items are heavily penalized (non-linearly).
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    } else if post_residual == 0 {
        // Perfect fill is maximally rewarded.
        score -= 40.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another one.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // If the mean residual across open bins is large, opening a new bin
        // is wasteful; add extra penalty.
        if mean_residual > item_size as f64 {
            score += (mean_residual - item_size as f64).min(50.0);
        }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just barely smaller than the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 6.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the NEXT item exactly fills
    // the post-residual (perfect chain), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            if gap == 0.0 {
                // Perfect 2-step match: strongly favored.
                score -= 40.0;
            } else {
                // Partial match: reward proportional to how close next item gets.
                score -= 25.0 * (1.0 - gap / pr);
            }
        } else {
            // Next item cannot fit: post residual is likely dead space.
            score += 18.0 + 0.4 * (nxt - pr);
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0 * tightness;
    }

    // Compare post_residual against mean residual: creating a residual far
    // below the mean means this bin becomes unusable for typical items.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.8 * (mean_residual - pr);
    } else {
        score -= 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when the current item is
    // large and no good fit exists elsewhere; otherwise discourage opening.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) > 0.6 * (bin_capacity as f64);
        if large_item || next_item_size == 0 {
            score -= 4.0;
        } else {
            score += 12.0;
        }
    }

    // Late in the stream: consolidate, avoid spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0; // dead space for the lookahead item
            // penalize more if the wasted space is close to next_item_size (near-miss)
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score += 3.0 * (1.0 - gap / (bin_capacity as f64));
        }
    } else {
        // Last item: purely minimize waste.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is discouraged early,
    // acceptable when open bins have large mean residual (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / (bin_capacity as f64) - 0.5).max(0.0);
        score += 20.0 - 10.0 * progress - 15.0 * fragmentation;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 8.0;
    }

    // Prefer bins with residual below the mean (consolidate small gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference for bins among many open ones (reduce bin count pressure).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping.
    let mut score = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes both extremes mildly

    // Strong reward for exact / near-exact fits.
    score -= (1.0 - x).powi(4) * 12.0;

    // Penalize large dead space super-linearly.
    score += x.powi(3) * 8.0;

    // Stream-progress coupling: early on, keep bins flexible (favor larger residual);
    // late, squeeze bins hard (favor small residual).
    let flex = 4.0 * (1.0 - progress) * x;
    let squeeze = 6.0 * progress * (1.0 - x);
    score += flex - squeeze;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Lookahead: reward leaving room for the next item if it fits; penalize otherwise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - nx / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Nudge away from bins far below mean residual (fragmentation avoidance).
    score += ((mean_residual - pr) / cap).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small residue" classes (0..=10) are nearly perfect fits -> reward heavily.
    let residue_class = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if residue_class <= 2 {
        score -= 25.0; // near-perfect harmonic slot
    } else if residue_class >= 8 {
        score += 10.0; // awkward large residue within a decade
    }

    // Integer-division thresholds: dead space is worse when it cannot host
    // typical small items (1..=10). Penalize unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0; // dead space: nothing can ever fit
    }

    // Lookahead coupling: reward leaving exactly enough room (or a bit more)
    // for the next item; penalize leaving room that just barely misses it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 3 {
                score -= 18.0; // tight but feasible next fit
            } else {
                score -= (20.0_f64.min(slack as f64 / 10.0));
            }
        } else {
            let gap = next_item_size - post_residual;
            if gap <= 5 {
                score += 15.0; // tantalizing near-miss -> wasted capacity
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large relative to capacity and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let urgency = (item_size as f64 / bin_capacity as f64) * 40.0;
        score = bin_capacity as f64 - urgency + crowding * 2.0 - progress * 5.0;
        if post_residual >= 20 {
            score -= 10.0; // new bin still useful for future items
        }
    }

    // Mild preference for fuller bins overall (waste minimization).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    // Mean-residual anchoring: bins deviating far below mean residual are
    // already tight; prefer them slightly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: small unusable gaps are the worst outcome.
    // A residual that no plausible future item (min size 1..10) can use is pure waste.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Zero residual is perfect packing: strongly reward.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward fits that leave room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Exact chain fit: post_residual == next_item_size leaves another zero gap.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual can't host the next item: mild penalty scaled by wasted fraction.
        let waste = 1.0 - (post_residual as f64 / (next_item_size as f64).max(1.0)).min(1.0);
        score += waste * 10.0;
    }

    // Open-bins pressure: penalize spreading across many bins when mean residual is low.
    score += (open_bins_count as f64) * 1.5 * (1.0 - mean_residual / bin_capacity as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when current bins have poor fit.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // Late in the stream, opening fresh bins is less desirable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If next item is small, a fresh bin wastes capacity potential.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: strongly reward if the next item fits exactly or well
    // into the post_residual space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain (post_residual == next_item_size) is ideal.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted space.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    }

    // Relative-to-mean residual coupling: bins with residual below mean are
    // "almost full"; placing there consolidates waste.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless the item is huge relative
    // to typical residuals or no real bin fits well.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Big items justify a fresh bin; small items should reuse open bins.
        score += 25.0 * (1.0 - tightness);
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin chains well with the next item: soften penalty.
            score -= 20.0;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into emptier bins.
    score += 0.2 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

