    }

    // New-bin candidate handling: empty bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Baseline penalty so open bins with decent fits win.
        score += 15.0;
        // Late in the stream, opening a new bin is less costly than fragmenting.
        score -= 30.0 * progress;
        // If the item leaves a very poor residual in every bin, new bin is attractive:
        // approximate via mean residual being small (bins are nearly full).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        // Lookahead: if next item is large, a fresh bin can host it.
        if next_item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Lookahead synergy: if the next item fits exactly in the post residual, big bonus.
        if next_item_size > 0 {
            let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            if diff == 0 {
                score -= 35.0;
            } else if diff < 10 {
                score -= 20.0 - 2.0 * diff as f64;
            } else if post_residual > 0 && (post_residual as u32) < next_item_size {
                // residual too small for next item: mild penalty for fragmenting
                score += 5.0;
            }
        }

        // Prefer bins whose residual is close to item size (minimize waste ratio).
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * waste_ratio * waste_ratio;

        // Spread load: slightly prefer bins below mean residual to balance.
        if (bin_residual as f64) > mean_residual {
            score += 2.0;
        } else {
            score -= 2.0;
