    }

    // Mild penalty when bin residual deviates from mean residual (non-linear).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Prefer consolidating into fewer bins, scaled smoothly by progress.
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Harmonic class of post_residual: residues divisible by common small sizes
    // (10,20,25,50) are "usable" dead space; odd/prime-like residues are waste.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr % 50 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 || pr % 20 == 0 {
        score -= 15.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr < 10 {
        score += 20.0; // tiny dead sliver
    } else {
        score += 6.0; // awkward residue class
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        if next_fit == 0 {
            score -= 45.0;
        } else if next_fit % 10 == 0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item won't fit here anyway; mild penalty for hogging a big bin.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, use it rather than open new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0; // default: prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual % 25 == 0 || post_residual % 20 == 0 {
            score -= 30.0; // fresh bin keeps a harmonic residual, acceptable
        }
        if fill_ratio < 0.35 && open_bins_count > 2 {
            score -= 25.0 * (1.0 - progress); // early stream: better to open than fragment
        }
    }

    // Fragmentation pressure: bins far below mean residual are less attractive targets
    // when many bins are open (avoid spreading waste).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items are wasted.
    // Penalize "unusable" residuals (too small for any plausible follow-up item) heavily.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 20 {
        // Dead space zone: gap too small to be useful later.
        score += 12.0 * (20 - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly or well in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 6.0; // next item can still use the gap
        } else {
            // next item cannot use the gap: the residual becomes dead weight
            score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open,
    // but allow opening a new bin early in the stream or when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += bin_pressure * 0.8;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (avoids wasting a fresh bin on a poor fit later).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is a "tight" bin;
    // filling tight bins to completion is good. If residual is far above mean, deprioritize.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for filling larger-residual bins when few bins exist (keeps small gaps consolidated).
    if open_bins_count <= 2 {
        score -= 0.1 * bin_residual as f64;
    }

    // New-bin candidate adjustment: opening a new bin should only win when the current item
    // would leave a large, awkward gap in an existing bin.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; the dead-space penalties above make bad fits lose to it
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead core: reward when next item exactly fills this bin ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        // Perfect 2-chain: next item exactly consumes remaining space
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        }
        // Next item fits into the post residual: partial chain reward,
        // stronger the tighter the fit
        if next_item_size <= post_residual {
            let tightness = 1.0 - (pr - nxt) / (bin_capacity as f64);
            score -= 8.0 + 30.0 * tightness;
        } else {
            // Next item will NOT fit here -> residual becomes dead space
            // relative to next item; penalize proportionally to waste.
            let waste = pr - nxt + 1.0;
            score += waste.clamp(0.0, 40.0) * 0.8;
        }
    }

    // --- Dead-space penalty relative to mean residual across open bins ---
    let pr = post_residual as f64;
    if pr < mean_residual - 15.0 {
        // creating a small residual below average => likely unusable fragment
        score += (mean_residual - pr - 15.0) * 0.5;
    } else if pr > mean_residual + 15.0 {
        // keeping a large residual preserves flexibility
        score -= (pr - mean_residual - 15.0) * 0.3;
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless it leaves huge waste) ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: opening a new bin is only attractive
    // when the current item nearly perfectly fits a fresh bin and no open
    // bin offers a good fit ---
    if bin_residual == bin_capacity {
        // neutral baseline for fresh bin; slight penalty so we prefer existing
        // bins unless they score badly
        score += 10.0;
        // but if the item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / bin_capacity as f64) * 12.0;
    }

    // --- Progress-based adaptation: late in the stream, prefer tighter
    // packing (minimize residual more aggressively) ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Slight preference for denser bins overall (packing big into emptier bins)
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional waste: dead space relative to capacity is worse than absolute waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Perfect fit bonus: leaving nothing behind is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead coupling: penalize leaving a residual that exactly tempts the next
    // item but is then destroyed; reward residuals the next item can also use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can still fit here -> good chaining.
            score -= 10.0;
            if post_residual - next_item_size < 10 {
                score -= 15.0; // chained near-perfect fit
            }
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // We consume space the next item needed -> mild penalty.
            score += 8.0;
        }
        // Large next item: keep big residuals available elsewhere.
        if next_item_size >= 50 && post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Global state: when many bins are open with large mean residual, discourage
    // spreading waste; when mean residual is small, tighter fits matter more.
    let spread = (mean_residual - post_residual as f64).abs();
    score += spread * 0.15;

    // Time horizon: early in the stream, be more willing to open new bins
    // (long future justifies fresh bins); late in the stream, squeeze existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progression-dependent openness.
        let mut new_bin_score = 70.0 + waste_frac * 40.0;
        new_bin_score -= progress * 45.0; // cheaper to open early
        // Open a new bin if the item is large and would leave tiny residual anyway.
        if item_size >= bin_capacity * 3 / 4 {
            new_bin_score -= 20.0;
        }
        // If current bin would leave a very tight residual, new bin is fine.
        if post_residual < 10 && bin_residual < bin_capacity {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Existing bin: late stream favors filling it aggressively.
        score -= progress * 10.0;
        // Reward filling large residuals with large items.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 8.0;
    }

    // Mild penalty when many bins are already open: prefer consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling: residual waste penalized more as stream progresses
    let prog_term = progress * progress;
    score += 40.0 * prog_term * norm_pr * norm_pr;

    // Reward tight fits (low post_residual) more strongly later in the stream
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead coupling: penalize if post_residual cannot fit next item (smoothly)
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let gap = (norm_pr - next_norm).max(0.0);
        score -= 18.0 * gap * (1.0 - gap) * (0.5 + progress);
        // Smooth penalty when next item would be stranded
        let stranded = if pr < next_item_size as f64 { 1.0 } else { 0.0 };
        score += 10.0 * stranded * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Many open bins: prefer filling existing ones over spreading
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 8.0 * open_norm * norm_pr;

    // Deviation from mean residual: prefer bins whose residual is near mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: penalize opening new bins mildly, more early on
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well it decomposes into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward post-residuals that are "harmonic" with capacity: small modulo classes
    let m = post_residual % 25; // quarter-capacity harmonic class
    let m_score = match m {
        0 => -18.0, // exact quarter multiples: highly reusable
        10 => -10.0,
        20 => -8.0,
        5 | 15 => -4.0,
        _ => 0.0,
    };
    score += m_score;

    // Integer division threshold: post_residual in [1,10] is prime dead space
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (1.0 - pr / 10.0);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Coupling with next item: reward if next_item fits harmonically into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact follow-up match
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            let nm = npr % 25;
            let nm_bonus = match nm {
                0 => -14.0,
                10 => -7.0,
                _ => 0.0,
            };
            score += nm_bonus - 0.5 * (npr as f64);
        } else {
            score += 12.0; // next item won't fit here: penalize
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly unless current bin would leave bad residue
    if bin_residual == bin_capacity {
        score += 8.0;
        // opening new bin is attractive when existing bins are fragmented
        if mean_residual / cap > 0.35 {
            score -= 6.0;
        }
    }

    // Fractional capacity-class penalty: residual in awkward bands (0.3-0.45 of cap)
    if frac > 0.3 && frac < 0.45 {
        score += 10.0;
    }
    if frac >= 0.45 && frac <= 0.55 {
        score -= 6.0; // half-capacity-like residual is valuable
    }

    // Late-stream tightening: prefer tight fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (pr / cap) * 15.0;

    // Mild spread penalty: avoid extreme divergence from mean residual
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (1..100 range,
    // min item size 1) are pure waste; the smaller the gap, the worse.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is ideal: strong reward.
        score -= 80.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 8.0; // gap still usable by next item
        } else if post_residual > 0 {
            score += 15.0; // gap unusable by next item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the empty-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 25.0 + 6.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 40.0; // an open bin exists that fits: avoid new bin
        }
    } else {
        // Mild reward for using existing bins, scaled by how full they are.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Prefer bins whose residual is close to the item (tight fit measure).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.3 * tightness;

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: strong reward
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to tightness
            score -= 10.0 * (1.0 - diff / cap);
        } else {
            // next item does NOT fit: penalize wasted residual
            score += 6.0 + 0.05 * post_residual as f64;
        }
    }

    // Prefer bins tighter than the mean (fill crowded bins first)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize creating dead space below the typical minimum item size
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins would leave large waste
    if bin_residual == bin_capacity {
        let waste_if_existing = if next_item_size > 0 {
            fitting_bins_count as f64 * 1.0
        } else {
            0.0
        };
        score = cap * 0.9 + waste_if_existing;
    }

    // Late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver is wasted capacity
    }
    if post_residual >= 10 && post_residual <= 80 {
        score -= 8.0; // residual in the reachable item range stays useful
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted opportunity
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score -= 14.0 * (1.0 - fit_quality);
    }

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    if open_bins_count > 2 {
        score -= 0.6 * (open_bins_count as f64).ln() * (1.0 - post_residual as f64 / bin_capacity as f64);
    }
    if mean_residual > item_size as f64 {
        score -= 2.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad
    // or the item is large and no bin accommodates it well.
    if bin_residual == bin_capacity {
        let best_possible = (bin_capacity - item_size) as f64;
        if post_residual as f64 > best_possible + 20.0 || fitting_bins_count == 0 {
            score -= 20.0; // open fresh bin for poor fits
        } else {
            score += 12.0 + 0.05 * open_bins_count as f64; // discourage needless new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual (larger leftover -> higher score, prefer tight fits)
    let mut score = pr;

