    let pr2 = norm_pr * norm_pr;
    let pr3 = pr2 * norm_pr;
    let prog2 = progress * progress;
    let coupling = norm_pr * (1.0 + 3.0 * progress) + pr2 * (2.0 - 1.5 * progress) + pr3 * (0.5 + 2.0 * progress);
    score += 20.0 * coupling;

    // Reward near-perfect fills more strongly late in the stream
    let fill = 1.0 - norm_pr;
    score -= 15.0 * fill * fill * (0.5 + progress);

    // Penalize residuals that cannot fit the next item (smooth via next_item_size)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * gap * gap * (1.0 + progress);
        // Reward residuals that exactly enable next item with a snug fit
        let snug = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 10.0 * snug.max(0.0) * snug.max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into low-residual bins
    let ob = open_bins_count as f64;
    score += 0.4 * ob * norm_pr;

    // Mean residual deviation: prefer bins below mean residual (tighter)
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic classes of post_residual (dead-space avoidance) ----
    // Residuals in 1..=10 are nearly unusable: massive penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Class 11..=20: awkward zone, moderate penalty.
    else if post_residual >= 11 && post_residual <= 20 {
        score += 15.0 - 0.5 * post_residual as f64;
    }
    // Perfect-fit class: reward exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Modulo-10 harmonic classes: multiples of 10 are reusable by
    // typical item sizes (10/20/30/...), reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Modulo-5 secondary harmonic class.
    if post_residual % 5 == 0 && post_residual % 10 != 0 && post_residual > 0 {
        score -= 2.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly or tightly in the leftover: strong reward.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 35.0;
            } else if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
        } else if next_item_size <= bin_residual {
            // Next item would have fit before this placement: penalize wasting it.
            score += 10.0;
        }
        // Harmonic class of next item vs post residual granularity.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else {
        // Last item: any residual is pure waste; reward tight fills extra.
        score += 5.0;
    }

    // ---- Last-chance bonus: if this is the only fitting bin, avoid new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Neutral base for fresh bin; discourage unless current open bins
        // would create bad residuals. Compare against mean residual.
        score = 55.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin keeps full flexibility for the next item.
            score -= 10.0;
        }
        // Late in the stream, opening bins is less amortizable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
    }

    // ---- Mild density preference: fuller bins are better ----
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // ---- Bin-count pressure: many open bins favor consolidating ----
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (1.0 - fill_ratio);
    }

    // ---- Mean-residual alignment: prefer bins near the mean residual ----
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "dead" if it's smaller than the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Open-bins pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count > 0 {
        let pressure = 1.0 / (fitting_bins_count as f64);
        score += 8.0 * pressure * (open_bins_count as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 12.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Post-residual too small for next item: mild penalty if gap is dead space.
        if (post_residual as f64) < dead_threshold {
            score += 10.0;
        }
    }

    // New-bin candidate: penalize slightly so we prefer existing bins unless they're bad.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
    }

    // Mean-residual coupling: prefer bins with residuals close to what we consume.
    let residual_diff = (bin_residual as f64 - item_size as f64) - (mean_residual - item_size as f64);
    score += 0.05 * residual_diff.abs();

    // Late-stream consolidation: as stream progresses, favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact match with the NEXT item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how tight the leftover would be
            let chain_left = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chain_left / bin_capacity as f64);
        } else {
            // next item does NOT fit here: penalize bins that would strand the lookahead
            score += 15.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Penalize creating dead space far below the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Prefer bins whose residual is below mean (packing tight bins first keeps
    // larger average residuals available for awkward future items).
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.3 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let is_decent_fit = post_residual as f64 <= mean_residual.max(1.0);
        if fitting_bins_count > 0 && is_decent_fit {
            score += 35.0; // discourage opening a new bin when a reasonable fit exists
        }
        // Late in the stream, keep open-bin count lean.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Mild preference for filling already-open bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small leftovers.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that no realistic future item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64 - 1.0).max(0.0);
        score += 0.35 * dead * (1.0 - (step_index as f64 / total_items.max(1) as f64).max(0.0) * 0.5);
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack);
        } else {
            // Next item cannot follow here; mild penalty scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap;
        }
    } else {
        // Last item: prefer filling existing bins fully.
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 14.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let avg_fit = if open_bins_count > 0 {
            (mean_residual - item_size as f64).abs() / bin_capacity as f64
        } else { 1.0 };
        score = if pressure > 0.0 { -5.0 } else {
            // discourage new bin unless all fits are bad
            60.0 + 40.0 * (1.0 - avg_fit.min(1.0))
        };
        // Late in stream, opening new bins is more acceptable.
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Crowding: many open bins -> prefer consolidating into existing ones.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Align with mean residual: bins deviating from mean residual are less attractive.
    score += 0.10 * (bin_residual as f64 - mean_residual).abs();

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post residual.
    let mut score = pr as f64
        - 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1
        + 25.0 * norm_pr * norm_pr;

    // Smooth interaction: tight fits become more valuable as stream progresses.
    score -= 30.0 * (1.0 - norm_pr) * progress;

    // Penalize dead space relative to mean residual across open bins.
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: reward leaving space for the next item, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = pr - nxt;
        if diff >= 0.0 {
            score -= 12.0 * (1.0 - (diff / cap).min(1.0)) * (1.0 + progress);
        } else {
            score += 8.0 * (-diff / cap);
        }
    }

    // Last-chance bonus: smooth reward when few fitting bins exist.
    if fitting_bins_count <= 1 {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for proliferation of open bins, scaled by progress.
    score += 0.6 * open_bins_count as f64 * progress;

    // New-bin candidate shaping: empty bin gets a mild prior against being chosen
    // unless its residual is genuinely large relative to tight fits.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small residuals are "dead" space.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fit, best possible outcome
    } else if post < 5 {
        score -= 15.0;
    } else if post < 10 {
        score -= 5.0;
    } else if post < 20 {
        score += 10.0; // awkward dead zone
    }

    // Modulo classes: residuals that are multiples of common item sizes (5, 10, 20, 25)
    // are more reusable by future items.
    if post > 0 {
        if post % 5 == 0 { score -= 3.0; }
        if post % 10 == 0 { score -= 4.0; }
        if post % 20 == 0 || post % 25 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post as f64) >= nxt {
            score -= 6.0; // can host the next item too
            // bonus for exact-ish match
            let gap = post as f64 - nxt;
            if gap <= 5.0 { score -= 5.0; }
        } else {
            // next item won't fit here; penalize proportional to wasted potential
            score += 0.2 * (nxt - post as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (residual == capacity means empty bin). Make it moderately costly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if item is large, opening a fresh bin can be fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild tie-break toward filling fuller bins (smaller residual) and
    // consolidating the number of open bins.
    score += 0.05 * (bin_residual as f64 - mean_residual);
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (given min item size 1..100, treat gaps < 12 as near-dead).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 * (12.0 - post_residual as f64);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh space; prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure.
        score += 15.0 + 8.0 * pressure;
    } else {
        score -= 3.0 * pressure.min(6.0);
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement (chains well); if next item cannot fit and
    // post-residual is small, this is acceptable (dead space anyway).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else if post_residual > 0 && post_residual < 12 {
            // next item can't use this gap: gap is truly dead, extra penalty
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next item size (perfect chain fill).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 25.0; // perfect lookahead match: strongly favored
        } else if nxt <= pr {
            // next item fits in the post residual: partial reward, closer is better
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize wasted leftover space
            score += 8.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is tight relative to the mean residual
    // (low post_residual already encodes this, but couple to mean_residual).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin before opening a new bin: reward using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize leaving tiny unusable slivers (< 10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference to keep new bins closed early in the stream.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty (dead space grows quadratically).
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect-fit bonus: exact fill is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement (chaining placements).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 30.0; // two-item perfect chain
            }
        } else {
            // next item cannot follow here; penalize small dead space more
            score += 8.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Global state: penalize placements that leave residual far from mean residual
    // (fragmentation control), scaled by number of open bins.
    let post_f = post_residual as f64;
    let drift = (post_f - mean_residual).abs();
    score += 0.15 * drift * (open_bins_count as f64).sqrt().min(4.0);

    // Time horizon: early in the stream, be conservative (prefer tight fills);
    // late in the stream, allow more flexibility to avoid opening extra bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress;

    // New-bin candidate handling: an empty bin should only win when the item
    // fits badly everywhere else (many fitting bins => discourage new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 50.0 + 10.0 * fitting_bins_count as f64;
        } else if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: new bin is correct
        } else {
            // exactly one fitting bin: prefer it unless item is large and fit is awful
            let fit_quality = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
            if fit_quality < 0.2 {
                score -= 10.0; // terrible fit, open new bin
            } else {
                score += 30.0;
            }
        }
    }

    // Mild preference for bins with larger residuals when item is large
    // (avoid stranding big items in nearly-full bins).
    if item_size > bin_capacity / 2 {
        score -= 5.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); late, tolerate larger leftovers.
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * (post * post) / (cap * cap) * 20.0;
    score -= 2.0 * progress * (post / cap) * 10.0;

    // Cubic term: penalize near-empty leftover bins smoothly.
    score += 0.05 * (post / cap).powi(3) * 100.0 * (1.0 - progress);

    // Dead-space penalty: post_residual too small for typical future items.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 2.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= (1.0 - (post - nxt) / cap) * 8.0 * (1.0 - 0.5 * progress);
        } else {
            score += (nxt - post) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild preference for bins below mean residual (balancing across bins).
    score += 0.1 * (post - mean_residual);

    // New-bin candidate: make it slightly unattractive unless post_residual is huge
    // (i.e., item is small) or few bins are open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 6.0 / openness + (cap - post) * 0.02;
        if next_item_size > 0 && post >= next_item_size as f64 + item_size as f64 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins whose leftover falls into a
    // "reusable" class (large enough chunks, divisible-friendly) are favored.
    let cap = bin_capacity as f64;

    // Class A: post_residual divisible cleanly into small units (harmonic fit)
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 2.5;
    }

    // Dead-space penalty: tiny leftovers that almost nothing (>=1) can reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item exactly matches post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward scaled by fill ratio
            let r = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * r;
            // harmonic bonus if next item leaves another clean class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit in this bin's leftover: penalize slightly
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post_residual < 10 {
            score -= 10.0; // even a near-dead leftover beats a fresh bin
        }
    }

    // New-bin candidate: penalize opening a new bin for small items
    // (wasteful), but allow it for large items or when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (mean_residual.max(1.0) / cap * 10.0 + 1.0);
        let base = 8.0 + 0.55 * (item_size as f64);
        score = base + crowd * 3.0 - 25.0 * progress;
        if item_size > 60 {
            score -= 15.0; // large items justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 6.0; // keep pairs together in existing bins when possible
        }
    }

    // Fractional capacity coupling: reward using a large share of the bin.
    let used_frac = (bin_residual - post_residual) as f64 / cap;
    score -= 8.0 * used_frac;

    // Modulo threshold on item size: awkward sizes (prime-ish gaps) prefer
    // tighter bins.
    if item_size % 7 == 0 || item_size % 3 == 0 {
        score += (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual that is too small for even the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones; also favor bins below mean residual (emptier bins
    // relative to fleet) to keep the fleet compact.
    let open_pressure = (open_bins_count as f64 / 8.0).min(3.0);
    score -= 5.0 * open_pressure;
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would leave this bin's post-residual dead, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: make empty bins less attractive unless the item is
    // large or the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills this bin afterwards
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: this bin becomes exactly full after the next item
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits here too: reward proportionally to how well it packs
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * tightness;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste.min(50.0);
        }
    } else {
        // Last item: prefer tightest fit, reward near-full bins
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize leaving unusable slivers (dead space below minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins that are already "broken in"
    // (lower residual than average means this bin is well-packed)
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Prefer filling bins that are already more than half full
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 15.0 * fill_ratio * fill_ratio;

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or
        // when the item fits badly everywhere (high post_residual waste)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = 0.5 * (post_residual as f64); // = 50 for empty bin with item
        score += 55.0 - 20.0 * progress + poor_fit_penalty - 30.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Mild penalty for spreading across too many open bins
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 30.0; // perfect chain fit
        } else if diff > 0 && (diff as u32) < 20 {
            score -= 12.0 * (1.0 - diff as f64 / 20.0);
        } else if diff < 0 {
            score += 4.0; // next item cannot follow here
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score -= 5.0 * pressure * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be slightly more willing to open
    // fresh bins (flexibility); later, consolidate harder.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score -= 2.0 * (1.0 - progress); // new-bin discount early
        score += 8.0 * progress;         // new-bin penalty late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic in post_residual (dead space penalized super-linearly)
    let mut score = post * post / cap;

    // Smooth cubic coupling of post_residual with stream progress:
    // later in the stream, waste is costlier -> amplify penalty non-linearly
    score += 0.5 * post * (progress * progress * progress) * (1.0 + norm_post);

    // Reward tight fits (small post_residual) with a smooth sigmoid-like term
    let tightness = (-norm_post * 8.0).exp() / (1.0 + (-norm_post * 8.0).exp());
    score -= 12.0 * tightness * (1.0 + progress);

    // Interaction: item size vs mean residual — placing big items into roomy bins is good
    let roominess = (mean_residual / cap).clamp(0.0, 2.0);
    score -= norm_item * roominess * 6.0;

    // Smooth decay of fit quality when post_residual is just below typical next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        let match_bonus = (-((gap / cap).powi(2) * 20.0)).exp();
        score -= 8.0 * match_bonus;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - norm_post * 0.5);
    }

    // New-bin candidate: penalize smoothly, less as stream progresses
    // (early on, spreading is cheap; late, consolidation preferred)
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    // Mild penalty for many open bins to encourage consolidation, smoothed
    score += (open_bins_count as f64).powf(1.3) * 0.4 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "useful" for future items
    // (multiples of 10 and small values) are less penalized than awkward residues.
    let residue_class = post_residual % 10;
    let awkward_penalty: f64 = match residue_class {
        0 => 0.0,
        1 | 2 | 3 | 4 | 6 | 7 | 8 | 9 => 6.0,
        5 => 3.0,
        _ => 0.0,
    };
    score += awkward_penalty;

    // Integer-division thresholds on post_residual: dead space tiers.
    let dead_tier = post_residual / 10;
    if dead_tier == 0 && post_residual > 0 {
        score += 25.0; // residual < 10 is nearly dead
    } else if dead_tier <= 2 {
        score += 5.0 * (2 - dead_tier) as f64;
    }

    // Reward bins whose post_residual exactly accommodates the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item cannot follow here: penalize proportionally to wasted capacity fraction.
            score += (post_residual as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins that are already well-used (capacity fraction coupling).
    let used_fraction = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= used_fraction * 20.0;

    // Modulo coupling: item_size class vs bin_residual class (same class => tighter fit).
    if item_size % 10 == bin_residual % 10 {
        score -= 4.0;
    }

    // New-bin candidate handling: only open a new bin when all fits are poor or
    // the item is huge relative to every residual (avoid fragmenting fresh bins).
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 45.0 - poor_fits * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if fitting_bins_count == 1 {
            score += 15.0; // a last-chance bin exists; don't abandon it
        }
    }

    // Mild stream-position coupling: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight preference for keeping open bin count small.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items are "dead space". Penalize sharply when post_residual
    // falls into a narrow unusable band, reward near-perfect fits.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: highly desirable
    } else if post_residual <= 10 {
        score += 45.0 + (10 - post_residual) as f64 * 4.0; // tiny dead gap
    } else if post_residual <= 25 {
        score += 12.0; // moderately risky gap
    } else {
        // larger residual keeps flexibility: mild reward scaled by size
        score -= 0.15 * (pr - 25.0).min(50.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a single item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: less urgency, slight penalty to prefer tighter bins.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Open-bins pressure: when many bins are open, prefer packing into
    // existing bins (penalize the new-bin candidate implicitly via residual
    // and add pressure proportional to open bins for wasteful placements).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (pr / bin_capacity as f64);

    // Lookahead: if the next item fits into the post residual, reward this bin;
    // if it would leave the next item stranded, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // (i.e. unusually full bin) is good; keep spread small.
    score += 0.20 * (mean_residual - pr).max(0.0).min(40.0);

    // Early in stream, be slightly more willing to open bins (future unknown);
    // late in stream, consolidate aggressively.
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
