        if next_item_size > 0 {
            let pair_waste = if next_item_size <= post_residual { 0.0 } else { (next_item_size - post_residual) as f64 };
            score -= 0.3 * pair_waste;
            if next_item_size > bin_residual {
                score -= 15.0; // current bins can't host the next item anyway
            }
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else {
        // Open bins: slight preference for bins whose leftover matches the next item.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
