    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize wasting a bin that could have hosted the next item exactly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 20.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < 10 {
            score -= 20.0; // still fine: dead space penalty already dominates
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score -= open_pressure * 0.5;
    }

    // New-bin candidate (empty bin): give it a baseline so it is only chosen
    // when open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score = item_size as f64 + 30.0;
        // Opening a new bin becomes attractive late in the stream or when
        // no other bin fits well.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64) >= next_item_size as f64 {
            score -= 12.0;
        }
        score += open_bins_count as f64 * 0.3;
    } else {
        // Mild preference for bins closer to full (tight packing).
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // Slight stream-progression tilt: as the stream advances, be more conservative
    // about dead space (future recovery opportunities shrink).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match of post_residual with next item is ideal.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item fits here: reward tightness of the two-step chain
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit; penalize residual smaller than next item
            score += 8.0 * diff / bin_capacity as f64;
        }
        // exact two-step fill: strongest reward
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // post_residual zero after two items is perfect
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 15.0;
        }
    } else {
        // last item: pure waste minimization
        score -= 10.0;
    }

    // Compare against mean residual across open bins: prefer bins that
    // become tighter than average (good consolidation).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize very small dead space (unusable fragments), except zero.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Late in the stream, waste matters more; early on, keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight bias toward filling already-open bins vs opening new ones.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Lookahead coupling: ideal post_residual leaves room for next item.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        // Perfect lookahead fit strongly rewarded; wasted space that can't fit next item penalized.
        if gap < 1.0 {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use it.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when good alternatives exist; but if this IS
    // the new-bin candidate (residual == capacity), give it a base handicap
    // that shrinks when mean residual across open bins is too fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // If open bins have plenty of slack, opening new bins is wasteful.
        score += 60.0 * fragmentation;
        // But if bins are nearly full (low mean residual), a new bin is fine.
        score += 10.0 * (open_bins_count as f64).ln().max(0.0);
        // As stream progresses, be slightly more willing to open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * progress;
    } else {
        // Placing into an existing bin: mild reward scaled by how full it becomes.
        let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= 20.0 * fill * fill;
        // Spread load: prefer bins whose residual is above mean (keep small slacks for small items).
        if (bin_residual as f64) < mean_residual {
            score += 5.0;
        }
    }

    // Small-item hoarding: keep large residuals available when current item is small.
    if item_size < bin_capacity / 4 {
        score += 6.0 * (1.0 - item_size as f64 / (bin_capacity as f64 / 4.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let frac = pr / cap;
    let mut score = pr as f64;
    // quadratic waste penalty: small post-residuals are prized
    score -= 60.0 * (1.0 - frac) * (1.0 - frac);
    // cubic coupling with stream progress: early on, tolerate slack; late, demand tight fits
    score += 40.0 * frac * frac * frac * (0.5 + progress);
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - gap * gap);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }
    // last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // new-bin candidate: penalize mildly so it's chosen only for very poor fits
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }
    // mean residual deviation: prefer bins whose residual deviates from the mean (heterogeneity)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score -= 10.0 * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Residuals that are multiples of common item sizes (or near-capacity-fractions)
    // are more likely to be filled by future items.
    let cap = bin_capacity as f64;

    // Exact-fit bonus: post_residual zero is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty for tiny, awkward leftovers (1..=9): almost nothing fits.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class: reward residuals divisible by small item granularity (5 or 10),
    // since streams often contain such items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 12.0;
    } else {
        // Non-aligned residual: distance to next multiple of 5 as friction.
        let frac = (post_residual % 5) as f64;
        score += frac * 3.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly the next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * fill;
            // Harmonic bonus if next item is a "round" size.
            if next_item_size % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here: penalize leaving residual it nearly fits.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 30.0; // frustrating near-miss dead space
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins whose residual is below the mean residual (tighter bins first),
    // keeping large-residual bins flexible.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Fraction-of-capacity classes: bins with residual in the top quartile are
    // good "hosts" for big future items; slight penalty for using them now.
    if bin_residual as f64 > 0.75 * cap {
        score += 15.0;
    }

    // Early in stream: be conservative, favor tight packing of open bins less aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    // New-bin candidate (empty bin): make it moderately expensive unless nothing else
    // is reasonable; harmonic tie-break by item size class.
    if bin_residual == bin_capacity {
        score += 180.0 + (item_size % 10) as f64 * 2.0;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1)
    // are pure loss; gaps below ~10 are nearly unusable for typical items.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space, effectively wasted
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits relative to bin size
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Dead space relative to mean residual across open bins
    if (post_residual as f64) < mean_residual * 0.4 {
        score -= 8.0; // better packing than average
    } else if (post_residual as f64) > mean_residual * 1.5 {
        score += 6.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when bins are already open
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Late in the stream, prefer filling existing bins strongly
        score += 10.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: prefer residual that can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item nearly fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness: reward small post_residual relative to item size.
        score -= 40.0 * (item_size as f64) / (bin_residual as f64).max(1.0);
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains two items into one bin — huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits, but leaves a gap; penalize the leftover gap.
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 - 1.5 * gap;
        } else {
            // next item won't fit here; penalize leaving large unusable residue.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    // from the fleet mean (small residual = tight bin, pack it first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only allow opening a new bin when the item is large
    // (poor fit elsewhere) or when many bins are open (spread load).
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity - item_size) as f64;
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0);
        score += 300.0 - 0.5 * tightness - pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 100.0; // fresh bin can also host the next item
        }
    }

    // Late-stream urgency: as the stream progresses, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 1.5 * (1.0 - tightness) * (item_size as f64);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward bins that remain useful for the lookahead item
            score -= 4.0;
        }
        // Bonus if post-residual exactly absorbs next item's smallness classes
        if post_residual > 0 && (post_residual % 10 == 0) {
            score -= 2.0;
        }
    } else {
        // Last item: pure tightness matters most
        score -= 10.0 * (1.0 - tightness);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if next_item_size > 0 && post_residual < next_item_size {
            10.0
        } else {
            0.0
        };
        // Base cost of opening a new bin, discounted when many bins are open or late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_cost = 25.0 - 8.0 * progress - (open_bins_count as f64).min(10.0);
        score += open_cost + poor_fit_penalty;
    } else {
        // Slight preference for fuller bins relative to fleet mean residual
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
        // Favor bins whose residual is closer to zero than the mean
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    // Non-linear coupling: quadratic penalty on moderate leftover space (hard-to-fill zone)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 2.0; // awkward zone
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear base: quadratic in post_residual (waste minimization).
    let mut score = post * post / cap;

    // Smooth coupling of residual tightness with stream progress:
    // later in the stream, tighter fits (small post_residual) matter more.
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: reward bins whose post_residual accommodates the next item,
    // with a smooth cubic interaction in progress.
    if next_item_size > 0 && post_residual >= next_item_size {
        let look = next_item_size as f64 / cap;
        score -= 30.0 * look * (1.0 + progress) * (1.0 - (post / cap - look));
    } else if next_item_size > 0 {
        // Penalize dead space unusable by the lookahead item, smoothly scaled.
        let gap = (next_item_size as f64 - post) / cap;
        score += 25.0 * gap * gap * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 * (1.0 - progress);
        score -= 20.0;
    }

    // Congestion pressure: many open bins with high mean residual -> prefer consolidation.
    let pressure = mean_residual / cap * (open_bins_count as f64).ln();
    score += 10.0 * pressure * (post / cap);

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (smooth sigmoid-like weighting).
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        let sig = 1.0 / (1.0 + (-12.0 * (size_frac - 0.7)).exp());
        score += 60.0 * (1.0 - sig) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of the capacity.
    // Residuals that are "usable" by typical small items (multiples of 10, or >= 20)
    // are less dead than odd leftovers.
    let pr = post_residual;
    let class_mod = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if class_mod == 0 {
        score -= 12.0; // round residual, easy to fill later
    } else if pr < 10 {
        score += 45.0; // unusable dead space
    } else {
        // odd/awkward classes penalized proportionally
        score += (class_mod as f64) * 1.5;
    }

    // Fraction-of-capacity harmonic band on post_residual.
    let frac = pr as f64 / bin_capacity as f64;
    if frac >= 0.5 {
        score -= 10.0; // half-full or better remaining: still very usable
    } else if frac >= 0.25 {
        score -= 3.0;
    } else if frac > 0.0 {
        score += 8.0; // thin sliver
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_waste = (bin_residual - item_size) as f64;
        let pressure = open_bins_count as f64;
        // base penalty for opening a new bin
        score += 70.0;
        // but if placing here would leave very little usable residue anyway,
        // opening fresh is fine: discount the penalty.
        if fit_waste < 10.0 || pr < 10 {
            score -= 90.0;
        }
        // late in the stream, prefer consolidation less aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        let _ = mean_residual;
        let _ = pressure;
    } else {
        // Slight preference for tighter bins when many are open (reduce spread).
        score += (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize large leftover space being wasted on a small item.
    if (post_residual as f64) > 0.5 * (bin_capacity as f64) && item_size < 50 {
        score += 20.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 5.0 * open_pressure;
    } else {
        // New bin candidate: penalize slightly more when many bins are open,
        // unless it would be a very tight fit for the next item too.
        score += 8.0 * open_pressure;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 55.0;
    }
    // Penalize if next item cannot use the post-residual and it's small.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 15 {
        score += 15.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, avoid creating tiny fragments even more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual <= 9 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty so exact matches dominate.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: strongly reward leaving a gap that exactly matches the next item.
    if next_item_size > 0 {
        let gap_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - gap_diff / (bin_capacity as f64));
        // Perfect chain bonus: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize near-miss dead space slightly larger than next item (unusable sliver)
        if post_residual > next_item_size && post_residual < next_item_size + 5 {
            score += 15.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates usefully from the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: if this is the only bin that fits, discourage opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of open bins and stream progress.
        score = 55.0 + 2.0 * open_bins_count as f64 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If nothing fits well (worst open fit leaves lots of waste), allow new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to ever hold a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item can still fit in the post residual, reward;
    // if post residual blocks the next item while being large, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Scarcity pressure: fewer fitting bins -> favor any fitting bin.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // fit poorly (item barely fits or leaves big unusable gaps), or when open
    // bins are already crowded with large residuals relative to capacity.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - post_residual) as f64; // == item_size here
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.55
            - 12.0 * poor_fit / bin_capacity as f64
            + 10.0 * crowding
            + 20.0 * progress
            - (bin_capacity as f64 - mean_residual) * 0.2;
        // If this is the last chance among fitting bins, new bin is worse.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Mild global balance: prefer bins whose residual is close to mean residual
    // to keep the fleet homogeneous.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Early stream: slightly prefer consolidating into few bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping over progress
    let mut score = pr * (1.0 + 0.6 * prn * prn);
    score += 20.0 * prn * progress * (1.0 - progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 35.0 * gap * gap;
    } else if next_item_size == 0 && post_residual > 0 {
        // end of stream: prefer fullest packing
        score -= 15.0 * (1.0 - prn);
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strong bonus to use it rather than open new
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: neutral-ish, better late when many bins are fragmented
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score = cap * (1.0 - 0.3 * progress) + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Coupling with mean residual across open bins: penalize adding to already-loose bins
    score += 8.0 * (mean_residual / cap - prn).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "friendly" classes
    // that other items can still fill (multiples of 10, small even values).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        let mod10 = pr % 10;
        score -= 12.0 * (1.0 - (mod10 as f64) / 5.0).abs(); // favor mod10 near 0
        // Integer division thresholds: residuals <= 10 are near-dead space
        if pr <= 10 {
            score += 8.0; // dead space penalty (unless it was a perfect fit)
        } else if pr <= 20 {
            score += 3.0;
        }
        // Residuals in [25..40] are highly reusable by mid-size items
        if pr >= 25 && pr <= 40 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic-class: slack small or multiple of 10 is good
            score -= 10.0 * (-slack / 25.0).exp();
            if slack % 10 == 0 { score -= 5.0; }
        } else {
            // next item won't fit here anyway; slight penalty for tight fills
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when all fits are poor.
    if bin_residual == bin_capacity {
        // new empty bin: baseline cost of a fresh bin
        score = 100.0 - (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // if next item pairs well with current one in a fresh bin
            if item_size + next_item_size <= bin_capacity {
                score -= 25.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    } else if fitting_bins_count > 1 {
        // prefer tighter existing bins: post_residual already does this,
        // add tie-break toward bins closer to full
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Mild stream-progress adaptation: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (below a minimum viable gap) are heavily penalized.
    let min_gap = 10u32;
    if post_residual > 0 && post_residual < min_gap {
        score += 40.0 + (min_gap - post_residual) as f64 * 4.0;
    }

    // Soft dead-space zone: gaps slightly above min_gap are still risky,
    // since only tiny items can use them.
    if post_residual >= min_gap && post_residual < 25 {
        score += (25 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits (low post_residual) proportionally to item size.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * item_size as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many bins open, prefer compacting into existing
    // bins rather than opening new ones; penalize the new-bin candidate.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; attractive only when
        // existing bins would leave large dead space.
        score += 35.0 + pressure * 2.5;
    } else {
        // Existing bin: small reward scaled by open-bin pressure.
        score -= pressure * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use the gap: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; discourage adding more fragmentation.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.2;
    }

    // Early stream: be slightly more willing to open bins to build a good
    // spread; late stream: compact aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    } else {
        score += progress * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: strongly prefer tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain: bin closed exactly by next item
        } else if next_item_size <= post_residual {
            // Partial lookahead fit: reward proportional to how well next item matches.
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * chain_fit * chain_fit;
        } else {
            // Next item cannot fit here; penalize leaving a gap the next item can't use.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(50.0);
        }
    } else {
        // Last item: any residual is dead space; prefer fullest bin.
        score += 20.0 * tightness;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 15.0 * (rel - 1.0).clamp(-1.5, 1.5);
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a good chain.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            penalty -= 25.0; // fresh bin leaves room for the next item too
        }
        score += penalty;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Penalize leaving small unusable dead space (post_residual below the smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance: strongly favor using this bin if it is the only one that fits.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: bonus if the next item can fit into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that the next item cannot use.
        score += 4.0;
    }

    // Global state: when many bins are open with high mean residual, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * mean_residual * (0.5 + 0.5 * progress);
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well elsewhere.
    if bin_residual == bin_capacity {
        score += 10.0 - 5.0 * (1.0 - fill_ratio.min(1.0));
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let tightness = 1.0 - pr_norm;
    // Non-linear coupling: reward tight fits more strongly as stream progresses
    let coupling = tightness * tightness * (0.5 + progress);
    score -= 40.0 * coupling;
    // Penalize residuals that no plausible future item can use
    let min_item = 1.0;
    let dead = if pr < min_item { 1.0 } else { (min_item - pr_norm).max(0.0) };
    score += 25.0 * dead * (1.0 + progress);
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }
    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * pr_norm;
    // Prefer bins below mean residual (denser bins)
    score += 0.1 * (mean_residual - pr).max(0.0);
    // Slight nudge against opening a new bin when a decent fit exists
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - coupling) + 3.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: how "usable" is the post residual?
    // Class 0: post_residual == 0 (perfect fit) -> huge reward
    // Class 1: post_residual divides nicely into small standard item sizes
    // Class 2: mid-range leftover, mildly penalized
    // Class 3: large awkward leftover, penalized
    let pr = post_residual;
    let cap = bin_capacity as f64;

    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        // modulo harmonic classes: leftover in {0,10,20,25,50} are classic-friendly
        let harmonic_bonus: f64 = match pr % 50 {
            0 => 12.0,
            10 => 9.0,
            20 => 7.0,
            25 => 6.0,
            40 => 4.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // Fraction-of-capacity classes
        let frac = pr as f64 / cap;
        if frac < 0.1 {
            score -= 6.0; // nearly full bin: excellent
        } else if frac < 0.3 {
            score -= 2.0;
        } else if frac > 0.7 {
            score += 8.0; // bin left mostly empty: bad placement
        }

        // Lookahead coupling: does next item fit the post residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                // next item chains perfectly into this bin
                let chain_tight = (pr - next_item_size) as f64;
                score -= 10.0 + chain_tight * 0.15;
            } else {
                // next item cannot use leftover: penalize proportionally
                score += (next_item_size - pr) as f64 * 0.08;
            }
        }

        // Integer-division threshold on residual: leftover >= 80 means bin barely used
        if pr / 40 >= 2 {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when existing bins fit poorly
    if bin_residual == bin_capacity {
        // fresh bin baseline: its "post_residual" is cap - item_size
        score += 5.0;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 6.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items as f64;
        score += progress * 8.0;
        // many open bins: discourage opening more
        score += open_bins_count as f64 * 1.5;
    }

    // Mean residual alignment: prefer bins whose residual is close to the mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a small leftover gap is nearly worthless.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual > 10 && post_residual < 25 {
        score += 8.0; // moderately unusable zone
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    // (their mean residual is small relative to the item).
    if bin_residual == bin_capacity {
        score = 35.0 + (open_bins_count as f64) * 2.0 - mean_residual * 0.6;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // next item needs a fresh bin anyway
        }
        if post_residual as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 15.0; // fresh bin can also host the lookahead item
        }
    } else {
        // Favor bins whose leftover can host the lookahead item.
        if next_item_size > 0 {
            if post_residual as f64 >= next_item_size as f64 {
                score -= 12.0;
            } else {
                score += 5.0;
            }
        }
        // Slight pressure toward filling more crowded sets of bins first.
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still hold the next item (partial lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize unusable leftover.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.6 * dead;
    }

    // Compare post_residual against mean residual: leaving more than average
    // slack is wasteful; leaving less than average keeps bins tight.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with tight residual before placement (best-fit flavor).
    score += 0.2 * (bin_residual as f64 - item_size as f64);

    // Early in stream: encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (open_bins_count as f64).ln().max(0.0);

    // Brand-new bin candidate: penalize unless item is large or no good fit.
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        score += 30.0 - big_item_bonus - if fitting_bins_count == 0 { 100.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) via quadratic shaping.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Dead-space penalty: residual too small to hold the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 100.0; // chain fit: two perfect placements
            }
        } else {
            // Next item won't fit here; mild penalty proportional to wasted lookahead potential.
            score += 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_quality = 1.0 - fit_ratio;
        score -= 60.0 * fit_quality;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress:
        // early in the stream, opening bins is cheaper (more future items to fill them);
        // late in the stream, prefer squeezing into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 + 150.0 * progress;

        // If many open bins already exist and mean residual is large, opening new bins is wasteful.
        score += 0.05 * open_bins_count as f64;
        score += 0.3 * mean_residual;

        // If next item is large, a fresh bin may still be useful.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 40.0;
        }
    }

    // Global fragmentation pressure: when mean residual across bins is low,
    // be extra careful about wasting space.
    if mean_residual < 20.0 && bin_residual != bin_capacity {
        score += 0.2 * (post_residual as f64 - mean_residual).abs();
    }

    // Mild preference for bins whose residual is close to the item (best-fit core).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, tighter packing (small post_residual) is rewarded more strongly.
    let tightness = 1.0 - norm_pr; // 1.0 = perfect fit
    let progress_coupling = tightness * tightness * (0.5 + progress) * 30.0;
    score -= progress_coupling;

    // Penalize large post_residual non-linearly (dead space grows quadratically in importance).
    score += norm_pr * norm_pr * 25.0 * (0.5 + 0.5 * progress);

    // Lookahead: reward residual that still fits the next item, smoothly scaled.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (0.3 + 0.7 * progress);
        } else {
            let gap = (n - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 * (0.5 + progress);
    }

    // Mild pressure toward consolidating into fewer bins as open bin count grows.
    let open_f = open_bins_count as f64;
    score += (open_f / (open_f + 10.0)) * 5.0 * (1.0 - tightness);

    // Blend toward mean residual: prefer bins whose resulting residual stays near the mean
    // (keeps residual distribution balanced for future items).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // New-bin candidate: penalize opening a new bin unless the item is large relative to capacity,
    // with smooth dependence on progress.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 18.0 * (1.0 - item_frac) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by
    // integer division thresholds (dead-space classes).
    let q = post_residual / 10; // class index 0..10 (0 = tightest fit)
    match q {
        0 => { score -= 60.0; }          // near-perfect fit, big reward
        1 => { score -= 35.0; }          // excellent fit
        2 => { score -= 18.0; }          // good fit
        3 => { score -= 6.0; }           // decent
        4 => { score += 4.0; }           // mediocre
        5 => { score += 10.0; }          // half-empty leftover
        6 => { score += 16.0; }          // poor
        7 => { score += 22.0; }          // poor
        8 => { score += 27.0; }          // mostly empty
        9 => { score += 31.0; }          // nearly new bin
        _ => { score += 34.0; }          // untouched bin
    }

    // Modulo arithmetic: exact divisibility of post_residual by common
    // item-size classes signals reusable leftover space.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }   // round class, reusable
        if post_residual % 25 == 0 { score -= 6.0; }   // quarter-class
        if post_residual % 50 == 0 { score -= 4.0; }   // half-class
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
        if next_item_size == post_residual {
            score -= 45.0; // perfect two-item chaining
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use leftover: dead space likely
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // would leave terrible dead space.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: roughly capacity worth of score
        score = 100.0 + mean_residual * 0.3 + (open_bins_count as f64) * 1.5;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64) * 0.4;

    // Tight-fit bonus scaled by fill fraction (non-linear coupling).
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be reused
    // (smaller than the minimum plausible item) are pure waste.
    let dead_threshold = 4.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is the best outcome
    }

    // Non-linear penalty on small-but-nonzero dead gaps.
    if post_residual > 0 && (post_residual as f64) < dead_threshold * 5.0 {
        score += (dead_threshold * 5.0 - post_residual as f64).powi(2) * 0.4;
    }

    // Reward bins whose residual was large but is now well used (high fill ratio).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving a gap next item can't use
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tighter bins
    // and make opening new bins less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 3.0;

    // Prefer bins whose residual is close to the mean (balance residuals),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: empty bin gets a base cost that grows with open bins,
    // so it only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 8.0;
        // But allow a new bin when the item is huge relative to mean residual
        // (poor fit everywhere) - relax the cost.
        if item_size as f64 > mean_residual * 0.9 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual closely matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect lookahead match strongly rewarded.
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // If next item fits exactly in the post residual, extra reward.
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here: mild penalty proportional to leftover waste.
            score += 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: bins tighter than average are good targets.
    let tightness = mean_residual - post_residual as f64;
    score += 0.4 * tightness;

    // Penalize large dead space that nothing (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // unusable sliver
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Slight penalty so existing bins with good lookahead fit win,
        // but keeps new-bin option viable when open residuals are poor.
        score += 10.0 + 0.1 * mean_residual;
    }

    // Early stream: be slightly conservative, keep bins balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Many open bins: prefer consolidating into tighter bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items,
    // but soften when many bins remain open (more recombination chances).
    let dead_zone = if post_residual > 0 && post_residual < 10 { 25.0 } else { 0.0 };
    let openness = (open_bins_count as f64).ln().max(1.0);
    score += dead_zone / openness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting residual.
        score += 4.0 * (next_item_size as f64 - post_residual as f64).min(30.0) / 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: default moderate cost; cheaper early, pricier late
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 20.0 + 40.0 * progress + 2.5 * (open_bins_count as f64);
        // If nothing fits anywhere well, opening is fine (handled by comparison).
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global residual balance: prefer bins whose residual is below mean
    // (fills fuller bins first, keeping large residuals free).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-40.0).min(40.0);

    // Mild time-horizon shaping: late in the stream, prioritize perfect closures.
    let t = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * (0.5 + 0.5 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;

    // Base: penalize leftover space, with a quadratic dead-space term
    let mut score = pr + 0.9 * (pr / cap).powi(2) * cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; small residuals are prized.
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * progress * tightness.powi(3);

    // Reward near-exact fills, stronger as stream progresses (smooth bump)
    let exactness = 1.0 - ((pr / cap) * std::f64::consts::PI).cos();
    score -= 12.0 * (0.3 + 0.7 * progress) * exactness.powi(2);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 18.0 * (1.0 - gap / cap).powi(2);
        } else {
            // penalty if post_residual is awkwardly between next size and capacity
            score += 6.0 * (nxt / cap) * (1.0 - tightness);
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening a bin for one item)
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    } else if fitting_bins_count > 1 {
        // mild penalty when many alternatives exist, scaled by crowding
        score += 2.0 * ((fitting_bins_count as f64).ln());
    }

    // Mean residual context: prefer bins close to the mean (balanced packing)
    let dev = (br - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: penalize opening a new bin, more so early and when
    // open bins exist that could still absorb the item.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + 20.0 * (1.0 - progress) + 0.4 * open_bins_count as f64;
        score += new_bin_penalty;
        // But if the item is huge relative to capacity, opening a bin is fine
        score -= 10.0 * (it / cap).powi(2);
    }

    // Slight penalty for very small fills of a large residual (wasteful placement)
    score += 8.0 * (it / cap) * (1.0 - it / cap).powi(2) * (br / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left over

    // Small post_residual => tight fit, strongly reward.
    if post_residual == 0 {
        score -= 1000.0; // perfect packing
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Dead-space penalty: residuals that are hard to fill (too small for typical items).
    // Harmonic class via integer division thresholds: residual in (0,10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }
    // Residuals in awkward bands (mod 10 classes 1..9 with small value) are less usable.
    let mod10 = post_residual % 10;
    if post_residual < 40 && mod10 != 0 {
        score += 20.0 + mod10 as f64;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let nxt_frac = next_item_size as f64 / cap;
            // Reward proportional to how well next item fills the leftover.
            score -= 80.0 * nxt_frac / (frac + 0.01).max(0.01);
            // Penalty if next item leaves yet another tiny residue (harmonic mismatch).
            let post2 = post_residual - next_item_size;
            if post2 > 0 && post2 < 10 {
                score += 60.0;
            } else if post2 == 0 {
                score -= 150.0;
            }
        } else {
            // Next item cannot use this residual at all: penalize leaving large gaps.
            score += 30.0 * frac;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0 + 0.5 * (bin_residual - post_residual) as f64;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline cost so that
    // any reasonably tight fit in an existing bin beats it, but a poor fit does not.
    if bin_residual == bin_capacity {
        score = 55.0 - 10.0 * (step_index as f64 / (total_items as f64).max(1.0));
        // If no existing bin fits well (this call happens alongside them), opening
        // a new bin is attractive when item is large relative to capacity.
        score -= 15.0 * (item_size as f64 / cap);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, prefer consolidating into open bins.
        score += 20.0 * (step_index as f64 / (total_items as f64).max(1.0));
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer bins with residual near the mean (balanced use),
    // but tight fits override this.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Many open bins: encourage closing bins out by filling small-residual bins.
    if open_bins_count > 4 {
        score += 0.3 * (bin_residual as f64 - pr) * 0.0; // no-op guard
        score -= 2.0 * (open_bins_count as f64).log2() * (1.0 - frac);
    }

    // Slight tie-break noise-free deterministic jitter via step parity (harmonic classes).
    if step_index % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for ANY
    // plausible future item (min size 1, but practically < ~10) are pure waste.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // Unusable sliver: heavy penalty, worse the smaller it is.
            score += (10.0 - pr) * 8.0;
        } else if post_residual < 20 {
            // Marginal gap: moderate penalty.
            score += (20.0 - pr) * 2.0;
        }
        // Reward exact/near-exact fits strongly.
        if post_residual == 0 {
            score -= 40.0;
        } else if post_residual <= 5 {
            score -= 15.0;
        }
    } else {
        score -= 40.0; // perfect fill
    }

    // Reward tightness relative to residual: prefer bins where the item
    // occupies a large fraction of available space.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if next item is large and post-residual is a useless gap, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but relax near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.5 - 1.5 * progress);

    // Prefer bins with residual above the mean (keeps big bins for big items).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - res) * 0.15;
    }

    // New-bin candidate: only attractive when the item is huge relative to
    // capacity or no good fit exists elsewhere; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.85 {
            score -= 20.0;
        } else if frac > 0.6 {
            score -= 5.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is highly desirable
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward closeness of post_residual to next item size
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Penalize tiny unusable residuals (dead space) more aggressively
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Slight preference for filling fuller bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Make new-bin candidate less attractive unless nothing fits well
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 12.0;

    // Penalize dead space that cannot fit typical future items
    if post_residual < 10 && post_residual > 0 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // leaving a gap that next item cannot use is wasteful
        score += (next_item_size as f64) * 0.15;
    }
    // Perfect chain: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: open only when current fits are poor or many bins already open
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64) > mean_residual;
        let mut new_bin_score = 20.0 + open_bins_count as f64 * 0.5;
        if poor_fit { new_bin_score += 10.0; }
        if progress > 0.5 { new_bin_score += 5.0 * progress; }
        score += new_bin_score;
    } else {
        // Prefer bins with residual below mean (consolidate space)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference for already-open bins as open_bins_count grows (bin-opening cost)
    if bin_residual != bin_capacity {
        score -= open_bins_count as f64 * 0.1;
    }

    // Early-stream exploration: be slightly more permissive with loose fits early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: wasted space, damped late in stream (waste matters less at end).
    let mut score = norm_pr * (1.0 - 0.35 * progress);

    // Non-linear penalty for awkward residuals (mid-range dead space is worst).
    let awkward = 4.0 * norm_pr * (1.0 - norm_pr);
    score += 0.6 * awkward;

    // Reward tight fits with smooth polynomial coupling.
    let tightness = (1.0 - norm_pr).powi(3);
    score -= 0.8 * tightness;

    // Lookahead coupling: bonus if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill = nx / cap;
            score -= 0.5 * fill * (1.0 - fill) * (1.0 + 0.5 * progress);
        } else {
            score += 0.3 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Penalize spreading across many open bins late in the stream.
    score += 0.05 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);

    // Mild preference for bins below mean residual early (balance load).
    score += 0.15 * ((pr as f64) - mean_residual) / cap * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with slight late-stream penalty
    // so we prefer reusing open bins unless fit is terrible.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: best-fit core — prefer tightest post_residual.
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Harmonic class of post_residual: residual in multiples of a base quantum
    // is more likely reusable by future items. Reward residual classes that
    // divide cleanly into the capacity (classic "harmonic" sizes).
    let quantum = bin_capacity / 8; // 12 for C=100; harmonic-ish granularity
    let class_hit = post_residual % quantum.max(1) == 0 && post_residual > 0;
    if class_hit {
        score -= 6.0; // residual lies on a reusable grid point
    }

    // Integer-division threshold ladder on post_residual: dead space bands.
    if post_residual == 0 {
        score -= 25.0; // perfect closure — ideal
    } else if post_residual < 10 {
        // very small dead space, nearly useless but tiny
        score += 2.0;
    } else if post_residual < 25 {
        score += 8.0; // awkward dead zone: too small for mid items, too big to ignore
    } else if post_residual < 50 {
        score -= 3.0; // still useful for medium items
    }

    // Lookahead coupling: reward if next item fits the post_residual exactly
    // or lands in a harmonic class with it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 15.0 - (gap as f64).min(15.0); // closer fit = better
            if gap % quantum.max(1) == 0 {
                score -= 4.0; // chained residual stays on grid
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    } else {
        // last item in stream: only perfect closure matters
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless post_residual would be terrible dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (bin_residual as f64) * 0.1;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we only
    // open a new bin when existing placements are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * progress; // opening bins late is more wasteful
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // If some open bin leaves a harmonic-class residual, prefer that.
            let candidate_post = bin_residual.saturating_sub(item_size);
            if candidate_post % quantum.max(1) == 0 {
                score -= 12.0;
            }
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate
    // fullness across bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for using more-open bins when many are open (avoid sprawl).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small for a plausible future item (<= 10)
    // or falls in the awkward mid-range that few items can fill.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // pure dead space
        } else if post_residual <= 25 {
            score += 25.0; // awkward gap: only tiny items can use it
        } else if post_residual <= 40 {
            score += 8.0;  // moderately usable
        } else {
            score -= 5.0;  // large residual stays flexible
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this gap -> penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate gets a rising penalty.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 15.0 + 4.0 * open_bins_count as f64 + 10.0 * progress;
        if mean_residual > item_size as f64 {
            score += 5.0; // existing bins have room; wasteful to open a new one
        }
    } else {
        // Using an existing bin reduces fragmentation pressure slightly.
        score -= 0.5 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.2 * (post_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here later; mild reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 100.0 * tight;
        } else {
            // next item cannot use this residual; penalize dead space
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual against mean residual: avoid leaving unusually
    // large residual relative to other bins (poor space utilization).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs() + (if dev > 0.0 { 0.5 } else { 0.0 }) * dev;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 && post_residual > 0 {
        // new-bin candidate: baseline is post_residual = capacity - item_size.
        // Favor new bin only if item is large relative to capacity (leaves small residual)
        // or few bins are open.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 200.0 * item_frac;
        if open_bins_count > 4 {
            score -= 50.0;
        }
    }

    // Progress-based tie-break: later in stream, prefer tighter packs.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small nudge to prefer bins with less residual overall.
    score += 0.1 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty spread across many fitting bins to prefer best-fit selection.
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a residual that is too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Time horizon: early in stream, tolerate opening new bins (low penalty on empty bin);
    // late in stream, prefer squeezing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score.
        let mut new_bin_score = bin_capacity as f64;
        new_bin_score -= (1.0 - progress) * 30.0;      // cheap early, expensive late
        new_bin_score += open_bins_count as f64 * 4.0; // many open bins -> discourage more
        // If next item is large and current bins are fragmented, opening a fresh bin is good.
        if next_item_size as f64 > mean_residual {
            new_bin_score -= 15.0;
        }
        return new_bin_score;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) with a twist:
    // favor bins with residual slightly below mean (nearly-full bins get closed out).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Reward closing out bins entirely (perfect fill) as stream progresses.
    if post_residual == 0 {
        score -= 50.0 + progress * 30.0;
    }

    // Small residual chunks (<10) are dead space; penalize creating them.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste matters more (long future to reuse space); later, accept slack.
    let waste_weight = 1.0 + 1.5 * (1.0 - progress) * (1.0 - progress);
    score += (score - pr) + waste_weight * (x * x) * cap * 0.3;

    // Reward near-perfect fits with a smooth bump around x ~ 0
    score -= 8.0 * (-x * 12.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - (pr - nx) / cap;
            score -= 6.0 + 8.0 * tight * tight;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Penalize bins far from mean residual (smooth quadratic dispersion term)
    score += 0.05 * (mean_residual - bin_residual as f64) * (mean_residual - bin_residual as f64) / cap;

    // New-bin candidate: make empty bins mildly attractive only when current bin
    // would leave large dead space relative to next item, else discourage.
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) > x * cap {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // divisibility classes (multiples of 10, 25, 50) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, best possible outcome
    } else {
        if pr % 50 == 0 { score -= 45.0; }
        else if pr % 25 == 0 { score -= 25.0; }
        else if pr % 10 == 0 { score -= 15.0; }
        else if pr % 5 == 0 { score -= 8.0; }

        // Dead-space penalty: residual too small for the smallest plausible item
        if pr < 5 {
            score += 60.0;
        }

        // Harmonic fit: does next_item_size divide into the new residual evenly?
        if next_item_size > 0 && next_item_size <= pr {
            if pr % next_item_size == 0 {
                score -= 30.0;
            }
            // next item fills residual exactly
            if next_item_size == pr {
                score -= 40.0;
            }
        } else if next_item_size > 0 && next_item_size > pr {
            // residual can't hold next item: mild penalty scaled by waste
            let waste = pr as f64 / cap;
            score += 20.0 * waste;
        }
    }

    // Fractional capacity coupling: prefer bins whose fill level lands on
    // quarter-capacity marks after placement.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    let quarter = (fill * 4.0).round() * 0.25;
    score -= 12.0 * (1.0 - (fill - quarter).abs() * 4.0).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would
    // be left with unusable residue or bins are scarce.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0
            - 40.0 * progress
            - (mean_residual / cap).max(0.0) * 60.0;
        if post_residual == bin_capacity {
            score += 25.0; // never open a bin when nothing else fits logic applies
        }
    }

    // Tight-fit bonus: item consumes most of the bin's residual.
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    if ratio > 0.85 && bin_residual != bin_capacity {
        score -= 35.0 * ratio;
    }

    // Many open bins: encourage consolidation into low-residual bins.
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= ~15) are essentially unusable.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Hard penalty scaled by how "dead" the gap is.
        let deadness = (dead_threshold - post_residual) as f64;
        score += 3.0 * deadness + 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual tightly matches the item (low waste fraction).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading to new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when there are already fitting open bins
        // and many open bins; relax when open bins are nearly full on average.
        let pressure = open_bins_count as f64 * 2.5 + (fitting_bins_count as f64) * 15.0;
        let mean_relief = mean_residual / bin_capacity as f64;
        score += pressure - 20.0 * (1.0 - mean_relief);
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= 1.5 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits the post residual, this
    // placement chains nicely; otherwise the residual is less valuable.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let overhang = (next_item_size - post_residual) as f64;
            score += 0.15 * overhang;
        }
    }

    // Late in the stream, avoid leaving many scattered open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        // Perfect match: post_residual exactly fits the next item -> strong reward
        if post_residual == next_item_size {
            score -= 40.0 + 20.0 * (1.0 - progress);
        }
        // Next item fits in the leftover space -> moderate reward
        else if post_residual >= next_item_size {
            // Reward proportionally to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 + 25.0 * fill;
        }
        // Dead space: next item cannot use the leftover -> penalize
        else {
            // Penalize more when the dead space is small (unusable) and early in stream
            let dead = post_residual as f64;
            score += 8.0 + 0.15 * dead * (1.0 - progress);
        }
    }

    // ---- Mean residual coupling: prefer bins whose residual is below mean
    // (tighter bins get filled first, keeping looser bins flexible) ----
    score += 0.25 * (mean_residual - bin_residual as f64);

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Opening a new bin is only attractive when the item leaves a residual
        // that likely matches future needs and existing bins are poor fits.
        // Base new-bin score: keep it competitive but not dominant.
        score = 55.0 + post_residual as f64 * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins
        score += 20.0 * progress;
    }

    // Small tie-breaking pressure toward larger items filling bins tightly
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small but usable residue.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize awkward dead space: residue that is too small to hold a typical item
    // but nonzero (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: bonus if the next item can fit into the post-residual space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize leaving a residue the next item cannot use.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize spreading across many open bins when mean residual is already low.
    if open_bins_count > 2 {
        let pressure = mean_residual / bin_capacity as f64;
        score += 0.5 * pressure * (open_bins_count as f64);
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins clean); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // New-bin candidate handling: an empty bin has large post_residual, which is
    // naturally high-scored; add extra penalty unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += desperation;
        // Late in the stream, opening a fresh bin is more acceptable for large items.
        if item_size > 60 {
            score -= 6.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = post_residual == 0;

    // Base: prefer small post_residual (tight fit), scaled by capacity
    let mut score = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (quadratic & cubic terms)
    let dead = pr / cap;
    score += dead * dead * (0.5 + 1.5 * progress);
    score += dead * dead * dead * (2.0 * progress);

    // Reward exact fits strongly
    if fit {
        score -= 2.0;
    }

    // Penalize opening a new bin when existing bins fit, unless residual is large
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is attractive only if current item would leave a very poor fit elsewhere
        // and lookahead suggests room is useful; otherwise penalize mildly
        score += 0.6 + 0.4 * (1.0 - progress);
        // But if next item is large, fresh bin may be valuable later
        let nxt = next_item_size as f64 / cap;
        score -= 0.5 * nxt * nxt;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 1.0;
    }

    // Slight preference for bins below mean residual (keeps balance), smooth term
    let diff = (bin_residual as f64 - mean_residual) / cap;
    score += 0.1 * diff * diff;

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0) / cap;
        score += 0.3 * waste * waste;
    }

    // Mild penalty for too many open bins, decaying over stream
    score += 0.01 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that are "dead space"
    // classes (too small for the minimum item size 1) are heavily penalized.
    let dead = post_residual == 0;
    if dead {
        score -= 1000.0; // perfect fit: always best
    }

    // Classify post_residual into harmonic buckets via integer division by 10.
    // Small residuals (1..=10) are near-dead; large residuals are flexible.
    let class = post_residual / 10;
    let class_bonus = match class {
        0 => 25.0,             // 0..=9 residual: nearly unusable
        1 => 12.0,             // 10..=19
        2 => 6.0,              // 20..=29
        3 => 2.0,              // 30..=39
        4 => 0.0,              // 40..=49
        _ => -2.0,             // >=50: roomy bin, mild reward
    };
    score += class_bonus;

    // Exact modular harmony: post_residual divisible by 10 or 5 is a
    // "clean" class that future standard items can tile well.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly
    // or at least fits well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chains perfectly
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to how
            // "wasted" the residual will be, worse near stream end.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score -= 10.0; // still better to pack here than waste residual
        }
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // the item is large relative to capacity or all existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Large items benefit from a fresh bin (no fragmentation).
        if item_size > bin_capacity / 2 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If many bins are open already, discourage one more.
        score += 2.0 * open_bins_count as f64;
        // If mean residual is large, some open bin likely fits fine.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Mild preference for tighter fits overall (best-fit flavor).
    score += (bin_residual - item_size) as f64 * 0.05;

    // Slight preference for bins with below-average residual (keep roomy
    // bins available for future large items).
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hardest.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100, assume ~10).
    let min_item = 10.0f64.min(bin_capacity as f64);
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 3.0 * (min_item - post_residual as f64);
    }

    // Non-linear penalty: post_residual just below next_item_size is wasted (next item won't fit).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 2.0 * (next_item_size - post_residual) as f64;
    }
    // Reward exact or near-exact fit for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 1.5 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Tight fit reward: filling most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= 2.0 * (fill_ratio - 0.8);
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor closing bins out.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (empty bin has full residual; make it mediocre by default so existing bins win on tight fits).
    if bin_residual == bin_capacity {
        score += 1.0 + 0.3 * open_bins_count as f64;
        // But if current bin would leave a large dead gap, new bin becomes competitive.
        if (post_residual as f64) < min_item && post_residual > 0 {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (more filled bins).
    score += 0.2 * (mean_residual - bin_residual as f64).max(-10.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next item fits; reward tightness of that fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize small dead post-residual
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Prefer bins whose residual is far below mean (densely packed bins)
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless the fit is very tight
    if bin_residual == bin_capacity {
        let tight = (bin_capacity - item_size) as f64;
        score += 30.0 - 0.4 * tight;
    }

    // Late in the stream: prefer closing bins out, penalize spreading
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (open_bins_count as f64).ln1p();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Penalize leaving dead space that no plausible item (min size 1, but
    // practically >= 10 in classic regime) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin scales with how much of the item it holds.
        score = 60.0 + 0.5 * item_size as f64;
        // If many bins are open and mean residual is large, discourage new bins.
        score += 0.3 * open_bins_count as f64;
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
        // Early in the stream, new bins are cheaper (more future to fill them).
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If nothing else fits, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is already close to the item (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - item_size as f64).abs();

    // Mild preference to fill bins with larger residual first when many are open.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Global pressure: late in the stream, be greedier about tight fits.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Deviation from mean residual: prefer bins that deviate less (balance load),
    // but only when the item actually leaves useful space.
    if post_residual >= 10 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next = next_item_size as f64;
    let mean_res = mean_residual;

    // Base: wasted space, mildly super-linear to prefer tight fits.
    let mut score = post + 0.05 * post * post / cap;

    // Smooth coupling: late in the stream, waste is costlier.
    score += 2.0 * progress * post / cap;

    // Reward bins whose post-residual can host the lookahead item.
    if next > 0.0 && post >= next {
        score -= 3.0 * (next / cap) * (1.0 - post / cap);
    } else if next > 0.0 {
        // Near-miss coupling: penalize residuals just below the next item.
        let gap = (next - post) / cap;
        score += 2.5 * gap * gap;
    }

    // Deviation from mean residual: prefer bins deviating smoothly (polynomial).
    let dev = (post - mean_res) / cap;
    score += 1.5 * dev * dev - 0.5 * dev;

    // Last-chance bin: strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Many open bins: favor consolidation.
    score += 0.05 * (open_bins_count as f64) * (post / cap);

    // New-bin candidate: penalize opening a new bin, more so if fits exist or stream is late.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
        if fitting_bins_count > 1 {
            score += 4.0;
        }
        if next > 0.0 && next <= cap - fit {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post_residual: which capacity fraction band it lands in.
    // Classes: [0], (0..10], (10..25], (25..50], (50..100]
    let class = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward exact fits and tiny dead space strongly.
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 8.0,
        3 => score -= 0.0,
        _ => score += 5.0,
    }

    // Lookahead: does next_item_size fit into the post_residual? Harmonic compatibility.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: strong reward, scaled by how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 20.0 - snug * 0.15;
        } else {
            // Next item will NOT fit here: penalize, worse if we barely used the bin.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.10;
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large relative to capacity or no good class exists among open bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Large items start fresh bins happily.
        if item_size * 5 >= bin_capacity * 3 {
            score -= 25.0;
        }
        // Late in the stream, avoid spawning bins with big residual.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins fill first),
    // keeping mean_residual as a soft reference.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.05;

    // Mild penalty for proliferating bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are "dead" —
    // punish them hard so we prefer either perfect fills or large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fill is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to item size (small post_residual / item_size).
    if item_size > 0 {
        score -= 25.0 * (1.0 - post_residual as f64 / item_size as f64);
    }

    // Open-bin pressure: with many open bins, favor packing into existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 3.0 + 10.0 * open_bins_count as f64 + 5.0 * progress;
    if bin_residual == bin_capacity {
        score += pressure;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= post_residual + 10 {
        // next item would leave a dead gap here too — mild penalty
        score += 8.0;
    }

    // Prefer bins whose residual is already below the mean (consolidating fullness).
    if bin_residual != bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item size.
    if next_item_size > 0 {
        let match_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * f64::exp(-match_diff / 8.0);

        // Perfect chaining: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Slight penalty if post_residual is awkwardly small (dead space) but larger than 0.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Relative to mean residual: prefer bins that are more filled than average.
    let mean_post = mean_residual - item_size as f64;
    score -= 0.5 * (mean_post - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent fitting bins exist.
    if bin_residual == bin_capacity {
        let base = 10.0 + 0.3 * open_bins_count as f64;
        score += base;
        if fitting_bins_count > 0 && next_item_size > 0 {
            score += 20.0;
        }
        if step_index as f64 / total_items as f64 > 0.9 {
            score += 15.0; // late in stream, avoid opening bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual), non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item (1..=100) can use well:
    // residuals below 10 are near-perfect; residuals just above common small sizes are fine.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 6.0;  // usable by small items
    } else if post_residual > 60 {
        score += 4.0;  // wasteful large hole
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - waste as f64 / 50.0).max(0.0);
        } else {
            score += 5.0; // next item would not fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, prefer keeping bins flexible (moderate penalty
    // for very small residuals); late in the stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 && post_residual > 0 && post_residual < 5 {
        score += 3.0;
    }
    if progress > 0.7 {
        score -= 8.0 * tightness;
    }

    // Global state: many open bins with high mean residual -> discourage spreading,
    // favor filling existing bins; few open bins -> slightly favor opening fresh ones
    // only when fit is poor.
    if open_bins_count > 4 && mean_residual > 40.0 {
        score -= 5.0 * (mean_residual / 100.0);
    }
    if open_bins_count < 3 && post_residual > 50 {
        score += 3.0;
    }

    // New-bin candidate handling: empty bin starts at full residual; make it attractive
    // only when the current bin's fit is bad (large post_residual) or no good fit exists.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.55
            + 0.4 * (post_residual as f64)
            - (if fitting_bins_count == 0 { 40.0 } else { 0.0 })
            - 10.0 * tightness;
        // Late in stream, opening new bins is less desirable; prefer squeezing in.
        score += 20.0 * progress;
        // If the item fits almost perfectly somewhere else, new bin is worse.
        if post_residual <= 10 && fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: waste left behind, with non-linear penalty on unusable slivers.
    let mut score = pr + 0.35 * (pr / cap).powi(2) * cap;

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item fits into the post-residual, reward it;
    // if it nearly fits, slight penalty for blocking a better pairing.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 4.0 * (nxt / cap);
        } else if nxt <= pr + 10.0 {
            score += 2.0 * (1.0 - pr / nxt);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 4.0 * progress;
    }

    // Stream-progress coupling: late in the stream, prefer consolidating
    // into bins with low mean residual (sealing near-full bins).
    let dev = (mean_residual - pr) / cap;
    score += progress * 3.0 * dev.abs() * (1.0 + dev.abs());

    // Mild penalty for spreading across many open bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * (pr / cap) * (1.0 - progress);

    // New-bin candidate: keep it competitive only when all open fits are bad.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let prog = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residual too small for any item (min size 1, but tiny scraps are worthless)
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if !is_new_bin && post_residual == 0 {
        score -= 25.0; // perfect fill reward
    }

    // Lookahead: reward bins that can also host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // harmonic class: residual bucket divisible by next item size is extra useful
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 4.0;
            }
        } else if !is_new_bin {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening a bin
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 18.0;
    }
    // Many alternatives: mild penalty to spread preference toward tight fits
    if !is_new_bin && fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate: acceptable early / when item is large relative to residual mean,
    // penalized late in the stream to force consolidation
    if is_new_bin {
        score += 8.0 + 14.0 * prog;
        if item_size > 60 { score -= 6.0; }
        if mean_residual > 40.0 { score -= 5.0; }
    }

    // Harmonic capacity-quarter classes on post_residual
    let q = post_residual / 25;
    score += match q {
        0 => 4.0,  // 0..25: near-full, good
        1 => 0.0,  // 25..50: neutral
        2 => -2.0, // 50..75: flexible
        3 => 2.0,  // 75..100: wasteful unless item large
        _ => 0.0,
    };

    // Prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Penalize open-bin proliferation slightly
    if !is_new_bin {
        score -= 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals too small for the smallest possible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Soft penalty: small but usable gaps are risky if they can't fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 18.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 35.0 + 12.0 * pressure;
    } else {
        score -= 4.0 * pressure;
    }

    // Slight preference for bins tighter than average.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 60.0; // perfect 2-chain: item then next item fills bin
        } else if post_residual >= next_item_size {
            // next item fits after this one; reward tightness of the chain
            let slack = post_residual as f64 - next;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin; penalize proportionally to leftover
            score += 10.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Reward tight fit relative to current bin residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Penalize creating dead space far from mean residual (fragmentation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer reusing an existing well-matched bin; only
    // open a new bin when this item is huge and residuals are all poor fits
    if bin_residual == bin_capacity {
        let reuse_quality = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        let pressure = if open_bins_count == 0 { 0.0 } else { 1.0 };
        score += 35.0 * pressure - 20.0 * reuse_quality;
        // opening fresh bin is good when item is large relative to mean residual
        let big_item = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * big_item;
    }

    // Late-stream consolidation: prefer fuller bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let cap = bin_capacity as f64;
    let fit_ratio = post_residual as f64 / cap;
    score += fit_ratio * fit_ratio * 30.0;

    // Reward perfect/very tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Penalize dead space that is too small for likely future items (10..80 originally,
    // but unknown distribution: penalize residuals below a dynamic threshold).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dynamic_threshold = 8.0 + 12.0 * (1.0 - progress);
    if post_residual as f64 > 0.0 && (post_residual as f64) < dynamic_threshold {
        score += (dynamic_threshold - post_residual as f64) * 2.5;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.6;
        } else {
            // Next item won't fit here anyway; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins with high mean residual: discourage spreading, prefer consolidation.
    let crowded = (open_bins_count as f64).ln().max(0.0);
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.35 * crowded + 0.12 * mean_gap;

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let scarcity_bonus = if next_item_size > 0 && next_item_size as f64 > mean_residual { 10.0 } else { 0.0 };
        score = cap - item_size as f64
            + 55.0 * pressure
            + 6.0 * crowded
            - scarcity_bonus
            - 20.0 * (1.0 - progress);
    }

    // Early stream: mild bonus for keeping bins balanced (future flexibility).
    score += (1.0 - progress) * 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let p = norm_pr * (1.0 + 0.8 * progress * progress + 0.6 * progress * fit);
    let mut score = p * (1.0 - 0.35 * p) + 0.15 * norm_pr * norm_pr;

    // Reward tight fits smoothly (quadratic in fit ratio).
    score -= 6.0 * fit * fit * (1.0 - progress);

    // Dead-space penalty: residuals too small to matter later.
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 2.0 * dead * dead;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Lookahead: favor bins whose post-residual fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 2.5 * (1.0 - ((pr - nxt) / cap).abs());
        } else {
            score += 1.5 * ((nxt - pr) / cap);
        }
    }

    // Mild preference for consolidating into fewer bins early.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: smooth threshold via mean residual.
    if bin_residual == bin_capacity {
        score += 1.0 + 0.02 * mean_residual * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Residuals divisible by small item sizes (or landing in coarse classes) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Dead-space penalty: residuals that no plausible item (1..=100) can pair into
    // are heavily punished. A residual of exactly 0 is perfect.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        // tiny unusable sliver (items are >= 1 but small residuals waste little)
        score += 2.0 * (10.0 - pr);
    }

    // Modulo classes: residuals that are multiples of common sizes (10, 20, 25, 50)
    // are more likely to be exactly filled later.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    // Harmonic band penalty: mid-range residuals are the worst dead space.
    if pr > 0.0 && pr < 0.5 * cap {
        score += 14.0 * (0.5 * cap - pr) / cap;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly reward; if next item nearly fits, mild reward; if next item
    // cannot use the leftover at all, penalize proportionally.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - waste / cap);
            if (post_residual - next_item_size) % 10 == 0 { score -= 3.0; }
        } else {
            score += 0.05 * (ni - pr).min(cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin when existing bins fit well.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Opening new bins is more acceptable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - progress);
        // If mean residual across open bins is small, a new bin is reasonable.
        score -= (mean_residual / cap).min(1.0) * 4.0;
    }

    // Slight preference to balance load across many open bins.
    score += 0.02 * open_bins_count as f64;

    // Tight-fit bonus: item nearly fills the bin.
    let tightness = 1.0 - frac;
    score -= 8.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it is too small to hold the smallest plausible item (1..100 range,
    // but conservatively assume items >= 10 can still arrive; anything < 8 is near-dead).
    if post_residual > 0 && post_residual < 8 {
        score += 40.0; // hard penalty for creating a sliver gap
    } else if post_residual < 15 {
        score += 12.0; // soft penalty for tight-but-likely-dead gaps
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Coupling: dead space matters more when the bin's residual was small
    // (a tight bin wasted on a loose fit is doubly bad).
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 0.8;
    }

    // Open-bins pressure: with many open bins, prefer packing tighter into existing bins
    // to avoid bin proliferation; subtract to favor reusing open bins.
    score -= open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no existing bin fits at all, opening a new bin is fine (handled by
        // fitting_bins_count of other calls being 0 -> their scores irrelevant here).
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack < 10.0 {
            score -= 10.0; // next item nearly fills the leftover
        }
    }

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post-residual: reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    }
    // Dead space: post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(40.0);
    }

    // Tight fit reward: item nearly fills the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Penalize leaving tiny unusable residuals (below minimum item size 1..=100 heuristic: < 10).
    if post_residual < 10 {
        score -= 20.0; // small dead space is fine if bin is nearly exhausted
    } else if post_residual < 25 {
        score += 12.0; // awkward mid-range residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Relative to mean residual: prefer consuming bins with below-average residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current bin would leave large waste.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 35.0 };
        score += 20.0 + waste_penalty - 0.3 * open_bins_count as f64;
    }

    // Late in the stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<= 1..100 range guard).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits the post residual (chaining placements).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if next_item_size <= bin_capacity {
            // If next item would need a fresh bin anyway, mild penalty for wasting big residual here.
            let waste = post_residual as f64 - (bin_capacity as f64 - next_item_size as f64).max(0.0);
            score += 0.05 * waste.max(0.0);
        }
    }

    // New-bin candidate handling: only prefer opening a new bin when existing fits are poor
    // or mean residuals across open bins are already fragmented.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Base penalty: prefer existing bins by default.
        let mut new_bin_score = 12.0;
        // If open bins are highly fragmented (large mean residual = poor packing), new bin is more attractive.
        new_bin_score -= 20.0 * fragmentation * fragmentation;
        // Late in the stream, closing out bins matters more; discourage new bins.
        new_bin_score += 10.0 * progress;
        // If many bins can fit, discourage a new one further.
        new_bin_score += 2.0 * fitting_bins_count as f64;
        // If this item would leave a large residual in an existing bin, new bin slightly less bad.
        new_bin_score += 0.03 * post_residual as f64;
        score = new_bin_score;
    }

    // Mild preference for bins whose residual is close to item_size (exact-ish fits).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * fit_gap;

    // Slight pressure to consolidate when many bins are open.
    score += 0.01 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: minimize leftover space.
    let mut score = post;

    // Smooth non-linear reward for tight fits (post_residual near 0 or small).
    let tightness = 1.0 - post / cap; // in (0,1], larger = tighter fit
    score -= 12.0 * tightness * tightness;

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late in stream, punish large residuals harder.
    let prog_sq = progress * progress;
    score += post * (0.5 * prog_sq + 0.3 * progress);

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let small_thresh = 10.0f64;
    if post < small_thresh {
        score += (small_thresh - post) * (1.5 + prog_sq);
    }

    // Lookahead coupling: if next item can fit in post_residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - progress) * (1.0 - (post - nxt) / cap);
        } else {
            // If next item is large and won't fit here, mildly penalize near-full bins
            // that leave the next item stranded.
            score += 2.0 * progress * (1.0 - post / cap);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or many bins are already open. Smooth coupling with mean residual.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Late in stream, reusing bins is even more valuable.
        score += 10.0 * prog_sq;
    }

    // Mild penalty proportional to crowding: spreading items over many bins
    // is worse; prefer filling existing bins when mean residual is high.
    score -= 0.05 * mean_residual * (1.0 - prog_sq);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: items of size 10..80 mean typical
    // dead-space classes cluster around small multiples of 10.
    let pr = post_residual as u32;
    let class = pr / 10; // integer-division harmonic class (0..=10)
    // Reward small classes strongly (perfect fit), penalize mid classes (dead space)
    match class {
        0 => score -= 30.0,                       // perfect fit
        1 => score -= 18.0,                       // near-perfect: only items <=9 wasted
        2 => score -= 8.0,
        3 => score -= 2.0,
        4 => score += 2.0,
        5 => score += 6.0,                        // half-empty bin: worst mid class
        6 => score += 4.0,
        7 => score += 1.0,
        8 => score -= 3.0,                        // small hole again, useful
        9 => score -= 6.0,
        _ => score -= 10.0,                       // empty-bin candidate class (10)
    }

    // Modulo coupling: leftover divisible by 10 pairs well with future items
    if pr % 10 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - pr).min(40) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins when many are open (consolidation pressure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64) * 0.15 * (0.5 + progress);

    // Tie-break toward bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Slight preference for tight fit relative to item size
    score += (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically < ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver penalty
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit: fully consumed bin
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0; // marginally usable gap
    }

    // Reward tight fits relative to residual (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Penalize leaving a gap much larger than the lookahead item only if
    // the lookahead item could not use the post_residual anyway.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // gap unusable by next item: mild penalty scaled by gap size
            score += 0.15 * (post_residual as f64);
        } else if post_residual == next_item_size {
            score -= 15.0; // lookahead chains perfectly
        } else {
            score -= 5.0; // lookahead can still fit
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // loose bins; favor consolidation.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 20.0);
    score += 0.5 * pressure * (1.0 - fit_ratio);

    // New-bin candidate handling: only attractive when no open bin fits
    // well or open bins are nearly saturated.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        } else {
            // opening fresh is only good if best open fit would be sloppy
            score += 12.0 + 0.3 * (post_residual as f64) + 0.2 * open_bins_count as f64;
        }
    }

    // Early stream: slightly more willing to open bins (builds structure);
    // late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 - progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it moderately attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_cost = 1.0 + 0.01 * open_bins_count as f64;
        let scarcity = if fitting_bins_count == 0 { -3.0 } else { 0.0 };
        return open_cost + scarcity + 0.3 * mean_residual / bin_capacity as f64;
    }

    // Perfect fit reward: leave nothing behind.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 20.0; // chain fit: this bin's leftover exactly hosts the next item
        }
        // Penalize leaving dead space the next item cannot use.
        if post_residual > next_item_size {
            score += 0.15 * (post_residual - next_item_size) as f64;
        }
    }

    // Relative-to-mean residual: prefer consuming bins with below-average residual
    // (tight bins) to consolidate fragmentation.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Small post-residual is generally good (less wasted space).
    score -= 0.25 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Late-stream consolidation: as stream progresses, tighten more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: squared dead-space penalty
    score += (post_residual as f64 / cap).powi(3) * 30.0;

    // Reward bins whose residual is close to item size (best-fit flavor)
    let gap = (bin_residual as i64 - item_size as i64) as f64;
    score -= (1.0 - gap / cap).max(0.0) * 20.0;

    // Last chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, this placement is chain-friendly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // wasted residual for the known next item
            score += (next_item_size as f64 - post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // New-bin candidate: make it moderately attractive when open bins are crowded,
    // unattractive early in the stream (prefer filling existing bins)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (open_bins_count as f64) * 0.5 + mean_residual * 0.1;
        score += (1.0 - progress) * 15.0;
    }

    // Slight preference for bins below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalize large residuals with non-linear growth
    let mut score = pr * pr / (cap * 2.0) + pr * 0.5;

    // Smooth polynomial coupling with stream progress:
    // late in the stream, tolerate larger residuals less (tight packing matters)
    let prog_coupling = 1.0 + progress * progress * 2.0 + progress * 0.5;
    score *= prog_coupling;

    // Interaction: normalized residual squared times progress (dead space penalty grows)
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Perfect fit reward (smooth, non-piecewise)
    if pr == 0 {
        score -= cap * (1.0 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 * fit_quality * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize creating residual the next item cannot use (dead space)
        score += 5.0 + 5.0 * progress;
    }

    // New-bin candidate: mildly penalize spreading open too early, more later
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) * (1.0 - progress) + 8.0 * (open_bins_count as f64).sqrt();
        // but if mean residual is large and item is big, opening is fine
        score -= (mean_residual / cap) * (1.0 - progress) * 10.0;
    }

    // Prefer bins below mean residual (consolidation toward fuller bins)
    score += (pr - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual == 0 (perfect fill) -> strong reward
    // Class 1: post_residual < small threshold -> near perfect
    // Class 2: post_residual is a multiple of 25 (quarter classes) -> decent
    // Class 3: otherwise -> penalize dead space, worse for large leftovers
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr % 25 == 0 {
        score -= 20.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else {
        // dead space penalty grows superlinearly with leftover size
        score += (pr as f64) * (pr as f64) / 300.0;
    }

    // Integer-division coupling: does the leftover admit the NEXT item?
    // Reward when next item fits exactly into post_residual (harmonic match),
    // penalize when next item is much smaller than post_residual (wasted space).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 25.0;
            } else if slack % 25 == 0 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.4;
            }
        } else {
            // next item cannot use this bin's leftover; leftover likely dead
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin should only win on perfect fits
    if bin_residual == bin_capacity {
        score += 55.0;
        if pr == 0 {
            score -= 55.0; // perfect fill from scratch is fine
        }
    }

    // Late in the stream, prefer tightening existing bins (fewer stragglers)
    let progress = step_index as f64 / total_items as f64;
    score += progress * mean_residual * 0.05;
    score -= progress * 5.0;

    // Many open bins: discourage spreading into bins with large residuals
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual).abs() * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is very tight.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it moderately attractive only when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * tightness;
        if fitting_bins_count >= 1 {
            score += 25.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Mean residual alignment: prefer bins close to the average residual.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 50.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            let waste = next_item_size - post_residual;
            score += 0.5 * waste as f64;
        }
    }

    // Penalize residuals that are too small to ever fit typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins below-mean (tighter packing).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: baseline penalty so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 250.0;
        // But if the item is large and next item would also need a fresh bin, allow opening.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (open_bins_count as f64 / 10.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward exact/tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.95 {
        score -= 30.0;
    } else if fit_ratio > 0.7 {
        score -= 10.0 * fit_ratio;
    }

    // Penalize large dead space relative to smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // small dead space is fine
    } else if post_residual >= 10 {
        score += 0.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            // bonus if next item also nearly fills the remaining space
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * next_fit;
        } else {
            // dead space that the next item cannot use: mild penalty scaled by wasted fraction
            let waste = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 4.0 * waste;
        }
    } else {
        // Last item of stream: maximize packing density.
        score -= 15.0 * fit_ratio;
    }

    // Global state: many open bins with high mean residual -> prefer reusing sparse bins,
    // discourage spreading residual too thin.
    if open_bins_count > 0 {
        let spread = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        // Pressure to consolidate when many bins are open.
        score += 0.02 * open_bins_count as f64;
    }

    // Time horizon: early in the stream, be conservative (keep bins balanced);
    // late in the stream, prioritize closing out bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fit_ratio;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins already open
        // (consolidation is less valuable) or fit elsewhere would be terrible.
        let poor_fit_elsewhere = fitting_bins_count == 0 || fit_ratio < 0.3;
        let base_cost = 45.0 - 0.1 * open_bins_count as f64;
        score = if poor_fit_elsewhere { base_cost - 10.0 } else { base_cost + 10.0 * fit_ratio };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fit preferred, quadratic waste penalty (dead space grows superlinearly)
    let mut score = pr as f64 + 40.0 * x * x;

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, large residuals become more costly (fewer chances to fill)
    let late_factor = 0.5 + 1.5 * progress * progress;
    score += 30.0 * x * x * late_factor;

    // Reward near-perfect fits smoothly (continuous bonus around x ~ 0)
    let tightness = (-8.0 * x).exp();
    score -= 25.0 * tightness;

    // Penalize leaving residual that just barely fails to fit the next item
    // (smooth version: closeness of next item to post residual)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let near_miss = (-0.08 * gap).exp();
        score += 12.0 * near_miss * (1.0 - progress);
        // Reward leaving room exactly for the next item
        let exact = (-(pr - next_item_size as f64) * (pr - next_item_size as f64) / 50.0).exp();
        score -= 18.0 * exact;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate (empty bin): penalize mildly so it's chosen only when
    // existing fits are poor; penalty relaxes as many bins pile up
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score += 35.0 + 5.0 * crowd;
    }

    // Mild preference to spread across bins when mean residual is high (balance load)
    score -= 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer minimal leftover space.
    let mut score = pr as f64;

    // Reward using a large fraction of the bin's capacity.
    score -= (item_size as f64 / cap) * 20.0;

    // Perfect fit: strong reward.
    if pr == 0 {
        score -= 50.0;
    }

    // Harmonic dead-space classes on post_residual (modulo-style thresholds).
    let dead_class: f64 = if pr == 0 {
        0.0
    } else if pr <= 5 {
        0.5
    } else if pr <= 12 {
        2.0
    } else if pr <= 25 {
        4.5
    } else if pr <= 50 {
        7.0
    } else {
        9.0
    };
    score += dead_class;

    // Lookahead coupling (k=2): reward bins whose residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly-ish: extra reward for harmonic alignment.
            let align = (pr % next_item_size.max(1)) as f64;
            score -= 8.0 - align * 0.15;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: normally penalize opening a new bin...
    if is_new_bin {
        score = pr as f64 + 30.0;
        // ...unless almost no open bin can fit (avoid stranding the item).
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        // Favor a fresh bin if the next item is large and would need space anyway.
        if next_item_size >= item_size {
            score -= 10.0;
        }
        // Late in the stream, avoid leaving many near-empty bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Mild coupling with the mean residual across open bins: prefer bins
    // whose post-residual stays near the fleet mean (balanced packing).
    score += (mean_residual - pr as f64) * 0.1;

    // Slight preference for consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable gaps (dead space below min item size)
    let min_item = 1.0f64;
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Graded penalty: gaps that no plausible item can fill
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 25.0 {
        score += (25.0 - gap) * 1.5;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 - ((post_residual - next_item_size) as f64 * 0.3);
    }
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading when many bins are open
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: exact match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let left = post_residual - next_item_size;
            if left <= 10 {
                score -= 70.0;
            } else {
                score -= 40.0 * (1.0 - left as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot follow here: penalize wasting space the next item could have used elsewhere.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 120.0 } else { 40.0 };
        score += pressure + 0.3 * open_bins_count as f64;
        // Late in stream, prefer reusing bins.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 30.0;
        }
    }

    // Mild preference for tighter existing bins.
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Penalize leaving residuals that no typical item can use (dead space).
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small unusable gap is fine only if it's tiny
    }
    if post_residual >= 10 && post_residual <= 80 {
        score -= 4.0; // residual usable by future items
    } else if post_residual > 80 {
        score += 10.0; // huge residual means we barely used the bin... but only for near-empty bins
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits even more.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    let open_f = open_bins_count as f64;
    score -= 0.5 * open_f.ln().max(0.0) * (1.0 - tightness);

    // Prefer bins whose residual is below mean residual (fill the emptier-relative bins less,
    // i.e., favor bins that are already relatively full).
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * rel;

    // Time horizon: early in the stream, be pickier (higher score variance); late, just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate handling: an empty bin gets a moderate baseline so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 60.0 - 10.0 * progress + 2.0 * open_f.ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits; new bin is necessary
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0; // room to pair upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress
    let p = progress;
    let coupling = x * x * (1.0 - x) * (2.0 + 6.0 * p) + x * p * p * 4.0;
    score += coupling * cap * 0.5;

    // Penalize large residuals more as stream progresses (less time to fill them)
    score += (pr * pr / cap) * (0.3 + 0.7 * p);

    // Reward tight fits (small post_residual) with a smooth bonus
    score -= (1.0 - x) * (1.0 - x) * 8.0 * (0.5 + p);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward residuals that can still hold the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap * cap / cap.max(1.0);
        }
    }

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * p;
        if open_bins_count > 0 {
            score += (open_bins_count as f64).ln() * 2.0;
        }
    }

    // Slight preference to balance residuals across open bins
    score += (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead-space classes mod 10
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -6.0,          // perfectly reusable class
        1 | 2 => 2.5,       // nearly useless slivers
        3 | 4 | 6 | 7 => 0.5,
        5 => -1.0,          // half-class, often reusable
        _ => 1.0,
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: coarse capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual == 0 {
        score -= 12.0; // perfect fit
    } else if post_residual < quarter / 2 {
        score += 8.0; // dead space too small for min-size item
    } else if post_residual <= quarter {
        score -= 2.0;
    } else if post_residual <= half {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic residue match: next item's class aligns with leftover
            let harmony = ((post_residual - next_item_size) % 10) as f64;
            score -= 6.0 + 0.4 * (10 - harmony);
        } else {
            // Next item cannot use this leftover; penalize proportionally to waste
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 + 0.15 * gap;
        }
        // If next item fits ONLY here, strongly favor keeping room for it
        if next_item_size <= post_residual && next_item_size > bin_residual - item_size - post_residual.min(0) {
            score -= 1.0;
        }
    } else {
        // Last item: just minimize leftover
        score -= 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate: empty bin gets a baseline that must beat bad fits,
    // but lose to good fits into existing bins.
    if bin_residual == bin_capacity {
        // Penalize opening new bins more as the stream progresses / many bins open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
        // If no other bin really fits well, opening is fine: soften via mean residual
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for tighter bins among open ones
    score += 0.05 * (mean_residual - post_residual as f64);

    // Modulo coupling on item size: items with "nice" residues pack better
    let item_class = item_size % 10;
    if item_class == post_residual % 10 && post_residual > 0 {
        score -= 1.5; // same harmonic class -> future alignment likely
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are "dead space". Penalize them heavily,
    // but zero residual is a perfect fit.
    if post_residual > 0 {
        let dead_threshold: f64 = 12.0;
        if (post_residual as f64) < dead_threshold {
            // Small unusable gap: strongly discourage.
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tightness * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 15.0 + pressure * 6.0;
    } else {
        score -= pressure * 2.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this
    // placement for enabling a follow-up fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual blocks the next item: mild penalty proportional to waste.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Prefer bins whose residual is below the mean (consolidating emptier space).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when post_residual exactly matches next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        // Perfect match: strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Post-residual too small to ever fit next item: penalize dead space.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: just minimize waste.
        score += 10.0;
    }

    // Compare post_residual relative to mean residual of open bins.
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if no existing bin fits well, allow opening: new bin baseline.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Early in stream: prefer tighter packs to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    // Discourage many open bins with large residuals (fragmentation).
    if open_bins_count > 3 {
        score += (open_bins_count as f64 - 3.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Penalize dead space that is too small to be useful later
    // (items are 1..=100; residual < next plausible minimum is waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Mean residual coupling: prefer bins whose residual is below mean
    // (fill the fullest bins first, keep slack spread wide).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Time horizon: early in the stream, be more selective (penalize mediocre fits);
    // late in the stream, just pack anything to close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 15.0;
    score -= progress * 5.0;

    // New-bin candidate: make it moderately attractive only when the fit
    // in existing bins is bad (large post_residual) or no real alternative exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream.
        score = 45.0 + post_residual as f64 - progress * 15.0;
        // If nothing else fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 30.0 * poly;

    // Reward tight fits more aggressively as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 12.0 * (1.0 - slack / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin penalty avoidance
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.3 + 0.7 * progress);
    }

    // Prefer bins with residuals near mean residual (smooth coupling)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * (1.0 - dev);

    // Mild penalty for spreading across many open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize slightly unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let waste = pr / cap; // = 1.0 for empty bin
        let poor_fit = 1.0 - (item_size as f64 / cap);
        score += 5.0 * waste * poor_fit * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residual mod 10 buckets
    let post = post_residual;
    let class = post % 10;

    // Reward leftovers that form "useful" harmonic classes (multiples of 5/10)
    if post == 0 {
        score -= 200.0; // perfect fit is always best
    } else if class == 0 {
        score -= 40.0;  // leftover divisible by 10 -> highly reusable
    } else if class == 5 {
        score -= 25.0;  // half-class leftover
    } else if post < 10 {
        score += 60.0;  // dead space: unusable for min-size items
    } else {
        // penalize awkward remainders proportionally
        score += class as f64 * 1.5;
    }

    // Lookahead coupling: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            // leftover can host next item: reward, scaled by how snugly
            let slack = (post - next_item_size) as f64;
            score -= 30.0 + slack * 0.2;
            // harmonic bonus if leftover - next is also a clean class
            if (post - next_item_size) % 10 == 0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize if leftover is near-miss
            let miss = (next_item_size - post) as f64;
            score += miss * 0.8;
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are crowded
    // or the fit here would be terrible
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; adjust with stream progression
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 150.0 + 100.0 * progress;
        // if open bins have plenty of room on average, opening new bins is wasteful
        new_bin_score += (mean_residual - item_size as f64).max(0.0) * 1.2;
        // many open bins with room -> discourage new bins
        new_bin_score += open_bins_count as f64 * 3.0;
        // if next item is large, a fresh bin preserves flexibility
        if next_item_size > 60 {
            new_bin_score -= 40.0;
        }
        score = new_bin_score;
    } else {
        // prefer fuller bins: reward small residuals relative to mean
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.5;
        }
    }

    // Tight fit reward: residual barely fits item
    if bin_residual != bin_capacity && item_size as f64 >= bin_residual as f64 * 0.9 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual as i32) as f64 * 40.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21 - post_residual as i32) as f64 * 6.0;
    } else if post_residual > 20 && post_residual <= 35 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Dead space relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 1.5;
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item almost fits but not quite, penalize leaving a near-miss gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New-bin candidate baseline: keep it competitive but slightly costly.
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits but not zero-waste extremes that strand capacity
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: perfect chain match (next item exactly fills post_residual)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            // reward small leftover after the chain, penalize mid-range dead space
            if slack_after_next < 10 {
                score -= 25.0;
            } else if slack_after_next <= 20 {
                score -= 8.0;
            } else {
                score += slack_after_next as f64 * 0.3;
            }
        } else {
            // next item cannot chain here; penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Compare post_residual against mean residual: leaving this bin near mean keeps flexibility
    let deviation = post_residual as f64 - mean_residual;
    score += deviation.abs() * 0.15;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    if bin_residual == bin_capacity {
        let open_fit_quality = post_residual as f64; // = capacity - item
        // penalize opening new bins early in the stream or when many bins open
        score += 45.0 + 3.0 * open_bins_count as f64;
        // allow new bin for huge items that leave bad residue
        if open_fit_quality > 0.0 && open_fit_quality < 15.0 {
            score -= 40.0; // item nearly fills a fresh bin: good
        }
        if next_item_size > 0 && next_item_size >= open_fit_quality as u32 && open_fit_quality > 0 {
            score += 20.0; // next item won't fit the fresh bin's residue either
        }
    }

    // Dead-space penalty: residue below smallest plausible item is waste
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fits (post_residual near 0)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Lookahead coupling: reward when next item fits into post_residual (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 20.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving dead space the next item cannot use
        let dead = (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)).max(0.0);
        score += 5.0 * dead / bin_capacity as f64 * 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to encourage diversity of choices via tightness only
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global residual state: penalize bins far from mean residual (outliers)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    // Time horizon: early on, be more exploratory (favor opening bins for large items);
    // late in stream, consolidate (favor existing bins)
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early when item is large
        let size_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_cost = 18.0;
        new_bin_cost -= 15.0 * size_frac * (1.0 - progress);
        // If no open bin fits well, opening is cheap
        if fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        } else {
            // If existing fit is poor (large post_residual elsewhere), opening is attractive
            new_bin_cost -= 0.2 * post_residual as f64;
        }
        // Penalize opening when many bins already open late in stream
        new_bin_cost += 0.5 * open_bins_count as f64 * (0.3 + progress);
        score += new_bin_cost.max(0.0);
    } else {
        // Existing bin: small bonus to prefer reuse, stronger late in stream
        score -= 6.0 * (0.5 + progress);
        // Reward bins whose residual is close to item (best-fit signal)
        let gap = (bin_residual - item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Small noise-free deterministic tiebreaker keyed on residual
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with a convex (quadratic) penalty
    // so tiny dead spaces are disproportionately rewarded.
    let mut score = norm_pr * norm_pr * cap + norm_pr * cap * 0.5;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate loose fits (favor spreading); late, tighten.
    let progress_coupling = (1.0 - progress) * (norm_pr * (1.0 - norm_pr)) * cap * 0.8;
    score -= progress_coupling;

    // Reward filling a bin well relative to mean residual state (smooth cubic term).
    let mean_norm = mean_residual / cap;
    let mean_term = (norm_item - mean_norm).powi(3) * cap * 0.3;
    score += mean_term;

    // Last-chance bonus: strongly favor the only bin that fits (smooth sigmoid-like weight).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: penalize if post-residual cannot plausibly host the next item,
    // smoothly scaled by how much would be wasted.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.5 + 0.5 * progress);
        } else {
            // small reward for leaving a usable gap for the next item
            score -= 2.0 * (1.0 - (pr - nxt) / cap);
        }
    }

    // Mild penalty for proliferating bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 0.5;

    // New-bin candidate: make it moderately attractive early, less so late,
    // and only if the current bin would be left with awkward residue.
    if bin_residual == bin_capacity {
        score = norm_pr * 0.0 + 10.0 - 8.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) > cap * 0.5 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are ideal
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 300.0; // near-perfect: dead space negligible
    }

    // Modulo-10 harmonic classes: residuals in {0,10,20,...} leave room
    // for the smallest items (sizes 1..=10 exist under the extended interface)
    if pr % 10 == 0 && pr > 0 {
        score -= 40.0;
    }
    // Residuals just below 10 are the worst dead space
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= bin_capacity {
        if next_item_size <= pr {
            // next item chains into this bin -> reward
            let slack = (pr - next_item_size) as f64;
            score -= 80.0 + slack.min(50.0);
        } else {
            // next item cannot follow here; penalize proportionally to waste
            let waste = (next_item_size - pr) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin when decent
    // fits exist, but allow it when residual would be tiny (good long-term)
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: item leaves (C - item) residual
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // fresh bin can also host next item
        }
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // discourage opening new bins mid-stream unless item is large
            score += 30.0 + 0.3 * (item_size as f64).max(0.0) * -1.0;
            score += 10.0 * (open_bins_count.min(20) as f64).sqrt();
        }
    }

    // Tight-fit reward: item nearly fills the bin
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.8 {
        score -= 50.0 * (fill - 0.8) * 5.0;
    }

    // Early stream: be slightly more willing to open bins / keep flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress);

    // Prefer bins with residuals close to the item (minimize fragmentation)
    let diff = (bin_residual - item_size) as f64;
    score += 0.1 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 120.0;
    }

    // Medium dead space (11..=25) mildly penalized since it rarely fits future items.
    if post_residual >= 11 && post_residual <= 25 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferating bins.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If the next item would fit into the residual this placement creates,
        // opening a fresh bin is less costly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 15.0;

    // Lookahead: if this placement leaves room for the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 3.0;
    }

    // Slight preference for larger residuals early in the stream (keeps options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nr).abs();

        // Perfect 2-step chain: next item exactly fills residual
        if post_residual == next_item_size {
            score -= 40.0;
        } else if pr > nr {
            // Next item fits inside post_residual; reward tight chains
            score -= 15.0 * (nr / pr) - 0.3 * gap;
        } else {
            // Next item won't fit here; penalize dead space relative to next item
            score += 0.25 * gap;
        }

        // Coupling with mean residual: bins far below mean residual are "tight" bins;
        // prefer using them when the chain is good, avoid wasting them otherwise
        let tightness = mean_residual - pr;
        if tightness > 0.0 {
            score -= 0.15 * tightness; // tighter than average: good to fill
        } else {
            score += 0.10 * (-tightness); // looser than average: deprioritize slightly
        }

        // Penalize post_residuals that are too small to ever host typical items
        if pr > 0.0 && pr < 10.0 {
            score += 8.0;
        }
    } else {
        // Last item: just fill the fullest-usable bin (minimize waste)
        score -= 10.0;
    }

    // Last-chance bin: strongly favor placing here to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Discourage opening new bins when good open bins exist
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0;
    }

    // Late in stream: prioritize closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<=10).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // perfect closure bonus
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward gap penalty
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            score += 5.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Global state: many open bins -> encourage filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 6.0 * pressure * tightness;

    // Mean residual coupling: bins far below mean residual are "wasted" fills,
    // bins above mean residual are good targets.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate logic: only attractive when current bin fit is terrible
    // (large post_residual) or bin is empty-capacity candidate itself.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin grows with how many bins are already open
        // and shrinks with how bad the best existing fit would be.
        let badness = (post_residual as f64) / (bin_capacity as f64);
        score = 45.0 + 10.0 * pressure - 30.0 * badness;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with a big follow-up item
        }
    }

    // Time horizon: early in stream, be conservative about fragmenting;
    // late in stream, squeeze tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    // Base: tight fit preferred (small post_residual), with non-linear shaping
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly; later, tolerate spread to keep bins reusable
    let coupling = 1.0 - 0.35 * progress * (1.0 - progress) * 4.0; // dips mid-stream
    score *= coupling.max(0.5);

    // Penalize large dead space quadratically
    score += 12.0 * norm_post * norm_post * cap;

    // Reward fitting into an existing bin vs opening a new one
    if bin_residual != bin_capacity {
        score -= 6.0 + 8.0 * norm_item;
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among multiple options, prefer the fullest bin (small residual)
        score += 3.0 * (mean_residual - post) / cap;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 10.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 4.0 * norm_item;
    }

    // Slight penalty for many open bins late in the stream
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual ----
    // Residuals in small residue classes (mod 10) are "reusable" dead space:
    // future small items (1..100) frequently land on them. Reward those classes.
    let r = post_residual;
    let class = r % 10;
    let harmonic_bonus: f64 = match class {
        0 => 14.0,           // exact decade residual: highly reusable
        1 | 2 | 3 => 9.0,    // near-decade: still attractive
        4 | 5 | 6 => 4.0,    // middling
        7 | 8 => 1.0,        // poor
        _ => 3.0,            // 9: nearly a decade, mild reward
    };
    score -= harmonic_bonus;

    // Integer-division thresholds: residual that can hold "large" items (>=50)
    // is valuable dead space; residual that fits nothing common is waste.
    if r >= 50 {
        score -= 6.0;
    } else if r < 10 && r > 0 {
        // unusable sliver under the minimum item size -> penalize
        score += 8.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        if next_item_size <= r {
            // this bin can also host the next item: strong chain reward,
            // scaled by how snugly the next item nests in the residual
            let snug = 1.0 - (r - next_item_size) as f64 / cap;
            score -= 10.0 + 8.0 * snug;
        } else if next_item_size > r && r > 0 {
            // next item cannot use the leftover: leftover becomes dead space
            score += 3.0;
        }
    }

    // ---- Last-chance logic ----
    if fitting_bins_count == 1 {
        // this is the only bin that fits; opening a new bin wastes this space
        score -= 12.0;
    } else if fitting_bins_count > 3 {
        // plenty of alternatives: we can afford to be picky about tightness
        score += 1.5;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Fresh empty bin: neutral-ish baseline. Attractive only when the item
        // is large (small residual left) or no open bin fits well.
        let frac = item_size as f64 / cap;
        score = 55.0 - 30.0 * frac;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // fresh bin also chains to next item
        }
        return score;
    }

    // ---- Tightness: reward near-perfect fills ----
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // ---- Fill-rate pressure over the stream ----
    // Late in the stream, prefer consolidating into fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    // ---- Open-bin pressure: with many open bins, discourage spreading ----
    if open_bins_count > 4 {
        score += 0.6 * (open_bins_count.min(20) as f64).sqrt();
    }
    // Slight pull toward bins whose residual matches the mean (balanced closing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small for typical
    // future items (<= 10) are essentially unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    } else if post_residual <= 35 {
        score += 4.0;
    } else {
        // Large usable residual is good: reward tight-but-roomy fits.
        score -= 6.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 8.0; // would create fresh dead space
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few open bins, opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to what open bins can absorb (poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 35.0 + pressure * 4.0;
        // If no other bin fits, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild stream-progression tilt: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0;

    // Mean-residual coupling: if open bins are already mostly empty,
    // avoid spreading into new bins.
    if bin_residual != bin_capacity && mean_residual > bin_capacity as f64 * 0.6 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness;

    // Reward near-perfect fills hard.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that no future item (>= min size 1) can use well:
    // small leftover slivers are only useful if next item fits them.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits in the leftover: bonus proportional to how snug.
            let snug = 1.0 - ((post_residual as f64 - nx) / cap).max(0.0);
            score -= 10.0 * snug;
        } else {
            // Leftover unusable by next item: penalize proportionally.
            score += 0.15 * post;
        }
        // Chain bonus: if this item AND next item together fit snugly now.
        if item + nx <= residual {
            let pair_slack = residual - item - nx;
            score -= 8.0 * (1.0 - pair_slack / cap);
        }
    } else {
        // Last item: strongly prefer zero-waste placements.
        score += 0.3 * post;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate handling: mild penalty so existing bins win on decent fits,
    // but attractive when item is large relative to capacity (poor future packability)
    // or when many open bins already carry large mean residual.
    if is_new_bin {
        score += 25.0; // base cost of opening a bin
        // Large items pack better in fresh bins.
        score -= 20.0 * (item / cap);
        // If existing bins are fragmented (high mean residual vs this fit), new bin ok.
        score -= 6.0 * (mean_residual / cap).min(1.0);
        // Late in stream, prefer consolidating into open bins.
        score += 10.0 * t;
        // Many open bins: discourage adding more.
        score += 1.5 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Slight bonus for using already-open bins, scaled by how full they are.
        score -= 4.0 * (1.0 - residual / cap);
    }

    // Global fragmentation pressure: when mean residual is low (bins nearly full),
    // prioritize squeezing items into them.
    score += 5.0 * (1.0 - (mean_residual / cap).min(1.0)) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic tightening late in stream
    let mut score = pr * (1.0 + 1.5 * progress * progress) + 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Perfect fit bonus (smooth, not piecewise)
    score -= 25.0 * (1.0 - norm_pr).powi(8);

    // Dead-space penalty: residual too small for any plausible item (1..100)
    score += 15.0 * (1.0 - (pr / 10.0).min(1.0)) * (1.0 + progress);

    // Lookahead coupling: reward leaving room for next item, penalize near-miss
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 20.0 * (-diff / 15.0) * (1.0 + progress);
        score += 10.0 * (pr / nxt.max(1.0) - 1.0).abs().min(1.0);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidation
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += crowd * (mean_residual - pr).max(0.0) * 0.5;

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 18.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by which item
    // classes (out of 1..=100) it can still host.
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit: exact fill, ideal
    } else {
        // Fraction of remaining item classes that fit into the leftover.
        let usable_frac = pr as f64 / cap;
        // Dead-space penalty grows super-linearly for small unusable leftovers
        // (residuals that can host only few classes).
        let class_deadness = 1.0 - usable_frac;
        score += 40.0 * class_deadness * class_deadness;
    }

    // Lookahead coupling: penalize leftovers smaller than the next item
    // (wasted capacity for the known future demand), reward leftovers that
    // can host it with room to spare.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64) < nxt && pr > 0 {
            score += 25.0 * (nxt - pr as f64) / cap;
        } else if pr >= next_item_size {
            // leftover still fits next item: reward tighter co-packing
            score -= 12.0 * (1.0 - (pr as f64 - nxt) / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a bin should only win when the current fit
    // is poor. Give it a mid-range score so bad fits (high post_residual /
    // dead space) lose to it, but good fits beat it.
    if bin_residual == bin_capacity {
        score = 0.35 * cap + 0.10 * mean_residual + 8.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference to consolidate into fewer bins as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64).log2().max(0.0);

    // Tie-break: prefer bins whose residual is already below the mean
    // (tighter bins get filled first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post-residual gaps are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0; // post residual likely dead for next item
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (keeps options balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: only attractive when no open bin fits well or bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 70.0 - poor_fit - 2.0 * crowding.min(20.0);
        // Prefer new bin late in the stream where consolidation matters less.
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits the post-residual
    // exactly or nearly, heavily favor this bin (chain packing).
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 150.0 - gap as f64 * 8.0;
            } else {
                // next item fits but leaves slack: mild reward
                score -= 40.0 - gap as f64 * 0.5;
            }
        } else {
            // next item cannot fit in the leftover: penalize big leftovers
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average slack is good (tight packing).
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Penalize waste relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize slightly so we only open new bins when
    // open bins are genuinely bad fits; relax as stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 - progress * 30.0;
        // If next item is large and current item is small, a fresh bin is
        // more attractive (keeps room for big items).
        if next_item_size > 60 && item_size < 30 {
            score -= 60.0;
        }
        // Many open bins with low mean residual: opening fresh is fine.
        if open_bins_count > 3 && mean_residual < 25.0 {
            score -= 40.0;
        }
    }

    // Mild scaling with fill ratio to prefer fuller bins overall.
    score *= 1.0 + (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize dead space that cannot plausibly host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size as f64 {
            score += 0.55 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size as f64 {
            // Bin remains useful for the lookahead item: reward.
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidation.
    let crowding = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 1.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: penalize leaving residual far from the mean
    // (prefer balanced residual profiles across open bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.12 * dev;

    // Time horizon: early in the stream, be pickier about waste (many items to come);
    // late in the stream, tolerate imperfect fits to avoid opening needless bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.35 * post_residual as f64;
    score -= progress * 8.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let waste_now = (bin_capacity - item_size) as f64;
        score = 30.0 + waste_now * (0.6 - 0.5 * desperation) - 20.0 * desperation;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual, with a non-linear polynomial shaping
    // that flattens tiny residuals (already-good fits) and punishes mid-range waste.
    let x = pr / cap;
    let base = x * x * (3.0 - 2.0 * x); // smoothstep-like in [0,1]

    let mut score = 10.0 * base + 0.5 * pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, be greedy (fill existing bins tightly); late, tolerate spreading.
    let coupling = (1.0 - progress) * (pr * pr) / cap;
    score += 2.5 * coupling;

    // Penalize post_residual that wastes space relative to the mean residual,
    // with a smooth saturating interaction.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.01;

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress + 0.5);
    }

    // Lookahead: reward if the next item fits the post-residual, smoothly.
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let tight = (next_item_size as f64 / cap).min(1.0);
        score -= 4.0 * fits * tight;
    } else {
        // Last item: strongly prefer minimal post_residual.
        score -= 3.0 * (1.0 - x);
    }

    // New-bin candidate: mildly discourage opening new bins when alternatives exist,
    // scaled by how many bins already fit the item.
    if bin_residual == bin_capacity {
        let alt = (fitting_bins_count as f64).max(1.0);
        score += 5.0 * (1.0 - 1.0 / alt) + 2.0 * (1.0 - progress);
    }

    // Slight penalty for large open-bin count (encourage consolidation early).
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residues divisible by small
    // "harmonic" divisors (2,4,5,10) are more likely to be filled by
    // future items drawn from a mixed-size stream.
    let r = post_residual;
    let harmony_bonus: f64 = if r == 0 {
        -60.0 // perfect fit: strongest reward
    } else if r % 10 == 0 {
        -22.0
    } else if r % 5 == 0 {
        -14.0
    } else if r % 2 == 0 {
        -8.0
    } else {
        6.0 // odd residue: dead-space risk
    };
    score += harmony_bonus;

    // Integer-division thresholds on post_residual: classify leftover size.
    let class = r / 10; // 0..10 classes
    score += match class {
        0 => -30.0,                       // leftover <= 9: near-sealed bin
        1 | 2 => -18.0,                   // 10..29: small-item friendly
        3 | 4 => -10.0,                   // 30..49
        5 | 6 => 0.0,                     // 50..69: mediocre
        _ => 12.0,                        // 70..99: wasteful large hole
    };

    // Lookahead coupling: reward if next item fits into the post residual
    // (chained packing), penalize if next item barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 10.0 + 20.0 * (nxt / cap);
        } else if next_item_size <= bin_residual {
            score += 8.0; // next item would force another bin if placed here
        }
        // Harmonic match: next item shares a divisor class with post residual
        if next_item_size % 10 == r % 10 && r > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad or stream
    // is early and mean residual across bins is already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (post_residual as f64) / cap; // = 1 - item/cap for new bin
        score = cap - 15.0 * (1.0 - progress)
            + if post_residual >= 20 { 25.0 } else { 0.0 }
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 }
            + 10.0 * (mean_residual / cap).min(1.0);
    }

    // Slight preference for fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 200.0 * (10 - post_residual) as f64;
        } else if post_residual < 20 {
            score += 40.0;
        } else if post_residual <= 30 {
            score += 15.0;
        }
    } else {
        // Perfect fit is highly rewarded.
        score -= 300.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheap.
    let pressure = (open_bins_count as f64).sqrt() * 5.0;
    score -= pressure * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0; // blocks the next item
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // more attractive late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 + progress * 60.0 - pressure * 0.5;
        if mean_residual < item_size as f64 {
            score -= 40.0; // open bins are too full; new bin is good
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact/very tight lookahead fit.
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Exact match bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If next item cannot fit after placement, penalize dead space left behind.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 30.0;
    }

    // Penalize small unusable post-residual (dead space) unless lookahead matches.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 15.0;
    }

    // Prefer bins whose residual is above mean (keep balanced bins for future).
    if (bin_residual as f64) < mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when other bins already fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 20.0;
        // Even worse if next item is small enough to share the new bin awkwardly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 5.0;
        }
    }

    // Early in stream, mild preference to spread items across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
