pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic polynomial in normalized post_residual
    let mut score = 2.0 * norm_pr + 1.5 * norm_pr * norm_pr;

    // Smooth coupling with stream progress: late in stream, tighter packing matters more
    score *= 1.0 + 0.8 * progress * (1.0 - norm_pr);

    // Lookahead bonus: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 2.5 * (-gap / 20.0) * (1.0 - progress);
    }

    // Last-chance bin: penalize slightly to prefer using it when no alternative
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Penalize deviation from mean residual (keeps residual spread balanced)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Mild penalty for too many open bins relative to progress
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small remainders are good (tight fit)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits: remainder classes via modulo arithmetic on capacity
    let rem_class = post_residual % 10;
    score -= (10 - rem_class) as f64 * 0.5; // remainders near multiples of 10 are reusable

    // Penalize dead space that nothing can fill (items >= 1, so tiny residuals are dead)
    if post_residual < 10 {
        score += 15.0 * (1.0 - post / 10.0);
    }

    // Harmonic pairing: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another remainder: partial reward
            let next_post = post_residual - next_item_size;
            score -= 10.0;
            score += (next_post % 10) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 5.0 + (next_item_size as f64 - post) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residual close to item size (best-fit flavor)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += fit_gap * 20.0;

    // New-bin candidate handling: opening a new bin is only attractive when
    // current item is large and no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin
        score += 55.0;
        // discount if item is huge (would leave unusable space in any partial bin)
        if item_size >= 70 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
        // as stream matures, slightly discourage bin proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    } else {
        // reward filling existing bins, more when many bins are open
        score -= open_bins_count as f64 * 0.5;
        // reward being below mean residual (consolidating fuller bins)
        score -= (mean_residual - post) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps (< 10) are unusable
    // for typical items, so penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Perfect fits are golden.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits proportionally to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when few
    // alternatives exist, but allow opening new bins when current bins fit poorly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 15.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (consolidating space into fewer, fuller bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: only attractive when all open bins would leave
    // large dead space, otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 35.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead fit: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Also reward near matches to the lookahead item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + diff);
    }

    // Penalize creating dead space far from mean residual (fragmentation risk).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Penalize leaving a residual too small to ever be useful (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild preference for tighter bins (small residual relative to capacity).
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Slight penalty for opening a new bin when plenty of open bins exist.
    if bin_residual == bin_capacity {
