}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small waste is good, but only if it doesn't strand space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Penalize dead space: post_residual too small to hold any future item.
    if post_residual < 10 && post_residual > 0 {
        score += 6.0 + 0.3 * post_residual as f64;
    }

    // Lookahead: if the next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // Bonus for exact chain fit.
            let chain = (post_residual - next_item_size) as f64;
            score -= 3.0 * (1.0 - chain / bin_capacity as f64);
        } else if next_item_size > bin_residual {
            // Next item won't fit here regardless; mild reward for conserving this bin's space.
            score -= 1.0;
        } else {
            // Placing here breaks the next item's fit: penalize.
            score += 4.0 + 0.05 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate logic: only attractive when item is large relative to capacity
    // and current open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 10.0; // default cost of opening a new bin
        score -= 14.0 * big_item * (0.5 + 0.5 * crowding.min(3.0) / 3.0);
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 2.0; // new bin leaves room for next item
        }
    }

    // Time horizon: early in the stream, be conservative with tight fits (keep bins flexible);
    // late in the stream, maximize packing density.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * fit_ratio;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Global residual coupling: prefer bins with residual below mean (tighten crowded bins).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (favor consolidation);
    // late in stream, penalize residual growth more strongly.
    let progress_coupling = 1.0 - 0.8 * progress * (1.0 - progress) * 4.0; // dips mid-stream
    score *= progress_coupling.max(0.4);

    // Smooth dead-space penalty: residual too small to be useful
    let deadness = ((pr / 10.0) - 1.0).abs();
    score += 12.0 * (1.0 / (1.0 + (pr / 10.0).powi(2)));

    // Reward tight fit relative to mean residual state
    let mean_gap = (mean_residual - pr) / cap;
    score -= 6.0 * mean_gap;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let slack_after_next = (pr as f64 - next_item_size as f64) / cap;
        score -= 10.0 * fits_next * (1.0 - slack_after_next.abs());
        score += 4.0 * (1.0 - fits_next) * progress;
    }

    // Mild penalty for bin proliferation
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

