        score -= 5.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits
    if bin_residual == bin_capacity {
        let tight_exists = mean_residual < item_size as f64 + 5.0;
        if tight_exists && open_bins_count > 0 {
            score += 30.0; // discourage new bin when decent fits exist
        } else {
            score -= 5.0 * (open_bins_count.min(10) as f64) / 10.0;
        }
        // Early stream: new bins are cheap-ish; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins below mean residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Capacity fraction penalty for very large leftover chunks when bin nearly full
    if cap_frac > 0.7 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
