        score += 30.0;
        // If item is large relative to capacity, a new bin is more acceptable.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If no open bin is tight (mean residual high), opening a new bin is less costly.
        score -= 0.2 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If the next item could chain into the fresh bin, soften the penalty.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: residuals below the minimum item size are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Many fitting bins: prefer the tightest, discourage wasteful choices.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).ln().max(0.0) * (1.0 - fit_ratio);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (poor fit elsewhere) or late in the stream when fragmentation dominates.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_alternatives = fitting_bins_count == 0
            || (fit_ratio < 0.5 && post_residual > 40);
        if poor_alternatives {
            score -= 20.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            // Discourage opening new bins when existing ones suffice.
            score += 45.0 + 8.0 * open_bins_count as f64;
        }
        // Early stream: opening bins is cheap and preserves flexibility.
        if progress < 0.3 {
            score -= 10.0;
        }
        // Late stream: avoid opening bins unless really necessary.
        if progress > 0.8 {
            score += 12.0;
        }
    }

    // Lookahead: if the next item would fit nicely into the post-residual,
    // reward this placement; penalize if next item is stranded.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 18.0; // chains two items perfectly
            } else {
                score -= 6.0 * (1.0 - gap as f64 / 100.0);
            }
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0; // next item would need another bin anyway
        }
    }

    // Global state coupling: when mean residual is large, prefer using
    // bins with residual far from the mean to balance the pool.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for larger residual bins when item is large.
    if item_size > 50 {
        score -= 0.08 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap; // 0..1 residual fraction after placement

    // Base: prefer small post residual, with non-linear (quadratic) tightening
    let mut score = pr * (1.0 + 0.9 * fit_frac * fit_frac);

    // Smooth polynomial coupling of residual fraction with stream progress:
    // early on, tolerate larger leftovers; late, tighten aggressively.
    let progress_tighten = 1.0 + 1.2 * progress * (1.0 - 0.5 * progress);
    score *= progress_tighten;

    // Dead-space penalty: cubic growth of unusable space (nothing smaller than item can fit)
    let dead = ((pr - 1.0).max(0.0) / cap).powi(3);
    score += 60.0 * dead * (1.0 + progress);

    // Lookahead: reward bins whose post residual can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - ((pr - nxt) / cap); // 1 when perfect next fit
            score -= 8.0 * snug * snug;
        } else {
            // next item won't fit here: mild penalty scaled by shortfall
            let gap = (nxt - pr) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild preference for consolidating into already-open bins vs. new bin
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless item is huge relative to capacity
        let big = item_size as f64 / cap;
        score += 18.0 * (1.0 - big * big) + 10.0 * progress;
    } else {
        // existing bin: reward spreading load when mean residual is high
        let mr = mean_residual / cap;
        score -= 5.0 * mr * (1.0 - mr);
    }

    // Slight preference for bins that are already fairly full (harmonic-like term)
    let used_frac = 1.0 - fit_frac;
    score -= 6.0 * used_frac * used_frac * used_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fills are gold.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: leftovers that no plausible item (1..=100) can use well.
    // post_residual in 1..10 is nearly unusable -> penalize strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Modulo-classes on post_residual: multiples of common item sizes are reusable.
    let reusable_mods: [u32; 5] = [10, 20, 25, 50, 100];
    let mut reusable = false;
    for m in reusable_mods.iter() {
        if post_residual % m == 0 && post_residual > 0 {
            reusable = true;
            break;
        }
    }
    if reusable {
        score -= 25.0;
    }

    // Harmonic fraction of capacity remaining: prefer bins whose residual is a
    // large fraction of capacity (they stay flexible), penalize tiny fractions.
    let frac = pr / cap;
    if frac < 0.2 && post_residual > 0 {
        score += 40.0 * (0.2 - frac);
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            // left over after next item too
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score += 30.0; // would create fresh dead space
            } else {
                score -= 15.0;
            }
        }
        // If next item cannot fit here anyway, mild penalty for wasting this slot.
        if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If the item leaves a bad residual in any bin, opening new is better.
        if post_residual < 15 && item_size < bin_capacity {
            score -= 45.0;
        }
        // Early in stream, bins are cheap to open; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If many open bins, discourage spreading.
        score += 2.0 * open_bins_count as f64;
    }

    // Prefer tighter fits generally: subtract relative fit quality.
    score -= 20.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64).min(1.0));

    // Slight preference for bins tighter than the mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward exact match with lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: more open bins -> discourage spreading, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Prefer bins tighter than average (below-mean residual = well-filled bin).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New empty bin candidate: neutral-ish baseline so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits: penalize leftover after that hypothetical placement
            let chain_residual = post_residual - next_item_size;
            if chain_residual == 0 {
                score -= 45.0;
            } else if chain_residual < 10 {
                score -= 20.0;
            } else {
                score += chain_residual as f64 * 0.3;
            }
        } else {
            // next item cannot use the residual: dead space risk
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Favor bins whose residual is tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless no open bin fits well
    if bin_residual == bin_capacity {
        score += 60.0;
        // less penalty late in stream or when few bins open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild preference to fill already-open bins when many are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Empty new-bin candidate: penalize mildly so it's chosen only when
    // open bins are poor fits, but allow it when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
    }

    // Time horizon: late in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    // Global residual pressure: if mean residual is high, prefer reusing bins.
    score -= 5.0 * (mean_residual / bin_capacity as f64);

    // Prefer fuller bins (smaller residual) generally.
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: reward tight fits (low post residual)
    let mut score = pr as f64;

    // Smooth non-linear penalty for wasted space, coupled with stream progress:
    // dead space matters more later in the stream (less opportunity to fill it).
    let waste = norm_pr * norm_pr;
    score += 40.0 * waste * (0.5 + progress);

    // Coupling with mean residual: prefer bins whose residual deviates smoothly
    // from the mean in a non-linear way (consolidate similar residuals).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by progress via a saturating quadratic).
    let last_chance = (fitting_bins_count == 1) as f64;
    score -= 60.0 * last_chance * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward bins whose post residual can still fit the next item,
    // penalize those that barely cannot (smooth quadratic on the shortfall).
    if next_item_size > 0 {
        let shortfall = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 25.0 * shortfall * shortfall;
        let fits_next = (next_item_size as u32 <= post_residual) as f64;
        score -= 8.0 * fits_next * (1.0 - norm_pr);
    }

    // New-bin candidate: it has post_residual == capacity (norm_pr == 1).
    // Penalize opening new bins, but less when few bins fit or residual is fragmented.
    let is_new = (bin_residual == bin_capacity) as f64;
    let fragmentation = (mean_residual / cap).min(1.0);
    score += is_new * (30.0 + 50.0 * (1.0 - fragmentation) * (1.0 - (fitting_bins_count as f64).recip()));

    // Mild reward for using existing bins as stream progresses (avoid bin explosion).
    score -= 5.0 * (1.0 - is_new) * progress * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "composable" classes (multiples of small sizes) are more reusable.
    let cap = bin_capacity as f64;
    let fill = 1.0 - (post_residual as f64) / cap; // fraction filled

    // Reward tight packing (small post_residual), strongly for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common small
    // item sizes (10, 20, 25, 50) remain usable -> subtract bonus.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 3.0; }

    // Harmonic class via integer division thresholds on post_residual.
    let class = post_residual / 15; // coarse class 0..6
    score += class as f64 * 2.5;

    // Lookahead: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item exactly consumes the leftover.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to the upcoming item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins
    // are poor fits; less penalty late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 - 4.0 * progress;
        // Opening a new bin is more attractive if mean residual is large/fragmented.
        if mean_residual > 30.0 { score -= 3.0; }
    }

    // Prefer filling bins that are already relatively full (best-fit flavor).
    score -= fill * 5.0;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable for any
    // future item (min size 1..100 stream, but tiny gaps rarely match) — hard penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that only fit very small items are near-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward residuals that can still host a "typical" next item: coupling with lookahead.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // This bin becomes dead space for the known next item.
            score += 10.0;
        }
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow filling loosely.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Deviation from mean residual: prefer bins that tighten the residual spread.
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.abs();

    // Late in the stream, prefer tighter packing to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.3);

    // Brand-new empty bin: only attractive when residual fit is poor elsewhere —
    // give it a mild default penalty so it wins only via its zero post_residual
    // (which already scores 0) against bins leaving large loose gaps.
    if bin_residual == bin_capacity {
        score += 8.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small post_residual that cannot host typical items.
        if post_residual < 10 {
            score += 50.0;
        }
        // 2-step lookahead: reward bins whose leftover can host the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > 0 {
            // Next item won't fit here; penalize proportionally to the mismatch.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin unless the item is large relative to it.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.4 * (bin_capacity - item_size) as f64;
    }

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively when many bins compete.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 12.0;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (ni - post_residual as f64).abs() < 1.0 {
            score -= 40.0;
        } else if ni <= post_residual as f64 {
            score -= 10.0 * (1.0 - ni / cap);
        } else {
            // Next item won't fit here; penalize leaving awkward mid-size gaps.
            score += 8.0 * (post_residual as f64 / cap);
        }
    }

    // Global state coupling: with many open bins, prefer filling existing ones.
    let open_f = open_bins_count as f64;
    score += (open_f - 3.0).max(0.0) * 2.0;

    // Mean residual context: if this bin is far below mean residual, it's a poor filler.
    score += ((mean_residual - bin_residual as f64) / cap).max(0.0) * 20.0;

    // Time horizon: early in stream, mildly prefer new bins to keep flexibility;
    // late in stream, consolidate into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) - 10.0 * t;
    } else {
        score -= 5.0 * t;
    }

    // Nonlinear nudge toward perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap; // 0..1 residual fraction
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Smooth non-linear coupling: quadratic residual shaping with progress interaction
    score += 40.0 * norm_post * norm_post * (1.0 + progress);
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - progress);

    // Dead-space penalty: small post_residual that cannot fit typical items
    if post > 0.0 {
        score += 15.0 * (-post / 12.0).exp();
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
        score -= 30.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 20.0 * (nxt / cap) * (1.0 - norm_post);
        } else {
            score += 10.0 * ((nxt - post) / cap);
        }
    }

    // Mean residual divergence: prefer bins whose residual deviates favorably
    score += 5.0 * (mean_residual - post).abs() / cap;

    // New-bin candidate handling: penalize opening a new bin, but allow it late
    // or when the item is large relative to residual (poor fit elsewhere)
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 45.0 * (1.0 - progress) + 10.0;
        score -= 35.0 * norm_item * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Smooth open-bin pressure: more open bins -> mild preference to fill existing
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how it decomposes modulo common item sizes
    let pr = post_residual;
    let mod10 = (pr % 10) as f64;
    let mod25 = (pr % 25) as f64;
    let mod50 = (pr % 50) as f64;
    score += 0.6 * mod10 + 0.4 * mod25 + 0.5 * mod50;

    // Small dead space is bad: penalize residuals that are hard to fill
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 60.0;
    }

    // Residual classes by integer division thresholds
    let div10 = pr / 10;
    if div10 >= 1 && div10 <= 3 {
        score += 8.0 * (4 - div10) as f64; // awkward mid-range residual
    } else if div10 >= 7 {
        score -= 10.0; // large residual is flexible
    }

    // Lookahead: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0;
            // harmonic match: next item divides residual nicely
            if pr % next_item_size == 0 {
                score -= 15.0;
            }
            let diff = pr - next_item_size;
            if diff > 0 && diff < 10 {
                score += 12.0; // leaves another tiny dead space
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 40.0 - 12.0 * pressure;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Progression: late in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (mean_residual / cap);

    // Prefer bins tighter than average (best-fit bias with harmonic twist)
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (below the minimum size of 1, but practically
    // below a "useful gap" threshold) are heavily penalized.
    let useful_threshold = 10.0f64.min(bin_capacity as f64);
    if (post_residual as f64) < useful_threshold && post_residual > 0 {
        score += 40.0 + 2.0 * (useful_threshold - post_residual as f64);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item
    // (k=2 lookahead exploitation).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Gap cannot hold next item: mild penalty scaled by gap smallness.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage closing out bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.6 + 0.4 * (1.0 - progress));

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Alignment with mean residual: bins far below the mean residual create
    // fragmented outliers; penalize deviation.
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let spread_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = bin_capacity as f64 - 8.0 + spread_pressure.min(20.0);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is clearly right
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
