        score += 10.0 + 6.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But allow a new bin if mean residual across open bins is very small.
        if mean_residual < item_size as f64 {
            score -= 14.0;
        }
    } else {
        // Reward using bins with residual close to item size (best-fit flavor).
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.05 * fit_gap;
        // Slight bonus for consolidating into low-residual bins as stream ends.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

