pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction of post_residual with stream progress:
    // late in the stream, dead space becomes more costly (quadratic coupling)
    let progress_coupling = 1.0 + 0.8 * progress * progress;
    score += 0.6 * pr * norm_pr * progress_coupling;

    // Reward low post residual more aggressively when it's very small (smooth saturating term)
    score -= 10.0 * (-(pr / 15.0)).exp();

    // Penalize bins that leave residual too small for typical future items
    // (smooth penalty via logistic on normalized residual)
    let dead_zone = 1.0 / (1.0 + (-(norm_pr - 0.2) * 25.0)).exp();
    score += 8.0 * dead_zone;

    // Lookahead: if next item fits into post_residual, reward this bin smoothly
    if next_item_size > 0 {
        let fits_next = (post_residual >= next_item_size) as i32 as f64;
        let tight_next = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap).abs();
        score -= 4.0 * fits_next * tight_next.max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild penalty for opening a new bin when many bins are open and residual is large
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
        // but allow new bin late in stream if item is large
        score -= 3.0 * (item_size as f64 / cap) * progress;
    }

    // Slight preference for bins below mean residual (consolidating small leftovers)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

