        score += (10 - r) as f64 * 0.8;
    } else if post_residual > 0 {
        // residue 0: reusable by multiples of 10 — reward
        score -= 4.0;
    }

    // Harmonic fraction classes: post residual in (0,10] is nearly unusable (min item 1..10)
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain
        } else if next_item_size <= post_residual {
            let rem2 = (post_residual - next_item_size) % 10;
            if rem2 == 0 {
                score -= 12.0; // leaves a reusable residue class
            } else {
                score += rem2 as f64 * 0.5;
            }
        } else {
            // next item cannot follow into this bin: mild penalty proportional to gap
            let gap = (next_item_size - post_residual) % 10;
            score += gap as f64 * 0.4;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a fresh bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 20.0;
        // but if current bin would leave bad residue, new bin becomes attractive
        if post_residual == 0 {
            score -= 55.0; // fresh bin keeps full flexibility for future harmonics
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: later in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 3.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (post_f - mean_residual).max(0.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

