            }
        }
        // Next item does NOT fit this bin's post residual: penalize leaving a gap next item can't use
        else {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize creating unusable dead space (post_residual too small for any item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Tight fits are good: reward low post_residual relative to capacity
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64
        } else {
            0.0
        };
        // Default penalty so open bins are preferred; relax when many bins and poor fits
        let mut penalty = 40.0;
        if open_bins_count > 3 {
