    let mx = mean_residual / cap;
    score += 0.2 * (x - mx).abs() * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight openness early
    if bin_residual == bin_capacity {
        score = 0.9 + 0.6 * progress + 0.1 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction classes. Leftovers in the "small residue" classes
    // (0..=10, 11..=20, 21..=30) are increasingly dead space; large leftovers
    // are reusable, so reward them progressively.
    let post_i = post_residual;
    let class = post_i / 10; // harmonic class 0..10
    let class_penalty = match class {
        0 => 40.0,               // near-perfect fill: big reward (subtract)
        1 => 15.0,
        2 => 5.0,
        3 => 0.0,
        4 => -5.0,
        5 => -10.0,
        6 => -15.0,
        _ => -20.0,              // roomy leftovers are valuable
    };
    score -= class_penalty;

    // Exact-fill bonus
    if post_i == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_i {
            score -= 60.0;
        } else if next_item_size <= post_i {
            // next item fits but leaves another residue: mild reward scaled
            // by how tight the secondary fit is
            let secondary = post_i - next_item_size as f64;
            score -= 20.0 * (1.0 - secondary / cap);
        } else {
            // next item cannot use this residue: penalize proportionally to
            // how stranded the leftover would be
            score += 10.0 * (post / cap);
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin mildly unattractive so
    // only genuinely bad fits (large post residual elsewhere) beat it.
    if bin_residual == bin_capacity {
        score += 30.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Spread-aware term: if this bin's residual is far below the mean
    // residual, using it balances the bin set (reduces fragmentation).
    let residual_f = bin_residual as f64;
    let deviation = (residual_f - mean_residual) / cap;
    score -= 8.0 * deviation;

    // Many open bins: discourage leaving many half-empty bins; prefer
    // filling the emptiest ones less, tighten the fullest ones more.
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln() * (1.0 - residual_f / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever hold a meaningful item
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual <= 20 {
        score += 120.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 25.0; // next item likely can't follow here
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins
    score += open_bins_count as f64 * 3.0;

    // Mean residual coupling: prefer bins whose residual deviates from the mean
    // (consolidating large residuals together keeps small ones usable)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // Slight progression pressure: late in stream, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 150.0 - 50.0 * progress; // new-bin candidate penalty, easing late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with super-linear penalty
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // 2-step lookahead: reward post_residual close to next_item_size
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 2.5
        };
        // exact match (post_residual == next_item_size) gets big reward
        if post_residual == next_item_size {
            score -= 35.0;
        } else {
            score += gap * 0.35;
        }
        // if next item fits exactly after this placement, strong bonus
        if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
        // avoid leaving residual that no plausible item (>=1) can use well
        if post_residual < next_item_size && post_residual < 10 {
            score += 12.0; // tiny dead space penalty
        }
    }

    // Relative to mean residual: prefer bins with above-average residual (keep small-residual bins for nothing)
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless current open bins are very full / crowded
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).ln() * 4.0;
        score += 45.0 - avg_fill * 30.0 - pressure;
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for fuller bins overall
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin, but relax late in the stream.
    if is_new_bin {
        score += 40.0 * (1.0 - 0.5 * progress);
    }

    // Reward last-chance bins heavily (avoid wasting a bin that would otherwise die).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Reward tight fits: normalized fill ratio bonus.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement;
    // if post-residual is small but nonzero and next item can't use it, penalize dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item: any placement is fine; prefer fullest fit.
        score -= 10.0;
    }

    // Mild preference for bins with residuals below the mean (consolidate small leftovers).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Penalize leaving tiny unusable fragments (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight penalty per open bin to discourage bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: late in the stream, dead space matters more
    let late = progress * progress;
    score *= 1.0 + 0.6 * late * norm_pr;

    // Penalize bins that deviate strongly from the mean residual (keeps residual spread small)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * late;
    }

    // Lookahead: reward if next item fits well in the post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = pr - ns;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 6.0 * (ns - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.5 * open_bins_count as f64 * norm_pr * progress;

    // New-bin candidate: neutral-ish score anchored to remaining space
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) - 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting dead space (integer division thresholds).
    let q = post_residual / 10;
    // Penalize dead space superlinearly within each class (waste grows faster than linear).
    score += (q as f64) * (q as f64) * 2.0;

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward
    // (this bin is a perfect two-item chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            let next_leftover = post_residual - next_item_size;
            // Reward small leftovers after the chained placement (harmonic class of leftover).
            let nq = next_leftover / 10;
            score -= (10.0 - nq as f64) * 3.0;
            if next_leftover == 0 {
                score -= 50.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize if we leave awkward gap classes.
            score += (post_residual as f64).min(50.0) * 0.3;
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer tighter bins among many candidates (tightness pressure).
    let tightness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= tightness * 20.0;

    // Modulo-class logic: residuals in awkward classes (e.g. 1..=9 gaps that few
    // item sizes 10..80 can fill) are penalized more.
    let awkward = post_residual > 0 && post_residual < 10;
    if awkward {
        score += 25.0;
    }

    // Early in the stream, allow more bins to stay flexible; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Mild penalty relative to mean residual: avoid spreading waste evenly.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: give it a neutral-ish baseline so it only wins when
    // all open bins are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small relative post residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio);

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: prefer existing bins when many bins are open.
    if bin_residual != bin_capacity {
        score -= 8.0 + open_bins_count as f64 * 1.5;
    } else {
        // New bin candidate: penalize unless it offers a clearly better placement.
        score += 10.0;
        // If current item plus lookahead would nest nicely in a fresh bin, soften penalty.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Lookahead synergy: if the post residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 20.0;
        } else {
            score -= 6.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing) early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * (1.0 - progress) * 0.3;
    }

    // Penalize leaving large residuals late in the stream (less chance to fill them).
    score += fit_ratio * progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of post_residual to next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;

        // Perfect chain: item fits exactly, next item fills remainder
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small slack: good chain
        if next_item_size <= post_residual {
            score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
        }
        // Next item cannot use this bin's remainder: penalize dead space more
        else {
            score += 6.0;
        }
    }

    // Penalize residual that is unusable for typical items (very small dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless it enables a better 2-step chain
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let chain = (bin_capacity - item_size - next_item_size) as f64;
            score -= 18.0 - chain * 0.3;
        }
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0;
        // extra reward if next item fills the bin nearly completely afterward
        let post2 = post_residual as u32 - next_item_size;
        if post2 <= 10 { score -= 4.0; }
    } else if next_item_size > 0 {
        // penalize leaving residual that next item cannot use (dead space risk)
        score += 2.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Prefer bins with residual below mean (consolidate small leftovers)
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Penalize creating tiny unusable residuals (< 10) unless bin nearly full
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // New-bin candidate: open a fresh bin only when current item is large
    // and no good fit exists (high post_residual means item is small -> bad to open)
    if bin_residual == bin_capacity {
        score += 15.0 - 0.15 * (item_size as f64);
        // early in stream, opening new bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // if many open bins already, discourage spreading
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear decay of residual value with stream progress:
    // residual space becomes less valuable (less penalizing) as stream advances.
    let decay = 1.0 - 0.35 * progress * progress;
    score *= decay;

    // Quadratic dead-space penalty for very small post-residuals (unusable gaps).
    let pr_norm = pr / cap;
    score += 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Reward tight fits: subtract based on fill ratio, weighted by progress.
    let fill = item_size as f64 / cap;
    score -= 8.0 * fill * fill * (0.5 + 0.5 * progress);

    // Lookahead coupling: smooth interaction between post-residual and next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        let s = gap.tanh();
        // If next item fits into post-residual, reward; else penalize smoothly.
        score -= 5.0 * s;
        score += 3.0 * s * s;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure toward consolidating into few bins when many are open.
    let open_norm = (open_bins_count as f64 / 20.0).tanh();
    score -= 2.0 * open_norm * (1.0 - pr_norm);

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // toward smaller residuals (pack fuller bins first).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev;

    // New-bin candidate handling: make an empty bin mildly unattractive early,
    // increasingly acceptable late or when it would fit the next item well.
    if bin_residual == bin_capacity {
        let nx_fit = if next_item_size > 0 {
            (next_item_size as f64 / cap).tanh()
        } else {
            0.0
        };
        score += 6.0 * (1.0 - progress) - 4.0 * nx_fit * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward residuals that are "nice" targets ---
    // Residuals divisible by common item sizes (10,20,25,50) are more likely reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony: f64 = 0.0;
        for m in [10u32, 20, 25, 50].iter() {
            if pr % m == 0 { harmony += 6.0; }
        }
        if pr % 5 == 0 { harmony += 2.0; }
        // Perfect fit gets a strong bonus
        if pr == 0 { harmony += 25.0; }
        score -= harmony;
    } else {
        score -= 30.0; // exact fill is ideal
    }

    // --- Dead-space penalty: tiny residuals that can't fit the minimum item (1..=100) ---
    if pr > 0 && pr < 5 {
        score += 12.0;
    }

    // --- Capacity fraction classes for the item itself ---
    let frac = item_size as f64 / bin_capacity as f64;
    if frac > 0.5 {
        // Large item: prefer placing it, keep small bins for small items
        score -= 8.0 * frac;
    } else if frac < 0.2 {
        // Tiny item: penalize wasting a fresh bin on it
        if bin_residual == bin_capacity {
            score += 10.0;
        }
    }

    // --- Integer-division threshold coupling with lookahead ---
    if next_item_size > 0 {
        // If the next item fits exactly in the post residual, big reward
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            // Quotient class: how many copies of next item could fit after placement
            let q = pr / next_item_size.max(1);
            score -= 3.0 * q as f64;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot class
            let overshoot_class = (next_item_size - pr) / 20; // 0,1,2,3...
            score += 2.0 * overshoot_class as f64;
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // --- New-bin candidate: only attractive when open bins are crowded ---
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // If mean residual across open bins is small, opening fresh bin is fine
        score += 20.0 * (1.0 - pressure);
        // But if many bins are open and residuals are fragmented, prefer consolidation
        score += 0.5 * open_bins_count as f64 * pressure;
        // Late in the stream, avoid opening new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    } else {
        // Existing bins: mild preference for tighter fits relative to mean
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 4.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (post_residual < min item ~1..10)
    // are the worst outcome; push them far above any normal placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // medium dead space: mild penalty scaled by gap size
        score += 0.5 * (25.0 - post_residual as f64);
    } else {
        // reward tight-but-usable fits
        score -= 0.3 * (post_residual as f64 - 25.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but if no existing bin fits well, allow opening when item is large
        if item_size > 60 && fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Lookahead: if next item could use the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.6 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the useful direction (use up outlier-large residuals).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score -= 0.2 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when next item exactly fills the post-residual (perfect 2-step match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack.min(40.0);
    }

    // Penalize dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post-residual against mean residual: prefer bins left tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for opening new bins late in the stream when reuse is possible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 15.0 * progress;
    }

    // Reward tight fits generally.
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill of the bin after placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 25.0;
        } else if (post_residual as i64 - next_item_size as i64) < 0 {
            // Next item won't fit here; slight penalty if residual becomes useless.
            if post_residual < 10 {
                score += 10.0;
            }
        } else {
            // Partial lookahead fit: small reward proportional to leftover.
            let leftover = post_residual - next_item_size;
            score -= 12.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is poor (large post_residual relative to capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; the penalty shrinks as the fit elsewhere
        // gets worse and as the stream progresses (fewer chances to consolidate).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress;
        // If the item would leave a large residual in the new bin, discourage more.
        if post_residual > bin_capacity / 2 {
            score += 20.0;
        }
    } else {
        // Prefer bins whose residual is below the mean (consolidating fuller bins),
        // keeping emptier bins available for future large items.
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Mild penalty when many bins are open: encourage consolidation.
        score += (open_bins_count.min(20) as f64) * 0.5;
    }

    // Time-horizon modulation: early in the stream, be more selective about
    // tight fits (future items may pair better); late, grab tight fits fast.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste shaping: penalize large residuals quadratically-cubically
    let post_norm = post / cap;
    score += 12.0 * post_norm * post_norm * (1.0 - post_norm);

    // Tight fits rewarded (small post_residual), with smooth interaction with progress
    let tightness = 1.0 - post_norm;
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item (smooth lookahead coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let miss = ((nx - post) / cap).max(0.0);
        score += 10.0 * miss * miss * (1.0 - 0.5 * progress);
        // Reward bins whose post-residual nicely matches the next item
        let match_term = 1.0 - ((post - nx) / cap).abs();
        score -= 6.0 * match_term.max(0.0) * match_term;
    }

    // Last-chance bonus: smooth exponential-ish reward when few fitting bins
    let fit_frac = if open_bins_count > 0 {
        fitting_bins_count as f64 / open_bins_count as f64
    } else { 1.0 };
    score -= 9.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (0.4 + 0.6 * progress);

    // Mild pressure toward consolidating into fewer bins as stream progresses
    score += 0.05 * progress * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near mean (smooth quadratic)
    score += 0.02 * (post - mean_residual) * (post - mean_residual) / (cap * cap);

    // New-bin candidate: penalize slightly so we prefer existing bins unless waste is large
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 partition dead space.
    let post = post_residual as i64;
    let residue = post % 10;
    let class = post / 10; // integer-division harmonic band: 0..9

    // Dead-space penalty grows super-linearly for small unusable remainders.
    // Residuals in [1,9] are nearly worthless; penalize hard, with a special
    // premium against the "odd" residues 1,3,7 (hardest to refill exactly).
    let residue_penalty = match residue {
        0 => -6.0,                       // perfect fit: strong reward
        5 => 0.5,                        // half-decade residue: mildly useful
        2 | 4 | 6 | 8 => 1.5,            // even residues can pair with even items
        _ => 5.0,                        // odd residues: ugly dead space
    };
    score += residue_penalty;

    // Harmonic band bonus: mid-band residuals (class 2..4, i.e. 20..49 left)
    // are the most reusable; very low class (near-full) or very high class
    // (near-empty) are less valuable.
    let band_bonus = match class {
        0 => 4.0,
        1 => 1.0,
        2 | 3 => -3.0,
        4 => 0.0,
        _ => 2.0,
    };
    score += band_bonus;

    // Lookahead coupling: harmonic match between post_residual and next item.
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if nxt > post {
            // Next item cannot fit here anyway; dead space is "locked" for one
            // step. Penalize proportionally to how much it overshoots mod 10.
            let over = nxt - post;
            score += 1.0 + (over % 10) as f64 * 0.2;
        } else {
            // Next item fits: reward exact-harmonic matches, reward closeness.
            if post % nxt == 0 {
                score -= 5.0; // next item exactly tiles the remainder
            } else if post - nxt <= 10 {
                score -= 3.0; // near-perfect sequential fill
            } else {
                score -= (post - nxt) as f64 * 0.05;
            }
        }
    } else {
        // Last item: only perfect closure matters.
        if post == 0 { score -= 10.0; }
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin
    // wastes this bin's remaining space entirely; strongly favor using it
    // unless the resulting dead space is truly pathological (residue 1..4).
    if fitting_bins_count == 1 {
        score -= 8.0;
        if post > 0 && post < 5 { score += 6.0; }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if (bin_residual as f64 - cap).abs() < f64::EPSILON {
        // Prefer reusing open bins when they leave decent residuals;
        // only open a new bin when all open bins would be wrecked.
        // Base cost of opening a bin, modulated by stream progress and load.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 12.0 * (1.0 - progress);
        // If many bins are open with high mean residual, opening is cheaper
        // than fragmenting further? No: high mean residual means space exists.
        score += mean_residual * 0.15;
        // Few open bins -> opening is natural early in bin lifecycle.
        if open_bins_count <= 2 { score -= 6.0; }
        // Perfect-fit seekers: if item is large, new bin gives clean slate.
        if item_size >= 70 { score -= 4.0; }
    }

    // Mild global pressure: when many bins are open, tighten packing
    // (prefer bins that close out).
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.01;

    // Tie-break noise-free harmonic jitter based on step, keeps determinism.
    let phase = (step_index % 7) as f64;
    score += phase * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept the smallest plausible item (<= 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Penalize mid-range dead space that can only fit tiny items.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual is already low via base term,
    // add extra bonus for exact or near-exact packing).
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * 0.5 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count,
        // but allow it when item is large and no bin fits well.
        score += 30.0 + pressure;
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else {
        // Reward placing into existing bins as their count grows.
        score -= pressure.min(15.0);
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this placement (perfect pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 18.0;
        } else if gap < 10 {
            score -= 6.0;
        }
    }

    // Slight preference for bins with below-average residual (denser bins),
    // keeping loose bins available for future larger items.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(10.0) * 0.4;
    } else {
        score += (res - mean_residual).min(10.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect / near-perfect fits strongly
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a chained perfect placement -> very desirable
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 120.0;
        }
        // Penalize leaving a residual that the next item cannot use at all
        // (dead space relative to lookahead)
        if next_item_size > post_residual {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(30.0);
        }
    }

    // Compare residual against mean residual of open bins:
    // prefer bins with residual close to item size (tight fit relative to fleet)
    let mean_r = mean_residual.max(0.0);
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Fleet-relative adjustment: bins with above-mean residual are better
    // candidates for large items; below-mean residual bins should be
    // prioritized for small items to consolidate.
    let rel = bin_residual as f64 - mean_r;
    score -= 0.2 * rel * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible)
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 150.0;
    }
    if fitting_bins_count == 1 && post_residual > 60 {
        score += 40.0; // poor last-chance fit: mild penalty, may prefer new bin
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 90.0;
        // Exception: huge item with no good open fit
        if next_item_size > 0 && item_size >= 70 {
            score -= 60.0;
        }
    }

    // Early in stream: slightly favor consolidating into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(2.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that end completely or nearly full.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows superlinearly for tiny leftover slivers.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 2.0;
        }
        // Fractional fill reward: fuller bins preferred.
        score -= (item_size as f64 / bin_residual as f64) * 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.05;
    }
    // Penalize leaving a gap that no plausible future item (>=10) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more when
    // open bins exist and the stream is early/mid (amortization matters).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0;
        if fitting_bins_count > 0 {
            new_bin_penalty += 20.0;
        }
        // Late in the stream, opening fresh bins is cheap-ish; early it is costly.
        new_bin_penalty *= 1.0 - 0.5 * progress;
        // Many open bins with large mean residual => prefer filling those instead.
        if mean_residual > item_size as f64 {
            new_bin_penalty += (mean_residual - item_size as f64) * 0.1;
        }
        score += new_bin_penalty;
    }

    // Slight preference for bins with below-average residual (tighter bins first),
    // keeping looser bins available for larger future items.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    // Mild diversification pressure: with many open bins, favor consolidation.
    if open_bins_count > 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual (larger leftover = better)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, prefer tighter fits (penalize large residuals more strongly)
    let tightness = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 60.0 * progress * tightness;

    // Quadratic waste penalty scaled by progress
    score += 40.0 * progress * pr_norm * pr_norm;

    // Reward near-perfect fits smoothly
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm);

    // Lookahead coupling: reward if next item fits smoothly
    if next_item_size > 0 && pr >= next_item_size {
        let fit_frac = next_norm / (pr_norm + 1e-9);
        score -= 20.0 * fit_frac * (1.0 - fit_frac) * 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 15.0 * (1.0 - progress) * next_norm;
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Mean residual divergence penalty (avoid fragmenting)
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate handling: penalize slightly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo capacity fractions
    let pr = post_residual;
    let cls = (pr / 10) % 10; // integer-division class on residual
    match cls {
        0 => score -= 6.0,           // exact fill / tiny dead space is ideal
        1 | 2 => score -= 4.0,       // small dead space, still usable for tiny items
        3 | 4 | 5 | 6 | 7 => score -= 1.5, // mid-range residual
        _ => {}                       // large residual: no reward
    }

    // Reward if lookahead item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= pr {
        let gap = (pr - next_item_size) as f64;
        score -= 5.0 * (1.0 - gap / cap);
        if pr == next_item_size {
            score -= 6.0; // perfect two-item chain
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 2.0; // lookahead cannot follow here
    }

    // Penalize waste relative to mean residual spread
    let res_f = post_residual as f64;
    score += 0.3 * (res_f - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: neutral baseline; only attractive if all open fits are bad
    if bin_residual == bin_capacity {
        score += 4.0;
        if item_size > 60 {
            score += 3.0; // big items prefer fresh bins
        }
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (cap - res_f) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty proportional to how "wasted" it is.
            score += 40.0 * (1.0 - post_residual as f64 / 10.0);
        } else {
            // Usable leftover: mild reward for larger remaining space.
            score -= 0.05 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Tightness reward: fraction of the bin that gets filled now.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate handling: only attractive if no open bin fits well
    // (i.e., this bin is empty and the item is large relative to mean residual).
    if bin_residual == bin_capacity {
        // Baseline cost of opening a bin.
        score += 30.0;
        // But if the item is big and mean residual is small, a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 35.0;
        }
        // Late in the stream with a large item, prefer a fresh bin to avoid slivers.
        if progress > 0.7 && item_size > 50 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item would fit exactly into the post
    // residual, reward this placement strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit in the leftover: penalize creating dead space.
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward bins whose post_residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-chain: post_residual exactly matches next item -> huge reward.
            let exact = (post_residual == next_item_size) as i32 as f64;
            score -= 40.0 + 25.0 * exact;
        } else {
            // Next item can't follow here: penalize proportionally to dead space.
            score += 12.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Penalize leaving unusable dead space (post_residual smaller than min item size).
    if post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins with residual near the mean
    // (balanced usage), avoid dumping into already-tight or overly empty bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: keep it neutral-ish, slightly penalized so we only
    // open a new bin when existing bins score badly.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening bins is cheaper; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let waste_frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: subtract proportional to how well the item fills the bin
    score -= 30.0 * fill_frac * fill_frac;

    // Penalize dead space non-linearly: small residuals are fine, mid-range residuals
    // (hard to fill later) are heavily penalized
    if post_residual > 0 {
        let dead = waste_frac * (1.0 - waste_frac);
        score += 40.0 * dead * (1.0 - fill_frac);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * fill_frac;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * next_fit;
        } else {
            // Next item won't fit here; slight penalty proportional to how much we block
            score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open and mean residual is low, be conservative
    // (prefer existing bins); when mean residual is high, opening new bins is cheap-ish
    let mean_frac = mean_residual / bin_capacity as f64;
    score -= 10.0 * (1.0 - mean_frac) * fill_frac;
    score += 8.0 * mean_frac * waste_frac;

    // Time horizon: early in the stream, tolerate spreading (new bins); late in the
    // stream, pack tightly into existing bins
    score += 12.0 * (1.0 - progress) * waste_frac;
    score -= 12.0 * progress * fill_frac;

    // New-bin candidate handling: empty bin gets a baseline cost that grows with
    // open_bins_count (discourage proliferation) but shrinks if item is large
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).sqrt();
        score = 45.0 * open_pressure + 20.0 * (1.0 - fill_frac) - 10.0 * progress;
        // If no existing bin fits well, allow new bin more readily
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Progress coupling: late in the stream, tighten bins more aggressively
    let progress_coupling = 0.8 * progress * post * norm_post;
    score += progress_coupling;

    // Reward tight fits (small post_residual) increasingly with progress
    let tightness_reward = -(cap - post).max(0.0) * (0.15 + 0.35 * progress) * (1.0 - norm_post);
    score += tightness_reward;

    // Penalize dead space relative to mean residual (wasteful bins)
    score += 0.3 * (post - mean_residual).max(0.0);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if the next item could use the post-residual, reward leaving exactly that space
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 / (1.0 + gap * gap * 0.05);
        // Penalize blocking next item
        if post < next_item_size as f64 {
            score += 6.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: neutral-ish baseline, slightly favored early, penalized late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.5 * progress) + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small but reusable" classes (<=10, or exact decade multiples) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0; // nearly perfect, dead space negligible
    } else {
        let decade = pr / 10; // integer-division harmonic class
        // Reward residuals that are exact multiples of 10 (likely to fit future items)
        if pr % 10 == 0 {
            score -= 8.0 + 2.0 * decade as f64;
        }
        // Penalize awkward residuals: large but below the minimum item size band
        if pr < 20 {
            score += 15.0;
        }
        // Dead-space penalty grows super-linearly in the mid-range
        score += 0.05 * (pr as f64).powi(2) * 0.01;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            // Reward exact harmonic fits of the next item
            if slack % 10 == 0 {
                score -= 12.0;
            }
            score -= 10.0 + 0.1 * slack as f64;
        } else {
            // This bin becomes dead after placement
            score += 20.0 + 0.2 * (next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin; more so when many bins are open and fragmented
        score += 35.0 + 2.0 * open_bins_count as f64 * fragmentation;
        // Late in the stream, avoid spawning bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Exception: big items with no good fit deserve a fresh bin
        if item_size >= bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for tighter bins overall
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are heavily penalized.
    // A residual is "dead" if it is smaller than the minimum plausible item size (1..100 range),
    // and increasingly wasteful the smaller it gets relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits (small post_residual) superlinearly.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 20.0 * tightness * tightness;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; with few bins, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 25.0;
    }
    // Penalize if next item would be blocked by a tiny dead gap we create now.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // Mild progress term: later in the stream, be more conservative about
    // leaving awkward gaps (stream length effects).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if average residual across open bins is small,
    // this bin's leftover matters more; if mean residual is large, tolerate gaps.
    if mean_residual > 0.0 {
        let gap_ratio = post_residual as f64 / mean_residual;
        if gap_ratio > 1.5 {
            score += 8.0 * (gap_ratio - 1.5);
        } else if gap_ratio < 0.5 {
            score -= 6.0 * (0.5 - gap_ratio);
        }
    }

    // New-bin candidate (empty bin) baseline: opening a new bin should only win
    // when every open bin would create a dead gap. Give the empty bin a mild
    // penalty so it only wins when open bins are penalized more heavily.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the NEXT item exactly fills the post_residual,
    // this placement is a chain-perfect fit -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits in the leftover: mild reward proportional to tightness.
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * tightness;
        } else {
            // Next item would NOT fit in the leftover: penalize dead space,
            // worse when the leftover is small and unusable.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 120.0 * (1.0 - waste);
        }
    }

    // Reward bins tighter than the mean residual (good fits), penalize loose bins.
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it unattractive unless residuals elsewhere are tiny.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.3 * mean_residual;
    }

    // Late-stream urgency: prefer filling existing bins as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 25.0;

    // Slight penalty on very small leftovers that are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large waste relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * (bin_residual as f64 - post_residual as f64) * 0.5;

    // Penalize small dead space (unusable residual) more than large leftover.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is generally wasteful,
    // but attractive when open bins have poor fits (high mean residual spread)
    // or when the item is large and residuals are tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64;
        let mut new_bin_penalty = 15.0 + 20.0 * (1.0 - fill_ratio);
        if tight {
            new_bin_penalty -= 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            new_bin_penalty -= 8.0;
        }
        // Late in the stream, avoid opening bins unless really needed.
        new_bin_penalty += 10.0 * progress;
        // Many open bins with slack -> prefer reusing them.
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += new_bin_penalty.max(0.0);
    }

    // Prefer bins whose residual is close to mean residual (balanced usage),
    // slight preference for fuller bins otherwise.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild time adaptation: early on, be conservative (favor exact fits),
    // later, prioritize closing bins out (prefer smallest post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.6 * progress * norm_post + 0.4 * progress * progress);

    // Penalize residuals that become dead space relative to typical item sizes.
    let dead = (pr - item_size as f64).max(0.0) / cap;
    score += 25.0 * dead * dead;

    // Reward near-perfect fits smoothly (quadratic trough at post_residual ~ 0).
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (item_size as f64 / cap);

    // Last-chance bonus when few fitting bins remain.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins early in the stream.
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // Discourage opening new bins when a decent fit exists (new-bin candidate has max residual).
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual, but avoid perfect-fit obsession that wastes bins.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * pr;

    // Harmonic class of post_residual: dead space in low classes is very costly.
    // Class A: post_residual <= 10  -> nearly perfect, strong reward.
    // Class B: 10 < post_residual <= 30 -> usable by small items, mild reward.
    // Class C: post_residual > 30 -> dead space risk, penalty grows superlinearly.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score -= 6.0 + 0.10 * (30.0 - pr);
    } else {
        score += 0.05 * (pr - 30.0) * (pr - 30.0) / 10.0;
    }

    // Lookahead coupling: reward when next_item_size fits the post_residual exactly
    // or within a tight harmonic window; penalize when next item cannot use leftover.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            if slack <= 5.0 {
                score -= 18.0; // chain fit: excellent
            } else if slack <= 20.0 {
                score -= 8.0;
            } else {
                score += 0.08 * slack; // next item leaves more waste
            }
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: an empty bin has huge residual; discourage opening
    // a new bin unless current placement would create severe dead space.
    if bin_residual == bin_capacity {
        // Neutral base for new bin; it should lose to good fits, win over bad fits.
        score = 55.0 + 0.1 * open_bins_count as f64;
        // Late in stream, prefer filling existing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mean-residual coupling: if open bins are already loose on average, discourage
    // spreading items thin; favor bins tighter than the mean.
    if mean_residual > 0.0 {
        let diff = pr - mean_residual;
        score += 0.05 * diff;
    }

    // Modulo-class bonus: post_residual divisible into useful chunk sizes (10/20/25)
    // keeps future packing flexible.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 || r % 25 == 0 {
            score -= 4.0;
        } else if r % 5 == 0 {
            score -= 1.5;
        }
    }

    // Mild penalty on very tight bins already near full when other bins exist.
    if post_residual < 5 && open_bins_count > 1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size (1..=10)
    // are effectively unusable; penalize them heavily with a super-linear ramp.
    if post_residual > 0 {
        if post_residual <= 10 {
            // small unusable gap: bad, but at least the bin is "closed"
            score += 20.0 * (11.0 - post_residual as f64);
        } else if post_residual < 25 {
            // awkward mid-range gap likely to become dead space
            score += 12.0;
        }
    } else {
        // perfect fill: strong reward
        score -= 60.0;
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make opening a new bin attractive only when the current
    // item would leave a large residual that could serve the NEXT item well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // baseline cost of opening a new bin
        score += 45.0 + 3.0 * open_bins_count as f64;
        // if next item fits into the post_residual of this fresh bin, discount
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // late in the stream, avoid opening new bins unless necessary
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    } else {
        // lookahead synergy: reward placements whose residual can host the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 {
            // residual too small for next item: mild penalty for wasted space
            score += 8.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
    score -= 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;

    // 2-step lookahead: strongly reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            // Perfect chain fit: big bonus.
            score -= 25.0 * (1.0 - gap / 100.0);
            // Extra reward if the residual after the next item would also be small.
            let post2 = post - nxt;
            score -= 10.0 * (1.0 - post2 / 100.0);
        } else {
            // Next item can't use this residual: penalize dead space.
            score += 8.0 + 0.15 * (post - nxt);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize near-empty usage of a fresh bin unless it's the new-bin candidate.
    if bin_residual != bin_capacity && post_residual as f64 > 0.85 * bin_capacity as f64 {
        score += 20.0;
    }

    // New-bin candidate: mild penalty early, larger later (favor consolidation over time).
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
    }

    // Slight preference for bins with more residual overall when few bins open.
    if open_bins_count <= 2 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small unusable dead space: post_residual that no future item (>=1) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // post_residual too small for next item: mild penalty proportional to waste
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are mostly full
    // or the current item fits nothing well.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        // Late in stream or bins nearly full -> opening a new bin is cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 - 25.0 * mean_fullness - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Discard new-bin option if a perfect fit exists among open bins.
        if fit_ratio > 0.95 {
            score += 100.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    // into fuller bins (penalize bins far below the mean residual).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Time-horizon modulation: early in the stream, be conservative (keep large
    // residuals for future big items); late, fill greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.10 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear polynomial shaping (favor tight fits).
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize large residuals more.
    score += 12.0 * progress * norm_pr * (1.0 - norm_pr) * 4.0;

    // Reward filling a bin nearly exactly (dead-space penalty, quadratic).
    score -= 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (item_size as f64 / cap);

    // Mean-residual coupling: bins far below mean residual get slight preference to be filled.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post-residual, reward strongly; if it doesn't fit, penalize mildly.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * fit_quality;
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual ---
    // Class residuals into "harmonic" buckets via integer division thresholds.
    let r = post_residual;
    let class = match r {
        0 => 0,          // perfect fill
        1..=10 => 1,     // near-perfect (dead space mostly useless)
        11..=25 => 2,    // small-item friendly
        26..=50 => 3,    // mid-item friendly
        _ => 4,          // large-item friendly
    };

    // Reward perfect and near-perfect fills strongly.
    match class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 5.0,
        3 => score += 5.0,
        _ => {}
    }

    // --- Lookahead coupling: does the residual match the next item's class? ---
    if next_item_size > 0 && next_item_size <= r {
        // Next item fits exactly into this residual's harmonic slot.
        let gap = r - next_item_size;
        if gap == 0 {
            score -= 45.0; // chain of perfect fills
        } else if gap <= 10 {
            score -= 15.0;
        } else {
            score -= gap as f64 * 0.3;
        }
    } else if next_item_size > 0 && next_item_size > r {
        // Next item won't fit here: residual becomes dead space.
        score += r as f64 * 0.4;
        // If next item is huge, keeping big residuals is valuable.
        if next_item_size > 50 && r >= 40 {
            score -= 10.0;
        }
    }

    // --- Last-chance bonus: only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // New bin is attractive for large items or when the stream is early,
        // but discouraged late in the stream when open bins exist.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 40.0 * (1.0 - progress) + 25.0 * progress;
        if item_size >= 60 {
            score -= 20.0; // big items like fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0; // room for the pair
        }
    }

    // --- Modulo arithmetic on residual: prefer residuals in "nice" classes ---
    let m = r % 10;
    if m == 0 && r > 0 {
        score -= 8.0; // round residuals pair well with 10-multiple items
    } else {
        score += m as f64 * 0.5;
    }

    // --- Waste relative to mean residual ---
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Mild penalty for proliferation of bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 1000.0;
        }
        // Dead space that cannot fit the next item is wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 2.5 * (next_item_size - post_residual) as f64;
        }
        // Non-linear penalty on tiny gaps (worst kind of dead space).
        let gap = post_residual as f64;
        score += 20.0 * (-gap / 10.0).exp();
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented.
    if bin_residual == bin_capacity {
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
            score += 5.0; // discourage new bin when existing space suffices
        } else {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this is a chained perfect fit -> big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 - slack * 0.5;
        if slack == 0.0 {
            score -= 700.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving awkward dead space
        // that is too small to be useful (dead space below typical min item).
        let dead = post_residual as f64;
        if dead > 0.0 && dead < 10.0 {
            score += 150.0;
        }
    }

    // Reward tightening toward the mean residual (good consolidation),
    // penalize bins whose residual is already tiny relative to mean.
    let tightness = mean_residual - post_residual as f64;
    score += tightness * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New empty bin candidate: penalize mildly so we only open new bins
    // when no decent fit exists (post_residual here = full capacity).
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item is large and would leave little waste even in a
        // fresh bin, opening a new bin is fine.
        if item_size as f64 >= 0.75 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer closing bins out (less fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that nothing (>= 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize small unusable-ish leftovers
    if post_residual > 0 && post_residual < item_size {
        score += (item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // plenty of alternatives; prefer best-fit discrimination
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // late in stream, consolidate to avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early exploration mildly, penalize late heavily
        score += 15.0 + 40.0 * progress;
        if item_size >= 50 {
            score += 10.0; // big items should go in open bins if possible
        }
    } else {
        score -= 8.0 * (1.0 - progress);
    }

    // Global residual state: many open bins with high mean residual -> consolidate
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 5.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0);
        }
    }

    // Too many open bins: discourage opening new ones further
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * poly * cap * 0.01;
    // penalize small dead space more as stream progresses (wasted capacity is costlier late)
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);
    // reward near-perfect fits
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0 * (1.0 - norm_pr * 10.0);
    }
    // lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0;
    }
    // mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;
    // new-bin candidate: make it less attractive unless residuals are tight
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of 10 / small values) are preferred, since future items (1..100, unknown
    // distribution) are more likely to exploit them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always great
    } else {
        // residue class modulo 10: leftover that is a multiple of 10 is "harmonious"
        let class = pr % 10;
        score += class as f64 * 1.5;

        // small leftovers are more reusable than large dead space
        if pr <= 20 {
            score -= 10.0;
        } else if pr <= 40 {
            score -= 3.0;
        } else if pr > 70 {
            score += 8.0; // large leftover wastes this bin's potential
        }

        // integer-division thresholds: leftover exactly fitting next item is a jackpot
        if next_item_size > 0 && pr >= next_item_size {
            if pr == next_item_size {
                score -= 45.0;
            } else if pr - next_item_size <= 10 {
                score -= 18.0;
            } else {
                score -= 6.0;
            }
        } else if next_item_size > 0 {
            // next item cannot fit in the leftover we create -> dead space penalty
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless it is genuinely better
    if bin_residual == bin_capacity {
        score += 55.0;
        // early in the stream, new bins are cheaper; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 15.0;
        // many open bins already -> discourage proliferation
        score += open_bins_count as f64 * 0.8;
        // big items fill new bins more efficiently
        score -= item_size as f64 * 0.3;
    }

    // prefer tighter bins overall (waste-minimizing pressure vs mean residual)
    score -= (bin_residual as f64 - mean_residual) * 0.25;

    // capacity-fraction coupling: bins that become exactly half or full after placement
    if pr == bin_capacity / 2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Reward leaving a gap that can fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Pressure from number of open bins: prefer tighter bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual is already below the mean (well-packed bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin, scaled by stream progression.
    if bin_residual == bin_capacity {
        score += 35.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving large unusable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving below-average residual creates fragmentation.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item
    // is huge and would leave a hard-to-fill gap elsewhere.
    if bin_residual == bin_capacity {
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.6;
        let poor_fit = (post_residual as f64) < 15.0 && next_item_size > post_residual;
        if !(big_item && poor_fit) {
            score += 45.0;
        } else {
            score += 5.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins (keeps
    // flexibility); late in the stream, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a quadratic bonus.
    score -= 2.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(2) * 10.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the residual (capacity) can host the next item too,
    // or when existing bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let next_fits = next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64) >= 0.0;
        let mut new_bin_score = 40.0;
        if next_fits && next_item_size <= bin_capacity {
            new_bin_score -= 15.0;
        }
        // Early in the stream, opening bins is cheap; late, prefer filling existing bins.
        new_bin_score += progress * 20.0;
        // If open bins are crowded on average, a new bin is more acceptable.
        new_bin_score -= (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
        score += new_bin_score;
    }

    // Mild preference for bins below mean residual (keeps residuals balanced).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: post_residual scaled by stream progress
    score += 12.0 * (pr / cap) * (pr / cap) * (1.0 + progress);

    // Reward tight fits (small post_residual) with smooth quadratic reward
    score -= 30.0 * (-pr / 20.0).exp();

    // Penalize dead space relative to mean residual across open bins
    score += 0.35 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post-residual smoothly reward, else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: smooth penalty increasing with progress and open bins
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Mild congestion term: fewer fitting bins -> slightly favor this bin
    score += 3.0 * (fitting_bins_count as f64).powi(2) / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo capacity quarters
    let quarter = (bin_capacity / 4).max(1);
    let residue = post_residual % quarter;
    let class = post_residual / quarter; // 0..4 harmonic class

    // Penalize dead space in the lowest harmonic class (tiny unusable slivers)
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 25.0;
    }

    // Reward exact fills
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post_residuals that are "harmonic" (divisible by common item sizes)
    if post_residual > 0 {
        let mut harm = 0.0;
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                harm += 8.0;
            }
        }
        score -= harm;
    }

    // Class-based bonus: middle classes (residual 25..75) are most reusable
    score -= match class {
        1 => 6.0,
        2 => 10.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Penalize small in-class residue (fragmentation within a class band)
    score += residue as f64 * 0.15;

    // Lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.2 * next_fit;
        if (post_residual % next_item_size.max(1)) == 0 {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        score += 8.0; // next item can't use this bin's remainder
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: keep it competitive only when open bins are congested
    if bin_residual == bin_capacity {
        let congestion = (open_bins_count as f64) * (mean_residual / cap);
        score = 0.5 * cap - 0.3 * congestion;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if post_residual > 60 {
            score += 10.0; // discourage fresh bins when streams are near end
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Mild global pressure: prefer dense bins when many bins are open
    score += mean_residual * 0.05 - (open_bins_count as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that likely cannot host any future item.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 60.0; // perfect packing, unusable gap is fine
    } else if (post_residual as f64) < 20.0 {
        score -= 25.0; // near-dead gap, mildly good
    } else if (post_residual as f64) < 35.0 {
        score += 8.0; // awkward mid gap
    }

    // Reward exact / tight fits relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Penalize leaving a gap that could have fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // keeping a useful gap open is good
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // creating a gap too small for the lookahead item
    }

    // New-bin candidate handling: only open a new bin when this is the last
    // chance bin or all fits are terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // last-chance bin should be used instead
        } else {
            score += 40.0 + 3.0 * open_bins_count as f64; // prefer existing bins
        }
    }

    // Open-bin pressure: spreading across many bins is costly.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (consolidating space).
    let dev = mean_residual - post_residual as f64;
    score -= 0.3 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good (already the base).

    // Aggressive 2-step lookahead: strongly reward a bin whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item fills the bin completely.
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits here too: reward proportionally to tightness.
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit after this placement: penalize a bit,
            // scaled by how much dead space would be left.
            score += 0.15 * gap;
        }
    }

    // Penalize post_residual that is small but unusable (typical item sizes 10..80,
    // but interface allows 1..100): residual below the minimum item size is dead space.
    if post_residual < 1 {
        score += 5.0;
    }

    // Penalize large post_residual relative to mean residual across open bins:
    // wasting a very roomy bin on a small item is bad unless lookahead rewards it.
    score += 0.08 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin mildly, more so early on
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 - 10.0 * progress - 0.5 * open_bins_count as f64;
        // If lookahead chains perfectly into a fresh bin, allow it.
        if next_item_size > 0 && item_size + next_item_size as u32 == bin_capacity {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 12.0 * waste;
        } else if post_residual >= next_item_size {
            // Reward bins that can still accommodate the lookahead item
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize bins whose residual deviates far below the mean residual (fragmentation signal)
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.35 * dev;
    } else {
        score += 0.1 * dev; // slightly favor larger-than-mean residual bins
    }

    // Time horizon: early in the stream, be more willing to open new bins (penalize tight reuse less);
    // late in the stream, pack tightly to close bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * tightness;
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins: encourage consolidation
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate handling: make empty bin attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 30.0 || (next_item_size > 0 && post_residual < next_item_size);
        if poor_fit {
            score -= 30.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), mildly convex
    let mut score = pr * (1.0 + 0.5 * x);

    // Smooth non-linear coupling with stream progress:
    // early on, waste is cheaper; late in stream, waste is heavily penalized
    let progress_coupling = 1.0 + 0.8 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: cubic smooth term subtracting when post_residual is small
    let tightness = (1.0 - x).clamp(0.0, 1.0);
    score -= 6.0 * tightness * tightness * tightness;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for spreading across many fitting bins
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.1;

    // Lookahead: if next item could exactly fill post_residual, big reward
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - gap / cap).clamp(0.0, 1.0);
        // penalize leaving space next item cannot use at all
        if next_item_size as f64 > pr {
            score += 2.0 * progress;
        }
    }

    // New-bin candidate: smooth logistic-style preference to open new bins
    // when existing residuals are small relative to item size
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + (-6.0 * (x - 0.25)).exp());
        score = pr * (1.0 - openness) + 30.0 * openness * (0.3 + 0.7 * progress);
        // discourage hoarding new bins early
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue mod 10 buckets
    let class = post_residual % 10;
    // Small residues mean post-residual is close to a "round" gap -> dead space risk
    if class == 0 {
        score -= 12.0; // perfect harmonic alignment (residual is multiple of 10)
    } else if class <= 3 {
        score += 6.0 + 2.0 * class as f64; // awkward tiny dead space
    } else if class >= 8 {
        score -= 4.0; // large usable gap remains
    }

    // Integer-division threshold: post_residual relative to capacity quarters
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 15.0; // bin becomes near-useless dead space
    } else if post_residual < quarter {
        score += 5.0;
    } else if post_residual >= 2 * quarter && post_residual < 3 * quarter {
        score -= 3.0; // half-ish bin remains, very reusable
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chain two items: excellent
            // bonus if next item exactly harmonizes with post residual
            if post_residual - next_item_size < 10 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here anyway; penalize small leftovers more
            if post_residual < next_item_size / 2 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral-ish score so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55
            - (open_bins_count as f64).ln() * 4.0
            - (item_size as f64 / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin useful
        }
        if fitting_bins_count <= 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
    }

    // Prefer filling fuller bins early vs late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Slight pull toward bins with residuals near the mean (balance)
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Mid-range awkward gaps (10..20) also mildly penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    }

    // Perfect fit for the lookahead item: strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual cannot host the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last chance: only this bin can fit the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins below mean residual (filler bins) to consolidate space.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when current fit is bad or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheapen late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 40.0 * progress - open_bins_count as f64 * 0.5;
        // A new bin is good if the item is large relative to capacity (fewer future gaps).
        if item_size >= 50 {
            score -= 15.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0; // room for lookahead pairing
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact-ish match of next item into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect two-item fill is gold
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 30.0;
            }
        } else {
            // next item cannot follow here: penalize proportionally to wasted space
            score += 0.35 * (post_residual as f64 - nxt).abs();
        }
    } else {
        // last item: prefer tightest fit only
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are scarce space;
    // using them for a poor fit is costly, so penalize leaving big post_residual there.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel > 1.0 {
            score += 0.5 * (rel - 1.0) * mean_residual.min(50.0);
        } else {
            score -= 0.4 * (1.0 - rel) * mean_residual.min(50.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bins are nearly full or item is large
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let urgency = (post_residual as f64) / bin_capacity as f64;
        // new bin starts with full residual; make it unattractive when open bins are loose
        score += 20.0 * (1.0 - pressure).max(0.0) + 10.0 * urgency;
        // but if item is huge and nothing fits well elsewhere, new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Slight late-stream tightening: prefer tight fits as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that cannot fit typical small items (residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item won't fit here; penalize wasted potential.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Global pressure: many open bins -> discourage spreading; few bins -> encourage consolidation.
    let pressure = (open_bins_count as f64) / ((step_index.max(1) as f64) + 1.0);
    score += 2.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (fill emptier space first
    // keeps tight bins available for small items), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 6.0 * dev * (0.5 + progress);

    // Late stream: prefer minimizing fragmentation more aggressively.
    if progress > 0.7 {
        score += 0.15 * post_residual as f64;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it's chosen only
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills (minimize post_residual); later, tolerate slack
    // to keep bins balanced. Polynomial interaction term.
    let coupling = pr_norm * pr_norm * (1.0 - progress) * 40.0;
    score += coupling;

    // Cubic smoothness penalty for tiny dead space, damped by progress
    let dead = (1.0 - pr_norm).min(1.0);
    score -= dead * dead * dead * 25.0 * (1.0 - 0.5 * progress);

    // Reward near-perfect fit smoothly
    if pr == 0 {
        score -= 30.0;
    }

    // Last-chance bin bonus (smooth sigmoid-like via fitting count)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins
    // are already open and slack is spread out; smooth in open_bins_count.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score += 12.0 + 10.0 * openness + 15.0 * (1.0 - progress);
        // If next item is small, new bin is attractive
        if next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Lookahead: penalize leaving residual that next item can't use
    if next_item_size > 0 && pr > 0 {
        let waste = if (pr as u32) < next_item_size {
            pr - next_item_size as f64
        } else {
            0.0
        };
        score += waste * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals divisible by common item
    // granularities (5, 10, 20, 25) are more reusable later.
    let h5 = (post_residual % 5 == 0) as f64;
    let h10 = (post_residual % 10 == 0) as f64;
    let h20 = (post_residual % 20 == 0) as f64;
    let h25 = (post_residual % 25 == 0) as f64;
    score -= 4.0 * h5 + 6.0 * h10 + 4.0 * h20 + 6.0 * h25;

    // Dead-space penalty: small non-harmonic leftovers are wasted.
    if post_residual > 0 && post_residual < 10 && h5 == 0.0 {
        score += 12.0;
    }

    // Lookahead coupling: does the next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect or near-perfect wrap with the next item is gold.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap % 10 == 0 {
                score -= 10.0;
            } else if gap < 10 {
                score += 4.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            // Leftover can't host next item: mildly penalize tiny leftovers.
            if post_residual < next_item_size.min(10) {
                score += 6.0;
            }
        }
    }

    // Integer-division thresholds on bin fill fraction.
    let fill_quartile = (bin_capacity - post_residual) * 4 / bin_capacity; // 0..3
    score -= 3.0 * fill_quartile as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the stream is young or open
    // bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 25.0 - 20.0 * progress + 2.0 * crowded;
    }

    // Tie-breaker: prefer tighter fits via normalized waste.
    score += (post_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead);
    } else if dead < 20.0 {
        // gaps 10..19 can hold small items but are still wasteful
        score += 6.0 * (20.0 - dead);
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward fitting item into a bin whose residual matches next item too (lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space that next item cannot use
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 3.0 * pressure;

    // New-bin candidate: penalize unless current bins are mostly full / tight
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let tight = mean_fill / bin_capacity as f64;
        if tight < 0.7 {
            score += 80.0; // keep using open bins while they have room
        } else {
            score -= 15.0 * (tight - 0.7); // allow fresh bin when others are nearly full
        }
    }

    // Early in stream, be slightly more willing to open bins (builds good structure)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
