pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 && !is_new_bin {
        score -= 60.0;
    }

    // Lookahead coupling: residual after placement relative to next item
    if !is_new_bin {
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let res = post_residual as f64;
            if res > 0.0 && res < nxt {
                // dead space that cannot host the next item
                score += 0.6 * (nxt - res);
            } else if res >= nxt {
                // residual can still host the lookahead item: mild reward
                score -= 0.25 * (res - nxt).min(30.0);
            }
        }
        // Small leftover fragments are wasteful
        if post_residual > 0 && post_residual < 10 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a bin for a small item; allow it for large items
    if is_new_bin {
        score += 12.0 + 0.35 * (bin_capacity - item_size) as f64;
        // late in the stream, consolidate into existing bins more aggressively
        score += 10.0 * progress;
        // if many bins are open and mean residual is large, discourage yet another bin
        score += 0.05 * open_bins_count as f64 + 0.1 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference for filling bins that are already relatively full
    if !is_new_bin {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear emphasis on tight fits.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Quadratic penalty on dead space that grows with stream progress (late items should pack tighter).
    score += 18.0 * norm_pr * norm_pr * (0.4 + progress);

    // Reward bins whose residual is close to the item (smooth coupling of residual and item size).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 10.0 * (-gap / cap).exp();
    }

    // Mean-residual coupling: prefer bins below mean residual (fill emptier space efficiently).
    score += 6.0 * (norm_pr - mean_residual / cap);

    // Mild pressure to reuse open bins as their count grows.
    score += 2.0 * (open_bins_count as f64).ln() * norm_pr;

    // New-bin candidate: penalize opening a bin unless residual waste elsewhere is severe.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;
    let class = pr % 10; // residue class mod 10
    let half_class = (pr % 25) as i64;

    // Reward residuals that land in "harmonic" classes (multiples of 25/50)
    if pr % 50 == 0 {
        score -= 6.0; // perfect half-capacity alignment
    } else if pr % 25 == 0 {
        score -= 3.0; // quarter alignment
    } else if pr % 10 == 0 {
        score -= 1.5; // decile alignment
    }

    // Penalize awkward small residues that are hard to fill later
    if class >= 1 && class <= 9 && pr > 0 {
        score += 0.35 * (10 - class) as f64;
    }

    // Integer-division threshold: post_residual in [1,9] is near-dead space
    if pr > 0 && pr <= 9 {
        score += 8.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if (next_item_size as i64) <= pr {
            score -= 4.0; // chain placement possible
            // extra reward if next item also lands in a good class
            let nxt_pr = pr - next_item_size as i64;
            if nxt_pr >= 0 && nxt_pr % 25 == 0 {
                score -= 2.0;
            }
        } else {
            score += 2.5; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / cap;
        let threshold = 0.45 + 0.25 * t;
        if pressure < threshold {
            score -= 1.0 + 3.0 * (threshold - pressure);
        } else {
            score += 4.0 + 6.0 * (pressure - threshold);
        }
        // prefer new bins early when few bins open
        if open_bins_count > 8 {
            score += 2.0;
        }
    }

    // Mild preference for tighter fits overall
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 2.0 * tightness;

    // Mean residual coupling: penalize bins far from the mean (keep balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable gaps are worse than large leftovers.
    // A residual that cannot plausibly hold a future item is "dead".
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item + 9 {
        score += 60.0 * (1.0 + (min_item + 9 - post_residual) as f64);
    }

    // Non-linear waste term: penalize mid-range wasted capacity quadratically.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frac * frac;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits
    // or the system is under pressure.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 + 2.0 * pressure;
        // If the next item could combine well with the current one in a fresh bin,
        // make a new bin slightly more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Reward using a bin whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
        // Mild penalty for spreading across too many open bins.
        score += 0.5 * open_bins_count as f64;
        // Lookahead: if the next item fits the post residual, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover exactly matches the next item (2-step perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
