    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 20.0 + 0.5 * mean_gap;
        if fitting_bins_count > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    }

    // Late in the stream, prefer compacting into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (tighter bins get filled first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // With several options, prefer emptier bins to consolidate load.
        score += 6.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Lookahead coupling: reward leaving room compatible with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact compatibility is gold; near-miss is worthless.
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 45.0;
            } else if slack <= 5.0 {
                score -= 10.0;
            } else {
                score += 3.0 * slack / bin_capacity as f64;
            }
        } else {
            // Post-residual too small for next item: dead space penalty.
            score += 8.0 * post_residual as f64 / bin_capacity as f64;
        }
    } else {
        // End of stream: minimize waste aggressively.
        score += 10.0 * waste_frac;
    }

    // New-bin candidate logic: opening a bin is only attractive when
    // the item is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalty baseline; discount when item is big or many bins fit poorly.
        score += 25.0 - 30.0 * item_frac - 8.0 * (crowding - 1.0).max(0.0) - 10.0 * progress;
        // Never open a new bin for a tiny item early on.
        if item_frac < 0.4 {
            score += 30.0;
        }
    }

    // Mild time-horizon shaping: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 12.0 * progress * (1.0 - waste_frac);

    // Fragmentation guard: penalize residuals in awkward mid-range.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
