        } else {
            score -= 10.0 * gap * (1.0 - gap); // next item fits snugly
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Slight preference for bins tighter than the mean residual.
    score += 0.3 * (mean_residual - pr);

    // Mild penalty for spreading across many bins when residual is large.
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
