    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: harmonic class match reward
            let nclass = next_item_size / (bin_capacity / 8).max(1);
            let pclass = post_residual / (bin_capacity / 8).max(1);
            if nclass == pclass {
                score -= 25.0; // exact class pairing
            } else {
                score -= 10.0;
            }
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Dead space penalty scaled by how much next item overshoots
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.6;
            // Small residues that can't fit next item are worse
            if post_residual < 10 {
                score += 20.0;
            }
        }
    } else {
        // Last item: minimize waste aggressively
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score = cap * 0.9;
        if fitting_bins_count <= 1 && next_item_size > 0 && post_residual == cap {
            score -= 25.0; // no alternative, fresh bin acceptable
        }
        if item_size >= bin_capacity * 7 / 10 {
            score -= 20.0; // big items fine in fresh bins
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // reserve fresh bin for a pairing
        }
    } else {
        // Prefer bins whose residual is harmonically close to the item (mod-based pairing)
        let r = bin_residual % (item_size.max(1));
        score += r as f64 * 0.3;
        // Prefer bins with residual near item_size + common small complements
        for comp in [0u32, 5, 10, 20, 25, 50] {
            if post_residual == comp {
                score -= 8.0;
            }
        }
    }

    // Progress pressure: late in stream, consolidate harder
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post / cap);

    // Many open bins: penalize spreading, favor filling existing
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64).ln() * (post / cap);
    }

    // Mean residual coupling: bins far from mean residual get slight penalty
    score += ((post - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: residuals in (0, 10) are unusable
    // (minimum item size is 10). Penalize them heavily, scaled by how
    // close they are to being truly wasted.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Small-but-usable residuals (10..=20) are risky: only the smallest
    // future items can use them. Mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 45.0;
        } else if slack < 10.0 {
            score += slack; // near-miss creates dead space risk
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones; with few open bins, tolerate new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // reward slightly when very few bins are open.
        score += 12.0 + pressure;
        if open_bins_count <= 2 {
            score -= 15.0;
        }
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with below-average residual (tighter bins get filled first).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, be more conservative: fill existing bins tightly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual > 0 && post_residual < 10 {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        score -= 30.0 * (1.0 - diff / cap).max(0.0);
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 50.0; // chain perfect fit
        }
        // Penalize leaving residual too small for next item (dead space)
        if (post_residual as i64) < (next_item_size as i64) && post_residual > 0 {
            score += 20.0 * (1.0 - post / cap);
        }
    }

    // Compare residual against mean residual across open bins
    score += 0.5 * (post - mean_residual);

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins,
    // unless existing bins would leave big dead space
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    // Penalize large wasted residual relative to capacity
    if post > 0.0 && post < 10.0 {
        score -= 15.0; // tiny residual is nearly a perfect fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual gets extra priority.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the resulting residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if post_residual > next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Prefer placements where next item leaves small dead space too.
            score -= 4.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // Placing here leaves residual smaller than next item: penalize
            // proportionally to how "wasted" the residual is.
            let waste = post_residual as f64 / next_item_size.max(1) as f64;
            score += 3.0 * waste;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Penalize spreading across many open bins when residuals are large.
    if open_bins_count > 2 {
        let avg_pressure = mean_residual / bin_capacity as f64;
        score += 2.0 * avg_pressure;
    }

    // Reward filling bins below mean residual (consolidation).
    if (post_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Time horizon: early in the stream, be conservative (favor new bins
    // for large leftover space); late in the stream, squeeze everything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    // New-bin candidate handling: an empty bin should only win when the
    // item fits poorly everywhere else (large post_residual on open bins).
    if bin_residual == bin_capacity {
        // Mild penalty so open bins with decent fits win first.
        score += 4.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits: open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with non-linear coupling to stream progress.
    // Early on, large residuals are fine (bins can absorb future items);
    // late in the stream, residual space is more likely to become dead space.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth non-linear penalty for "awkward" residuals: mid-size gaps are least
    // reusable, tiny gaps are fine, large gaps are reusable.
    let awkward = 4.0 * x * (1.0 - x) * (1.0 - x);
    score += 18.0 * awkward * (0.5 + progress);

    // Reward tight fits (post residual near zero) more strongly as stream advances.
    score -= 12.0 * (1.0 - x).powi(3) * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement is excellent; if it barely doesn't fit, penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr as f64 {
            score -= 10.0 * (pr as f64 - n + 1.0).ln().max(0.0);
        } else {
            score += 8.0 * (1.0 - ((n - pr as f64) / cap)).powi(2);
        }
    }

    // Mild penalty when this bin is much worse than average residual
    // (encourages spreading load across bins evenly early on).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: neutral baseline, opened only if all open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: smaller post_residual is better (base already does this),
    // but give an extra harmonic-class bonus for "perfect-ish" fits.
    let fit_ratio = item_size as f64 / bin_residual as f64; // 0..1
    score -= fit_ratio * 30.0;

    // Harmonic classes on post_residual: dead space buckets.
    // post_residual == 0 is perfect; small residuals (1..10) are near-dead.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    } else {
        // large leftover space: mildly penalize unless it can host next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // leftover still usable by lookahead item
        } else {
            score += 6.0; // dead space penalty
        }
    }

    // Modulo-10 class of post_residual: multiples of 10 align with typical
    // item sizes and are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this item fits poorly everywhere. Penalize new bin by default, scaled
    // by how full existing bins are (mean_residual).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 30.0 + mean_residual * 0.5 - progress * 10.0;
        // If next item is huge and this item is small, new bin may be better
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0;
        }
        // Few fitting bins and high mean residual -> existing bins are fragmented,
        // new bin slightly more attractive.
        if fitting_bins_count <= 2 && mean_residual > 40.0 {
            score -= 12.0;
        }
    }

    // Lookahead pairing: reward bins where post_residual exactly matches or
    // exceeds next item with room to spare (chain packing).
    if next_item_size > 0 {
        let next_fit = post_residual as i64 - next_item_size as i64;
        if next_fit == 0 {
            score -= 20.0;
        } else if next_fit > 0 && next_fit <= 10 {
            score -= 10.0;
        } else if next_fit < 0 && next_fit > -10 {
            score += 5.0; // near-miss wastes the leftover
        }
    }

    // Mild preference to fill bins when many bins are open (consolidation).
    score += open_bins_count as f64 * 0.3;

    // Small noise-free tiebreak by bin fullness fraction.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical future
    // items (min size 1, but realistically small fragments) are dead space.
    // Penalize sharply when post_residual is tiny but nonzero (wasted capacity),
    // and when it falls in the "unusable" band [1, 12].
    if post_residual > 0 && post_residual <= 12 {
        score += 25.0 * (1.0 - post_residual as f64 / 12.0);
    }
    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Dead-space ratio penalty: post_residual relative to what remains.
    if bin_residual > 0 {
        let waste_ratio = post_residual as f64 / bin_residual as f64;
        score += 15.0 * waste_ratio * waste_ratio;
    }

    // Open-bin pressure: discourage opening new bins when open bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Reward using existing bins, more so as open bins accumulate.
        score -= 3.0 * (open_bins_count.min(20) as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if post_residual is smaller than next item but nonzero,
    // it is dead space for the lookahead — penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 10.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (consume the fuller bins first, keep large residuals for big items).
    score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64).max(-1.0).min(1.0);

    // Mild stream-progression pressure: later in the stream, consolidate more
    // aggressively to avoid bin sprawl.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if !is_new_bin {
            score -= 5.0 * progress;
        } else {
            score += 5.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect two-item packing: post_residual exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits snugly into the post residual (tight lookahead fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize if we leave large dead space.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > 0 {
        score += 25.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with residual already below mean (tighter bins fill better).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize creating small unusable gaps (1..10) unless next item fills them.
    if post_residual > 0 && post_residual < 10 && next_item_size != post_residual {
        score += 30.0;
    }

    // Early in stream, slightly prefer keeping new bins closed (use open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins would waste a lot.
        score += 20.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are valuable: reward small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness).powi(3);

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.55 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins whose leftover can still host the next item.
            score -= 0.35 * (post_residual - next_item_size).min(bin_capacity as u32) as f64;
        }
    } else {
        // Last item: pure best-fit dominates.
        score -= 8.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // late in the stream, squeeze into existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0 * (1.0 - tightness);

    // Global residual pressure: if mean residual is high, prefer filling roomy bins;
    // if mean residual is low, tolerate looser fits to keep bins consolidated.
    let mean_t = mean_residual / bin_capacity as f64;
    score += 2.0 * (tightness - mean_t).abs();

    // Penalize very large leftovers that become dead space (below min item size ~ 1).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0 * (10 - post_residual) as f64;
    }

    // Mild penalty for opening a new bin when many bins are already open and
    // consolidated packing is preferable.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.02 * open_bins_count as f64;
        // But if the item is large relative to mean residual, opening may be fine.
        score -= 1.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large residuals are acceptable; late in the stream, waste is penalized harder.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * norm_pr * norm_pr * cap * 0.25;

    // Reward tight fits: small post_residual gets a smooth quadratic discount.
    let tightness = 1.0 - norm_pr;
    score -= 2.0 * tightness * tightness * (1.0 + progress);

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) as f64;
            let gap_norm = gap / cap;
            // Perfect complementarity strongly rewarded; larger gaps decay quadratically.
            score -= 6.0 * (1.0 - gap_norm) * (1.0 - gap_norm) * (1.0 + 2.0 * progress);
        } else {
            // Next item cannot use this residual: mild penalty scaled by leftover size.
            score += 1.5 * norm_pr * (1.0 - progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 + progress);
    }

    // Penalize bins whose residual deviates far from the mean residual
    // (encourages balanced residual profiles across open bins).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: neutral-ish baseline that becomes less attractive
    // as the stream progresses and when many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
        // Still allow new bins early or when nothing fits well elsewhere.
        if fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it decomposes against common item sizes
    let pr = post_residual;
    // Modulo classes vs typical small items (10, 20, 25, 50)
    let fits10 = pr / 10;
    let mod10 = pr % 10;
    let mod20 = pr % 20;
    let mod25 = pr % 25;
    let mod50 = pr % 50;

    // Reward residuals that lie on harmonic grid points (divisible by 10/20/50)
    if mod10 == 0 { score -= 6.0; }
    if mod20 == 0 { score -= 4.0; }
    if mod25 == 0 { score -= 3.0; }
    if mod50 == 0 { score -= 5.0; }
    // Penalize awkward off-grid residuals
    if mod10 != 0 && mod25 != 0 { score += 2.0 * mod10 as f64; }

    // Dead-space penalty: residual too small for any plausible future item
    if pr < 10 {
        score += 25.0 * (10 - pr) as f64;
    } else if pr < 20 && pr < item_size {
        score += 8.0;
    }

    // Perfect fit reward
    if pr == 0 { score -= 100.0; }

    // Lookahead: does post_residual accommodate next item harmonically?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Extra reward if after next item residual again lands on grid
        let pr2 = pr - next_item_size;
        if pr2 % 10 == 0 { score -= 5.0; }
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // Next item won't fit here anyway; residual value is its future utility
        score += 0.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize proportionally
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, discounted when many bins already open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.65 + 10.0 * (1.0 - progress);
        // If item leaves a harmonic residual in a fresh bin, slightly cheaper
        if (bin_capacity - item_size) % 10 == 0 { score -= 8.0; }
    }

    // Tight-fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.9 { score -= 10.0; }
    else if fill_ratio < 0.3 { score += 4.0; }

    // Prefer bins with residual close to item (waste minimization via mean coupling)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any plausible item (1..100 range)
    // are wasted. Penalize gaps below the minimum useful threshold.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Moderate gaps (10..20) are risky: penalize softly.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit: small penalty proportional to leftover.
        score += 4.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (favoring existing bins over new ones); penalize when few open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open
        // and early in the stream (long remaining horizon to fill it).
        score += 15.0 + 20.0 * (1.0 - progress) + (open_bins_count as f64).min(20.0);
    } else {
        // Existing bin: slight reward when many bins are open (consolidation).
        score -= (open_bins_count as f64).min(10.0) * 0.8;
    }

    // Prefer bins with below-average residual (tighter bins) for tight fits.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit lookahead: next item exactly fills leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual: good chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit: leftover space becomes dead space; penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0 + 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to bin capacity (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Compare against mean residual: filling below-mean bins is valuable.
    if bin_residual as f64 <= mean_residual {
        score -= 6.0;
    } else {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless it is the only option,
    // so we prefer packing into open bins when reasonable.
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 15.0; // no real alternative: new bin is fine
        } else {
            score += 30.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Late in stream: keep bins closed, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small post-residual dead space that nothing (>=10) can use,
    // unless the fit was near-perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; slight penalty for wasting residual
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        // fresh bin baseline cost; becomes attractive when mean residual is low
        score += 20.0 * crowding;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        // late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Mild penalty for spreading across many open bins; encourage filling fewer bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins with residual below the mean (tighter bins get filled first).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling: penalize large post-residuals more as stream progresses
    // (early: waste is cheap; late: waste is expensive -> tight packing matters)
    let progress_weight = t * t; // smooth increasing weight
    score += progress_weight * (norm_pr * norm_pr) * cap * 0.5;

    // Reward tight fits: post_residual near zero gets a bonus, smoothly via (1 - norm_pr)^2
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 2.0;

    // Smooth interaction between post_residual and mean residual:
    // if this bin's post residual is far below the mean residual, it is a "good squeeze"
    let squeeze = (mean_residual - pr) / cap;
    score -= squeeze * squeeze * 1.5;

    // Lookahead coupling: penalize post residuals that cannot fit the next item
    // (smooth quadratic penalty proportional to the shortfall)
    if next_item_size > 0 {
        let shortfall = (next_item_size as f64 - pr).max(0.0) / cap;
        score += shortfall * shortfall * 3.0;
        // smooth reward if post residual leaves room for the next item
        let room = (pr - next_item_size as f64).max(0.0) / cap;
        score -= (1.0 - room) * room * 0.8;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0 + t * 3.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    let ob = open_bins_count as f64;
    score += (ob / (ob + 4.0)) * 1.0;

    // New-bin candidate: empty bin has large post_residual; the polynomial terms above
    // already penalize it late in the stream. Add smooth extra pressure proportional to progress.
    if bin_residual == bin_capacity {
        score += 2.0 + t * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residual mod small divisors reveals
    // how "usable" the leftover space is for typical item sizes.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -60.0,                       // perfect fit
        1..=9 => 25.0,                    // tiny dead space
        _ => {
            // usable if it can host common item sizes (multiples of 5/10)
            let tens = pr / 10;
            let rem = pr % 10;
            match rem {
                0 => -18.0 + (10 - tens.min(10)) as f64 * 1.5,
                1..=4 => 8.0 + rem as f64,
                5 => -6.0,
                _ => 5.0 + (9 - rem) as f64,
            }
        }
    };
    score += class_penalty;

    // Lookahead: reward if next item fits exactly in post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic class of slack after hypothetical next placement
            let cls = match slack as u32 % 10 {
                0 => 0.0,
                5 => 4.0,
                _ => 9.0,
            };
            score -= (25.0 - slack * 0.4).max(0.0) - cls * 0.5;
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + (bin_residual - item_size).min(40) as f64 * 0.3;
    }

    // New-bin candidate handling: opening a bin should only win when the fit
    // into open bins is bad. Penalize new bin when item fits snugly elsewhere.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 70.0;
        // early in stream, new bins are cheap (build inventory)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 45.0 * (1.0 - progress);
        // if many open bins with large mean residual, opening new bin is wasteful
        score += (open_bins_count as f64).sqrt() * 6.0;
        if mean_residual > item_size as f64 + 5.0 {
            score += 15.0;
        }
        // a fresh bin perfectly hosts the item: post_residual == capacity - item
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0;
        }
    } else {
        // reward placing into already-open bins, more so when many are open
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Prefer bins whose residual is close to item size (tight fit) —
    // relative tightness term.
    let tight = (bin_residual - item_size) as f64;
    score += tight * tight / (cap * 2.0);

    // Slight preference for bins below mean residual (consolidate emptier bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward tight fits: perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual != bin_capacity {
        score -= 30.0 * open_pressure;
    } else {
        // New-bin candidate: penalize opening new bins, more so with many open bins.
        score += 40.0 + 20.0 * open_pressure;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (next_item_size as f64) / (post_residual as f64);
        if next_fit > 0.7 {
            score -= 35.0 * next_fit;
        }
    }
    // Penalize leaving a gap just below next item size (near-miss waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates below mean (tighter bins).
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_residual as f64;
        if dev > 0.0 {
            score -= 10.0 * (dev / (mean_residual + 1.0));
        } else {
            score += 5.0 * (-dev / (mean_residual + 1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            score -= 200.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // Next item cannot fit here; penalize proportionally to wasted residual.
            score += 100.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare post_residual against mean residual: tight bins (below mean residual)
    // are good to close down; loose bins should absorb items.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when fits are poor.
    if bin_residual == bin_capacity {
        score += 250.0;
    }

    // Early in the stream, prefer keeping bins tight to build good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // Penalize creating dead space the next item cannot use,
            // scaled by how much is wasted.
            let dead = post_residual as f64;
            score += 0.3 * dead;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and could fit reasonably.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 30.0 + 20.0 * progress;
        // If other bins fit, make the new bin much less attractive unless
        // existing residuals are all large (poor fits everywhere).
        if fitting_bins_count > 1 {
            score += base_penalty + 50.0;
        } else {
            score += base_penalty;
        }
        // Early in the stream, opening bins is cheaper (spread load).
        if progress < 0.2 {
            score -= 15.0;
        }
        // If mean residual of open bins is small, a new bin is more justified.
        score -= 0.2 * mean_residual;
    } else {
        // Favor bins with residual close to item (best-fit flavor) among open bins.
        let slack = (bin_residual as f64 - item_size as f64).abs();
        score += 0.1 * slack;
        // Slightly prefer bins with below-average residual (fill fuller bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild global load balancing: with many open bins, prefer using them.
    if open_bins_count > 4 && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: polynomial in normalized post-residual, modulated by stream progress.
    // Early on, tight fits matter (minimize post_residual); later, slight slack is fine.
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - 0.5 * progress);

    // Non-linear coupling of post_residual with mean residual across open bins:
    // penalize if this bin's residual diverges from the fleet mean (fragmentation).
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // Reward filling a bin nearly exactly (post_residual near zero) super-linearly.
    score -= 1.5 * (1.0 - norm_pr).powi(6);

    // Lookahead: penalize leaving post_residual that is too small for the next item
    // (dead space), but reward leaving room exactly matching it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs() / cap;
        score += 0.9 * gap * gap;
        score -= 0.6 * ((pr >= ni) as f64) * (1.0 - gap).powi(4);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && is_new_bin < 0.5 {
        score -= 3.0 * (1.0 + progress);
    }

    // New-bin candidate handling: opening a bin is cheap early (build diversity),
    // expensive late; also penalize it when other bins fit.
    score += is_new_bin * (2.5 - 3.5 * progress + 0.3 * open_bins_count as f64 * 0.1);
    if is_new_bin > 0.5 && fitting_bins_count > 0 {
        score += 1.2 + progress;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: exact fit is best
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues that are "usable" for
    // common item sizes (multiples of 10 / small divisors) are less dead.
    let usable = post_residual >= 10 && (post_residual % 10 == 0 || post_residual % 5 == 0);
    if usable {
        score -= 15.0;
    } else if post_residual > 0 && post_residual < 10 {
        // tiny dead space below minimum item size -> heavy penalty
        score += 40.0;
    }

    // Nonlinear tightness: reward residual close to zero with a quadratic kick
    let pr = post_residual as f64;
    score -= 30.0 * (1.0 - (pr / cap)).powi(6);

    // Lookahead coupling: if the next item fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * (next_item_size as f64);
        }
        // Harmonic class match: next item leaves a multiple-of-10 residue again
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it is a
    // very tight placement (large item) or current bins are fragmented.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        score += 90.0;               // base cost of opening a bin
        score -= 80.0 * frac.powi(3); // large items justify new bins
        // If existing bins are fragmented (high mean residual), new bin is ok
        if mean_residual > 50.0 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild preference for fuller bins among open bins
    score -= 0.3 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1u32;
    let gap_threshold = 10u32;
    if post_residual > 0 && post_residual < gap_threshold {
        score += 40.0 * (gap_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome: strong reward.
        score -= 60.0;
    } else {
        // Usable residual: mild quadratic penalty to prefer tighter fits.
        score += 0.08 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Lookahead synergy: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot use this bin's remainder: penalize.
            score += 6.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when
    // open_bins_count is already high; favor filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / 10.0);
    score += 0.05 * pressure * (1.0 - 0.5 * progress);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // current fit is terrible (large dead space) or no bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.6 * bin_capacity as f64
            || (post_residual > 0 && post_residual < gap_threshold);
        if bad_fit {
            score -= 45.0; // opening fresh bin beats wasting capacity
        } else {
            score += 25.0; // keep using existing bins for decent fits
        }
    }

    // Mild reward when bin residual is close to consumed.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when post_residual closely matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Perfect chain bonus: next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a dead space that no item of typical size can use.
        if post_residual < 10 {
            score += 40.0;
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual).
        score += 0.0;
    }

    // Prefer bins whose residual is tight relative to the mean (fill crowded bins).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize wasting a nearly-full bin's identity on a tiny item (large post_residual).
    if res > 50.0 {
        score += 0.4 * (res - 50.0);
    }

    // New-bin candidate: make it attractive only when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; reduced when many items remain and
        // current open bins are crowded (mean residual low).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = (mean_residual / bin_capacity as f64).max(0.0);
        score += 15.0 + 30.0 * crowding - 10.0 * progress;
        // If next item is huge, a fresh bin gives flexibility.
        if next_item_size > 60 {
            score -= 12.0;
        }
    }

    // Mild preference to consolidate into fewer bins early on.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space quadratically.
    let residual_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * residual_frac * residual_frac * (bin_capacity as f64);

    // Penalize small-but-nonzero dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size as f64 <= post_residual as f64 {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }
    // Penalize leaving space that the next item almost-but-not-quite fits.
    if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // New-bin candidate handling: discourage opening new bins when open bins fit well.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early stream: opening bins is cheap (more future items to fill them).
        // Late stream: prefer filling existing bins.
        let new_bin_penalty = 55.0 * (1.0 - 0.5 * progress);
        score += new_bin_penalty;
        // If current item is huge and mean residual is low, opening a bin is fine.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
        // If many bins are open and residuals are scattered, consolidate instead.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    // Slight tie-break: prefer bins with lower residual overall (denser bins first).
    score += 0.05 * bin_residual as f64;

    // Global state coupling: many open bins -> encourage consolidation.
    score += 0.3 * open_bins_count as f64 * residual_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling: quadratic/cubic penalty on wasted space,
    // modulated by stream progress (waste matters more later in the stream).
    let waste_curve = norm_pr * norm_pr * (1.0 + norm_pr);
    score += waste_curve * (0.5 + 1.5 * progress) * cap * 0.1;

    // Reward tight fits: near-zero post residual gets a strong smooth bonus.
    let tightness = (1.0 - norm_pr).powi(8);
    score -= tightness * 6.0;

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward; if post residual is slightly too small for next item, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fit_gap = (pr - ni).abs() / cap;
        score -= (1.0 - (fit_gap * 4.0).min(1.0)) * 3.0;
        if pr >= ni {
            score -= 2.0; // next item can follow in this bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    let crowding = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powi(2);
    score += crowding * 2.0 * norm_pr;

    // Mean residual deviation: prefer bins whose residual deviates smoothly
    // from the mean (consolidate large residuals).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 1.5;

    // Mild preference for fuller bins as stream progresses (smooth sigmoid).
    let sig = 1.0 / (1.0 + (-(progress - 0.5) * 6.0).exp());
    score -= sig * (bin_residual as f64 / cap) * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quartiles
    let quarter = bin_capacity / 4; // 25
    let class = post_residual % quarter;
    score += class as f64 * 0.3;

    // Reward near-perfect fits (post_residual in a "dead zone" of small values)
    if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= quarter / 2 {
        score -= 15.0;
    }

    // Penalize leaving residual that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space smaller than smallest item
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic bonus if next item also lands in a good class
            let nclass = (post_residual - next_item_size) % quarter;
            score -= (quarter - nclass) as f64 * 0.1;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: keep it neutral-to-slightly-high unless open bins are fragmented
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't abandon the only fitting bin
        }
    }

    // Fragmentation penalty relative to mean residual
    if (post_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 5.0; // homogenize residuals for future pairing
    }

    // Late-stream tightening
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // classic dead space: nothing (10..80) can ever use it
        } else if post_residual < 20 {
            score += 25.0; // near-dead space, only tiny items fit
        } else {
            // Usable residual: mild penalty scaled by how small the window is
            score += (20.0 - (post_residual as f64 - 20.0) * 0.05).max(0.0);
        }
    } else {
        // Perfect fit: strongly reward closing the bin completely
        score -= 80.0;
    }

    // Reward tight fits: fraction of bin consumed by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good
    // consolidation is possible; encourage new bin when bins are few.
    score += (open_bins_count as f64).ln().max(0.0) * 6.0;

    // Mean residual coupling: prefer bins whose residual is below average
    // (i.e., filling fuller bins first keeps emptier bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward;
    // if next item cannot fit in post-residual, penalize slightly (unless
    // post_residual is dead space anyway).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual >= 20 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // New-bin candidate handling: empty bin is a fallback. Prefer it only
    // when no open bin offers a decent fit (high post_residual penalty
    // already discourages bad fits). Add a mild fixed cost so open bins
    // with reasonable fits win, but keep it cheap enough when stream is
    // early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64 / 8.0).min(3.0);
        score = score.max(0.0) + 18.0 + open_pressure * 10.0 - (1.0 - progress) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 {
        // dead space relative to the next item
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Penalize post_residual that is small but nonzero (unusable sliver)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tightness relative to mean residual: prefer filling fuller bins
    let tightness = (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;
    score -= tightness * 20.0;

    // Compare post_residual against mean residual: creating below-average residual wastes space
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count > 0 && next_item_size > 0 && (bin_residual - item_size) >= next_item_size {
            // fresh bin still attractive for a perfect 2-item chain
            score -= 90.0;
        }
    }

    // Late in stream: consolidate into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 15.0 * (open_bins_count as f64).sqrt().max(1.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residual relative to mean residual state of the system.
        score += (post_residual as f64 - mean_residual) * 0.35;
        // Non-linear penalty on large wasted space.
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
    }

    // Lookahead (k=2): reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0; // perfect two-item chain
        } else if post_residual >= next_item_size {
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: dead-space risk, scaled by how dead it is
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    } else {
        // Last item: just empty bins as much as possible.
        score -= post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 60.0;
        // Cheaper to open new bins early in the stream / when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * (1.0 - progress);
        // If few bins can fit the item, opening a new bin is more reasonable.
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        // If open bins have small mean residual, they fit poorly -> new bin attractive.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 30.0;
        // Lookahead: a fresh bin guarantees room for the next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Mild pressure against hoarding many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear polynomial coupling: reward tight fits quadratically-cubically
    score -= 40.0 * (1.0 - norm_post).powi(2) * (1.0 + 0.8 * progress);
    score -= 25.0 * norm_item * (1.0 - norm_post).powi(3);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    let unusable = ((post - next_item_size as f64) / cap).max(0.0);
    score += 30.0 * unusable * unusable * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize early, reward late when open bins fit poorly
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 80.0 * (1.0 - progress) * (1.0 - norm_item);
        score -= 20.0 * progress * norm_item;
        // If existing bins would leave large waste, opening new bin is attractive
        score += 15.0 * (norm_post - mean_residual / cap).abs();
    }

    // Mild penalty for spreading across many open bins with slack
    score += 0.5 * open_bins_count as f64 * norm_post * (1.0 - progress);

    // Perfect-fit lookahead reward
    if next_item_size as f64 == post && !is_new {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residual that can't hold typical items is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic class of post_residual modulo 10: residuals in "useful" classes
    // (multiples of 10, or >= 10) are rewarded.
    let pr = post_residual;
    let class = pr % 10;
    if class == 0 && pr > 0 {
        score -= 8.0; // perfect harmonic alignment
    } else if pr >= 10 {
        score -= 3.0; // still reusable
    } else if pr > 0 {
        score += 6.0; // awkward sliver
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0;
        // Harmonic check on remaining slack after the lookahead item.
        if slack % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item would need another bin if we place here; mild penalty.
        score += 4.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that grows
    // with how many bins are already open, but is attractive when the fit
    // would leave a bad harmonic class.
    if bin_residual == bin_capacity {
        let open_cost = 10.0 + 0.3 * open_bins_count as f64;
        // If placing in an existing bin would leave a sliver, new bin is fine.
        let bad_existing_fit = pr > 0 && pr < 10;
        if bad_existing_fit {
            score -= 5.0;
        }
        score += open_cost;
    }

    // Progress-based mild tightening: late in the stream, prefer filling bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than average (good packing density).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item
    // (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.0 * post_residual as f64;
    }
    if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.15 * slack;
    }
    // If next item almost fits (small miss), mild penalty for tempting gap.
    if next_item_size > post_residual && next_item_size > 0 && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to the
    // mean (keeps bin states homogeneous and predictable).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., few fitting bins and current bin residual is a poor match),
    // or when open bins are nearly full already.
    if bin_residual == bin_capacity {
        let poor_options = (fitting_bins_count == 0) || (fitting_bins_count == 1 && bin_residual < bin_capacity);
        let tight_state = mean_residual < 15.0;
        if poor_options || tight_state {
            score -= 12.0;
        } else {
            // Prefer using existing bins: penalize new bin.
            score += 20.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Early stream: be slightly more willing to open bins (build diverse residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        }
        // Penalize leaving residual slightly larger than next item (wasted sliver)
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins already below-average residual (consolidation)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge relative to capacity
    if bin_residual == bin_capacity {
        score += 55.0 - 40.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Early stream: keep bins open for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 && progress < 0.3 {
        score += 5.0;
    }

    // Dead-space penalty: very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 18.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 30 {
        score += 4.0; // awkward gap
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize very small leftovers
            score += 3.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins aren't opened frivolously.
        score += 15.0;
        // More attractive if open bins are crowded (high mean fill).
        score -= 0.15 * mean_residual;
        // Less attractive early in the stream (keep bins mergeable).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If item is large, a fresh bin is fine.
        score -= 0.1 * item_size as f64;
    } else {
        // Prefer filling bins with low residual relative to mean (balance avoidance).
        score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // Slight preference to use fewer open bins when many are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothed by progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling: post_residual^2 normalized, weighted by progress
    score += 20.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic term penalizing large dead space late in the stream
    score += 15.0 * norm_pr.powi(3) * progress;

    // Reward tight fits (small post_residual) strongly
    score -= 25.0 * (1.0 - norm_pr).powi(2);

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * (1.0 - progress);

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 30.0 * (1.0 - gap / cap).powi(2);
        // Penalize if next item cannot fit in this bin's post residual
        if next_item_size as f64 > pr {
            score += 15.0 * norm_pr * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: discourage unless existing bins create bad dead space
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with harmonic (quantized) classes
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (1/8 steps)
    let class = (post_residual * 8 / bin_capacity.max(1)) as f64; // 0..8 integer class
    score += class * 0.7; // penalty ladder for coarse dead-space classes

    // Perfect fit reward: post_residual in small harmonic classes
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Modulo arithmetic on post_residual: residues that pair well with common item sizes
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0; // residue 0 aligns with decade-sized items
    } else if r <= 2 {
        score -= 3.0;
    } else if r >= 8 {
        score += 2.0; // awkward residue, near-miss dead space
    }

    // Lookahead coupling: can next_item_size exactly fill the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain completion
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap_f);
        } else {
            score += 4.0; // next item cannot use this bin
        }
        // Harmonic division check: post_residual divisible by next_item_size
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current fit is poor
    if bin_residual == bin_capacity {
        // fresh bin: baseline moderate score; penalize opening when item is small relative to capacity
        score = post_f + 15.0;
        if item_size as f64 / cap_f > 0.7 {
            score -= 20.0; // big items start fresh bins happily
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 30.0; // an open bin already has room; don't open a new one
        }
        if open_bins_count == 0 {
            score -= 60.0; // must open first bin
        }
    }

    // Tightness bonus: filling a bin closer to capacity is rewarded nonlinearly
    let fill = 1.0 - post_f / cap_f;
    score -= 12.0 * fill * fill;

    // Progress-aware waste penalty: later in stream, dead space costs more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * post_f * 0.15;

    // Mean residual divergence: penalize bins far above mean residual (fragmented bins)
    score += 0.3 * (post_f - mean_residual).abs();

    // Open-bin pressure: many open bins -> consolidate
    if open_bins_count > 4 {
        score += 1.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (assume min item ~10) are wasted. Penalize sharply.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 30.0;

    // Reward when post_residual can exactly host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // extra reward for near-exact chain fit
        let slack = (post_residual - next_item_size) as f64;
        if slack < dead_zone {
            score -= 6.0;
        }
    } else if next_item_size > 0 {
        // Lookahead won't fit here: mild penalty proportional to gap
        score += ((next_item_size - post_residual) as f64).min(20.0) * 0.5;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins (new-bin candidate has residual == capacity and
    // gets no such discount).
    if bin_residual < bin_capacity {
        score -= (open_bins_count.min(20) as f64) * 1.5;
        // Prefer bins tighter than average (best-fit flavor)
        score += (mean_residual - bin_residual as f64) * 0.3;
    } else {
        // New-bin candidate: penalize when open bins exist and pressure is low
        score += (open_bins_count as f64) * 2.0;
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0; // chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            // closeness of next item to post_residual -> strong reward
            let gap = post - nxt;
            score -= 300.0 / (1.0 + gap / 10.0);
        } else {
            // next item can't fit: penalize wasted potential
            score += 0.5 * (nxt - post);
        }
    }

    // Compare post_residual relative to mean residual of open bins
    if post_residual as f64 > mean_residual {
        score -= 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score += 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        // baseline penalty so new bins are opened only when needed
        score += 120.0;
        // but if no open bin fits well, allow opening (lookahead-friendly fresh bin)
        if next_item_size > 0 && (post_residual as f64).abs() < f64::EPSILON {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Mild penalty for many open bins (encourage closing bins out)
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no plausible item can fill
    if post_residual > 0 && (post_residual < 10 || post_residual > 80) {
        score += 8.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 15.0 * (1.0 - slack);
        } else {
            score += 4.0 + 0.1 * (nxt - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global pressure: many open bins -> prefer filling existing ones
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score -= 6.0 * pressure * (bin_residual as f64 / cap);

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: late in stream, be greedier about tight fits
    let t = step_index as f64 / (total_items as f64).max(1.0);
    score -= 10.0 * t * (1.0 - (post_residual as f64) / cap);

    // New-bin candidate: penalize slightly unless existing fit is poor
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * (1.0 - (post_residual as f64) / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    // Early: prefer filling bins tightly (low post_residual weighted strongly).
    // Late: dead space matters less, slight relaxation.
    let warp = 0.6 + 0.8 * progress * progress;
    let mut score = pr * warp;

    // Smooth polynomial coupling: penalize mid-range residuals (awkward gaps),
    // reward near-zero and reward moderately large usable residuals.
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 40.0 * poly * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 25.0 * tight * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        // Penalize creating residual too small for the next item (dead space).
        score += 10.0 * (1.0 - pr / (next_item_size as f64)).max(0.0) * norm_pr;
    }

    // Mean residual coupling: avoid bins deviating far from fleet mean
    // (keeps residual distribution balanced for future fits).
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate handling: prefer opening a new bin early or when
    // open bins are crowded; penalize new bins when good fits exist.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap * open_bins_count as f64);
        score = cap * (1.2 - 0.7 * progress) + 5.0 * crowd;
        if fitting_bins_count >= 1 {
            score += 30.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly" sizes
    // (divisible by common item magnitudes), penalize awkward dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 4.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else if pr < 10 {
        score += 6.0; // tiny dead space, bin effectively closed
    }

    // Integer-division threshold: classify post_residual into capacity-fraction bands.
    let band = pr / 25; // 0..=4 quarters of capacity
    score += band as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
            // harmonic match: next item leaves a class-friendly residual again
            let pr2 = pr - next_item_size;
            if pr2 == 0 { score -= 8.0; }
            else if pr2 % 10 == 0 { score -= 3.0; }
        } else {
            score += 4.0; // next item cannot use this bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
    }

    // Progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item_share = (item_size as f64 / cap).clamp(0.0, 1.0);
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let mean = mean_residual.clamp(0.0, cap);
    let progress = if total_items == 0 {
        0.0
    } else {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    };
    let open_f = open_bins_count as f64;
    let open_pressure = open_f / (open_f + 4.0);
    let fitting_f = fitting_bins_count as f64;
    let urgency = if fitting_bins_count == 0 { 0.0 } else { 1.0 / fitting_f };
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    if post_residual == 0 {
        let closure_scale = if next_item_size > 0 && fitting_bins_count > 1 {
            let room_elsewhere = ((mean - next) / cap).clamp(0.0, 1.0);
            (1.0 / fitting_f) * (1.0 - 0.50 * room_elsewhere)
        } else {
            1.0
        };
        score -= cap * (1.10 + 0.90 * open_pressure) * closure_scale;
    } else if next > 0.0 {
        if next <= post {
            let utilization = (next / post).clamp(0.0, 1.0);
            score -= cap * (1.10 + 0.90 * open_pressure) * utilization * utilization;
            if post_residual == next_item_size {
                score -= cap * (0.15 + 0.35 * open_pressure);
            }
        } else {
            let shortfall = ((next - post) / cap).clamp(0.0, 1.0);
            let dead_zone = cap * (0.04 + 0.06 * open_pressure);
            let deadness = if post < dead_zone {
                (dead_zone - post) / dead_zone
            } else {
                0.0
            };
            score += cap
                * (0.15 + 0.85 * shortfall + 0.50 * deadness * deadness)
                * (0.35 + 0.85 * open_pressure);
        }
    }

    if !is_new_bin {
        score -= cap * 0.30 * urgency * (0.35 + 0.85 * open_pressure);

        if fitting_bins_count == 1 {
            score -= cap * (0.45 + 0.35 * open_pressure + 0.10 * progress);
        }

        let tightness = 1.0 - (post / cap).clamp(0.0, 1.0);
        score -= open_pressure * tightness * tightness * cap * 0.30;

        let scarcity = ((mean - residual) / cap).clamp(0.0, 1.0);
        score -= scarcity * cap * (0.05 + 0.15 * open_pressure);
    } else {
        let trapped = (mean / cap).clamp(0.0, 1.0);
        let new_cost = 0.30 + 0.75 * open_pressure + 0.25 * trapped + 0.10 * progress;
        score += cap * new_cost * (1.0 - 0.20 * item_share);

        if fitting_bins_count > 0 {
            score += cap * (0.20 + 0.35 * open_pressure) * urgency;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit lookahead: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits in the residual: strong reward, scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (next_item_size as f64) / (post_residual as f64);
        score -= 20.0 + 25.0 * tightness;
    }

    // Next item does NOT fit: penalize dead space, worse for large leftover
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tighter bin) is preferable — keeps roomy bins open.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 4.0 * ((post_residual as f64) - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New empty bin candidate: penalize so it's only chosen when open bins are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening fresh bins is less attractive (can't amortize)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit: tighter fit is better (already via post_residual).

    // Lookahead: penalize if the leftover cannot fit the next item,
    // reward if it fits exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover usable by next item: reward proportionally
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // leftover is dead space w.r.t. lookahead item
            score += 4.0 + 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins far below mean residual (fragmenting unevenly),
    // mildly favor bins near the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Make the empty bin moderately costly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, opening bins is fine; later, prefer consolidation.
        let open_cost = 25.0 - 15.0 * progress;
        // If many bins already open, discourage yet another one.
        let crowd = 0.5 * open_bins_count as f64;
        // If next item is large, an empty bin is more valuable.
        let next_relief = if next_item_size > 60 { 8.0 } else { 0.0 };
        score += open_cost + crowd - next_relief;
    }

    // Time horizon: late in stream, squeeze items in harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very large leftover chunks that likely go unused
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable slivers are wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual normalized, polynomial shaping
    let pr = post_residual as f64 / cap;
    let pr2 = pr * pr;
    let pr3 = pr2 * pr;

    // Large dead space penalized super-linearly; small residual (tight fit) rewarded
    score += 40.0 * pr3 - 12.0 * pr2;

    // Reward tight fits more strongly as stream progresses (consolidation pressure)
    let tightness = 1.0 - pr;
    score -= (0.5 + 2.5 * progress) * tightness * tightness * cap * 0.1;

    // Perfect-ish fit bonus (post_residual < 10) scaled by progress
    if post_residual < 10 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if (nd - post_residual as f64).abs() < 1.0 {
            score -= 25.0;
        } else if nd <= post_residual as f64 {
            // next item fits: mild reward proportional to how well it nests
            score -= 8.0 * (1.0 - (post_residual as f64 - nd) / cap);
        } else {
            // next item won't fit: penalize leaving residual smaller than next item
            score += 5.0 * (1.0 - post_residual as f64 / nd);
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins below mean residual slightly (balance avoidance of fragmentation)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress) + 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild preference for more-filled bins among many open bins
    score += 0.05 * open_bins_count as f64 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space in [1..10] is nearly worthless,
    // [11..20] still bad, larger chunks reusable.
    let pr = post_residual;
    if pr > 0 && pr <= 10 {
        score += 25.0; // worst dead-space class
    } else if pr <= 20 {
        score += 10.0;
    } else if pr <= 30 {
        score += 4.0;
    }

    // Perfect fit reward: strongly favor zero residual.
    if pr == 0 {
        score -= 40.0;
    }

    // Exact-fit harmonic check: post_residual divisible by 10 means a clean
    // compartment that future items (multiples of 10) can fill.
    if pr > 0 && pr % 10 == 0 {
        score -= 6.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // this placement sets up a chain — reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 {
                score -= 8.0; // near-perfect chain setup
            } else if slack > 60 {
                score += 3.0; // next item leaves a big awkward remainder
            }
        } else {
            // Next item won't fit in residual anyway; residual class matters more.
            score += 1.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer reusing open bins when their fit is decent; the empty-bin call
    // gets a moderate base penalty so only genuinely bad fits trigger it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap + 10.0 + 20.0 * (1.0 - progress);
        // But if item is large relative to capacity and open bins are crowded
        // (mean residual small), opening fresh is reasonable.
        if (item_size as f64) / cap > 0.7 && mean_residual < item_size as f64 {
            score -= 35.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open the first bin
        }
    }

    // Mild preference to fill fuller bins first (tighter packing).
    score -= (bin_residual as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals below the minimum item size (10)
    // are unusable; penalize them heavily, proportionally to how "wasted" they are.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Soft gradient: the smaller the usable leftover, the better (best-fit core),
    // with a non-linear boost for very tight fits.
    if post_residual >= 10 {
        score -= (20.0 - (post_residual as f64 / 5.0)).max(0.0);
    }

    // Lookahead: reward if the next item fits into the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't fit here; penalize bins whose leftover is large but
            // unusable by the next item (fragmentation risk).
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual < bin_capacity {
        score -= pressure * 2.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins
    // have poor mean fit or the item is large relative to typical residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by state.
        score = bin_capacity as f64 - 40.0
            + pressure
            - if mean_residual < item_size as f64 { 80.0 } else { 0.0 }
            - if fitting_bins_count == 0 { 50.0 } else { 0.0 };
        // Late in stream, prefer reusing bins harder.
        score += progress * 30.0;
    } else {
        // Mild alignment with mean residual: prefer bins close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            // Perfect 2-step fit: strongly favor this bin.
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here: mildly favor, scaled by tightness.
            score -= 12.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover dead space.
            score += 8.0 * diff / bin_capacity as f64;
        }
    }

    // Dead-space penalty: nonzero but unusably small post_residual is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect closure (post_residual == 0) is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (fill fuller bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: neutral baseline with slight penalty so we
    // only open new bins when no open bin fits reasonably well.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in the stream, opening bins is cheaper.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space in
    // [1, 10] is nearly useless — penalize leaving awkward slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Reward filling a bin nearly to capacity (post_residual <= 5 is gold).
    if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count >= 2 {
        // With multiple options, prefer the bin where this item is the best fit;
        // slight penalty scaled by how "loose" the fit is relative to others.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead (k=2): if the next item exactly fits the post_residual,
    // this placement sets up a perfect follow-up — big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits but leaves more slack: mild reward proportional to
        // how well it uses the remaining space.
        let usage = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * usage;
    } else if next_item_size > post_residual {
        // Next item won't fit here: penalize leaving large unusable gaps
        // relative to the lookahead demand.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.15 * gap;
    }

    // Global state coupling: when mean residual across open bins is high,
    // we have slack everywhere — be pickier about fits (penalize loose fits).
    let slack_pressure = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 8.0 * slack_pressure.clamp(-1.0, 1.0);

    // Many open bins: encourage consolidation into existing bins rather
    // than spreading; scale with open bin count.
    score += 0.05 * open_bins_count as f64;

    // Time horizon: early in the stream, keep bins open-ended (favor tight
    // fits less aggressively so future items have room); late in the stream,
    // close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has bin_residual == capacity.
    // Its raw post_residual is large, but add an explicit opening penalty so
    // it only wins when fits in open bins are truly poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Exception: if no open bin fits at all (fitting_bins_count == 0 for
        // open bins), opening is necessary — soften the penalty.
        if fitting_bins_count == 0 {
            score -= 22.0;
        }
        // Late in the stream with few bins, opening is cheap.
        score -= 6.0 * progress;
    }

    // Fragmentation guard: placing into a nearly-full bin with a large item
    // is efficient — reward high fill ratio.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste becomes progressively more costly as the stream advances.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * progress * progress;
    score += 8.0 * coupling;

    // Reward tight fits: quadratic bonus shrinking as post_residual -> 0.
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Lookahead: reward residuals that can host the next item, penalize near-misses.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr as u32 >= next_item_size {
            let slack = (pr - next_item_size) as f64 / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let miss = (next_item_size - post_residual) as f64 / cap;
            score += 5.0 * miss * miss;
        }
        let _ = ni;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 5.0 * progress;
    }

    // New-bin candidate: acceptable early or when residual waste would be large.
    if bin_residual == bin_capacity {
        let waste_if_reject = if fitting_bins_count > 0 {
            mean_residual / cap
        } else {
            0.0
        };
        score = cap * (0.35 + 0.4 * progress) + 20.0 * waste_if_reject * waste_if_reject;
        if fitting_bins_count == 1 {
            score += 25.0; // never outrank the sole fitting bin
        }
    }

    // Mild penalty when bin deviates from mean residual (keeps bin profile balanced).
    score += 0.05 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity fractions (1/8 granularity)
    let class = post_residual / 12; // 8 classes over 0..100
    let class_penalty = match class {
        0 => -30.0,               // near-perfect fit
        1 => -12.0,
        2 => -4.0,
        3 => 0.0,
        4 => 6.0,
        5 => 14.0,
        6 => 24.0,
        _ => 30.0,                // large dead space
    };
    score += class_penalty;

    // Dead space: post_residual too small for the next item is wasted unless tiny
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as u64) < (next_item_size as u64) {
            // unusable residue: penalize proportionally, but tiny residue is fine
            let waste = post_residual as f64;
            score += 0.9 * waste * (1.0 - waste / cap) + 8.0;
        } else {
            // residue fits next item: reward tight chain
            let tightness = 1.0 - (post_residual as f64 - nxt) / cap;
            score -= 10.0 * tightness;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = cap * (1.0 - fill) + 5.0;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when one open bin fits
        }
    }

    // Mild pressure toward compacting many open bins
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 200.0;
    } else if post_residual <= 25 {
        // Small gaps are only usable by tiny items; mild penalty.
        score += 30.0 * (1.0 - (post_residual as f64) / 25.0);
    } else {
        // Larger usable residuals are mildly rewarded relative to baseline.
        score -= 5.0;
    }

    // Tight fit reward: the smaller post_residual relative to bin capacity,
    // the better the packing density (non-linear bonus).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally.
        score += 10.0 * ((next_item_size - post_residual) as f64) / 100.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; makes new bins less attractive.
    score += 3.0 * (open_bins_count as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin by rewarding this candidate.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Penalize the fresh bin, scaled by how
    // much residual capacity already exists across open bins.
    if bin_residual == bin_capacity {
        score += 90.0 + 2.0 * (open_bins_count as f64);
        // Late in the stream, opening new bins is even less desirable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // But if mean residual across open bins is tiny, a new bin is fine.
        if mean_residual < 15.0 {
            score -= 80.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (filling the
    // emptier-tail bins first keeps residual distribution balanced).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
