pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post-residual that cannot fit the next item is wasted.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * post_residual as f64;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the lookahead item exactly.
            let lookahead_fit = (post_residual as f64 - next_item_size as f64).abs();
            score -= 8.0 * (1.0 - lookahead_fit / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Fragmentation pressure: when many bins are open with small mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual < item_size as f64 * 1.5 {
        score += 5.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin when existing bins fit well,
    // but allow it when existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (1.0 - fill_ratio);
        }
        // Late in the stream, opening fresh bins is fine for large items.
        if item_size > 60 {
            score -= 6.0 * progress;
        }
    }

    // Mild preference for bins with residual close to mean (balance residual distribution).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Nonlinear coupling: squash score via mild tanh-like shaping on fill ratio.
    score -= 5.0 * (fill_ratio * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual in [0,1]
    let x = pr / cap;

    // Base: post residual, mildly discounted as stream progresses
    let mut score = pr * (1.0 - 0.35 * progress);

    // Smooth non-linear coupling: quadratic in normalized post-residual modulated by progress.
    // Early on, prefer tight fits (low post_residual); later, dead space matters more.
    score += 30.0 * progress * x * (1.0 - x) * 4.0;

    // Cubic interaction: penalize mid-range residuals increasingly with progress
    score += 20.0 * progress * progress * x * x * (1.0 - x);

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 25.0 * progress * (1.0 - x) * (1.0 - x);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - slack * slack);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Prefer bins with residuals below mean (consolidating waste)
    score += 5.0 * ((pr - mean_residual) / cap);

    // Mild penalty for spreading across many open bins early
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: perfect fits are gold, tiny dead space is poison.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take
        return score;
    }

    // Dead-space penalty: leftovers that nothing (min size 1..100) can use well.
    if post_residual < 10 {
        score += 120.0; // unusable sliver
    } else if post_residual <= 25 {
        score += 25.0;
    } else if post_residual <= 50 {
        score += 5.0;
    }

    // Modulo / harmonic classes of post_residual relative to capacity fractions.
    let q = post_residual / 25; // quarter classes
    let r = post_residual % 25;
    score += (r as f64) * 0.4; // prefer leftovers aligned to quarter boundaries
    if q == 0 {
        score -= 40.0; // leftover <=24 but aligned
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item can't fit here; leftover quality matters more
            score += 10.0;
            // harmonic class of next item vs leftover: multiples reward
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
    } else {
        // Prefer tighter (fuller) bins: reward low pre-residual relative to item.
        let tightness = (bin_capacity - bin_residual) as f64 / cap;
        score -= 30.0 * tightness;
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness_proxy(bin_residual, bin_capacity);

    // Prefer bins whose residual is near the mean (harmonic balance).
    score += 0.15 * (pr - mean_residual).abs();

    score
}

#[inline]
fn tightness_proxy(bin_residual: u32, bin_capacity: u32) -> f64 {
    1.0 - (bin_residual as f64 / bin_capacity as f64)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    // for future items (sizes >= 1, but realistically small gaps waste space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // worst kind of dead space
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this bin is a great choice; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0; // leftover likely becomes dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score -= pressure;

    // New-bin candidate handling: opening a new bin wastes capacity equal
    // to the mean residual of open bins; penalize it accordingly, but
    // relax the penalty when open-bin pressure is high and fits are poor.
    if bin_residual == bin_capacity {
        let waste = mean_residual.max(0.0);
        score += 15.0 + waste * 0.5 - pressure;
        // If current item would leave a big dead gap in any existing bin,
        // a fresh bin becomes attractive.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Slight preference for bins whose residual is close to the item
    // (tight fit) relative to mean residual spread.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it unattractive unless no open bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Late in the stream, opening a new bin is less costly.
        let progress = step_index as f64 / total_items as f64;
        score -= 30.0 * progress;
        // If very few bins fit the item, allow the new bin more readily.
        if fitting_bins_count <= 1 {
            score -= 55.0;
        }
        // Next item large relative to capacity: fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
        return score;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect pairing: this bin becomes exactly full after two items.
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize proportionally to the overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * overshoot;
        }
    } else {
        // Last item: prefer tightest fit only.
        score -= 5.0;
    }

    // Penalize creating dead space that is small-but-unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Reward bins whose residual is already below the mean (tight bins).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild bonus for filling bins tightly relative to capacity.
    score -= 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Strongly favor perfect/near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that cannot fit typical future items (>=10).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead conflict: next item would fit this bin better if we skip it.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 10.0;
    }

    // Time horizon: late in the stream, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // Global state: many open bins with slack -> prefer reusing bins with above-mean residual.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score -= 8.0 * (rel - 1.0);
    }

    // New-bin candidate penalty: opening a new bin is costly, scaled by how many bins already exist.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // But if current item is large and would leave a clean residual, new bin is more acceptable.
        if item_size >= 60 {
            score -= 25.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Prefer bins with residual close to item size (best-fit coupling).
    score += 0.5 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
