    let norm_pr = pr / cap;
    // smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);
    score -= 8.0 * norm_pr * (1.0 - norm_pr) * (1.0 - progress);
    // penalize dead space relative to mean residual
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);
    // reward last-chance bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
