        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }
    // new-bin candidate handling
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
    }
    score
