pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 30.0;

    // Harmonic class: post_residual mod 10 — bins with residual divisible by 10
    // tend to pair well with item sizes on 10-multiples; reward small remainders.
    let class = post_residual % 10;
    score += class as f64 * 1.5;

    // Integer-division thresholds on post_residual: dead-space bands
    if post_residual > 0 && post_residual < 10 {
        // unusable sliver for items >=10, but small items may exist; mild penalty
        score += 5.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 4.0; // sweet spot: still usable by next small item
    } else if post_residual > 60 {
        score += 3.0; // leaving too much space means poor fit now
    }

    // Lookahead: reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let next_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - next_left as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last chance: this is the only bin that fits — strongly prefer it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 0.5;
        if !crowded {
            score += 15.0 + 10.0 * (1.0 - progress);
        } else {
            score += 2.0;
        }
    }

    // Prefer filling bins that are already relatively full (low residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Mean-residual coupling: discourage diverging from the fleet average residual
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // Slight exploration bonus varying by open bin count modulo class
    score -= (open_bins_count % 3) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
