    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // post residual too small for next item: mild penalty unless tiny
            if post_residual > 10 {
                score += 5.0;
            }
        }
    }

    // Prefer bins with below-mean residual (more packed bins first),
    // keeping them tight and leaving larger residuals elsewhere.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Mild global scaling
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
