    // Prefer bins whose post_residual stays close to the mean residual (keeps fleet balanced)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer bins already below mean residual (consolidating waste)
    if (post_residual as f64) < mean_residual {
