    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits: strongly favor using it over opening a new bin
        score -= 20.0;
        // Unless the fit is terrible (large dead space), then new bin may be better
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
