    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: how well the item fills the bin relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward near-perfect fits (small post residual) more strongly over time.
    score -= 12.0 * (1.0 - residual_ratio) * (0.4 + 0.6 * progress);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - progress); // early: mild penalty, later: harsher
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let waste_after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - waste_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving large gaps.
            score += 3.0 * residual_ratio;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global mean residual: if this bin's post residual is below average, it's a good consolidation.
    if mean_residual > 0.0 {
        score += 0.15 * (post_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: make empty bins attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper early, expensive late.
        score = 45.0 - 15.0 * progress + 0.5 * open_bins_count as f64;
        // If lookahead pairs nicely with this item in a fresh bin, encourage it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;

    // Base: penalize leftover residual, smoothed by progress
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear coupling: residual squared normalized, amplified late in stream
    score += 0.3 * (pr * pr / cap) * (0.5 + progress);

    // Reward tight fits (high fill) with smooth saturating term
    score -= 8.0 * fill * fill * (1.0 + progress);

    // Dead-space penalty: residuals too small for typical items
    let dead = (1.0 - (pr / 40.0).min(1.0)) * (1.0 - fill);
    score += 5.0 * dead * dead;

    // Lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0 * (1.0 - ((pr - ni) / cap)) * (0.5 + progress);
        } else {
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 + progress);
    }

    // New-bin candidate: mildly discourage early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 4.0 * progress;
        if pr > 0.0 && pr < 20.0 { score += 5.0; }
    }

    // Mean residual coupling: prefer bins near mean to preserve spread
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls on "nice" divisors
    // of capacity (50, 33/34, 25, 20, 10) are more reusable -> reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is king
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr % 50 == 0 {
        score -= 18.0;
    } else if pr % 25 == 0 {
        score -= 12.0;
    } else if pr % 20 == 0 {
        score -= 10.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else {
        // dead-space penalty for awkward residuals
        score += 8.0;
        // extra penalty in the "unfillable" band (small but not tiny)
        if pr < 20 {
            score += 15.0;
        }
    }

    // Lookahead: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // chain a perfect follow-up
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 {
                score -= 10.0;
            } else if gap > 50 {
                score += 6.0; // next item leaves huge hole anyway
            }
        } else {
            // next item won't fit here; slightly prefer filling elsewhere
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this bin's residual is awkward.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let crowding = mean_residual / bin_capacity as f64;
        // fresh bin baseline: its residual equals capacity, already low score;
        // penalize opening new bins when existing bins are healthy.
        score += 20.0 + 10.0 * crowding + 0.5 * pressure;
        // late in stream, prefer consolidating into open bins
        if total_items > 0 {
            let t = step_index as f64 / total_items as f64;
            score += 25.0 * t;
        }
    }

    // Mild preference to balance residuals toward the mean (avoid many
    // nearly-full bins plus one huge bin).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold typical items (>= 10) are pure waste -> heavy penalty.
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    }

    // Non-linear penalty on wasted residual scaled by fill ratio.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Lookahead: reward if the post residual can hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual left that next item cannot use -> mild dead-space penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating
    // into existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open,
        // and when the item could have fit elsewhere.
        score += 45.0 + open_pressure;
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    } else {
        score -= open_pressure * 0.5;
    }

    // Mean residual coupling: if open bins are generally loose (high mean
    // residual), opening a new bin is wasteful; tighten existing bins.
    if bin_residual != bin_capacity {
        if mean_residual > item_size as f64 * 1.5 {
            score -= 10.0;
        } else if mean_residual < item_size as f64 * 0.75 {
            score += 6.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for
    // better long-run structure; late, squeeze everything in.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: item + next item fills bin
        } else if post_residual >= next_item_size {
            score -= 12.0; // next item can follow in this bin
        } else {
            // next item won't fit: penalize proportional to wasted gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
        // bonus if next item fits exactly in the residual BEFORE placing (alternative chaining)
        if bin_residual - item_size == next_item_size {
            score -= 5.0;
        }
    }

    // Relative to mean residual: prefer bins that are already below-average residual
    // (i.e. fuller bins) to concentrate packing
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bin unattractive unless current
    // fit is terrible (large dead space) or stream is early
    if bin_residual == bin_capacity {
        let dead = (bin_capacity - item_size) as f64;
        // empty bin baseline: cost proportional to dead space created
        score = dead * 0.9 + 10.0;
        // early in stream, new bins are cheaper (more future to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 8.0;
        // if next item is large and won't pair well, opening fresh bin is fine
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0;
        }
        // many open bins: discourage adding another
        score += open_bins_count as f64 * 1.5;
    }

    // Small tie-breaker toward using fewer bins overall
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose residual is close to item size.
    score -= (bin_residual as f64 - item_size as f64).abs() * 0.35;

    // Penalize dead space that is too small for typical items (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; mild penalty scaled by mismatch.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with below-mean residual (consolidating fuller bins).
    score -= (mean_residual - bin_residual as f64) * 0.12;

    // New-bin candidate handling: opening a new bin is wasteful unless current
    // fits are all poor and the stream is early enough to amortize.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = (bin_residual - item_size).abs() as f64 > 30.0;
        if poor_fits && progress < 0.85 {
            score -= 12.0 * (1.0 - progress);
        } else {
            score += 20.0;
        }
    }

    // Slight preference for fewer open bins (bin consolidation pressure).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = (1.0 - t) * 0.35 + t * t * 0.25;
    score += poly * pr * (1.0 - fit);

    // Reward tight fits (small post_residual) increasingly as stream progresses
    score -= (1.0 - fit) * (1.0 - fit) * (30.0 + 40.0 * t);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * t;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Penalize divergence from mean residual (keeps bins balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty early, decreasing later
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - t) - 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: classify dead space
    // into modulo bands of capacity/10. Small post_residual classes are good.
    let class = post_residual % (bin_capacity / 10).max(1);
    score += class as f64 * 0.35;

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves another residual; penalize by leftover
            let next_left = post_residual - next_item_size;
            score -= 20.0 - (next_left as f64) * 0.3;
        } else {
            // next item cannot fit here: penalize bins that strand space
            score += (post_residual as f64) * 0.25;
        }
    }

    // Harmonic integer-division thresholds on post_residual:
    // residuals in (0,10] are excellent; (10,25] acceptable; larger is waste.
    if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 25 {
        score -= 5.0;
    } else if post_residual > 40 {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin leaves large waste
    // or no open bin fits well. Penalize opening new bins mildly by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 25.0 * (1.0 - progress);
        // If item is large relative to capacity, a fresh bin is fine
        if item_size * 4 >= bin_capacity * 3 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size > post_residual.max(item_size) {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins overall (compare against mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Prefer filling bins that are already mostly full (small residual).
    score += (bin_residual as f64) * 0.08;

    // Slight penalty when many bins are open to encourage consolidation.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size) are worst.
    if post_residual < 10 {
        score -= 200.0; // filling a bin nearly perfectly is excellent
    } else if post_residual < 20 {
        score += 40.0; // small gap likely dead space
    } else if post_residual < 35 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Pressure from number of open bins: discourage spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins already open.
        score += 60.0 + 3.0 * bin_pressure;
        // But if no existing bin fits well, allow opening: handled by others scoring worse.
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    } else {
        score -= 1.0 * bin_pressure; // reward reusing open bins
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += (next_item_size as f64 - post_residual as f64).min(25.0);
    }

    // Prefer bins tighter than average (best-fit bias).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot follow here; penalize wasted residual
            score += 0.35 * post_residual as f64;
        }
    } else {
        // last item: prefer tightest fit (post_residual already does this)
    }

    // Penalize large dead space relative to mean residual of open bins
    score += 0.15 * ((post_residual as f64 - mean_residual).max(0.0));

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer packing into existing bins as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress;

    // Slight penalty when many bins already open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    // Brand-new bin candidate: only attractive when item nearly fills it or nothing fits well elsewhere
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.75 {
            score -= 20.0 * (fill_ratio - 0.75) / 0.25;
        } else {
            score += 15.0 * (1.0 - fill_ratio);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: residuals too small for the smallest item are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, mild penalty for wasting a scarce-fit bin elsewhere.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Extra reward if next item nearly fills the remaining space.
            let next_leftover = post_residual - next_item_size;
            if next_leftover < 10 {
                score -= 8.0;
            }
        } else if next_item_size > post_residual && next_item_size <= bin_capacity {
            // Next item won't fit here; penalize leaving awkward gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Global state: if mean residual is high, prefer using fuller bins
    // (keep spread-out space consolidated for large future items).
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel > 1.0 {
            score += (rel - 1.0) * 4.0;
        } else {
            score -= (1.0 - rel) * 4.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (favor tight packing
    // less aggressively to keep flexible bins); late in stream, close bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= tightness * progress * 10.0;

    // Many open bins: encourage consolidation into existing bins over new bins.
    score += (open_bins_count as f64) * 0.5;

    // New-bin candidate: penalize opening a new bin unless item is large relative
    // to typical residuals or no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 60 {
            score -= 15.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: quadratic + cubic shaping of post residual
    let x = pr / cap; // normalized post residual in [0,1]
    score += 12.0 * x * x - 20.0 * x * x * x;

    // Stream progress interaction: late in stream, tolerate less residual waste
    let late = progress * progress;
    score += 15.0 * late * x;

    // Dead-space penalty: residual too small for smallest plausible next item
    if pr < 10.0 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let tight = 1.0 - (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * fits * (0.5 + 0.5 * tight.max(0.0));
    }

    // Last-chance bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Prefer bins with residuals close to the current item (tight fit)
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 6.0 * tightness * tightness;

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64;

    // Mean residual coupling: avoid bins deviating far from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that lie in "usable"
    // classes (small dead space, or exactly reusable by common item sizes).
    let pr = post_residual as u32;
    let q = pr / 10; // integer-division class (0..10)
    let r = pr % 10; // remainder class

    // Class 0: perfect fit -> huge reward
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= 10 {
        // tiny dead space: strongly reward
        score -= 60.0 + (10 - pr) as f64 * 4.0;
    } else if pr <= 20 {
        // class q=1,2: often reusable by small items (sizes 1..20)
        score -= 25.0 - r as f64 * 0.5;
    } else if pr <= 30 {
        score -= 12.0;
    } else if pr <= 50 {
        // mid residuals: moderately reusable
        score -= 5.0 + ((50 - pr) as f64) * 0.3;
    } else {
        // large waste: penalize proportionally to fraction of capacity wasted
        score += (pr as f64 / cap) * 40.0;
    }

    // Modulo-10 remainder classes: residuals with small remainder pack better
    // against typical integer sizes (divisible by 10).
    if r == 0 {
        score -= 8.0;
    } else {
        score += r as f64 * 0.8;
    }

    // Lookahead: if next item fits into post_residual, big reward (chained fit)
    if next_item_size > 0 && next_item_size <= pr {
        score -= 30.0 + (pr - next_item_size) as f64 * 0.5;
    }
    // If next item almost fits (within 10), mild reward
    if next_item_size > 0 && next_item_size > pr && next_item_size - pr <= 10 && pr > 0 {
        score -= 6.0;
    }
    // If next item cannot use post_residual at all, penalize leaving large gap
    if next_item_size > 0 && pr > 0 && next_item_size > pr && pr > 20 {
        score += (pr as f64) * 0.15;
    }

    // Last-chance bin: this is the only bin that fits -> strong reward to avoid new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: keep it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; scales with how many bins already open.
        score = cap * 0.9 + open_bins_count as f64 * 1.5;
        // Early in stream, opening bins is cheaper (need spread of bins).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        // If item is large (few future fits likely), new bin more attractive
        if item_size > 50 {
            score -= 15.0;
        }
        // If many bins can fit, less need for a new bin
        score += fitting_bins_count as f64 * 6.0;
    }

    // Mean residual coupling: placing into a bin far from mean residual
    // balances load; reward closeness to mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Slight preference for tighter bins early (best-fit bias) modulated by progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (bin_residual as f64 / cap) * (5.0 + progress * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable -> heavy penalty.
    let pr = post_residual as f64;
    if post_residual > 0 {
        if post_residual <= 12 {
            score += 45.0 * (13.0 - pr) / 12.0; // dead zone: 1..=12
        } else if post_residual < 20 {
            score += 18.0 * (20.0 - pr) / 8.0; // risky small gap
        } else {
            score -= 8.0 * (pr / bin_capacity as f64); // usable residual: reward
        }
    } else {
        score -= 30.0; // perfect fit is ideal
    }

    // Tightness reward: filling most of the bin is good.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Open-bin pressure: prefer packing into existing bins when many are open.
    score += 0.35 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item is large and this placement leaves a small gap, penalize.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual <= 15 {
        score += 12.0;
    }

    // New-bin candidate: opening a new bin is only acceptable when no decent fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open
        } else if mean_residual >= item_size as f64 + 15.0 {
            score -= 5.0; // existing bins are roomy enough anyway
        } else {
            score += 25.0; // prefer squeezing into existing bins
        }
    }

    // Late-stream consolidation: near the end, fill existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 6.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward near-zero post residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in leftover: penalize large dead space.
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins whose residual is larger than average
    // (drain large leftover bins) but avoid wasting a tight bin.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate penalty: only open a new bin when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit = post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual);
        if !good_fit {
            score += 150.0;
        } else {
            score += 50.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for loose fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear waste penalty
    let waste = post_residual as f64;
    score += 0.35 * (waste / 100.0).powi(2) * 100.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this bin stays useful
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fills the bin completely afterward
            if post_residual - next_item_size < 10 {
                score -= 15.0;
            }
        } else {
            // Dead space relative to the next item's needs
            score += 0.25 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: only attractive when open bins are fragmented or fit is poor
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let fragmentation = (mean_residual - waste).abs();
        // Penalize opening new bins early / when few bins open
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Reward opening a new bin when existing residuals are large & unusable
        if mean_residual < item_size as f64 * 0.5 {
            score -= 55.0;
        }
        if fragmentation > 40.0 {
            score -= 10.0;
        }
        // Late in stream, opening fresh bins is more acceptable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Mild global-state coupling: prefer consolidating into bins with below-mean residual
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let p = progress;
    // Dead-space penalty grows super-linearly as the stream progresses
    // (waste matters more later), scaled by bin capacity.
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (0.5 + 2.0 * p) + norm_pr * (0.2 + 1.5 * p * p);
    score += poly * 10.0;

    // Reward tight fits: quadratic bonus for small post_residual.
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + p);

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: penalize leaving residual that neither fits the next item well
    // nor is comfortably large.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            // Next item can't use this residual: waste penalty, stronger late.
            score += (ns - pr) * (0.05 + 0.15 * p);
        } else {
            // Next item fits: reward, especially if it nearly fills residual.
            let after = pr - ns;
            score -= (1.0 - after / cap) * 3.0 * (0.5 + p);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and existing bins are quite full.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let mean_fullness = 1.0 - mean_residual / cap;
        score += 20.0
            - 10.0 * fill_ratio * fill_ratio
            - 8.0 * mean_fullness * mean_fullness
            + 5.0 * (1.0 - p);
    }

    // Mild preference for bins tighter than average.
    score += 0.05 * (pr - mean_residual);

    // Slight penalty for proliferating open bins early in the stream.
    score += 0.02 * open_bins_count as f64 * (1.0 - p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small leftovers are dangerous dead space
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny unusable sliver
    } else if pr < 20 {
        score += 25.0;
    } else if pr < 35 {
        score += 5.0;
    }

    // Modulo-class coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0; // chain a perfect follow-up
        } else if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.5;
            // harmonic residue classes: next item leaves another friendly residual
            let nxt_left = pr - next_item_size;
            if nxt_left < 10 { score += 20.0; }
        } else {
            // next item cannot use this residual; penalize if residual is odd-class / awkward
            if pr % 2 == 1 { score += 8.0; }
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 60.0 * pressure * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // large stream of big items: fresh bins fine
        }
    }

    // Prefer filling bins with high residual relative to mean (consolidation)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Integer-division thresholds on post_residual: reward "half-bin" friendly states
    if pr == bin_capacity / 2 {
        score -= 40.0;
    } else if pr >= bin_capacity / 2 {
        score -= 10.0;
    }

    // Few open bins: slightly favor compacting into them
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 30.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening yet another;
    // when few bins are open, opening a fresh bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score = 30.0 + pressure * 2.5;
        // Attractive if lookahead item could use a fresh bin better than leftovers here.
        if next_item_size > 0 && next_item_size > post_residual.max(1) && post_residual < next_item_size {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins whose residual is below mean (consolidating waste).
        if (post_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer residuals just above next_item_size
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; residual becomes dead space
            score += 20.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small unusable residuals relative to item domain (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect packing
    }

    // Compare against mean residual of open bins: keep tight bins tight.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // big items coming, fresh bin useful
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual is good, but a tiny unusable sliver
    // (< 10) is essentially waste; keep base post_residual as the main driver.

    // Lookahead: reward if the next item also fits in the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }
    // Penalize if next item is slightly larger than post residual (near-miss creates
    // a stranded bin while next item must go elsewhere).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global fragmentation pressure: if mean residual is high and open bins are many,
    // prefer filling existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 0.3 * mean_residual * (open_bins_count as f64 / 10.0).min(2.0);
        score += 8.0 * (1.0 - progress); // early on, be a bit pickier about bad fits
    }

    // New-bin candidate: only attractive when existing residuals are too small or
    // item is large relative to typical residual.
    if bin_residual == bin_capacity {
        let avg_badness = mean_residual - item_size as f64;
        if avg_badness < 5.0 && fitting_bins_count > 0 {
            score -= 15.0; // open a fresh bin when fits are all poor
        } else {
            score += 20.0 + open_bins_count as f64 * 2.0; // discourage sprawl
        }
        // Large items early: opening a bin for a big item is fine.
        if item_size >= 60 && progress < 0.5 {
            score -= 10.0;
        }
    }

    // Small coupling: prefer bins whose residual is close to mean (keep residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual.max(0.0);

    // Base: post residual (waste), non-linearly coupled with progress.
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Reward tight fits: penalize when item fills most of the bin.
    let fill = it / cap;
    score -= 18.0 * fill * fill * (1.0 + 0.5 * progress);

    // Penalize residual relative to mean residual of open bins (dead space coupling).
    score += 0.12 * (pr - mean_r).abs() * (0.5 + progress);

    // Smooth quadratic coupling of post_residual with item size.
    score += 0.002 * pr * pr * (1.0 - fill);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits into post residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (nxt / cap) * (1.0 + 0.4 * (1.0 - progress));
        } else {
            score += 3.0 * ((nxt - pr) / cap) * progress;
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // more strongly when other bins fit and this one is empty.
    if bin_residual == bin_capacity {
        let open_bonus = if fitting_bins_count > 0 { 10.0 + 8.0 * (1.0 - progress) } else { 2.0 };
        score += open_bonus;
        // Empty-bin residual is large; its base already reflects that, but
        // smooth the penalty with progress so late streams prefer consolidation.
        score += 6.0 * (1.0 - progress) * (1.0 - fill);
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: multiples of 10 are "usable" residues.
    let pr = post_residual as u32;
    let harmonic = pr % 10;
    score += harmonic as f64 * 1.5;

    // Perfect fill is excellent.
    if pr == 0 {
        score -= 40.0;
    }

    // Small but non-zero leftovers are dead space (1..10 units).
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Mid-range leftovers (10..30) are still usable for typical items; reward.
    if pr >= 10 && pr <= 30 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            // Penalize leftovers that don't match harmonic classes of next item.
            score += (slack % 10) as f64 * 0.8;
            if slack < 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 4 {
        score -= 3.0;
    }

    // Compare against mean residual: bins with residual above mean are better targets.
    let residual_gap = (bin_residual as f64) - mean_residual;
    score -= residual_gap * 0.25;

    // Early in stream, be more willing to open new bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus adjustment.
        score = bin_capacity as f64 * 0.9;
        if item_size >= 60 && progress < 0.5 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size && next_item_size + item_size >= bin_capacity {
            score -= 20.0; // can pack next item tightly too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps that are too small for
    // typical future items are pure waste. Penalize unusable gaps quadratically.
    let min_item = 1.0;
    if (post_residual as f64) < mean_residual.max(min_item) {
        // gap below mean residual is likely unusable dead space
        let dead = (mean_residual - post_residual as f64).max(0.0);
        score += 1.5 * dead * dead / (bin_capacity as f64);
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 2 {
        score -= 20.0;
    }

    // Reward tight fits: small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 5.0 * tightness * tightness;

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    // and this bin is a new-bin candidate.
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost of a new bin
        score = (bin_capacity as f64) * 0.9 + 2.0 * open_bins_count as f64;
        // If lookahead item fits nicely into this fresh bin, keep it attractive
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // neutral
        }
        // During early stream, new bins are necessary; later, avoid them
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item exactly fills post_residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot fit here anyway; small dead-space penalty if gap tiny
        if post_residual < next_item_size && post_residual < 10 {
            score += 3.0;
        }
    }

    // Mild preference for more-filled bins (lower residual before placement)
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Post residual can still host the next item: reward tight coupling.
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the dead space left behind: penalize waste.
        let waste = (next_item_size - post_residual) as f64;
        score += 25.0 * (waste / bin_capacity as f64);
    }

    // Reward using bins whose residual is tighter than average (good fits).
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Last-chance bin: strongly favor filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable fragments (< 10, smallest item size).
    if post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that are too small to ever be useful (dead space)
        if post_residual < 10 {
            score += 80.0;
        }
        // Reward residuals that can accommodate typical future items
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 30.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // If next item won't fit in post_residual, penalize proportionally
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = item_size as f64; // perfect fit leaves 0
        let waste = (bin_capacity - item_size) as f64;
        // Penalize new bin; discount penalty when item is large (little waste anyway)
        score += 120.0 - waste * 0.5;
        // If open bins are fragmented (high mean residual but none tight), new bin more attractive
        score -= mean_residual * 0.2;
        if post_residual as f64 > mean_residual {
            score += 40.0;
        }
        let _ = best_possible;
    } else {
        // Reward using already-open bins to avoid bin proliferation
        score -= 20.0;
        // Prefer the bin whose residual is closest above the item (tightness)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.1;
    }

    // Dynamic time horizon: early in stream, be conservative with open bins;
    // late in stream, squeeze into existing bins harder
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score -= progress * 25.0;
    } else {
        score += progress * 15.0;
    }

    // Many open bins: prefer consolidation into existing bins
    score += (open_bins_count as f64).ln().max(0.0) * 5.0 * if is_new_bin { 1.0 } else { -0.5 };

    // Mild preference for bins with residual above mean (keeps balance)
    if !is_new_bin {
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 0.35 * (pr * pr) / cap
        - 0.15 * (pr * pr * pr) / (cap * cap) * (1.0 - progress)
        + 0.25 * pr * progress;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.4 * waste * (1.0 - progress);
        if pr >= next_item_size as f64 {
            score -= 6.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild preference toward consolidating into existing bins when many are open
    score += 0.02 * open_bins_count as f64 * (pr / cap);

    // Nudge toward mean-residual alignment (smooth coupling)
    score += 0.1 * (pr - mean_residual).abs() * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening a bin unless residual is very small
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction classes
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: zero waste is ideal
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Class of the leftover: which capacity-fraction bucket does it fall into?
        // Classes: (0,10], (10,25], (25,50], (50,100]
        let class = if post_residual <= 10 { 0 }
                    else if post_residual <= 25 { 1 }
                    else if post_residual <= 50 { 2 }
                    else { 3 };
        score += match class {
            0 => -30.0,               // tiny leftover is nearly a perfect fit
            1 => 5.0,                 // small dead space
            2 => 15.0,                // medium leftover
            _ => -10.0,               // large leftover is still usable
        };

        // Reward if next item exactly fills the leftover (modulo / equality coupling)
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 120.0;       // chain a perfect fit
            } else if next_item_size <= post_residual {
                // next item fits: leftover class after chaining
                let chain_post = post_residual - next_item_size;
                if chain_post <= 10 {
                    score -= 45.0;
                } else {
                    score -= (chain_post as f64) * 0.2;
                }
            } else {
                // next item cannot use this leftover: penalize proportionally
                score += (next_item_size.min(bin_residual) as f64) * 0.15;
            }
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer bins tighter than the mean residual (harmonic coupling to mean)
    score += (post - mean_residual) * 0.5;

    // Prefer using more-open bins early vs late (progress coupling)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 {
        score -= 20.0 * (1.0 - progress); // consolidate small leftovers early
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty; relax if many open bins exist (crowding) or no fit
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        } else if open_bins_count > 0 {
            // discourage new bin when open bins can fit, more so late in stream
            score += 40.0 * progress;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 25.0; // big next item: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to be useful
    // for typical future items are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 100.0;
    }

    // Penalize post_residual that cannot fit the lookahead item (wasted space
    // relative to what's coming next).
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        } else {
            score -= 0.3 * (post_residual as f64 - next_item_size as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins should be discouraged.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 25.0 + 8.0 * bin_pressure + 20.0 * progress;
        // Allow opening a new bin if no existing bin fits well (last-chance logic inverse).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strongly favor using it.
        score -= 35.0;
    }

    // Slight bonus for bins tighter than the mean residual (good packing density).
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: reward if the next item exactly fills post_residual
    // (perfect chaining), scaled by lookahead magnitude.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus
        if post_residual == next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else if next_item_size as u32 <= post_residual {
            // Next item fits here: mild reward proportional to closeness
            score -= 15.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // Next item won't fit in this bin's leftover: penalize large dead space
            score += 0.3 * diff;
        }
