    // Penalize post_residual that is too small to ever be useful
    // (items are >= 1, but tiny slivers are dead space relative to typical sizes).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: placing into a bin with residual above the
    // mean keeps the residual distribution tighter (better future fits).
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // New-bin candidate logic: an empty bin is attractive when current fit is
    // poor (large post_residual) or when many bins are open with slack.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin, offset by avoiding bad fits.
        let open_penalty = 8.0 + 0.05 * open_bins_count as f64;
        // If the item fits poorly in existing bins (post_residual large), new bin looks good.
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        score = open_penalty + fit_quality * 40.0;
        if fitting_bins_count == 1 {
            // Existing bin is a last chance: discourage new bin unless fit is terrible.
            score += 35.0;
        }
        if next_item_size > 0 && next_item_size as u32 > post_residual {
            // New bin gives next item more room.
            score -= 10.0;
        }
    }

    // Slight stream-progress term: early on, be more willing to open bins
    // (long stream ahead rewards keeping residuals clean).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

