    }

    // Dead-space penalty: small post_residual that nothing can fill
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
