    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // Penalize if next item almost fits but not quite (wasted potential)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Penalize opening a new bin when good fits exist, scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 - 30.0 * progress;
        // New bin more attractive if mean residual is small (bins nearly full)
        score -= (mean_residual / bin_capacity as f64) * 40.0;
        // Few fitting bins => new bin more acceptable
        score -= (fitting_bins_count as f64).min(5.0) * 8.0;
    }

    // Mild preference for filling bins with larger residuals when many bins open
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Slight bonus for consolidating when many bins are open
    if open_bins_count > 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling between post_residual and stream progress.
    // Early stream: prefer filling bins with large post-residuals (keep space flexible).
    // Late stream: prefer tight fits (small post_residual) to close bins cleanly.
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - pr_norm); // peaks at mid residuals
    score += poly * (1.0 - progress) * 20.0;        // reward mid-space bins early
    score -= poly * progress * 15.0;                // reward mid-space bins late (relative)

    // Tight-fit reward: strongly favor small post_residual, amplified by progress.
    let tight = (1.0 - pr_norm).powi(3);
    score -= tight * (5.0 + 25.0 * progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 && post_residual > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + 0.5 * progress);
        } else {
            // leftover after lookahead would fit: mild reward
            let after2 = pr - nx;
            score -= 2.0 * (1.0 - (after2 / cap).powi(2));
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // New-bin candidate: make it moderately attractive only when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - it).max(0.0);
        score = cap - 4.0 + poor_fits * 0.3 - 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
