        } else {
            // Large leftover: penalize proportionally, but modulate by its
            // harmonic class (residual mod 10): round classes (0,5) are more
            // likely to be reusable by future items.
            let class = post_residual % 10;
            let class_bonus: f64 = match class {
                0 => 12.0,
                5 => 8.0,
                1 | 9 => 2.0,
                _ => 0.0,
            };
            score += (pr / cap) * 40.0 - class_bonus;
        }
    }

    // Coupling with the lookahead item: if the next item fits exactly into
    // post_residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Fits, but leaves another leftover: reward if combined class is clean.
            let chain_left = post_residual - next_item_size;
            if chain_left < 10 { score -= 40.0; }
            else if chain_left % 10 == 0 { score -= 25.0; }
            else { score -= (chain_left as f64) * 0.3; }
        } else {
            // Next item cannot use this bin's leftover: penalize large leftovers
            // that are stranded relative to the lookahead.
            if post_residual >= 10 {
                score += (post_residual - next_item_size.min(post_residual)) as f64 * 0.15;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline penalty so we only open new bins when genuinely useful.
        score += 30.0;
        // If many bins can fit the item, prefer reusing one of them.
        if fitting_bins_count > 0 {
            score += 45.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 25.0;
    }

    // Prefer bins whose residual is below the mean (filling the emptiest first
    // consolidates dead space), modulated by stream progress.
    let dev = mean_residual - pr;
    score += dev * 0.25;

    // Mild pressure to keep the number of open bins low late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    // Small tie-breaker on tightness of fit.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Assume typical item sizes >= 10; residual below 10 is pure dead space.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward near-perfect packing (small but nonzero leftover).
    if post_residual > 0 && post_residual <= 5 {
        score -= 15.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    }

    // Dead-space coupling: penalize leaving a gap just below next item size
    // (gap that next item cannot use).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
    }
    // Reward leaving room exactly usable by the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, discourage spreading to new bins,
    // but with few open bins allow opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 25.0 + pressure * 12.0;
        // Prefer new bin if mean residual across open bins is small (they are full-ish).
        score -= (mean_residual * 0.2).min(15.0);
    } else {
        // Existing bin: mild reward to consolidate, scaled by pressure.
        score -= pressure * 2.0;
    }

    // Early in stream, be pickier about dead space (long horizon left).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.0 - progress) * 20.0;
    }

    // Penalize wasting a large bin on a tiny item when other bins exist.
    if post_residual as f64 > mean_residual + 30.0 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect chain: next item fills bin exactly afterwards.
            if gap == 0.0 {
                score -= 500.0;
            } else if gap <= 10.0 {
                score -= 150.0 - gap * 5.0;
            } else {
                score -= (100.0 / (1.0 + gap)).max(0.0);
            }
        } else {
            // Next item won't fit here: penalize proportional to leftover dead space.
            score += (nxt - post_residual as f64) * 2.0;
        }
        // Coupling with mean residual: prefer bins below mean residual (tighter packing).
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize mildly so we only open new bins when fits are poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if lookahead suggests a fresh bin enables a perfect pair, discount it.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 300.0;
        }
    }

    // Mild late-stream consolidation: prefer filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost
    let tightness = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score += 20.0 * tightness;

    // Penalize dead space that cannot fit even a minimum future item
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 50.0; // perfect fit bonus
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't chain here; penalize proportionally to wasted chain potential
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // more competition -> mild penalty to spread load
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: prefer bins below mean residual (balance across bins)
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_diff;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, allow more aggressive consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate adjustment: opening a new bin is only attractive when
    // existing bins would leave large dead space and stream is early
    if bin_residual == bin_capacity {
        let best_alternative_dead = post_residual as f64; // post_residual == capacity here
        let early_bias = 1.0 - 0.5 * progress;
        score = best_alternative_dead + 10.0 * early_bias + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin may serve it well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: small residuals are dead space; penalize quadratically.
    let prn = pr / cap;
    score += 12.0 * (1.0 - prn) * (1.0 - prn) * prn * cap * 0.25;

    // Smooth interaction: as stream progresses, tighter fits matter more.
    score -= (1.0 - prn).powi(2) * (10.0 + 20.0 * progress);

    // Lookahead coupling: reward residuals that can host the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - nx).abs() / cap);
        score -= 6.0 * fits_next * closeness * closeness;
        score += 4.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits — strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild preference for bins below mean residual (consolidate fullness).
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: keep it slightly less attractive than a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: subtract a bonus proportional to fill, stronger when post_residual is tiny
    score -= 30.0 * fill;

    // Harmonic class of post_residual: dead space that nothing (min size 1) can use is worst.
    // Classify post_residual into buckets via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 35.0; // near-perfect, likely dead but tiny
    } else if post_residual <= 15 {
        score += 10.0; // awkward dead zone
    } else if post_residual <= 30 {
        score -= 5.0; // usable by small items
    }

    // Modulo arithmetic on post_residual: residuals matching common item sizes are reusable
    let reusable = |r: u32| -> bool {
        r % 10 == 0 || r % 25 == 0 || r == 20 || r == 40 || r == 50
    };
    if reusable(post_residual) {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 25.0;
            }
            if reusable(next_post) {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize slightly so bins that chain better win
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Avoid wasting a nearly-empty new bin's purpose: opening new bin should win only
    // when existing residuals are badly fragmented. Compare against mean_residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: its post_residual = capacity - item_size
        // Prefer new bin when open bins are already fragmented (high mean residual spread)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 * (1.0 - progress); // early on, prefer reusing open bins
        if mean_residual > 40.0 {
            score += 10.0; // fragmentation high, new bin less attractive
        }
        if post_residual <= 20 {
            score -= 15.0; // big item in fresh bin leaves little waste
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (tighter bins first)
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 20.0 * dev; // smaller residual than mean => lower score => preferred
    }

    // Mild pressure against accumulating many open bins with large residuals
    if open_bins_count > 8 && post_residual > 50 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (min size 1..10, but practically small gaps)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // gap 1 => +55, gap 9 => +15
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits proportionally to fill ratio.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill;
        // Non-linear coupling: penalize leaving medium-sized awkward gaps.
        let pr = post_residual as f64;
        score += 0.15 * (pr * pr) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins => discourage spreading, prefer
    // consolidating into existing bins; fewer bins => allow opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline competitive score, adjusted by pressure.
        score = bin_capacity as f64 * 0.5 + 10.0 * pressure - 15.0;
        // If next item is large and current item is small, opening a fresh
        // bin may be attractive (preserve large gaps for large items).
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 8.0;
        }
    } else {
        // Existing bin: slight penalty when many bins are already open
        // and this bin's residual is far from mean (outlier gap).
        score += 2.0 * pressure;
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; leaving a large unusable-for-next gap
        // is mildly penalized.
        score += 3.0;
    }

    // Stream progression: late in the stream, be greedier about tight fits.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 5.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        score -= 60.0 * (1.0 - gap / cap).max(0.0);
        if post_residual as f64 == nxt {
            score -= 100.0; // perfect chain: this bin closes exactly with next item
        }
        // penalize post_residual too small for next item (dead space)
        if (post_residual as u32) < next_item_size {
            score += 25.0 * (1.0 - post_residual as f64 / cap);
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are better targets
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening new bins when decent fits exist: new bin has bin_residual == bin_capacity
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * progress;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 20.0; // pairing identical items in a fresh bin is fine
        }
    }

    // Prefer tighter fits generally
    score += 0.3 * (post_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best, but penalize
    // "just barely fits" less than large leftovers quadratically.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that is too small to be useful later
    // (typical item sizes make small residuals nearly unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item exactly fills the post-residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is
    // large or the open bins are crowded (high mean residual usage).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_large = item_size as f64 / bin_capacity as f64;
        // New bins are more attractive early and for large items.
        score += 30.0 - 25.0 * item_large - 10.0 * (1.0 - progress) - 15.0 * pressure;
        // If many bins can fit the item, opening new is wasteful.
        score += 5.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Slight preference for filling bins that are already mostly full,
    // keeping many medium-residual bins available for future items.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fullness;

    // Mild penalty when many bins are open: consolidate to limit sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual, scaled non-linearly (dead space hurts more when small).
    let mut score = pr * (1.0 + 0.5 * (pr / cap) * (pr / cap));

    // Smooth non-linear coupling of residual with stream progress:
    // early on tolerate residual; late in stream penalize it more.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += 0.3 * progress_coupling;

    // Reward tight fits: quadratic bonus as post_residual approaches 0.
    score -= 8.0 * (1.0 - pr / cap).powi(4);

    // Penalize bins whose residual deviates strongly from the mean residual
    // (keeps residual distribution homogeneous for future packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev;

    // Lookahead: reward bins whose post-residual matches next item size.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = (pr - nx) / cap;
            score -= 4.0 * (1.0 - gap).powi(3);
        } else {
            // post-residual too small for next item: mild penalty scaled by wasted fraction
            score += 3.0 * (pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: prefer it only when open-bin set is very fragmented
    // or the fit is poor; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fit = (it / cap) * (1.0 - (pr / cap));
        score += 5.0 * (1.0 - fragmentation) + 3.0 * (1.0 - poor_fit);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "clean" is the leftover space?
    let pr = post_residual;
    let mod10 = pr % 10;
    let mod5 = pr % 5;

    // Reward post-residuals that are multiples of 10 (likely reusable by common sizes)
    if mod10 == 0 {
        score -= 6.0;
    } else if mod5 == 0 {
        score -= 3.0;
    } else {
        score += (5 - mod5) as f64 * 0.8; // penalize awkward leftovers
    }

    // Dead-space penalty: tiny leftovers are wasted capacity
    if pr < 10 {
        score += 12.0;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item consumes most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Harmonic match: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 4.0;
            // divisible-harmony: pr is a multiple of next item
            if next_item_size > 0 && pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening bins early, more so early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 20.0 * (1.0 - progress);
        // But allow new bin if existing residuals are all too awkward for next item
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 18.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier bins)
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Threshold on integer division of residual: quarter classes
    let quarter = pr / 25;
    score += [0.0, 1.0, 2.0, 3.0, 4.0][quarter.min(4) as usize] * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 {
        let usable = next_item_size != 0 && post_residual >= next_item_size;
        if !usable {
            // Gap too small for the lookahead item -> likely permanent waste.
            let gap_frac = post_residual as f64 / bin_capacity as f64;
            score += (1.0 - gap_frac) * 120.0; // small gaps penalized more than large ones
        }
    }

    // Exact match with lookahead: reward chaining.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open bins pressure: prefer filling existing bins when many are open,
    // but tolerate new bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 + 8.0 * progress);

    // Prefer bins with residual below the mean (tighter bins fill first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for large items into tight bins (waste-aware).
    score -= item_size as f64 * 0.1;

    // New-bin candidate baseline: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 5.0 - 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly prefer bins whose post_residual matches next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this one: reward closeness of match
            let gap = (post_residual - next_item_size) as f64;
            score -= (30.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit in residual: penalize wasted lookahead opportunity
            let shortfall = (next_item_size - post_residual) as f64;
            score += (shortfall / 40.0).min(25.0);
        }
    }

    // Tight packing reward: small post_residual is good, scaled by bin usage
    let usage = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * usage * usage;

    // Relative-to-mean residual coupling: prefer bins with residuals near the mean
    // (keeps residual distribution uniform, eases future packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += (dev / 50.0).min(20.0);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a
    // near-perfect 2-step chain (item + next item almost fill it)
    if bin_residual == bin_capacity {
        let chain = item_size as f64 + next_item_size as f64;
        if next_item_size > 0 && chain >= 0.92 * bin_capacity as f64 {
            score -= 70.0; // opening a new bin is great for a full chain
        } else {
            score += 55.0; // otherwise prefer existing bins
        }
    }

    // Early-stream exploration: fewer open bins means less fragmentation risk;
    // slightly prefer new bins early, existing bins later
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Dead-space penalty: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is exponentially valuable).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 12 {
        score -= 15.0;
    }

    // Penalize dead space that is too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if next item fits into the post-residual, big bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = 1.0 - (next_item_size as f64 / post_residual.max(1) as f64).abs();
        score -= 30.0 + 25.0 * chain;
    } else if next_item_size > 0 {
        // Next item won't chain: mildly penalize leaving a mid-range gap.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: prefer consolidating into existing space rather than spreading.
    if open_bins_count > 3 {
        score -= 5.0 * ((open_bins_count as f64).ln() + 1.0);
    }

    // Time horizon: early in stream, be pickier about tight fits; late, just close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * (1.0 - progress) * fill_ratio;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin is far below mean residual (already tight),
    // finishing it is good; if far above mean (very roomy), discourage wasting it.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 55.0 + 0.5 * mean_residual;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let shape = 1.0 + 0.6 * t - 1.2 * t * t + 0.8 * t * t * t;
    score *= shape;

    // Reward tight fits more strongly as the stream progresses
    score -= (cap - pr) * fit_frac * (0.5 + t);

    // Penalize creating small unusable dead space (non-linearly)
    if pr > 0.0 {
        let dead = fit_frac * (1.0 - fit_frac);
        score += 4.0 * dead * (1.0 - t);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * t;
    }

    // Lookahead: reward residual that could fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (pr - nx) / cap * (1.0 + t);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for bin proliferation late in the stream
    score += (open_bins_count as f64).sqrt() * 0.15 * t;

    // Deviation from mean residual: prefer near-average bins
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.07;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harsh penalty for small unusable gaps.
    let dead_zone: f64 = if post_residual > 0 && post_residual < 10 {
        40.0 + (10 - post_residual) as f64 * 8.0
    } else if post_residual == 0 {
        -30.0 // perfect fit
    } else {
        0.0
    };
    score += dead_zone;

    // Reward tight fits: post_residual small relative to item size.
    if item_size > 0 {
        score += 0.6 * post_residual as f64 * (item_size as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += pressure * post_residual as f64 * 0.15;

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space blocks the known next item
    }

    // New-bin candidate handling: make empty bin attractive only when
    // no open bin offers a good fit (mean residual too small).
    if bin_residual == bin_capacity {
        let scarcity = (mean_residual - item_size as f64).max(0.0);
        score = 20.0 + 10.0 * (1.0 - scarcity / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
        if open_bins_count as f64 > total_items as f64 * 0.02 {
            score += 15.0; // discourage bin proliferation
        }
    }

    // Mild progression term: early on, slightly prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * (1.0 - progress) * post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fills (post residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits into post_residual, big bonus.
    if next_item_size > 0 {
        let slack = post_residual as i64 - next_item_size as i64;
        if slack == 0 {
            score -= 40.0;
        } else if slack > 0 {
            // Reward proportional fit, penalize large leftover slack after next item.
            score -= 20.0 - (slack as f64).min(20.0);
        } else {
            // Next item won't fit here; penalize proportionally to the shortfall.
            score += (-slack as f64) * 0.35;
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins first).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize creating small unusable dead space relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact or near-exact placements get strong discounts.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 25.0 * fit_ratio * fit_ratio;
    }

    // Penalize small dead space that nothing can use (items >= 1, so residual 0 is fine;
    // small residuals like 1..3 are nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With several options, mild tie-breaking toward fullest bin (smallest residual).
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for leaving odd residuals.
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the current
    // fit is very poor (item small relative to residual, leaving huge waste) or
    // when open bins are already fragmented.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        // Baseline cost of a fresh bin: keep it high unless fit is excellent.
        score = waste + 20.0;
        // If no other bin can take the item, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins with large mean residual: reuse them instead.
        if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // Perfect-fit opportunity in a fresh bin (item == capacity).
        if item_size == bin_capacity {
            score -= 150.0;
        }
    }

    // Global fragmentation pressure: when mean residual is small, waste hurts more.
    score += post_residual as f64 * (mean_residual / bin_capacity as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = base * base * (1.0 + 2.0 * progress) + base * (1.0 - progress);
    let mut score = 10.0 * poly;
    // reward tight fits: low post residual relative to mean residual
    score -= (mean_residual - pr) * 0.05;
    // penalize large dead space more as stream progresses (less time to fill it)
    score += base * base * base * 20.0 * (0.5 + progress);
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    // lookahead: reward bins whose residual can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    }
    // new-bin candidate: penalize opening a new bin mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (near multiples of common item sizes) are valuable.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are multiples of small harmonic steps (10, 20, 25, 50)
        for step in [10u32, 20u32, 25u32, 50u32] {
            if pr % step == 0 {
                score -= 6.0 + (pr / step) as f64;
                break;
            }
        }
        // Penalize dead space in the awkward band (1..10) that few items can use
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0;
        }
        // Penalize mid-band residuals that are not harmonic
        if pr >= 10 && pr % 10 != 0 && pr % 25 != 0 {
            score += 3.0;
        }
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + next_item_size as f64 / cap * 10.0;
        } else {
            // If next item won't fit, prefer bins whose post_residual is small
            score += (post_residual as f64) * 0.15;
        }
        // Harmonic pairing: post_residual + next item near fullness
        let combined = post_residual + next_item_size;
        if combined == bin_capacity {
            score -= 30.0;
        } else if combined > bin_capacity {
            // next item must go elsewhere; favor bins with tight leftovers
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open when
    // existing placements are truly bad.
    if bin_residual == bin_capacity {
        score += 12.0 + (open_bins_count as f64) * 0.5;
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor)
    let res_frac = post_residual as f64 / cap;
    score -= (mean_residual / cap - res_frac) * 5.0;

    // Integer-division threshold: bins whose residual class (residual/10)
    // equals the item's size class pair well (harmonic matching)
    let item_class = item_size / 10;
    let res_class = bin_residual / 10;
    if res_class >= item_class && (res_class - item_class) <= 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host typical
    // future items are pure waste. Penalize small unusable gaps super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Nearly-full bin: excellent, reward heavily.
            score -= 60.0 + (10.0 - gap) * 8.0;
        } else if gap < 25.0 {
            // Small dead-space zone: likely unusable for items 10..80 with
            // unknown distribution; penalize but less than leaving bin open.
            score += (25.0 - gap) * 1.5;
        } else if gap <= 40.0 {
            // Mid gap: moderately useful, slight reward relative to baseline.
            score -= 2.0;
        }
    } else {
        // Perfect fill.
        score -= 120.0;
    }

    // Exact-fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    // Make the empty bin costly by default, discounted under bin pressure.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 55.0 - 10.0 * pressure;
        // If lookahead item is large and current item is small, new bin is fine.
        if next_item_size > 0 && (next_item_size as u32) >= 60 && item_size <= 30 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to item_size (tight fit) beyond raw gap.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness).min(1.0) * 0.5;

    // Open-bins pressure: with many open bins, consolidate into existing ones.
    score += 0.6 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Slight preference toward bins with residual near the mean (spread fills evenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: keep bins flexible (avoid over-tightening too early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64).max(0.0);

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && (next_item_size as u32) == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item exactly fills post_residual, this is a golden pair
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still fit here later; mild bonus scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 / (1.0 + slack / 20.0);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 2.0 * waste;
        }
    }

    // Penalize bins far below mean residual (they are already tight; keep them tight)
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score += 0.5 * diff;
    } else {
        score += 0.2 * diff; // slightly reward roomier-than-average bins
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New empty bin candidate: only attractive when few alternatives or huge item
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0; // allow fresh bin when a pair might go together
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (bin_residual < bin_capacity) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Non-linear best-fit pressure: quadratic waste penalty
    score += 0.12 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead coupling: dead space that the next item cannot use is wasted
    if next_item_size > 0 {
        let nxt = next_item_size as u32;
        if nxt > post_residual {
            score += 0.4 * (nxt - post_residual) as f64;
        } else {
            // leftover remains usable by the next item -> reward
            score -= 2.0 + 0.03 * (post_residual - nxt) as f64;
        }
    }

    // Last-chance bonus: this is the only open bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 + 6.0 * progress;
    }

    // Prefer consolidating into existing bins when many bins are open
    score -= 0.25 * mean_residual * (open_bins_count as f64 + 1.0).ln() * 0.1;

    // New-bin candidate handling: discourage opening a bin when alternatives exist,
    // especially early in the stream; allow it late when fits are poor.
    if is_new_bin {
        score += 6.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 12.0 - 8.0 * progress;
        }
        // Opening a fresh bin is attractive for large items late in stream
        score -= 0.05 * item_size as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let res = bin_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: raw wasted space, non-linearly scaled (quadratic coupling with progress)
    let mut score = post * (1.0 + 0.8 * progress * post / cap);

    // Reward tight fits: smooth bell around small post_residual
    let tightness = (post / cap).powi(2);
    score -= 12.0 * (1.0 - tightness) * (item / cap);

    // Penalize residuals that are too small to ever be useful (dead space)
    let dead_zone = (1.0 - (post / cap)).exp() - (1.0 - (2.0 * post / cap)).exp();
    score += 8.0 * dead_zone * progress;

    // Lookahead: reward if next item fits the post residual (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize early, allow late when residuals are fragmented
    if is_new_bin {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 * (1.0 - progress) - 14.0 * fragmentation * progress;
    } else {
        // Slight preference for bins below mean residual (balance load)
        score += 0.05 * (res - mean_residual).max(0.0);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.3 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer-division thresholds (capacity fractions).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space classes: tiny leftovers (<=10) are almost unusable given
    // item sizes >= 1 but practically hard to fill -> strong penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: excellent
    } else if post_residual <= 10 {
        score += 55.0; // likely dead space
    } else if post_residual <= 25 {
        score += 18.0; // awkward class
    } else if post_residual <= 50 {
        score -= 5.0; // half-bin class: still useful
    } else {
        score -= 12.0; // large residual: very reusable
    }

    // Modulo arithmetic on post_residual: leftovers divisible by common
    // item-size classes (e.g. multiples of 10) pair well with future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Coupling with lookahead item: reward residuals that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // exact harmonic match: next item fills residual to a clean class
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 15.0;
            } else if after_next <= 10 {
                score += 12.0; // would create dead space for the item after
            }
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // mean residual across open bins is already tight (items are big) or
    // many bins exist and this item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < 30.0;
        let many_open = open_bins_count as f64 > 20.0 + 40.0 * progress;
        if item_size >= 70 || (tight && item_size >= 50) || many_open {
            score -= 20.0;
        } else {
            score += 30.0; // prefer existing bins early on
        }
    }

    // Slight preference for bins whose residual is close to the mean
    // (keeps the pool balanced, avoids extreme fragmentation).
    score += 0.15 * (mean_residual - frac * cap).abs().min(50.0);

    // Mild progression-aware tie-break: later in the stream, compact more.
    score += 0.02 * (1.0 - step_index as f64 / total_items.max(1) as f64) * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest item (1..10)
    // are wasted forever; make them look maximally bad.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 10.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 && post_residual != next_item_size {
        score -= 30.0;
    }
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Open-bin pressure: mildly discourage scattering across many bins,
    // slightly stronger late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mean-residual coupling: bins far below the mean residual are "loose" fits
    // relative to the fleet; nudge score toward tighter bins.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.2;

    // Mild penalty for the brand-new empty bin candidate unless it beats
    // terrible fits (its raw post_residual is large, so it rarely wins).
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor placements that leave little waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 350.0;
        } else if post_residual > next_item_size {
            let chain_left = post_residual - next_item_size;
            // Reward chains that land near-perfect after the lookahead item.
            if chain_left <= 5 {
                score -= 150.0;
            } else {
                // Mild reward proportional to how much the chain consumes.
                score -= (next_item_size as f64 / post_residual as f64) * 80.0;
            }
        } else {
            // Next item cannot chain into this bin: penalize dead space creation.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // bins are badly fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fragmentation = mean_residual < item_size as f64 * 0.5;
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.4;
        if !bad_fragmentation && !poor_fit && open_bins_count > 0 {
            score += 500.0; // prefer reusing open bins on decent fits
        } else {
            score -= 50.0 + progress * 50.0; // allow fresh bin for bad fits
        }
    }

    // Slight preference for tighter bins among equals (small residual before placement).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative fill of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize unusable dead space: post residual smaller than the smallest possible item (1) is fine,
    // but small nonzero residuals that can't fit a typical next item are wasteful.
    if post_residual > 0 {
        if (next_item_size > 0 && post_residual < next_item_size) || next_item_size == 0 {
            score += 6.0;
        }
    } else {
        // Perfect closure is excellent.
        score -= 15.0;
    }

    // Lookahead: bonus if the next item also fits in the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bin: strongly favor using the only bin that can fit this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1 - item/C for new bin
        // Base penalty for opening a new bin, softened late in the stream or with many open bins.
        score += 18.0 - 8.0 * progress - (open_bins_count as f64).ln().max(0.0);
        // If this bin is the only fitting option, opening is acceptable.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Slightly prefer new bins when item is large (poor fit anywhere).
        score -= 5.0 * poor_fit;
    }

    // Global state coupling: if mean residual across open bins is high, prefer using existing bins.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
    }

    // Mild time-horizon term: early in stream, keep bins flexible (prefer larger post residual);
    // late in stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.08 * post_residual as f64;
    score -= progress * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // base: waste, but discount small residuals non-linearly
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr;

    // dead-space penalty: residuals too small for typical items
    let dead = 1.0 - (pr / (0.5 * cap + 1.0)).min(1.0);
    score += 0.6 * dead * dead;

    // tight fit reward (smooth)
    let tight = 1.0 - norm_pr;
    score -= 0.8 * tight * tight * tight;

    // late in stream: prefer filling bins tighter, avoid opening new bins
    score += progress * 2.0 * norm_pr;
    score -= progress * 1.5 * tight;

    // lookahead: bonus if next item fits well in resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = pr - nxt;
        if slack >= 0.0 {
            let fit_q = 1.0 - (slack / cap).abs();
            score -= 0.5 * fit_q * fit_q;
        } else {
            score += 0.25 * (-slack / cap);
        }
    }

    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else if fitting_bins_count > 2 {
        score += 0.1 * (fitting_bins_count as f64 - 2.0);
    }

    // many open bins with high mean residual: discourage adding to sprawl
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Residuals that are "waste classes" (small leftovers) are heavily penalized;
    // residuals that are perfect fractions of capacity (0, 25, 50, 75) are rewarded.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let waste_class = pr % 10;
    score += match waste_class {
        0 => -8.0,
        1 | 2 | 3 | 4 => 6.0 + (4 - waste_class) as f64 * 2.0,
        5 => -2.0,
        _ => 1.5,
    };

    // Perfect capacity-fraction residuals are ideal closure states.
    if pr == 0 {
        score -= 25.0;
    } else if cap % pr == 0 || (pr * 2 == cap) {
        score -= 6.0;
    }

    // Integer-division threshold: how many items of the NEXT size could still fit?
    if next_item_size > 0 && next_item_size <= post_residual {
        let fits_next = pr / (next_item_size as i64);
        score -= 4.0 + fits_next as f64 * 3.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // dead space relative to lookahead: penalize proportionally
        let gap = next_item_size as f64 - post_residual as f64;
        score += gap * 0.6;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the item is large and fits nowhere nicely.
    let is_new_bin = bin_residual == bin_capacity && post_residual < bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 10.0;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin when item is large and open-bin residuals are small.
        score += 20.0 - big_item * 22.0 - (mean_residual / bin_capacity as f64) * 10.0 + crowding * 2.0 - progress * 3.0;
        // If next item is small, a fresh large residual is valuable.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 5.0;
        }
    }

    // Tight fits (small post residual) are good in existing bins.
    if post_residual <= 5 && !is_new_bin {
        score -= 10.0;
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum plausible item are "dead". Penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin residual (waste ratio).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // If this bin is the last chance, avoid forcing a bad fit; but if the fit
    // is decent (small post residual), reward using it instead of a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 {
            score -= 25.0;
        } else {
            score += 40.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins; few open bins -> opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when few bins open; penalize when
        // many bins are open and mean residual is large (consolidate instead).
        score -= 15.0;
        score += 8.0 * pressure;
        score += 0.3 * mean_residual;
        // If the next item could fit into the leftover of this new bin, mildly
        // encourage opening it (pairing lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else {
        // Existing bin: reward using it when open-bin pressure is high.
        score -= 4.0 * pressure;
        // Lookahead: if next item exactly fits the post residual, big reward.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 50.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Early in the stream, tolerate opening bins slightly more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit: dead space zero is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item exactly matches post_residual, huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }
    // Next item fits into the remaining space: moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + (post_residual - next_item_size) as f64;
    }
    // Next item would NOT fit here: penalize leaving a gap just under next_item_size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is close to the item (tight fit) relative to mean.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Deviation from mean residual: prefer bins deviating below mean (denser bins).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.5;

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // Base penalty so we only open new bins when open bins fit poorly.
        score += 120.0;
        // If lookahead item is large and current fit is bad, new bin more attractive.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 40.0;
        }
        // Early in stream, allow more bins; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Penalize many open bins slightly to encourage consolidation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 20.0;

    // Penalize leaving residuals that are too small for any realistic item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward residuals that can still hold the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if bin_residual >= item_size + next_item_size {
            // Sequence fit: both current and next item fit perfectly.
            score -= 4.0;
        } else {
            score += 3.0;
        }
    }

    // Compare against mean residual: prefer bins whose residual is below average
    // (concentrate filling in fuller bins, keep larger residuals available).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, accept decent fits to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual as f64 <= mean_residual + 5.0;
        let base_penalty = 25.0 + (open_bins_count as f64).sqrt() * 2.0;
        if good_fit_exists {
            score += base_penalty;
        } else {
            // Opening a new bin is reasonable if the best alternative wastes a lot.
            score += 5.0 - (post_residual as f64 / bin_capacity as f64) * 5.0;
        }
        // Early stream: prefer consolidating into open bins.
        score += (1.0 - progress) * 10.0;
    }

    // Mild preference for bins that are already substantially filled.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 5.0;

    // Jitter-free deterministic tie-breaker scaled by bin identity proxies.
    score += (bin_residual as f64 * 0.001) + (open_bins_count as f64 * 0.0005);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let rn = r / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = r;
    score -= 18.0 * (1.0 - rn) * (1.0 - rn) * (1.0 + progress);
    score += 10.0 * rn * rn * rn * (1.0 - progress);
    // Reward exact-ish fits strongly, smoothly
    score -= 25.0 * (1.0 - rn).powi(4);
    // Lookahead coupling: reward residual that can host the next item
    if next_item_size > 0 {
        let gap = rn - nxt;
        score -= 12.0 * (gap.max(0.0)) * (1.0 - progress);
        score += 8.0 * (nxt - rn).max(0.0) * (nxt - rn).max(0.0);
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    // Penalize bins far from mean residual (fragmentation)
    score += 3.0 * (r - mean_residual).abs() / cap * (1.0 + progress);
    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 5.0 * (1.0 - fit) * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes of the capacity
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap; // capacity fraction of leftover

    // Reward tight fits: post_residual in low harmonic classes (0, small values)
    let class = pr % 10; // integer division / modulo threshold on post_residual
    score -= (10 - class) as f64 * 0.8; // prefer residuals near multiples of 10

    // Dead-space penalty: residuals that are too small to fit the smallest item (1..100 unknown, assume >= 5)
    if pr > 0 && pr < 5 {
        score += 60.0;
    }

    // Non-linear penalty on tiny fractional leftovers (unusable slivers)
    if frac > 0.0 && frac < 0.05 {
        score += 25.0;
    }

    // Harmonic coupling with next item: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0; // perfect lookahead fit
        } else if next_item_size < pr {
            let r2 = pr - next_item_size;
            score -= 15.0 - (r2 % 10) as f64; // partial lookahead fit, modulo-harmonic bonus
        } else {
            // next item cannot fit here: slight penalty scaled by overflow
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual of open bins
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // average waste across open bins
        // Prefer new bin only if open bins are mostly full (low mean residual)
        score += 30.0 + 45.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing else fits
        }
    }

    // Progression: early in stream, be more willing to consolidate (favor filling open bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Mild preference to keep number of open bins from exploding
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // plausible future item are pure waste — penalize them super-linearly.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual) non-linearly.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; residual becomes dead weight if small.
            if post_residual < next_item_size && post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean-residual coupling: prefer bins with residual below the mean
    // (consolidate nearly-full bins) when the fit is good.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit (post_residual large relative to item).
    if bin_residual == bin_capacity {
        // Base cost of a new bin, offset by its perfect 100 residual utility.
        score += 45.0;
        score -= 0.05 * bin_capacity as f64;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 20.0 * fitting_bins_count as f64;
        }
        // Late in the stream, avoid proliferating bins.
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - (slack * 0.4).min(18.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space below next item's size: penalize, worse if next item is large
        score += 5.0 + (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Reward filling relative to mean residual of open bins (tighter than average is good)
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving very small unusable slivers (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: keep it attractive early / when current bins fit poorly,
    // but discourage opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        let good_fit = next_item_size > 0 && post_residual == next_item_size;
        if good_fit {
            score -= 55.0; // fresh bin perfectly serves the next item too
        } else if fitting_bins_count > 0 && open_bins_count > 0 {
            score += 15.0 + 10.0 * progress; // prefer existing bins more as stream progresses
        } else {
            score -= 10.0;
        }
    }

    // Slight preference for filling bins with more items already packed (larger item_size usage)
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize small dead space relative to capacity (unusable slivers).
    let dead_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_ratio > 0.0 && dead_ratio < 0.10 {
        score += 6.0 * (0.10 - dead_ratio) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // residual too small for next item but not tiny: mild penalty
            score += 4.0;
        }
        // If next item is large, prefer leaving big residuals.
        if next_item_size > 60 && post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // Time horizon: early in stream, be pickier about waste (many items remain);
    // late in stream, accept imperfect fits to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += dead_ratio * 20.0 * (1.0 - progress);

    // Global pressure: many open bins with high mean residual -> prefer
    // filling existing bins over opening new ones.
    if open_bins_count > 3 && mean_residual > item_size as f64 * 1.5 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no good alternative exists
    // (few fitting bins) or item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        let base_open = 55.0
            + (open_bins_count as f64) * 2.0
            - (fitting_bins_count as f64) * 12.0
            - (item_size as f64 - 50.0) * 0.4;
        // Opening a bin early is worse than late.
        score = score.max(base_open + (1.0 - progress) * 15.0);
        // If the current bin would leave a terrible residual, opening is fine.
        if post_residual > 0 && post_residual < 10 && bin_residual != bin_capacity {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = post / cap;

    // Base: prefer small post-residual, with non-linear reward for tight fits
    let mut score = post
        - 40.0 * (1.0 - tight) * (1.0 - tight) * (1.0 - tight)
        - 25.0 * (1.0 - tight) * (1.0 - tight);

    // Stream-progress coupling: as stream advances, penalize loose fits more strongly
    score += 30.0 * progress * tight * tight * cap;

    // Mean-residual coupling: if open bins are already loose, penalize adding more slack
    let mean_norm = mean_residual / cap;
    score += 20.0 * mean_norm * post / cap * cap;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - tight);
    }

    // Lookahead: reward post-residual that could still fit the next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post >= next {
            score -= 15.0 * (post - next) / cap * (1.0 + progress);
        } else {
            score += 10.0 * (next - post) / cap;
        }
    }

    // Mild penalty for many open bins to discourage bin proliferation
    score += 2.0 * open_bins_count as f64 * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit with a mild squaring to sharpen preference for tight fits.
    score = post_residual as f64 * (1.0 + post_residual as f64 / (2.0 * bin_capacity as f64));

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularities are more reusable, so reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 6.0; }
        if pr % 5 == 0 && pr % 10 != 0 { harmony_bonus += 2.5; }
        if pr % 4 == 0 { harmony_bonus += 1.5; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        if pr % 20 == 0 { harmony_bonus += 2.0; }
        // Perfect fill is the ultimate harmonic class.
        if pr == 0 { harmony_bonus += 20.0; }
        score -= harmony_bonus;

        // Integer-division thresholds: small dead space classes are bad.
        let dead_class = pr / 10; // 0..10
        if dead_class <= 1 {
            // residual 0..19: nearly unusable for items >= 10
            score += 8.0 * (2.0 - dead_class as f64);
        } else if dead_class <= 3 {
            score += 2.0;
        }

        // Lookahead coupling: does the next item fit harmonically into post_residual?
        if next_item_size > 0 && next_item_size <= pr {
            // Exact harmonic match: post_residual is a multiple of next item
            if pr % next_item_size == 0 {
                score -= 12.0;
            } else {
                // leftover after next item, scaled by how small it is
                let after = pr - next_item_size;
                score -= 4.0 + 8.0 * (1.0 - after as f64 / bin_capacity as f64);
            }
        } else if next_item_size > pr {
            // next item cannot use this residual; penalize proportionally
            score += 3.0;
        }

        // Half-capacity class: residual exactly 50 is maximally flexible
        if pr == bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current bin would leave a very awkward residual class.
    if bin_residual == bin_capacity {
        // Neutral-ish anchor: new bin gets post_residual = capacity.
        // Only beat it if the placement in an open bin is clearly poor.
        let awkward = (post_residual > 0 && post_residual < 10)
            || (next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual);
        if !awkward {
            score += 10.0;
        }
        // Early in the stream, opening bins is fine (builds a portfolio).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
    }

    // Mean-residual context: if this bin's residual deviates from the mean
    // in a useful direction (smaller residual = consolidating fullness),
    // reward it.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Many open bins: encourage closing bins (tight fits) to reduce spread.
    if open_bins_count > 4 {
        score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1)
    // can use are pure waste; residuals below a small threshold are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable gap -> strong penalty
        } else if post_residual <= 25 {
            score += 18.0; // small gap, hard to fill
        } else if post_residual <= 50 {
            score -= 6.0; // medium gap still usable
        } else {
            score -= 12.0; // large residual, flexible
        }
    } else {
        score -= 40.0; // perfect fit
    }

    // Exact match with lookahead: strongly favor bins that will be perfectly closed
    // now and leave the next item to a fresh/other bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize placements that leave a gap exactly unusable by the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into yet another
    // bin; encourage consolidating into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when the
        // residual structure of open bins is bad (high mean dead space).
        score += 30.0 + pressure + mean_residual * 0.0;
        if mean_residual > 35.0 {
            score -= 25.0; // open bins are fragmented; a fresh bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item benefits from a fresh bin
        }
    } else {
        // Existing bin: slight bonus to prefer reusing bins over opening new ones.
        score -= 8.0 + pressure * 0.5;
        // Prefer bins with below-average residual (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild time coupling: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
    }
    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 55.0 - 35.0 * bad_fit - 10.0 * progress;
    }

    // Prefer consolidating into fewer bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post residual).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward bins that can also host the lookahead item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // lookahead cannot fit here: penalize wasting space if next item is big
            score += 0.1 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bonus: only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: open a fresh bin only when fits are poor or
    // residual space in existing bins is fragmented relative to item sizes.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = (post_residual as f64 / bin_capacity as f64).min(1.0);
        // penalize opening new bin generally
        score += 20.0;
        // but reward opening when existing bins would leave large dead space
        let dead = (bin_residual - item_size) as f64;
        if dead > 0.35 * bin_capacity as f64 {
            score -= 12.0;
        }
        // early stream: opening bins is cheaper
        score -= 10.0 * (1.0 - progress);
        // if many open bins with high mean residual, prefer reusing them
        score += 0.05 * mean_residual;
        let _ = tightness;
    }

    // Prefer filling bins that are already low on residual (consolidate waste).
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    // Mild penalty for many open bins to encourage reuse.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this item
    let fill_ratio = item_size as f64 / cap;
    let waste_ratio = post_residual as f64 / cap;

    // Smooth non-linear tightness reward: cubic decay of waste
    let tightness = (1.0 - waste_ratio).powi(3);
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Non-linear coupling: waste penalized more strongly as stream progresses
    score += 8.0 * waste_ratio * waste_ratio * (1.0 + progress);

    // Polynomial coupling of post_residual with progress: dead space matters more later
    let pr = post_residual as f64;
    score += 0.002 * pr * pr * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - waste_ratio);
    }

    // New-bin candidate handling: prefer new bins early, penalize them later
    if bin_residual == bin_capacity {
        let early_bias = (1.0 - progress).powi(2);
        score -= 6.0 * early_bias;
        score += 10.0 * progress;
        // If open bins fit but are poor fits, new bin is attractive when mean residual is low
        score += (mean_residual / cap - waste_ratio).max(0.0) * 5.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let combo_fill = (item_size as f64 + nxt) / cap;
            score -= 6.0 * combo_fill * combo_fill;
        } else {
            // Penalize leaving residual that is almost-but-not-quite usable for next item
            let gap = (post_residual as f64 - nxt) / cap;
            if gap < 0.15 {
                score += 4.0 * (1.0 - gap / 0.15);
            }
        }
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - waste_ratio) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic in post_residual (dead space grows quadratically bad)
    let tightness = (post_residual as f64 / cap).powi(2) * 30.0;
    score += tightness;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Harmonic class logic: post_residual modulo classes
    // Residuals that are "nice" multiples/divisors pair well with common item sizes
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals divisible by small harmonics (easy to fill later)
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 5 == 0 { score -= 4.0; }
        // Penalize awkward residuals (prime-ish / odd classes)
        if pr % 10 != 0 && pr % 5 != 0 && pr % 2 != 0 { score += 6.0; }
        // Integer-division threshold: residual in mid-band [30,60] is hardest to fill
        if pr >= 30 && pr <= 60 { score += 10.0; }
        if pr > 60 { score += 2.0; }
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly or well
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 == n {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item can't fit here; slight penalty scaled by probability proxy
            score += 5.0;
        }
        // Harmonic pairing: item + next sums to capacity-fraction classes
        let sum = item_size + next_item_size;
        if sum == bin_capacity { score -= 60.0; }
        if sum % 25 == 0 { score -= 10.0; }
    }

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        // big items prefer fresh bins when existing residuals are small
        let mean_r = mean_residual / cap;
        let crowding = if open_bins_count > 0 { 1.0 / (1.0 + open_bins_count as f64) } else { 1.0 };
        let mut new_score = cap as f64 * 0.55; // base cost of opening a bin (half-filled residual)
        new_score -= item_frac * 40.0;
        new_score -= mean_r * 30.0;
        new_score -= crowding * 15.0;
        new_score -= progress * 10.0;
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) <= cap {
            new_score -= 15.0; // fresh bin can host both
        }
        score = new_score.max(0.5); // never dominate perfect fits
    }

    // Mild pressure to consolidate into fewer bins
    if !is_new_bin {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are poison.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 14.0;
    }
    // Medium dead space (hard to fill later) gets a moderate penalty.
    if post_residual > 12 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.6;
    }

    // Reward very tight fits (almost exact fill).
    if post_residual <= 4 {
        score -= 25.0;
    }

    // Perfect fill is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Prefer bins whose residual was already small (consolidate fullness).
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and prefer using existing space; when few are open, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (18.0 + 22.0 * pressure * (0.5 + 0.5 * progress));

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && new_bin < 0.5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into the post-residual exactly-ish, reward leaving that gap.
    if next_item_size > 0 {
        let nd = (post_residual as f64 - next_item_size as f64).abs();
        if nd <= 5.0 {
            score -= 18.0 * (1.0 - nd / 5.0);
        }
        // Penalize leaving a gap that is just barely too small for the next item.
        if post_residual < next_item_size && next_item_size - post_residual <= 10 {
            score += 10.0;
        }
    }

    // Slight nudge toward bins near the mean residual (keeps residuals balanced).
    score += ((post_residual as f64 - mean_residual) / 10.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 150.0;
            } else if slack <= 15 {
                score -= 50.0;
            }
            // Fraction of residual consumed by the next item.
            let consume_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * consume_ratio;
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: bins already tighter than average are better targets.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 0.8 * (mean_residual - res);
    } else {
        score += 0.4 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
        if post_residual <= 20 {
            score -= 40.0;
        }
    }

    // New-bin candidate: prefer using it only when the item is large relative to
    // capacity (opening fresh for big items is fine) or stream is early.
    if bin_residual == bin_capacity {
        score += 120.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 {
            score -= 90.0;
        }
        if progress < 0.15 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            // Fresh bin can also host the next item: mildly attractive.
            score -= 30.0;
        }
    }

    // Small penalty for very tight bins relative to capacity (keep flexibility).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    // Mild preference to consolidate into fewer bins early on.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small unusable sliver is fine (nearly perfect fit)
    } else if post_residual >= 10 {
        // residual between 1 and 80 could be wasted; mild penalty grows with size
        score += 0.15 * post_residual as f64;
    }

    // Lookahead coupling: reward if next item fits into post_residual (chaining),
    // penalize if next item would have fit this bin exactly but we leave it broken.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // we consumed space the next item could have used
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
        // if next item exactly fills post_residual, strongly reward
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Crowding pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowding = (open_bins_count as f64).ln().max(0.0);
    score -= crowding * (1.5 + 2.0 * progress);

    // Mean residual anchoring: prefer bins whose post_residual stays near mean
    // (keeps residual distribution homogeneous, easier future packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate logic: empty bin gets a base cost that shrinks over time
    // and when the current bin choice would be a very poor fit.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        let mut open_cost = 10.0 + 20.0 * progress;
        if fitting_bins_count == 0 { open_cost -= 30.0; }
        if poor_fit && post_residual >= 20 { open_cost += 8.0; }
        if next_item_size > 0 && next_item_size >= item_size && open_bins_count == 0 {
            open_cost -= 10.0;
        }
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic penalty on wasted space, modulated by stream progress
    let waste_penalty = norm_pr * norm_pr * cap * (0.5 + 0.5 * progress);
    score += waste_penalty;

    // Cubic interaction: mid-range residuals are risky late in the stream
    score += 8.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * progress * cap * 0.25;

    // Lookahead: reward if next item fits into post residual (smooth bump)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress);
        } else {
            // penalize residuals that cannot host the next item, scaled by gap
            let gap = (nx - pr) / cap;
            score += 6.0 * gap * (1.0 - gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: neutral-ish baseline, slightly discouraged early, more acceptable late
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.3 * progress) + 5.0 * (open_bins_count as f64).sqrt();
        // prefer opening a new bin if all open bins would leave bad residuals
        let mean_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score -= 20.0 * mean_gap * mean_gap * cap * 0.1;
        return score;
    }

    // Mild reward for using bins with larger residuals (consolidation)
    score -= 0.05 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are tight fits -> reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = post / cap;

    // Reward tight fits (small post_residual) more than linearly
    score -= 30.0 * (-frac * 4.0).exp();

    // Modulo classes on post_residual: residues near multiples of 10
    // are "harmonic" with typical item sizes -> slightly reward.
    let r = post_residual % 10;
    let harm = if r == 0 { 6.0 } else if r <= 2 { 3.0 } else if r >= 8 { -2.0 } else { 0.0 };
    score -= harm;

    // Dead space penalty: residual too small for any plausible item (1..100)
    if post_residual == 0 {
        score -= 25.0; // perfect fill is excellent
    } else if post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: penalize proportionally to wasted harmony
            score += 4.0;
        }
    }

    // Last-chance bin: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-ish but slightly discouraged unless open bins are crowded
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 12.0 + 3.0 * pressure;
    }

    // Prefer filling bins with low residual relative to mean (balance avoidance)
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild stream-progression pressure: later in stream, consolidate more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space penalty: residual gaps too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (waste near zero)
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins, more so early when open bins are few
    if is_new_bin {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt() - 10.0 * progress;
        // If next item would fit in the fresh residual, soften the penalty slightly
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Open-bin pressure: mildly prefer filling bins when many are open
        score += (open_bins_count as f64) * 0.5;
        // Prefer bins whose residual deviates below the mean (fill laggards)
        score -= (mean_residual - bin_residual as f64) * 0.3;
        // Lookahead: bonus if next item fits the post residual
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 3.0; // near-perfect chain
        } else {
            // penalize residuals that are awkwardly close to but not matching next item
            score += diff * 0.15;
        }

        // reward if next item could fit into the post-residual at all
        if (post_residual as f64) >= next {
            score -= 8.0;
        }
    }

    // Penalize tiny dead space (< 10, likely unusable for items >= 1 but wasteful)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // small-but-nonzero residual is the worst outcome
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Compare against mean residual: prefer bins that absorb the item while
    // keeping residual distribution balanced (avoid leaving one huge outlier bin)
    if post_residual as f64 > mean_residual + 20.0 {
        score += 6.0; // creating an outlier residual is risky
    } else if post_residual as f64 <= mean_residual {
        score -= 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a decent fit (residual-based pressure grows with number of open bins)
    if bin_residual == bin_capacity {
        // base penalty so new bins are used only when open bins fit poorly
        score += 18.0 + 2.0 * open_bins_count as f64;
        // but if item is large relative to mean residual, opening fresh is fine
        if (item_size as f64) > mean_residual {
            score -= 22.0;
        }
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer tighter fits generally: reward small post_residual relative to capacity
    score -= (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post-residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving large unusable gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.08 * residual_gap;

    // Penalize opening new bins late in the stream when open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open-bin count
        score += 20.0 + 3.0 * (open_bins_count as f64);
        // early in stream, new bins are cheaper; late, expensive
        score += 30.0 * progress;
        // if next item is large, a fresh bin is more valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // placing into an existing bin is generally good; reward more when bins are scarce
        score -= 2.0 * (1.0 - progress);
    }

    // Discard near-zero residual waste: a bin left with tiny residual is dead space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;

    // Normalized post-residual (0 = perfect fit, 1 = empty bin)
    let post_norm = (post_residual as f64 / cap).clamp(0.0, 1.0);

    // Smooth non-linear coupling: tight fits (small post_residual) get a strong
    // reward that grows with stream progress (waste matters more later).
    let tightness = (1.0 - post_norm).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Quadratic penalty on wasted space, amplified as stream progresses.
    score += 2.5 * post_norm.powi(2) * (1.0 + 2.0 * progress);

    // Cubic dead-space term: residuals too small for any plausible item
    // (items >= 1, but small leftovers are useless) are heavily penalized.
    let dead = if post_residual > 0 { post_norm } else { 0.0 };
    score += 4.0 * dead * dead * dead;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins
    // fit poorly; the penalty grows with progress (avoid opening bins late).
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual deviates from the mean in a useful way:
        // filling bins that are already small reduces bin count variance.
        let dev = post_residual as f64 - mean_residual;
        score += 0.05 * dev.abs() * (1.0 - progress);
    }

    // Lookahead: reward leaving space compatible with the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / cap);
        score -= 3.0 * snug.max(0.0) * snug;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Leftover too small for the next item: dead space penalty.
        score += 3.0 * post_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (min item size granularity)
    let r = post_residual % 10;
    // Dead-space classes: residues 1..9 are hard to fill; 0 is harmonic
    if post_residual > 0 {
        score += match r {
            0 => -6.0,
            1..=3 => 12.0,
            4..=6 => 6.0,
            _ => 3.0,
        };
    }

    // Small unusable residual is dead space: quadratic penalty below threshold
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: does next item fit into post_residual? Reward compatibility
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else {
            // next item won't fit here; residual likely wasted
            score += (post_residual as f64) * 0.15;
        }
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of every open bin on average;
        // penalize unless existing bins fit poorly or are nearly full.
        let avg_waste = mean_residual.max(0.0);
        score = cap * 0.55 + avg_waste * 0.6;
        if next_item_size > 0 && next_item_size > post_residual {
            // next item won't fit an empty bin either (impossible) — keep neutral
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // forced open
        } else if fitting_bins_count == 1 {
            score += 25.0; // discourage abandoning the last-chance bin
        }
        // Later in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        score -= open_bins_count as f64 * 0.5;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Favor filling bins with large residual (harmonic fraction of capacity)
    let frac = post_residual as f64 / cap;
    score -= frac * frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are the worst outcome.
    if post_residual < 10 {
        score -= 1000.0; // perfect or near-perfect fill: strongly favored
    } else if post_residual <= 20 {
        // Dead space zone: penalize proportionally to how "wasted" it is.
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Non-linear penalty on residual waste: quadratic in the mid-range.
    if post_residual > 20 {
        let r = post_residual as f64;
        score += 0.05 * r * r / bin_capacity as f64;
    }

    // Reward tight fits relative to what the bin had.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // and make opening a new bin less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the current
    // residual would create bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 120.0;
        // If existing bins fit poorly (large dead space), a new bin becomes attractive.
        if post_residual >= bin_capacity - item_size {
            // empty bin: post_residual == capacity - item_size
            let waste_avoided = mean_residual - item_size as f64;
            if waste_avoided > 0.0 {
                score -= 2.0 * waste_avoided.min(80.0);
            }
        }
        // Late in the stream, opening new bins is cheaper than fragmenting.
        if progress > 0.8 {
            score -= 40.0 * progress;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
    }
    // If next item nearly fits, mild penalty for leaving a tantalizing gap.
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact matches: residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Reward tight match with next item (subtract up to ~40).
        score -= 40.0 / (1.0 + diff * 0.25);

        // Penalize leaving residual too small for the next item (dead space risk)
        if post_residual < next_item_size {
            let waste = next_item_size - post_residual as u32;
            score += 0.6 * waste as f64;
        } else {
            // Reward leaving space exactly usable by next item
            score -= 0.4 * (post_residual as f64 - next_item_size as f64).min(30.0) * 0.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Compare against mean residual: bins with residual close to mean are flexible;
    // penalize using bins whose residual is much larger than mean (save big-space bins).
    if bin_residual < bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += 0.3 * dev; // prefer filling bins that are already tight
        } else {
            score += 0.1 * (-dev); // slight penalty for touching roomy bins
        }
    }

    // New-bin candidate handling: only open a new bin if no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of opening a bin; reduce late in stream (fewer future chances to fill).
        let mut new_bin_cost = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 {
            // an empty bin perfectly fits the next item too; slightly cheaper
            new_bin_cost -= 5.0;
        }
        if fitting_bins_count == 1 {
            // An open bin exists and is last chance; make new bin unattractive.
            new_bin_cost += 30.0;
        }
        score += new_bin_cost;
    }

    // Small tie-breaker favoring bins with larger residual among equals (keep tight bins tight)
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize post_residual that is too small to hold any plausible item
    // (dead space): residual below the minimum item size is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 8.0 * (25.0 - post_residual as f64) / 25.0;
    }

    // Lookahead: reward bins whose post residual can accommodate the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by
            // how much the next item overshoots the post residual.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // When many bins are open, prefer consolidating into existing ones;
    // when few bins are open, opening a new bin is cheaper.
    let open_f = open_bins_count as f64;
    let pressure = 1.0 - 1.0 / (1.0 + open_f / 10.0);
    score += 15.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residual near the mean are
    // "typical" targets; strongly-empty bins should be saved for big items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    // Time horizon: early in the stream, be conservative (favor tight fits
    // even more); late in the stream, prioritize closing out bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * tightness;

    // New-bin candidate: it should only win when fits into open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced over time and when few
        // bins are open; increased when many bins are already open.
        score = 55.0 + 20.0 * pressure - 10.0 * t;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin always fits the next item perfectly.
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer small post residual, smoothed non-linearly
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress coupling: later in the stream, penalize waste more strongly
    let prog_coupling = 0.5 + 1.5 * progress * progress;
    score *= prog_coupling;

    // Reward tight fits non-linearly (quadratic bonus on item/residual ratio)
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= 4.0 * fill_ratio * fill_ratio * (1.0 + progress);

    // Lookahead: penalize if post residual can't fit next item, reward if it can
    if next > 0.0 {
        let fits_next = if pr >= next { 1.0 } else { 0.0 };
        score -= 1.5 * fits_next * (next / cap);
        score += 0.6 * (1.0 - fits_next) * (1.0 - (next / cap).min(1.0)) * (0.5 + progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 2.0 + 3.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate waste)
    let mr = mean_residual / cap;
    score += 1.2 * (norm_pr - mr).abs() * (0.5 + progress);

    // Many open bins: discourage spreading, favor filling existing bins tighter
    let ob = open_bins_count as f64;
    score += 0.05 * ob.sqrt() * norm_pr;

    // New-bin candidate: penalize opening a new bin unless residual waste would be severe
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress + 0.02 * ob;
        // Allow new bin if item is huge relative to typical residuals
        score -= 3.0 * (item / cap) * (1.0 - (mean_residual / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: fill fraction of bin used by this item
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Harmonic class of post_residual modulo capacity quarters: prefer residuals
    // that lie in "usable" classes (multiples of 10 / small classes)
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -20.0,
        1..=3 => 15.0,
        4..=6 => 5.0,
        _ => 10.0,
    };
    score += class_penalty;

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // prefer leaving residuals close to next item (harmonic pairing)
            let gap = (post - nxt) / cap;
            score -= 12.0 * (1.0 - gap).min(1.0);
        } else {
            // next item cannot fit here; slight penalty scaled by overflow
            let over = (next_item_size as f64 - post) / cap;
            score += 8.0 * over.min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 40.0 * (1.0 - avg_fill) - 10.0 * progress;
        // opening new bin is fine if all open bins cannot nicely hold item
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference to balance: avoid concentrating on bins far below mean residual
    let dev = post - mean_residual;
    score += 0.05 * dev;

    // Integer-division threshold: residuals >= half capacity are wasteful targets
    if post_residual >= bin_capacity / 2 {
        score += 10.0 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals that are too small for typical future items
    // (below a "usable threshold") are heavily penalized, scaled by how dead they are.
    let usable_threshold = 20.0_f64.min(cap * 0.2);
    if post > 0.0 && post < usable_threshold {
        let deadness = (usable_threshold - post) / usable_threshold;
        score += deadness * deadness * 45.0;
    }

    // Perfect-fit reward.
    if post == 0.0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate relatively more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln1p() * (2.0 + 3.0 * progress);
    score += pressure * (post / cap);

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
        score -= tightness * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

