    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_reward = 60.0 / (1.0 + gap / 10.0);
        score -= lookahead_reward;

        // Exact 2-step chain: item now + next item fills bin perfectly
        if item_size + next_item_size == bin_residual {
