    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.8 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: only fitting bin -> use it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // Penalize leaving very small unusable slivers (unless perfect fit)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild pressure to consolidate into few bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.3 * progress * post_residual as f64;

    // New-bin candidate: neutral baseline, slightly penalized so decent fits win
    if bin_residual == bin_capacity {
        score += 120.0;
        // But prefer a fresh bin if no open bin gives a tight fit
        if post_residual < 15 && next_item_size > 0 {
            score -= 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
