    score -= 12.0 * tightness;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in stream, encourage consolidation; late, be flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> prefer filling existing ones; penalize new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin ok if next item is large too
        }
    }

    // Prefer bins with residuals close to item size (best-fit refinement).
    let slack = (bin_residual - item_size) as f64;
    score += 0.08 * slack;

    // Coupling with mean residual: favor bins below mean residual (tighter bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post-residual, non-linearly coupled with stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Polynomial shaping of residual: reward tight fits (small pr), penalize mid-range waste.
    let shape = pr_norm * pr_norm * (1.0 - pr_norm);
    score -= 60.0 * shape;

    // Smooth interaction: waste penalized more as stream progresses.
    score += 25.0 * pr_norm * pr_norm * progress;

    // Dead-space penalty: residual below smallest plausible item relative to mean residual.
    let dead = ((mean_residual - pr).max(0.0) / cap).powi(3);
    score += 40.0 * dead;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 12.0 * (pr / (ns + 1.0)).sqrt().min(3.0);
        } else {
            score += 15.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild penalty for spreading across many bins late in stream.
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: keep it neutral-to-slightly-attractive early, unattractive late.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res_mod = post_residual % (bin_capacity / 4).max(1);
    let res_mod8 = post_residual % (bin_capacity / 8).max(1);

    // Reward residuals that sit on "harmonic" nodes (multiples of 25, 50, 20, 10)
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 3.0; }
    if post_residual % 10 == 0 { score -= 1.5; }
    if res_mod == 0 { score -= 2.0; }
    if res_mod8 == 0 { score -= 1.0; }

    // Penalize tiny dead space (unusable slivers), scaled by harmonic depth
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            // harmonic quality of the residual after the lookahead item
            if npr % 25 == 0 { score -= 5.0; }
            if npr % 10 == 0 { score -= 2.0; }
            if npr < 10 { score += 4.0; }
            score += npr as f64 * 0.05;
        } else {
            // next item cannot use this bin's leftover; slight penalty
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 8.0;
    }

    // Tight fit reward: fraction of bin consumed
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * 5.0;

    // Prefer closing near-full bins when many bins are open
    if fill > 0.9 { score -= 4.0; }

    // New-bin candidate: neutral-ish baseline, discouraged when decent fits exist
    if bin_residual == bin_capacity {
        score = cap * 0.75;
        if fitting_bins_count == 0 { score -= 20.0; }
        if open_bins_count as f64 > mean_residual { score -= 2.0; }
    }

    // Mild time-averaging: late in stream, pack tighter
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to
    // plausibly fit a future item (items >= 1, but small gaps < ~10 are dead).
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= tightness * 6.0;
    }

    // Penalize large wasted residual when bin residual is huge but item tiny.
    if post_residual > item_size * 3 {
        score += 4.0;
    }

    // Open bins pressure: encourage filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.15;

    // Deviation from mean residual: prefer bins whose residual is close to item
    // needs (avoid dumping into very full or very empty bins unevenly).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty if we leave big gap.
        if post_residual > 0 {
            score += (post_residual as f64) * 0.02;
        }
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // offers a decent fit. Make the empty bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if current item would leave a large dead residual in any bin,
        // opening new bin becomes more attractive.
        if post_residual < dead_threshold && fitting_bins_count <= 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base reward for tight fits (low post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: perfect match when next item exactly fills post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain: bin fully closed after next item
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how little slack remains after
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving awkward gap
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / bin_capacity as f64).min(1.0);
        }
    } else if next_item_size == 0 {
        // last item: just close bins tightly
        score -= 8.0 * tightness;
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than new ones
    if open_bins_count > 4 {
        if bin_residual < bin_capacity {
            score -= 3.0;
        } else {
            score += 10.0; // this is the new-bin candidate; discourage when many open bins
        }
    }

    // Early in stream: opening new bins is cheaper
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize tiny unusable residuals (< 10, smallest item)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor small post_residual (best-fit core)
    let tightness = 1.0 - (post / cap);
    score -= 24.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty for awkward residuals that likely fit nothing (min item ~ small)
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0;
        }
        // Penalize leaving residual that tempts a large next item into fragmentation
        if next_item_size > post_residual && post_residual < 20 {
            score += 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is costly unless current fit is bad
    if bin_residual == bin_capacity {
        let waste = cap - item_size as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin late in stream or when open bins are fragmented
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score = cap + 18.0 - 20.0 * fragmentation - 10.0 * progress;
        if waste < 10.0 {
            score -= 8.0; // near-full packing of a fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Slight preference for bins with larger residuals when many bins are open (balance load)
    score -= 0.02 * (bin_residual as f64 - mean_residual) * (open_bins_count.min(20) as f64).sqrt();

    // Mild time-dependent tightening: early stream, be conservative with fills
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty on post-residual
    let mut score = pr + 4.0 * norm_pr * pr;

    // Non-linear coupling with stream progress: early on tolerate slack,
    // late in the stream punish residual space harder (polynomial ramp)
    let ramp = progress * progress * (3.0 - 2.0 * progress);
    score += ramp * 12.0 * norm_pr * pr;

    // Smooth interaction between post_residual and next item lookahead
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap >= 0.0 {
            // next item still fits: reward smooth, saturating
            let s = gap / cap;
            score -= 10.0 * s / (1.0 + s);
        } else {
            // next item won't fit: penalize proportionally to shortfall
            let s = (-gap) / cap;
            score += 8.0 * s * s / (1.0 + s);
        }
    }

    // Coupling with mean residual: prefer bins below mean (tighter bins first)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev;

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure against opening new bins when many are open
    let nb = open_bins_count as f64;
    score -= 2.0 * (nb / (1.0 + nb)) * norm_pr;

    // New-bin candidate: smooth penalty that shrinks with progress
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - ramp) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse modulo classes on capacity
    let item_class = item_size % 10;
    let post_class = post_residual % 10;

    // Reward tight fits: post_residual small => low score (already base).
    // Extra reward when post_residual lands in a "usable" harmonic class
    // (residuals that are multiples of small granularity are easier to fill later).
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_class == 0 {
        score -= 8.0; // round residual, reusable class
    } else if post_residual <= 10 {
        score -= 5.0; // near-perfect fit
    }

    // Penalize dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic match on classes
            if next_item_size % 10 == post_class {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overflow
            let overflow = (next_item_size - post_residual) as f64;
            score += overflow * 0.15;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // would create bad dead space. Penalize opening new bins moderately.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        score += 30.0 + 10.0 * (1.0 - progress) + open_pressure * 0.5;
        // But if item is huge and mean residual across open bins is small,
        // a new bin is fine
        if item_size as f64 > mean_residual + 20.0 {
            score -= 25.0;
        }
    }

    // Prefer bins with residuals close to item size (best-fit sharpening)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Coupling with mean residual: favor bins below mean residual (tighter than average)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize hard as post_residual approaches the "dead zone".
    if post_residual > 0 {
        // dead space severity grows quadratically for small unusable gaps
        let dead = 100.0 - post_residual as f64; // how full the bin becomes
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64) / 10.0; // tiny gaps are worst
        } else {
            score += 8.0 * (1.0 - dead / 100.0); // mild penalty for leftover space
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover: dead space confirmed
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making new bins less attractive.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score = 120.0 + 10.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is bad.
        score += 0.8 * mean_residual;
        // Late in stream, avoid opening new bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If only one bin fits and it isn't this new bin, new bin is very unattractive.
        if fitting_bins_count <= 1 {
            score += 100.0;
        }
    } else {
        // Existing bin: slight preference when it deviates from mean residual
        // (fill the emptiest bins first to consolidate).
        score -= 0.3 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 600.0;
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // Smooth penalty growing with mismatch, scaled by lookahead size.
            score += (diff / (next_item_size as f64 + 1.0)) * 120.0;
            // If next item cannot fit in the post-residual, penalize proportionally.
            if post_residual < next_item_size {
                score += 80.0;
            }
        }
    }

    // Tightness reward: bins with small residual relative to mean are precious.
    let tightness = (mean_residual - post_residual as f64).max(0.0);
    score += tightness * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize opening a new bin when open bins could still take the item,
    // unless the fit is very tight.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 300.0
            - (item_size as f64 / bin_capacity as f64) * 150.0
            + mean_residual * 0.3;
        score += new_bin_penalty.max(0.0);
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score -= (1.0 - progress) * 100.0;
    }

    // Slight preference to spread load when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space: post_residual that cannot fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < item_size {
        // residual smaller than current item: less reusable
        score += 6.0;
    }

    // Lookahead: reward if next item fits into post residual exactly/well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 10.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should be penalized unless
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (mean_residual.max(1.0));
        if fitting_bins_count > 0 {
            // open bins exist that fit: penalize new bin, more when residuals are usable
            score += 20.0 + 15.0 * (1.0 - pressure.min(1.0));
        } else {
            score -= 5.0;
        }
        // early in stream, opening bins is cheap; late, consolidate
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild load balancing: many open bins -> prefer consolidating into low-residual bins.
    if open_bins_count > 4 {
        score -= 0.05 * (open_bins_count as f64) * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild penalty on large residual (keep bins tight).
    // Late stream: amplified penalty so dead space is punished more.
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress) + norm_post * (1.0 - progress);
    score += 8.0 * poly;

    // Reward tight fits with smooth quadratic decay around zero post residual.
    let tightness = 1.0 - norm_post;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Penalize creating residual that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            let gap = (nxt - post) / cap;
            score += 6.0 * gap * (1.0 + progress);
        } else {
            // Smooth reward when lookahead fits into the future residual.
            let fit = post / cap;
            score -= 2.0 * fit * (1.0 - fit) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_post * norm_post);
    }

    // Mild coupling with mean residual: prefer bins near the mean (balance).
    let dev = (post - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate: neutral baseline with slight progress-dependent cost
    // so early stream prefers consolidation, late stream allows opening bins
    // when open bins would waste space.
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.3 * progress) + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common
    // item sizes (10/20/25/50) are more reusable -> reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 4.0; }
        if pr % 50 == 0 { harmonic_bonus += 5.0; }
        // Exact-fit classes: tiny dead space is fine.
        if pr < 10 { harmonic_bonus += 8.0; }
        // Bad zone: residual in 11..19 is rarely usable.
        if pr >= 11 && pr <= 19 { harmonic_bonus -= 7.0; }
        if pr >= 21 && pr <= 24 { harmonic_bonus -= 5.0; }
        if pr >= 26 && pr <= 29 { harmonic_bonus -= 4.0; }
        score -= harmonic_bonus;
    } else {
        score -= 15.0; // perfect closure
    }

    // Lookahead coupling: if next item fits exactly into post-residual,
    // strongly reward this placement.
    if next_item_size > 0 && next_item_size <= pr {
        let diff = pr - next_item_size;
        if diff == 0 {
            score -= 20.0;
        } else if diff <= 10 {
            score -= 10.0;
        } else {
            score -= 4.0 * (1.0 - diff as f64 / cap);
        }
        // Harmonic match between leftover and next item size classes
        if diff % next_item_size == 0 { score -= 3.0; }
    } else if next_item_size > pr {
        // Next item won't fit here anyway; mildly penalize wasting space.
        score += 2.0 * (next_item_size as f64 - pr as f64) / cap;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a bin is good only when
    // crowded bins have large mean residual (fragmentation) or the
    // item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        score = 30.0
            + 40.0 * fragmentation          // open bins are fragmented -> new bin ok
            + 10.0 * progress               // late in stream, prefer consolidation unless fragmented
            - if fitting_bins_count == 0 { 25.0 } else { 0.0 };
    } else {
        // Prefer denser bins (small residual relative to mean).
        score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);
        // Slight preference for bins that already hold items as bins grow.
        score -= 0.5 * open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (0..=10) are nearly unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 35.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 12.0;
    }

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residual that could still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when it truly beats dead space.
    if bin_residual == bin_capacity {
        score -= 5.0;
        // Penalize new bins more when many bins are already open.
        score += open_bins_count as f64 * 2.0;
        // But if the item is large relative to mean residual, a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 25.0 - slack * 1.5;
            } else {
                score -= 5.0 / slack;
            }
        } else {
            // Next item won't fit here; penalize tight leftovers that become dead space.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 0.6;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals close to the item need.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But allow new bin if item is large and open bins are fragmented.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild progression scaling: later in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (100.0 - post_residual as f64) * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize large dead space, especially if next item can't use it
        let t = step_index as f64 / (total_items.max(1) as f64);
        let waste_weight = 1.0 + 2.0 * t;
        score += waste_weight * (post_residual as f64).powf(1.4) / bin_capacity as f64;
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 15.0 + 0.5 * post_residual as f64;
        } else if next_item_size > 0 {
            // reward bins whose residual matches next item well
            let gap = post_residual as i64 - next_item_size as i64;
            if gap == 0 {
                score -= 200.0;
            } else {
                score += 0.3 * gap as f64;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only attractive when fits are terrible
    if bin_residual == bin_capacity {
        let open_f = open_bins_count.max(1) as f64;
        // default penalty so we prefer existing bins with decent fits
        score += 120.0;
        // if all fits are poor (large post residual everywhere), allow new bin
        let mean_gap = (mean_residual - item_size as f64).abs();
        if mean_gap > 30.0 {
            score -= 60.0 + 2.0 * mean_gap.min(80.0);
        }
        // early stream: keep bins consolidated
        if open_bins_count < 3 {
            score += 100.0;
        }
        // late stream with many bins: consolidation pressure
        score += 0.5 * open_f;
    }

    // Mild preference for tighter bins among ties
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize post_residual to [0,1]
    let pr = post_residual as f64 / cap;

    // Non-linear polynomial coupling: waste grows super-linearly with residual,
    // modulated by stream progress (late in stream, dead space is costlier).
    let waste_poly = pr * pr * (1.0 + progress) + pr * pr * pr * (0.5 + 2.0 * progress);
    score += 40.0 * waste_poly;

    // Reward tight fits: subtract when post_residual is small relative to capacity.
    let tightness = 1.0 - pr;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit here; penalize proportionally to overshoot.
            let over = (nxt - post_residual as f64) / cap;
            score += 6.0 * over * over;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this bin is far from mean residual
    // (prefer consolidating around the average fill level).
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate adjustment: an empty bin gets a slight penalty so we only
    // open when existing bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect packing, strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post residual: residuals that form "usable"
    // classes (multiples of common item sizes) are more valuable than
    // dead space. Penalize residuals in awkward classes.
    let small = post_residual.min(bin_capacity - post_residual);
    if post_residual > 0 {
        let usable = if post_residual % 10 == 0 {
            0.0
        } else if post_residual % 5 == 0 {
            5.0
        } else if post_residual >= 10 {
            10.0
        } else {
            25.0
        };
        score += usable;
        // Tiny dead space is worthless; large residual keeps flexibility.
        if post_residual < 10 {
            score += 20.0;
        }
        let _ = small;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward heavily; if the next item cannot fit here anyway, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate: opening a new bin wastes mean_residual across all
    // open bins. Favor new bins only when open bins are very full on average
    // or when the fit into an existing bin would leave a bad residual.
    if bin_residual == bin_capacity {
        let waste = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 60.0 * waste - 20.0 * progress;
        if post_residual == bin_capacity {
            // exact fit into fresh bin only sensible for huge items
            if item_size >= 80 { score -= 40.0; }
        }
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 50.0;
        }
    }

    // Prefer filling bins with larger residual when many bins are open
    // (reduces bin count pressure).
    score -= 0.1 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual size.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / 20.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 25.0 + open_pressure * 30.0;
    } else {
        score -= open_pressure * 5.0;
    }

    // Lookahead: if next item fits in post_residual, reward leaving usable space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // Penalize if post_residual is small but nonzero relative to next item.
            if post_residual > 0 && post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // keeping large-residual bins for future larger items.
    if bin_residual == bin_capacity {
        score += (mean_residual / 10.0).min(8.0);
    } else if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += ((bin_residual as f64) - mean_residual) * 0.1;
    }

    // Early stream: be slightly more willing to open new bins to build a spread.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the residual (good chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // residual too small for next item: penalize dead space
        score += 8.0;
    }

    // Reward tight fits overall (small post residual relative to capacity)
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize wasting a large-residual bin when mean residual is high
    if (post_residual as f64) > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate: only attractive when current item is huge relative to open capacity
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Late in the stream: prefer filling existing bins harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that become dead space relative to item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // dead space for the next item — penalize proportionally
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        } else {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have poor fit potential.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 45.0 + 25.0 * (1.0 - progress) - 15.0 * tightness;
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Mild pressure against proliferating bins with large mean residual.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr;

    // Base: reward tight fits (small post_residual) with a non-linear decay
    score -= (1.0 - norm_pr).powi(3) * cap * 0.6;

    // Smooth coupling: how well the next item fits the post-residual
    let gap = (norm_pr - norm_next).abs();
    score -= (1.0 - gap).powi(2) * cap * 0.35 * (0.5 + 0.5 * t);

    // Penalize leaving residuals that are likely dead space (too small for typical items)
    let deadness = (norm_pr * (1.0 - norm_pr) * 4.0).powi(2); // peaks at half-full residual
    score += deadness * cap * 0.15 * (1.0 - t);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.8 + 0.4 * t);
    }

    // Mild penalty for spreading across many open bins early on
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - t);

    // Mean-residual alignment: prefer bins near the mean residual (keeps balance)
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * cap * 0.2;

    // Smooth stream-progress tilt: later in the stream, prefer consolidation
    score -= t * norm_item * cap * 0.25;

    // Small penalty when the new-bin candidate competes (empty residual)
    if bin_residual == bin_capacity {
        score += cap * (0.9 - 0.6 * (1.0 - (norm_next - norm_item).abs())) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as "dead-space classes"
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -6.0,               // perfectly full or multiple of 10 -> ideal
        1 | 2 => 1.5,            // tiny slivers, nearly useless
        3..=5 => 0.5,            // small but sometimes usable
        6..=9 => -1.0,           // medium residuals still usable
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: post_residual bucketed by capacity fractions
    let quarter = bin_capacity / 4;
    if post_residual < quarter / 2 {
        score += 8.0;            // dead space below 1/8 capacity
    } else if post_residual <= quarter {
        score -= 2.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 1.0;
    }

    // Lookahead coupling: reward residuals that exactly fit the next item's class
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            if post_residual % next_item_size.max(1) == 0 {
                score -= 7.0;    // next item divides residual perfectly
            } else if post_residual - next_item_size < 10 {
                score -= 4.0;    // next item nearly fills bin
            } else {
                score -= 1.5;
            }
        } else {
            // next item can't use this residual: penalize if residual is small
            if post_residual < 20 {
                score += 3.0;
            }
            // if next item would need a fresh bin anyway, prefer conserving this bin
            if next_item_size > mean_residual {
                score -= 2.0;
            }
        }
    }

    // Last-chance bonus: sole fitting bin should be strongly preferred
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin gets a mild default penalty so we
    // only open when no open bin scores better, but allow it for bad fits.
    if bin_residual == bin_capacity {
        score += 4.0 + mean_residual * 0.05;
        if post_residual == bin_capacity {
            // opening a bin for a huge item that wastes little: acceptable
            if item_size > bin_capacity * 7 / 10 {
                score -= 6.0;
            }
        }
    }

    // Tight fit reward: item fills bin exactly or near-exactly
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // Small item into large residual: mild penalty (wasteful pairing)
    if item_size * 4 < bin_residual {
        score += 1.0;
    }

    // Stream progression: late in stream, prefer closing bins out
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Congestion: many open bins -> favor filling existing ones
    if open_bins_count > 8 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= ~10 units) are pure waste. Penalize hard.
    let dead_threshold = 9.0;
    if post > 0.0 && post <= dead_threshold {
        score += 60.0 * (1.0 - post / dead_threshold); // up to +60 for 1-unit slivers
    }

    // Small residual above dead threshold but below next item: still likely waste
    if next_item_size > 0 && post > 0.0 && (post as u32) < next_item_size {
        score += 15.0 * (1.0 - post / cap);
    }

    // Reward perfect / near-perfect fits strongly
    if post == 0 {
        score -= 100.0;
    } else if (post as u32) == next_item_size && next_item_size > 0 {
        score -= 40.0; // leaves exactly the room the next item needs
    }

    // Reward tight fit relative to bin capacity
    score -= 25.0 * (item_size as f64 / cap) * (bin_residual as f64 / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins whose residual is close to what we consume (avoid fragmenting fat bins)
    score += 0.3 * (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.1;

    // New-bin candidate: only attractive when existing bins would create bad dead space
    if bin_residual == bin_capacity {
        // neutral-ish baseline; dead-space penalties above on real bins make poor
        // fits lose, while good fits (small post_residual) beat this.
        score = 45.0 + 2.0 * open_bins_count as f64 * 0.2 - 10.0 * (item_size as f64 / cap);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0 * (next_item_size as f64 / cap);
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative at all
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match: strong reward.
        if diff < 1.0 {
            score -= 40.0;
        } else if post_residual as f64 >= nxt {
            // Next item fits in leftover: reward proportional to tightness.
            score -= 25.0 * (nxt / post_residual as f64);
            // Extra bonus if leftover after the lookahead item would be tiny.
            let second = post_residual as f64 - nxt;
            if second < 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit: penalize leaving awkward space.
            score += 8.0 * (1.0 - post_residual as f64 / nxt);
        }
    }

    // Tightness reward: small post_residual is good packing.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize bins with residual far below mean (wasted potential),
    // reward bins near or above mean residual that absorb the item.
    if post_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0 * (mean_residual - post_residual as f64).min(30.0) / 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count <= 1 && post_residual as f64 > 25.0;
        if poor_fit {
            score -= 12.0; // opening fresh bin is reasonable
        } else {
            score += 10.0; // discourage opening new bins when a fit exists
        }
    }

    // Late in the stream: consolidate, favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Many open bins: prefer reusing to control bin count.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Tightness: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the
    // next item; penalize residuals that strand the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // Extra reward for a two-item perfect closure.
            if post_residual == next_item_size {
                score -= 120.0;
            }
        } else {
            // Dead space relative to the next item's need.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 0.5 * post_residual as f64;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing capacity rather than opening new bins.
    if open_bins_count > 4 {
        score -= 0.15 * open_bins_count as f64;
    }
    if mean_residual > 40.0 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when existing
    // bins are poor fits or residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base penalty so full/low-residual bins always win.
        score += 60.0;
        // But if no open bin fits well (many bins, high mean residual, or
        // this bin is the only fitting one), relax the penalty.
        if fitting_bins_count <= 1 {
            score -= 90.0;
        }
        if mean_residual > 55.0 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Small fragmentation penalty scaled by progress: late in the stream,
    // tiny residuals are nearly worthless.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, avoid over-tightening bins (keep flexibility);
    // late in the stream, aggressively reward tight fits.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let w = 1.0 + 2.0 * progress; // tightness reward grows over the stream
    score -= w * (1.0 - pr_norm) * (1.0 - pr_norm) * 30.0;

    // Penalize dead space: residual too small to ever hold a typical item,
    // penalized more strongly as the stream progresses.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * (20.0 + 60.0 * progress);

    // Smooth quadratic penalty on residual deviating from mean residual
    // (keeps residual distribution balanced across open bins).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward;
    // if it fits but leaves more dead space, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item cannot use this residual: slight penalty scaled by waste
            score += 0.1 * pr;
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: neutral-ish baseline; open new bin only when all
    // open bins would create bad fits (handled by the terms above).
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * progress * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item-size divisors
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward perfect / near-perfect fills
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Modulo harmonic classes: post_residual divisible by small integers is more reusable
    let mut harmonic_bonus = 0.0;
    if post_residual % 10 == 0 { harmonic_bonus += 60.0; }
    if post_residual % 20 == 0 { harmonic_bonus += 40.0; }
    if post_residual % 25 == 0 { harmonic_bonus += 30.0; }
    if post_residual % 50 == 0 { harmonic_bonus += 50.0; }
    score -= harmonic_bonus;

    // Lookahead coupling: can next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 100.0 - (gap as f64).min(100.0);
            // harmonic match of gap
            if gap % 10 == 0 { score -= 30.0; }
        } else {
            // next item won't fit here: penalize wasted opportunity less if residual small
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize choosing a tight bin when many bins fit (preserve flexibility)
    if fitting_bins_count > 1 && post_residual > 40 {
        score += (post_residual as f64 - 40.0) * 0.3;
    }

    // Dead-space penalty: residuals in "awkward" class (just below common sizes)
    for s in [10u32, 20, 25, 30, 40, 50] {
        if post_residual > 0 && post_residual < s {
            score += 8.0 * (s as f64 - pr) / s as f64;
        }
    }

    // New-bin candidate logic: empty bin should be chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 60.0;
        // more open bins with high mean residual -> prefer packing into existing bins
        score += (open_bins_count as f64).sqrt() * 15.0 + mean_residual * 0.4;
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
        // if no open bin can take next item well, new bin more attractive
        if next_item_size > 0 && next_item_size > post_residual.min(item_size) {
            score -= 20.0;
        }
    }

    // Mild preference for fuller bins overall (best-fit core)
    score -= (1.0 - pr / cap) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are wasted space -> heavy penalty.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure on number of open bins: when many bins are open, prefer
    // packing into existing bins over opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline is a fresh residual; penalize when
        // open-bin pressure is high, reward slightly when few bins open
        // (keeps future large items placeable).
        score += open_pressure;
        if fitting_bins_count > 0 {
            // Opening a new bin while existing ones fit is extra cost.
            score += 15.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure.
        score -= open_pressure * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, this placement is excellent; if next item is large and
    // this bin is fresh, opening is justified.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual && post_residual > 0 {
            score -= 10.0;
        }
        if bin_residual == bin_capacity && next_item_size > item_size {
            score -= 8.0; // fresh bin accommodates bigger follow-up item
        }
    }

    // Mild preference for filling bins with larger residual gaps relative
    // to the mean residual across open bins (balance avoidance of many
    // half-empty bins).
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    // Late in the stream, tighten packing further (less room for slack).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            // tighter fit after placement is better
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize large dead space relative to mean residual
            score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);
        }
    }

    // Prefer bins whose residual was already small (tight packing)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // late in the stream, avoid opening new bins with small leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Slight penalty for very small post residuals that waste capacity
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Nonlinear dead-space penalty: small leftovers are fine, large ones waste capacity.
    score += 22.0 * (post / cap).powf(2.2);

    // Reward bins that are already well-filled (prefer denser bins).
    score -= 0.12 * (cap - bin_residual as f64);

    // Lookahead (k=2): favor bins whose post-residual can host the next item,
    // extra reward when the next item would fit snugly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post {
            score -= 7.0 + 12.0 * (1.0 - n / cap);
        } else {
            // Next item won't chain here; early in the stream this is worse
            // (plenty of future items to pair), late it matters less.
            score += 5.0 * (1.0 - t);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 28.0;
    }

    // New-bin candidate penalty: opening a bin is costly, but relax this
    // late in the stream or when many bins are open and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = ((mean_residual - cap * 0.5).abs() / cap).clamp(0.0, 1.0);
        score += 20.0 + 0.15 * open_bins_count as f64 - 8.0 * t - 6.0 * fragmentation;
    }

    // Mild pull toward bins whose residual is near the current mean
    // (keeps residual distribution compact for future items).
    score += 0.04 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space (non-linear in post_residual)
    let mut score = pr * (1.0 + 0.9 * norm_pr);

    // Smooth stream-progress coupling: late in the stream, tight packing matters more
    let late = progress * progress;
    score *= 1.0 + 0.6 * late * norm_pr;

    // Reward bins that are well-filled relative to the mean residual of open bins
    let fill = (item_size as f64) / cap;
    score -= 18.0 * fill * (1.0 - late * 0.5);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // existing fits are poor (post_residual large) or many bins are open
    if bin_residual == bin_capacity {
        let poor_fit = norm_pr; // residual after placing into empty bin = capacity - item
        let escape = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (0.5 + 0.5 * poor_fit);
        score = cap * (0.55 + 0.5 * poor_fit) - 30.0 * escape;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64 / cap));
    }
    // If next item nearly fits but not quite, mild penalty for stranding space
    if next_item_size > 0 && (next_item_size as f64) > pr && pr > 0.0 {
        score += 4.0 * (1.0 - (next_item_size as f64 - pr) / cap);
    }

    // Tie-break toward bins with residuals close to the mean (harmonic consolidation)
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    // Residuals that are multiples of common item sizes (or small) are "reusable" classes.
    let pr = post_residual;
    let reusable = (pr % 10 == 0) as f64 + (pr % 20 == 0) as f64 + (pr % 25 == 0) as f64;
    score -= reusable * 6.0;

    // Dead-space penalty: small nonzero residuals are hard to fill.
    if pr > 0 && pr < 10 {
        score += 18.0 - (pr as f64) * 1.5;
    }

    // Perfect fit reward.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // Reward if next item leaves another reusable class residual.
            let nxt_reusable = ((pr - next_item_size) % 10 == 0) as f64;
            score -= 20.0 * nxt_reusable - slack * 0.15;
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += ((next_item_size - pr) as f64) * 0.12;
        }
    }

    // Fraction of capacity wasted by this placement.
    let waste_frac = (post_residual as f64) / cap;
    score += waste_frac * waste_frac * 25.0;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap; // high => open bins nearly full
        let big_item = item_size as f64 / cap;
        // Prefer new bin when item is big and open bins are tight; otherwise penalize.
        score += 45.0 - big_item * 55.0 - crowded * 25.0;
        // Late in the stream, consolidation matters more; discourage new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // Many open bins: discourage adding another.
        score += (open_bins_count as f64).min(20.0) * 1.5;
    }

    // Mild preference for fuller bins (tight packing) via mean residual coupling.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use well
    // are pure waste. Penalize tiny non-zero residuals harshly (1..=9 unusable),
    // while zero residual (perfect fit) gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 9 {
        score += (10.0 - post_residual as f64) * 6.0;
    } else if post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward relative tightness of the fit (fraction of bin consumed).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // residual still usable by next item: mild reward proportional to slack
            score -= 4.0;
        } else {
            // next item won't fit here: residual risks becoming dead space
            score += 3.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (1.0 + progress);

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it's a good candidate to absorb the item (reduce dispersion).
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.15;

    // New-bin candidate: only attractive when open bins are nearly full /
    // residuals are small. Penalize opening a new bin when consolidation is viable.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (no dead space at all).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this is a perfect chain placement -> reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits snugly in the remaining space (small leftover after chain).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_left = post_residual - next_item_size;
        score -= 200.0 - (chain_left as f64) * 1.5;
    }
    // Next item would NOT fit here: mild penalty scaled by wasted potential.
    if next_item_size > 0 && next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64).min(50.0) * 0.5;
    }

    // Prefer bins whose residual is already below the mean (tight bins first),
    // leaving large-residual bins flexible for future items.
    score += ((mean_residual - post_residual as f64).max(0.0)) * 0.3;
    score -= ((post_residual as f64 - mean_residual).max(0.0)) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when all open bins are quite full
    // (mean residual small) or the fit here would leave big dead space.
    if bin_residual == bin_capacity {
        let dead = post_residual as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Reward opening a new bin when existing bins are tight and the
        // alternative fit is bad; penalize otherwise.
        score += 120.0 * (1.0 - pressure) - dead * 0.5;
        if post_residual > 60 {
            score += 100.0; // very poor fit elsewhere -> open new bin
        }
    }

    // Slight preference to fill earlier-opened bins as stream progresses.
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: non-linear bonus as post_residual approaches zero.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead_zone = (pr < 25.0) as i32 as f64;
        score += 12.0 * dead_zone * (1.0 - pr / 25.0);
    }

    // Lookahead: reward if next item fits in post_residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let slack = post_residual as f64 - nxt;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Penalize residuals that block the next item badly.
            score += 4.0 * (1.0 - (post_residual as f64 / nxt).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to keep options open for tighter bins.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state coupling: when mean residual is low, conserve open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * mean_residual * progress;

    // New-bin candidate handling: make empty bin attractive only when
    // open bins are nearly full or item is large.
    if bin_residual == bin_capacity {
        let avg_fill_pressure = 1.0 - mean_residual / cap;
        let item_pressure = item_size as f64 / cap;
        let pressure = 0.6 * avg_fill_pressure + 0.4 * item_pressure;
        // Base cost of opening a bin, discounted by pressure and progress.
        score = cap * (1.0 - pressure) + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 5.0; // fresh bin useful for upcoming medium items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress.
    let base = pr * (1.0 + 0.8 * progress * norm_pr) - 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward tight fits: smooth quadratic bonus for small normalized residuals.
    let tight_fit = -30.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Late-stream: penalize large residuals more aggressively (fewer chances to fill them).
    let late_penalty = 25.0 * progress * norm_pr * norm_pr;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    let last_chance = if fitting_bins_count == 1 { -20.0 } else { 0.0 };

    // Lookahead: reward if the next item fits into the post-residual.
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -10.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)))
    } else if next_item_size > 0 {
        5.0 * (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };

    // New-bin candidate: keep it attractive when residuals are fragmented,
    // unattractive when a good fit exists in open bins.
    let is_new_bin = bin_residual == bin_capacity;
    let new_bin_bias = if is_new_bin {
        15.0 - 20.0 * (mean_residual / cap).min(1.0) + 10.0 * progress
    } else {
        0.0
    };

    // Slight preference for bins below mean residual (balance fragmentation).
    let mean_coupling = 3.0 * (mean_residual - pr) / cap;

    base + tight_fit + late_penalty + last_chance + lookahead + new_bin_bias + mean_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: quantize leftover space into capacity fractions.
    let post = post_residual as f64;
    let class = (post / (cap / 4.0)).floor(); // 0..4 harmonic class of leftover
    score += class * 3.0; // prefer bins whose leftover falls into a lower class (tighter fit)

    // Dead-space penalty: leftover too small to hold even the smallest item (1..100 unknown dist).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Integer-division threshold: leftover divisible chunks (modulo arithmetic on residual).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0; // leftover is a clean harmonic fraction of capacity -> reusable
    }
    if post_residual % 20 == 0 && post_residual > 0 && post_residual % 25 != 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chains nicely
            // exact chain: next item fills leftover exactly
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize more if leftover is small-ish (wasted potential)
            score += (post / cap) * 15.0;
        }
    }

    // Last-chance bin: only bin that fits the item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin: high, so only chosen when open bins score badly.
        score = cap * 0.9 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += (mean_residual / cap) * 30.0;
        // But if this item is huge and would leave tiny leftovers everywhere, new bin helps.
        if item_size as f64 / cap > 0.7 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
    } else {
        // Reward using bins whose residual is close to item size (tight packing).
        let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
        score -= tightness * 10.0;
        // Slight pressure to keep number of open bins low.
        score += open_bins_count as f64 * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (small waste) with a discount.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize opening new bins.
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when open bins are crowded or fit is bad.
        score -= open_pressure * 2.0;
        score += 25.0; // base reluctance to open a new bin
        // If next item could fill this fresh bin well, mild bonus.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using it more when many bins are open.
        score -= open_pressure * 0.5;
    }

    // Lookahead coupling: avoid leaving a gap that wastes space the next item
    // could have used in this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 > 0.0 && next > post_residual as f64 {
            // Next item cannot fit here anyway -> gap is truly dead.
            score += 0.3 * (next - post_residual as f64).min(30.0);
        } else if next > 0.0 && (post_residual as f64 - next).abs() <= 5.0 {
            // Next item pairs perfectly with this residual.
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is close to item size
    // (tight fit relative to fleet average).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * tightness;
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 3.0;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does next item fit exactly in the post residual?
    if next_item_size > 0 {
        if post_residual == next_item_size {
