        } else if post_residual >= next_item_size {
            score -= 60.0; // next item can also go here: keep pair together
        } else {
            score += 30.0; // dead space for next item
        }
    }

    // Tight fit reward: small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 150.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize creating residuals below the minimum item size (1..100 unknown, assume ~10 dead zone)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Compare against mean residual: prefer bins already more filled than average
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.5;

    // Early in stream: allow opening new bins cheaply to build good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / (step_index as f64 + 1.0)).max(0.0);
        score = 100.0 + 50.0 * progress - 40.0 * pressure.min(2.0);
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: early on, keep residuals flexible; late, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative tightness of fit: reward near-perfect fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.3;
        }
    } else {
        // Last item: filling tightly is best.
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: discourage opening a new bin unless current
    // placements would waste a lot of space.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64; // avg free space in open bins
        // If open bins are quite full and crowded, a fresh bin is reasonable.
        let open_bonus = (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += 20.0 + open_bonus - 40.0 * (1.0 - pressure) * (1.0 - progress);
        // Late in the stream, opening new bins is more acceptable.
        score -= 25.0 * progress;
    } else {
        // Prefer bins whose residual is below the mean (fill the emptier ones less,
        // keep a spread of mid-size residuals for future items).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Mild global congestion effect: many open bins -> consolidate.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr_norm * (1.0 + 0.6 * progress * progress);

    // Penalize large dead space quadratically, stronger late in stream
    score += 0.35 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits (small post_residual) with a cubic shaping term
    score -= 0.25 * (1.0 - pr_norm).powi(3) * (0.4 + 0.6 * progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 + fit_ratio);
    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += 0.15 * ((mean_residual - bin_residual as f64) / cap).abs();

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 0.4 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 0.2 * pr_norm;
    }

    // Mild preference for consolidating into fewer bins early on
    score += 0.05 * (open_bins_count as f64) / (1.0 + total_items as f64) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

