    // residue classes (multiples of common item sizes) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let fill_frac = pr / cap;

    // Penalize residuals in awkward classes: 1..=9 (dead slivers).
    if post_residual <= 9 {
        score += 60.0 - post_residual as f64 * 3.0; // tiny slivers are near-waste
    }

    // Reward residuals that are harmonically aligned (divisible by 10 or 25).
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Integer-division thresholds: classify post_residual into coarse buckets.
    let bucket = post_residual / 10; // 0..=10
    score -= (bucket as f64) * 2.5; // larger usable residual preferred, mildly

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward;
    // if next item is just barely too big, penalize (near-miss dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 15.0 + 0.2 * nxt;
        } else {
            let gap = next_item_size as u32 - post_residual;
            if gap <= 10 {
                score += 25.0; // near-miss: this bin becomes useless for next item
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 4.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin
    // would leave a large residual and the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening fresh bins early is fine; late, prefer packing into opens.
        score = cap * (0.9 + 0.5 * progress) + 10.0;
    }

    // Slight pull toward bins close to mean residual (balanced packing).
    score += 0.05 * (pr - mean_residual).abs();

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (post_residual near zero but usable).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across too many bins,
    // but favor filling existing bins over opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // Allow new bin only if no open bin fits well (tight fit elsewhere wins anyway).
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Mild reward for using existing bins as open count grows.
        score -= 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Progression: later in the stream, tighten up more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain
        } else if post_residual > next_item_size {
            // next item fits; reward proportional to how much would remain after next
            let chain_residual = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize leaving space that next item almost fits
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 12.0 + gap as f64; // near-miss dead space
            }
        }
    }

    // Compare post_residual against mean residual: avoid making bin much worse than average
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize new-bin opening unless current bins are all poor fits
    if bin_residual == bin_capacity {
        // new empty bin: post_residual == capacity - item_size
        score += 15.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Late in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize leaving dead space that likely can't be used:
    // post_residual smaller than the smallest possible item (1) is impossible here,
    // but a small nonzero residual that next_item_size can't use is wasteful.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can also host the lookahead item: strong reward.
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else {
            // Dead space for the lookahead item: penalty scaled by wasted gap.
            let gap = (post_residual as f64 - (post_residual as f64 % 1.0)).min(next_item_size as f64 - post_residual as f64);
            score += 0.5 * gap.max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // When many bins fit the item, prefer bins that keep flexible residuals.
    if fitting_bins_count > 1 {
        // Penalize residuals far from commonly usable sizes (multiples of small items).
        let flexible = (post_residual as f64 / 10.0).fract().abs();
        score += 5.0 * flexible;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this fresh bin's
    // comparison baseline. Prefer new bin only when current bin would leave large unusable
    // residual and the item is large.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early stream: opening bins is cheap-ish; late stream: avoid new bins.
        let new_bin_penalty = 20.0 + 30.0 * progress;
        score += new_bin_penalty - 0.1 * waste;
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.3 * dev;

    // Slight preference for bins with larger residual when item is large (avoid fragmentation).
    if item_size > bin_capacity / 2 {
        score += 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Mild time-coupled pressure: as stream progresses, discourage sloppy fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: prefer low post-residual, with non-linear polynomial shaping.
    let mut score = pr
        + 18.0 * prn * prn * cap
        - 30.0 * prn * (1.0 - prn) * cap * (0.5 + 0.5 * progress);

    // Tight fits rewarded more strongly as stream progresses.
    let tightness = 1.0 - prn;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space: residuals too small for typical items (non-linear gate).
    let dead = (1.0 - prn).min(0.25) / 0.25;
    score += 40.0 * dead * dead * (1.0 - progress);

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).ln();
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus (smooth).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 / (1.0 + gap * gap / 50.0);
        score -= 30.0 * fit_next;
    } else {
        // Last item: minimize final waste aggressively.
        score -= 20.0 * tightness;
    }

    // Coupling with mean residual: prefer bins below mean residual (compact usage).
    let mrn = (mean_residual / cap).clamp(0.0, 1.0);
    score += 12.0 * (prn - mrn) * (prn - mrn) * cap * (1.0 - progress);

    // Slight preference to fill existing bins rather than open new ones early.
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: make empty bin less attractive unless it enables near-perfect packing.
    if bin_residual == bin_capacity {
        let ideal = 1.0 - (item_size as f64 / cap);
        score += 15.0 - 20.0 * ideal * ideal;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity fractions / 10 classes
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1 fraction free after placement

    // Penalize leftovers that fall into "dead" harmonic classes:
    // residues that no typical item (1..=100) can nicely reuse.
    // Class boundaries at multiples of 100/10 = 10 units.
    let class = (post_residual / 10) as f64;
    let class_center = class * 10.0 + 5.0;
    let deviation = (post_residual as f64 - class_center).abs();

    // Reward leftovers whose class is highly reusable (small residues are bad,
    // mid-size residues 30..=60 are excellent for mid items).
    let reusability = match post_residual {
        0 => 8.0,          // perfect fit, zero waste
        1..=9 => -6.0,     // awkward sliver, nearly dead space
        10..=19 => -2.0,
        20..=29 => 2.0,
        30..=49 => 5.0,    // sweet spot: fits many mid items
        50..=69 => 3.0,
        70..=89 => 0.0,
        _ => -3.0,         // barely used bin, wasteful placement
    };
    score -= reusability;

    // Small penalty for intra-class misalignment (harmonic phase)
    score += 0.15 * deviation;

    // Modulo coupling: leftover congruent to 0 mod 10 is maximally reusable
    if post_residual % 10 == 0 {
        score -= 2.0;
    } else if post_residual % 5 == 0 {
        score -= 0.5;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            let used_frac = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * used_frac;
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Progress-aware conservatism: early in the stream, tolerate loose fits;
    // late in the stream, tighten packing (favor small post_residual harder).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // Encourage balancing residuals: bins far from mean residual get a nudge
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate (empty bin): only attractive when item is large or
    // no good existing fit exists. Penalize mildly so existing good fits win,
    // but a huge item opening a fresh bin is fine.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 {
            score -= 1.0; // large items justify fresh bins
        } else {
            score += 3.0; // small items should use existing space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items (1..100) are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0; // only tiny items can use it
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit, fully packed bin
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing, avoid fragmentation
    score += 0.05 * open_bins_count as f64;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocks the next item
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 1 {
            score += 50.0; // keep using the last-chance open bin
        } else {
            score += 5.0; // mild preference for existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space).
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 2 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; penalize proportionally to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: keep it attractive only when current bins would leave large waste.
    if bin_residual == bin_capacity {
        // New bin baseline: neutral residual, but avoid opening bins when a good fit exists.
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
        if item_size >= bin_capacity / 2 {
            score -= 20.0; // big items are fine in fresh bins
        }
    }

    // Penalize bins that are outliers vs. mean residual (keep residuals balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Prefer filling older/fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item (k=2 lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 + 0.15 * (bin_capacity as f64 - chain_fit);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space the next item cannot use.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins; encourage consolidation.
    score += 0.6 * open_bins_count as f64 * tightness;

    // Deviation from mean residual: prefer bins below mean residual (already fuller).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        let no_alternative = fitting_bins_count == 0;
        if no_alternative || (bad_fit && next_item_size > 0 && next_item_size > post_residual) {
            score -= 15.0;
        } else {
            score += 40.0 + 0.2 * open_bins_count as f64;
        }
    }

    // Time horizon: early in stream, be pickier about residual quality; late, prioritize packing now.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, but its value is modulated by stream progress.
    // Early on, prefer tight fills (low post_residual); late, dead space matters even more.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: quadratic + cubic in normalized post residual,
    // weighted by progress so late-stage dead space is penalized super-linearly.
    score += 25.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score -= 12.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress);

    // Reward near-perfect fits via smooth Gaussian-like bump around post_residual ~ 0..5.
    let fit_quality = (norm_pr * 4.0).exp();
    score -= 18.0 * fit_quality * (1.0 - progress * 0.5);

    // Last-chance bonus: smooth, avoids opening a new bin when only one bin fits.
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual alignment.
    let mean_gap = (mean_residual - bin_residual as f64).abs() / cap;
    score += 4.0 * mean_gap * mean_gap * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor,
    // with the penalty decaying as the stream progresses.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common item sizes) are more attractive.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        // Dead-space penalty grows when post_residual is an "awkward" class.
        let awkward = if pr < 10 {
            3.0
        } else if pr % 10 == 0 {
            0.0
        } else if pr % 25 == 0 || pr % 20 == 0 {
            0.5
        } else if pr % 5 == 0 {
            1.0
        } else {
            2.5
        };
        score += awkward * (pr as f64).sqrt() * 2.0;

        // Reward bins whose residual is exactly reachable by next_item_size.
        if next_item_size > 0 && pr >= next_item_size {
            let diff = pr - next_item_size;
            if diff == 0 {
                score -= 40.0;
            } else if diff <= 10 {
                score -= 15.0;
            } else if diff % 10 == 0 {
                score -= 8.0;
            }
        }
        // Penalize wasting a large residual on a tiny item.
        if next_item_size > 0 && pr >= next_item_size {
            let waste = (pr as f64 - next_item_size as f64) / bin_capacity as f64;
            score += waste * 10.0;
        }
        // Penalize leaving residuals that nothing (>=10) can ever use.
        if pr < 10 {
            score += 35.0;
        }
    }

    // Capacity fraction coupling: bins already near full are attractive.
    let fill = 1.0 - (bin_residual as f64) / bin_capacity as f64;
    score -= fill * 12.0;

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: prefer tight fits, discourage spreading.
    if fitting_bins_count > 2 && post_residual > 0 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Mean residual coupling: when open bins are generally empty, be pickier.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Mild stream progression: later in stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * fill;

    // New-bin candidate: default neutral-ish, but only attractive when open
    // bins would leave bad residuals or are scarce.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 {
            1.0
        } else {
            (mean_residual / bin_capacity as f64).max(0.0)
        };
        // New bin is penalized normally; it wins only if all fits are bad.
        score = 45.0 + open_pressure * 10.0 - progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residual gaps that are too small for the smallest plausible future item
    // are "dead space". Penalize them super-linearly.
    let dead_threshold = 20.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // The smaller (and thus less usable) the gap, the harsher the penalty.
        let severity = (dead_threshold - pr) / dead_threshold; // 0..1
        score += severity * severity * 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // --- Open-bins pressure ---
    // When many bins are open, prefer consolidating into existing bins
    // rather than letting residual space sit idle; penalize opening new bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin grows with how many bins are already open.
        score += 25.0 + (open_bins_count as f64).sqrt() * 8.0;
        // But if no open bin fits well (this bin is a last-chance candidate),
        // opening a new bin becomes relatively more attractive.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance to use this bin: reward filling it to avoid waste.
        score -= 15.0;
    }

    // --- Lookahead coupling ---
    // If the next item exactly matches the post-residual, this placement
    // sets up a perfect follow-up fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // --- Mean residual coupling ---
    // Bins far below the mean residual are "loose ends"; filling them is good.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= dev * 0.3;
    }

    // --- Stream progression ---
    // Late in the stream, dead space matters more (less time to recover it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly fills the leftover
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward closeness of match
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit in leftover: penalize dead space
            score += gap * 0.35;
        }
    } else {
        // Last item: just minimize waste
        score += post_residual as f64 * 0.2;
    }

    // Relative-to-mean residual coupling: bins tighter than average are precious
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well,
    // unless the current item is large and would leave awkward residue
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists
        let awkward = (bin_residual - item_size) < next_item_size && next_item_size > 0;
        if open_bins_count > 0 {
            score += 25.0;
            if !awkward {
                score += 15.0;
            }
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (wasting little space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 40 {
        score -= 3.0; // still usable for medium items
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // next item cannot use this bin's remainder: mild penalty for large leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // New-bin candidate handling: discourage opening a new bin when a reasonable fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin.
        score += 20.0;
        // Opening is more attractive early (plenty of stream left to fill it)
        // and when open bins are already quite full on average.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        score += 10.0 * avg_fill;
        // If many bins already fit the item, opening a new one is wasteful.
        score += 8.0 * (fitting_bins_count as f64);
        // Opening a bin when the next item is large can be good (keep big space free).
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 6.0;
        }
    } else {
        // Prefer bins with smaller residual among equally tight fits (best-fit flavor).
        score += (bin_residual as f64) * 0.05;
        // Mild penalty for spreading across too many open bins.
        score += (open_bins_count as f64) * 0.3;
    }

    // Time-horizon coupling: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to stream progress.
    // Early: prefer tight fills (penalize large post_residual super-linearly).
    // Late: residual matters less; weight decays smoothly.
    let decay = (1.0 - progress).powf(1.5);
    let mut score = pr * (0.7 + 0.6 * decay);

    // Quadratic dead-space penalty: small residuals are disproportionately bad,
    // scaled by how much of the stream remains.
    score += 12.0 * decay * norm_pr * norm_pr * cap;

    // Cubic interaction: near-perfect fits late in the stream are gold.
    score -= 8.0 * progress * (norm_item * (1.0 - norm_item)).powf(2.0) * cap;

    // Reward bins whose residual matches the next item's needs (lookahead synergy).
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let match_term = 1.0 - ((norm_pr - nx) / 0.35).powf(2.0);
        score -= 6.0 * match_term.max(-1.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: neutral baseline with slight early-stream openness.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * (1.0 - progress)) + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modular arithmetic on residual space
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: near-perfect fit (post_residual in a small harmonic band)
    if post_residual == 0 {
        score -= 1000.0; // perfect packing
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 25 {
        score -= 80.0;
    }

    // Integer-division thresholds: residual slots of size >= 10 remain usable
    let usable_slots = post_residual / 10;
    score -= usable_slots as f64 * 12.0;

    // Modulo coupling: residuals that align with common item-size residues (multiples of 5/10)
    // are more likely reusable by future items.
    let residue = post_residual % 10;
    score -= (10 - residue) as f64 * 2.0; // reward residuals close to a multiple of 10
    if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 60.0 - next_fit_quality.min(60.0);
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportional to wasted space
        score += (next_item_size as f64 - post) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are fragmented
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 250.0;
        // open a new bin if existing bins are tight / fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < 0.5 * cap {
            score -= 200.0; // existing bins too full, new bin reasonable
        }
        if post_residual as f64 / cap > 0.5 && next_item_size as f64 > post {
            score -= 100.0; // fresh bin keeps large room for big next item
        }
        score -= progress * 30.0;
    }

    // Penalize bins whose residual deviates strongly from mean (fragmentation control)
    score += (post - mean_residual).abs() * 0.3;

    // Slight preference for filling fuller bins when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harder than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness;

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Slight preference for filling bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * tightness;

    // Prefer bins with residuals below mean (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + next_item_size as f64;
        } else {
            // dead space penalty scaled by wasted amount
            let waste = (post_residual as f64) - (next_item_size as f64).min(post_residual as f64);
            score += 0.5 * (post_residual as f64).min(50.0);
            let _ = waste;
        }
        // exact 2-chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 200.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 50.0;
    }

    // Penalize small unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New bin candidate handling: penalize opening a new bin unless residuals are all tight
    if bin_residual == bin_capacity {
        score += 250.0 - 0.3 * mean_residual;
        // open new bin if next item is large and mean residual small
        if next_item_size > 0 && (mean_residual < next_item_size as f64) {
            score -= 60.0;
        }
    }

    // Relative to mean residual: prefer using bins with below-average residual (tighter bins)
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: favor existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Fractional fill achieved by placing the item here
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    if is_new_bin {
        // Opening a new bin is only attractive when the item fills it substantially
        // or when existing bins are nearly full (mean residual is small).
        let tight = mean_residual < item_size as f64 * 1.5;
        score += 60.0
            - 45.0 * fill
            - 20.0 * progress
            - if tight { 15.0 } else { 0.0 };
        if fitting_bins_count == 0 {
            // No open bin can fit: new bin is mandatory-ish
            score -= 80.0;
        }
    } else {
        // Reward near-perfect fits strongly (dead-space penalty)
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 10 {
            score -= 60.0;
        } else if post_residual <= 20 {
            score -= 30.0;
        }

        // Last-chance bonus: this is the only bin that fits, avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 25.0;
        } else if fitting_bins_count > 1 {
            // With many options, prefer tighter fits relative to alternatives
            score += 3.0 * (fitting_bins_count as f64).ln();
        }

        // Lookahead: if the next item would exactly fit the post-residual,
        // strongly prefer this bin (chain packing).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Next item still fits here afterwards: mild bonus proportional to fit quality
            let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * next_fit;
        } else if next_item_size > post_residual {
            // Next item won't fit here: penalize leaving awkward mid-size gaps
            let gap = post_residual as f64;
            if gap >= next_item_size as f64 * 0.5 {
                score += 8.0;
            }
        }

        // Prefer bins whose residual is below the mean (consolidate emptiness)
        score += 0.5 * (bin_residual as f64 - mean_residual);

        // Early in the stream, keep residual flexibility; late, pack greedily
        score += (1.0 - progress) * (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit = fitting_bins_count as f64;
    let open_f = open_bins_count as f64;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * (pr / cap).powi(2));

    // Smooth interaction: post-residual vs stream progress (tighter packing late)
    score += 6.0 * progress * (pr / cap) * (1.0 - progress);

    // Quadratic coupling of item size with post-residual (big items prefer snug fits)
    let isz = item_size as f64;
    score += 0.004 * isz * pr * (1.0 - pr / cap);

    // Last-chance bonus: strongly reward this bin when it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 + 0.1 * residual;
    } else {
        score += 2.0 * (fit - 1.0) / (fit + 1.0) * (pr / cap);
    }

    // Penalize bins far from mean residual (avoid residual fragmentation)
    score += 0.03 * (residual - mean_residual).abs();

    // Lookahead: reward leaving room for the next item
    let n = next_item_size as f64;
    if n > 0.0 {
        if pr >= n {
            score -= 4.0 * (1.0 - ((pr - n) / cap).abs());
        } else {
            score += 5.0 * (n - pr) / cap;
        }
    }

    // Mild new-bin penalty scaling with open bins (encourage reuse)
    score += 0.5 * open_f.ln().max(0.0) * (pr / cap);

    // New-bin candidate: penalize opening a new bin unless post-residual would be large
    if bin_residual as u32 == bin_capacity {
        score += 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic classes on post_residual via integer division thresholds.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure is excellent
    } else if pr <= 10 {
        score -= 25.0; // dead space in the smallest class is nearly closed
    } else if pr <= 25 {
        score -= 8.0;
    } else if pr <= 50 {
        score += 6.0; // half-empty bin: moderate waste
    } else {
        score += 14.0; // large dead space class
    }

    // Modulo arithmetic on post_residual: residuals divisible into coarse capacity
    // fractions (multiples of 25) pair well with typical item sizes.
    if pr % 25 == 0 && pr > 0 {
        score -= 5.0;
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: does next_item_size fit into post_residual? Reward compatible bins.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how well the next item divides the residual
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 12.0;
            } else {
                score -= (10.0 - (slack as f64 / 10.0).min(10.0)).max(0.0);
            }
        } else {
            score += 8.0; // next item won't fit here; bin becomes dead
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if post_residual <= 20 {
            score -= 10.0;
        }
    }

    // New-bin candidate (empty bin): only attractive when residuals across open
    // bins are large (open bins are badly fragmented) or few bins exist.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 + fragmentation * 40.0 - (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits anywhere; must open
        }
        // late in the stream, avoid spawning bins unnecessarily
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild pressure to consolidate: prefer bins with below-average residual
    // (fill the emptier-relative bins first keeps many near-closed bins).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Small penalty for very loose fits relative to item size.
    let ratio = item_size as f64 / bin_residual.max(1) as f64;
    if ratio < 0.5 {
        score += 6.0 * (0.5 - ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual < 10 {
        score += 18.0; // tiny gap, almost certainly dead space
    } else if post_residual < 20 {
        score += 7.0; // risky small gap
    } else if post_residual < 30 {
        score += 2.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open-bins pressure: favor consolidating into existing bins when many are open.
    score -= 0.4 * open_bins_count as f64;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is the only option.
            score -= 25.0;
        } else if post_residual as f64 > mean_residual {
            // Existing bins offer better residual profiles than a fresh bin.
            score += 15.0;
        } else {
            score += 4.0;
        }
    }

    // Lookahead: if the next item can fit into the resulting gap, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // Gap is both small and useless for the known next item.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this bin the new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // 2-step lookahead: reward when post_residual matches next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            // perfect chaining: next item exactly fills this bin
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let gap = pr - nx;
            // closer gap to next item => better (small leftover after two placements)
            score -= (20.0 * nx / (nx + gap)) - gap * 0.15;
        } else {
            // next item won't fit here; penalize proportionally to how badly
            score += (nx - pr) * 0.25;
        }
    } else {
        // last item: prefer tightest fit (smallest post_residual)
        score += 10.0;
    }

    // Reward tight fills relative to mean residual across open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual) * 0.20;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing (10..80 range) can use well
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny leftover is fine (near-perfect fill)
    } else if post_residual >= 10 && post_residual < 40 {
        score += 5.0; // moderate dead space is mildly bad
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base penalty so open bins win when they fit decently
        let mut new_bin_score = 120.0;
        // lookahead: an empty bin guarantees the next item fits too
        if next_item_size > 0 {
            new_bin_score -= 30.0;
        }
        // later in the stream, avoid spawning bins for small leftovers
        new_bin_score += progress * 20.0;
        // if many bins are open already, opening more is costlier
        new_bin_score += open_bins_count as f64 * 1.5;
        score = score.max(new_bin_score) * 0.0 + new_bin_score + score * 0.0 + new_bin_score;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (dead space elimination).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this bin
    // remains useful -> reward; if the next item would be blocked by a tiny
    // leftover, penalize creating unusable slivers.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size <= post_residual {
            score -= 80.0 + 0.5 * next;
        } else if post_residual > 0 && post < 10.0 {
            // tiny leftover that likely wastes space
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Contextual preference: prefer fuller bins relative to global state.
    let fill_ratio = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 60.0 * fill_ratio;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 40.0 * progress * fill_ratio;

    // Penalize bins whose residual deviates badly from the mean residual:
    // a bin much emptier than average should be filled preferentially.
    if post_residual as f64 > mean_residual + 30.0 {
        score += 15.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // It should only win when no open bin offers a decent fit; give it a
    // moderate handicap that shrinks as the stream progresses (consolidation
    // pressure grows over time).
    if bin_residual == bin_capacity {
        score += 90.0 - 50.0 * progress;
        // Opening new bins is more acceptable when many bins are already open
        // and mean residual is high (fragmented state).
        if mean_residual > 40.0 && open_bins_count > 3 {
            score -= 40.0;
        }
    }

    // Mild penalty for very large open_bins_count to discourage sprawl.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Smooth polynomial decay of residual value over stream progress
    let decay = 1.0 - 0.5 * progress * progress;
    score *= decay;

    // Non-linear coupling: penalize large post_residual quadratically, modulated by mean residual
    let mr = mean_residual.max(0.0);
    let excess = pr - mr;
    score += 0.02 * excess * excess * (0.5 + progress);

    // Reward tight fits with smooth sigmoid-like term
    let fit_frac = (item_size as f64) / cap;
    score -= 8.0 * fit_frac * fit_frac * (1.0 - fit_frac);

    // Last-chance bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (pr - ns).max(0.0);
        score += 0.05 * waste * (1.0 + progress);
        if pr >= ns {
            score -= 5.0;
        }
    }

    // Mild pressure against accumulating many open bins late in stream
    score += 0.01 * (open_bins_count as f64) * progress;

    // New-bin candidate: neutral-ish baseline with smooth progress scaling
    if bin_residual == bin_capacity {
        score = 60.0 + 30.0 * progress - 0.3 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets
    let class = post_residual / 10; // 0..=10 classes
    // Dead-space penalty grows superlinearly for small but unusable leftovers
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        // smallest "typical" item is small; penalize residuals below ~10 harshly
        if post_residual < 10 {
            score += 25.0 * (10 - post_residual) as f64;
        } else {
            score += 8.0 * frac * frac;
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Modulo-harmonic reward: residuals that are multiples of 5 or 10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // excellent: chain placement possible
            score -= 10.0 + 0.05 * next_item_size as f64;
            // harmonic bonus if next item exactly divides remaining space
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by overshoot
            let over = next_item_size - post_residual;
            score += 0.1 * over as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_ratio = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate handling: only attractive if no good fit exists
    if bin_residual == bin_capacity {
        // neutral base; make new bin slightly worse than a decent existing fit
        score += 15.0;
        // but if existing bins are fragmented and item is large, opening is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Progress term: as stream advances, tighten packing (favor tight fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fill_ratio;

    // Tie-break toward bins closest to mean residual (balance exploitation)
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone = 20.0; // residuals below ~20 are hard to fill for items >= 10
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Pressure against opening new bins when open bins exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 60.0 + 15.0 * open_bins_count as f64 + mean_residual.max(0.0) * 0.8;
        // Allow new bin only if no existing bin is a decent fit (post_residual large waste).
        if post_residual as f64 > bin_capacity as f64 - item_size as f64 {
            // this is the empty bin itself; keep penalty but soften if many bins open
            score -= 20.0 * (open_bins_count as f64).min(5.0);
        }
    } else {
        // Reward using existing bins, stronger when few bins fit the item (last chance).
        if fitting_bins_count <= 1 {
            score -= 50.0;
        } else {
            score -= 10.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward keeping this gap usable.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 25.0;
    } else if next_item_size > 0 {
        // gap likely dead for the next item too; penalize
        score += 10.0;
    }

    // Mild stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer bins with small post_residual (tight fit), but avoid
    // creating unusable dead space. Dead space = post_residual too small to
    // hold any plausible future item (min item size 1, but typical items larger).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: perfect match with next item is highly desirable ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == next {
            // Exact fit for the next item: strong reward.
            score -= 60.0;
        } else if pr > next {
            // Next item fits afterwards; reward proportionally to closeness.
            let slack = pr - next;
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item does NOT fit in the leftover: penalize dead space,
            // especially when the leftover is small (unusable).
            let dead = next - pr;
            score += 0.6 * dead.min(40.0);
        }
        // Coupling: if the next item also fits post placement AND current
        // placement, this bin is doubly valuable.
        if next <= post_residual && next <= bin_residual {
            score -= 8.0;
        }
    }

    // --- Mean residual coupling: prefer bins whose residual is far above mean
    // (large residual bins are flexible; consume them when fit is tight) ---
    let pr = post_residual as f64;
    let mean_gap = pr - mean_residual;
    score += 0.25 * mean_gap;

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a
        // decent fit (post_residual would be large/wasteful elsewhere) or
        // when the item nearly fills a fresh bin.
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin normally; reward if item is big.
        score += 20.0 - 30.0 * tightness;
        // If existing bins would leave huge waste, new bin becomes attractive.
        if fitting_bins_count > 0 {
            let best_possible_waste = pr; // post_residual of new bin = C - item
            if mean_residual > 0.0 && (best_possible_waste as f64) < mean_residual * 0.5 {
                score -= 15.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        score += 15.0 * progress;
    }

    // --- Small general bonus for very tight fits (post_residual tiny) ---
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Slight preference to keep number of open bins bounded.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 0.06 * (next_item_size - post_residual.min(next_item_size)) as f64;
        }
    }

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count > 0 && fit_ratio > 0.55 {
            score += 20.0; // existing bins give decent fit, avoid new bin
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits, must open new bin
        }
    }

    // Time horizon: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Global state coupling: many open bins -> prefer filling existing ones
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    score -= 0.02 * (mean_residual - post_residual as f64).abs();

    // Slight preference for bins with residuals close to item (perfect partitioning)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.03 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 - progress);
    let mut score = pr + 30.0 * poly;
    // Reward tight fits (low post residual) more strongly later in the stream
    score -= 20.0 * (1.0 - norm_pr) * progress * (1.0 - norm_pr);
    // Penalize creating dead space smaller than the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 15.0 + 10.0 * (1.0 - progress);
    }
    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + progress);
    }
    // Mild preference for bins deviating from mean residual (balance-aware)
    score += 0.05 * (pr - mean_residual).abs();
    // New-bin candidate: keep it neutral-to-slightly-high unless residual is large
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward residuals that are "friendly" sizes for future items.
    // Items are integers 1..100; small residuals (< 10) are near-dead space.
    if post_residual == 0 {
        score -= 30.0; // perfect fit: best outcome
    } else if post_residual < 10 {
        score += 40.0; // dead space penalty
    } else {
        // Reward residuals in harmonic classes divisible by common item sizes
        let pr = post_residual;
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 4.0; }
        // Integer-division threshold classes
        match pr / 15 {
            0 => score += 8.0,
            1 => score -= 3.0,
            2 => score -= 5.0,
            3 => score -= 2.0,
            _ => {}
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nr = post_residual - next_item_size;
            if nr < 10 { score += 10.0; } else { score -= (nr as f64).min(15.0) * 0.3; }
        } else {
            // next item won't fit here; mildly penalize wasting large residual
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin fits badly.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in stream, allow new bins more freely
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Many open bins: encourage consolidation.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: avoid creating residuals far from the mean.
    score += ((post_residual as f64) - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
