    // Prefer bins below mean residual (tighter bins) mildly.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 + 30.0 * fragmentation - 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // big next item: fresh bin is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // If the next item also fits after this placement, reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual as f64 - next_item_size as f64) * 0.1;
    }

    // Penalize leaving dead space that can't fit the next item (waste beyond next item).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless current bins are crowded / poor fits.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            mean_residual / bin_capacity as f64
        } else {
            1.0
        };
        // Open a new bin only when mean residual is low (bins are full).
        score += 150.0 - crowding * 300.0;
    } else {
        // Prefer bins tighter than the mean (best-fit style).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Slight preference for placing large items early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += item_size as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that few future items can use (post_residual < 10 is perfect).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 8.0 * (20.0 / (dead + 5.0)).min(2.0) * (1.0 - fill_ratio);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: penalize wasted space more.
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, opening a new bin is costly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when fits are poor or bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Prefer new bin when mean residual is high (existing bins too full) or item is huge.
        let big_item = (item_size as f64) / (bin_capacity as f64);
        score = 60.0
            + 40.0 * fragmentation
            - 50.0 * big_item
            - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin mandatory
        }
    } else {
        // Prefer fuller bins among open bins: penalize bins with large residual waste.
        let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score += 15.0 * waste;
        // Slight preference for bins below mean residual (keeps big bins for big items).
        if (bin_residual as f64) > mean_residual {
            score += 4.0;
        }
        // Early stream: keep flexibility by spreading; late stream: pack tight.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening.
    let mut score = pr;
    score += 60.0 * norm_pr * norm_pr;

    // Dead-space penalty: residuals too small for typical items are worthless.
    let dead = (norm_pr * (1.0 - norm_pr)).sqrt(); // peaks at mid residuals
    score -= 25.0 * dead;

    // Smooth stream-progress coupling: tighten tolerance as stream advances.
    score *= 1.0 + 0.5 * progress * (1.0 - norm_pr);

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0)).max(0.0);
    }

    // Last-chance bonus: using the only fitting bin avoids opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when alternatives exist,
    // unless the item fits poorly everywhere (high post residual elsewhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 45.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to drain crowded state: favor bins below mean residual.
    score += 3.0 * ((bin_residual as f64) - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class
    match class {
        0 => { score -= 6.0; }          // near-perfect fit
        1 => { score += 2.0; }          // small-but-usable dead space
        2 => { score += 1.0; }          // half-ish residual, still useful
        3 => { score += 3.0; }          // large residual, weak commitment
        _ => { score += 8.0; }          // essentially untouched bin
    }

    // Lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 4.0 * fit_quality;
    }
    // Penalize leaving residual that next item cannot use at all.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny dead space unusable by most items
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // New-bin candidate handling: only attractive when current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) > mean_residual as u32;
        if tight_fit_exists && post_residual > quarter {
            score += 12.0; // keep existing bins, avoid bin proliferation
        } else {
            score -= 3.0 + 2.0 * progress; // late stream: fresh bin is fine
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5;
    }

    // Integer-division threshold: split residual into usable chunks of >=10.
    let usable_chunks = post_residual / 10;
    score -= usable_chunks as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    if is_new_bin {
        // Pressure against opening new bins: grows with open-bin count and stream progression.
        score += open_bins_count as f64 * 1.5 + progress * 8.0;
        // If existing bins are nearly full on average (small mean residual),
        // opening a fresh bin is natural and cheap.
        score -= (35.0 - mean_residual).max(0.0) * 0.9;
        // Lookahead: reward a fresh bin whose leftover can host the next item (pairing).
        if next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 4.0;
        }
    } else {
        if pr == 0.0 {
            // Perfect fit: zero dead space, strong reward.
            score -= 6.0;
        } else if pr <= 12.0 {
            // Unusable sliver: tiny leftover gaps are almost never reusable.
            score += 6.0 + (12.0 - pr) * 0.6;
        } else if pr > cap * 0.55 {
            // Poor fit: leaves a large leftover, mild extra penalty.
            score += 2.5;
        }

        // Last-chance bonus: this is the only open bin that fits, so avoid
        // opening a new bin unless the fit is disastrous.
        if fitting_bins_count == 1 {
            score -= 14.0;
        }

        // Lookahead: next item nests exactly or near-exactly into the leftover.
        if next_item_size > 0 {
            let n = next_item_size as f64;
            if pr == n {
                score -= 9.0;
            } else if pr > n && pr - n <= 6.0 {
                score -= 4.0;
            }
        }

        // Mild consolidation pressure: prefer bins that are fuller than average.
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward bins that become nearly empty after placement.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: strongly reward when next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // Next item fits too: reward tighter chains, penalize large leftover slack.
            let chain_waste = post_residual - next_item_size;
            score -= 100.0 - (chain_waste as f64) * 2.0;
        } else {
            // Next item cannot fit: penalize proportional to overshoot.
            score += ((next_item_size - post_residual) as f64) * 1.5;
        }
    }

    // Dead space penalty: large post_residual that is unlikely usable.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0; // small residual is fine (near-perfect fit)
    } else if post_residual >= 10 {
        // penalize slack relative to mean residual of open bins
        score += ((post_residual as f64) - mean_residual).max(0.0) * 0.8;
    }

    // Last chance bin: if this is the only bin that fits, prefer using it over opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if lookahead says next item is large, new bin may be attractive later; small discount.
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly more willing to open bins to build diversity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.2 {
        score -= 10.0;
    }

    // Prefer tighter existing bins (smaller residual before placement) mildly.
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but nonzero (dead space).
    if post_residual > 0 {
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score += (1.0 - tight) * 8.0;
    } else {
        // Perfect fill is highly desirable.
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // Next item cannot fit here; leftover space likely becomes waste.
            score += post_residual as f64 * 0.25;
        }
    } else {
        // Last item: prioritize closing bins completely.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Discourage fragmenting bins whose residual is already small relative to the mean.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score += (mean_residual - residual_f) * 0.2;
    } else {
        score -= (residual_f - mean_residual).min(50.0) * 0.1;
    }

    // Time horizon: early in the stream, be more willing to open/spread bins;
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // When many bins are open, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.4;

    // Mild penalty proportional to item size for large items in nearly-full bins
    // (avoid wasting a big item's placement flexibility).
    if item_size as f64 > residual_f * 0.9 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 20.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small to be useful later
    let min_useful = 10.0;
    if pr < min_useful && pr > 0.0 {
        score += 8.0 * (min_useful - pr) / min_useful;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (pr - nxt) / bin_capacity as f64;
        } else {
            score += 5.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Mild preference for consolidating into fewer bins
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    // Smooth interaction with mean residual: prefer bins near the mean
    let dev = (pr - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: integer-division thresholds on capacity fractions.
    let item_class = item_size / (bin_capacity / 4).max(1); // 0..=4 classes
    let post_class = post_residual / (bin_capacity / 4).max(1);

    // Reward tight fits: waste below a quarter-capacity is cheap dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_class == 0 {
        score -= 25.0; // very tight fit, tiny unusable residue
    } else if post_class == 1 {
        score -= 8.0;
    } else if post_class == 3 {
        score += 6.0; // large leftover is fine (still usable)
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // harmonic coupling: reward decays with leftover slack class
            let slack_class = (next_item_size / (bin_capacity / 4).max(1)) as f64;
            score -= 20.0 - 3.0 * slack_class - 0.15 * slack;
        } else {
            // next item won't fit here; penalize leaving a residue that is
            // just barely below next_item_size (worst dead space)
            let gap = (next_item_size - post_residual) as f64;
            if gap < cap * 0.2 {
                score += 10.0 + 0.3 * gap;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // would create bad dead space. Give it a mild penalty by default.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
        // but if item is large (class >= 2), a fresh bin is attractive
        if item_class >= 2 {
            score -= 18.0;
        }
    }

    // Modulo arithmetic on post_residual: residues near capacity/2 are
    // awkward (few item sizes pair well with them).
    let half = bin_capacity / 2;
    let mod_half = post_residual % half.max(1);
    if mod_half > 0 && mod_half < 10 {
        score += 5.0; // sliver residue
    }

    // Progress-based drift: early in stream, prefer consolidating (favor
    // existing bins); late in stream, tightness matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / cap);
    score += progress * (post_residual as f64 / cap) * 5.0;

    // Slight preference for bins below mean residual (keeps spread balanced).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, minimum item size)
    // are pure waste; penalize them heavily, but a perfect fit (0) is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score += 40.0; // dead space penalty
    } else {
        // Reward snug fits: smaller post_residual relative to capacity is better
        score -= 30.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // If the next item fits exactly in the post_residual, this is a great chain — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Exact chain fit is even better
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // Next item would have fit before this placement but not after — mild penalty
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    // New-bin candidate (bin_residual == bin_capacity) gets penalized when open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual would be tiny elsewhere),
        // the base score already reflects that; slight extra pressure early.
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (consolidate space into emptier bins is bad; fill fuller bins first).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Progress-based tightening: as the stream advances, be more conservative
    // about waste since long streams amplify per-item dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0);
    }

    // Penalize small dead space that nothing can use (items >= 1, but small residuals waste)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer bins tighter than mean residual (good fills)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35 && fitting_bins_count > 0;
        score += if poor_fit { 5.0 } else { 40.0 };
        // Opening new bin is fine if lookahead would perfectly fill it
        if next_item_size > 0 && (bin_capacity - item_size - next_item_size.min(bin_capacity)) == 0 {
            score -= 35.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can't hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual - next_item_size).min(20) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: prefer opening a new bin only when current bin
    // fits are poor and mean residual is fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 18.0 + 10.0 * progress - 0.4 * open_bins_count as f64 - fragmentation * 0.2;
    }

    // Discourage leaving residuals in awkward zones (e.g. 1..10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference for filling bins with larger residual when many bins open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Time-horizon coupling: early in stream, be more exploratory (favor new bins less);
    // late in stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if !is_new_bin {
        score -= 6.0 * progress * fit_ratio;
    }

    // Global state: penalize choosing a bin whose residual deviates strongly from mean
    // when it creates imbalance, unless the fit is very tight.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling: penalize small post-residuals quadratically
    let tight = (1.0 - norm_pr).powi(3);
    score += 8.0 * tight * (0.5 + progress);

    // Reward filling bins tightly as stream progresses
    score -= 6.0 * (norm_pr * norm_pr) * (1.0 - progress);

    // Interaction: post_residual vs mean residual deviation
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (cap * 0.01 + 1.0);

    // Lookahead coupling: penalize if next item cannot use post residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni > pr as f64 {
            score += 4.0 * (ni - pr) / cap * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - ni / cap) * norm_pr;
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for many open bins (discourage fragmentation)
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Smooth residual-squared penalty scaled by progress
    score += (norm_pr * norm_pr * norm_pr) * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (harmonic class: post_residual small).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit is always best
    } else {
        // Harmonic penalty: dead space graded by divisibility class.
        let pr = post_residual;
        // Residuals that can still hold small items (>=1) are less dead.
        // Penalize residuals in "awkward" classes (e.g. 1..10 hard to fill).
        if pr < 10 {
            score += 40.0; // nearly unusable sliver
        } else if pr % 10 == 0 {
            score -= 15.0; // round-class residual, easily reusable
        } else if pr % 5 == 0 {
            score -= 8.0;
        }

        // Lookahead: does the next item fit exactly into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 200.0; // chain a perfect fit next
            } else if next_item_size <= pr {
                score -= 30.0 - (pr - next_item_size) as f64 * 0.5;
            } else {
                // next item won't fit here; slight penalty grows with gap
                score += (next_item_size - pr) as f64 * 0.3;
            }
        } else {
            // Last item: only waste matters
            score += pr as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper late in the stream
        // and when many bins are already open (amortization).
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score = bin_capacity as f64 - 20.0 * progress - 0.5 * open_bins_count as f64;
        // If the item fits the empty bin exactly or leaves a round residual,
        // opening fresh is more attractive.
        if item_size % 10 == 0 {
            score -= 10.0;
        }
        // Lookahead synergy: next item pairs well with a fresh bin.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Mild preference for filling fuller bins (relative fill fraction).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Coupling with mean residual: placing into a bin far below the mean
    // residual helps balance and reuse.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.2 * dev;
    } else {
        score += 0.1 * (-dev);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item are pure waste; penalize them extra hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 30.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up; reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, tolerate opening new ones less.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * bin_pressure;

    // New-bin candidate: make the empty bin attractive only when the
    // item would leave a large, flexible residual relative to current
    // mean residual, or when no good fit exists.
    if bin_residual == bin_capacity {
        let flexible = post_residual as f64 >= mean_residual;
        let poor_fit = fitting_bins_count == 0;
        if flexible || poor_fit {
            score -= 35.0;
        } else {
            score += 25.0;
        }
    }

    // Slight preference for tighter fits overall (normalized).
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post_residual is good, but only if it's not
    // an unusably tiny sliver relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty: sliver unusable for items >=10
    }

    // 2-step lookahead: if next item fits perfectly into post_residual,
    // strongly reward this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are more precious;
    // placing into them is good only if fit is tight, otherwise prefer loose bins.
    let tightness = mean_residual - bin_residual as f64;
    if tightness > 0.0 {
        score -= 0.3 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);
    } else {
        score += 0.15 * (-tightness);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (item_size as f64 / bin_residual as f64);
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // unless current bins are nearly all full (high mean fill).
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        score += 30.0 + 20.0 * mean_fill - 10.0 * pressure.min(1.0);
        // If lookahead item is large and no bin chains, new bin is more attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        }
    }

    // Mild progression term: late in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional waste more strongly for small residuals.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that nothing in the plausible size range can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual <= 100 {
        // Usable residual is fine; slight reward scaled by openness.
        score -= 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only good when the current
    // fit is poor and future items may need the space.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = fit_ratio < 0.6;
        if poor_fit && open_bins_count > 0 {
            score -= 10.0 + 20.0 * (1.0 - progress);
        } else {
            score += 30.0; // don't open new bins when a decent fit exists
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward leaving that space.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 1.0 {
            score -= 20.0;
        } else if post_residual as f64 >= nr {
            score -= 4.0 * (1.0 - (post_residual as f64 - nr) / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting the space.
            score += 3.0 * (nr / bin_capacity as f64);
        }
    }

    // Global state: when mean residual is high, prefer spreading load (favor bins
    // with residual above mean); when low, prefer consolidating into tight bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Late in the stream, avoid opening new bins: favor existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Mild penalty on accumulating too many open bins with poor fits.
    if open_bins_count > 8 && post_residual as f64 > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Reward tight fits: penalize quadratically as post_residual grows.
    score += 2.5 * pr_norm * pr_norm * cap;

    // Reward filling a bin nearly completely (small post_residual) more strongly.
    score -= (1.0 - pr_norm).powi(3) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 15.0 * (1.0 - pr_norm);
    }

    // Lookahead coupling: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap);
            score -= 8.0 * snug * (0.5 + 0.5 * progress);
        } else {
            // Next item cannot follow here: mild penalty scaled by wasted space.
            score += 3.0 * pr_norm * (1.0 - progress);
        }
    }

    // Progress-coupled consolidation: later in the stream, favor existing bins over new ones.
    score += 12.0 * progress * (pr_norm - 0.5).abs();

    // New-bin candidate handling: empty bin has residual == capacity.
    if (bin_residual as f64 - cap).abs() < 1e-6 {
        // Prefer new bin only if no open bin offers a decent fit.
        score += 18.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual below mean (concentrate waste).
    score += 0.5 * (pr - mean_residual) * 0.1;

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors
    // captures "how reusable" the leftover space is for typical item sizes.
    let post = post_residual;
    let mod4 = (post % 4) as f64;
    let mod10 = (post % 10) as f64;
    let mod25 = (post % 25) as f64;

    // Penalize residuals that are awkward (small, non-divisible leftovers).
    if post > 0 {
        if post < 10 {
            // Dead space: nothing can ever fit.
            score += 30.0;
        } else if post < 20 {
            score += 8.0 - mod4 * 1.5;
        } else {
            // Prefer residuals that are multiples of 10/25 (highly reusable).
            score -= (25.0 - mod25) * 0.15 + (10.0 - mod10) * 0.10;
        }
    }

    // Lookahead coupling: reward leaving exactly enough room for the next item.
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 25.0; // perfect chained fit
        } else if post >= next_item_size && post - next_item_size < 10 {
            score -= 12.0; // near-perfect chain, minimal new dead space
        } else if post < next_item_size && post >= 10 {
            score += 3.0; // next item can't follow here
        }
        // Harmonic class match: post_residual in same mod-10 class as next item
        if post >= next_item_size && (post % 10) == (next_item_size % 10) {
            score -= 4.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin when a fit exists).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so we
    // prefer existing bins unless they fit poorly; but if all open bins have
    // tiny residuals relative to the item, opening fresh is attractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        score = cap_f * 0.55 + progress * 5.0
            - if next_item_size > 0 && (bin_capacity as u32 % 10) >= next_item_size % 10 { 3.0 } else { 0.0 };
        // If many bins but none fit well, encourage new bin.
        if open_bins_count > 0 && (item_size as f64) > mean_residual * 0.9 {
            score -= 20.0;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / cap_f;
    score -= fill * 10.0;

    // Slight pressure against bin sprawl late in the stream.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (<=10)
    // or too small to fit the known next item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // completely wasted space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap cannot host the lookahead item
        } else {
            // Smooth penalty on small-but-usable gaps (tight fit is good).
            let tightness = post_residual as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - tightness);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // Exact-fit reward when the next item also fits the resulting gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let combined = item_size + next_item_size;
        if combined == bin_residual {
            score -= 30.0; // two-item exact fill
        } else if combined as f64 >= 0.9 * bin_residual as f64 {
            score -= 12.0; // near-exact two-item fill
        }
    }

    // Open-bin pressure: discourage spreading across many bins when residuals
    // are already large; encourage using existing bins as open_bins_count grows.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (smaller residual than average = tighter bin).
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize new bins mildly, scaled by how many bins already fit the item.
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += fit_pressure + 5.0 * open_bins_count as f64;
        // Late in the stream, new bins are even less desirable.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match with the lookahead item: strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the next item: penalize unusable sliver.
            let dead = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 25.0 + dead;
            } else {
                score += 0.3 * dead;
            }
        }
    }

    // Last chance: only bin that fits this item -> strong bonus to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when current item is large or no good fit exists;
    // otherwise keep open bins consolidated.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_fit = next_item_size > 0 && post_residual < 10;
        if item_size >= 60 || tight_fit || open_bins_count == 0 {
            score -= 10.0 + 20.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Slight preference for leaving round-ish residuals divisible by common sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 12.0;

    // Penalize dead space: residual too small for any plausible item (min size 1 assumed, use 10 as practical floor).
    if post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer the bin that leaves the least usable remainder.
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: empty bin gets a base penalty so we only open
    // a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Escalate penalty over time slightly; opening new bins early is fine,
        // later we prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + progress * 10.0;
        // But if mean residual across open bins is very low (all bins nearly full),
        // opening a new bin is justified.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    }

    // Prefer filling bins with low residual relative to mean (balance consolidation).
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.05;

    // Slight preference to use bins with fewer alternatives when many bins open.
    if open_bins_count > 8 {
        score += post_residual as f64 * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // later, punish residual space more strongly (squared growth).
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Perfect-fit reward: smooth trough near zero residual.
    if pr == 0 {
        score -= 25.0;
    }

    // Penalize leaving a residual that no typical next item could use well
    // (dead space): small nonzero residuals are risky.
    if pr > 0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Lookahead: reward if next item fits the post residual (smooth bonus).
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let partial = 1.0 - ((next_item_size as f64 - pr).abs() / cap).min(1.0);
        score -= 8.0 * fits * partial;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure against proliferating open bins relative to mean residual.
    let openness = open_bins_count as f64 / (mean_residual + 1.0);
    score += 0.05 * openness * (1.0 + progress);

    // Slight bias toward filling existing bins vs opening new ones
    // (new-bin candidate has norm_pr == 1, so it gets the full base penalty).
    score += 3.0 * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" small classes (fit next typical item) are rewarded.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Reward near-perfect fits strongly (nonlinear).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Modulo-10 harmonic class: dead space that is a multiple of 10 is
    // more likely reusable by future items (sizes 1..100, often tens).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Penalize awkward leftovers: > 50 waste but < next_item_size usability.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to lookahead item
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 90.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last-chance bonus: only one bin fits -> prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but more attractive late in stream when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Fraction-of-capacity harmonic penalty: leftover in (0.3C, 0.5C) band
    // is the classic wasteful zone.
    let frac = post_f / cap_f;
    if frac > 0.3 && frac < 0.5 {
        score += 12.0;
    }

    // Prefer filling bins that are already below mean residual (balance).
    score += 0.15 * (mean_residual - post_f);

    // Integer division threshold: post_residual / item_size class
    let div_class = post_residual / item_size.max(1);
    if div_class == 0 {
        score -= 5.0; // item fills more than half of remaining space: good compaction
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    }

    // Tight fit reward relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.4 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Lookahead: if next item fits exactly in the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 8.0; // post residual likely wasted
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_open = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score = bin_capacity as f64 - 12.0 * bad_open
            + 3.0 * (post_residual as f64)
            + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // pairing potential with next item
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the lone fitting bin
        }
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the next item fits exactly into post_residual
    if next_item_size > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            let match_quality = 1.0 - ((post_residual as f64) - (next_item_size as f64)) / (bin_capacity as f64);
            score -= 30.0 * match_quality * match_quality;
        } else {
            // Penalize leaving a gap the next item cannot use
            score += 8.0 * ((post_residual as f64) - (next_item_size as f64)) / (bin_capacity as f64);
        }
    }

    // Prefer tight fits relative to mean residual
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 5.0 * (mean_residual - post_residual as f64) / (bin_capacity as f64);

    // Last-chance bonus: avoid wasting this bin's remaining space
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (item_size as f64) / (bin_residual as f64);
    }

    // Penalize tiny dead space that nothing (min size 1..100) may ever use
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild preference for keeping bin count low early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (open_bins_count as f64) / 50.0;

    // Brand-new bin candidate: only attractive when open bins would leave bad fits
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
        if next_item_size > 0 && (bin_capacity as u32) - item_size >= next_item_size {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight super-linear penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 20.0;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0; // dead space unless next item is tiny
            if post_residual < 10 {
                score -= 2.0; // tiny dead space is acceptable
            }
        }
        // Perfect chain: post_residual exactly equals next item
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mild preference for fuller bins (smaller residual).
        score -= (bin_residual as f64 - post_residual as f64) * 0.3;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is more acceptable early; late stream, prefer consolidation.
        let new_bin_penalty = 18.0 + 30.0 * progress;
        score += new_bin_penalty;
        // But if item is large and mean residual is low, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 22.0;
        }
        // If no open bin fits (signaled via fitting_bins_count == 0 context), new bin is required.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    let open_f = open_bins_count as f64;
    score += 0.15 * open_f * (mean_residual / bin_capacity as f64);

    // Prefer bins below mean residual (filling the emptier ones less) —
    // actually favor bins tighter than average to reduce fragmentation.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Time horizon: as stream nears end, penalize leaving moderate dead space more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual > 0 && post_residual < 10 {
        score += 4.0 * progress; // tiny dead space late is wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space, with a smooth non-linear (quadratic) coupling
    // that intensifies as the stream progresses (dead space matters more later).
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Smooth polynomial coupling of post_residual with progress:
    // cubic interaction term amplifying large residuals late in the stream.
    score += 0.5 * norm_pr * norm_pr * norm_pr * progress;

    // Reward tight fits: small post_residual relative to capacity.
    score -= 0.4 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin (avoid opening bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 * (1.0 + progress);
    }

    // Penalize opening new bins when plenty of open bins exist and mean residual is high.
    if bin_residual == bin_capacity {
        score += 0.8 + 0.3 * open_bins_count as f64 + 0.002 * mean_residual * open_bins_count as f64;
        // Slightly favor new bins early when mean residual is low.
        score -= 0.001 * mean_residual;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 0.3 * (pr - nxt) / cap;
        } else {
            score += 0.3 * (nxt - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "reusable" the leftover space is.
    // Residuals that are multiples of common size classes (10, 20, 25, 50) are valuable.
    let harmonic_bonus: f64 = if post_residual == 0 {
        -60.0 // perfect fit, strongly favored
    } else if post_residual % 50 == 0 {
        -30.0
    } else if post_residual % 25 == 0 {
        -22.0
    } else if post_residual % 20 == 0 {
        -18.0
    } else if post_residual % 10 == 0 {
        -12.0
    } else if post_residual % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward dead space
    };
    score += harmonic_bonus;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 5)
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // partial reward scaled by how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here; slight penalty if this bin becomes nearly full anyway
            if post_residual <= 10 {
                score += 5.0;
            }
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 45.0;
        // cheaper to open new bins early in the stream or when few bins are open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        score -= 2.0 * open_bins_count as f64;
        // if mean residual across open bins is large, opening new bin is wasteful
        score += 0.3 * mean_residual;
        // if next item is large and this item is small, new bin may serve both better
        if next_item_size >= 60 && item_size <= 30 {
            score -= 10.0;
        }
    } else {
        // mild reward for using already-open bins with large residual (avoid fragmentation)
        score -= 0.05 * bin_residual as f64;
    }

    // Mean-residual coupling: penalize placing into bins far from the mean (keeps balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Integer-division threshold on post_residual: discourage leaving 11..19 slivers
    if post_residual >= 11 && post_residual <= 19 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (post_residual too small to be useful later)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits strongly
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space penalty scaled by how unusable the gap is relative to typical item sizes
    if post_residual > 0 && post_residual < 50 {
        score += (50.0 - post_residual as f64) * 0.6;
    }

    // Pressure from many open bins: prefer filling existing bins rather than spreading
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item would NOT fit in post residual but would fit a fresh bin, penalize slightly
    if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 6.0;
    }

    // Slight preference for keeping mean residual balanced
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: only attractive when all open bins leave terrible fits
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 20.0 + (open_bins_count as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 100.0 + (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * (post_residual - next_item_size) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score += 50.0;
    }

    // Relative to mean residual: prefer bins already below-average residual
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bin when open bins could fit reasonably
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * (open_bins_count as f64);
        // allow new bin if item is large and would leave big hole in existing bins
        if item_size > bin_capacity / 2 && fitting_bins_count > 0 {
            score -= 100.0;
        }
    }

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (good fits).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize dead space that can never fit typical items (post_residual too small).
    if post_residual > 0 && post_residual < 10 {
