    // Global pressure: when many bins are open with high mean residual,
    // prefer consolidating into existing space rather than spreading.
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual;
        score += 0.5 * open_bins_count as f64;
        // Prefer bins below mean residual (tighter bins get used first).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (good fit), with smooth non-linear shaping
    let mut score = 12.0 * pr;

    // Non-linear polynomial coupling with stream progress:
    // early on, moderate residuals are acceptable; late, tighten fit preference
    let progress_coupling = (x - 0.5).powi(2) * (1.0 + 20.0 * progress) * cap;
    score += progress_coupling;

    // Cubic penalty on very small residuals (dead space) growing with progress
    score += (1.0 - x).powi(3) * 40.0 * (0.5 + progress);

    // Reward near-perfect fits smoothly
    score -= 30.0 * (-((x - 0.05) * (x - 0.05)) * 30.0).exp() * (1.0 - progress * 0.5);

    // Lookahead: if next item fits the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - (next_item_size as f64 / pr.max(1.0) - 1.0).abs());
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.3);
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    score += (open_bins_count as f64).ln() * x * 8.0;

    // Slight preference for bins below mean residual (consolidation)
    score += (mean_residual - pr) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Harmonic class logic: dead space matters more when it falls into
    // "unusable" residue classes relative to typical item sizes (multiples of 5/10).
    let dead = post_residual;
    if dead > 0 && dead < 10 {
        // tiny slivers are nearly useless unless they exactly match a small item class
        score += 12.0;
    }
    if dead >= 10 && dead < 20 {
        // mod-10 coupling: dead space congruent to 0 mod 10 is reusable by small items
        if dead % 10 == 0 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }
    // Integer division thresholds on post_residual
    let q = dead / 20; // coarse residue class
    score += q as f64 * 2.5;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 18.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space the next item cannot use
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (item large relative to mean residual).
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / mean_residual.max(1.0);
        if pressure > 0.8 || fitting_bins_count == 0 {
            score -= 15.0; // favor new bin under pressure
        } else {
            score += 25.0; // discourage wasting fresh bins
        }
    }

    // Mild stream-progression coupling: early on, be frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= progress * 5.0;
    }

    // Penalize bins far below mean residual (fragmentation avoidance).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are almost unusable
    // since future items are >= 1 but typically much larger; penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (11 - post_residual.min(11)) as f64);
    } else if post_residual > 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual near 0 handled by base term,
    // but give extra bonus for perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    }

    // If the lookahead item fits in the post-residual, this placement is
    // doubly efficient: subtract a bonus proportional to how well it fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.15 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // The next item cannot use this bin; the leftover is dead space for it.
        score += 3.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // across bins; with few bins, be lenient.
    score += 0.35 * open_bins_count as f64;

    // Mean residual coupling: prefer bins with residual below the mean
    // (fill the emptiest-fitting bins first to consolidate space).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate handling: an empty bin is attractive only when the
    // item leaves a large, reusable residual or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * 0.55 + 10.0 * (1.0 - progress);
        // If item leaves a big usable residual in the fresh bin, slightly cheaper.
        if post_residual >= 30 {
            score -= 8.0;
        }
        // Never open a new bin when this is the only fitting bin (keep existing).
        if fitting_bins_count == 1 {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: tiny post residual is highly desirable.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if the next item fits the post residual exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit: penalize dead space proportionally to how unusable it is.
            let dead = (next_item_size - post_residual) as f64;
            score += 30.0 * (dead / bin_capacity as f64).min(1.0);
        }
    }

    // Relative to mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize wasting a nearly empty bin's flexibility early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing fits are poor.
        score += 120.0 * (1.0 - progress);
    }

    // Slight preference to consolidate into fewer bins as stream matures.
    score += 2.0 * open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fits are excellent: reward low post_residual with a non-linear bonus.
    let tight_bonus = ((post_residual as f64) / bin_capacity as f64).powi(3);
    score -= 40.0 * (1.0 - tight_bonus);

    // Penalize dead space that cannot plausibly hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the lookahead item.
            score -= 5.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening new bins, more so early in the stream
    // and when many bins are already open (amortization of open-bin overhead).
    if is_new_bin {
        let mut penalty = 30.0 + 0.6 * open_bins_count as f64 + 25.0 * (1.0 - progress);
        // If the item would leave a very awkward residual elsewhere, allow new bin.
        if post_residual == 0 {
            penalty += 0.0; // perfect fit in fresh bin is fine but still not preferred
        }
        if next_item_size > 0 && next_item_size > item_size {
            // Next item is bigger; a fresh bin may serve it better.
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Global fragmentation pressure: if mean residual across open bins is high,
    // prefer consolidating into existing space (favor bins with residual near mean).
    let resid_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * resid_gap;

    // Slight preference for bins with larger residual early on (keep tight bins
    // available for small future items), reversed late in the stream.
    score += (bin_residual as f64 / bin_capacity as f64) * (12.0 * (1.0 - progress) - 6.0 * progress);

    // Exact fit is unbeatable.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // 0..1
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 8.0 * poly;

    // Reward tight fits more aggressively as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * t);

    // Penalize dead space: residuals too small for typical future items.
    if pr > 0.0 && pr < 10.0 {
        score += 6.0 * (10.0 - pr) / 10.0;
    }

    // Last-chance bonus: only one bin can fit this item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into resulting residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 4.0 * (1.0 - ni / cap);
        } else {
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for proliferation of open bins late in stream.
    score += 0.05 * (open_bins_count as f64) * t;

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does the leftover fall in?
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fits are golden: zero leftover is the ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space bands (harmonic classes of capacity):
    // leftover in (0,10] is nearly unusable dead space -> penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    }
    // leftover in (10,20] is only usable by the smallest items -> penalize.
    else if post_residual <= 20 {
        score += 25.0;
    }
    // leftover in (20,40] moderately useful.
    else if post_residual <= 40 {
        score -= 5.0;
    }
    // leftover in (40,60] is a half-bin, very reusable -> reward.
    else if post_residual <= 60 {
        score -= 15.0;
    }
    // large leftover > 60: still very flexible, mild reward.
    else {
        score -= 8.0;
    }

    // Exact harmonic divisor logic: if next item divides the post_residual evenly
    // (next_item_size divides post_residual), this bin absorbs the follower perfectly.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual % next_item_size == 0 {
        score -= 30.0;
    }
    // If next item fits with a tiny remainder, mildly reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let rem = post_residual - next_item_size as f64;
        if rem <= 10.0 {
            score -= 10.0;
        } else if rem <= 20.0 {
            score -= 4.0;
        }
    }
    // If next item cannot fit here, penalize leaving large leftover it could have used.
    else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish baseline, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 70.0;
        // But if the item exactly halves the bin, opening fresh is attractive.
        if item_size as f64 / cap >= 0.5 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins among equal leftovers: smaller bin_residual is better used.
    score += (bin_residual as f64) * 0.05;

    // Stream progression: late in the stream, avoid spreading across many bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 && open_bins_count > 3 {
        score -= 10.0;
    }

    // Coupling with mean residual: if this bin's post state is below average,
    // it's a good compaction target.
    if post < mean_residual {
        score -= (mean_residual - post) * 0.1;
    } else {
        score += (post - mean_residual) * 0.05;
    }

    // Integer-division threshold on post_residual: multiples of 5 are "rounder",
    // slightly more likely to match future item sizes drawn from coarse grids.
    if post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (waste-aware): bonus proportional to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 18.0;

    // If this bin is the last chance before opening a new bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward strongly.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if next item leaves another tiny gap in this bin.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap2 = post_residual - next_item_size;
        if gap2 < 10 {
            score += (10 - gap2) as f64 * 2.5;
        }
    }

    // Open-bin pressure: mildly discourage scattering across many open bins.
    score += open_bins_count as f64 * 0.35;

    // Mean residual coupling: penalize bins far above the mean residual (poor fits relative to fleet).
    score += (bin_residual as f64 - mean_residual).abs() * 0.08;

    // New-bin candidate handling: an empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins already open.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 0.35;
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits: opening new bin is fine
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 20.0; // reserve capacity for big upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits (small post residual)
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins where the next item fits the new residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish after placement
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 35.0;
            } else {
                score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here after placement -> penalize dead space
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit reasonably
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to ever hold a typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 15.0 - (slack as f64).min(15.0) * 0.4;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or all open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = bin_capacity as f64 - mean_residual;
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 + progress)
            + scarcity * 30.0
            + (avg_open_fill / bin_capacity as f64) * 10.0
            + open_bins_count as f64 * 0.5;
        // Base cost of a fresh bin + pressure-based discount.
        score += 55.0 - pressure.min(50.0);
    }

    // Mild preference to consolidate into bins below mean residual (balance avoidance).
    if bin_residual < bin_capacity {
        score += ((bin_residual as f64 - mean_residual) * 0.05).max(-4.0).min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fills (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins roomy; late, push toward very tight fits.
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress) * 20.0
                 - norm_pr * progress * progress * 10.0;
    score += coupling;

    // Penalize dead space that no plausible item can use, smoothly.
    let dead = (pr - next_item_size as f64).max(0.0) / cap;
    score += dead * dead * 30.0;

    // Reward using a bin when it's the last fitting option (avoid new bin).
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when bin is far from mean residual (keeps diversity balanced),
    // scaled smoothly by number of open bins.
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Slight preference for opening new bins early when residual is large.
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress) + pr * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: bins whose post_residual falls into
    // "usable" residue classes (multiples of small sizes) are more valuable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 25 == 0 {
        -6.0
    } else if pr % 7 == 0 {
        -2.0
    } else {
        6.0 // awkward leftover
    };
    score += class_bonus;

    // Integer-division thresholds: leftover usable by the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward proportional to how snugly
            score -= (pr - next_item_size) as f64 * 0.5;
            if pr % next_item_size == 0 {
                score -= 5.0; // exact harmonic match with next item
            }
        } else {
            score += 4.0; // next item won't reuse this leftover
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current leftover
    // would be dead space (very small post_residual classes are fine though).
    if bin_residual == bin_capacity {
        // opening a new bin: penalize mildly unless existing bins are fragmented
        score = 55.0 + mean_residual * 0.2 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin is attractive
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
    } else {
        // prefer bins whose residual is close in size to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
    }

    // Progress-based modulation: early on, keep bins flexible (avoid tiny leftovers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 0 && pr < 10 {
        score += 10.0 * (1.0 - progress); // dead space worse early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-zero post residual is ideal.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if the next item (or a typical item) cannot use it.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size) && next_item_size > 0 {
        score += 40.0; // gap too small for lookahead item -> likely dead space
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver, almost always dead space
    }

    // Reward when post_residual can still accommodate the next item (chainability).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Perfect-fit shaping: reward using bins whose residual was close to the item.
    let fit_quality = (bin_residual as f64 - item_size as f64).abs();
    score += fit_quality * 0.15;

    // Open bins pressure: prefer filling existing bins over opening new ones.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: if this bin's residual is far below average,
    // it is a "straggler" bin; prefer to consolidate into it.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: opening a new bin is expensive, but acceptable
    // if the item is huge and no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let waste_here = bin_capacity - item_size;
        score += 25.0 + open_bins_count as f64 * 3.0;
        if item_size >= 70 {
            score -= 20.0; // huge items: fresh bin is often the best choice
        }
        if waste_here < 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits: tiny post_residual is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize dead space that is too small for the smallest plausible item (<=10)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 0.5 {
            score -= 35.0;
        } else if post_residual as f64 >= next {
            // next item fits but not perfectly: mild reward proportional to tightness
            let slack = post_residual as f64 - next;
            if slack <= 10.0 {
                score -= 15.0 - slack * 0.5;
            } else {
                score += slack * 0.15;
            }
        } else {
            // next item cannot use this residual: residual likely wasted
            score += (post_residual as f64) * 0.25;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (fill fuller bins first, keep emptier bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no decent fit exists. Make the empty bin moderately expensive by default.
    if bin_residual == bin_capacity {
        // Cheaper early in the stream (few open bins) or when many bins can't fit well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = open_bins_count as f64;
        score += 45.0 + progress * 25.0 + openness * 3.0;
        // If the next item is large, a fresh bin keeps flexibility
        if next_item_size >= 60 {
            score -= 20.0;
        }
        // If this bin would be the only fitting bin, opening new is less bad
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Mild global scaling: slightly prefer filling bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 + 0.25 * post_residual as f64;
        } else if post_residual >= next_item_size {
            score -= 6.0; // bin remains useful for the lookahead item
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score += 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Reward using bins with below-average residual (consolidate slack).
    score -= 0.15 * (mean_residual - post_residual as f64);

    // Penalize opening new bins when many bins are already open and time remains.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But allow a new bin for large items that would wreck a good bin.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 30.0;
        }
    }

    // Mild preference for bins with small residual overall (pack tight bins first).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = item_size as f64 / cap;
    let nfit = fitting_bins_count as f64;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let shape = 1.0 + progress * progress;
    score += 0.35 * pr * pr / cap * shape;

    // Reward tight fits (small post_residual), stronger later in the stream
    score -= 12.0 * (1.0 - fit).powi(3) * (0.5 + progress);

    // Penalize waste relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead: penalize leaving residual too small for the next item
    if next_item_size > 0 {
        let gap = pr - nxt;
        if gap < 0.0 {
            score += 0.25 * (-gap);
        } else {
            score -= 0.1 * gap * (1.0 - gap / cap);
        }
    }

    // Mild penalty for opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity && nfit > 0.0 {
        score += 3.0 + 0.5 * nfit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 and integer division bands
    let pr = post_residual;
    let class = pr % 10;
    let band = pr / 10; // 0..=10

    // Reward small post_residual, especially "harmonic" residues that pair well
    // with common item sizes (multiples of 10, and sizes 1..100 unknown distribution).
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if class == 0 {
        score -= 15.0; // post_residual is a multiple of 10: reusable by round sizes
    } else if class <= 3 {
        score += 8.0; // awkward sliver
    }

    // Dead-space penalty: residuals below the minimum item size are unusable
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize proportionally to wasted capacity
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when open bins
    // would create bad fits (mean residual low means bins are nearly full).
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55;
        // open new bin more readily when existing residuals are small/fragmented
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        score = base + (1.0 - fragmentation) * 10.0
            - (open_bins_count as f64) * 0.5
            + (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    // Mild tie-break: prefer tighter bins (smaller bin_residual) among equals
    score += (bin_residual as f64) * 0.02;

    // Integer-division threshold: bins whose residual band is high (>=5, i.e. >=50 free)
    // are less precious; slightly deprioritize urgency there.
    if band >= 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable -> heavy penalty.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space severity: gaps smaller than typical small item (<= 10) are worst.
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap) / 10.0;
        } else if gap < 25.0 {
            score += 25.0 * (25.0 - gap) / 15.0;
        }
        // Smooth quadratic dead-space component scaled by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 0.08 * gap * gap * (0.5 + progress);
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Open-bin pressure: discourage scattering when many bins are open.
    score += 1.5 * open_bins_count as f64;

    // Prefer bins whose residual deviates from mean (consolidate space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 0.4 * (n - post_residual as f64).min(50.0);
        }
    }

    // New-bin candidate: neutral-ish base, opened only when fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening early in stream is cheaper than late (long horizon to fill it).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits (small post_residual)
    score += (post_residual as f64) * (post_residual as f64) * 0.01;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15; // chainable fit, penalized by leftover
        } else {
            // next item cannot use this residual: dead space risk
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.30;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual near mean are "normal",
    // deviating bins get normalized pressure
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if open bins are crowded
        score += 15.0 + mean_residual * 0.10;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly (fragments are wasted).
    if post_residual < 10 {
        score -= 25.0; // perfect/near-perfect fit strongly rewarded
    } else {
        let frag = post_residual as f64;
        score += 0.02 * frag * frag / bin_capacity as f64;
    }

    // Reward tight fits relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 3.0; // blocks the natural follow-up
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be conservative, prefer exact fits;
    // early, allow exploration of new bins for better long-term packing.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: open early if current bins are crowded with big residuals,
        // but late in the stream prefer squeezing into existing bins.
        let exploration = (1.0 - t) * (mean_residual / bin_capacity as f64);
        score += 5.0 - 20.0 * exploration;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
    } else {
        // Existing bin: late stream rewards tighter packing.
        score -= 6.0 * t * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, but with non-linear decay
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: residual value changes over stream progress
    // Early: keep bins tight (favor low post_residual); Late: prefer filling bins fully
    let progress_weight = 0.5 * (1.0 - (progress * std::f64::consts::PI).cos());
    score -= progress_weight * 20.0 * (1.0 - norm_pr);

    // Penalize deviation from mean residual (avoid fragmenting many bins unevenly)
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits in the resulting post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 * (1.0 - (next_item_size as f64 / cap));
        } else {
            // penalize leaving a residual that almost-but-not-quite fits next item
            let gap = (next_item_size as f64 - pr).max(0.0);
            if gap < 10.0 {
                score += 8.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Slight preference for using existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls in
    // "small residue" classes are valuable; large residues are dead space.
    let pr = post_residual;
    // Integer-division thresholds on post_residual (classes of 10)
    let class = pr / 10; // 0..=10
    match class {
        0 => score -= 30.0,           // near-perfect fit
        1 => score -= 18.0,
        2 => score -= 10.0,
        3 => score -= 4.0,
        4 => score += 2.0,            // awkward half-full zone
        5 => score += 6.0,
        6 => score += 10.0,
        7 => score += 14.0,
        _ => score += 18.0,           // large dead space
    }

    // Modulo arithmetic: leftovers congruent to common item sizes are reusable.
    let rem = pr % 10;
    if rem == 0 {
        score -= 6.0; // divisible residue, likely reusable by multiples of 10
    } else if rem <= 2 {
        score += 4.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here: penalize slightly more when this bin
            // is the only fitting option (last-chance logic)
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // and there is plenty of stream left to justify fresh capacity.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let bad_fit = (post_residual as f64) > 0.45 * cap;
        if bad_fit && open_bins_count > 0 && progress < 0.85 {
            score -= 8.0;
        } else {
            score += 15.0;
        }
    }

    // Spread awareness: prefer bins below mean residual (tighter packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild urgency: as stream nears end, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (min item size 1, but practically small gaps)
    // are dead space. Penalize small nonzero post_residual heavily.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable dead space: worst outcome.
            score += 60.0;
        } else if post_residual <= 20 {
            // Nearly unusable: strong penalty.
            score += 30.0;
        } else if post_residual <= 35 {
            // Risky gap: moderate penalty.
            score += 12.0;
        } else {
            // Usable gap: mild penalty proportional to wasted fraction.
            score += (post_residual as f64) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another;
    // with few open bins, allow new bins when the fit is poor.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; penalize more when
        // many bins are already open.
        score += 10.0 + open_pressure;
        // If the new bin would be filled well, soften the cost.
        score -= fill_ratio * 15.0;
    } else {
        // Existing bin: reward using already-open capacity.
        score -= open_pressure * 0.5;
    }

    // Lookahead: if next item fits into the resulting post_residual,
    // reward this placement strongly (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward for near-exact chaining.
        if post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    }
    // If next item is large and this placement leaves a gap it cannot use,
    // penalize creating fragmented space.
    if next_item_size > post_residual && post_residual > 0 && post_residual <= 20 {
        score += 10.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 8.0;
    }

    // Mild preference for bins below mean residual (balance avoidance of
    // many half-empty bins) — favor bins tighter than average.
    let mean_gap = mean_residual - bin_residual as f64;
    score += mean_gap * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next_item_size exactly.
    if next_item_size > 0 {
        let match_val = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += match_val * 0.8;

        // Perfect chain: item + next item exactly fill the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item would also fit after this placement.
        if next_item_size <= post_residual {
            score -= 12.0;
        }
    } else {
        // Last item: prefer tightest fill.
        score += 0.0;
    }

    // Relative to mean residual: favor bins that are tighter than average (less wasted space).
    let mean_gap = post_residual as f64 - mean_residual;
    score += mean_gap * 0.35;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize creating unusable dead space (small leftover that few items can use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when current fit is very poor.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless their fit is bad.
        score += 30.0;
        // More attractive late in the stream or when many bins are open and fragmented.
        score -= (open_bins_count as f64) * 0.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If next item is large, a fresh bin gives more flexibility.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize large dead space after placement.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    }

    // Lookahead coupling: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - next_tight / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize proportionally to the wasted gap.
            score += (next_item_size - post_residual) as f64 * 0.08;
        }
    } else {
        // Last item: prefer filling existing bins completely.
        score -= 15.0;
    }

    // Last-chance bonus: only one bin fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins (keep options);
    // late in the stream, strongly prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how crowded current bins are.
        score += 45.0 - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host both current and next item nicely.
            if item_size + next_item_size <= bin_capacity {
                score -= 25.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post residual (dead space), weighted by stream progress
    let mut score = norm_pr * (1.0 + 2.0 * progress) + 3.0 * norm_pr * norm_pr;

    // Smooth interaction: residual vs item size coupling (tight fits rewarded)
    score -= 1.5 * norm_item * (1.0 - norm_pr) * (1.0 - progress);

    // Mean residual deviation: prefer bins near mean residual (smooth Gaussian-like)
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev;

    // Last-chance bin bonus (smoothly damped by progress)
    if fitting_bins_count == 1 {
        score -= 1.2 * (1.0 - 0.5 * progress);
    }

    // Crowding penalty: many open bins -> prefer filling existing ones
    let crowd = (open_bins_count as f64).ln_1p() / 10.0;
    score += crowd * norm_pr;

    // Lookahead: smooth reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let fit_gap = (norm_pr - nxt).max(0.0);
        score -= 1.0 * (1.0 - fit_gap) * (1.0 - norm_pr).max(0.0);
    }

    // New-bin candidate: smooth penalty unless residual is nearly full capacity
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) + 1.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it cannot
    // hold any plausible future item (items >= 1, but small residuals < 10
    // are nearly useless; multiples of common sizes are reusable).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny unusable sliver
    }
    // Reusable harmonic classes: residuals divisible by 5 or 10 are friendlier
    if pr % 10 == 0 {
        score -= 15.0;
    } else if pr % 5 == 0 {
        score -= 7.0;
    }

    // Integer-division thresholds on post_residual
    let pr_class = pr / 20; // 0..=5 coarse class
    score += pr_class as f64 * 4.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            // next item fits: prefer leaving room, scaled by how well it fits
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0);
        } else {
            // next item won't fit here: penalize tight residuals slightly
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin if existing residuals
    // are large (poor fits) or this is a near-perfect fill of a fresh bin
    if bin_residual == bin_capacity {
        // brand-new bin: base penalty so it's chosen only when it beats bad fits
        score += 90.0;
        if item_size >= 50 {
            score -= 70.0; // filling a fresh bin with a large item is fine
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins below mean residual (relatively emptier bins get filled first,
    // keeping tight bins for small items)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (post_residual near zero but usable)
    if post_residual == 0 {
        score -= 15.0;
    } else {
        // fractional fill ratio bonus: prefer bins where item fills a large share of residual
        let fill = item_size as f64 / bin_residual as f64;
        score -= 10.0 * fill;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
        // But opening a new bin is attractive if current bin would leave a gap
        // exactly matching nothing useful (dead space) — already penalized above.
    } else {
        // mild pressure to consolidate into fewer bins
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would be blocked by a small leftover, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: near the end, prefer filling existing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

