            let two_step = post_residual - next_item_size;
            score -= 50.0 * (1.0 - two_step as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to wasted residual
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post_residual relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
