    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0 + (open_bins_count as f64) * 5.0;
        // but if the item is large relative to mean residual, new bin is less bad
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Mild penalty for large dead space that nothing (min size 1..100) can use
    if post_residual > 50 {
        score += (post_residual - 50) as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
