    // Many open bins with high mean residual: discourage spreading, prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    let spread_penalty = (open_bins_count as f64).ln() * (mean_residual / cap) * (1.0 + progress);
    score += 4.0 * spread_penalty;

    // Late in stream: prefer filling existing bins, avoid opening new ones
    if bin_residual == bin_capacity {
