}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, with a smooth non-linear inflation
    // of small-but-nonzero residuals (dead space that is hard to reuse).
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.9 * norm_post * (1.0 - norm_post));

    // Tight fits are strongly favored (quadratic reward near zero post-residual).
    score -= 28.0 * (1.0 - norm_post).powi(3);

    // Smooth stream-progress coupling: early on, prefer filling existing bins
    // loosely (keep options open); late, reward tight packing harder.
    score += (1.0 - progress) * 6.0 * norm_post;
    score -= progress * 14.0 * (1.0 - norm_post);

    // Last-chance bin: penalize skipping it (opening a new bin is costly).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0 * (1.0 - norm_post);
    }

    // New-bin candidate: penalize unless it yields a tight fit relative
    // to what existing bins could achieve; smooth in item size.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - norm_post;
        score += 18.0 + 10.0 * (1.0 - tightness);
        score -= 6.0 * tightness * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // Deviation from mean residual: prefer bins whose residual is close to
    // what the item consumes (smooth coupling).
    score += 0.02 * (resid - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is a multiple of 10
    // are "harmonic" and easier to fill later -> reward them.
    let pr = post_residual;
    let harmonic = (pr % 10 == 0) as f64;
    score -= 6.0 * harmonic;

    // Penalize dead space in awkward bands: leftovers 1..10 are near-unusable
    // (items are >= 10 in classic regime, but sizes 1..100 allowed here).
    if pr > 0 && pr < 10 {
        score += 8.0;
    }

    // Integer-division thresholds: classify leftover into thirds of capacity.
    let third = bin_capacity / 3;
    let two_thirds = 2 * bin_capacity / 3;
    if pr <= third {
        // Tight bin: excellent use, reward strongly.
        score -= 10.0;
        // Perfect fit bonus.
        if pr == 0 { score -= 25.0; }
    } else if pr <= two_thirds {
        score -= 3.0;
    } else {
        // Bin left mostly empty: wasteful, penalize.
        score += 12.0;
    }

    // Lookahead coupling: does next_item_size fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 7.0; // chaining possible
            // Harmonic match: next item lands post_residual on a multiple of 10
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            score += 5.0; // next item won't chain here
        }
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make it mildly unattractive unless
    // no open bin fits well (post_residual == capacity means empty bin).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, scaled by how many bins fit.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is required
        } else if item_size > two_thirds {
            // Large items: fresh bin often better than fragmenting a bin.
            score -= 18.0;
        }
    }

    // Mild preference for tighter-than-average bins (waste spreading control).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Small tie-break toward fewer open bins (consolidation pressure).
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
