    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with mild nonlinearity
    score = (post_residual as f64).powf(1.25);

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // perfect chain match strongly rewarded
            score -= 25.0 * (1.0 - gap / pr.max(1.0));
            // penalize leaving space just above next item size (dead space)
            if gap > 0.0 && gap < 10.0 {
                score += 6.0;
            }
        } else {
            // next item won't fit here either: residual stays dead until later
            score += 4.0;
        }
    }

    // Compare against mean residual: avoid destroying bins better than average
    if (post_residual as f64) > mean_residual {
        score += 0.5 * ((post_residual as f64) - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: keep it competitive only when current bins are poor fits
    if bin_residual == bin_capacity {
        // opening a new bin is penalized more late in the stream / many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.35 * bin_capacity as f64 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // allow new bin if no open bin fits well (post_residual of others handled elsewhere)
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to be useful later.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size / 2 {
            score -= 3.0;
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: only open a new bin when open bins are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let poor_state = avg_open_fit < item_size as f64 * 1.1;
        if fitting_bins_count == 0 || (poor_state && progress > 0.3) {
            score -= 15.0;
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference for filling bins below average residual (consolidation).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Time-horizon coupling: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 18.0 * norm_pr * (1.0 - norm_pr) * progress;
    score += 8.0 * norm_pr.powi(3) * progress;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 10.0 + (next_item_size as f64 - pr) * 0.5;
    }

    // Last-chance bonus: only one bin fits, encourage using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Slight preference toward consolidating residual mass
    score += (mean_residual - pr).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue determines dead-space quality.
    let pr = post_residual as i64;
    let residue = pr % 10;
    // Residues 0 (perfect) .. 9 (worst) map to a graded penalty.
    let residue_penalty: f64 = match residue {
        0 => -8.0,
        1 => 7.0,
        2 => 5.0,
        3 => 3.0,
        4 => 4.0,
        5 => -2.0,
        6 => 3.0,
        7 => 4.0,
        8 => 5.0,
        _ => 6.0,
    };
    score += residue_penalty;

    // Integer-division thresholds: bins whose post_residual falls in a "usable band"
    // for typical small items (10..=30) are rewarded.
    let band = (pr / 10) as f64;
    if band >= 1.0 && band <= 3.0 {
        score -= 4.0;
    } else if band > 6.0 {
        // Large leftover: wasteful unless the bin was fresh.
        score += 3.0;
    }

    // Lookahead coupling: reward if next item can fit exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 12.0;
        } else if next_item_size <= post_residual as u32 {
            score -= 3.0;
        } else {
            // Next item won't fit here: penalize proportionally to overshoot class.
            let overshoot = (next_item_size - post_residual as u32) as f64;
            score += (overshoot / 10.0).floor().min(5.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // (creates a big residual for future small items) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item_bonus = if item_size >= 60 { 6.0 } else { 0.0 };
        let scarcity_penalty = if fitting_bins_count > 2 { 14.0 } else { 4.0 };
        score += scarcity_penalty + progress * 6.0 - large_item_bonus;
        // Exact-fill of a fresh bin is always great.
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when open bins are generally full (low mean residual),
    // prefer packing tightly into this bin.
    if bin_residual != bin_capacity {
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score -= tightness * 5.0;
        // Penalize leaving this bin as an outlier far above the mean residual.
        let dev = post_residual as f64 - mean_residual;
        if dev > 0.0 {
            score += (dev / 20.0).min(4.0);
        }
    }

    // Slight preference for filling bins opened earlier (stability, fewer half bins).
    if open_bins_count > 3 && post_residual > 0 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (but nonzero) are the worst outcome. Treat gaps below a "useless zone"
    // as very costly, scaled by how far into the gap we are.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }

    // Perfect fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap exists but cannot host the next item: mild penalty
        score += 15.0;
    }

    // Tightness bonus: prefer bins where the item fills a large fraction
    // of the current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Open-bin pressure: discourage scattering across many bins,
    // but relax pressure late in the stream when consolidation matters less.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (2.5 - 1.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to capacity or no good existing fit exists. Penalize mildly by
    // default so existing bins with tight fits win; large items get relief.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 60 { 20.0 } else { 0.0 };
        score += 55.0 - large_item_bonus + (mean_residual / bin_capacity as f64) * 10.0;
    }

    // Slight preference for bins whose residual is close to the item size
    // (best-fit flavor) beyond raw post_residual ordering.
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += slack * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact match: next item fills this bin perfectly -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Lookahead: penalize post_residual just below next item size (wasted space).
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -next_item_size as f64 {
            // Post-residual slightly smaller than next item => dead space.
            score += (gap.abs() / next_item_size as f64) * 12.0;
        } else if gap >= 0.0 {
            // Post-residual can host next item: mild reward, tighter is better.
            score -= (1.0 - gap / bin_capacity as f64) * 6.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Late in stream: consolidate into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // Prefer filling nearly-full bins.
    let fill = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tight_fit = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tight_fit) * (1.0 - tight_fit);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 30.0 * (1.0 - (leftover as f64) / (bin_capacity as f64));
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for blocking.
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: discourage spreading; favor filling existing bins.
    let pressure = (open_bins_count as f64) / ((total_items.max(1) as f64).sqrt() + 1.0);
    score += 3.0 * pressure;

    // Mean residual coupling: bins far from the mean residual get a mild penalty
    // (prefer bins whose residual is typical, keeping balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, be more exploratory (prefer new bins less);
    // late in stream, pack tighter into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin, but relax when the item
    // is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        score += base_penalty - large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 20.0 * poly;
    // penalize wasted space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();
    // reward tight fits (small post residual) more strongly later in stream
    score -= (1.0 - pr_norm) * (1.0 + progress) * 5.0;
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 3.0 * (1.0 - ((pr - ns) / cap).abs());
        } else {
            score += 2.0;
        }
    }
    // last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }
    // discourage proliferating open bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    // new-bin candidate: penalize slightly so it's used only when fits are bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 act as "dead-space classes".
    let r = post_residual % 10;
    // Perfect fits and harmonic classes divisible into 100 get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Residue 0 classes (10,20,...) are the most reusable harmonic class.
        let class_reward: f64 = match r {
            0 => 14.0,
            5 => 9.0,
            2 | 4 | 6 | 8 => 5.0,
            _ => 0.0,
        };
        score -= class_reward;

        // Penalize very small unusable slivers, but less if they land on a good class.
        if post_residual < 10 {
            score += 12.0 - class_reward;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin chains perfectly — big reward scaled by next item size.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 + (slack as f64).min(10.0);
        // Harmonic bonus: next item lands on a multiple-of-10 residual too.
        if slack % 10 == 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless residuals
    // of open bins are nearly exhausted or the fit is poor.
    if bin_residual == bin_capacity {
        let tight = post_residual as f64 / bin_capacity as f64; // 1 - item/capacity
        score += 30.0;
        // Allow new bin when the item is large (poor fit anywhere) or stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - tight) * 18.0 + (1.0 - progress) * 10.0;
        // If many open bins have large mean residual, opening new bins is wasteful.
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 15.0;
    }

    // Mild penalty for bins that are already "harmonically depleted":
    // integer-division threshold: residual below a quarter of capacity is hard to fill.
    if post_residual > 0 && post_residual < bin_capacity / 4 {
        score += 6.0;
    }

    // Slight preference to fill bins with lower residual overall (best-fit core),
    // modulated by number of open bins to encourage consolidation.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small, hard-to-fill leftovers) are heavily penalized.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += 40.0 * (10.0 - post); // near-waste gap: strong penalty
    } else if post >= 10.0 && post < 30.0 {
        // mid-range leftover: mildly penalized, scaled by how far from a
        // typical small item size it sits
        score += 2.0 * (1.0 - post / 30.0);
    } else if post == 0.0 {
        // perfect fit: strong reward
        score -= 60.0;
    } else {
        // large leftover: gentle reward proportional to remaining space
        score -= 5.0 * (post / bin_capacity as f64);
    }

    // Reward tight fits: fraction of bin space actually used by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; if post residual can't fit next item
    // but bin_residual could have, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 15.0;
        } else if bin_residual as f64 >= nxt {
            score += 8.0; // blocks a known future fit
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter bin, better choice).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when the item is large
    // relative to available residuals or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // penalty that shrinks for large items / late stream
        score += 30.0 * (1.0 - large_item) * (1.0 - 0.5 * progress);
        if fitting_bins_count > 2 {
            score += 15.0; // plenty of alternatives: keep new bin closed
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-matches that leave next item placeable with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }
    // Penalize post_residual that is small but nonzero (dead space unusable by next item).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Penalize very tight fits slightly less than dead space but keep ordering.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }
    // Relative to mean residual: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }
    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * mean_residual;
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative, opening new bin is fine
        }
    }

    // Mild progression bias: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize tiny
    // unusable slivers (< next item's minimum possible need).
    if post_residual > 0 {
        let sliver = (post_residual as f64 / 20.0).min(1.0);
        score += 25.0 * sliver * sliver;
    }

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-fit bonus scaled by how snugly the next item fits
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 + 10.0 * (1.0 - snug / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize blocking residual slightly
            score += 4.0;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin normally, but relax
    // the penalty when the item fits poorly everywhere (large item) or
    // when many bins are already open and fragmented.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        // new bin attractive when item is large relative to mean residual
        let poor_fit = if mean_residual > 0.0 {
            (item_size as f64 / mean_residual).min(3.0)
        } else { 3.0 };
        score = bin_capacity as f64 * 0.5
            + 30.0
            - 20.0 * pressure
            - 10.0 * (poor_fit - 1.0).max(0.0)
            + 15.0 * fragmentation;
    }

    // Time horizon: early in the stream, be more willing to spread load
    // (future flexibility); late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins with below-mean residual (balance avoidance
    // of many medium residuals) — keep large residuals for large items.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early on, tolerate larger residuals; late, penalize wasted space quadratically.
    let progress_weight = 0.4 + 1.6 * progress * progress;
    score += progress_weight * pr_norm * pr_norm * cap * 0.5;

    // Smooth interaction between post_residual and mean residual deviation.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Reward tight fits smoothly (small post_residual) via cubic decay.
    score -= 8.0 * (-pr_norm * 6.0).exp() * (1.0 + progress);

    // Penalize leaving residual that cannot fit the lookahead item (smoothly).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 0.5 * (gap * gap) / cap;
        // Reward if lookahead fits exactly-ish.
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= 3.0 * (-fit_gap / 10.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - pr_norm);
    }

    // Mild penalty for bin proliferation (smooth in open_bins_count).
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Smooth new-bin bias: opening a fresh bin is favored mid-to-late stream
    // when the fit is poor, discouraged early.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 2.0 * (1.0 - progress) * (1.0 - pr_norm);
        score -= 1.5 * progress * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 residue classes
    let r = post_residual % 10;
    // Residue 0 (perfect multiple) is ideal; odd/tiny residues create dead space
    if r == 0 {
        score -= 12.0;
    } else if r <= 3 {
        score += 8.0; // small dead space, hard to fill
    } else if r <= 6 {
        score += 3.0;
    } else {
        score -= 4.0; // 7..9 residue still usable for mid items
    }

    // Integer-division thresholds: post_residual in harmonic capacity fractions
    let q = post_residual / (bin_capacity / 4); // quarters
    score += match q {
        0 => 15.0, // <25 left: near-dead bin
        1 => 2.0,
        2 => -3.0,
        _ => -6.0, // roomy bin
    } as f64;

    // Coupling with lookahead item (k=2): if next item fits post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // harmonic bonus: next item exactly consumes a residue class
            if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
                score -= 5.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate: penalize unless open bins are nearly all tight
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 20.0 - 15.0 * (pressure / (open_bins_count.max(1) as f64));
        if post_residual % 10 == 0 {
            score -= 10.0; // fresh bin with clean residue alignment
        }
    }

    // Stream progression: early on, keep bins balanced; later, exploit tight fits
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= t * (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Deviation from mean residual: prefer bins whose fill matches the pack average
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range)
    // are pure waste; penalize them heavily with a nonlinear blow-up.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (< min item size): severe penalty.
        score += 45.0 + (10.0 - pr) * 6.0;
    } else if post_residual <= 20 {
        // Marginal gap: only useful for tiny items, moderate penalty.
        score += 8.0 + (20.0 - pr) * 0.8;
    }

    // Reward tight fits relative to bin capacity (best-fit core with sharpening).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        if post_residual <= 10 {
            score -= 10.0; // near-perfect last-chance fit is excellent
        }
    }

    // Open-bin pressure: when many bins are open, discourage fragmenting
    // space further; when few bins are open, allow new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, but attractive if the
        // item is large and would leave awkward gaps elsewhere.
        score += 18.0 + pressure;
        if item_size >= 50 && post_residual < 50 {
            score -= 6.0;
        }
    } else {
        // Placing into an existing bin slightly reduces open-bin sprawl.
        score -= 2.0 + pressure * 0.3;
    }

    // Lookahead coupling: if the next item fits the post residual well,
    // reward leaving exactly that kind of gap.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            let gap_diff = (post_residual as f64 - n).abs();
            if gap_diff <= 5.0 {
                score -= 10.0; // chains perfectly with next item
            } else if gap_diff <= 15.0 {
                score -= 4.0;
            }
        } else if post_residual > 0 {
            // Next item cannot use this gap; if gap is small it's dead space.
            if (post_residual as f64) < 10.0 {
                score += 6.0;
            }
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual is below the
    // mean (smaller, tighter bins) to keep large residuals available.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual exactly matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // exact match for the next item is a jackpot
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score -= 50.0;
    }

    // compare against mean residual: bins with residual far from item_size are less attractive
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // tight fit bonus
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // new empty bin candidate: penalize unless current bins are nearly full / poor fits
    if bin_residual == bin_capacity {
        score += 150.0 * (1.0 - fill_ratio);
        // opening new bin more attractive early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize dead space non-linearly; small leftovers (<10) are nearly useless.
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += 25.0;
        } else {
            score += (pr / bin_capacity as f64) * 15.0;
        }
    }

    // Lookahead coupling: bonus if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Penalize if next item would be blocked by this placement's leftover.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_residual {
        score += 8.0;
    }

    // Last-chance bin: favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a bin is expensive unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 10.0;
        let waste = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Penalize new bins more when existing bins are fragmented (high mean residual)
        score += 30.0 + 25.0 * waste - 10.0 * crowding + 5.0 * progress;
    }

    // Mild preference for fuller bins relative to global state.
    score -= (bin_residual as f64 / bin_capacity as f64) * 3.0;
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fit = fitting_bins_count as f64;
    let obs = open_bins_count as f64;
    let meanr = mean_residual / cap;

    let mut score = pr;

    // smooth non-linear coupling of post-residual with stream progress
    let progress_coupling = prn * (1.0 + t * t) * (1.0 - prn * 0.5);
    score += 60.0 * progress_coupling;

    // penalize dead space more when many bins fit the item (choice available)
    let choice = fit / (obs + 1.0);
    score += 25.0 * prn * prn * (1.0 - choice);

    // last-chance bonus: subtract to prefer using a nearly-unique fitting bin
    let last_chance = (fit <= 1.5) as i32 as f64;
    score -= 40.0 * last_chance * (1.0 - prn * 0.3);

    // lookahead: reward leaving room for the next item (smooth bell)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = (pr - nx) / cap;
        let bell = (-8.0 * (room - 0.1) * (room - 0.1)).exp();
        score -= 15.0 * bell;
    } else {
        score -= 10.0 * prn;
    }

    // prefer bins whose residual deviates from the mean (tighten spread) via smooth term
    let dev = (meanr - prn) * (meanr - prn);
    score += 20.0 * dev * (0.5 + t);

    // mild preference for reusing bins over opening new ones as stream matures
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * t + 5.0 * obs;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it fall into?
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class = match pr {
        0 => 0u32,                 // perfect fill
        x if x < eighth => 1,      // near-full, dead space small
        x if x < quarter => 2,     // awkward sliver
        x if x < 2 * quarter => 3, // half-ish
        _ => 4,                    // roomy
    };

    // Reward perfect and near-perfect fills strongly.
    match class {
        0 => score -= 40.0,
        1 => score -= 12.0,
        2 => score += 8.0,   // slivers are dead space
        3 => score -= 2.0,
        _ => {}
    }

    // Modulo arithmetic on post_residual: residuals divisible by common item sizes
    // (multiples of 10, 25, 50) are more likely to be filled later.
    if pr % 10 == 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            // next item fits but leaves another residual; penalize if it creates a sliver
            let pr2 = pr - next_item_size;
            if pr2 < eighth && pr2 > 0 {
                score += 3.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; a roomy residual is wasted unless reusable
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // tie-breaking among many fitting bins: prefer tighter fit (already via post_residual)
        score += (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // New-bin candidate handling: only open a new bin when current fit is terrible
    // and plenty of stream remains.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of a new bin
        score += 55.0;
        // opening bins early is cheap-ish, late is expensive
        score += 20.0 * (1.0 - progress);
        // if existing bins are cluttered (high mean residual), new bin more attractive
        if mean_residual > cap * 0.45 {
            score -= 10.0;
        }
        // big items that leave big residuals anywhere justify a fresh bin
        if item_size >= 3 * quarter as u32 {
            score -= 8.0;
        }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    if open_bins_count > 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below 10 are almost unusable
    // (min item size is 1..100, but small gaps fragment capacity). Penalize
    // hard when post_residual falls into a "dead zone" (0 < gap < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post-residual, this placement is excellent (chained fit).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0; // chain ends in a near-perfect double fit
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap: the gap is likely dead space.
        score += (post_residual as f64).min(15.0) * 0.8;
    }

    // Last-chance bonus: if this is the only open bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones
    // (reduces fragmentation); few open bins -> opening new bins is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin has no fragmentation value;
    // make it attractive only when the current fit would waste a lot or
    // the item barely fits an existing bin.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.2 + 5.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits: new bin is mandatory
        }
    }

    // Slight global drift: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a nonlinear bonus
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // 2-step lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize dead space
            score += (post_residual as f64) * 0.35;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * progress;
        // new bin is OK if it enables a perfect chain with next item
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty if we leave large unusable gap
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.05 * gap;
            }
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; late, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If mean residual across bins is large, opening a new bin is wasteful.
        score += 0.3 * mean_residual;
    } else {
        // Slight preference for bins already below mean residual (rebalance load).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild penalty for very large items into nearly-full bins creating fragmentation.
    if item_size >= 70 && post_residual > 0 && post_residual < 20 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: post residual, scaled by a smooth polynomial of stream progress.
    let mut score = pr * (0.9 + 0.4 * progress * progress);

    // Non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to the smallest plausible future item.
    let dead = pr / cap;
    score += 8.0 * dead * dead * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a bin unless post_residual is large
    // relative to the lookahead item (i.e., the new bin can serve the next item well).
    if bin_residual == bin_capacity {
        let next = next_item_size as f64;
        if next > 0.0 {
            let next_fit = (pr - next).max(0.0) / cap;
            score += 10.0 - 14.0 * next_fit * (1.0 + progress);
        } else {
            score += 15.0;
        }
    }

    // Mild dispersion penalty: prefer bins whose residual is near the mean.
    let dev = (pr as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead coupling: reward bins whose post residual fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Slight preference for fewer open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible into nice
    // "co-fillable" classes (small, and multiples of common item sizes)
    // are less dead than awkward residues.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Penalize awkward dead space: residues that are tiny but nonzero are worst.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Reward post-residuals that are exact multiples of common size classes
    // (harmonic classes via integer division thresholds).
    for class in [10u32, 20, 25, 50] {
        if pr % class == 0 && pr > 0 {
            score -= 8.0;
        }
    }

    // Perfect fit: zero post-residual is ideal.
    if pr == 0 {
        score -= 40.0;
    }

    // Coupling with lookahead: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but leaves a bad residue -> mild penalty
        let nxt_post = post_residual - next_item_size;
        if nxt_post < 10 && nxt_post > 0 {
            score += 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residue: penalize proportionally
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Fractional capacity logic: prefer bins whose fill fraction is high.
    let fill_fraction = (bin_capacity - post_residual) as f64 / cap;
    score -= 10.0 * fill_fraction;

    // New-bin candidate: neutral-to-slightly-positive baseline; only choose
    // it when open bins leave large unusable residues.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        if mean_residual > 30.0 {
            score -= 10.0; // existing bins are roomy; using them is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 35 {
        score += 10.0;
    } else {
        // Larger leftovers are reusable: mild reward scaled by gap size.
        score -= (post_residual as f64) * 0.05;
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 300.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, favor using it
    // to avoid opening a new bin, unless it creates dead space.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via its large residual, and
    // add pressure proportional to open bins to discourage spreading).
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 150.0;
        } else if gap > 0 && gap < 10 {
            score += 30.0; // next item leaves dead space here
        } else if gap > 0 {
            score -= 10.0;
        }
    }

    // Late in the stream, tighten up: prioritize compacting residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 15.0;

    // Prefer bins whose residual is close to the mean (keeps bin states uniform,
    // preserving flexibility), slightly penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Aggressive 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits: reward, more so if the fit is snug.
            let snug = 1.0 - (post - nxt) / cap;
            score -= 12.0 * snug;
            // Perfect 2-chain: post_residual == next_item_size exactly.
            if (post_residual as i64 - next_item_size as i64).abs() <= 2 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            let dead = (post - (cap - nxt)).max(0.0); // unusable gap relative to next item
            score += 0.6 * dead;
            if post < nxt && post < 10.0 {
                // near-perfect single fit, next item forces a new bin anyway: good
                score -= 6.0;
            }
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are "loose";
    // filling loose bins is cheap, filling tight bins wastes flexibility.
    let dev = post - mean_residual;
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when item is large and would leave
    // a clean, reusable residual; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item / cap;
        score += 18.0 - 14.0 * fill_ratio; // big items prefer fresh bins
        if next_item_size > 0 && (next_item_size as f64) <= post - item {
            score -= 8.0; // new bin can host a 2-chain
        }
    }

    // Slight pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space quadratically, normalized by capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Reward near-perfect fits strongly.
    if post_residual < 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: favor leaving residual that still fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space for the known next item: penalize proportionally.
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
        // If next item fits exactly in post_residual, big reward.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: score competes with open bins.
        // Early: cheaper to open new bins; late: expensive.
        score = 100.0 - 60.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        // If no open bin fits well, opening a new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Avoid hoarding too many open bins late in the stream.
        score += 0.15 * open_bins_count as f64 * progress;
    } else {
        // Existing bin: mild preference when few bins are open (reduce fragmentation).
        score -= 2.0 / (open_bins_count as f64 + 1.0);
    }

    // Global residual alignment: prefer bins close to the mean residual (balanced packing),
    // unless it's a fresh bin.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer bins whose residual is slightly larger than the item (best-fit behavior).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, non-linearly warped by stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Dead-space penalty: quadratic in normalized post-residual, stronger late in stream.
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - slack).powi(2) * (1.0 - progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only fitting bin -> strong preference to use it.
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (keeps bin pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight scaling with number of open bins to discourage bin sprawl early.
    score *= 1.0 + 0.02 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead space" get penalized.
    let r = post_residual % 10;
    let dead_penalty = match r {
        0 => -30.0,                    // perfect fit class
        1 | 2 => 12.0,                 // nearly unusable slivers
        3 | 4 => 5.0,
        5 => -8.0,                     // half-slots pair well
        6 | 7 => 2.0,
        _ => 8.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: bins whose post_residual falls into a useful
    // class for common item sizes get rewarded.
    if post_residual >= 10 && post_residual <= 80 {
        // post_residual itself is a plausible future item size
        score -= 10.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with next item lookahead (harmonic match: next_item divides into
    // post_residual or complements it to a multiple of 10).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            let comp = post_residual - next_item_size;
            if comp % 10 == 0 {
                score -= 12.0;
            }
        } else {
            score += 6.0;
        }
        if post_residual % 10 == 0 && next_item_size % 10 == 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 45.0 - 30.0 * pressure;
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Prefer filling already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    // Small tie-break toward denser bins.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 40 {
        // Large leftover is flexible; mild reward.
        score -= 10.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize if the leftover can't fit the next item and is small-ish.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) slightly.
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Late in the stream, tighten up: favor tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;
    } else {
        // Perfect fill: strong reward.
        score -= 50.0;
    }

    // 2-step lookahead: if the next item exactly matches the post_residual,
    // this placement is excellent (chain fill).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            score -= 40.0;
        } else if post > next {
            // Next item fits in the leftover: mild reward proportional to how
            // much slack remains after placing the next item too.
            let two_step_left = post - next;
            score += (two_step_left / bin_capacity as f64).powf(2.0) * 15.0;
        } else {
            // Next item cannot fit here: penalize large dead space a bit more.
            score += (next - post).min(50.0) * 0.3;
        }
    } else {
        // Last item: prefer consuming an existing bin's residual fully.
        score += post_residual as f64 * 0.5;
    }

    // Deviation from mean residual: prefer bins that are already low
    // (concentrate filling) but avoid leaving outliers of tiny residual.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 10.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer existing bins over the new-bin candidate unless residual is large.
    if bin_residual < bin_capacity {
        score -= 5.0;
    } else {
        // New-bin candidate: penalize mildly so it wins only when fits are bad.
        score += 15.0;
    }

    // Late in the stream, closing out bins matters more: penalize leftover
    // residual harder as we approach the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // ~10 is nearly unusable, so give a bonus for very small leftovers.
    if post_residual < 10 {
        score -= 6.0;
    } else if post_residual <= 15 {
        score -= 3.0;
    }

    // Penalize waste relative to capacity: large post_residual means the bin
    // is nearly empty after placement (poor use of an existing bin).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 4.0 * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // it over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count <= 3 {
        score -= 3.0 * (3 - fitting_bins_count) as f64;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after that matters
            let chained = post_residual - next_item_size;
            score -= 5.0 - 0.05 * chained as f64;
        } else {
            // next item cannot fit here: slight penalty proportional to gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer filling existing bins as tightly as possible.
        score -= 8.0;
    }

    // Global state coupling: when mean residual across open bins is high,
    // there is slack in the system — prefer bins that reduce variance,
    // i.e., bins whose post_residual is close to the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Time horizon: early in the stream, be conservative (slightly favor
    // reusing bins to build tight packing); late in the stream, just
    // minimize leftover space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer not to open new bins when many bins are already open and the
    // item fits comfortably (post_residual >= 20 keeps bin useful).
    if bin_residual != bin_capacity && post_residual >= 20 && open_bins_count > 2 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic coupling of post_residual with capacity
    let waste = pr / cap;
    score += 12.0 * waste * waste * cap * 0.1;

    // Reward tight fits more strongly as stream progresses (smooth coupling)
    let tightness = 1.0 - waste;
    score -= tightness * tightness * (6.0 + 14.0 * progress);

    // Lookahead: penalize if post_residual cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // reward leaving exactly usable space for next item
            let gap = (pr - nx) / cap;
            score -= 8.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // dead space relative to next item, penalized quadratically
            let dead = (nx - pr) / cap;
            score += 10.0 * dead * dead * cap * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize spreading across many open bins slightly
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score = cap * 0.6 + 8.0 * (1.0 - progress) - 3.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "large" classes (>= 50) remain reusable; tiny leftovers are dead space.
    let cap_f = bin_capacity as f64;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Base: prefer tight fits (small post_residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 24.0 * tightness * tightness;

    // Harmonic classes via integer division thresholds on post_residual.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, best possible outcome
    } else if post_residual >= half {
        score -= 10.0; // large reusable class
    } else if post_residual >= quarter {
        // mid class: mildly penalize, dead-ish zone
        score += 6.0;
    } else {
        // tiny leftover class: strong dead-space penalty, scaled by class depth
        let depth = (quarter - post_residual) as f64;
        score += 12.0 + depth / (quarter as f64) * 14.0;
    }

    // Modulo arithmetic on post_residual: leftover compatible with common
    // small item sizes (multiples of 10 / 5) is more likely usable later.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 8.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead coupling: reward a residual that exactly fits next item,
    // penalize if the next item cannot use this bin's leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only
    // when no good fit exists. Penalize the fresh bin, but relax the penalty
    // when open bins are congested (low mean residual) or the item is large.
    if bin_residual == bin_capacity {
        let congestion = 1.0 - (mean_residual / cap_f).clamp(0.0, 1.0);
        let big_item = (item_size as f64) / cap_f;
        score += 18.0
            - 14.0 * congestion
            - 10.0 * big_item
            - (step_index as f64 / (total_items.max(1) as f64)) * 6.0;
    }

    // Slight preference to fill older/more populated bins to keep bin count down.
    score -= (open_bins_count.min(20) as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 {
        let dead_zone = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else { 0.0 };
        score += dead_zone;
        // Non-linear coupling: tiny gaps are worse when many bins are open.
        if post_residual < 10 {
            score += (open_bins_count as f64) * 3.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * (open_bins_count as f64);
    } else {
        // Reward filling existing bins, scaled by stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual becomes dead space for the known next item.
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 150.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: penalize small dead space that blocks it
        score += 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is below mean (tighter bins get filled)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: avoid wasting the only fitting bin on a bad fit
    if fitting_bins_count == 1 {
        score -= 80.0;
        if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
            score += 40.0; // but penalize if fit is poor and nothing follows
        }
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when open bins are bad
    if bin_residual == bin_capacity {
        score += 120.0;
        // open a new bin early in the stream or when lookahead fits perfectly
        if next_item_size == 0 || next_item_size > 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64).powi(3) * (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward;
    // if next item would fit this bin now but not after placement, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size <= bin_residual {
            score += 12.0;
        }
    }

    // Discourage opening new bins when many bins are already open and have slack.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 10.0 * (open_bins_count as f64).sqrt() + 15.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
        // Late in the stream, reusing bins is even more important.
        if progress > 0.7 {
            score += 15.0;
        }
    }

    // Slight preference for bins below mean residual (balance slack distribution).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: penalize leftover space, with smooth non-linear coupling to stream progress.
    // Late in the stream, dead space is more costly (fewer chances to fill it).
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: strongly penalize mid-range waste that is
    // unlikely to be reused, mildly reward very tight fits.
    let x2 = x * x;
    let x3 = x2 * x;
    score += 30.0 * (x2 - x3) * (0.5 + progress); // peaks around x ~ 0.66 (unusable zone)

    // Reward near-perfect fits smoothly.
    score -= 20.0 * (1.0 - x).powi(6);

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let tightness = 1.0 - (post - nxt) / cap;
            score -= 12.0 * tightness * (1.0 + progress);
        } else {
            // Post residual too small for next item: penalize proportionally to waste.
            score += 8.0 * (x2) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + 0.5 * progress);
    }

    // Slight preference for bins that are already more filled than average
    // (best-fit-like consolidation), smoothly scaled.
    let fill = (cap - post) / cap;
    let mean_fill = 1.0 - (mean_residual / cap);
    score -= 6.0 * (fill - mean_fill);

    // Mild penalty for proliferation of open bins.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: make it unattractive unless nothing else is reasonable,
    // via a smooth barrier growing with progress.
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 + progress) - 15.0 * (1.0 - (post / cap));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" multiples
    // of common item sizes are more reusable; penalize awkward remainders.
    let r = post_residual;
    if r > 0 {
        let r_mod_10 = r % 10;
        score += r_mod_10 as f64 * 1.5;          // dead space below granularity 10
        if r % 20 == 0 { score -= 8.0; }          // very reusable class
        else if r % 5 == 0 { score -= 3.0; }      // moderately reusable
        if r <= 10 { score += 12.0; }             // near-unusable sliver
        else if r <= 20 { score += 5.0; }
    } else {
        score -= 20.0;                            // perfect closure
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how well next item divides the post residual
            let slack = post_residual - next_item_size;
            score -= 6.0;
            if slack % 10 == 0 { score -= 4.0; }
        } else {
            score += 4.0; // next item likely needs another bin anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are tight
    // or the fit here is poor.
    if bin_residual == bin_capacity {
        let tight = open_bins_count == 0
            || (mean_residual < item_size as f64 * 1.2)
            || (post_residual > 0 && post_residual < 10);
        if tight {
            score -= 10.0;
        } else {
            score += 25.0; // keep using open bins when they fit well
        }
    }

    // Progress term: early in the stream, tolerate slight waste to keep bins
    // flexible; late in the stream, prioritize tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64 - item_size as f64) * 0.05;

    // Spread penalty: avoid concentrating waste when mean residual is already low.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 8.0;

    // Penalize large leftover space that can never be used by typical items:
    // gap in [1, 9] is worst (already covered); gap slightly above item minimums is bad too.
    if post_residual >= 1 && post_residual < item_size.min(20) {
        score += 4.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is relatively cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // Last chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mild reward proportional to how well it uses the gap.
        let fill = next_item_size as f64 / post_residual.max(1) as f64;
        score -= fill * 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the gap: penalize dead space creation.
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are tight or the fit is poor. Add a baseline penalty that grows with
    // mean residual (if open bins have lots of room, avoid new bins implicitly
    // by making them cheaper).
    if bin_residual == bin_capacity {
        score += 3.0 + (mean_residual / bin_capacity as f64) * 10.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative anyway
        }
    }

    // Deviation from mean residual: bins with residual far above mean are
    // better targets (they are the "loose" bins), so reward filling them.
    let dev = (bin_residual as f64) - mean_residual;
    score -= dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score = post_residual as f64 * 1.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space penalty: unusable residual relative to capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    if dead > 0.0 && dead < 0.10 {
        score += 20.0; // tiny slivers are hard to fill
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fit
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins whose post_residual deviates
    // favorably (smaller than mean => tight packing)
    if mean_residual > 0.0 {
        score += 0.3 * (post_residual as f64 - mean_residual);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 10.0 * (1.0 - progress);
        // allow new bin if next item is huge and current item leaves bad residue
        if next_item_size >= item_size && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    // Mild preference for fuller bins when many bins are open
    score -= 0.05 * (bin_residual.saturating_sub(post_residual)) as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Penalize dead space: post-residual below typical small item size is wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward if next item fits into post-residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= (next_item_size as u64) {
            score -= 12.0;
        } else if (post_residual as u64) < (next_item_size as u64) {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Prefer bins with residual below mean residual (tighter bins first),
    // keeping looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Time horizon: early in the stream, be more conservative about opening
    // new bins; late in the stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (15.0 + 25.0 * progress);

    // Many open bins: discourage opening another; few open bins: opening is cheap.
    score += new_bin * (open_bins_count as f64) * 2.0;

    // Slight preference for filling nearly-full bins as stream progresses.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * (10.0 * progress);

    // Item size coupling: large items should go into large-residual bins.
    score += (item_size as f64 / bin_capacity as f64) * (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: normalized post residual (0..1) shaped by progress
    let prn = pr / cap;
    score += 8.0 * prn * prn * (0.5 + progress) * cap * 0.01;

    // Reward tight fits, amplified as stream progresses
    let fit = 1.0 - prn;
    score -= 12.0 * fit * fit * (0.3 + 0.7 * progress);

    // Penalize dead space: residuals too small to hold typical items
    if pr < next_item_size as f64 && next_item_size > 0 {
        score += 6.0 + 10.0 * progress;
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Mild penalty when bin is far below mean residual (wasteful use of a rich bin)
    score += 0.05 * (mean_residual - pr).max(0.0);

    // Slight preference to fill existing bins rather than open new ones, stronger early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress);
    }

    // Smooth cubic interaction of post residual with progress
    score += 2.0 * prn * prn * prn * cap * 0.01 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals that are exact multiples of common size classes are more reusable.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize very small dead space (wasted capacity) with a steep non-linear term
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward residuals that fall into reusable harmonic classes (multiples of 10/20/25)
    let r = post_residual;
    if r % 10 == 0 {
        score -= 8.0;
    }
    if r % 20 == 0 {
        score -= 4.0;
    }
    if r % 25 == 0 {
        score -= 3.0;
    }
    // Penalize awkward residuals just below common item sizes
    if (11..=19).contains(&r) || (21..=24).contains(&r) || (26..=29).contains(&r) {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; penalize leaving large residual unused
            score += 0.15 * (post_residual as f64 - frac * cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive early in the stream or when
    // current bin fit is poor (large post_residual with no lookahead benefit)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > cap * 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 10.0 + 15.0 * (1.0 - progress);
        } else {
            score += 8.0;
        }
    }

    // Mild preference for compact bins as stream progresses
    score += frac * frac * 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    }

    // Reward tight fits generally.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: make it unattractive unless it is genuinely needed.
    if bin_residual == bin_capacity {
        score += 70.0 + open_bins_count as f64 * 3.0;
        // Allow new bin late in stream if current item is huge and lookahead is large
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 60 && next_item_size > 60 && progress > 0.5 {
            score -= 80.0;
        }
    }

    // Lookahead coupling: penalize leaving a gap that barely misses the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0; // gap exactly fits next item
    }

    // Mild alignment with mean residual: prefer bins below mean residual (tighter).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small residuals under the minimum item size are wasted.
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score -= 500.0;
        }
        // Nonlinear dead-space penalty for tiny residuals.
        score += (post_residual as f64).powi(2) * 0.01;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual as f64 >= ni {
            // Perfect chain: post_residual exactly equals next item size.
            let gap = post_residual as f64 - ni;
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 400.0;
            }
        } else {
            // Next item cannot follow here: penalize proportionally to wasted lookahead.
            score += 50.0 * (ni - post_residual as f64) / ni.max(1.0);
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so late in stream
    // or when many bins are already open.
    if bin_residual == bin_capacity {
        score += 60.0;
        score += 0.5 * open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Slight preference to fill more-open bins early (reduce bin sprawl).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual, penalize large dead space
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item would fit better elsewhere (post residual too small but nonzero), mild penalty
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fitting open bins exist
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin
        score += 60.0;
        // More open bins with slack => discourage new bins
        score += open_bins_count as f64 * 2.0;
        // Early in stream, new bins are cheaper; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // If mean residual across open bins is high, opening new bin is wasteful
        score += mean_residual * 0.5;
        // If item is large relative to capacity, a fresh bin is more acceptable
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
    } else {
        // Slight preference for bins below mean residual (balance load)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Global pressure: many open bins -> favor filling existing ones harder
    score -= open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: residual penalty grows with stream progress
    let coupling = norm_pr * norm_pr * (0.5 + progress);
    score += 12.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Lookahead: penalize leaving residual that cannot fit next item
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 4.0 * (1.0 - pr / (next_item_size as f64 + 1.0)) * (0.3 + 0.7 * progress);
        } else {
            score -= 3.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Penalize last-chance bins less (avoid opening new bins unnecessarily)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr);
    }

    // Mean residual context: prefer bins deviating from mean when many bins open
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * (open_bins_count as f64).ln().max(0.0) / (1.0 + progress);

    // Mild penalty for opening new bins late in stream
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (1/2, 1/3, 1/4) — leftovers near these fractions
    // are more reusable by future items, so reward them.
    let half = cap * 0.5;
    let third = cap / 3.0;
    let quarter = cap * 0.25;
    let pr = post_residual as f64;

    // Distance to nearest harmonic anchor; closeness => subtract bonus.
    let d_half = (pr - half).abs();
    let d_third = (pr - third).abs();
    let d_quarter = (pr - quarter).abs();
    let d_min = d_half.min(d_third).min(d_quarter);
    score -= (cap * 0.15) * (1.0 - d_min / half).max(0.0);

    // Integer-division dead-space penalty: residual in the awkward
    // (1, 10) band is nearly unusable given min item size.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot ever fit, penalize mildly.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 20.0 * (1.0 - ((pr - ni) / cap).abs());
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, discourage opening
    // a new bin (subtract), scaled by how full the bin already is.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - bin_residual as f64 / cap);
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when the stream is early or open bins are many and
    // fragmented (mean residual low relative to capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = open_bins_count as f64 / 8.0;
        let new_bin_bonus = 25.0 * (1.0 - progress) + 30.0 * fragmentation + pressure * 10.0;
        // Base cost of a fresh bin keeps it from winning on good fits.
        score = score.min(0.0) + cap * 0.55 - new_bin_bonus;
    }

    // Modulo tie-break on item class: items in coarse size classes pair
    // better with residuals of matching class; small deterministic nudge.
    let cls = (item_size / 10) as f64;
    let prc = (post_residual / 10) as f64;
    score -= 0.5 * ((cls - prc).abs() < 1.5) as u8 as f64;

    // Mild pressure to prefer fewer open bins when fragmentation is low.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).clamp(0.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead coupling ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: this bin will be exactly filled by the next item
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: mild reward,
            // decaying as leftover slack grows beyond what's needed
            score -= 12.0 - 0.08 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space for the lookahead item: penalize proportionally
            score += 3.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // --- Last-chance bin bonus (avoid opening a new bin unnecessarily) ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: its post_residual is already large,
        // add an extra opening penalty so we only open when fits are poor
        score += 30.0 + 0.3 * item_size as f64;
        // If the only fitting bin would leave dead space vs the lookahead item,
        // opening a fresh bin becomes attractive
        if next_item_size > 0 && fitting_bins_count == 1 {
            let alt_post = bin_residual - item_size; // post_residual of the sole fitting bin approximated by context
            if next_item_size > post_residual && post_residual < next_item_size {
                score -= 20.0;
            }
            let _ = alt_post;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // --- Context relative to mean residual across open bins ---
    score += 0.05 * (mean_residual - post_residual as f64);

    // Slight preference for bins with many siblings (keep few bins hot)
    if open_bins_count > 1 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that cannot fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // If next item would exactly fill the post residual, strong reward.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: prefer fullest possible bin.
        score -= 20.0;
    }

    // Global state coupling: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins open or early in stream.
        score += 18.0 + open_pressure * 6.0 + (1.0 - progress) * 10.0;
        // But if mean residual across bins is small (all bins tight), a new bin is fine.
        score -= (mean_residual / 10.0).min(20.0);
    }

    // Prefer bins with residual below the mean (consolidate fullness).
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Mild time-dependent exploration: later in stream, favor tighter fits more.
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p = progress;
    let poly = norm_pr * (1.0 + 2.0 * p * p + 3.0 * p * p * p);

    let mut score = poly;

    // Penalize large dead space quadratically
    score += 0.5 * norm_pr * norm_pr;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 0.8 * (n / cap);
        } else {
            score += 0.8 * ((n - pr) / cap);
        }
    }

    // New-bin candidate: mildly penalize early, allow later
    if bin_residual == bin_capacity {
        let openness = 0.5 + 1.5 * p;
        score += openness + 0.3 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward small post_residual (tight fit).
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(2) * 10.0;

    // Harmonic classes: post_residual divisible by small moduli => likely reusable slots.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 5 == 0 { score -= 2.0; }
        if pr % 3 == 0 { score -= 1.0; }
        // Dead-space penalty: residual too small for the smallest plausible item (1..100 range).
        if pr < 10 && pr > 0 {
            score += 25.0; // dead space, unusable
        }
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect harmonic match: next item exactly fills remainder.
            if next_item_size == pr { score -= 20.0; }
            else if pr % next_item_size == 0 { score -= 8.0; }
            else { score -= 3.0; }
        } else {
            // Next item won't fit here: penalize proportionally to wasted potential.
            score += 4.0 + (next_item_size - pr) as f64 * 0.15;
        }
    } else {
        // Last item: prefer any fit, tightness dominates.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0
            + open_bins_count as f64 * 0.5
            + (1.0 - (step_index as f64 / (total_items as f64 + 1.0))) * 10.0;
        // But if next item is large and mean residual is small, new bin is less bad.
        if next_item_size > 50 && mean_residual < 30.0 {
            score -= 25.0;
        }
    }

    // Mild preference for bins with residual close to item_size classes (integer division buckets).
    let bucket = pr / 20;
    let item_bucket = item_size / 20;
    if bucket >= item_bucket {
        score -= 1.5;
    }

    // Prefer filling bins with larger residual spread (avoid fragmenting many half-full bins).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.05;

    // Progress term: later in stream, be more tolerant of loose fits to avoid opening bins.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Penalize bins whose residual deviates from mean residual (prefer balanced state),
    // but only mildly, so dead-space logic dominates.
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Open-bin pressure: discourage spreading across many bins; the new-bin candidate
    // (bin_residual == bin_capacity) gets an extra load that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        if next_tight < 10.0 {
            score -= 20.0 - 1.5 * next_tight;
        }
    }
    // If next item would be blocked by this placement, penalize slightly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: strong reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            // Penalize mismatch scaled by magnitude of difference
            score += diff * 0.35;
        }
        // If next item can also fit in this bin after placement, reward
        if post_residual >= next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: minimize leftover tightly
        score += (post_residual as f64) * 0.5;
    }

    // Relative-to-mean coupling: prefer bins below mean residual (tighter bins)
    let resid = post_residual as f64;
    score += (resid - mean_residual) * 0.25;

    // Penalize large dead space that nothing (min item 1..10) can use
    if post_residual < 10 && post_residual > 0 {
        score += 6.0; // small unusable slivers are bad unless exact
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave huge waste
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if lookahead suggests a fresh bin fits both items perfectly, soften penalty
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 20.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild penalty for many open bins: encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit bias: reward small post-residuals super-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Dead-space penalty: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item could use this bin's post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if next item would need a fresh bin anyway but post-residual is large.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when no
    // open bin fits well, or when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base reluctance to open new bins, softened by fragmentation.
        let mut new_bin_score = 60.0;
        // If many bins but few can fit, opening fresh is reasonable.
        if fitting_bins_count == 0 {
            new_bin_score -= 70.0;
        } else if fitting_bins_count == 1 {
            // Last open bin fits: prefer using it unless fit is terrible.
            new_bin_score += 55.0;
        }
        // Fragmented state (low mean residual) favors a fresh bin.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Late in stream, slightly avoid opening new bins (less payoff).
        new_bin_score += progress * 10.0;
        // Large items starting a bin leave room for a medium follow-up.
        if item_size >= bin_capacity / 2 {
            new_bin_score -= 15.0;
        }
        score = score.min(new_bin_score + post_residual as f64);
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize wasted residual (best-fit core), slightly superlinear.
    let mut score = pr * (1.0 + 0.002 * pr);

    // Smooth non-linear coupling: large post_residual hurts more as stream progresses
    // (dead space late in the stream is less likely to be recovered).
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Perfect-fit lookahead reward: next item exactly fills the leftover space.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        let gap_norm = gap / cap;
        score -= 18.0 * (1.0 - gap_norm) * (1.0 - gap_norm);
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline, modulated by how
    // well the item itself would fill a fresh bin and by stream progress.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 20.0 - 10.0 * fill * fill + 6.0 * progress;
        // Strongly prefer a new bin over a very poor fit in an existing bin.
        if pr_norm > 0.6 {
            score -= 8.0 * (pr_norm - 0.6);
        }
    }

    // Mild tie-breaker: prefer filling bins that are already relatively full
    // relative to the fleet mean (keeps a few "loose" bins for future items).
    score += 0.05 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is a "usable"
    // class (small or large) are rewarded; mid-range dead space penalized.
    let pr = post_residual;
    let class = pr % 10; // decade class of leftover
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= 10 {
        score -= 15.0; // nearly full, tiny waste
    } else if pr > 50 {
        score -= 5.0; // large leftover stays reusable
    } else {
        // mid-range dead space: penalize more when class is awkward
        score += (10 - class) as f64 * 0.5;
    }

    // Integer-division threshold: leftover divisible by small sizes is reusable
    if pr > 0 && (pr % 5 == 0 || pr % 10 == 0) {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            // next item won't fit here; mildly penalize leaving awkward gaps
            if pr > 0 && pr < next_item_size && pr < 20 {
                score += 6.0;
            }
        }
    }

    // Progress-based pressure: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bins are bad
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // but if no open bin fits well (large post waste elsewhere), allow it
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10) can use are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0 - (post_residual as f64) * 6.0; // tiny gaps are worst
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fitting when this is the last chance bin (avoid opening a new bin needlessly)
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer tightening existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is far from mean (i.e., this bin is tighter than average)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 - gap * 0.25;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // dead space relative to lookahead
    }

    // New-bin candidate: only attractive when no good existing option (high residual everywhere)
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count <= 1 {
            score -= 35.0; // opening a new bin is fine if nothing fits well
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual too small for next item: dead space penalty (waste)
    if next_item_size > 0 && post_residual < next_item_size {
        // penalize proportionally to how unusable the leftover is
        let waste = next_item_size as f64 - post_residual as f64;
        score += 0.5 * waste;
    }

    // Post residual large enough for next item: mild reward, scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Prefer bins with residual below mean (tighter packing), penalize above-mean usage
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving large residual when many bins are already open (fragmentation)
    if open_bins_count > 4 && post_residual as f64 > mean_residual * 1.5 {
        score += 8.0;
    }

    // Early in stream: keep bins balanced (avoid extreme residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.05 * (post_residual as f64 - bin_capacity as f64 / 2.0).abs();
    }

    // New empty bin: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.09;
    score
