pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Reward tight fits more strongly later in the stream.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 40.0 * (0.5 + progress);

    // Lookahead: reward if next item fits into post residual.
    if next_item_size > 0 {
        let fits = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let slack_gap = (pr - next_item_size as f64).abs();
        score -= fits * 15.0 * (1.0 - slack_gap / cap);
        score += (1.0 - fits) * 5.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Slight penalty when bin is far from mean residual (fragmentation).
    score += ((pr - mean_residual) / cap).abs() * 8.0;

    // Mild preference for consolidating into fewer bins as stream progresses.
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is divisible into
    // useful chunk sizes (multiples of 10, or small enough to be dead space)
    // are rewarded; awkward mid-range leftovers are penalized.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        let class = pr % 10;
        // Residuals that are exact multiples of 10 pair well with typical item sizes
        if class == 0 {
            score -= 12.0;
        } else if class <= 3 {
            score += 8.0; // tiny sliver: nearly dead space
        } else if class >= 7 {
            score += 5.0; // awkward 7-9 remainder
        }
        // Integer-division thresholds on post_residual
        if pr <= 10 {
            score -= 20.0; // small leftover, fine to consume
        } else if pr <= 20 {
            score -= 5.0;
        } else if pr > 50 {
            score += 10.0; // large waste when item was big
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            // next item won't fit here; slightly penalize wasting residual
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are badly fragmented and item is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let big_item = item_size >= 60;
        if big_item && fragmentation > 0.35 && open_bins_count > 2 {
            score -= 15.0; // fresh bin justified
        } else {
            score += 25.0 + 20.0 * progress; // prefer existing bins
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps below the minimum item size)
    let min_item = 1.0f64;
    if post_residual > 0.0 as u32 as f64 && (post_residual as f64) < 10.0 {
        score += (10.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= (item_size as f64 / (bin_residual as f64 + 1.0)) * 20.0;
    }

    // Open bins pressure: prefer spreading across fewer bins
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * 0.5;
    } else {
        // New bin candidate: penalize opening a new bin unless current fit is bad
        score += 15.0 + open_bins_count as f64 * 0.3;
    }

    // Last chance bin: strongly reward using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32 as f64) <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size as f64 && post_residual > 0.0 {
        score += 8.0;
    }

    // Progress-based dead space penalty
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight residual by how "dead" it is
    // relative to the smallest plausible item.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strong reward when the leftover space exactly matches the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect lookahead match: big subtraction; decay with gap size.
        score -= 30.0 * (1.0 - gap / (bin_capacity as f64)) - 0.5 * gap;
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space creation.
        let dead = next_item_size - post_residual;
        score += 8.0 + dead as f64 * 0.3;
    }

    // Reward leaving residuals that are small enough to be nearly useless-fillers
    // (very small post_residual means the bin is almost perfectly packed).
    if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Relative to mean residual: placing into a bin with above-average residual
    // is good (drains large holes); below-average residual bins are precious.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early on and when
    // other bins fit; but allow it when open bins would waste lots of space.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if fitting_bins_count > 0 {
            // minimum post residual we'd get among fitting open bins is unknown,
            // approximate via mean residual vs item size
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score += 40.0 + 30.0 * progress - waste_elsewhere * 0.6;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin gives perfect room for next item
        }
    }

    // Slight preference to fill older/more crowded bin sets to consolidate.
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (wasted space dominated quadratically).
    score += 0.15 * (post_residual as f64).powi(2) / cap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            score -= 12.0 + 8.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else if nxt > post_residual as f64 && post_residual > 0 {
            // dead space that likely can't host next item: penalize
            score += 6.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bin; scale with how many bins already fit the item
        score += 25.0 + 10.0 * fitting_bins_count as f64;
        // late in stream, prefer filling existing bins even more
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // if mean residual is large, existing bins have room
        score += 0.2 * mean_residual;
    } else {
        // reward using existing bins, more when they're relatively full
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 10.0 * fill;
        // prefer bins below mean residual (fuller than average)
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    // Mild exploration term: vary preference with stream position.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * ((t * std::f64::consts::PI).sin());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + 1.5 * progress * progress)
        - 0.8 * x * x * (1.0 - progress)
        + 0.35 * x * x * x;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - x;
    score -= tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = (x - nx).max(0.0);
        score += 0.6 * waste * waste * (1.0 + progress);
        if nx <= x {
            score -= 0.4 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize early, allow late when fits are poor
    if bin_residual == bin_capacity {
        score += 0.9 - 0.7 * progress * progress;
        score += 0.05 * (open_bins_count as f64);
    }

    // Slight preference for bins deviating from mean residual (balance)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "friendly" classes (small or exactly matching common item sizes).
    let pr = post_residual;
    if pr > 0 {
        let pr_mod = (pr % 10) as f64;
        score += pr_mod * 0.35; // penalize residuals not aligned to decade grid
        // Perfect class: residual is a plausible future item size
        if pr >= 1 && pr <= 100 && (pr % 5 == 0) {
            score -= 4.0;
        }
        // Dead space: residual too small for the minimum plausible item
        if pr < 10 {
            score += 18.0;
        } else if pr <= 20 {
            score += 3.0;
        }
    } else {
        score -= 12.0; // perfect fill
    }

    // Integer-division threshold on residual utilization
    let fill = 1.0 - (post_residual as f64) / cap;
    let tier = (fill * 4.0).floor(); // 0..3 quartile of fill
    score -= tier * 5.0;

    // Lookahead coupling: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + slack * 0.08;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: keep it competitive only when current bin
    // would leave bad dead space or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64) / cap;
        // base new-bin score ~ half capacity wasted potential
        score = cap * 0.5;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 5.0;
        }
        if mean_residual < cap * 0.25 {
            score -= 8.0; // open bins nearly full -> fresh bin attractive
        }
        let _ = pressure;
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (1.0 - fill);

    // Fragmentation penalty: many open bins with high mean residual
    if open_bins_count > 3 && mean_residual > cap * 0.5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space: gap too small for any item (items >= 1, but tiny gaps are waste).
            score += 40.0;
        } else if post_residual < 20 {
            // Nearly dead: only very small items could fit.
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        }
    } else {
        // Perfect fill: strongly reward exact closure.
        score -= 25.0;
    }

    // Reward tight fits: item occupying a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit would create severe dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and discourage opening yet another one.
    score += 0.35 * open_bins_count as f64;

    // New-bin candidate: penalize relative to how fragmented existing bins are.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified when existing residuals are small/fragmented.
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 30.0 - 20.0 * frag;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 20.0;
        } else if slack < 10 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: gap likely becomes dead space.
        if post_residual < 10 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight dead space more when bins are plentiful.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 + 2.0 * (1.0 - progress);
    score = post_residual as f64 * tightness;

    // Aggressive 2-step lookahead: reward post_residual that closely matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_reward = 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0).powi(3);
        score -= lookahead_reward;
        // Perfect chaining: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space next_item_size can never use.
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0 + 0.15 * post_residual as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 5.0;
    }

    // Relative to mean residual: prefer bins already below average residual (consolidate).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is large or no good fits exist.
    if bin_residual == bin_capacity {
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score += 35.0 - big_item_bonus - scarcity_bonus;
        // Discard new-bin lookahead mismatch: fresh bin residual after placement should host next item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual non-linearly.
    let cap = bin_capacity as f64;
    let tight = post_residual as f64 / cap;
    score += 18.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small dead space that cannot plausibly fit typical items is bad.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 + 0.25 * next_item_size as f64;
        } else {
            // Post-residual useless for the known next item: penalize proportionally.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if mean_residual > 0.0 {
        let frag = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 5.0 * frag;
    }
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive early in stream or when the item is huge
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let fit_quality = (bin_residual - item_size) as f64 / cap;
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let open_bonus = (open_bins_count as f64) * 3.0;
        score = 100.0 + fit_quality * 20.0 - desperation * 60.0 - open_bonus * (1.0 - progress) - 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with non-linear shaping of dead space
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth progress coupling: later in stream, penalize large residuals more
    score += pr * progress * (x * (1.0 - x)) * 2.0;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= (1.0 - x).powi(3) * (10.0 + 20.0 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.25 * (1.0 - progress);
    }

    // Slight penalty when bin residual deviates from mean residual (balance)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 3.0;

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction bands.
    // Residuals in (50,100] can still host medium items; (0,50] risk dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let half = cap / 2.0;
    let quarter = cap / 4.0;

    // Penalize residuals in the awkward (0, quarter] zone — near-dead space.
    if pr > 0.0 && pr <= quarter {
        score += 12.0 * (quarter - pr) / quarter;
    }
    // Reward residuals just above half (still versatile).
    if pr > half {
        score -= 6.0;
    }

    // Perfect or near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item can fit into post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how much it misses.
        let miss = (next_item_size as u32 - post_residual) as f64;
        score += 0.15 * miss.min(30.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 35.0;
        // Late in the stream, avoid opening bins (little time to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // If many bins are open with slack, discourage new bin.
        score += 2.0 * open_bins_count as f64;
        // If mean residual is large, open bins have room; discourage new bin.
        score += (mean_residual / cap).max(0.0) * 20.0;
        // If next item is large, a fresh bin is more attractive.
        score -= 0.2 * next_item_size as f64;
        // If no bin currently fits (this item forces a new bin anyway), make it cheap.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Harmonic modulo class: prefer post_residual divisible by common item classes
    // (multiples of 10 are reusable by typical item sizes).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage opening new bins
    // when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins,
        // but relax when item is large and current residuals are fragmented.
        score += 30.0 + open_pressure;
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    } else {
        // Slight bonus for keeping items in existing bins as stream matures.
        score -= open_pressure * 0.1;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here: penalize leaving a gap smaller than next item.
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight packing).
    score += (bin_residual as f64 - item_size as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Next item fits exactly-ish in the leftover: strong reward.
            let match_quality = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 8.0 * match_quality;
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally.
            score += 0.35 * (post_residual as f64 / bin_capacity as f64) * nxt / bin_capacity as f64;
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 4.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "precious" —
    // using them well is rewarded, wasting them is penalized.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 3.0 * (1.0 - res_f / mean_residual.max(1.0));
    } else {
        score += 1.5 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: make opening a new bin unattractive unless the item
    // truly cannot fit well anywhere (post_residual is naturally 100 - item_size
    // for a fresh bin, which is large, so add a mild penalty on top).
    if bin_residual == bin_capacity {
        score += 12.0;
        // Exception: early in the stream or when no bins fit, opening is fine.
        if fitting_bins_count == 0 || open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by the base term,
    // but amplify it non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large unusable dead space: if post_residual is small but nonzero,
    // it may become waste. Mild penalty for very small leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chaining future fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward for exact chain fit.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: potential dead space penalty,
        // scaled by how close it is to being useless.
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += 4.0 * waste;
    }

    // Global state: penalize placements that leave residual far from the
    // mean residual of open bins when open_bins_count is large (fragmentation control).
    if open_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (spread items); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening new bins late in the stream,
        // and when many bins are already open.
        score += 30.0 * progress + 2.0 * (open_bins_count as f64);
        // Allow new bin early if item is large and would leave awkward residual elsewhere.
        if item_size >= 50 && progress < 0.3 {
            score -= 15.0;
        }
    } else {
        // Existing-bin bonus grows with stream progress.
        score -= 5.0 * progress;
    }

    // Reward filling large items into bins with just-enough residual.
    let exact_gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.02 * exact_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: prefer small post residual (tight fit).
    let mut score = post;

    // Smooth polynomial coupling of tightness with stream progress.
    let tightness = 1.0 - post / cap; // 1 = perfect fill
    score -= 45.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize residual relative to mean residual across open bins:
    // leaving more than the mean wastes shared space.
    let excess = (post - mean_residual).max(0.0);
    score += 0.35 * excess * (1.0 + progress);

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize if it nearly fits (creating a dead gap).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (nxt / (post + 1.0)) * (1.0 - progress * 0.5);
        } else {
            let gap = nxt - post;
            score += 0.25 * gap * gap / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - post / cap) + 10.0 * progress;
    }

    // Many open bins: discourage spreading; few open bins: encourage reuse.
    let bin_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 2.0 * bin_pressure * (post / cap);

    // New-bin candidate: mild penalty so it is chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 + progress) - 8.0 * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" space classes.
    let residue_class = post_residual % 10;
    // Dead-space penalty: residuals that no future item (min size 1, but typically >=10)
    // can use are heavily penalized. Class 0 residuals are perfect; small nonzero
    // residues (<10) are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if residue_class == 0 {
        score -= 12.0; // perfectly aligned residual, reusable by decile-sized items
    } else if residue_class >= 5 {
        score -= 3.0; // half-decile class still reasonably reusable
    } else {
        score += 4.0; // awkward small residue class
    }

    // Integer-division thresholds on post_residual: how many "typical" items fit.
    let slots = post_residual / 20;
    score -= slots as f64 * 5.0;

    // Next-item lookahead: harmonic coupling between post_residual and next_item_size.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect or near-perfect lookahead fit is very desirable.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0;
            } else if gap < 10 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
            // Modulo harmony: next item leaves a clean class too.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here regardless; slight penalty for tight residual.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin would waste a lot
    // or the item is large relative to residual (poor fit).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        // A fresh bin is good for big items (they define the bin's class).
        score = (bin_capacity - item_size) as f64;
        if fill_frac > 0.7 {
            score -= 20.0;
        }
        if post_residual < 10 {
            score -= 10.0; // near-perfect packing of a fresh bin
        }
        // Late in stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0 + open_bins_count as f64 * 2.0;
    } else {
        // Prefer filling bins that are already substantially loaded (best-fit bias).
        let used_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= used_frac * 10.0;
        // If this bin's residual is far from mean residual, slight penalty (outlier bin).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Item-size harmonic class: large items should go into tight bins, small items
    // into loose bins; reward agreement via decile classes of item_size.
    let item_class = item_size / 10;
    let residual_class = bin_residual / 10;
    if item_class >= residual_class {
        score -= 2.0; // big item into relatively tight bin: good
    } else {
        score += 1.5; // small item into loose bin: wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits (small waste relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.3;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fills (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose residual after placement
    // can be exactly consumed by the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover slack after hypothetically serving the next item.
            score += slack * 0.8;
            // Bonus if the next item still fits with small slack (tight chain).
            if slack <= 10.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit in this bin after placement: mild penalty,
            // scaled by how much space would be wasted.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Compare against mean residual across open bins: prefer bins that are
    // tighter than average (concentrate filling), avoid spreading.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit. Penalize the fresh bin mildly so it is
    // chosen only when all open bins score poorly.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Late in the stream, slightly more willing to open new bins to keep
        // residuals clean for remaining items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 50.0;
    }

    // Mild reward for using bins with large existing commitment (fewer
    // partially-filled bins left dangling).
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // Early stream: encourage packing tightly to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Lookahead: reward if the next item can fit into post_residual (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating dead space that the next item cannot use.
        let dead = post_residual as f64;
        score += 0.35 * dead * dead / 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin offers a decent fit, or the stream is early and mean
    // residual is high (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 150.0;                       // base cost of opening a new bin
        score -= 90.0 * (1.0 - progress);     // cheaper to open bins early
        score -= 0.5 * open_bins_count as f64; // slight economy of consolidation
        if fragmentation > 40.0 {
            score -= 40.0;                    // open bins are fragmented anyway
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 50.0;                    // next item won't fit here either
        }
    }

    // Mild penalty for wasting a very large bin residual on a small item
    // when other bins could take this item.
    if bin_residual > item_size + 50 && fitting_bins_count > 2 {
        score += 25.0;
    }

    // Time-horizon modulation: late in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Coupling with global mean residual: prefer bins whose post-residual
    // lands near the mean (keeps residual distribution uniform and usable).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.8 * pr_norm + 0.6 * pr_norm * pr_norm);

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, larger dead space becomes increasingly costly
    score += 20.0 * pr_norm * pr_norm * (progress * progress * (3.0 - 2.0 * progress));

    // Reward tight fits (small post_residual) more strongly as progress grows
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * tightness * (0.5 + progress);

    // Last-chance bin bonus: strongly favor using a unique fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // penalize bins that waste the next item's potential
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins vs. consolidating
    score += 0.5 * open_bins_count as f64 * pr_norm;

    // Mean residual deviation: prefer bins near mean to keep balance, smooth term
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when residual is poor
    if bin_residual == bin_capacity {
        // opening a new bin costs ~cap of unused space elsewhere; neutral baseline
        score = cap as f64 * (1.0 + 0.5 * progress) - 3.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size as f64 >= cap * 0.5 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: classify by capacity fractions.
    let post = post_residual as f64;
    let frac = post / cap;

    // Penalize residuals that fall into "dead" harmonic classes:
    // (0, 10) is nearly unusable for items >= 10; (10..25) only fits small items.
    if post_residual < 10 {
        score -= 40.0; // perfect fill
    } else if post_residual < 25 {
        score += 12.0; // awkward small pocket
    } else if post_residual < 50 {
        score += 4.0;
    } else {
        score += 0.0;
    }

    // Modulo arithmetic on residual: residuals congruent to typical item sizes
    // (multiples of 5/10) are more likely to be exactly filled later.
    let r = post_residual % 10;
    score += (r as f64) * 0.8;

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Prefer leaving room the next item can partially use.
            let slack = (post_residual - next_item_size) % 10;
            score += slack as f64 * 0.5;
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals
    // are fragmented (high mean residual spread) or this is a poor fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin; discounted early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 - progress * 10.0;
        // If many bins fit the item, opening new is wasteful.
        score += fitting_bins_count as f64 * 6.0;
        // If mean residual is small (bins are tight), opening new bin is fine.
        score -= (mean_residual / cap) * 20.0;
        // Lookahead synergy: empty bin can host both item and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tight = (bin_residual - item_size) as f64;
        score = score * 0.6 + tight * 0.4;
        // Slight preference for bins already below mean residual (consolidation).
        score += ((bin_residual as f64 - mean_residual) / cap) * 5.0;
    }

    // Late-stream tightening: prefer exact fills as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - frac) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Gaps that can only fit tiny items are semi-dead space.
    else if post_residual <= 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits: post_residual close to zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    }

    // Exact-fit lookahead: if the next item fits exactly into the post gap,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 55.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0; // leaves near-zero residual after next placement
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use this gap: mild penalty proportional to gap waste
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new one is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it only when the
        // item is large relative to typical residuals or few bins are open.
        score = 95.0 + bin_pressure - (item_size as f64 * 0.4);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big pair coming: fresh bin may pay off
        }
    } else {
        // Mild bonus for placing into bins whose residual is below average
        // (consolidating waste into fewer bins).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
        score += bin_pressure * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect chain: item + next item fills bin completely
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
    }

    // Prefer tight fits: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare against mean residual: bins below mean residual are already tight,
    // filling them further is efficient; bins far above mean residual waste space.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score -= 10.0 * dev;
    } else {
        // Brand-new bin candidate: only attractive when no open bin fits well
        // or the item is large enough that a fresh bin is sensible.
        if fitting_bins_count == 0 || item_size > bin_capacity / 2 {
            score -= 20.0;
        } else {
            score += 35.0 + (open_bins_count as f64) * 0.5;
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 12.0 * progress;
    }

    // Slight preference for bins whose residual is a multiple-friendly target
    // for typical small items (5..=20 range granularity).
    if post_residual >= 5 && post_residual <= 30 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize large dead space (post_residual) nonlinearly if it can't fit typical items.
    if post_residual < 10 {
        score += 500.0; // unusable dead space
    } else {
        let usable = (post_residual as f64 / 10.0).floor();
        score += (10.0 - usable) * 4.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins: normalize fill ratio.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 20.0;

    // Time horizon: early in stream, encourage opening new bins less (prefer existing bins);
    // late in stream, be more tolerant of new bins since fewer items remain.
    let t = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize early, discount late
        score += 25.0 * (1.0 - t) + open_bins_count as f64 * 2.0;
        // but if no open bin fits well, allow it
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if mean_residual > 20.0 && open_bins_count > 2 {
        score += mean_residual * 0.1;
    }

    // Small tie-breaker against very loose fits.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space (dead space grows quadratically in cost)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: later in the stream, tight fits matter more
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fits smoothly (small post_residual exponentially favored)
    score -= 60.0 * (-norm_pr * 12.0).exp();

    // Penalize bins whose residual deviates from the mean residual (keeps diversity of sizes)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if next item fits the post residual exactly, reward; if post residual
    // is too small for next item, mild penalty (dead space for the lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 20.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (1.0 - pr / cap);
        }
    }

    // Mild preference for consolidating into existing bins vs opening new ones
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: empty bin gets a neutral-ish score; only beat existing bins
    // when the fit there would be poor (high post_residual relative to capacity)
    if bin_residual == bin_capacity {
        score = pr + 25.0 * norm_pr * cap + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quanta of usable dead space.
    // Residuals in [1..10] are near-unusable; [11..30] fit small items; [31..60] mid; >60 healthy.
    let pr = post_residual as u32;
    let quantum = (pr / 10) as f64; // integer-division class 0..=10
    score -= quantum * 2.0;

    // Penalize tiny dead space harshly (nonlinear).
    if pr > 0 && pr < 10 {
        score += 25.0 * (10.0 - pr as f64) / 10.0;
    }
    if pr == 0 {
        score -= 40.0; // perfect closure is excellent
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 20.0 + (pr - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 {
        // next item cannot use this residual: penalize proportionally to wasted class
        score += (next_item_size.min(pr + next_item_size)) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Tightness reward: item filling most of the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 15.0;

    // New-bin candidate: only attractive when no open bin is a good fit
    // (large residual waste elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        let waste = mean_residual - (cap - mean_residual).abs();
        score = cap * 0.55 + open_pressure * 2.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        }
        if mean_residual > 45.0 {
            score += 15.0; // plenty of room already open; discourage new bin
        }
        let _ = waste;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item is dead space.
    if post_residual > 0 {
        let dead_threshold = 12.0f64.min(next_item_size.max(1.0) as f64);
        if (post_residual as f64) < dead_threshold {
            score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
        // Waste ratio penalty: quadratic in fill tightness
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 25.0 * tightness * tightness;
    } else {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 2.5 * open_bins_count as f64;

    // Mean residual coupling: prefer bins near the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: neutral-ish baseline, penalize slightly so it only
    // wins when open bins would create severe dead space
    if bin_residual == bin_capacity {
        score = 45.0 + 2.5 * open_bins_count as f64;
        // Late in stream, be more reluctant to open new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Match quality: tighter the leftover after the pair, the better
            let pair_leftover = (post_residual - next_item_size) as f64;
            score -= 60.0 - pair_leftover * 0.4;
        } else {
            // Penalize dead space the next item cannot use
            score += post_residual as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize new-bin candidate unless it's genuinely needed
    if bin_residual == bin_capacity {
        score += 200.0;
        // Late in stream, opening new bins is fine
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score -= 100.0;
        }
        // If many open bins, discourage spreading
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) with a non-linear bonus.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item (likely wasted).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving exactly enough room for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: mild penalty for consuming a flexible bin.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global balance: prefer bins whose residual deviates favorably from mean residual.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, encourage spreading load (new bins OK);
    // late in the stream, consolidate into existing bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more heavily as stream progresses.
        score += 6.0 + 18.0 * t;
        // Early stream with many open bins: opening new bins is fine.
        if t < 0.3 && open_bins_count > 4 {
            score -= 4.0;
        }
        // New bin is attractive if item is large and no tight fit exists.
        if (item_size as f64) > 0.7 * cap && fitting_bins_count <= 1 {
            score -= 10.0;
        }
    } else {
        // Late stream: consolidation bonus.
        score -= 10.0 * t;
    }

    // Small structural bonus for bins that keep residual in "usable" ranges
    // (multiples likely to fit common item sizes).
    let usable = (post_residual >= 10 && post_residual <= 50) || post_residual == 0;
    if usable {
        score -= 3.0;
    } else if post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth stream-progress coupling: late in stream, tighten more aggressively
    score *= 1.0 + 0.5 * progress * norm_post;

    // Penalize waste relative to mean residual of open bins (smooth quadratic coupling)
    let waste_gap = post - mean_residual;
    score += 0.15 * waste_gap.abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 0.35 * cap * (1.0 - 0.3 * progress);
    }

    // Lookahead: reward leaving residual that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 0.25 * nx * (0.5 + 0.5 * progress);
        } else {
            // smooth penalty for creating dead space unusable by next item
            score += 0.2 * (nx - post) * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.10 * cap * (1.0 + progress) + 0.05 * open_bins_count as f64;
    }

    // Penalty when many bins can fit: avoid burning scarce-fit bins unnecessarily
    if fitting_bins_count > 1 {
        score += 0.02 * (fitting_bins_count as f64 - 1.0) * post;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual falls into
    // "small" residue classes are more valuable (tight fit), reward them.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = post / cap;

    // Class thresholds via integer division on post_residual (harmonic buckets of 10).
    let bucket = post_residual / 10;
    match bucket {
        0 => score -= 30.0,                 // near-perfect fit (0..10 dead space)
        1 => score -= 18.0,                 // excellent
        2 => score -= 10.0,                 // good
        3 => score -= 4.0,                  // decent
        4 => score -= 0.0,                  // neutral
        5 => score += 3.0,                  // half-full leftover
        6 => score += 6.0,
        7 => score += 9.0,
        _ => score += 12.0,                 // large dead space
    }

    // Dead space that no future item (>=1, typically >=10) can use is wasted:
    // penalize leftovers smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Coupling with next item: if the next item fits exactly in post_residual,
    // strongly reward this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well the next item nests
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item cannot fit here; slightly penalize large leftovers
            score += 2.0 * frac;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        // but if it would leave a huge unusable remainder, soften the reward
        if post_residual > 50 {
            score += 10.0;
        }
    }

    // Many open bins: prefer consolidating into existing bins (penalize new-bin
    // tendency) by rewarding bins that are already partially filled.
    let fill = 1.0 - frac;
    score -= 5.0 * fill * (open_bins_count.min(20) as f64 / 20.0);

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it is a "tight" bin), favor filling it further.
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= 3.0 * (dev / cap).min(1.0);
    } else {
        score += 1.5 * ((-dev) / cap).min(1.0);
    }

    // Early in the stream, be more willing to spread items (reward larger
    // post_residual slightly); late in the stream, pack tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * frac * (1.0 - progress);
    score -= 4.0 * frac * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced when many bins are open
        // and current fits are poor.
        let mut new_bin_cost = 20.0;
        if fitting_bins_count == 0 {
            new_bin_cost = -50.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            new_bin_cost = 35.0; // only one fitting bin: keep it cheap-ish
        }
        if open_bins_count == 0 {
            new_bin_cost = -100.0;
        }
        score = new_bin_cost + 0.5 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 {
        // Smallest plausible item is 1; treat gaps < ~10 as near-dead.
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            score += 15.0 * (25.0 - post_residual as f64) / 15.0;
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins whose post_residual can still host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins with residual near the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item (perfect chain), penalize near-miss residuals.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 60.0; // next item fits perfectly afterwards
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64));
        } else {
            // dead space: next item cannot use this residual
            score += 0.35 * post_residual as f64;
        }
    }

    // Prefer tight fits relative to mean residual across open bins
    let cap = bin_capacity as f64;
    let tightness = (post_residual as f64) / cap;
    score += 20.0 * tightness * tightness;

    // Penalize bins that are far from the mean residual (outliers create fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        if fitting_bins_count <= 1 {
            score -= 10.0;
        } else {
            score += 30.0;
        }
    }

    // Slight preference for compacting many bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // next item won't fit here; small penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (item_size as f64 / bin_capacity as f64) > 0.85;
        if poor_fit || open_bins_count == 0 {
            score -= 35.0;
        } else {
            // discourage opening new bins mid-stream when fits exist
            score += 15.0 + 20.0 * (1.0 - progress);
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing ones.
    if mean_residual > (item_size as f64) * 1.5 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Mild time-horizon modulation: late in stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer low post residual, with smooth non-linear shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm
        - 30.0 * pr_norm * pr_norm * pr_norm;

    // Stream progress coupling: later in stream, penalize wasted space more strongly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Dead-space penalty: residual too small to be useful (below typical min item)
    let dead = ((10.0 - pr) / 10.0).max(0.0);
    score += 25.0 * dead * dead;

    // Lookahead: reward bins whose post residual can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 20.0 * (nxt / cap) * (1.0 - pr_norm);
        } else {
            score += 8.0 * (nxt / cap);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild penalty when many bins are open and this one is nearly empty (fragmentation)
    let frag = (pr_norm - mean_residual / cap.max(1.0)).abs();
    score += 5.0 * frag * frag * (open_bins_count as f64).sqrt();

    // New-bin candidate: make empty bin moderately attractive only when current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets by capacity fraction (eighths).
    let eighth = bin_capacity / 8;
    let class = (post_residual / eighth) as f64;

    // Reward small post_residual, but reward "harmonic" residuals (0, half, full-ish) more.
    let harmonic = if post_residual == 0 { 2.0 }
        else if post_residual == bin_capacity / 2 { 1.5 }
        else if post_residual % 10 == 0 { 1.2 }
        else { 1.0 };
    score -= 18.0 * harmonic;

    // Penalize dead space: residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; leftover becomes dead space
            score += class * 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad residue.
    if bin_residual == bin_capacity {
        let bad = fitting_bins_count <= 1
            || (post_residual > 0 && post_residual < 10)
            || (next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity);
        score = if bad { -5.0 } else { 40.0 };
    }

    // Mild pressure toward consolidating many open bins.
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold on post_residual: very tight fits get extra reward.
    if post_residual / 5 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: gaps of 1..=10 are nearly unusable for future items.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }
    // Medium gaps (11..=25) are moderately risky.
    if post_residual > 10 && post_residual <= 25 {
        score += 8.0 * (26.0 - post_residual as f64) / 15.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; with few, consolidation is fine.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item cannot fit here: penalize leaving residual it might have used.
            score += 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or nothing fits well; otherwise keep open bins tight.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted late in the stream is not needed;
        // keep a moderate constant so tight fits in open bins win.
        score += 30.0;
        if open_bins_count > 0 && post_residual == 0 {
            score -= 20.0; // fresh bin for exact-fit item is fine
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chaining with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;

        // Perfect fit for the next item: chain two items cleanly.
        if (post_residual as u32) == next_item_size {
            score -= 60.0;
        } else if post_residual as u32 > next_item_size {
            // Next item still fits afterwards: mild reward proportional to tightness.
            let tight = nxt / pr;
            score -= 10.0 * tight;
        } else {
            // Next item won't fit: penalize dead space, worse when the gap is small.
            let gap = pr - nxt;
            score += 8.0 + 0.5 * gap;
        }

        // If this placement leaves room for roughly half of the next item too
        // (potential third-item chain), give a small nudge.
        if post_residual as u32 >= 2 * next_item_size && next_item_size <= 25 {
            score -= 5.0;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual stays near the mean
    // (balanced packing), penalize extreme outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10 can never hold an item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive early, unattractive late,
    // and unattractive when existing bins are already plentiful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 - 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.3 * (post_residual as f64 - next_item_size as f64).abs();
        } else {
            // Reward leaving room exactly usable by the next item.
            let gap = post_residual - next_item_size;
            score -= 6.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mildly discourage spreading across many open bins when residuals are high.
    if open_bins_count > 1 {
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    // Early in the stream, be more willing to open fresh bins (long horizon amortizes them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows over time (prefer reuse later).
        score += 10.0 + 20.0 * progress;
        // Opening a bin is attractive if the item is large and no open bin fits well.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        // Existing-bin reuse bonus, stronger late in the stream.
        score -= 2.0 + 6.0 * progress;
    }

    // Prefer placing large items into bins with modest residual (avoid wasting big gaps).
    let frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = x * x * (1.0 - x) * 4.0; // smooth bump peaking mid-residual
    let mut score = pr - 24.0 * base * (1.0 - progress);

    // Penalize large residuals more as stream advances (less time to fill them)
    let late_penalty = x * x * progress * 30.0;
    score += late_penalty;

    // Reward tight fits (small post residual) especially when lookahead matches
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let match_bonus = 1.0 - ((next_item_size as f64) - pr).abs() / cap;
        score -= 8.0 * match_bonus * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        score += 5.0; // lookahead can't use leftover space
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Mild pressure toward consolidating residuals near the mean
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: keep it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64).sqrt();
    } else {
        score -= 50.0; // perfect fill
    }

    // Harmonic classes: classify post_residual into capacity-fraction buckets
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    if post == 0 {
        // dead bin, ideal
    } else if post < 10 {
        score -= 20.0; // nearly full, tiny dead space
    } else if post <= quarter {
        // small residual: usable only by tiny future items; mild penalty
        score += 8.0;
    } else if post <= half {
        // mid residual: good for medium items; check lookahead compatibility
        if next_item_size > 0 && next_item_size <= post {
            score -= 15.0; // next item fits here nicely
        } else if next_item_size > 0 {
            score += 10.0; // next item won't fit: stranded capacity
        }
        // modulo-10 class bonus: residuals divisible by 10 align with item grid
        if post % 10 == 0 {
            score -= 6.0;
        }
    } else if post <= 3 * quarter {
        score += 4.0;
        if next_item_size > 0 && next_item_size <= post {
            score -= 10.0;
        }
    } else {
        // large residual left: wasteful placement of a small item in big bin
        score += 15.0;
    }

    // Penalize wasting a mostly-empty bin when many bins are open
    if post > half && bin_residual < bin_capacity {
        score += (post - half) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open new bin if current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.6;
        if next_item_size > 0 && next_item_size >= item_size.min(bin_capacity / 2) {
            // pair large items together in fresh bins
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference to balance residuals toward mean
    score += (post as f64 - mean_residual).abs() * 0.05;

    // More open bins -> prefer filling existing ones rather than spreading
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: post_residual in small unusable gaps is very costly.
    // A gap is "dead" if it is too small to fit even the smallest plausible item.
    let dead_threshold = 9.0f64.min(next_item_size as f64);
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // heavy penalty for creating unusable sliver
    } else if post_residual == 0 {
        score -= 60.0; // perfect fit is best possible outcome
    } else {
        // penalize large leftover less if it can host the lookahead item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > 0 {
            score += 10.0; // leftover can't host next item -> mild dead space risk
        }
    }

    // Reward tight fits: closeness of post_residual to zero (when usable)
    score += (post_residual as f64) * 0.15;

    // Open bins pressure: discourage spreading across many bins when few are open
    if fitting_bins_count == 1 {
        // last chance bin: strongly favor using it over opening a new bin
        score -= 25.0;
    } else if open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 2.0;
    }

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (keeps bin residuals balanced, avoiding many near-empty bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early in stream, be conservative (favor new bins to build good structure);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0; // slight default penalty; open new bin only if fits are bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits: small post_residual is already the base.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item too big for the leftover: penalize creating dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead.min(80.0);
        }
    }

    // Relative-to-mean coupling: bins with residual below mean are scarcer; using them well is good.
    let resid = post_residual as f64;
    score += 0.3 * (resid - mean_residual).max(-50.0);

    // Last-chance bin: if this is the only fitting bin, avoid wasting it on a bad fit,
    // but strongly prefer it over opening a new bin for a good fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual {
            score -= 150.0;
        } else {
            score -= 30.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits tightly.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (post_residual as f64) < mean_residual;
        if tight_exists {
            score += 300.0; // discourage opening a new bin when a tight fit exists
        } else {
            score += 50.0; // mild default penalty; new bins cost capacity
        }
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
    }

    // Fragmentation penalty scaled by how much space is wasted relative to item size.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit bias with mild nonlinearity on post residual.
    score += (post_residual as f64).powf(1.15) * 0.02;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty: small post-residuals that can't fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Time horizon: early in stream, be conservative (prefer tight fills);
    // late in stream, consolidate into open bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let new_bin_base = 40.0 + 0.5 * (open_bins_count as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score += new_bin_base - 20.0;
        } else {
            score += new_bin_base;
        }
        if fitting_bins_count > 2 {
            score += 60.0; // plenty of alternatives, avoid opening bins
        }
    }

    // Fragmentation risk: penalize bins whose residual barely exceeds item.
    let slack = bin_residual.saturating_sub(item_size);
    if slack > 0 && slack < 15 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let prn = pr / cap; // normalized residual (0..1)
    let poly = prn * prn * (1.0 + t) + prn * (1.0 - t) * (1.0 - t);
    score += 0.6 * poly * cap;

    // Penalize wasted space more as the stream progresses (bins get locked in).
    score += 0.35 * prn * prn * prn * cap * (0.5 + t);

    // Reward tight fits: small post_residual relative to capacity.
    score -= 0.5 * (1.0 - prn) * (1.0 - prn) * (1.0 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * t;
    }

    // Lookahead: reward if next item fits into the resulting residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * (1.0 - slack);
    } else if next_item_size > post_residual {
        score += 1.5 * prn * (0.5 + t);
    }

    // Prefer denser bins (small mean residual) slightly.
    score += 0.2 * (mean_residual / cap - prn).abs() * cap;

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common item
    // sizes (10, 20, 25, 50) are more reusable, reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit is always best
    } else {
        let residue_class_bonus = match pr % 10 {
            0 => 12.0,
            5 => 6.0,
            _ => 0.0,
        };
        score -= residue_class_bonus;
        // Integer-division thresholds: small dead space (< 10) is nearly unusable
        if pr / 10 == 0 {
            score += 25.0;
        } else if pr / 25 > 0 {
            score -= 8.0; // can still host a medium item
        }
        // Reward residuals that match the lookahead item exactly (harmonic coupling)
        if next_item_size > 0 && pr == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && pr > next_item_size && pr - next_item_size < 10 {
            score += 10.0; // would leave unusable sliver for the next item
        }
    }

    // Last-chance bin: strong bonus to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits
    // poorly everywhere (large item, tight stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 1.5;
        score += 15.0
            - 10.0 * progress
            - if tight { 20.0 } else { 0.0 }
            - (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Slight preference for fuller bins (small residual fraction)
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    // Open-bin pressure: with many open bins, prefer consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, reward below instead
    }

    // Base: prefer minimal post_residual (tight fit).
    score = post_residual as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize "unusable" small gaps: residual that few future items could use.
    let gap_uselessness = if post_residual > 0 && post_residual < 10 {
        (10 - post_residual) as f64 * 8.0
    } else if post_residual < 20 {
        (20 - post_residual) as f64 * 3.0
    } else {
        0.0
    };
    score += gap_uselessness;

    // If the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= (30.0 - slack.min(30) as f64) * 2.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; slight penalty proportional to wasted potential
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins give bad fits.
    if bin_residual == bin_capacity {
        // mild default preference against opening new bins
        score += 25.0;
        // but if many open bins exist and mean residual is small (fragmented),
        // opening fresh is more attractive
        score -= open_bins_count as f64 * 1.5;
        score += (mean_residual - 50.0).max(0.0) * 0.5;
    } else {
        // open-bin pressure: discourage spreading across too many bins when residual is high
        score += open_bins_count as f64 * 0.3;
        // reward using bins whose residual is close to mean (balance)
        score += ((bin_residual as f64 - mean_residual).abs()) * 0.2;
    }

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: eliminate dead space aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that cannot fit typical items.
        if post_residual < 10 {
            score += 50.0;
        }
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chain packing).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - next).abs();
        if diff < 1.0 {
            score -= 400.0;
        } else if diff <= 10.0 {
            score -= 200.0 * (1.0 - diff / 10.0);
        } else {
            // Post-residual too large or too small for next item:
            // slightly penalize leaving a gap that mismatches lookahead.
            score += diff * 0.5;
        }
        // If next item cannot fit anywhere else and this bin can host it after,
        // strong reward.
        if next <= post_residual && fitting_bins_count <= 2 {
            score -= 150.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    // (keeps large residual bins free for big items).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.3;
    }

    // Prefer filling bins with small residual relative to capacity
    // (tight packing first).
    score -= (bin_capacity as f64 - res) * 0.2;

    // Early in the stream, be slightly more willing to open new bins
    // (spread items); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New bin candidate: penalize moderately, less as stream progresses.
        score += 80.0 - 60.0 * progress;
        // But if no open bin fits well, allow new bin.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, use it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins among many open bins (mild pressure to close bins).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global state: if mean residual is high, be pickier about creating new
    // small residuals; if low, more tolerant.
    let mean_ratio = mean_residual / bin_capacity as f64;
    score += 6.0 * mean_ratio * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when the item
    // is large (poor fit elsewhere likely) or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened frivolously.
        score += 20.0;
        // Large items benefit from a fresh bin.
        let item_ratio = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * item_ratio * item_ratio;
        // If many bins fit the item, discourage the new bin further.
        if fitting_bins_count > 1 {
            score += 10.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Time-horizon term: early in the stream, allow slightly worse fits to
    // keep bins flexible; late, demand tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual scaled by a smooth progress-dependent convexity factor.
    let convexity = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let mut score = pr * convexity;

    // Non-linear penalty for dead space: residual that is too small to hold
    // even a typical item (below min item size 1 is impossible, but small
    // residuals relative to capacity are wasted). Smooth quadratic coupling.
    let rel_dead = pr / cap;
    score += 12.0 * (1.0 - rel_dead) * (1.0 - rel_dead) * rel_dead;

    // Tight fits are desirable: subtract reward proportional to fill fraction
    // with a smooth saturating term.
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill * (2.0 - fill);

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin; penalize if next item barely misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 15.0 * snug * snug;
        } else {
            let miss = (nxt - pr) / cap;
            score += 10.0 * miss * miss;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: neutral baseline, slightly discouraged early,
    // encouraged late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        score = cap as f64 * (0.6 + 0.4 * progress) - 10.0 * fragmentation * progress;
    } else {
        // Mild preference to consolidate into bins below mean residual
        // (fills emptier bins first, keeping tight bins for small items).
        score += 3.0 * (pr - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands (dead space vs. reusable space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional class of post_residual: 0 = tiny leftover (good), large = bad.
    let frac = pr / cap;
    if frac < 0.10 {
        score -= 12.0; // near-perfect packing, tiny dead space
    } else if frac < 0.25 {
        score -= 3.0;
    } else if frac < 0.50 {
        score += 4.0;
    } else {
        score += 10.0; // half-empty bin left behind: wasteful
    }

    // Harmonic pairing: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            // Reward chains where the lookahead also fits: harmonic resonance.
            let chain = (pr / next_item_size as f64).floor(); // integer division threshold
            score -= 6.0 + 2.0 * chain.min(3.0);
            // Extra reward when next item exactly fills the bin (mod-style exact fit)
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Lookahead won't fit here: penalize slightly more for big dead gaps.
            score += 3.0 + 4.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin
    // offers a decent fit; otherwise keep open bins preferred.
    if bin_residual == bin_capacity {
        // Empty bin starts with score = capacity + penalties above.
        // Reward it when existing bins are crowded (low mean residual).
        score -= 8.0 * (1.0 - mean_residual / cap).max(0.0);
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Tie-break: prefer bins with residual close to item (tight fits),
    // using an integer-division harmonic class on bin_residual.
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * tight;

    // Modulo-style bonus: post_residual in {0, 5, 10} are classic clean classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual == 0 {
        score -= 10.0; // perfect fill
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps nonlinearly.
    // A residual that cannot fit even the smallest plausible item (<= ~10)
    // is pure waste; weight it heavily.
    let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else { 0.0 };
    score += dead * (post_residual as f64) * 3.0;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Penalize leaving a residual that is larger than needed but still small
    // relative to typical item sizes (awkward gap zone).
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 1.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score = bin_capacity as f64 - fill_ratio * 40.0 + 25.0 + open_bins_count as f64 * 4.0;
        // Late in the stream, new bins are even less desirable.
        score += progress * 30.0;
        // If the next item could use the leftover of an existing bin instead,
        // slightly favor existing bins.
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score += 10.0;
        }
    } else {
        // Existing bin: mild reward when many bins already open.
        score -= (open_bins_count as f64).sqrt() * 2.0;
        // Lookahead: if the post residual exactly fits the next item, big bonus.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Prefer bins whose residual is below the current mean (consolidating
        // near-full bins, keeping large residuals in other bins).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    if next_item_size > 0 {
        // Perfect 2-step match: bin residual after this item exactly fits next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item fits in the post residual: strong reward, scaled by how snug.
        else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 - slack.min(45.0);
        }
        // Next item would not fit here: mild penalty if we leave a small dead zone,
        // larger penalty if we leave a large unusable gap.
        else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Reward leaving residuals near the mean (keeps bin portfolio balanced),
    // penalize outliers relative to current mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Late in the stream: consolidate harder, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 12.0;
    }

    // Many open bins: discourage spreading; favor tight placements more.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is very tight
    // or nothing else reasonably fits (handled via fitting_bins_count comparisons).
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if next item is huge and would pair perfectly, soften the penalty.
        if next_item_size > 0 && (bin_capacity - next_item_size) as i64 - (item_size as i64) >= 0 {
            score -= 20.0;
        }
    }

    // Exact-fill bonus: using the bin completely is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 8.0;

    // Penalize dead space that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual - next_item_size;
        score -= 12.0 - (chain as f64) * 0.15;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0; // next item won't chain here
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless all fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = (bin_capacity - item_size) as f64; // waste of fresh bin
        score += open_bins_count as f64 * 0.5;
        // Late in stream, prefer compacting into existing bins
        score += (1.0 - progress) * 2.0;
        // If many bins fit the item, opening new bin is clearly worse
        score += fitting_bins_count as f64 * 4.0;
    }

    // Prefer bins whose residual is close to item (best-fit flavor)
    score += (bin_residual - item_size) as f64 * 0.05;

    // Global pressure: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 && mean_residual > item_size as f64 * 1.5 {
        score -= 2.0;
    }

    // Mild time-horizon modulation: early stream, be greedy about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover residual, mildly
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tight = (norm_pr - 0.5) * (norm_pr - 0.5); // 0 when half-full leftover
    let progress_weight = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 60.0 * tight * (0.5 + progress_weight);

    // Reward filling bins nearly exactly: quadratic bonus decaying with residual
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + progress);

    // Lookahead: penalize if post_residual cannot fit next item (dead space risk)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 25.0 * (ni - pr) / cap * (0.5 + progress);
        } else {
            // reward leaving exactly enough room for next item
            score -= 15.0 * (1.0 - (pr - ni) / cap) * (1.0 - (pr - ni) / cap) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0 * (1.0 - 0.5 * progress);
    }

    // Penalize spreading across many open bins; encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 4.0 * norm_pr;

    // Deviation from mean residual: prefer balanced residuals
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately attractive only when it's genuinely better
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
        // opening new bin is bad if other bins fit well
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near multiples of common item
    // sizes are more reusable. Class = post_residual mod 10.
    let class = post_residual % 10;
    let class_penalty: f64 = match class {
        0 => -6.0,           // perfectly reusable residual
        5 => -3.0,           // half-class, decent
        2 | 4 | 6 | 8 => -1.0,
        _ => 1.5,            // odd residues are dead-space prone
    };
    score += class_penalty;

    // Integer-division thresholds on post_residual: large residuals are fine,
    // tiny residuals are acceptable (bin nearly full), middle residuals waste.
    let q = post_residual / 10;
    if q >= 5 {
        score -= 2.0; // >= 50 residual: still very usable
    } else if q <= 1 {
        score -= 1.0; // <= 19: nearly sealed bin, good packing
    } else {
        score += 2.0; // 20..49: awkward middle zone
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            // harmonic compatibility: next_item mod 10 class matching residual
            let nclass = next_item_size % 10;
            if nclass == class {
                score -= 3.0;
            }
            // penalize leaving residual that next item cannot use well
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score += slack as f64 * 0.5; // tiny unusable remainder
            }
        }
    }

    // Last chance: this is the only bin that fits -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (this call has full residual == capacity).
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: its residual is maximal, so make it
        // competitive only when the stream is early or bins are scarce.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity as f64) * (1.0 - 0.15 * progress);
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Slight preference for tighter bins when many bins are open (consolidate).
    score += mean_residual * 0.05;
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are "dead" and cost extra.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0; // perfect fill, reward strongly
    } else {
        // dead-space penalty grows super-linearly as the gap becomes unusable
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += (10.0 - gap) * (10.0 - gap) * 2.0;
        }
    }

    // Reward tight fits: fraction of bin consumed by this item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 30.0;

    // Exact fill bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: strongly favor bins whose post_residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // extra reward for near-perfect chain fit
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain_gap / bin_capacity as f64) * 10.0;
        } else {
            // creating a gap that cannot host the next item: penalize
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; also make new bins less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost plus pressure; only attractive when
        // no open bin offers a decent fit
        score += 40.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
    } else {
        // existing bin: slight reward, stronger when it's the only fitting bin
        score -= pressure * 0.5;
        if fitting_bins_count == 1 {
            score -= 35.0; // last-chance bin before opening a new one
        }
    }

    // Prefer bins below mean residual (fill emptier bins first keeps tight bins flexible)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // exact match bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // post residual too small to ever fit anything (dead space) unless ~0
        if post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 20.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 15.0;
    }

    // Reward bins below mean residual (tighter bins get used first)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 15.0 * (1.0 - progress);
        // but if no open bin can fit, new bin is necessary; relax penalty
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild preference for very tight fits overall
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small leftover relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Penalize waste relative to the mean residual of open bins:
    // leaving much more space than average is bad packing.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    }
    // If next item cannot fit in post-residual but this bin could be closed out anyway,
    // mild bonus (dead space bounded).
    if next_item_size > post_residual && post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: opening a new bin wastes (capacity - item_size)
    // potential. Penalize unless the fit is excellent or no real alternative exists.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 120.0 + waste * 0.8;
        // Early in the stream, opening bins is cheap; later it's costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 150.0;
        // If many bins are already open, prefer consolidating into them.
        score += (open_bins_count as f64) * 5.0;
        // But if a perfect fit exists elsewhere, this penalty doesn't matter anyway.
        if post_residual == 0 {
            score -= 1000.0;
        }
    }

    // Slight preference for bins with larger residuals among equally tight fits
    // (drain fuller bins first).
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.8 * progress * progress);

    // Reward tight fits: penalize (subtract) when post_residual is small
    let tightness = -60.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space that can't fit next item (smooth interaction)
    let dead = if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        0.25 * gap * gap / cap
    } else {
        0.0
    };

    // Perfect fit reward
    let perfect = if post_residual == 0 { -80.0 } else { 0.0 };

    // Last-chance bonus: strongly prefer using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -30.0 * (1.0 - progress) } else { 0.0 };

    // Mild preference for bins with lower residual relative to mean
    let mean_pull = 0.3 * (pr - mean_residual);

    // New-bin candidate: penalize opening new bins unless residuals are large
    let new_bin_penalty = if bin_residual == bin_capacity {
        25.0 + 40.0 * progress + (open_bins_count as f64) * (item_size as f64 / cap)
    } else {
        0.0
    };

    base + tightness + dead + perfect + last_chance + mean_pull + new_bin_penalty
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity/8 buckets and reward residuals that stay "usable".
    let class = post_residual / (bin_capacity / 8).max(1);
    score -= (class as f64) * 3.0;

    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fits (small dead space) get a harmonic bonus.
    if post_residual <= 10 {
        score -= 40.0;
    }

    // Penalize residuals that no plausible item (min size 10... but interface says 1..100)
    // can ever fill: dead space beyond the largest plausible gap.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny useless sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 120.0;
        } else {
            score -= (post_residual - next_item_size).min(50) as f64 * 0.5;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: leftover becomes dead space.
        score += (post_residual as f64) * 0.6;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral baseline, penalized when
    // open bins already have plenty of room.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in the stream, opening bins is cheap and keeps residuals large.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // placing into below-average-residual bins preserves fat bins.
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 5.0;
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10
    // pair well with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Integer-division threshold: avoid leaving residuals in the
    // awkward (capacity/8..capacity/4) mid-range if a tighter option exists.
    let mid_low = bin_capacity / 8;
    let mid_high = bin_capacity / 4;
    if post_residual > mid_low && post_residual < mid_high {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1,10] are nearly unusable
    // (min item size is 1, but tiny gaps rarely match future items) — hard penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0) + 25.0;
    }

    // Reward near-perfect packing strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 20 {
        score -= 20.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Coupling: dead space hurts more when many bins are open (pressure to consolidate).
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).min(1.0);
    score += pressure * post_residual as f64 * 0.6;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.35 * item_size as f64;
        // If lookahead fits better into a fresh bin, soften the new-bin cost.
        if next_item_size > 0 && next_item_size <= 40 {
            score -= 12.0;
        }
    }

    // Lookahead synergy: if the next item exactly fills this bin's post-residual,
    // reward placing the current item here.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
    }

    // Prefer fuller bins relative to the fleet mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, allow slightly looser packing to build useful bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is already favored by base term.

    // 2-step lookahead: if next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin becomes exactly full
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover proportional to wasted space after next
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.8;
            // bonus if next item leaves near-zero residual
            if after_next <= 5 {
                score -= 25.0;
            }
        } else {
            // next item won't fit here; penalize bins that leave awkward mid-range gaps
            let gap = post_residual as f64;
            if gap >= 10.0 && gap < (next_item_size as f64) {
                score += 15.0; // dead space that next item cannot use
            }
        }
    }

    // Relative to mean residual: prefer bins with residual near/below mean (consolidation)
    let residual_f = post_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += mean_gap * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Penalize the fresh bin moderately.
    if bin_residual == bin_capacity && bin_residual == post_residual + item_size && item_size == bin_capacity - post_residual {
        // (item placed in empty bin: post_residual == capacity - item_size)
        score += 30.0 + 0.3 * (open_bins_count as f64);
    }

    // Progression: later in stream, be more conservative about waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += residual_f * progress * 0.4;

    // Slight preference to fill bins with larger residual first when many bins open
    score -= 0.2 * (bin_residual as f64) / (bin_capacity as f64) * (open_bins_count.min(20) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: fraction of residual consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize opening new bins when existing bins fit well.
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in stream, new bins are cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Global pressure: many open bins with large mean residual -> consolidate.
    if open_bins_count > 3 {
        score += 0.05 * open_bins_count as f64 * (mean_residual - post_residual as f64).abs();
    }

    // Mild preference for bins with residual close to item (best-fit flavor).
    let waste = (bin_residual - item_size) as f64;
    score += 0.1 * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr;

    // Non-linear coupling: reward tight fits more strongly as stream progresses
    let tightness = (1.0 - fit).powi(3);
    score -= (1.0 + 3.0 * progress) * tightness * item_size as f64;

    // Penalize dead space that is too small for typical future items
    let dead = pr / cap;
    score += 8.0 * progress * dead * dead * cap;

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = pr / nx.max(1.0);
        score -= 6.0 * (room / (1.0 + room)).powi(2) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins are nearly full
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / cap;
        score += 12.0 + 25.0 * (1.0 - mean_tight) * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue classes" are more likely to be closed out efficiently.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: post_residual == 0 -> perfect closure, strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic residue classes on post_residual (mod-based dead-space buckets).
    let class_mod = post_residual % 10;
    match class_mod {
        0 => score -= 6.0,            // residue divisible by 10: reusable slot sizes
        5 => score -= 2.5,            // half-class residues still usable
        _ => score += (class_mod as f64) * 0.4, // odd fragments are dead space
    }

    // Integer-division thresholds: tiny unusable residuals are penalized,
    // unless the bin is now essentially full.
    if pr > 0.0 && pr < 10.0 {
        score += 8.0; // dead space below minimum item size
    }

    // Reward filling bins tightly relative to capacity fractions.
    let fill_frac = (bin_residual as f64) / cap;
    if fill_frac > 0.5 {
        score -= 4.0 * fill_frac; // prefer packing into already-half-full bins
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic compatibility: exact or near-exact next-item fit is gold.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 15.0;
            } else if gap < 10 {
                score -= 6.0;
            } else {
                score -= 2.0;
            }
        } else {
            // Next item cannot follow here; penalize more as residual shrinks.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // When many bins are open, prefer consolidation into tight fits.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (1.0 - fill_frac);
    }

    // New-bin candidate: make the empty bin attractive only when no good fit
    // exists among open bins (its post_residual is huge otherwise, so the
    // base already penalizes it; add a mild bias toward using open bins).
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if the stream is late and bins are scarce, allow opening.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if this bin is much tighter than average,
    // prefer it (drives residual variance down).
    score += 0.3 * (mean_residual - (bin_residual - item_size) as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fits get strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is bad or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 35.0;
        // Pressure from many open bins makes new bins slightly more attractive later.
        score -= (open_bins_count as f64).ln() * 3.0;
        // If next item fits well into a fresh bin's residual, encourage new bin.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            let pair_waste = (bin_capacity - item_size).saturating_sub(next_item_size);
            if pair_waste < 10 {
                score -= 20.0;
            }
        }
        // Early in stream, new bins are cheap.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Reward bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness) * (1.0 - tightness);

    // Slight pressure to consolidate: prefer bins with low mean residual spread.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Discourage leaving residuals that can't fit typical small items unless next item fits.
    if post_residual > 0 && next_item_size > post_residual && post_residual < 20 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Near-perfect match: next item leaves minimal new dead space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 120.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize if the next item would NOT fit in the resulting residual
    // (creates a stranded bin unless residual is near zero).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 50.0 * fill_ratio;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Late in the stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 25.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * tightness;

    // Penalize leaving dead space that can't fit typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as f64) < (next_item_size as f64) * 0.5
        } else {
            false
        };
        if dead {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - chain / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item won't fit here; penalize wasting residual on a mid-size gap.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // Prefer filling bins that are already well used (large fill fraction).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 3.0 * fill;

    // Time horizon: late in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 2.0 * progress;
    }

    // Global state: many open bins with high mean residual -> favor compacting into
    // existing bins rather than spreading; low mean residual -> new bin less costly.
    if open_bins_count > 0 {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        score -= 2.5 * mean_fill;
        // Penalize new-bin candidate when many bins are already open and empty-ish.
        if bin_residual == bin_capacity {
            score += 1.5 + 0.05 * open_bins_count as f64 * (1.0 - mean_fill);
        }
    }

    // Mild penalty for exact-fit overuse when item is large (keep flexibility).
    if post_residual == 0 && item_size < 40 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post-residual (dead space), slightly super-linear
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr) * 100.0;

    // Smooth non-linear coupling with stream progress: early on, tolerate residual;
    // late in stream, penalize residual harder since fewer chances to fill it.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits: interaction between post_residual and item fraction
    let tightness = 1.0 - norm_pr; // high when item nearly fills bin
    score -= 40.0 * tightness * norm_item * (1.0 + progress);

    // Lookahead: if next item fits exactly in post_residual, strong reward (smooth)
    if next_item_size > 0 {
        let gap = (pr - norm_next * cap).abs() / cap;
        let fit_bonus = (-6.0 * gap).exp();
        score -= 25.0 * fit_bonus * (1.0 - progress * 0.5);
    }

    // Last-chance bin: penalize opening new bins when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Mean residual alignment: prefer bins close to the mean residual (smooth)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Mild pressure to consolidate when many bins are open
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: make it moderately attractive only when residuals are poor
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = 30.0 + 60.0 * avg_tightness * (1.0 - progress * 0.5) - 20.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zone" classes are penalized less if they were already small.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize large leftover residual quadratically (wasted space).
    score += frac * frac * 40.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class: post_residual modulo 10 — small classes are "usable"
    // for small items; large classes indicate fragmentation.
    let class = post_residual % 10;
    score -= (9 - class) as f64 * 0.8;

    // Integer-division threshold: can next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: reward proportional to how well next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.5;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0; // exact harmonic division, great packing
            }
        } else {
            // next item cannot follow here; slight penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when
    // existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // base cost of opening a bin
        score = cap * 0.85;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open
        }
        // late in stream with tight mean residual, prefer new bin over bad fits
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 15.0 + 20.0 * progress;
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // save space for a bigger next item
        }
    }

    // Mild preference to fill bins with larger residuals when many open.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftovers (1..10) are almost unusable for
    // future items (min size 10); punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual == 10 {
        score -= 25.0; // leaves room for smallest item class
    }

    // Prefer bins whose residual was already small (tight packing).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; encourage filling existing ones.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: penalize opening a new bin unless current bin
    // would leave a truly dead gap.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
    }

    // Mean residual coupling: if open bins are on average quite full,
    // reward placing into this bin.
    score -= (bin_capacity as f64 - mean_residual) * 0.05;

    // Slight stream-progression bias: later in stream, pack tighter.
    if total_items > 0 {
        score -= (step_index as f64 / total_items as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tightly it fits
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item does NOT fit this bin after placement: penalize wasted lookahead
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical";
    // penalize leaving residual far above mean (wasteful large leftover)
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it unattractive unless all fits are terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if next item is large and no good fit exists, opening may be OK
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 30.0;
        }
    }

    // Late-stream pressure: consolidate as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 40.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than spreading
    score += 0.5 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: quadratic bonus for small post-residual.
    let tightness = (post / cap) * (post / cap);
    score -= 18.0 * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Dead-space penalty: post residual too small for any plausible item (min size 1,
    // but small unusable slivers relative to capacity are wasted).
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here: penalize large leftover that blocks lookahead.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Crowding: when many bins are open, prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * crowd * (0.5 + progress);

    // Prefer bins whose residual is below mean residual (denser bins) when item fits well.
    if post < mean_residual {
        score -= 6.0 * (mean_residual - post) / cap;
    } else {
        score += 4.0 * (post - mean_residual) / cap;
    }

    // New-bin candidate: only attractive when nothing fits well (high mean residual spread,
    // poor tightness here, or no lookahead benefit). Penalize opening new bins early.
    if bin_residual == bin_capacity {
        let early_penalty = 45.0 * (1.0 - progress);
        score += early_penalty + 20.0 + 5.0 * crowd;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin leaves room for next item; soften penalty
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear shrinkage of large residuals
    let mut score = norm_pr - 0.6 * norm_pr * norm_pr;

    // Polynomial coupling of post_residual with stream progress
    let t = progress;
    score += 0.5 * norm_pr * t * t - 0.3 * norm_pr * t * (1.0 - t);

    // Reward tight fits (small post_residual), stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 0.35 * tightness * tightness * (0.5 + t);

    // Lookahead: reward leaving room for next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = norm_pr - nx;
        let smooth_gap = gap * gap / (1.0 + gap * gap);
        score -= 0.4 * smooth_gap * (1.0 - t);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 1.2;
    }

    // Mild penalty when many bins are open and residual is large (fragmentation)
    let frag = norm_pr * (open_bins_count as f64).ln_1p();
    score += 0.08 * frag * (0.5 + t);

    // Mean residual deviation: prefer bins near mean to keep balance, smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += 0.1 * dev * dev;

    // New-bin candidate: penalize slightly so real fits are preferred unless very poor
    if bin_residual == bin_capacity {
        score += 0.15 + 0.5 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "nice" residue classes (multiples of common item quantum) are more
    // reusable, so reward them (subtract), others penalize (add).
    let quantum = 10u32;
    let nice = post_residual % quantum == 0;
    if nice {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Integer-division threshold: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.1 {
        // Tight fit: excellent, strongly reward.
        score -= 12.0;
    } else if frac < 0.25 {
        score -= 3.0;
    } else if frac > 0.6 {
        // Large dead space: penalize unless bin was fresh.
        score += 5.0 * frac;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this is a perfect chain placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Harmonic gap: gap divisible by quantum is a benign leftover.
            if gap % quantum == 0 {
                score -= 5.0;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // Next item cannot use the leftover: leftover likely dead space.
            score += post_residual as f64 * 0.10;
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or all existing bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize new bins by default; relieve penalty when existing bins
        // are tight (low mean residual) or item is big.
        score += 14.0 - 10.0 * (1.0 - pressure) - 8.0 * large_item - 2.0 * progress;
    }

    // Mild global pressure: many open bins with high mean residual means we
    // should pack tighter into existing bins (favor low post_residual even more).
    if open_bins_count > 2 {
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: gaps too small for the minimum item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Last chance: only this bin can fit the item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: prefer keeping the number of open bins low.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual deviates below the mean (consolidate small gaps).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: make it attractive only when fits are poor or dead space
    // would be created; otherwise slightly discourage opening new bins.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 5.0;
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how tightly it fits
            score -= 50.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use post_residual: penalize dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins with residuals below mean (compact bins first)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize slightly unless current bin is a bad fit
    if bin_residual == bin_capacity {
        score += 30.0;
        // If no existing bin fits well, opening a new bin is fine
        if post_residual > 60 {
            score -= 60.0;
        }
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item is worthless.
    let dead = if post_residual < 1 { 0.0 } else { post_residual as f64 };
    score += 0.35 * dead;

    // Exact or near-exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild bonus proportional to how well it packs
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving a residual that
            // is "almost but not quite" large enough (dead space trap)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 0.6 * (20.0 - gap);
            }
        }
    }

    // Prefer filling bins that are already relatively full (low residual
    // relative to mean): keeps many mid-size bins available.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += 3.0 * (rel - 1.0);
    }

    // Time horizon: late in the stream, consolidate aggressively; early,
    // keep bins open for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // When many bins are open, favor consolidating into existing ones
    // rather than opening new bins.
    score += 0.8 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early stream: new bins are cheaper to open.
        score -= 25.0 * (1.0 - progress);
        // If item is large, a fresh bin is reasonable.
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, mildly damped
    let mut score = pr * (0.85 + 0.3 * progress);

    // Non-linear polynomial coupling of residual with stream progress
    let t = progress;
    score += 40.0 * norm_pr * norm_pr * (1.0 - t) * t * 4.0;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.5 + t);

    // Lookahead: penalize if post residual can't fit next item, reward if it can
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * norm_next * (0.5 + t);
        } else {
            score += 8.0 * norm_next * (1.0 - t);
        }
    }

    // Dead-space penalty for very small residuals that are hard to reuse
    if pr > 0 && pr < 10 {
        score += 15.0 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when current bin would leave large waste
    if bin_residual == bin_capacity {
        score -= 6.0 + 10.0 * (1.0 - norm_item) * (1.0 - t);
    }

    // Mean-residual coupling: prefer bins deviating from mean to balance residuals
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

