pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately awkward gaps (10..=20) get a mild penalty.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual was already small (tight packing).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: prefer using existing bins when many are open.
    score -= open_bins_count as f64 * 3.0;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If lookahead item is large, opening a fresh bin may be wise.
        if next_item_size > 0 && next_item_size >= item_size && post_residual < next_item_size as u32 {
            score -= 15.0;
        }
    }

    // If the next item would fit exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mean residual coupling: prefer bins below the mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: post_residual slightly above next item size (waste 1..=5)
    if next_item_size > 0 && post_residual > next_item_size {
        let waste = (post_residual - next_item_size) as f64;
        if waste <= 5.0 {
            score -= 25.0 - 4.0 * waste;
        } else if waste <= 15.0 {
            score -= 5.0 - 0.3 * waste;
        }
    }

    // Penalize small unusable leftovers (dead space) that can't fit next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Reward leaving large, flexible residual relative to mean residual
    if mean_residual > 0.0 {
        score -= 0.15 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when this bin would leave bad dead space
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // make new bin unattractive unless the item is a huge fraction of capacity
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 20.0 * fill_ratio;
        // if no other bin fits well (post residual dead space), new bin gains appeal
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 18.0;
        }
    }

    // Late in stream: tighten packing, prefer tight fits even more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 12.0;

    // Exact fill is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize new-bin candidate unless the fit in open bins would be poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0;
        // New bins more attractive late in stream when mean residual is low.
        score -= progress * 10.0;
        score -= (mean_residual / bin_capacity as f64) * 8.0;
        // Big dead space in a fresh bin is bad.
        score += waste * 0.05;
    }

    // Lookahead coupling: reward leaving space exactly matching next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // Good: next item still fits; reward proportionally.
            score -= 6.0;
        } else {
            // Bad: next item won't fit in this bin's remainder.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize creating small unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild pressure to consolidate into existing bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Prefer bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let next = next_item_size as f64;
    let fit = if post_residual >= item_size { post_residual - item_size } else { 0 } as f64;

    // Base: wasted space after placement, normalized
    let mut score = post / cap;

    // Tight-fit reward: strongly favor bins where post_residual is small
    let tightness = 1.0 - (post / cap).powi(2);
    score -= 2.5 * tightness * (1.0 - progress * 0.5);

    // Lookahead: penalize residuals that cannot fit the next item (dead space)
    if next > 0.0 {
        let gap = (next - post).max(0.0) / cap;
        let usable = if post >= next { 1.0 } else { 0.0 };
        // smooth coupling: waste hurts more when it nearly fits but doesn't
        let near_miss = (post / next).clamp(0.0, 1.0);
        score += 1.8 * gap * (1.0 - usable) * near_miss;
        // reward residual that exactly accommodates next item
        score -= 1.2 * usable * (1.0 - ((post - next) / cap).powi(2));
    }

    // Penalize bins far below mean residual (fragmentation risk)
    let dev = (post - mean_residual) / cap;
    score += 0.4 * dev * dev.abs();

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: discourage early, allow late when stream nearly done
    if bin_residual == bin_capacity {
        score = 1.0 + 0.5 * (1.0 - progress) - 0.3 * progress * progress;
        if next > 0.0 && next <= bin_capacity as f64 {
            score -= 0.1;
        }
    }

    // Mild coupling: more open bins -> prefer filling existing ones
    score += 0.02 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins partitioned by residual magnitude classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: small dead space (1..=10) -> mild reward.
    // Class 2: medium dead space (11..=30) -> neutral/mild penalty.
    // Class 3: large dead space (>30) -> penalty.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    } else if post_residual <= 30 {
        score += 4.0;
    } else {
        score += 10.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are more reusable later.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0) {
        score -= 3.0;
    }
    // Odd, awkward residuals are less reusable.
    if pr % 2 == 1 && pr > 0 {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 5.0;
            } else {
                score += (gap as f64) * 0.15;
            }
        } else {
            // Next item cannot follow here; residual becomes dead space.
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: only fitting bin -> avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: empty bin. Prefer it only when no open bin fits well
    // (i.e., item is large relative to capacity or open bins are nearly full).
    if bin_residual == bin_capacity {
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin; discount when item is large.
        score += 18.0 - 14.0 * fill_fraction;
        // If many open bins are nearly full, a fresh bin is fine.
        if mean_residual < 15.0 {
            score -= 8.0;
        }
        // Late in the stream, keep bins open less aggressively.
        if step_index as f64 / total_items as f64 > 0.8 {
            score -= 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (compact fuller bins first), penalize dipping into roomy bins.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Slight preference for using bins with high current fill.
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (near-exact packing).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual closely matches the item (best-fit sharpening).
    score -= 2.0 * (bin_residual as f64 - item_size as f64).abs().recip().min(2.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer filling existing bins.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate: penalize unless the item cannot fit any bin well
    // (i.e., it is large relative to typical residuals) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_elsewhere = mean_residual < item_size as f64 + 5.0;
        if poor_fit_elsewhere {
            score -= 55.0 * (1.0 - progress);
        } else {
            score += 120.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual well, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 25.0;
        }
    }

    score
