pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, but especially
    // when it is tiny relative to the mean residual across open bins.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_quality * fit_quality;

    // 2-step lookahead: strongly reward when the next item exactly fills
    // the post residual (perfect chain), mildly reward if it fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item chain
        } else if next_item_size < post_residual {
            // reward proportional to how much of the leftover the next item uses
            let use_frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * use_frac * use_frac;
        } else {
            // next item won't fit in leftover: penalize large dead space
            score += 0.6 * post_residual as f64;
            // extra penalty if the leftover is small enough that nothing typical fits
            if post_residual < 10 {
                score += 15.0;
            }
        }
    } else {
        // last item: just prefer tightest fit
        score += 0.2 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above the mean
    // should absorb items if the fit is decent, keeping tight bins free.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.25 * mean_gap;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        if post_residual <= next_item_size && next_item_size > 0 {
            score -= 15.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but allow it when open bins are mostly full (high mean residual pressure).
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        score += 50.0 - 45.0 * pressure;
        // opening a fresh bin is good if next item is large and no bin chains well
        if next_item_size > 50 && mean_residual < 30.0 {
            score -= 20.0;
        }
    }

    // Late in the stream: consolidate aggressively, avoid spreading items.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Penalize leaving dead space that cannot fit any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are wasted capacity
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
        // Extra reward if post_residual fits next item tightly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 2.0 * (1.0 - slack as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, be conservative and pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 10.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: penalize leftover waste with a non-linear (quadratic) term
    let mut score = post * (1.0 + 0.8 * norm_post);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer filling bins tightly; later, tolerate spread residual
    let progress_coupling = (0.5 + t) * norm_post * norm_post * cap;
    score += progress_coupling * 0.6;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 20.0 * t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    }

    // Compare against mean residual: placing in a bin with residual near the mean
    // keeps the fleet balanced; penalize deviating too far (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: mild penalty so it's chosen only when open bins are poor fits;
    // the penalty relaxes slightly late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: exact-fill classes are gold.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else {
        score += 8.0;
    }

    // Modulo-class dead zones: residuals that no plausible item (1..=100) pairs well with.
    let r = post_residual;
    if r > 0 && r < 10 {
        score += 25.0; // tiny slivers are dead space
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == r {
