        } else if next_item_size <= r {
            // next item fits: residual gets consumed, good
            score -= (r - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot use this residual: penalize large leftovers
            score += (next_item_size - r) as f64 * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        score += 40.0; // default penalty; overcome only by excellent existing fits above
        if post_residual > 50 { score -= 20.0; }
    }

    // Prefer fuller bins relative to capacity fraction.
    score -= (1.0 - (post_residual as f64) / cap) * 15.0;

    // Spread pressure: when many bins are open, tighten selection.
    score += (open_bins_count as f64) * 0.5 - mean_residual * 0.05;

    // Late-stream tightening.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (r as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9)
    // are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual too small for next item: mild penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
