    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large or all open bins would leave big dead space.
    if bin_residual == bin_capacity {
        let large_item_bonus = 0.4 * item_size as f64;
        score = 30.0 + large_item_bonus - pressure;
        if fitting_bins_count == 1 {
            score += 45.0; // don't abandon the only fitting bin
        }
        if item_size >= 50 {
