        return score;
    }

    // Prefer bins whose residual is already below average (filling fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        if (post_residual as f64 - look).abs() < 0.5 {
            score -= 60.0; // perfect two-step chain
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward scaled by tightness
            let tight = 1.0 - (post_residual as f64 - look) / bin_capacity as f64;
            score -= 25.0 * tight;
        } else {
            // next item won't fit: penalize wasted residual relative to lookahead
            let waste = look - post_residual as f64;
            score += 0.35 * waste.min(60.0);
        }
    }

    // Penalize post_residual that is small but unusable (dead space < min item 1)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins that are already tight
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer filling nearly-full bins (small post residual) nonlinearly
    let fill_frac = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // New-bin candidate: penalize opening a new bin when decent alternatives exist,
    // but allow it when open bins are all very tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - mean_residual / bin_capacity as f64;
        if avg_tightness < 0.75 {
            score += 30.0;
        } else {
            score -= 5.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit via quadratic waste penalty
    let waste = post_residual as f64;
    score += 0.35 * (waste / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward proportional to leftover quality
            score -= 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // next item won't fit here; penalize leaving awkward small gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - gap);
            }
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when alternatives are bad
    if bin_residual == bin_capacity {
        // Penalize opening new bins early / when many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 25.0 * (1.0 - progress) + 3.0 * open_bins_count as f64;
        // But if no open bin can fit (fitting_bins_count counts only this new bin), make it viable
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Global residual coupling: prefer bins that bring mean residual closer to typical future demand
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Prefer filling bins that are already mostly full (consolidation)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Late stream: discourage leaving large residuals when near the end
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        if t > 0.8 {
            score += 0.05 * post_residual as f64 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: penalize wasted space quadratically (dead space grows quadratically costly)
    let mut score = pr + 8.0 * norm_pr * norm_pr * cap;

    // Smooth non-linear coupling: residual value depends on stream progress.
    // Early on, tight fits matter less; later, tight fits (small post_residual) are prized.
    let tightness = 1.0 - norm_pr; // how full the bin becomes
    let progress_reward = 20.0 * tightness * tightness * (0.5 + 0.5 * progress);
    score -= progress_reward;

    // Polynomial interaction between post_residual and progress:
    // large residuals become more acceptable as stream progresses (bins will close anyway)
    let interaction = 6.0 * norm_pr * (norm_pr - 0.5) * (progress - 0.5);
    score += interaction;

    // Lookahead: reward leaving room for the next item (smooth gaussian-like match)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        let match_bonus = 10.0 * (-40.0 * diff * diff).exp();
        score -= match_bonus;
    } else {
        // last item: strongly favor tightest fit
        score -= 15.0 * tightness;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Slight penalty when many bins are open and residual is large (fragmentation risk)
    let frag = (open_bins_count as f64).ln1p() * norm_pr;
    score += 1.5 * frag;

    // Mild pull toward mean residual to balance bin loads (smooth)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual is naturally lower, amplify quadratic waste penalty.
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class of post_residual: dead space zones by capacity fraction.
    // Residuals that are hard to fill (small odd leftovers) get penalized.
    let class = post_residual / 10;
    match class {
        0 => score -= 8.0,      // near-perfect: 0..9
        1 => score += 4.0,      // awkward: 10..19
        2 => score -= 2.0,      // medium item fits
        3 => score += 1.0,
        4 => score -= 1.0,
        5 => score -= 3.0,      // half-bin: very reusable
        6 => score += 0.0,
        7 => score -= 1.0,
        8 => score -= 2.0,
        9 => score -= 4.0,      // nearly empty bin
        _ => {}
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64) * 0.15;
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when few bins fit the item and mean residual is low,
    // or when the current bin would leave very awkward space.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish, slightly above good fits.
        score = 55.0;
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening new bin is fine when nothing else fits
        }
        if next_item_size > 0 && next_item_size >= 50 && next_item_size <= 100 {
            score -= 10.0; // big next item benefits from fresh bin
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress); // early stream: opening bins is cheaper
    }

    // Prefer filling bins that are already mostly used (large item_size relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Spread pressure: when many bins are open, favor consolidation into emptier ones less.
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    // Mean residual coupling: if this bin is below mean residual (more packed), favor it.
    score -= 2.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "unusable" if it cannot hold even a small item (size ~10)
    // or cannot hold the lookahead item.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny dead space, wasted forever
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap can't fit the next item either
        } else {
            // reward gaps that can still be exploited
            score -= 8.0;
        }
    } else {
        // perfect fit: strongly reward
        score -= 40.0;
    }

    // Reward tight fits: closeness of item to bin_residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bins pressure: when many bins are open, prefer consolidating
    // into existing bins (especially last-chance bins) rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open-bin residuals are large/fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Attractive if existing bins are fragmented (high mean residual spread)
        // or if this bin would be the first.
        if open_bins_count == 0 {
            score -= 100.0;
        } else {
            let fragmentation = (mean_residual - post_residual as f64).abs();
            if mean_residual < 15.0 {
                // existing bins nearly full: opening new bin is fine
                score -= 20.0;
            }
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 5.0;
            }
            let _ = fragmentation;
        }
        // Discourage opening new bins early in the stream.
        score += 30.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (more filled bins) to consolidate.
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            if leftover_after_next <= 10 {
                score -= 150.0 - (leftover_after_next as f64) * 8.0;
            } else {
                score += (leftover_after_next as f64) * 0.5;
            }
        } else {
            // Next item won't fit here; penalize large post_residual (dead space).
            score += (post_residual as f64) * 0.8;
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    let resid = post_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 1.5;
    } else {
        score += (resid - mean_residual) * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let bad_fragmentation = fitting_bins_count == 0
            || (open_bins_count > 0 && mean_residual < item_size as f64 * 0.9);
        if bad_fragmentation {
            score -= 50.0;
        } else {
            score += 400.0;
        }
    }

    // Late-stream bias: tighten packing as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += resid * 0.3 * progress;

    // Small penalty for very large residual waste relative to capacity.
    score += (resid / bin_capacity as f64).powi(3) * 60.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual relative to capacity (non-linear).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if the next item can fit into post_residual (chaining),
    // penalize if post_residual is small but nonzero and unusable by next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 {
            // dead space unusable by next item: penalize proportionally
            score += 8.0 * (post_residual as f64 / 100.0)
                   * (1.0 - next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Prefer filling bins with larger residuals among open bins (consolidation),
    // but only mildly so tight-fit dominance remains.
    if bin_residual != bin_capacity {
        score -= 0.05 * bin_residual as f64;
    }

    // New-bin candidate handling: acceptable early in the stream or when
    // mean residual across open bins is low (poor overall state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 55.0;
        nb -= 40.0 * (1.0 - progress);                       // easier to open early
        nb -= 0.5 * (mean_residual / bin_capacity as f64).max(0.0).min(2.0) * 10.0; // open bins are full-ish -> new bin ok
        nb -= 2.0 * open_bins_count as f64;                  // few open bins -> opening cheap
        if next_item_size > 0 && post_residual >= next_item_size {
            nb -= 10.0;                                      // fresh bin chains next item
        }
        score += nb.max(1.0);
    }

    // Slight penalty for creating very small unusable slivers (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly non-linearly transformed
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: small post-residuals become more valuable later in the stream
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (progress * progress);

    // Reward near-perfect fits with a smooth saturating term
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_quality * fit_quality * (1.0 - progress * 0.5);

    // Penalize large dead space, weighted by stream progress
    score += 6.0 * norm_pr * norm_pr * progress;

    // Lookahead: reward residual that can host next item (smooth margin term)
    if next_item_size > 0 {
        let margin = pr - next_item_size as f64;
        if margin >= 0.0 {
            let s = (margin / cap).min(1.0);
            score -= 5.0 * (1.0 - s) * (1.0 - s);
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild pressure against spreading across many bins
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer it only when residuals are tight and progress is low
    if bin_residual == bin_capacity {
        let avg_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 4.0 * avg_tight * (1.0 - progress);
        score += 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit: opening a new bin is mandatory.
            score -= 100.0;
        } else {
            // Prefer existing bins; penalize new bin more when current item is small
            // (small items waste fresh capacity) and when many bins are already open.
            score += 40.0 + 0.5 * item_size as f64 + 2.0 * open_bins_count as f64;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly reward using it to avoid opening a new bin.
        score -= 15.0;
    }

    // --- Lookahead (k=2): reward if next item fits into the post residual ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect chaining: post residual exactly consumed by next item.
            score -= 12.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // --- Harmonic class logic on post_residual ---
    // Dead space classification via integer division thresholds (capacity fractions).
    let r = post_residual;
    if r == 0 {
        // Perfect fit: best possible outcome.
        score -= 20.0;
    } else if r <= bin_capacity / 10 {
        // Tiny dead space: nearly perfect.
        score -= 6.0;
    } else if r <= bin_capacity / 4 {
        // Small-but-usable residue class.
        score -= 2.0;
    } else if r > bin_capacity / 2 {
        // Large residual left behind: wasted potential, penalize.
        score += 0.15 * r as f64;
    }

    // Modulo arithmetic: residues divisible by common item granularities (5, 10)
    // are more likely reusable by future items.
    if r % 10 == 0 && r > 0 {
        score -= 3.0;
    } else if r % 5 == 0 && r > 0 {
        score -= 1.5;
    }

    // --- Context coupling ---
    // Early in the stream, be conservative with residual quality; late in the
    // stream, tolerate messy fits since remaining impact is small.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.2 * progress;

    // Slight preference toward bins whose residual deviates favorably from mean.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers are the worst outcome.
    let dead_zone = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0; // heavy penalty for tiny unusable gaps
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 12.0;

    // If the next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0; // dead space that can't host the next item
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent home.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += desperation + mean_residual * -0.5;
        // Opening a new bin early in the stream is cheap; late is costly.
        score += progress * 20.0;
    }

    // Mean residual coupling: prefer bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) > mean_residual {
        score += 4.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain of perfect fits
        } else if post_residual >= next_item_size {
            // reward proportionally to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 60.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 2.0 * (post_residual as f64 - mean_residual);

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or fits are poor
    if bin_residual == bin_capacity {
        score += 250.0;
        if item_size > 80 {
            score -= 100.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Progression: as stream advances, be more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit typical items is worse. Penalize awkward residuals.
    let dead = post_residual as f64;
    if post_residual > 0 {
        // residuals too small to hold anything useful (min item ~1..100 unknown,
        // use relative scale) are pure waste
        let waste_frac = dead / bin_capacity as f64;
        score += 25.0 * waste_frac * waste_frac;
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward;
    // if next item cannot fit in post residual but fits empty bin, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here after placement
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins: compare residual to mean residual across open bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, be picky (prefer tight fits); late in
    // stream, just pack anything to avoid opening bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (post_residual as f64 / bin_capacity as f64);

    // When many bins are open, favor consolidating into existing ones
    // rather than opening new bins; the new-bin candidate has
    // bin_residual == bin_capacity, so give it a mild penalty that grows
    // with open_bins_count.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Normalize post-residual and its polynomial couplings with stream progress
    let prn = pr / cap;
    let prog = progress.clamp(0.0, 1.0);

    // Smooth non-linear interaction: dead-space penalty grows quadratically with progress
    score += 8.0 * prn * prn * (0.5 + prog);

    // Reward tight fits (small post_residual) with cubic shaping
    score -= 6.0 * (1.0 - prn).powi(3);

    // Lookahead coupling: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 5.0 * (1.0 - gap * gap);
        } else {
            score += 3.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (pack tighter bins first)
    let dev = (mean_residual - pr) / cap;
    score += 2.0 * dev * (1.0 - prog);

    // Early stream: slight preference for new bins to keep options open
    score -= 4.0 * (1.0 - prog) * (prn - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual falls into "small"
    // classes are nearly perfect; large residuals waste capacity.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit is always best
    } else {
        // class = ceil(pr / 10): harmonic bucket of dead space
        let class = ((pr + 9) / 10) as f64;
        score += class * class; // quadratic penalty on dead-space class
    }

    // Reward if the lookahead item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // harmonic compatibility: gcd-like class match
            let combo = pr + next_item_size;
            if combo % 10 == 0 || combo % 25 == 0 {
                score -= 12.0;
            }
            score -= 5.0;
        } else {
            // next item won't fit here; penalize more if residual is large
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 35.0;
        // relax penalty late in the stream when many bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        if open_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Prefer bins tighter than the mean residual (good fill direction)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for bins whose residual shares harmonic class with item
    if bin_residual % 10 == item_size % 10 && bin_residual >= item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit typical future items
    // (below the minimum item size) are pure waste -> strong penalty.
    let dead = post_residual < 10 && post_residual > 0;
    if dead {
        score += 40.0;
    } else if post_residual < 20 {
