    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover gap -> mild penalty.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += pressure * 1.5;

    // Prefer bins with below-mean residual (tighten the tightest bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; reduced late in the stream or when
        // open-bin pressure is high and fits are poor.
        let mut new_bin_cost = 30.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 45.0; // no alternative: opening a bin is fine
        }
        if post_residual as f64 > mean_residual * 0.9 {
            new_bin_cost -= 10.0;
        }
        score = new_bin_cost + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
