    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
    }

    // Prefer tighter fits overall (smaller post_residual already in base score)

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (post_residual == 0 handled by base score already low)
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in the post residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // penalize leaving dead space the next item can't use
            score += 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin when alternatives exist
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 60.0;
        } else if fitting_bins_count == 1 {
            score += 5.0;
        }
        // early stream: opening bins is cheap; late stream: prefer filling existing
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - t);
    }

    // Prefer bins tighter than the average residual (fill the fullest first)
    score += (bin_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.08;

    // Slight preference for bins among many open bins (consolidate)
    score += 0.02 * open_bins_count as f64;

    // Small penalty for large leftover gaps that few items can fill
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny gap nearly perfect
    }
    if post_residual >= 10 && post_residual < 20 && next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // awkward gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (low post_residual); Late: tolerate larger residuals
    // since future opportunities diminish.
    let tightness = (pr / cap).powi(2);
    let late_bonus = 0.5 * progress * (1.0 - (pr / cap)).powi(3);
    score -= late_bonus;

    // Penalize residuals that are too small to ever fit a typical item again,
    // scaled smoothly by progress (dead space matters more early on).
    let dead = (1.0 - (pr / cap)).powi(4);
    score += 8.0 * dead * (1.0 - progress);

    // Reward filling a bin nearly full, more so mid-to-late stream.
    let fill = (item_size as f64 / cap).powi(2);
    score -= 3.0 * fill * (0.3 + 0.7 * progress);

    // Lookahead: if next item fits in post_residual, strongly favor this bin.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - progress);
    }

    // Last-chance bin: avoid opening new bins when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 4.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: encourage consolidation toward low-residual bins.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 5.0)).powi(2);
    score += 2.0 * pressure * (pr / cap);

    // Mean-residual coupling: bins far below mean residual are less attractive.
    let dev = (mean_residual - pr) / cap;
    score += 1.5 * dev * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: classify leftover space into residue classes
    // modulo capacity fractions. Small leftovers (class 0: <=10) are excellent.
    let cls = match post_residual {
        0 => 0,
        p if p <= 10 => 1,
        p if p <= 20 => 2,
        p if p <= 40 => 3,
        p if p <= 70 => 4,
        _ => 5,
    };
    score += match cls {
        0 => -40.0,
        1 => -15.0,
        2 => 5.0,
        3 => 15.0,
        4 => 25.0,
        _ => 35.0,
    };

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic pairing: if next item exactly fills post_residual, strongly favor
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: residual after next placement, same class logic
        let nr = post_residual - next_item_size;
        score -= 20.0 * (1.0 - nr as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // dead space: next item cannot use this residual
        score += 0.35 * post_residual as f64;
    }

    // Last-chance bin: avoid opening a new bin if this fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty so it is only
    // chosen when existing bins create large dead space.
    if bin_residual == bin_capacity {
        score = 55.0 - 0.1 * open_bins_count as f64;
    }

    // Mild preference to fill older bins when many are open (keep count down)
    score += 0.05 * open_bins_count as f64;

    // Progress coupling: later in stream, be greedier about tight fits
    let prog = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * prog * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: bins deviating far from mean residual are less attractive
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically < next item) are wasted.
    // Penalize "unusable" small gaps extra hard.
    if post_residual > 0 {
        let dead = post_residual < 10; // below minimum item size range
        if dead {
            score += 40.0;
        }
        // Gap smaller than the next item is likely unusable for lookahead
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 30.0;
    }

    // Reward tight fits generally (post_residual small relative to item)
    let tightness = item_size as f64 / (post_residual as f64 + item_size as f64 + 1.0);
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is great
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad gaps
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, offset by potential of full capacity
        score += 10.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // a fresh bin serves the large next item well
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Early stream: slightly prefer consolidating into few bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item leaves minimal waste.
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - residual_ratio).powi(6);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        let match_strength = (-diff / 40.0).exp();
        score -= 25.0 * match_strength;
        // Penalize leaving a residual slightly larger than next item (dead space trap).
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer filling below-average-residual bins (tighter bins).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, be more willing to open bins (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer using nearly-full bins to close them out.
    if post_residual < 10 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, handled by base; add non-linear bonus.
    let cap_f = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap_f;
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else { post_residual as f64 };
        score += 0.25 * dead * dead / cap_f;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 4.0 * (1.0 - slack_after_next as f64 / cap_f);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let open_f = open_bins_count as f64;
    score += 0.4 * open_f * (1.0 - tightness);

    // Mean residual coupling: if this bin is much fuller than average, reward.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let relative = res_f / mean_residual;
        score -= 2.0 * (relative - 1.0).clamp(-2.0, 2.0);
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * tightness;

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin early when few bins exist or item is huge
        if item_size >= 80 || open_bins_count == 0 {
            score -= 25.0;
        }
        if progress > 0.7 {
            score += 10.0; // late stream: avoid new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Strong non-linear reward for tight fits (small post_residual)
    let tight = 1.0 - pr / cap; // 1.0 = perfect fit
    score -= 40.0 * tight * tight * tight;

    // Penalize medium dead space (unusable gaps) with a smooth bump
    let dead = (pr / cap - 0.3) * (pr / cap - 0.3);
    score += 15.0 * (-dead * 8.0).exp() * (1.0 - progress);

    // Stream-progress coupling: late in stream, prefer closing bins tightly
    score -= 30.0 * progress * tight * tight;

    // Lookahead: reward if next item fits the post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when open bins fit poorly
    if bin_residual == bin_capacity {
        let fit_quality = (bin_capacity - item_size) as f64 / cap;
        let mean_tightness = 1.0 - (mean_residual / cap).max(0.0).min(1.0);
        score += 45.0 + 30.0 * mean_tightness - 25.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Mild penalty for spreading across too many bins early
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual ---
    // Class 0: post_residual is a "clean" fraction of capacity (0, 25, 50, 75, 100)
    //          -> highly reusable, reward strongly.
    let clean_fractions: [u32; 5] = [0, 25, 50, 75, 100];
    if clean_fractions.contains(&post_residual) {
        score -= 18.0;
    } else {
        // Class 1: divisible by 10 -> still decent residual slots (10..90 multiples)
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 9.0;
        }
        // Class 2: divisible by 5
        else if post_residual % 5 == 0 {
            score -= 4.0;
        }
        // Class 3: odd / prime-dead residues -> penalize dead space
        else if post_residual < 10 {
            score += 14.0; // tiny unusable sliver
        } else {
            score += 6.0;
        }
    }

    // Integer-division thresholds: post_residual bucketed into decades.
    let decade = post_residual / 10;
    match decade {
        0 => score += 10.0,          // 0..9 : nearly dead
        1 => score -= 2.0,           // 10..19: fits only small items
        2 | 3 => score -= 5.0,       // mid-range useful
        4 | 5 => score -= 7.0,       // half-empty: very flexible
        6 | 7 => score -= 6.0,
        8 | 9 => score -= 3.0,
        _ => {}
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        // Perfect harmonic match: next item exactly fills the residual.
        if next_item_size == post_residual {
            score -= 30.0;
        }
        // Next item fits harmonically: residual divisible into copies of next item
        else if post_residual > 0 && next_item_size <= post_residual && post_residual % next_item_size == 0 {
            score -= 16.0;
        }
        // Next item fits but leaves a dead sliver (<10) -> penalize
        else if next_item_size <= post_residual && (post_residual - next_item_size) < 10 {
            score += 8.0;
        }
        // Next item cannot use this residual at all: residual value decays
        else if next_item_size > post_residual {
            score += 5.0;
        }
    } else {
        // Last item: any residual left is pure waste; prefer tightest fill.
        score += post_residual as f64 * 0.5;
    }

    // --- Last-chance bonus: this is the only fitting bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are
        // harmonically poor (mean residual is fragmented) or few bins fit.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 60.0
            + fragmentation * 0.3
            - (open_bins_count as f64) * 0.4
            + (mean_residual % 10.0); // penalize if mean residual is off-harmonic
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host the next item perfectly aligned.
            if bin_capacity % next_item_size == 0 {
                score -= 10.0;
            }
        }
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 * 1.5 {
            score += 15.0; // existing bins are still roomy; don't open new
        }
    }

    // --- Stream progression: late in stream, tighten packing ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // --- Mean residual anchoring: prefer bins near the mean (balanced packing) ---
    score += (bin_residual as f64 - mean_residual).abs() * 0.08;

    // Small tie-break favoring fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // future item are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    } else if post_residual <= 35 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
        // Penalize if post_residual just barely misses fitting the next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // stronger late in the stream when consolidation matters.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + 2.0 * progress) * 0.5;

    // New-bin candidate: make an empty bin attractive only when the item
    // leaves a large, flexible residual or no good fit exists.
    if bin_residual == bin_capacity {
        if post_residual >= 50 {
            score -= 10.0;
        } else if post_residual < 10 {
            score += 40.0;
        }
        // Prefer new bin when existing bins are fragmented.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 40.0 * match_quality;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize dead space creation
        score += 15.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize large leftover relative to mean residual (dead space)
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly-empty new bin opportunity on small items
    if bin_residual == bin_capacity {
        score += 10.0 + item_size as f64 * 0.3;
    }

    // Late in stream: prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight fit reward: non-linear in post_residual.
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tight * tight;

        // Lookahead: if next item fits into post_residual, favor this bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
        }
        // If next item would NOT fit here but would fit a fresh bin, penalize leaving tiny gap.
        if next_item_size > post_residual && post_residual < 10 {
            score += 5.0;
        }
    }

    // New-bin candidate handling: it has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize new bin mildly; escalate when many bins already fit the item.
        let mut penalty = 6.0;
        if fitting_bins_count > 0 {
            penalty += 4.0 * (fitting_bins_count as f64).sqrt();
        }
        // Late in the stream, avoid opening bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 4.0 * progress;
        // If mean residual across open bins is large, prefer reusing them.
        penalty += 0.05 * mean_residual;
        // If this bin is the last chance, strongly favor using it over a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 15.0;
        }
        score += penalty;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward heavily to avoid opening a new bin.
        score -= 15.0;
    }

    // Slight preference to fill bins with larger residuals when many bins are open.
    if open_bins_count > 3 {
        score -= 0.02 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping
    let base = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress-coupled penalty: dead space matters more late in the stream
    let progress_coupling = 12.0 * progress * norm_pr * (1.0 - norm_pr);

    // Tight-fit reward (small post residual relative to capacity), smoothed
    let tight_fit = -6.0 * (1.0 - norm_pr).powi(3) * (1.0 + 0.5 * progress);

    // Mean residual divergence: prefer bins whose residual after placement
    // stays close to the mean residual of open bins (harmonization)
    let mean_gap = (pr - mean_residual).abs() / cap;
    let harmonize = 5.0 * mean_gap * (1.0 - progress);

    // Lookahead: penalize if next item cannot use the post residual
    let look = if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns { 8.0 + 4.0 * (ns - pr) / cap }
        else { -3.0 * ((pr - ns) / cap).min(1.0) }
    } else { 0.0 };

    // Last-chance bin bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -10.0 } else { 0.0 };

    // New-bin candidate: neutral baseline, slightly discouraged early,
    // encouraged when open bins are fragmented (high mean residual)
    let new_bin_bonus = if bin_residual == bin_capacity {
        2.0 + 6.0 * (mean_residual / cap) * (1.0 - progress) - 4.0 * progress
    } else { 0.0 };

    let score = base + progress_coupling + tight_fit + harmonize + look + last_chance + new_bin_bonus;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals near multiples of
    // common item sizes are more reusable, so reward small "class distance".
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;

    // Tight fit bonus: post residual in low harmonic classes (0..=10)
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 22.0;
    } else if post_residual <= 30 {
        score -= 10.0;
    }

    // Modulo-10 class: residuals divisible by 10 pair well with 10..80 items
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Odd / awkward classes penalized slightly
    if post_residual % 10 != 0 {
        score += (post_residual % 10) as f64 * 0.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next fits: penalize leaving too much slack for it (dead space)
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack.min(18.0);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when current bins are very full
    // (harmonic threshold at 3/4 capacity) or it's early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // Base new-bin score: its residual equals capacity, so add a bias
        // that shrinks as mean residual across bins grows (fragmentation).
        score += 15.0 + mean_residual * 0.6;
        if progress < 0.25 {
            score -= 10.0;
        }
        if fill_ratio >= 0.0 && fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Prefer filling bins close to capacity as stream progresses
    score -= fill_ratio * (10.0 + 20.0 * progress);

    // Slight preference for bins below mean residual (balance fragmentation)
    score += ((post_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are toxic.
    let dead = post_residual < 10 && post_residual > 0;
    let unusable_for_next = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
    if dead {
        score += 60.0; // absolute waste
    }
    if unusable_for_next {
        // gap too small for the lookahead item: penalize proportionally to how close it is to fitting
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward tight fits (small post_residual relative to capacity)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing space
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is close to the item (best-fit flavor)
    score += 0.5 * ((bin_residual as f64 - item_size as f64) - post_residual as f64).abs();

    // New-bin candidate: only attractive when nothing fits well or open bins are nearly full
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score += 20.0; // base cost of opening a bin
        if mean_residual < item_size as f64 {
            score -= 45.0; // no open bin can hold it anyway
        }
        if avg_tightness > 0.7 {
            score -= 15.0; // open bins are nearly exhausted
        }
    }

    // Lookahead synergy: if the next item fits exactly in the post residual, reward heavily
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still fit the next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize unusable gap.
        let gap = (next_item_size - post_residual) as f64;
        score += (gap * 0.6).min(40.0);
    }

    // Tight fit reward: small post residual overall is good (best-fit flavor).
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current bin creates large dead space
    // or no open bin exists / residuals are large.
    if bin_residual == bin_capacity {
        let avg_dead = if next_item_size > 0 { (post_residual as f64 - next_item_size as f64).abs() } else { post_residual as f64 };
        score += 45.0 - avg_dead.min(45.0);
        if open_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Prefer bins with below-average residual (more packed bins get emptied first).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
