pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; late, tight fits matter more.
    let tightness = 1.0 + 2.0 * progress * progress;
    score += 40.0 * norm_pr * norm_pr * tightness;
    score -= 30.0 * norm_pr * (1.0 - progress);

    // Reward near-perfect fits more aggressively as stream advances
    let perfect = (1.0 - norm_pr).max(0.0);
    score -= 50.0 * perfect * perfect * (0.5 + progress);

    // Penalize bins whose residual deviates from mean (fragmentation pressure)
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 2.0 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 act as "dead space classes".
    let r = post_residual % 10;
    // Residuals that are multiples of 10 are the most reusable classes -> reward them.
    if r == 0 {
        score -= 6.0;
    } else if r <= 2 {
        score += 4.0; // tiny slivers are nearly dead space
    } else if r >= 8 {
        score += 2.5; // awkward large-but-unusable gaps for typical items
    }

    // Integer-division thresholds: can the leftover host the next item (k=2 lookahead)?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact-fit lookahead pair is excellent.
            if post_residual == next_item_size {
                score -= 12.0;
            } else {
                score -= 5.0;
                // Harmonic coupling: leftover after the lookahead also lands on a good class.
                let r2 = (post_residual - next_item_size) % 10;
                if r2 == 0 {
                    score -= 4.0;
                } else if r2 > 5 {
                    score += 2.0;
                }
            }
        } else {
            // Leftover cannot host the lookahead: penalize proportionally to how close it is.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is huge
    // relative to capacity (would leave open bins with poor residuals anyway).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 4.0;
        } else {
            score += 8.0 + 10.0 * (0.7 - frac);
        }
    }

    // Tight fit bonus: relative waste of the placement.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 8.0;

    // Progress modulation: late in the stream, consolidation matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    // Crowd control: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    // Mean-residual coupling: avoid bins far below the mean residual (they are the "best" bins
    // already nearly full; putting items there wastes their usefulness on poor fits).
    if (bin_residual as f64) < mean_residual - 10.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Reward proportional fit; penalize leaving a gap that next item almost fills.
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            if fit_ratio > 0.8 {
                score -= 200.0 * fit_ratio;
            } else {
                score -= 40.0 * fit_ratio;
            }
        } else {
            // Next item cannot fit: post_residual becomes dead space if too small.
            if post_residual < 10 {
                score += 150.0;
            } else {
                score += 30.0;
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins that end closer to mean
    // (keeps a portfolio of usable residuals), unless the fit is excellent.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when a reasonable fit exists in an open bin.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaled by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 400.0 + 200.0 * (1.0 - progress);
        // If next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 100.0;
        }
    }

    // Mild preference for bins with larger residuals when many bins are open.
    score -= 0.1 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powf(2.0) * (bin_capacity as f64);

    // Reward using nearly-full bins (small residual before placement).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a poor fit later.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when the item is large
    // relative to capacity or open-bin residuals are fragmented.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let fragmentation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        // Penalize new bins by default; discount the penalty when the item is
        // big or open bins are too fragmented to absorb it well.
        let mut new_bin_penalty = 25.0;
        new_bin_penalty -= 30.0 * large_item * fragmentation;
        if post_residual > 0 && post_residual < 10 {
            new_bin_penalty += 10.0; // creates tiny dead space in a fresh bin
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 15.0 * progress;
        score += new_bin_penalty.max(-10.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to waste
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Prefer spreading across bins when many bins are open and mean residual
    // is high (avoid hoarding space in one bin).
    if open_bins_count > 1 {
        let mean_r = mean_residual / bin_capacity as f64;
        score += 6.0 * mean_r * (1.0 - tightness);
    }

    // Mild bonus for leaving mid-range residuals (usable by typical items 10..80).
    if post_residual >= 10 && post_residual <= 80 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with non-linear tightening over time.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Non-linear polynomial coupling: penalize large residual quadratically as stream progresses.
    score += 6.0 * norm_post * norm_post * (0.3 + progress);

    // Dead-space penalty: residuals too small to fit typical items.
    let next = next_item_size as f64;
    if next > 0.0 && post < next {
        score += (next - post) * (1.5 + 2.0 * progress);
    } else if next > 0.0 && post >= next {
        // Reward bins that can also host the lookahead item.
        score -= 3.0 * (post - next) / cap;
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Slight penalty for spreading across many open bins when residuals are high.
    let norm_mean = mean_residual / cap;
    score += 0.4 * (open_bins_count as f64).sqrt() * norm_mean * progress;

    // Mild reward for tight fits (small item into small residual).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fill * fill * (1.0 - progress);

    // New-bin candidate: make it attractive only when fits are poor elsewhere.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: which "capacity fraction band" it lands in.
    // Residuals are graded by how likely future items (1..100) can use them.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -40.0 // perfect closure — ideal
    } else if pr < 10 {
        -25.0 // dead space but tiny; effectively closed bin
    } else if pr < 25 {
        15.0 // awkward small residual: only tiny items fit
    } else if pr < 40 {
        5.0
    } else if pr < 60 {
        0.0
    } else if pr < 80 {
        -8.0
    } else {
        -15.0 // large residual: very reusable
    };
    score += class_penalty;

    // Harmonic compatibility with lookahead item (k=2): reward residuals that
    // can exactly or comfortably host the next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            if slack == 0.0 {
                score -= 30.0; // next item closes this bin perfectly
            } else if slack < 10.0 {
                score -= 18.0; // near-perfect chaining
            } else {
                score -= 6.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Integer-division thresholds on post_residual vs item size class.
    let item_class = item_size / 20; // 0..4 harmonic class of current item
    let resid_class = pr / 20;
    score += ((item_class as i32 - resid_class as i32).abs() as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit,
    // unless this is genuinely the only fitting option (handled above).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 * pressure
            + 10.0 * (1.0 - progress) // early stream: prefer filling open bins
            + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild pull toward bins with residual close to the mean (balance preservation).
    score += ((post_residual as f64) - mean_residual).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be reused (below
    // the minimum item size) are pure waste -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(100)) && post_residual > 0 {
        // gap too small even for the smallest item: absolute dead space
        score += 40.0 + (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Penalize "awkward" gaps: small but nonzero residuals that likely become dead
    let r = post_residual as f64;
    if r > 0.0 && r < 25.0 {
        score += (25.0 - r) * 1.2; // smaller leftover => worse
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if r <= 10.0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, reward;
    // if next item cannot fit, the residual is likely dead -> penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid proliferation); with few open bins, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= pressure * 4.0;
    } else {
        // New-bin candidate: penalize more when many bins are already open,
        // and when the current bin could still hold future items.
        score += 10.0 + pressure * 5.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 8.0; // an existing bin could serve the next item too
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild global compactness: prefer bins below mean residual (tighter bins)
    score += (mean_residual - r) * 0.15;

    // Slight early-stream aggressiveness toward consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect chain match (item then next item exactly fills bin)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // chain closes perfectly after next item
        } else if post_residual > next_item_size {
            let leftover = (post_residual - next_item_size) as f64;
            // reward leaving room for the next item, scaled by how small the leftover is
            score -= 25.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize proportionally to the shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Reward bins tighter than the mean residual (good fits), penalize loose bins
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize new-bin opening unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // open a new bin when mean residual of open bins is small (dead space dominated)
        score += 20.0 - 45.0 * fragmentation - 10.0 * progress;
        // but if the item is large, opening a fresh bin is attractive
        score -= 0.1 * item_size as f64;
    }

    // Slight preference for filling large chunks of the bin
    score -= 0.05 * item_size as f64;

    // Mild penalty for creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if post_residual > next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with residuals far below mean (consolidate small leftovers)?
    // Prefer bins with residuals near mean to keep bin pool homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 15.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        score += new_bin_penalty;
        // But allow new bin if this item is huge and would leave awkward residue
        if item_size >= 60 && next_item_size > post_residual.min(40) && fitting_bins_count > 2 {
            score -= 18.0;
        }
    }

    // Slight preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize wasted residual, but with non-linear (quadratic) growth
    let mut score = pr_norm * (1.0 + 1.5 * pr_norm);

    // Smooth stream-progress coupling: later in the stream, dead space matters more
    score *= 1.0 + 0.8 * progress * pr_norm;

    // Reward tight fits: subtract bonus that grows as post_residual shrinks (non-linear)
    score -= 2.0 * (1.0 - pr_norm).powi(2) * fit;

    // Lookahead coupling: if next item can fit in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 * (next_item_size as f64 / cap);
    }

    // Penalize leaving residual that no plausible next item fits (smooth saturation)
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 0.4 * pr_norm;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.02 * open_bins_count as f64 * pr_norm;

    // Mean-residual coupling: prefer bins deviating from mean to balance residuals
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: make it mildly attractive early, unattractive late
    if bin_residual == bin_capacity {
        score = 0.9 + 0.8 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity quarters.
    let q = bin_capacity / 4;
    let class = (post_residual / q) as f64;
    score += class * 3.0; // prefer bins whose leftover falls in a lower harmonic class

    // Reward near-perfect fills (post_residual in smallest harmonic band).
    if post_residual <= q / 2 {
        score -= 25.0;
    } else if post_residual % q == 0 && post_residual > 0 {
        // leftover exactly a quarter-multiple: still usable for small items
        score -= 8.0;
    } else {
        // dead-space penalty: leftover in an awkward band
        score += (post_residual % q) as f64 * 0.4;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 + slack * 0.15;
            // harmonic match: next item lands in same quarter class
            if (next_item_size / q) == (post_residual / q) {
                score -= 6.0;
            }
        } else {
            score += 10.0; // next item cannot follow here
        }
    } else {
        score -= 5.0; // last item: just fill anything tightly
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    score += (open_bins_count as f64) * 0.5;

    // Prefer bins whose residual is below the mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-40.0).min(40.0) * 0.3;

    // Early in stream: be pickier about dead space; late: just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 20.0 };
        score = cap * 0.75 + pressure + (open_bins_count as f64) * 0.3;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps harder (dead space below typical item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins when a new bin is cheap.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 2.0;
    } else {
        // New bin: mild baseline so it's chosen only when fits are bad.
        score += 15.0;
    }

    // Prefer filling bins with larger residuals (waste reduction) relative to mean.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post residual small relative to item).
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score -= 8.0 / (1.0 + tightness);

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 20.0; // perfect chain: next item fills this bin exactly
        } else if diff > 0 && (diff as u32) < item_size.max(next_item_size) {
            score -= 10.0 / (1.0 + diff as f64); // next item still fits well
        } else if diff < 0 {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 2.0 + (-diff as f64) * 0.05;
        }
        // if post_residual too small for anything useful, penalize dead space
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
    } else {
        // last item: pure tight fit preference
        score -= 5.0 / (1.0 + post_residual as f64);
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual > 0 && (post_residual as i64 - next_item_size as i64).abs() > 20;
        if bad_fit && fitting_bins_count <= 2 {
            score -= 4.0; // allow opening a new bin when fits are poor
        } else {
            score += 10.0; // discourage wasting fresh bins on decent fits
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 / (1.0 + post_residual as f64));

    // Many open bins: prefer filling existing ones over spreading
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of residual consumed
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_frac;

    // Penalize small dead space that nothing can use (waste pockets)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        }
        // If next item would not fit here, mild penalty proportional to leftover
        if next_item_size > post_residual {
            score += 5.0 * post_residual as f64 / 100.0;
        }
    }

    // Last chance: this is the only bin that fits; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 60.0;
        // Cheaper to open a bin when few bins open or late in stream
        score -= 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Prefer new bin if current bin would leave large unusable residue
        if post_residual < 20 && post_residual > 0 {
            score -= 80.0;
        }
        // If next item is large, a fresh bin is useful
        if next_item_size >= 70 {
            score -= 40.0;
        }
    }

    // Global state coupling: spread items across bins when mean residual is high
    score += 0.2 * (mean_residual - post_residual as f64);

    // Time horizon: early in stream, be more conservative about fragmentation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - post / cap;

    // Base: prefer tight fits, but with non-linear (quadratic/cubic) shaping
    let mut score = post * (1.0 + 0.9 * fill * fill) + 8.0 * fill * fill * fill;

    // Smooth progress coupling: later in the stream, waste is more costly
    let progress_coupling = 1.0 + 1.2 * progress * progress;
    score *= progress_coupling;

    // Penalize post-residual that is too small to be useful for the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (nxt - post) / cap;
        } else {
            // Reward leaving room for the next item
            score -= 5.0 * (post.min(nxt * 2.0) / nxt - 1.0).max(0.0) * 0.5;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins vs. mean residual alignment
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;
    score += 0.4 * open_bins_count as f64;

    // New-bin candidate: smooth gate — open a new bin when item is large relative
    // to typical residuals and stream is not near the end
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);
        score = 0.55 * cap * (1.0 - openness) + post * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions (C/10 buckets)
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..=9 harmonic class
    // Non-linear penalty per class: small residuals (< ~15) are dead space
    if post_residual > 0 {
        if post_residual < 15 {
            score += 40.0 * (15.0 - post_residual as f64);
        } else if post_residual <= 20 {
            score -= 10.0; // sweet spot: leaves room for mid-size items
        } else {
            score += 0.35 * class as f64;
        }
    } else {
        score -= 60.0; // perfect fit, best outcome
    }

    // Lookahead: does next_item_size fit the post_residual exactly or well?
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 55.0; // chains a perfect fit
        } else {
            score -= 25.0 - 0.3 * slack as f64;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin: mild penalty scaled by how far off
        score += 0.25 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling already-open bins when many are open
    score += 1.5 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin unless this item is huge relative to capacity
        // or all existing fits would leave tiny dead space
        let best_possible = if post_residual == bin_capacity { 0.0 } else { 0.0 };
        let _ = best_possible;
        let dead_elsewhere = mean_residual - item_size as f64;
        if dead_elsewhere < 15.0 && fitting_bins_count >= 1 {
            // existing fits would be wasteful; new bin is fine
            score -= 20.0;
        } else {
            score += 45.0 + 0.5 * open_bins_count as f64;
        }
        // never open a new bin for a tiny item
        if item_size <= 40 {
            score += 60.0;
        }
    }

    // Stream progression: early on, be conservative about new bins (handled above);
    // late in stream, tighten packing further
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold coupling between post_residual and next_item_size
    if next_item_size > 0 {
        let pr_half = post_residual / 2;
        if next_item_size <= pr_half {
            score -= 8.0; // next item uses at most half the leftover: flexible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical items are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Perfect / tight fits are rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack.min(12.0);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Last chance bin: avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Pressure from number of open bins: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.15;

    // Prefer bins below mean residual (filling emptier bins spreads load poorly).
    score += (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate: make an empty bin moderately attractive only when residuals are tight.
    if bin_residual == bin_capacity {
        let tight = if post_residual > 0 { 0.0 } else { 1.0 };
        score += 5.0 - tight * 10.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but strongly reward
    // post_residual that exactly matches the next item's size (2-step lookahead).
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    if next_item_size > 0 {
        let diff = (pr - nis).abs();
        // Perfect match for next item: heavy reward.
        if diff < 1.0 {
            score -= 60.0;
        } else if pr >= nis {
            // Next item still fits after this placement: moderate reward,
            // scaled by how close the match is.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover dead space relative to mean residual.
            score += 10.0 + (pr / mean_residual.max(1.0)) * 8.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Penalize creating tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild pressure to consolidate into already-open bins vs. opening new ones:
    // make the empty new-bin candidate slightly less attractive unless it gives
    // a perfect next-item match.
    if bin_residual == bin_capacity {
        score += 5.0;
        if next_item_size > 0 && (pr - nis).abs() < 1.0 {
            score -= 70.0;
        }
    }

    // Stream progression: early on, be slightly more willing to open bins
    // (spread large items); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    // Reward bins with residual already below mean (efficiently filled bins).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing here would block the next item; slight penalty.
            score += 10.0;
        }
    }

    // Global state coupling: when mean residual is high, avoid fragmenting bins.
    let mean_gap = mean_residual - post_residual as f64;
    if mean_gap > 0.0 {
        score += 0.15 * mean_gap;
    } else {
        score -= 0.10 * (-mean_gap);
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * tightness;

    // When many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 8.0 + 2.0 * pressure;
        // But allow a new bin if the item is large and would leave a bad remainder.
        if item_size > bin_capacity / 2 && post_residual < 20 {
            score -= 30.0;
        }
    }

    // Mild penalty scaled by item size to prefer filling bins with big items first.
    score += 0.05 * item_size as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    let mut score = r;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = rn * rn * (1.0 - rn) * (1.0 - progress * 0.5);
    score -= 12.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - rn;
    score -= tightness * tightness * (1.0 + progress) * 4.0;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 {
        let can_fit_next = (post_residual as u32) >= next_item_size;
        if !can_fit_next {
            score += 6.0 + 8.0 * rn;
        } else {
            score -= 3.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open relative to progress
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: prefer it only when residuals elsewhere are large
    if bin_residual == bin_capacity {
        score = r + mean_residual * 0.3 + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: partition sizes into residue classes mod 10
    let item_class = item_size % 10;
    let next_class = next_item_size % 10;

    // Perfect fit bonus: post_residual in harmonic small classes is valuable dead space
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize dead space that cannot host the next item (lookahead coupling)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Modulo-class complementarity: reward bins whose post_residual is a
    // plausible harmonic complement of the next item's class
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 10 == 0 {
            score -= 4.0; // round residuals pair well with class-aligned items
        }
    }

    // Integer-division threshold: residual thirds / quarters
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual > 0 && post_residual < quarter {
        score += 10.0; // tiny unusable sliver
    } else if post_residual >= third && post_residual <= bin_capacity / 2 {
        score -= 5.0; // sweet-spot residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.5 + progress);

    // New-bin candidate should only win when the fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.1;
        if post_residual > bin_capacity - item_size {
            // unreachable, safety
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual gaps too small for typical
    // future items are effectively wasted capacity — penalize them hard.
    if post_residual > 0 {
        // Gap unusable for the lookahead item and for small items (<= 10):
        if post_residual < 10 {
            score += 40.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Gap can't hold the next item: potential dead space
            score += 15.0 * (1.0 - post_residual as f64 / 10.0);
        } else if next_item_size > 0 && post_residual == next_item_size {
            // Perfect lookahead fit: reward strongly
            score -= 60.0;
        } else if next_item_size > 0 && post_residual - next_item_size < 10 {
            // Fits next item but leaves a new tiny gap
            score += 10.0;
        }
    } else {
        // Perfect fill: best possible outcome
        score -= 100.0;
    }

    // Reward tight fits relative to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * bin_pressure * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // and mean residual is low (existing bins nearly full).
        score += 25.0 - 10.0 * (mean_residual / bin_capacity as f64);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin can host a perfect pair: mildly attractive
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Post-residual can still fit the next item (partial lookahead credit).
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Tighter fit for next item is better; reward decays with slack.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Dead space: post_residual too small for any plausible future item.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        // Penalize unusable residue more when it's tiny (wasted capacity).
        score += 40.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Prefer filling bins below the mean residual (pack tight bins first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in stream: encourage opening bins to spread load; late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize late in stream, mild early.
        score += 80.0 * (0.3 + 0.7 * progress);
        // But if nothing fits well anywhere, opening a new bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Slight bonus for high fill ratio.
    score -= 0.3 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less wasted space relative to capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // bin remains useful
        } else {
            score += 0.5 * (post_residual as f64); // stranded dead space
        }
    } else {
        // Last item: fill bins as completely as possible.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    // (large post_residual) or the bin is effectively empty anyway.
    if bin_residual == bin_capacity {
        // Empty bin: score = capacity - item_size; make it competitive only for bad fits.
        let fit_quality = 1.0 - tightness;
        score -= 40.0 * fit_quality * fit_quality;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer placing into bins with below-average residual (consolidate waste).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // Penalize extremely small unusable remnants.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let poly = 1.0 + 0.6 * p2 + 0.9 * p3;

    let mut score = pr * poly;

    // Penalize large dead space more than linearly (quadratic waste term)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: penalize leaving a bin that is the only fitting option
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can fit into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 15.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mild preference for bins below mean residual (consolidate space)
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: smooth penalty growing with number of open bins
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt() + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "dead zones"
    // (very small, unusable slivers) are penalized; mid-range leftovers rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure is ideal
    } else if pr < 10 {
        score += 45.0; // dead sliver: unusable space
    } else {
        // quantize leftover into capacity-fraction classes (1/8 granularity)
        let frac = (pr as f64) / cap;
        let class = (frac * 8.0).floor() as i64; // 0..7
        // reward classes that match common item-size harmonics (10..80 in eighths: 0.1..0.8)
        let harmonic = match class {
            0 => 6.0,  // 0..12.5 fits small items
            1 => 4.0,  // 12.5..25
            2 => 2.0,  // 25..37.5
            3 => 0.0,
            4 => -2.0, // sweet zone ~50
            5 => 0.0,
            6 => 3.0,
            _ => 8.0,  // >87.5 leftover means we barely used the bin
        };
        score -= harmonic;
    }

    // Integer-division threshold coupling: leftover divisible by common sizes is reusable
    if pr >= 10 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty scaled by how much it overshoots
            score += 6.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling already-open bins when many are open (avoid bin proliferation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * (open_bins_count as f64) * (0.5 + progress);

    // Deviation from mean residual: bins far tighter than average are good targets
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item is large relative to capacity and existing fits are poor.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        // base penalty so new bins aren't opened frivolously
        score += 40.0;
        // but large items benefit from a fresh bin
        score -= 70.0 * size_frac * size_frac;
        // late in stream with many open bins, discourage new bins more
        score += 15.0 * progress;
        // if few bins fit the item, a new bin is more acceptable
        if fitting_bins_count <= 1 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling bins tightly relative to mean residual (compactness pressure).
    score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item fits current bin but not post_residual: mild penalty for wasting gap.
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly (large dead space risk).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual < item_size as f64 * 0.5;
        if poor_fit_elsewhere {
            score -= 10.0;
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits but with slack: mild reward proportional to tightness
            let slack = post_residual as f64 - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving dead space
            score += 8.0 + 0.15 * post_residual as f64;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.3 * (mean_residual - pr);
    } else {
        score += 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating very small unusable dead space (waste).
    if pr > 0 && pr < 10.0 {
        score += 12.0;
    }

    // Early in stream: slightly discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize less when post_residual is small relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (waste), but not perfect fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward residuals.
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 10.0;
            }
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor tight fits later when consolidation matters).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * fit_ratio;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer bins below the mean
    // (consolidate fragmentation); if low, prefer larger residuals.
    if bin_residual as f64 > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 15.0 + 0.3 * item_size as f64 * (1.0 - fit_ratio) };
        score += desperation;
        // Early stream: new bins are cheap; later: expensive.
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate loose fits; late, penalize them harder
    let late_bias = 1.0 + 1.5 * progress * progress;
    score *= late_bias;

    // Penalize dead space relative to mean residual of open bins
    score += 0.4 * (pr - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item can fit in the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (1.0 - pr / cap);
    }

    // Discard spreading across too many bins when a tight fit exists
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // New-bin candidate handling: make empty-bin attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        score = 60.0 + 40.0 * progress - 55.0 * scarcity - (item_size as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common size
    // classes (10s, 25s, 50s) are more reusable by future items.
    let post = post_residual;
    if post == 0 {
        score -= 40.0; // perfect fit, always reward
    } else {
        let class_bonus: f64 = if post % 50 == 0 {
            18.0
        } else if post % 25 == 0 {
            12.0
        } else if post % 10 == 0 {
            8.0
        } else if post % 5 == 0 {
            4.0
        } else {
            0.0
        };
        score -= class_bonus;

        // Dead space penalty: small odd residues are hard to reuse.
        if post < 10 {
            score += 25.0 * (10 - post) as f64;
        } else if post < 20 && post % 5 != 0 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this placement (chain fit).
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 30.0;
        } else if post > next_item_size {
            let rem = post - next_item_size;
            if rem % 10 == 0 || rem == 0 {
                score -= 10.0;
            }
            score += rem as f64 * 0.15; // discourage leaving awkward chain remainder
        } else {
            // next item cannot use this bin's remainder; mildly penalize
            // wasting space the next item might have needed elsewhere.
            score += (next_item_size - post) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item is large relative
    // to capacity or open bins are congested with small residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.5;
        let bias = 60.0
            - 25.0 * poor_fits
            - 20.0 * congestion
            - (if big_item { 15.0 } else { 0.0 })
            - 10.0 * progress;
        score += bias;
    }

    // Slight preference for bins below mean residual (tighter bins get
    // filled first, keeping loose bins flexible).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap that cannot fit even the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderately small gaps are also risky dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit gets a strong reward (subtract).
    if post_residual == 0 {
        score -= 100.0;
    }

    // If the lookahead item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5 + 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit: penalize proportionally to wasted gap.
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins, but allow new bins when current fits are poor.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted when the
        // current bin's post-residual would be bad dead space.
        score += 30.0 + 10.0 * pressure;
        if post_residual >= 0 && post_residual < 10 {
            score -= 50.0; // fresh bin keeps full flexibility
        }
    } else {
        score += 2.0 * pressure;
    }

    // Tight-fit bonus: reward placements that leave less than half capacity.
    if post_residual < bin_capacity / 2 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: if the next item fits exactly into post_residual, heavily reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well next item fills the leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // Next item cannot use this residual: penalize large dead space.
            score += 0.15 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    }

    // Prefer bins whose residual is below the mean residual (tight packing).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless it is genuinely needed or item is huge.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // New bin is attractive only for very large items or when few bins fit.
        score += 20.0 - 30.0 * tightness;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheaper; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty for leaving tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable dead space (residual too small for any realistic item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item can fit in the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // penalize blocking the next item slightly, scaled by how much it blocks
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    } else {
        // last item: prefer tightest fit even more aggressively
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins whose residual is already below average (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Slight preference for reusing bins vs opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more heavily as stream progresses
        score += 10.0 + 40.0 * progress;
    } else {
        score -= 5.0 + 10.0 * progress;
    }

    // Mild penalty proportional to number of open bins to discourage fragmentation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, but non-linearly (dead space punished super-linearly)
    let mut score = pr_norm.powi(2) * 100.0 + pr_norm * 30.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste matters more (no future to amortize it)
    let progress_coupling = pr_norm * (1.0 + 2.0 * progress * progress + 1.5 * progress);
    score += progress_coupling * 40.0;

    // Perfect fit reward, stronger as stream progresses
    let fit_quality = 1.0 - pr_norm;
    score -= fit_quality * fit_quality * (30.0 + 40.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).sqrt() * fit_quality * 5.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = pr - ns;
            score -= 25.0 * (1.0 - slack / cap) * (1.0 + progress);
        } else {
            // penalize leaving residual too small for the known next item
            score += 10.0 * (1.0 - pr / ns.max(1.0)) * (0.5 + progress);
        }
    }

    // Mild bonus for bins below mean residual (keep balanced spread)
    score += (mean_residual - bin_residual as f64) / cap * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Reward residuals that land in "usable" harmonic classes (large enough for typical items)
    if class >= quarter / 2 {
        score -= 8.0;
    } else if class < 10 {
        // dead-space penalty for tiny unusable remainders
        score += (10 - class) as f64 * 2.0;
    }

    // Perfect-fit harmonic classes via integer division thresholds
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if post_residual <= 20 {
        score -= 5.0; // still fits small items
    }

    // Coupling with lookahead: can next item land exactly in the residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) % quarter;
            if nxt_class < 10 { score += 6.0; } else { score -= 4.0; }
        } else {
            score += 3.0; // next item cannot reuse this bin
        }
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling existing bins when many are open; new bin (residual==capacity) penalized
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64) * 0.5;
    } else {
        score -= 2.0;
    }

    // Mean-residual coupling: keep score aligned with global slack
    score -= 0.05 * mean_residual;

    // Late-stream tightening: push toward tighter packs as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are worthless — apply a heavy non-linear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }
    // Residuals below the "double dead zone" (can't hold two small items) get a
    // moderate penalty scaled by how far into the stream we are.
    if post_residual >= 10 && post_residual < 20 {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * (0.5 + progress);
    }

    // Reward exact-ish fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + (post_residual as f64) * 0.2;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Lookahead: if the next item fits the post-residual exactly, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mean-residual coupling: placing into a bin below the mean residual
    // (i.e., a fuller bin) is preferred — tighten packing.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual) or no good alternative exists.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 25.0;
        if poor_fit {
            score -= 8.0;
        } else {
            score += 30.0;
        }
        // Early in the stream, opening bins is cheap; later, avoid it.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) with a mild non-linear bonus.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item completion
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how little slack remains after both
            let after2 = (post_residual - next_item_size) as f64;
            score -= 20.0 + (bin_capacity as f64 - after2) * 0.2;
        } else {
            // next item cannot use this bin's remainder: penalize dead space
            let dead = (post_residual as f64 - bin_capacity as f64 * 0.1).max(0.0);
            score += dead * 0.5;
        }
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Penalize opening a brand-new bin unless current bins are quite full.
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - (bin_residual as f64 - post_residual as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize low post-residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: small post_residual that cannot hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty if we leave big gap
            score += 5.0;
        }
    }

    // Global state: when many bins are open relative to progress, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    score += pressure * 20.0 * (1.0 - progress);

    // Compare against mean residual: bins with residual far below mean are scarce space.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // New-bin candidate handling: empty bin gets baseline score plus penalty
    // so it's chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        if progress > 0.8 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - progress) + pr * progress;
    score += poly * (bin_capacity as f64) * 0.5;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - pr;
    score -= tightness * tightness * (1.0 + progress) * 5.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
        score += waste * waste * 10.0 * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many bins
    score += open_bins_count as f64 * 0.05 * progress;

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += dev * dev.abs() * 8.0;

    // New-bin candidate: penalize slightly so we prefer reusing bins unless waste is high
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left

    // Dead-space penalty: small leftovers (< 10) are nearly unusable.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    } else if post_residual <= 25 {
        score += 8.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    let tightness = 1.0 - (post_f / (bin_residual as f64).max(1.0));
    score -= 40.0 * tightness;

    // Harmonic class via integer division: post_residual bucketed in steps of 10.
    let class = post_residual / 10;
    // Odd classes (mid-range leftovers like 30-40, 50-60) pair well with many sizes; even extremes worse.
    if class % 2 == 0 && post_residual > 0 {
        score += 6.0;
    } else {
        score -= 4.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; reward proportionally to how well it fits.
            let slack = post_residual - next_item_size;
            score -= 30.0 - (slack as f64).min(25.0);
            // Bonus if next item exactly consumes the remainder (perfect pairing).
            if slack == 0 {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; penalize if leftover becomes stranded.
            score += 12.0;
        }
    } else {
        // Last item: just prefer minimal leftover.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline penalty so we prefer
    // open bins unless they fit poorly; but reward opening when existing bins would strand space.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If no open bin fits well (post_residual in open bins would be tiny), opening is fine.
        if post_residual >= 20 && open_bins_count > 0 {
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Stream progression: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // Mean residual context: if this bin is far below mean residual, it's a good "garbage absorber".
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Many open bins: prefer filling existing ones rather than opening more.
    if open_bins_count > 4 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using bins that would otherwise be "wasted" (large residual).
    let large_residual = bin_residual as f64 > 60.0;
    if large_residual {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item would leave an even worse gap, penalize slightly.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 6.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        } else if pressure < 15.0 {
            score -= 5.0; // open bins nearly full, new bin reasonable
        } else {
            score += 20.0; // prefer existing bins otherwise
        }
    }

    // Mild stream-progression adaptation: later in stream, be more conservative.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward post_residual matching next_item_size ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect 2-step chain: item + next item exactly fills the bin
        if diff < 0.5 {
            score -= 45.0 + 10.0 * (1.0 - progress);
        } else if nxt <= pr {
            // next item fits: reward tighter matches
            let rel = diff / bin_capacity as f64;
            score -= 12.0 * (1.0 - rel).powi(3);
        } else {
            // next item does NOT fit: penalize leaving residual that is
            // simultaneously too small for the next item (dead space)
            let dead = (pr - (nxt % bin_capacity as f64)).min(pr);
            score += 0.25 * dead;
        }
    } else {
        // Last item: pure tight-fit reward
        score -= 20.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(2);
    }

    // ---- Tight fit reward relative to current residual ----
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio.powi(2);

    // ---- Relative to mean residual: prefer bins below-average residual (tighter bins) ----
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 6.0 * (rel - 1.0).abs();
        // slight preference for using tighter-than-average bins
        score -= 4.0 * (1.0 - rel).max(0.0);
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly prefer it ----
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // with alternatives, be pickier about fit quality
        score += 3.0 * fitting_bins_count as f64;
    }

    // ---- New-bin candidate handling: empty bin ----
    if bin_residual == bin_capacity {
        // Prefer opening a new bin when current fit is poor (large post_residual
        // dead space) or the item fits nothing well; otherwise prefer existing bins.
        let poor_fit = post_residual as f64 > 0.0
            && next_item_size > 0
            && (post_residual as f64) < next_item_size as f64;
        let pressure = if open_bins_count == 0 { 1000.0 } else { 0.0 };
        if poor_fit {
            score -= 18.0 + 8.0 * progress;
        } else {
            // default: mildly discourage opening new bins when fits exist
            score += 10.0 + 5.0 * (1.0 - progress);
        }
        score += pressure;
    }

    // ---- Late-stream consolidation: keep residuals usable ----
    if progress > 0.7 {
        score += 0.05 * post_residual as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
        } else {
            // Reward bins whose leftover can host the lookahead item.
            score -= 6.0;
        }
        // Reward exact pairing: leftover just fits next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity / 3 {
        score -= 10.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Open new bin late in stream only if item is large and bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 20.0 * progress;
        }
    }

    // Global fragmentation pressure: many open bins with high mean residual -> prefer consolidating.
    let frag = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    score += 0.5 * frag;

    // Prefer bins whose residual deviates from mean (match similar fill levels).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Small-item handling: avoid wasting large residuals on tiny items.
    if item_size <= 10 && bin_residual > 60 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits (low post_residual) strongly.
    // Late stream: tolerate moderate residuals to avoid opening extra bins.
    let w = 12.0 * (1.0 - progress) * (1.0 - progress);
    score += w * norm_pr * norm_pr * cap;

    // Smooth reward for residuals that could still fit a mid-sized future item.
    let fit_window = (norm_pr - 0.3).abs();
    score -= 6.0 * (1.0 - fit_window * fit_window).max(0.0);

    // Penalize dead space (residual too small for any item).
    if norm_pr < 0.1 {
        score += 8.0 * (0.1 - norm_pr) * cap;
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item, smoothly.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let slack = ((post_residual as f64 - next_item_size as f64) / cap).max(0.0);
        score -= fits_next * (4.0 + 6.0 * (1.0 - slack * slack));
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Deviation from mean residual: prefer bins near the mean (balance).
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small usable" classes are favored (dead space is quantized).
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: perfect or near-perfect packing.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Modulo-10 harmonic classes: leftover sizes divisible into small chunks
    // (multiples of 10) are more reusable by typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize awkward odd leftovers in the mid range.
    if post_residual % 2 == 1 && post_residual > 20 && post_residual < 50 {
        score += 6.0;
    }

    // Integer-division thresholds: leftover in [25,50) is semi-usable,
    // leftover >= 60 is very reusable.
    let div_class = post_residual / 25;
    match div_class {
        0 => score -= 5.0,           // tiny leftover, good
        1 => score += 0.0,           // neutral
        2 => score += 3.0,           // moderate dead space
        _ => score -= 10.0,          // large residual, bin still flexible
    }

    // Lookahead coupling: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if next item fills the bin almost exactly.
        let nr = post_residual - next_item_size;
        if nr <= 5 {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize proportionally to wasted potential.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it when the stream is young and residual
    // fragmentation is high; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + progress * 30.0 - mean_residual * 0.2;
        // If many bins fit the item, opening a new bin is wasteful.
        score += fitting_bins_count as f64 * 10.0;
        // Early on, opening fresh bins builds a diverse residual pool.
        if progress < 0.2 {
            score -= 15.0;
        }
        // If no other bin gives a tight fit, new bin looks better.
        if post_residual > 40 {
            score -= 10.0;
        }
    }

    // Mild preference for fuller bins overall (relative fill).
    score -= (1.0 - frac) * 5.0;

    // Tie-break with mean residual: when mean residual is low, keep tight fits.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; new bins get penalized.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        score += open_pressure + 25.0;
    } else {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        } else if (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 10.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0; // gap too small for lookahead item
        }
    }

    // Early in the stream, be slightly more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Prefer bins tighter than the mean residual (better packing candidates).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * next_item_size as f64;
            // exact match of post_residual to next item is ideal
            score -= 30.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Penalize small unusable residuals (dead space that nothing can fill later)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins that are tighter (below mean residual)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        // baseline penalty so new bins are opened only when beneficial
        score += 20.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // opening a fresh bin lets both items pack together
            score -= 10.0;
        }
    }

    // Mild late-stream consolidation: favor existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize leaving dead space that cannot fit the smallest plausible item (1..=100 stream).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: bonus if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains where the follow-up item also fits this bin.
            let gap = (post_residual - next_item_size) as f64;
            score -= (1.0 - gap / bin_capacity as f64) * 12.0;
        } else {
            // Penalize post-residuals that cannot host the lookahead item.
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of open bins exist (fragmentation control).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bins and mean residual.
        score += 10.0 + open_bins_count as f64 * 3.0;
        if mean_residual > item_size as f64 {
            score += 20.0; // existing bins have room; opening new bin is wasteful
        }
    } else {
        // Reward using existing bins, more so as stream progresses (horizon effect).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // Slight preference for bins whose residual deviates below mean (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild penalty for very large open_bins_count (too many bins open).
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: as stream progresses, penalize larger residuals more strongly.
    let prog_coupling = 1.0 + 2.0 * progress * progress;
    score *= prog_coupling;

    // Reward near-perfect fits with a smooth exponential term.
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Dead-space penalty: post_residual too small for likely future items.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let waste = (ns - pr).max(0.0) / cap;
        score += 25.0 * waste * waste * (1.0 + progress);
    }

    // Slightly favor bins whose residual deviates from the mean (consolidation).
    let dev = (mean_residual - pr) / cap;
    score -= 5.0 * dev * dev;

    // Mild penalty for proliferating bins when many are open.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make it moderately attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        score = pr + 20.0 + 30.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division classes: residual in {0..9,10..19,...} -> dead-space severity.
    let class = (post_residual / 10) as f64;
    score += class * 0.35;

    // Reward near-exact fills (post residual in a tight harmonic band).
    if post_residual <= 2 {
        score -= 12.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Penalize residuals that no future small item (min size 1) can pair with efficiently:
    // dead space in (5, 15) is the worst "unusable" band.
    if post_residual > 5 && post_residual < 15 {
        score += 8.0;
    }

    // Modulo coupling: does next_item_size fit into post_residual? Big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 5.0 + (post_residual - next_item_size) as f64 * 0.2;
        } else {
            score += 4.0;
        }
        // Perfect chain: next item exactly consumes the remainder.
        if next_item_size == post_residual {
            score -= 10.0;
        }
        // Harmonic divisibility: residual divisible by next item size.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // pairing large with large in fresh bin
        }
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - frac * 10.0) * 0.05;

    // Prefer filling bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 120.0; // perfect two-item closure
        } else if diff <= 5.0 {
            score -= 60.0 * (1.0 - diff / 5.0);
        } else {
            // penalize residuals that are slightly too small to fit next item (dead space)
            if (post_residual as f64) < nxt && (post_residual as f64) >= nxt - 10.0 {
                score += 25.0;
            }
            score += diff * 0.15;
        }
        // residual that can't fit next item nor typical items is dead space
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins below-average residual (denser bins)
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin: strong bonus to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current item is huge relative
    // to all residuals (handled implicitly); add mild penalty scaled by open bins
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if item is large and would leave awkward residual elsewhere, opening is fine
        if item_size >= 60 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Early in stream, allow more bins for flexibility; late, consolidate tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., mean residual is small relative to the item) or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (item_size as f64 - mean_residual).max(0.0);
        score += 30.0 - 0.5 * scarcity - 10.0 * progress - 2.0 * open_bins_count as f64;
    } else {
        // Mildly prefer fuller bins among open ones (best-fit bias).
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;
    }

    // Tie-breaker: prefer bins that keep mean residual balanced.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = pr / cap;

    // Base: quadratic penalty on post residual (dead space), smoothed by progress
    let mut score = pr * (1.0 + 0.9 * fit_frac * fit_frac);

    // Non-linear coupling: residual usefulness decays with stream progress
    let decay = 1.0 - 0.5 * progress * progress;
    score -= decay * fit_frac * (cap - fit_frac * cap) * 0.5;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Penalize fragmentation relative to mean residual of open bins
    score += 0.3 * (pr - mean_residual).abs();

    // Mild new-bin penalty so open bins are preferred unless fit is terrible
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward (harmonic anchor: post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "useful" residue class (divisible into common small sizes) are favored.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for d in [10u32, 20, 25, 50].iter() {
        if pr > 0 && pr % d == 0 {
            harmonic_bonus += 8.0;
        }
    }
    // Small dead space is worse than a classically divisible leftover of same size
    if pr > 0 && pr < 10 {
        harmonic_bonus -= 15.0;
    }
    score -= harmonic_bonus;

    // Integer-division threshold on post_residual: leftover >= 25 is reusable
    if pr >= 25 {
        score -= 6.0;
    } else if pr > 0 {
        score += 4.0 * (10 - pr) as f64 / 10.0;
    }

    // Coupling with next item: if the next item exactly fills post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after chain matters
            let chained = pr - next_item_size;
            score -= 12.0 - (chained as f64) / 10.0;
        } else {
            // next item cannot use this leftover: penalize large stranded space
            score += (pr.min(next_item_size - 1) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large post_residual).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave open bins fragmented. Empty-bin residual == capacity.
    if bin_residual == bin_capacity {
        // Waste of a fresh bin scales with how much of it the item leaves empty
        score += (bin_capacity - item_size) as f64 * 0.5;
        // But if item is huge, a fresh bin is fine
        if item_size >= 60 {
            score -= 30.0;
        }
        // Early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Prefer filling bins below mean residual (balance fragmentation)
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // Modulo threshold on item size: items in "awkward" classes (>50, not dividing 100)
    // should go into bins where they leave divisible leftovers.
    if item_size > 50 && item_size % 10 != 0 {
        if pr % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mild pressure to keep number of open bins low
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: penalize unusable small gaps.
        // A residual gap is "unusable" if it is smaller than the smallest
        // plausible item (min item size 1, but typical items are larger);
        // the smaller and more isolated the gap, the bigger the penalty.
        let gap = post_residual as f64;
        if gap < 10.0 {
            // tiny sliver: nearly useless
            score += (10.0 - gap) * 12.0;
        } else if gap < 20.0 {
            // small gap: only fits tiny items
            score += (20.0 - gap) * 4.0;
        } else if gap < 35.0 {
            // medium-dead zone: risky
            score += (35.0 - gap) * 1.5;
        }

        // Lookahead coupling: if the next item fits exactly in the
        // post-residual, reward heavily (chain perfect fits).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // mild reward if next item still fits after this placement
            let slack = post_residual - next_item_size;
            score -= (slack as f64).min(20.0) * 0.5;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; penalize creating a gap
            // that nothing else may use
            score += 8.0;
        }

        // Last-chance bonus: if this is the only bin that fits, avoid
        // opening a new bin unless the fit is terrible.
        if fitting_bins_count == 1 {
            score -= 60.0;
            // but if the resulting gap is dead space, partially cancel
            if gap < 10.0 {
                score += (10.0 - gap) * 6.0;
            }
        }

        // Open-bin pressure: discourage spreading across many bins when
        // a tight fit exists; encourage consolidating into fuller bins.
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= fullness * (open_bins_count as f64).sqrt() * 6.0;

        // Mean-residual coupling: prefer bins whose residual is below the
        // mean (i.e., fuller than average) to keep residual variance low.
        score += (mean_residual - bin_residual as f64) * 0.8;
    }

    // New-bin candidate handling: an empty bin is a fresh start; only
    // prefer it when no open bin gives a decent fit. Penalize opening a
    // new bin mildly, more so early in the stream when consolidation is
    // cheap, less so when many bins are already open and gaps abound.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * 0.9
            + open_bins_count as f64 * 2.0
            - progress * 30.0;
        // if next item is large, a fresh bin is more valuable
        if next_item_size > 60 {
            score -= 40.0;
        }
        // never allow new bin to win when a perfect fit exists elsewhere
        if post_residual == 0 && bin_residual != bin_capacity {
            score += 2000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 60.0 - (chain_waste as f64) * 1.5;
        } else {
            // next item cannot chain here; penalize dead space relative to next size
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // last item: only tightness matters
        score += 10.0;
    }

    // Penalize leaving residuals that are likely unusable (small leftovers)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space
    }

    // Relative-to-mean coupling: prefer bins with residuals near mean (balance) unless tight fit
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        // new bin: neutral-ish base, but attractive if lookahead chains well into it
        score = 60.0 + (bin_capacity - item_size) as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0;
        }
        if fitting_bins_count <= 1 {
            score -= 70.0; // no good alternative: open new bin
        }
    }

    // Slight pressure against bin proliferation late in stream
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: moderate reward proportional to leftover slack.
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item won't fit here: penalize wasting space that could serve it.
        score += 8.0;
    }

    // Global balance: prefer bins whose residual is near the mean residual
    // (keeps bin states homogeneous, easier future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (exploration); later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus dynamic penalty.
        score = (bin_capacity as f64) * 0.9 + 20.0 * progress;
        // Opening a bin is more attractive when many items remain and few bins open.
        score -= 15.0 * (1.0 - progress);
        // Discard new-bin option if a good fit exists elsewhere.
        if tightness > 0.8 && fitting_bins_count >= 1 {
            score += 50.0;
        }
    } else {
        // Late stream: extra consolidation pressure.
        score += 10.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    // Mild penalty for very crowded bin pools to encourage spreading early.
    score += 0.01 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score -= 12.0 * (1.0 - progress) * norm_pr * (1.0 - norm_pr) * 4.0;
    score += 8.0 * progress * norm_pr * norm_pr;

    // Perfect fit reward, smoothly scaled by progress
    let fit_quality = 1.0 - (pr / cap).powi(2);
    score -= 20.0 * fit_quality * (0.5 + 0.5 * progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins deviating from mean residual (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let match_gain = 1.0 - ((pr - n) / cap).abs();
        score -= 10.0 * match_gain.max(0.0) * (1.0 - progress);
        if pr < n {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Mild penalty for hoarding many open bins late in stream
    score += 0.3 * (open_bins_count as f64).ln() * progress;

    // New-bin candidate: make it attractive only when residuals are tight
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap).min(1.0);
        score -= 5.0 * tight * tight;
        score += 4.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual falls in a "useful"
    // modular class (divisible by common small item sizes) are more valuable to keep.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 {
        0.0
    } else {
        25.0 + (10 - pr) as f64 * 4.0 // tiny dead space (<10, min item size): penalize hard
    };
    score += class_bonus;

    // Lookahead coupling: reward post_residual classes that the next item can exactly fill.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 5 == 0 {
            score -= 10.0;
        } else if pr < next_item_size && pr > 0 {
            score += 15.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fractional capacity logic: prefer filling bins past half capacity.
    let half = bin_capacity as f64 / 2.0;
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.5 {
        score -= fill_frac * 20.0;
    } else {
        score += (half - (bin_capacity - post_residual) as f64) * 0.3;
    }

    // Deviation from mean residual: bins tighter than average are better targets.
    score += (mean_residual - bin_residual as f64).max(0.0) * -0.2;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: keep it neutral-to-slightly-poor unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 18.0 - (fitting_bins_count as f64) * 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10, or smaller than next item)
    // are nearly useless -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward tight fits generally.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But allow opening when this item would leave a bad gap in any open bin.
        if post_residual > 0 && post_residual < 10 {
            score -= 45.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 12.0;
        }
    } else {
        // Mild reward for consolidating into existing bins when few are open.
        if open_bins_count > 1 {
            score -= 2.0;
        }
    }

    // Slight preference for bins below mean residual (spreading load evenly).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Late in stream: prefer exactness even more (less time to recover gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            // Next item can follow: reward tight matching between post_residual and next_item_size.
            let gap = post_residual as f64 - nxt;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain bonus: post_residual == next_item_size leaves a fully packed bin.
            if gap < 1.0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot fit here: penalize dead space creation.
            score += 4.0 + 0.05 * post_residual as f64;
        }
    } else {
        // Last item: reward minimal post residual (perfect fit).
        score += 0.0;
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize waste relative to the mean residual of open bins.
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred, reduced when item is large.
        score += 15.0 - 0.1 * item_size as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // Fresh bin can host item + next item: soften penalty.
            score -= 5.0;
        }
    }

    // Slight preference for tight fits overall.
    score += 0.02 * post_residual as f64;

    // Progress-aware tiebreak: as stream advances, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (bin_residual as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / cap;
    score -= (1.0 - fit_ratio).powi(3) * 12.0;

    // Penalize dead space that is too small to be useful later
    // (items are >= 1, but very small residuals below typical item sizes are waste).
    if post_residual > 0 {
        let waste = post_residual as f64;
        score += (waste / cap) * 8.0;
        if waste < 20.0 {
            score += (20.0 - waste) * 0.6; // small unusable gap penalty
        }
    } else {
        score -= 15.0; // perfect closure is excellent
    }

    // Last-chance bin: strongly prefer filling it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item cannot fit here anyway, mild bonus for using this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            score -= (1.0 - gap / cap).powi(2) * 10.0; // chain fit reward
        } else {
            score += 2.0;
        }
    } else {
        // Last item: just close as much space as possible.
        score -= 5.0;
    }

    // Global state: prefer placing into bins when many are open (reduce spread),
    // but allow opening new bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_f = open_bins_count as f64;
    score += open_f * (0.5 + 1.5 * progress);

    // New-bin candidate handling: make empty bin attractive only when current
    // bin fits are poor (large post residual) or item is large.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / cap; // = 1 - item/cap for empty bin
        let item_ratio = item_size as f64 / cap;
        let penalty = 18.0 + open_f * 2.0 - progress * 8.0;
        score += penalty * (0.3 + 0.7 * poor_fit) - item_ratio * 6.0;
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 4.0; // fresh bin can also host the next item
        }
    }

    // Mean residual coupling: if average residual is high, prefer bins that
    // reduce dispersion (post residual close to mean is fine; extremes penalized).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = norm_post * (1.0 + 0.8 * norm_post * (1.0 - progress));

    // Dead-space penalty: post_residual too small to fit the next item is wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size as f64 - post) / cap;
        score += waste * (1.5 + 2.0 * progress);
    }

    // Reward using bins that would otherwise be closed (last-chance fit).
    if fitting_bins_count == 1 {
        score -= 0.6 + 0.8 * progress;
    } else {
        score += 0.15 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for bins below mean residual early (spread load),
    // above mean residual late (fill down).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * (0.3 - 0.6 * progress);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let poor_fit = if next_item_size > 0 && post_residual == 0 && false { 0.0 } else { 0.0 };
        let _ = poor_fit;
        score = cap - (desperation * (1.0 + progress) * 2.0)
            + (fitting_bins_count as f64) * 0.5
            + if next_item_size > 0 && (bin_residual as u32) < item_size + next_item_size { 0.0 } else { 0.5 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (integer division thresholds) ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity left after placement
    let frac = pr / cap;

    // Dead-space penalty: residuals that are "wasted" (too small for typical items)
    // Items 1..100, so residual < 1 is perfect; small residuals are dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, strongly reward
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual <= 30 {
        score += 4.0;
    } else {
        score += 10.0 * (frac - 0.3); // large leftover: mild penalty
    }

    // --- Modulo arithmetic on post_residual: harmonic classes mod 10 ---
    let m = post_residual % 10;
    // Residuals congruent to 0 mod 10 are "harmonic" (easy to fill with round sizes)
    score -= match m {
        0 => 12.0,
        5 => 6.0,
        2 | 8 => 3.0,
        1 | 9 => 1.0,
        _ => 0.0,
    };

    // --- Next-item lookahead coupling ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward proportional to tightness
            let tight = 1.0 - (pr - nxt) / cap;
            score -= 20.0 * tight;
            // Harmonic pairing: post_residual % nxt small => good chain
            if next_item_size > 0 && (post_residual % next_item_size) <= 3 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize if this bin would strand a big item
            if next_item_size >= 50 && pr > 0.0 && pr < 20.0 {
                score += 5.0;
            }
        }
    }

    // --- Last-chance logic ---
    if fitting_bins_count == 1 {
        score -= 25.0; // strongly prefer using the only fitting bin
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0); // many options: mild penalty for wasting tight bins
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline score. Prefer it only if no open bin fits well
        // (i.e., when many bins can't fit or mean residual is low).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 30.0 * (1.0 - mean_residual / cap) + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can pair this item with next
        }
    }

    // --- Stream progression: late in stream, consolidate (favor tight fits more) ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    // --- Open bins pressure: many open bins => prefer filling existing ones ---
    score += (open_bins_count as f64).sqrt() * 0.5;

    // --- Mean residual coupling: if mean residual is high, avoid adding to it ---
    if pr > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold even the
    // smallest item (or the lookahead item) are effectively wasted capacity.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Gap too small for the next item is a dead-end unless nothing else fits.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
    }
    // Reward near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Non-linear penalty on small-but-nonzero leftovers.
        let pr = post_residual as f64;
        score += 30.0 * (1.0 - pr / bin_capacity as f64).powi(8);
    }

    // Lookahead synergy: if the next item fits exactly in the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    // and mean residual is healthy; encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 4.0 * open_bins_count as f64;
        // Opening a bin is more tolerable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is small, a new bin is reasonable.
        score -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
    } else {
        // Reward using bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (50.0 - slack.min(50.0)) * 2.0;
        } else {
            // next item cannot fit here; penalize small dead space less than large
            let dead = (next_item_size - post_residual) as f64;
            score += dead.min(80.0) * 0.8;
        }
    } else {
        // last item: prefer tight fit strongly
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 40.0 + item_size as f64 * 0.3;
    }

    // Early stream: be more exploratory (favor opening bins less)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize large dead space relative to capacity.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead_frac * dead_frac;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // chain fit bonus: residual after next item would be small
            let chain = post_residual - next_item_size;
            if chain <= 10 {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            // stranded space the next item cannot use
            score += 10.0;
        }
        // If next item is big, prefer tighter current placement to save room elsewhere
        if next_item_size >= 60 {
            score += 5.0 * dead_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid new bins).
    if bin_residual < bin_capacity {
        // existing bin bonus scaled by how many bins are open
        score -= 2.0 + (open_bins_count as f64).min(20.0);
    } else {
        // new-bin candidate: penalize when plenty of open bins / mean residual is large
        score += 8.0 + mean_residual * 0.3 + (open_bins_count as f64) * 1.5;
        // early in stream, opening a bin is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to mean (balanced usage) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress.
    let base = norm_pr.powf(1.0 + 1.5 * progress) - 0.35 * (norm_pr * (1.0 - norm_pr)).powi(2);

    // Penalize dead space more as the stream matures.
    let dead = (norm_pr - 0.2).abs().powf(2.0 + 2.0 * progress);

    // Last-chance bonus: strong reward when this is the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -0.6 } else { 0.0 };

    // Lookahead: reward if next item fits exactly in post_residual.
    let lookahead = if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        -0.5 * (-10.0 * diff * diff)
    } else {
        0.0
    };

    // Slight preference for keeping bins balanced relative to mean residual.
    let balance = 0.15 * (pr - mean_residual) / cap;

    let mut score = base + dead + last_chance + lookahead + balance;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near 0 are perfect fits.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small unusable residuals are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post / 10.0);
    }

    // Modulo-10 class: residuals that are multiples of 10 are "harmonic"
    // (typical item sizes align), favor them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Fractional capacity classes: residual as fraction of capacity
    let frac = post / cap;
    score += 20.0 * (frac - 0.5) * (frac - 0.5); // penalize extremes mildly

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 30.0 * (1.0 - slack as f64 / 10.0);
            }
        } else {
            // next item cannot fit here; residual will be dead space
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral baseline, slightly discouraged unless
    // current bins are nearly full / crowded.
    if bin_residual == bin_capacity {
        score = cap * 0.9 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative
        }
        if post_residual > 0 && post_residual < 10 {
            score += 0.0;
        }
    }

    // Late in stream: prefer tightening packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100).
    // A residual below ~10 is almost certainly dead weight; below next_item_size it wastes lookahead.
    if post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < next_item_size as f64 {
        score += 18.0;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: discourage opening new bins when many are open,
    // but relax pressure late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 5.0;
    }

    // Prefer bins whose residual deviates from mean: consolidate toward fuller bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item fits snugly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match: next item exactly fills the leftover space.
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        // Extra reward for near-perfect chaining.
        if slack < 5.0 {
            score -= 40.0;
        }
    } else if next_item_size > 0 {
        // Next item does NOT fit: leftover becomes dead space; penalize proportionally.
        let waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
        score += 0.5 * waste;
    }

    // Penalize leaving residuals too small for typical items (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose ones.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild penalty on opening new bins when many are already open and fit exists.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
    }

    // Early in the stream, allow slightly more freedom to open bins (diversity).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residual too small for the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; else penalize
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // Perfect pair: post_residual == next_item_size exactly
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: mildly penalize so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 45.0;
        // But late in stream with many open bins, opening fresh is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Prefer fuller bins when many bins are open (contain bin proliferation)
    if open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64);
        score -= 0.2 * (bin_residual as f64 - mean_residual).signum() * (bin_residual as f64 - mean_residual).abs().min(30.0);
    }

    // Global balance: prefer bins near mean residual to keep options open
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time-horizon coupling: early stream, keep residuals flexible; late, pack tight
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - progress) * 40.0
             - norm_pr * norm_pr * norm_pr * progress * 60.0;
    score += poly;

    // Reward tight fits, more so late in the stream
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * tightness * (1.0 + progress) * 8.0;

    // Last-chance bin bonus (smoothly weighted by progress)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins far from the mean residual (encourages balanced residuals)
    score += ((pr - mean_residual) / cap).powi(2) * 10.0;

    // Lookahead: prefer leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 12.0 * (0.5 + progress);
        if pr >= next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Mild penalty for many open bins, encouraging consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / 25.0).floor(); // 0..3 harmonic class of dead space

    // Reward tight fits strongly: small post_residual gets big subtraction.
    score -= (cap - pr).powi(2) / cap; // perfect fill bonus, quadratic in used space

    // Penalize dead space in low harmonic classes (small leftovers are useless).
    if pr > 0 {
        score += 30.0 / pr; // small residual -> big penalty
    } else {
        score -= 40.0; // exact fill is ideal
    }

    // Class-based coupling: residuals of 0, 25, 50, 75 are "harmonic" (reusable by common sizes).
    if pr % 25 == 0 && pr > 0 {
        score -= 12.0;
    }
    // Odd small residuals (1..9) are nearly dead space.
    if pr < 10 && pr > 0 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: leftover is dead unless reusable later
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Fresh bin: attractive when current bin's post_residual is wasteful.
        score = cap - pr * 0.8; // high score if current fit is tight (pr small), low if wasteful
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // big-item streams: fresh bin keeps flexibility
        }
        if fitting_bins_count <= 2 {
            score += 10.0; // don't abandon nearly-last bins
        }
    }

    // Mild stream-position adaptation: later in stream, prefer consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

