    // Tight fit reward: post_residual small relative to item size
    score -= (item_size as f64) * 0.5;

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
        // even better if the chain nearly empties the bin
        let two_step = post_residual - next_item_size;
        score -= two_step as f64 * 0.3;
    } else if next_item_size > 0 {
        // penalize leaving a gap that next item cannot use (dead space)
        let gap = post_residual as f64;
        score += gap * 0.4;
    }

    // Penalize creating small unusable fragments (below minimum item size 1..10 range)
    if post_residual > 0 && post_residual < 10 {
