    // with a smooth quadratic coupling.
    let dev = pr - mean_residual;
    score += 0.1 * dev * dev / cap;

    // Slight preference for filling fuller bins as bins accumulate.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 3.0;

    // New-bin candidate: mild default preference unless heavily rewarded otherwise.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: classify post_residual by capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let eighth = (post_residual * 8) / bin_capacity; // 0..8 class
    score -= (8 - eighth) as f64 * 8.0;

    // Modulo classes on post_residual: prefer residuals that are "harmonic"
    // multiples of common item-size classes (mod 10)
    let m = post_residual % 10;
    if m == 0 {
        score -= 12.0;
    } else if m <= 5 {
        score += 3.0;
    } else {
        score += 8.0;
    }

    // Dead space penalty: tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0;
        // harmonic check: post-residual after next item also in a clean class
        if slack % 10 == 0 || slack == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use this bin's leftover: penalize proportionally
        score += 10.0 + frac * 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only attractive when open bins are congested
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / bin_capacity as f64;
        // prefer new bin when existing residuals are large (poor fits) or late stream
        score = 30.0 + 80.0 * (1.0 - congestion) + 20.0 * (1.0 - progress);
        if item_size > 60 {
            score -= 15.0; // big items like fresh bins
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild preference for bins tighter than the mean (best-fit flavor)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are highly undesirable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += 0.05 * pressure;

    // New-bin candidate calibration: make empty bin moderately attractive
    // only when residuals elsewhere are poor.
    if bin_residual == bin_capacity {
        score += mean_residual * 0.3 + 10.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size && (post_residual as u32) - next_item_size < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    // Reward when the leftover space (post_residual) exactly matches the next item.
    if next_item_size > 0 {
        let lookahead_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match, decaying with distance.
        score -= 60.0 / (1.0 + lookahead_diff);
        // Extra bonus for a perfect chain fit.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a残 residual that is too small for the smallest possible item
        // (dead space) unless it perfectly chains.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 30.0;
        }
    }

    // Penalize post_residual relative to mean residual: creating an outlier
    // tiny residual wastes capacity elsewhere.
    let pr = post_residual as f64;
    if pr > 0.0 && mean_residual > 0.0 {
        let ratio = pr / (mean_residual + 1.0);
        if ratio < 0.5 {
            score += 12.0 * (1.0 - ratio);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // current bin would leave a large awkward residual and the next item is big.
    if bin_residual == bin_capacity {
        // Baseline neutral score: slightly above a decent fit.
        score = bin_capacity as f64 * 0.75;
        if next_item_size > 0 && post_residual >= next_item_size {
            // An empty bin can chain the next item too: moderately attractive.
            score -= 15.0;
        }
        // Late in the stream, avoid opening new bins more aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    }

    // Prefer tighter fits overall: bonus proportional to fill fraction.
    score -= 20.0 * (item_size as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins whose post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    // (nothing below ~10 can be filled by typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use this residual; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals clean); late in the stream, pack aggressively.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 10.0 * progress * tightness;

    // Global state coupling: many open bins with high mean residual means
    // fragmentation; discourage new-bin tendency by rewarding use of open bins.
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 0.3 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize when mean residual across open bins
        // is large (space already exists elsewhere), reward when open bins
        // are nearly full.
        score += 0.04 * mean_residual;
        score -= 0.2 * open_bins_count as f64;
        // Late stream: opening new bins is cheaper than fragmenting.
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    // Small post_residual is good (tight fit), but very small residual (<~10)
    // can be dead space; smooth quadratic penalty on extreme smallness.
    let mut score = pr - 18.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (norm_pr * 4.0).min(1.0);

    // Smooth interaction: residual usefulness decays with stream progress
    // (late in stream, leftover space is less likely to be used).
    let decay = 1.0 + 0.8 * progress * progress;
    score *= decay;

    // Reward bins whose residual matches the next item's needs (smooth coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.35 * gap * (1.0 - progress);
    }

    // Penalize if this is one of many fitting bins (prefer scarcity/last-chance).
    if fitting_bins_count > 1 {
        score -= 6.0 / (fitting_bins_count as f64);
    }
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // last-chance bin: strongly favor using it
    }

    // New-bin candidate: keep it mildly attractive unless an open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    // Slight preference toward bins below mean residual (consolidating space).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer small post_residual.
    // Harmonic class penalty: classify post_residual into capacity fractions.
    // Residuals in (0,10] are dead space (unusable since items >= 1, but small items
    // up to 100 exist, so weight by size of dead zone relative to smallest useful item).
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Fractional class of the residual: which quarter of capacity it lives in
        let quarter = (post_residual * 4) / bin_capacity; // 0..3
        let class_penalty = match quarter {
            0 => 12.0, // tiny residual: likely dead space
            1 => 6.0,
            2 => 3.0,
            _ => 0.0,
        };
        score += class_penalty;

        // Modulo arithmetic: residual divisible into common small sizes is reusable
        let reusable = |r: u32| -> f64 {
            let mut best = 0.0;
            for d in [1u32, 2, 4, 5, 10, 20, 25, 50] {
                if r >= d && r % d == 0 {
                    best += 1.5;
                }
            }
            best
        };
        score -= reusable(post_residual);
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // harmonic class of the gap left after the next item
            let gap = post_residual - next_item_size;
            let gap_class = (gap * 4) / bin_capacity;
            score += gap_class as f64 * 2.0;
            if gap % 5 == 0 || gap % 10 == 0 {
                score -= 2.0;
            }
        } else {
            // next item cannot follow here: mild penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // neutral-ish score: slightly above a good fit, below a bad fit
        score = 55.0
            - (mean_residual / bin_capacity as f64) * 10.0
            - (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: must open new bin
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Tie-break with mean residual alignment: bins near mean residual are good targets
    score += ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Partially unusable zone: small gaps that only tiny items could fill.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 15.0;
    }
    // Penalize if next item will NOT fit here (wasting lookahead opportunity).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64) * 1.5;
    score -= pressure;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // existing residuals are poor fits; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: new bin is fine
        } else {
            score += 55.0 + pressure; // discourage new bin when fits exist
        }
        // Late in the stream, opening a fresh bin is even less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild preference for bins tighter than average (use up emptier space first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - diff / (bin_capacity as f64)) * (diff as f64).exp().min(1.0);
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize residual that can neither fit the next item nor much else
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 8.0;
    }

    // Penalize dead space relative to mean residual (fragmentation penalty)
    let pr = post_residual as f64;
    if pr > 0.0 {
        score += 4.0 * (pr / bin_capacity as f64) * (pr / mean_residual.max(1.0)).ln().abs().min(2.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Mild penalty on new-bin candidate when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
        // Allow new bin if item is large and fits poorly anywhere
        if item_size > bin_capacity / 2 && next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Progress-based tie-breaking: later in stream, tighten packing more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small post-residuals that are too small to be useful later
    // (dead space), but reward exact or near-exact fills.
    if post_residual < 10 {
        score -= 8.0; // near-perfect fill is great
    } else if post_residual < 25 {
        score += 6.0; // awkward dead zone
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 4.0 + 0.1 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global balance: prefer bins whose residual deviates from the mean
    // in the direction of a tighter fit (consolidate small residuals).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: late in the stream, be more conservative about opening
    // new bins (favor filling existing ones); early on, allow exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins late, mildly reward early.
        score += 20.0 * progress - 5.0 * (1.0 - progress);
        // Prefer a new bin when the item is huge and would fragment a bin.
        if item_size > bin_capacity / 2 && next_item_size > post_residual as u32 && post_residual > 0 {
            score -= 6.0;
        }
    } else {
        score -= 3.0 * progress;
    }

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on post_residual (waste minimization)
    let mut score = post * (1.0 + 0.9 * norm_post);

    // Non-linear coupling: waste matters more as stream progresses
    score += 40.0 * norm_post * norm_post * progress;

    // Smooth interaction with mean residual: prefer bins whose residual
    // is below mean (consolidating tighter bins)
    let mean_term = (mean_residual - post) / cap;
    score += 12.0 * mean_term * (1.0 + progress);

    // Perfect fit reward via smooth term on small post_residual
    score -= 25.0 * (1.0 - norm_post).powi(6) * (1.0 + progress);

    // Last-chance bin: strongly reward using it to avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 18.0 + 10.0 * progress;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - 0.5 * progress);
        } else {
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Mild penalty for spreading across many open bins early on
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: bins whose leftover belongs to a
        // "reusable" residue class (small residues divisible into common
        // item sizes) are penalized less than awkward dead space.
        let pr = post_residual;
        let class_penalty: f64 = match pr % 10 {
            0 => 0.5,          // residue aligns with small items (10,20,...)
            5 => 1.0,          // half-class
            2 | 4 | 6 | 8 => 2.0,
            _ => 3.5,          // odd awkward residues -> dead space
        };
        score += class_penalty * (pr as f64 / 10.0).sqrt();

        // Dead-space threshold: leftover too small for the smallest item
        if pr < 10 {
            score += 500.0;
        }

        // Lookahead coupling: reward if next item fits exactly into post_residual
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size < pr {
                score -= 20.0 * (1.0 - (pr - next_item_size) as f64 / 100.0);
            } else {
                // next item cannot fit here: penalize by the wasted slack
                score += (next_item_size - pr) as f64 * 0.3;
            }
        }

        // Last-chance bin: strongly favor using the only fitting bin
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Fraction-of-capacity harmonic thresholds on residual before placement
        let frac = bin_residual as f64 / bin_capacity as f64;
        if frac > 0.75 {
            score -= 10.0; // big bins first (best-fit-like)
        } else if frac < 0.25 {
            score += 5.0;  // discourage squeezing into nearly-full bins
        }

        // Late in the stream: consolidate aggressively, avoid opening bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;

        // Many open bins: prefer filling existing ones over spreading
        score -= open_bins_count as f64 * 0.5;

        // Prefer bins below mean residual (tighter bins get filled first)
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 300.0 } else { 60.0 };
        score += desperation + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any item (1..=9)
    // are pure waste -> heavy penalty on top of the base residual.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Small-ish gaps (10..=19) are only usable by small items; mild penalty.
    else if post_residual <= 19 {
        score += 6.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 12 {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another;
    // a brand-new empty bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 4.0;
        // Opening a new bin is more tolerable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Don't open a new bin if this bin would be nearly full anyway.
        if (bin_capacity - item_size) as f64 <= mean_residual * 0.5 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // reward this placement; if post_residual is too small for the next item,
    // penalize slightly (dead space relative to the lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 4.0;
        }
    }

    // Prefer filling bins that are already relatively full (low residual)
    // to consolidate waste into fewer bins.
    score += (bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize creating dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 50.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // next item can't follow here; small penalty scaled by tightness
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // Bonus if next item would perfectly consume what's left after that.
        if next_item_size > 0 && post_residual >= next_item_size {
            let after_next = post_residual - next_item_size;
            if after_next == 0 {
                score -= 80.0;
            } else if after_next <= 10 {
                score -= 20.0;
            }
        }
    }

    // Relative to mean residual: prefer bins that are already fuller than average
    // (keeps emptier bins flexible for future items).
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 90.0;
        // Encourage new bin early in stream or when many bins are open with slack.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count > 3 && mean_residual > 30.0 {
            score -= 30.0 * progress;
        }
        // If next item is large and won't fit leftovers anyway, new bin is fine.
        if next_item_size > 50 {
            score -= 40.0;
        }
    }

    // Prefer packing into bins with smaller residual overall (best-fit bias).
    score += (bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (perfect fit gets big bonus).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - tightness).powi(3);
    }

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect chain: current fit + next item fits exactly.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream
    // and when the item is small (wasteful), unless many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = item_size as f64 / bin_capacity as f64;
        score += 20.0 + 40.0 * (1.0 - waste) + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Slight preference for bins below mean residual (keep a spread of sizes).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Mild pressure to consolidate as stream nears completion.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let isz = item_size as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with smooth non-linear emphasis
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early stream tolerates slack,
    // late stream punishes dead space more aggressively.
    score *= 1.0 + 1.5 * progress * norm_pr;

    // Reward tight fits (post residual near zero) with a smooth quadratic bonus
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness;

    // Reward bins that can also fit the lookahead item smoothly
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_fit = (post_residual - next_item_size) as f64 / cap;
        score -= 3.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
    } else if next_item_size > 0 {
        // lookahead cannot follow here: mild penalty scaled by how much it misses
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 2.0 * miss * miss;
    }

    // Last-chance bin bonus: smooth reward when this is the only fitting bin
    if fitting_bins_count <= 1 {
        score -= 4.0;
    }

    // Penalize bins whose residual deviates strongly from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.5 * dev * dev;

    // New-bin candidate handling: empty bin (bin_residual == bin_capacity).
    // Acceptable only for large items (poor fit elsewhere); otherwise penalize.
    if bin_residual == bin_capacity {
        let fill_ratio = isz / cap;
        let openness = 1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        // large items benefit from a fresh bin; small items should use open bins
        score += 8.0 * (1.0 - fill_ratio) * (1.0 - fill_ratio) - 3.0 * openness;
    }

    // Slight preference for more-filled bins overall
    score -= 0.5 * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small leftovers (<20) are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits strongly (post_residual small).
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 15.0;
    }

    // Penalize residual in the "awkward" band 30..50 (hard to fill later).
    if post_residual >= 30 && post_residual <= 50 {
        score += 8.0;
    }

    // Modulo-harmonic classes: residuals congruent to multiples of 10 pair
    // well with items drawn in 10-steps; reward divisible-by-10 residuals.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0; // odd leftovers pair poorly
    }

    // Integer-division thresholds on next_item_size vs post_residual:
    // perfect lookahead pairing (next item exactly fills leftover).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover2 = post_residual - next_item_size;
            if leftover2 < 10 {
                score -= 18.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled
            // by how much of the leftover next item wastes.
            let ratio = next_item_size as f64 / (post_residual as f64 + 1.0);
            score += 6.0 * (1.0 - (1.0 / ratio)).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer opening a fresh bin when the current item
    // would leave a large dead space in every existing bin, but discourage
    // needless new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, discounted when item is large (hard to place).
        let mut nb = 55.0;
        if item_size >= 60 { nb -= 20.0; }
        if item_size >= 80 { nb -= 10.0; }
        // If few fitting bins exist, opening new bin is less wasteful.
        if fitting_bins_count <= 1 { nb -= 15.0; }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 20.0 * progress;
        score = score.max(0.0) + nb;
        // Fresh-bin harmonic bonus: empty bin leaves residual = C - item,
        // reward when that residual is a "good class" (multiple of 10).
        if (bin_capacity - item_size) % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Deviation from mean residual: prefer bins whose residual is below
    // average (tighter bins get filled first).
    score += 0.3 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space: penalize proportionally to how "stranded" it is
    // relative to the next item's demand.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual) with a bonus.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: prefer compacting into existing bins as they accumulate.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean residual coupling: bins below mean residual are already tight;
    // filling them further keeps large residuals consolidated.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Slight stream-position pressure: later in the stream, consolidate more.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    // New-bin candidate: neutral baseline with mild penalty so it is chosen
    // only when all open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (dead space eliminated).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item fits exactly in the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits: penalize leftover after the hypothetical next placement.
            let after_next = post_residual - next_item_size;
            score -= 100.0 * (1.0 - after_next as f64 / bin_capacity as f64);
            if after_next <= 10 {
                score -= 50.0;
            }
        } else {
            // Next item will NOT fit here: penalize bins that become tight dead space.
            if post_residual < 10 {
                score += 80.0;
            }
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin plus waste potential.
        score += 60.0;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 40.0;
        }
        // Early in the stream, slightly discourage hoarding open bins; late, discourage new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
    }

    // Mild penalty for very large post residual (wasted space).
    score += 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual penalty for small leftovers.
    let pr = post_residual as f64;
    score += pr * pr / (bin_capacity as f64);

    // Reward filling bins nearly completely.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize leaving post-residual that cannot fit the next item
    // (dead space), reward post-residual that exactly accommodates it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        } else {
            score += 4.0 * (nxt - pr) / 10.0;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so that
    // only genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If no open bin can fit the item, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in the stream, prefer reusing bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins.
    if open_bins_count > 2 {
        score += 0.5 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    }

    // Slight preference for bins whose residual is close to the item size.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling: prefer tight fits, penalize large residuals smoothly.
    score += 18.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward high fill ratio with smooth saturation.
    score -= 12.0 * (fit / (1.0 + fit)) * (1.0 + 0.5 * progress);

    // Lookahead: reward if next item fits into post-residual, penalize otherwise.
    if next_item_size > 0 {
        if pr >= next_item_size as f64 {
            score -= 8.0 * (1.0 - (pr - nxt * cap) / cap).abs().min(1.0);
        } else {
            score += 6.0 * (1.0 - nxt) * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean, slightly.
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: penalize opening a new bin unless residual is large.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class bins by integer division into harmonic bands of capacity.
    let band = post_residual / (bin_capacity / 4); // 4 harmonic bands: 0..3
    match band {
        0 => score -= 6.0,           // tiny leftover: near-perfect fit, reward heavily
        1 => score += 2.0,           // small leftover: mildly wasteful
        2 => score += 6.0,           // medium leftover: poor fit
        _ => score -= 1.0,           // large leftover: bin stays flexible
    }

    // Modulo coupling: post_residual divisible by common item sizes is more reusable
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual > 0 && post_residual % m == 0 {
            score -= 3.0;
        }
    }

    // Penalize post_residual that cannot hold the next item (dead space risk)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // leftover can host next item: reward, scaled by tightness
            score -= (post_residual - next_item_size) as f64 * 0.15;
            // exact harmonic fit for next item
            if post_residual == next_item_size {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral baseline with slight cost of opening
    if bin_residual == bin_capacity {
        score += 4.0 + 0.05 * open_bins_count as f64;
    }

    // Progress term: late in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual) * 0.1;

    // Tightness reward: filling bin closer to capacity
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    let dead_zone = 10.0f64.min(bin_capacity as f64 * 0.10);
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual can still host the lookahead item after placement.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus per-open-bin pressure.
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But if the new bin leaves a large usable residual while mean residual is small,
        // opening a fresh bin is more attractive.
        score -= (bin_capacity as f64 - item_size as f64) * 0.25;
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Mild stream-progression term: later in the stream, tightening fits matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (2-step lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Reward bins where the next item also fits, scaled by slack left after.
        let two_step_left = post_residual - next_item_size;
        score -= 20.0 + (two_step_left as f64).min(15.0);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize dead space creation.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.5 * waste;
    }

    // Penalize residual far below mean residual (fragmented bin).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    }

    // Last-chance bonus: only bin that fits -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Prefer filling tight bins; keep large residual bins flexible.
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Slight penalty on new empty bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness;

    // Penalize dead space: residuals too small for any plausible item (1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: strongly reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: mild penalty if we strand capacity.
        score += 0.5 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many open bins: prefer consolidating into existing ones.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates far above the mean (fragmented outliers),
    // unless the item is a poor fit elsewhere.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev.abs();

    // Time horizon: late in the stream, be more conservative (favor tight packing,
    // avoid opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // New empty-bin candidate: penalize opening a new bin unless the current item
    // is huge and no good fit exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count == 0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear coupling: penalize large post-residuals more as stream progresses
    score += 60.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with smooth decay
    score -= 40.0 * (-pr / 15.0).exp();

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 25.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 15.0 * (ns - pr) / cap;
        }
    }

    // Last-chance bonus: if only this bin fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Mild pressure to prefer bins below mean residual (consolidate fullness)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Late-stream: discourage opening new bins
    if bin_residual == bin_capacity {
        score += 20.0 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how close post_residual is to a
    // "divisible" residue class of the capacity (dead-space avoidance).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize post residuals that are unusable dead space (< smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: post_residual modulo small divisors of capacity.
    // Residuals divisible by 10 (capacity/10) are reusable by typical items.
    let m10 = post_residual % 10;
    score += (m10 as f64) * 0.8;

    // Reward residuals that can host the lookahead item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= 8.0 - (gap as f64).min(8.0);
            score += (gap % 5) as f64 * 0.5;
        } else {
            // lookahead item cannot use this bin: slight penalty if residual small
            if post_residual < next_item_size {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill = 1.0 - pr / cap;
    score -= fill * 6.0;

    // Harmonic threshold on integer division: residuals in (0,15] are poor.
    if post_residual >= 1 && post_residual / 5 == 0 {
        score += 15.0;
    }

    // New-bin candidate: prefer it only when open bins are crowded and
    // the item is large relative to the bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (open_bins_count as f64) * mean_residual / (open_bins_count.max(1) as f64 * cap);
        // base cost of opening a new bin, discounted when existing residuals are fragmented
        score += 18.0 - crowded * 10.0 - progress * 4.0;
        if item_size >= 50 {
            score += 6.0; // big item into fresh bin is fine
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap 1 -> +56, gap 9 -> +24
    }

    // Reward tight fits (small but non-dead residual is fine).
    score -= (bin_residual - post_residual) as f64 * 0.5;

    // If the remaining gap could fit the lookahead item, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit in the leftover: penalize proportionally.
        score += (next_item_size as f64) * 0.3;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by open-bin pressure.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64) * 2.0;
        // But if no open bin fits well, opening a bin becomes less bad.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins less.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mild pressure toward bins below mean residual (balancing load).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Aggressive 2-step lookahead: reward when next item fits into post_residual
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                let chain_fit = next_item_size as f64 / post_residual as f64;
                score -= 60.0 * chain_fit;
                // Bonus if chained placement leaves near-zero residual
                let chain_post = post_residual - next_item_size;
                if chain_post == 0 {
                    score -= 250.0;
                } else if chain_post <= 10 {
                    score -= 80.0;
                }
            } else {
                // Next item cannot chain: penalize proportional to leftover dead space
                score += 25.0 * (next_item_size as f64 / post_residual as f64);
            }
        }

        // Penalize small unusable residuals (dead space)
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: neutral baseline, penalize opening when decent fits exist
    if bin_residual == bin_capacity {
        score += 150.0;
        // Allow new bin early in stream or when few open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 || open_bins_count < 3 {
            score -= 100.0;
        }
        // Prefer new bin if mean residual is small (existing bins are full)
        if mean_residual < item_size as f64 {
            score -= 200.0;
        }
    }

    // Mild pressure to consolidate into fewer bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual can host next item: reward proportionally.
            score -= 3.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize wasted gap.
            let gap = (post_residual as f64) / (next_item_size as f64).max(1.0);
            score += 6.0 * gap.min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = (post_residual as f64) / (bin_capacity as f64); // == 1 - item/C
        let pressure = (open_bins_count as f64).max(1.0);
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty for new bin, reduced when item is large (better fill) or many bins open.
        let mut new_bin_penalty = 15.0 - 10.0 * fit_quality;
        new_bin_penalty -= 2.0 * (pressure.ln() + 1.0).min(3.0);
        // Late in stream, prefer consolidating into existing bins.
        new_bin_penalty += 6.0 * time_frac;
        // If no other bin fits (fitting_bins_count==1 means only new bin), waive penalty.
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild global-state coupling: prefer bins with residual near mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Slight preference for filling fuller bins (larger item fraction).
    score -= 0.05 * (item_size as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr * pr * (1.0 + 2.0 * progress) - pr * (1.0 - progress);
    score += 0.6 * poly;

    // Reward tight fits (low post residual) more strongly later in the stream
    score -= (1.0 - pr) * (1.0 - pr) * (0.5 + 1.5 * progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.4 * (pr - mean_residual / cap).abs() * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - pr);
    }

    // Lookahead: penalize leaving residual that barely fits next item poorly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = (pr - nx).max(0.0);
        score += 0.5 * waste * (1.0 - progress);
        // reward if next item fits snugly in the resulting residual
        if nx <= pr && nx > 0.0 {
            score -= 0.8 * (1.0 - (pr - nx).abs() * 4.0).max(0.0) * progress;
        }
    }

    // Mild penalty for proliferating open bins early
    score += 0.15 * (open_bins_count as f64 / (1.0 + progress * 10.0)) * pr;

    // New-bin candidate handling: only attractive when stream is early or fits are bad
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.5 * progress;
        if fitting_bins_count == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "usable" slots.
    let residue_class = post_residual % 10;
    let harmonic_penalty = match residue_class {
        0 => -8.0,           // perfectly aligned slot, highly reusable
        1 | 9 => 4.0,        // awkward slivers
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division thresholds on post_residual: dead-space bands.
    if post_residual < 10 {
        score += 15.0; // dead space, unusable for min item
    } else if post_residual <= 20 {
        score += 5.0;
    }

    // Reward tight fits (small post_residual relative to capacity fractions).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // partial reward proportional to how well next item consumes the slot
        score -= 6.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item can't use this slot: penalize proportional to leftover waste
        score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: prefer it only when existing bins are fragmented.
    if bin_residual == bin_capacity {
        // fresh bin is attractive when open bins have low mean residual (nearly full)
        let pressure = 1.0 - mean_residual / bin_capacity as f64;
        score = 30.0 - 25.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 8 / 10 {
            score -= 10.0; // big item coming, keep capacity free
        }
    }

    // Stream progression: early on, be conservative with open bins; later, pack aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    if post_residual > 0 {
        let dead = post_residual as f64;
        // Unusable gap: too small for the next item and typical small items.
        let unusable = next_item_size == 0 || (next_item_size > 0 && (post_residual as u32) < next_item_size);
        if unusable {
            score += 30.0 + dead * 1.5; // heavy penalty for creating dead space
        } else {
            score -= 5.0; // gap is still usable by the lookahead item: reward
        }
    } else {
        // Perfect fit: strongly reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Open-bins pressure: discourage spreading across many bins when few fit options exist.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0; // last-chance bin: strongly prefer using it
    }
    score += open_bins_count as f64 * 0.4;

    // New-bin candidate: only attractive when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset if current bins would waste space.
        score = 25.0 + (item_size as f64 * 0.1);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
    }

    // Slight preference for bins below mean residual (balances load).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it fills leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // Next item does NOT fit in the leftover dead space: penalize dead space.
            let dead = post_residual as f64;
            score += 0.35 * dead;
        }
    } else {
        // Last item: just minimize post_residual.
        score -= 20.0;
    }

    // Compare residual against mean residual of open bins:
    // bins with residual below mean are "more packed"; using them keeps many loose bins available.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it attractive only when open bins are badly fragmented
    // (mean residual low relative to item size) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Fresh bin is good when existing bins are too full/fragmented for future items.
        if fragmentation < 0.35 || (progress > 0.6 && open_bins_count > 4) {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Mild penalty for creating very small unusable slivers (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any future item
    // (min item size ~1, but penalize residuals below next item's need).
    if post_residual < next_item_size && next_item_size > 0 {
        score += 4.0 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 {
        // Reward bins whose leftover can still host the next item
        score -= 2.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // When many bins fit the item, mildly discourage spreading; prefer
    // bins already below mean residual (denser bins first).
    if fitting_bins_count > 1 {
        score -= 1.5;
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // New-bin candidate logic: empty bin should only win when the fit in
    // existing bins is poor. Penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Early in the stream, opening fresh bins is cheaper (future items
        // unknown); relax the penalty as the stream progresses.
        score -= 8.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin gives a
        // clean layout for follow-ups.
        if item_size * 2 >= bin_capacity {
            score -= 3.0;
        }
        // If many open bins exist, opening yet another one fragments capacity.
        score += 0.4 * open_bins_count as f64;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // Late in the stream, consolidate aggressively: close out bins.
    score -= 3.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Tight fits rewarded; dead space penalized more as stream progresses
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Smooth interaction between post_residual and stream progress
    score += norm_post * post * progress * 0.8;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = post - nxt;
        if diff >= 0.0 {
            score -= (1.0 - (diff / cap).abs()) * 4.0;
        } else {
            score += (-diff / cap) * 8.0;
        }
    }

    // Last-chance fitting: strongly favor using this bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Crowd penalty: many open bins with small residuals -> consolidate
    let crowd = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += crowd * norm_post * 2.0;

    // Mean residual coupling: penalize bins far below mean residual (wasteful)
    score += (mean_residual - post).abs() * 0.05;

    // Slight bias against opening a new bin early
    if bin_residual == bin_capacity {
        score += 3.0 + 20.0 * (1.0 - progress) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions.
    // Perfect fit (post_residual == 0) is the ideal outcome.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Class the dead space into capacity-fraction buckets.
        // Small leftovers that can still host common small items are less penalized.
        let frac = post_residual as f64 / bin_capacity as f64;
        if post_residual <= 10 {
            score -= 120.0; // nearly perfect: dead space of the smallest class
        } else if post_residual <= 20 {
            score -= 60.0;
        } else if post_residual <= 30 {
            score -= 25.0;
        } else if post_residual <= 50 {
            score += 15.0 * frac;
        } else {
            score += 40.0 * frac;
        }

        // Integer-division thresholds: residual divisible by common item sizes
        // (10, 20, 25, 50) means the leftover is reusable by a whole item.
        if post_residual % 10 == 0 {
            score -= 30.0;
        }
        if post_residual % 25 == 0 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use the leftover: dead space likely permanent.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Encourage spreading load when many bins are open (avoid many near-empty bins).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    // Mild preference for filling older bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    // New-bin candidate: keep it attractive only when no open bin is a good fit.
    if bin_residual == bin_capacity {
        // Neutral baseline; tight fits in open bins (score << 100) will beat it.
        score = 100.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest plausible
    // item are pure waste; penalize them super-linearly.
    let dead_zone = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last fitting bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer bins that leave room for the lookahead item.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        }
        // Penalize wasting a nearly-full bin on a small item when others fit.
        if (bin_residual as f64) < item_size as f64 + next_item_size as f64 * 0.5 {
            score += 4.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, a fresh bin is cheap.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        let pressure = (open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64)).sqrt() * 3.0;
        score += pressure;
        // If this is the only fitting option anyway, opening is fine.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin reduces fragmentation pressure.
        score -= (open_bins_count.min(10) as f64) * 0.5;
    }

    // Late in the stream, consolidate aggressively to avoid leftover scraps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit (zero waste)
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual matches next item exactly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 150.0;
        } else {
            score += gap * 0.8;
        }
        // Penalize leaving residuals smaller than next item (dead space)
        if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Prefer fuller bins relative to the fleet mean residual
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize creating tiny unusable residuals (below minimum item size)
    if post_residual > 0 && post_residual < 1 {
        score += 100.0;
    }

    // New empty bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let opening_penalty = 90.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 0.0 } else { 40.0 * (fitting_bins_count as f64).min(3.0) };
        score += opening_penalty + scarcity_bonus;
        // If the item nearly fills a fresh bin, opening is more attractive
        if item_size >= bin_capacity * 9 / 10 {
            score -= 70.0;
        }
    }

    // Slight preference for consolidating fewer open bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream: early -> explore, late -> consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let urgency = progress * progress; // 0..1, grows over time

    // Reward near-perfect fits, amplified late in the stream.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * (0.5 + urgency);

    // Lookahead: if the leftover space exactly accommodates the next item, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // leftover can host the next item: mild bonus scaled by leftover slack
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: dead-space penalty grows with urgency
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste * (0.4 + urgency);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * urgency;
    }

    // Many open bins: encourage filling existing ones (fragmentation control).
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 4.0 * (1.0 - urgency);
    }

    // Global mean residual coupling: bins far from the mean residual are
    // slightly deprioritized early (balance exploration), favored late.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15 * (1.0 - urgency) - dev * 0.05 * urgency;

    // New-bin candidate handling: empty bin gets a base handicap so we only
    // open a new bin when remaining open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let needed = item_size as f64;
        let badness = (bin_capacity as f64 - needed) / bin_capacity as f64;
        score += 35.0 + 55.0 * badness - 30.0 * urgency;
        // If no open bin can fit the item, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Small nudge toward using larger residuals for larger items.
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste buckets modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual % quarter) as f64;
    score += class * 0.3;

    // Reward exact / tiny post residuals (perfect fit classes)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // dead space penalty scaled by how much of next item is wasted
            score += (next_item_size as f64 - post_residual as f64).min(60.0) * 0.25;
        }
    }

    // Last-chance bonus: this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are very full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 15.0 {
            score -= 30.0; // open bins nearly saturated -> new bin fine
        } else {
            score += 60.0; // plenty of room left, avoid spreading
        }
    }

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Stream progression: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Integer-division threshold: bins whose residual is >= 2x item size are less urgent
    if bin_residual >= 2 * item_size {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that no future item (min size 1..=10) can use.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Prefer tight fits generally: scale by fill fraction.
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= fill * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But if remaining fits are scarce and next item is large, opening is fine.
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0;
        }
    }

    // Lookahead: if next item exactly matches post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // this gap likely becomes dead space for next item
    }

    // Late in stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain: next item fills bin completely
            if slack == 0.0 {
                score -= 60.0;
            } else {
                // Reward proportional to how well next item uses the leftover
                let usage = 1.0 - slack / post_residual as f64;
                score -= 40.0 * usage;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += 15.0;
        }
    }

    // Compare post_residual against mean residual across open bins
    // Prefer bins whose post-residual is close to (or below) the mean -> keeps residuals uniform
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.3 * mean_diff;

    // Penalize large unusable post-residual (dead space below min item size)
    if post_residual < item_size.min(100) && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if no open bin
    // offers a tight fit; make the fresh empty bin less attractive by default
    if bin_residual == bin_capacity {
        // Slight penalty so existing tight fits win, but relax late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 - 10.0 * progress;
        // If next item is large and current item leaves big post-residual, new bin more attractive
        if next_item_size > 50 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Reward tighter overall fit (waste minimization)
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect or near-perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize leaving a residual that no plausible item can use (dead space).
    // Items are 1..100; residual below ~10 is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: reward placements where the next item fits the post-residual
    // exactly or well (chaining fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        } else {
            // Next item won't fit here; slightly neutral.
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Prefer opening a new bin only when existing fits are bad (large post_residual)
    // and the item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin (bins are costly).
        score += 15.0;
        // If the item fills a large chunk of a fresh bin, opening is cheap.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 30.0;
        // If existing fit is very wasteful, make new bin more attractive.
        if post_residual > 40 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // Few open bins => opening is relatively cheaper early on.
        if open_bins_count > 8 {
            score += 8.0;
        }
    } else {
        // Reward using already-open bins to consolidate state.
        score -= 5.0;
        // Prefer bins whose residual is below average (more filled bins),
        // keeping emptier bins available for larger future items.
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score -= dev * 0.3;
        } else {
            score += (-dev) * 0.3;
        }
    }

    // Global pressure: when many bins are open relative to progress,
    // discourage opening new ones (handled above) and encourage tight packing.
    if open_bins_count > 0 {
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += pressure * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize post residual, but with diminishing returns (quadratic damping)
    let mut score = pr * (1.0 + norm_pr * (1.0 - progress));

    // Smooth polynomial coupling: waste grows super-linearly for tiny residuals
    let waste_coupling = (1.0 - norm_pr).powi(2) * norm_pr * cap * 0.5;
    score += waste_coupling * (0.5 + progress);

    // Stream-progress interaction: later in stream, tolerate tighter fits more
    score -= progress * norm_pr * cap * 0.3;

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_ratio = if pr > 0.0 { nxt / pr } else { 2.0 };
        if fit_ratio <= 1.0 {
            score -= (1.0 - fit_ratio).powi(2) * 8.0 * (1.0 - progress);
        } else {
            score += (fit_ratio - 1.0).powi(2) * 4.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for consolidating into fewer bins when residuals are high
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score += 10.0 + 20.0 * (1.0 - tightness) * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.02 * pr / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: residuals that are hard to fill (small odd classes).
    let class = post_residual / eighth; // 0..=8 harmonic class
    let class_penalty = match class {
        0 => 60.0, // perfect fit
        1 => -5.0, // tiny leftover: usually dead space -> penalize via negative? no: penalize means ADD
        2 => 12.0,
        3 => 20.0,
        4 => 6.0,  // quarter residual still usable
        5 => 18.0,
        6 => 10.0,
        7 => 4.0,
        _ => 0.0,
    };
    // class 1 (tiny leftover) is bad: add penalty
    score += if class == 1 { 35.0 } else { class_penalty };

    // Reward tight fits strongly when post_residual is small but next item can use it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect lookahead chain
        } else if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / pr);
        } else {
            score += 8.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if all fits are poor or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = fitting_bins_count == 0 || (mean_residual < item_size as f64 * 0.5);
        if poor_fits {
            score -= 30.0;
        } else {
            score += 45.0 + 30.0 * progress; // prefer reusing bins mid-stream
        }
        // Opening a bin when many bins are open with slack is wasteful
        score += open_bins_count as f64 * 3.0;
    }

    // Modulo coupling: residuals divisible into halves/quarters are valuable.
    if post_residual % (bin_capacity / 2) == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Mild preference for bins with less residual relative to mean (better packing).
    score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
