pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual
    // (chained perfect fit), penalize when next item cannot use the leftover space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size > post_residual {
            // Leftover is dead space unless tiny; penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Next item fits; reward tightness of the follow-up fit.
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Reward bins whose residual was already below average (dense bins),
    // penalize dumping into loose bins.
    let res_f = post_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.4;
    } else {
        score += (res_f - mean_residual) * 0.4;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Early in the stream, prefer opening new bins less (keep bins tight);
    // late in the stream, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0;

    // Penalize large dead space after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are bad
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later (below typical item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // post-residual too small for next item: penalize proportional waste
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    } else {
        // Last item: just dump into anything, prefer exact fill.
        score -= 50.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (new-bin candidate also has residual == capacity).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream with few open bins, discourage opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count < 4 && progress < 0.5 {
            score += 30.0;
        }
        // But if mean residual across open bins is low (all bins nearly full),
        // opening a new bin is fine.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    }

    // Mild penalty for accumulating many open bins with scattered residuals.
    score += 0.5 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Time-horizon modulation: later in stream, be greedier (tighter fits matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth progress coupling: later in the stream, be stricter about dead space
    score += 12.0 * progress * norm_pr * (1.0 - progress);

    // Reward if the lookahead item fits in the post residual (smooth, non-linear)
    if next_item_size > 0 {
        let fits = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let fit_frac = (fits / cap).min(1.0);
        score -= 10.0 * fit_frac * (1.0 - fit_frac * 0.5);
        // Slight penalty if lookahead nearly but not exactly fits (wasted potential)
        let gap = (pr - next_item_size as f64).abs();
        if gap < 5.0 { score += 2.0; }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening a new bin when other bins fit, scaled by stream progress
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += (8.0 + 20.0 * progress) * fit_pressure + 2.0 * open_bins_count as f64;
        // Reward new bin early in stream when residuals are fragmented
        if progress < 0.3 && mean_residual < 0.25 * cap {
            score -= 6.0;
        }
    }

    // Mild preference for bins with residuals below mean (consolidate emptier bins)
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: strongly penalize residuals that no plausible item can use.
    // Harmonic classes: classify post_residual by modulo 10 bands.
    let pr = post_residual;
    let dead_class = if pr == 0 { 0.0 }
        else if pr < 10 { 1.0 }          // nearly unusable dead space
        else if pr % 10 == 0 { -0.5 }    // clean slot, reusable
        else { 0.3 };

    score += dead_class * (pr as f64) * 0.5;

    // Tight fit reward: item fills bin exactly or nearly.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin is only attractive when the item is large
    // and would leave a very poor residual elsewhere, or when existing residuals are large.
    if is_new_bin {
        // Penalize new bin by default; scale with open bins (proliferation cost).
        score += 20.0 + 3.0 * open_bins_count as f64;
        // Reward opening a fresh bin when the item is huge (little would be wasted anyway).
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 40.0 * fill_frac * fill_frac;
        // If mean residual of open bins is large, prefer reusing them: penalize new bin more.
        score += 0.4 * mean_residual;
        // If no open bin could fit at all, opening is necessary: reduce penalty.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Reuse reward: favor bins whose residual is close to item size (best fit sharpening).
        let waste = (bin_residual - item_size) as f64;
        score -= 10.0 * (1.0 - waste / bin_capacity as f64);
    }

    // Lookahead: if the next item would fit exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr && pr - next_item_size <= 10 {
            score -= 8.0;
        } else if next_item_size > pr {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Stream progression: late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 10.0 * progress;
    }

    // Harmonic modulo logic on item size: items in "awkward" classes (e.g. 51..60 leaving 40s)
    // pair well with complements; reward bins whose post_residual complements the item class.
    let item_class = item_size % 10;
    if !is_new_bin && item_class != 0 {
        // Bins whose residual mod 10 == item_class tend to leave clean multiples of 10.
        if bin_residual % 10 == item_class {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the lookahead item => likely dead space.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the lookahead item.
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: prefer bins where the item fills a large fraction.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    score += 0.15 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are fragmented
        // (low mean residual) or this is the last-chance bin is unavailable.
        score += 20.0 + 0.3 * mean_residual;
        if fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score += 15.0; // open bins still have room; avoid spreading
        }
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Early stream: be slightly conservative with bin openings.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 5.0 * (1.0 - progress * 5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: perfect match with the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Usable by the next item: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= (20.0 - slack.min(20.0)) * 0.5;
        } else {
            // Dead space too small for the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(40.0) * 2.0;
        }
    }

    // Penalize tiny unusable dead space (below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the mean residual (best-fit bias).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && item_size + next_item_size > bin_capacity);
        if poor_fit {
            score -= 250.0;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 100.0 + (open_bins_count as f64) * 5.0;
        }
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 120.0;
    }

    // Penalize creating dead space that no plausible item can fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 && post_residual > 0 {
        score += 150.0 * (1.0 - progress);
    }

    // Lookahead: reward bins whose post-residual fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 60.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 0.3 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0 + 0.5 * (bin_residual - item_size) as f64;
    }

    // Global state: when many bins are open with slack, discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins can absorb the item.
        if fitting_bins_count > 0 {
            score += 500.0 + 20.0 * fitting_bins_count as f64;
        }
        // Opening a bin is more acceptable late in the stream or with few open bins.
        score -= 50.0 * progress;
        score -= 10.0 * open_bins_count.min(10) as f64;
    } else {
        // Prefer bins with residuals close to the item (tightness reward).
        let tightness = (bin_residual - item_size) as f64;
        score += 0.1 * tightness;
        // Slight preference for bins below mean residual (consolidate fuller bins).
        score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear penalty on wasted space (quadratic coupling with progress)
    let post_frac = post / cap;
    score += 2.5 * post_frac * post_frac * cap * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - post / (item + post).max(1.0);
    score -= 4.0 * tightness * tightness;

    // If next item fits into post_residual, reward (leave room for lookahead)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 3.0 * (1.0 - slack * slack);
        } else {
            // dead space relative to lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap / cap * 10.0;
        }
        let _ = nxt;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize proliferation of open bins with high mean residual
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    score += 0.3 * (mean_residual - post).abs() / cap;

    // New-bin candidate (empty bin): make it unattractive unless residual is tiny elsewhere
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by capacity eighths.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1);
    score += match class {
        0 => -40.0,                       // near-perfect fill
        1 => -18.0,
        2 => -6.0,
        3 => 4.0,
        4 => 10.0,
        5 => 16.0,
        6 => 22.0,
        _ => 28.0,
    };

    // Exact-fit bonus: post residual is an exact fraction of capacity (1/2, 1/4, etc.)
    if post_residual > 0 {
        for k in [2u32, 4, 5, 8, 10] {
            if post_residual * k == bin_capacity {
                score -= 25.0;
                break;
            }
        }
    } else {
        score -= 60.0; // closed bin perfectly
    }

    // Lookahead: does next item fit the post residual exactly or well?
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 55.0;
            } else if slack <= 5 {
                score -= 30.0;
            } else {
                score -= (10.0 * slack as f64) / cap;
            }
        } else {
            // next item won't fit here; penalize large dead space left behind
            score += 0.25 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Many fitting bins: mild penalty to encourage tightest fit via residual ordering.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only open a new bin when existing residuals are fragmented
    // and item is large (harmonic class of item size).
    if bin_residual == bin_capacity {
        let item_class = item_size / eighth.max(1);
        let fragmentation = mean_residual / cap;
        score = 40.0 + 30.0 * fragmentation;
        if item_class >= 6 {
            score += 50.0; // large items: strongly prefer existing bins
        }
        if post_residual == 0 && open_bins_count == 0 {
            score -= 100.0; // nothing open, must open
        }
    }

    // Progress coupling: late in stream, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are unusably small are pure waste.
    if post_residual < 10 {
        // Perfect or near-perfect fill -> strong reward.
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Risky gap: likely dead space unless next item is tiny.
        score += 15.0;
    } else if post_residual < 35 {
        // Moderate gap: mild penalty.
        score += 6.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // Leftover cannot fit next item: penalize proportionally to waste.
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening yet another
    // (the new-bin candidate has residual == capacity, so this mainly hits it).
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 2.5;
    } else {
        // Mild preference for tighter existing bins relative to mean residual.
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64).recip().min(1.0);
        } else {
            // Dead space relative to lookahead: penalize if next item can't use leftover.
            let waste = next_item_size as f64 - post_residual as f64;
            if waste > 20.0 {
                score += waste * 0.5;
            }
        }
    }

    // Compare residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.3 {
            score -= 20.0; // consuming a bin that's almost full is good
        } else if ratio > 1.5 {
            score += 10.0; // fragmenting a large-residual bin
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin fits well
    // (base score = capacity residual is naturally high, add slight penalty
    // unless open bins are scarce or stream is ending).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.35 * (waste / 10.0).powi(2);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize bins whose post-residual can't host the next item
    // when the next item could otherwise fit nowhere else.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > bin_capacity - post_residual {
            // dead space for the next item; mild penalty scaled by dead size
            score += 0.15 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
        // If next item exactly fills post-residual, big reward (perfect pair).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // New-bin candidate logic: empty bin gets a baseline penalty so we prefer
    // reusing bins, unless reuse would create large dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If item is huge relative to capacity, new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into bins that leave small residuals.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.05 * mean_gap;

    // Prefer bins already below mean residual (consolidating fuller bins).
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Late-stream pressure: near the end, minimize bin count aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: quadratic in normalized post-residual, modulated by stream progress.
    let mut score = post * (1.0 + 0.8 * progress) - 2.5 * post * x * (1.0 - x);

    // Reward tight fits, stronger late in the stream.
    let tightness = 1.0 - x;
    score -= tightness * tightness * cap * (0.5 + 0.7 * progress);

    // Penalize creating dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.0 + progress);
        } else {
            score -= 0.4 * (post - nxt).min(cap) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 0.6 * cap * (1.0 + progress);
    }

    // Mild pressure to prefer bins with residuals below mean (consolidate).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference for fewer open bins early on.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * x;

    // Smooth cubic penalty on very large leftover space (waste indicator).
    score += 0.3 * x * x * x * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of capacity
    let class = post_residual % (bin_capacity / 10).max(1); // class width 10
    let class_penalty = (class as f64) * 0.35;
    score += class_penalty;

    // Exact-fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small unusable dead space penalty (harmonic low classes)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Next-item lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + (next_item_size as f64) * 0.15;
        } else {
            // penalize leaving residual that no plausible next item uses
            score += (post_residual as f64) * 0.08;
        }
    } else {
        // last item: prefer filling tightly
        score -= 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening unless current bins are tight
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter fill)
    score += (mean_residual - post_residual as f64) * 0.25;

    // Progress coupling: later in stream, tighten more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * progress * 0.3;

    // Integer-division threshold on post_residual
    let half = bin_capacity / 2;
    if post_residual > half {
        score -= 8.0; // roomy bin is fine
    } else if post_residual == half {
        score += 5.0; // awkward half state
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps that are dead relative to minimum plausible item size are heavily penalized.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits (small but not zero residual).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 35.0;
    }

    // Tightness relative to bin residual: prefer bins where item consumes most of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual >= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when this bin's residual would become dead space
    // or when open-bin pressure is low and fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by how many bins are already open.
        score = 30.0 + 4.0 * open_bins_count as f64;
        // If placing in this bin would leave a small dead gap in some open bin anyway,
        // opening fresh is fine; but reward keeping a new bin closed when a good fit exists.
        if post_residual == 0 {
            score -= 5.0;
        }
        // Early in stream, opening bins is cheap to build a portfolio of residuals.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Open-bins pressure: discourage spreading across many bins when residuals are large.
    score += 0.05 * open_bins_count as f64;

    // Lookahead coupling: if next item fits the post_residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits (within 5), mild reward.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 5 {
        score -= 5.0;
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (keeps balance),
    // penalize outliers creating fragmented residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64).powf(1.3) * 0.5;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let chain = next_item_size as f64;
        if post_residual as f64 == chain {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits here: mild reward proportional to how snugly
            let slack = post_residual as f64 - chain;
            score -= 200.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot use the leftover: penalize dead space relative to next size
            score += (chain - post_residual as f64) * 1.5;
        }
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would be wasted badly.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the best existing fit is poor.
        // Base cost of a new bin:
        score += 120.0;
        // Attractive if item is large and would leave small unusable residue elsewhere.
        if item_size as f64 > bin_capacity as f64 * 0.8 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0;
        }
    }

    // Early in the stream: allow more bins (flexibility); late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 20.0;

    // Many open bins: discourage spreading, prefer tight packing.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual,
    // penalize if next item fits but leaves nothing useful.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0; // next item won't reuse this bin
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score += (open_bins_count as f64).ln() * 4.0 * tightness;

    // Pull toward mean residual: avoid wasting bins with large residuals
    // when the average residual is small.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: empty bin gets a baseline penalty so it
    // only wins when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * tightness;
        // Late in the stream, opening new bins is cheaper than forcing bad fits.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Mild time decay: early on, be pickier about residual quality.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;

    // Base: post-residual, with smooth non-linear shaping of dead space
    let mut score = pr + 30.0 * fit_ratio * fit_ratio * cap;

    // Tight fits rewarded quadratically
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * tightness * tightness;

    // Stream-progress coupling: later in stream, penalize residual more (urgency to pack tight)
    score += 25.0 * progress * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: prefer residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 20.0 * (nxt / cap);
        } else {
            score += 15.0 * ((nxt - pr) / cap);
        }
    }

    // Crowd penalty: many open bins, prefer consolidating into low-mean-residual bins
    let crowd = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).ln() * 10.0;
    score += crowd * (1.0 - (mean_residual / cap).min(1.0));

    // New-bin candidate: make it mildly unattractive unless residual is hopeless
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) - 10.0 * progress;
        if item_size as f64 / cap < 0.35 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    // Classes: [0..5], [6..15], [16..30], [31..50], [51..cap]
    let class = if post_residual <= 5 { 0u32 }
        else if post_residual <= 15 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Penalize dead space per class: tiny leftovers are near-unusable.
    let class_penalty: [f64; 5] = [40.0, 18.0, 6.0, 0.0, -4.0];
    score += class_penalty[class as usize];

    // Integer-division thresholds: post_residual divisible bands (harmonic slots).
    // A post_residual that is a "nice" slot (e.g. exact multiple of 10, or 25/50/75)
    // is more likely to be filled by future items.
    let nice_slot = (post_residual % 10 == 0 && post_residual >= 10)
        || post_residual == 25 || post_residual == 50 || post_residual == 75;
    if nice_slot { score -= 8.0; }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let after_next = post_residual - next_item_size;
            if after_next <= 5 { score -= 12.0; }
            else if after_next > 50 { score += 6.0; }
        } else {
            // Next item won't fit here; leftover must survive another round.
            if post_residual > 0 && post_residual < 10 {
                score += 15.0; // stranded dead space
            }
        }
    }

    // Last chance: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless it creates extreme waste).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual > 0 && post_residual < 10 {
            score += 20.0; // still penalize stranding
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are heavily fragmented and the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Base cost of a fresh bin keeps it from winning by default.
        score += cap * 0.9;
        if fragmentation > 0.6 && item_size >= 50 {
            score -= cap * 0.5 * fragmentation * (0.5 + 0.5 * progress);
        }
        // If the new bin would leave a very flexible residual, slightly better.
        if item_size <= 20 { score += 20.0; }
    } else {
        // Prefer filling already-open bins over leaving many half-empty bins.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Tightness reward: how well the item fills this bin relative to others.
        let fill = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits generally: prefer bins where item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving residual that no plausible next item can use, but reward when
    // post_residual exactly matches lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin_candidate = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if new_bin_candidate {
        score += 20.0 + 8.0 * open_bins_count as f64;
        // But allow new bin if all open fits would create dead space.
        if post_residual > 0 && post_residual < 10 && fitting_bins_count <= 2 {
            score -= 70.0;
        }
        // Early stream: opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 30.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize huge leftover relative to capacity (wasted space).
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into post residual: strong lookahead reward,
    // scaled by how tightly it fits (smaller leftover after next item is better).
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 25.0 + (after_next as f64).min(20.0);
    } else if next_item_size > 0 {
        // Next item will NOT fit here: penalize dead space proportionally.
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Reward tight packing relative to mean residual: bins below mean residual
    // are being consumed efficiently; penalize leaving space above mean.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or all existing fits are very loose.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Penalize new bins generally; reduce penalty when item is big
        // (a big item in a fresh bin wastes little).
        score += 45.0 - 35.0 * tightness;
        if next_item_size > 0 {
            // Fresh bin can host both this and next item comfortably.
            if bin_capacity >= item_size + next_item_size {
                score -= 20.0;
            }
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    }

    // Mild penalty for leaving many open bins with fragmented residuals.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // Dead space: smaller than the next item's need.
            let dead = post_residual as f64;
            score += 8.0 * (dead / (bin_capacity as f64)) * (dead / (bin_capacity as f64)) * 10.0;
        } else {
            // Residual can host the next item: reward proportional to how snugly.
            let snug = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - snug / (bin_capacity as f64));
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: late in the stream, consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Penalize scattering when many bins are open relative to mean residual.
    if open_bins_count > 1 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * spread * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        let poor_existing = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let min_needed = item_size as f64;
        let waste_open = (mean_residual - min_needed).max(0.0);
        score += 30.0 - 25.0 * poor_existing - 1.5 * waste_open - 5.0 * progress;
        // Large next item makes a fresh bin more valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_res = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += (prog2 * 12.0 + prog3 * 18.0) * norm_res * norm_res;

    // Reward tight fits more aggressively as stream advances
    score -= norm_item * (10.0 + 30.0 * prog2);

    // Penalize large leftover dead space quadratically
    score += 8.0 * norm_res * norm_res * (1.0 + progress);

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 10.0 * norm_next * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * norm_next;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many bins are already open and progress is high
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) + 6.0 * progress;
    }

    // Coupling with mean residual across open bins
    score += 0.05 * (mean_residual - post_residual as f64) * (1.0 + prog3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small fraction
    // of capacity is nearly unusable; penalize residue in the "dead zone".
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.10 {
        score += 12.0 * (0.10 - frac);
    } else if frac == 0.0 {
        score -= 15.0; // perfect fit
    }

    // Modulo-class logic: residual classes mod 10 — small odd leftovers
    // pair poorly with typical item sizes.
    let class = post_residual % 10;
    if class != 0 && post_residual > 0 {
        score += 2.5 * (10 - class) as f64 / 10.0;
    }

    // Lookahead: reward if the next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let nxt_frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nxt_frac; // next item can use this bin's space
        } else {
            score += 3.0; // next item won't fit here
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins among many open bins.
    score -= 4.0 * (bin_residual as f64 / bin_capacity as f64);

    // Late in the stream, tighten up: discourage opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += 5.0 + 15.0 * progress;
        if open_bins_count == 0 {
            score -= 25.0; // must have a bin
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "wasted"; using it is cheap.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= 1.5 * diff.min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Lookahead: if the next item fits into the resulting residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // creates dead space relative to lookahead
    }

    // Last chance: strongly prefer using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    score += open_bins_count as f64 * 0.3;

    // Mean-residual coupling: prefer bins below mean residual (fill emptier... actually
    // prefer filling bins with less residual to consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New empty bin candidate must look unattractive unless nothing fits decently.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness;

    // Aggressive 2-step lookahead: strongly reward bins where the next item
    // exactly matches the post_residual (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_quality = 1.0 - (gap / bin_capacity as f64);
        score -= 30.0 * match_quality;
        // Extra bonus for an exact or near-exact chain (gap <= 5).
        if gap <= 5.0 {
            score -= 15.0;
        }
        // Penalize leaving residual that is too small for the next item
        // (dead space relative to lookahead).
        if (post_residual as i64) < (next_item_size as i64) {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize post_residual far below mean residual (creating unusable slivers).
    if (post_residual as f64) < mean_residual {
        score += 0.6 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for opening a brand-new bin when plenty of bins fit the item.
    if bin_residual == bin_capacity && fitting_bins_count > 2 {
        score += 20.0;
    }
    // Favor new-bin opening early in the stream (cheap to have bins open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Slight penalty per open bin to encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tight = (post_residual as f64) / (bin_capacity as f64);
        score += tight * tight * 40.0;
    }

    // Lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let diff = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 2.0
        };
        score += diff * 0.5;

        // Perfect two-item chain bonus.
        if post_residual == next_item_size {
            score -= 35.0;
        }
    }

    // Last-chance bin: penalize opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        score += 30.0 - pressure * 50.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Time horizon: early on, be frugal with bins; late, just finish cleanly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (open_bins_count as f64).ln();

    // Prefer bins with residuals below the mean (consolidate fullness).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth non-linear coupling: waste grows super-linearly with post_residual,
    // modulated by stream progress (late in the stream, tight fits matter more).
    let waste_penalty = (norm_post * norm_post) * (1.0 + 2.0 * progress) * cap * 0.5;
    score += waste_penalty;

    // Reward filling bins deeply (large item relative to residual), smoothed.
    let fill_reward = (norm_item * norm_item) * cap * 0.4;
    score -= fill_reward;

    // Lookahead: bonus if post_residual leaves room for the next item (smooth kernel).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = pr - ns;
        if slack >= 0.0 {
            let k = (slack / cap) * std::f64::consts::PI;
            let kernel = (1.0 + (k * 0.5).cos()) * 0.5;
            score -= kernel * (6.0 + 6.0 * progress);
        } else {
            // Penalize post-residuals just barely too small for the next item.
            let gap = (-slack / cap).min(1.0);
            score += gap * gap * 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize proportionally to how well existing bins cluster;
    // opening a bin is fine when open bins have small residuals (mean_residual low).
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        let crowd = (open_bins_count as f64).ln().max(0.0);
        let openness = mean_norm * (1.0 + 0.5 * crowd);
        score += 18.0 + 30.0 * openness * (1.0 - 0.5 * progress);
        // Late in the stream, prefer squeezing into existing bins even harder.
        score += 20.0 * progress * progress;
    }

    // Mild preference for bins with residuals close to the item (tight fit signal),
    // computed as a smooth function of relative deviation.
    let dev = ((bin_residual as f64 - item_size as f64) / cap).abs();
    score += dev * dev * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1..10] is nearly wasted; reward tight fits.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: excellent
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 10 {
        score -= 15.0;
    } else if pr <= 20 {
        score += 8.0; // awkward dead zone
    } else if pr <= 30 {
        score += 3.0;
    } else {
        score -= 5.0; // large residual still reusable
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair well with typical sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: can next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 12.0;
            // Exact modulo harmony: post residual is a multiple of next size class
            if pr as u64 % (next_item_size as u64) == 0 {
                score -= 8.0;
            }
        } else if next_item_size as f64 > post_residual as f64 && post_residual < 10 {
            score += 6.0; // dead space that blocks the lookahead
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only good if current residual is tiny trash.
    if bin_residual == bin_capacity {
        let trash = post_residual <= 10 && next_item_size > post_residual && next_item_size > 0;
        if trash {
            score -= 10.0; // abandon nearly-full bin, prefer fresh bin
        } else {
            score += 45.0 + 0.3 * (open_bins_count as f64); // discourage opening bins generally
        }
    }

    // Congestion control: many open bins -> prefer filling existing ones.
    score += 0.15 * (open_bins_count as f64);

    // Progress bias: late in the stream, tighten fits more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (20.0 - (post_residual as f64).min(20.0));

    // Deviation from mean residual: prefer bins with residual close to item (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are worthless; penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 500.0; // perfect fit, zero dead space
    } else if post_residual <= 10 {
        // gap too small for typical items (sizes 1..=100 but bulk >= 10 in classic case):
        // treat as near-dead space, strongly discourage leaving it here.
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual <= 20 {
        // small gap: mild penalty proportional to wasted fraction of capacity
        score += 8.0 + post_residual as f64 * 0.4;
    } else {
        // usable gap: reward leaving room for the lookahead item if it fits
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // reward larger usable residuals slightly
        score -= post_residual as f64 * 0.05;
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 12.0 * fill_ratio;
    } else if fill_ratio > 0.7 {
        score -= 5.0 * fill_ratio;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual);
        score = 40.0 + crowd * 10.0;
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when a unique fit exists
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin guarantees room for the next item
            score -= 5.0;
        }
    }

    // Open-bin pressure: discourage proliferation of bins late in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score += open_bins_count as f64 * (0.5 + 2.0 * progress);
    }

    // Prefer bins whose residual is close to the stream's mean residual
    // (keeps bin states homogeneous, easier future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Reward proportional to how well next item fills the remainder.
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64)).max(0.0);
        } else {
            // Next item cannot fit: penalize wasted post residual relative to next item.
            let excess = (next_item_size - post_residual) as f64;
            score += 0.15 * excess.min(80.0);
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 0.1 * post_residual as f64;
    }

    // Penalize bins that deviate from mean residual (keep balance / avoid fragmenting).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 45.0 - 20.0 * tightness;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.1 * next_item_size as f64;
        }
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Late in stream: be more conservative, avoid opening new bins unnecessarily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill strongly favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize dead space relative to capacity, nonlinearly.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is very fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 45.0 + 20.0 * progress + 30.0 * open_pressure;
        if item_size >= 60 {
            score -= 25.0; // large items fit better in fresh bins
        }
    }

    // Mild preference for fuller bins (small residual before placement).
    score += 0.1 * (bin_residual.saturating_sub(item_size)) as f64;
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Base: post-residual waste, with non-linear polynomial growth
    let mut score = pr + 0.015 * pr * pr / cap;

    // Tight-fit reward: smooth quadratic coupling of post_residual with item size
    let fit_ratio = item / cap;
    score -= 2.0 * (1.0 - pr / cap) * fit_ratio * (1.0 - fit_ratio);

    // Stream progress coupling: later in stream, punish residual waste harder (polynomial in progress)
    let prog_term = progress * progress;
    score += prog_term * pr * 0.5;

    // Penalize residuals that cannot fit the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0);
        score += 0.8 * gap + 0.005 * gap * gap;
        // Reward if post-residual still fits next item well
        let slack = (pr - nx).max(0.0);
        score += 0.3 * (slack / cap) * slack;
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // New-bin candidate: penalize opening bins unless residual here is very poor
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized progressively; acceptable only if this bin's fit is bad
        score += 8.0 - 3.0 * (pr / cap) * (1.0 - progress);
        // If current bin is a decent fit, discourage new bin even more
        let waste = (bin_capacity - item_size) as f64;
        if waste as u32 <= bin_capacity / 4 {
            score += 10.0;
        }
    }

    // Mild penalty tied to mean residual divergence (fragmentation pressure)
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev;

    // Small reward for using nearly-full bins
    score -= 1.5 * (1.0 - bin_residual as f64 / cap) * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes (likely dead space) are penalized; classes that can
    // still host common small items are rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Integer-division thresholds on post_residual: classify leftover space.
    let class = post_residual / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 30.0,                    // near-perfect fit, reward strongly
        1 => score -= 20.0,                    // leftover 10-19: usable by small items
        2 => score += 5.0,                     // 20-29: awkward zone
        3 => score += 10.0,                    // 30-39: dead-ish space
        4 => score += 15.0,                    // 40-49
        _ => {}                                // large leftover: neutral
    }

    // Modulo coupling: leftover divisible by common item sizes is reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_gap = post_residual - next_item_size;
        score -= (next_gap as f64) * 0.3;
        if next_gap == 0 { score -= 25.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this leftover: penalize proportionally to waste.
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current leftovers are badly
    // fragmented (high mean residual vs this bin) or many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.9;
        // Attractive if open bins are fragmented and cannot absorb well.
        score -= (open_bins_count as f64) * 1.5;
        score -= mean_residual * 0.2;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If this is the last chance among fitting bins, never open new.
        if fitting_bins_count == 1 {
            score += 500.0;
        }
    }

    // Tie-break toward tighter existing bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Mild preference for bins whose residual is below mean (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_max = 9.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_zone_max {
        score += (dead_zone_max - post_residual as f64) * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness reward: fraction of residual consumed.
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= fill_frac * 25.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    score += open_bins_count as f64 * (2.0 - fill_frac) * 1.5;

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no existing bin fits well
    // (i.e., best possible post_residual among open bins would be large) or
    // the next item pairs well with this item's post_residual.
    if bin_residual == bin_capacity {
        // Base premium for opening a new bin.
        score += 20.0;
        // If item is small relative to capacity, opening a new bin wastes space.
        score += (100 - item_size.min(100)) as f64 * 0.3;
        // Pairing lookahead: if next item fits into post_residual, opening is good.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
        // If this bin is the only fitting bin, never open a new one.
        if fitting_bins_count == 1 {
            score += 100.0;
        }
    } else {
        // Existing bin: reward if it leaves room for the lookahead item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Dead space the next item can't use.
            score += 6.0;
        }
    }

    // Mean residual context: when mean residual is high, prefer consolidating
    // into fuller bins (low residual bins get priority).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in stream: be more conservative, avoid opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual).
    score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Aggressive 2-step lookahead: reward if next item fits into post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Perfect chaining: post residual exactly equals next item.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Penalize creating dead space that the next item cannot use.
        let waste = (post_residual as f64) - (next_item_size as f64);
        if waste > 0.0 {
            score += 0.05 * waste;
        }
    }

    // Penalize large post residuals relative to mean residual (wasteful bin).
    score += 0.3 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Favor packing into existing bins over opening new bins, especially early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 5.0 + 10.0 * progress;
    } else {
        score -= 3.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize blocking the next item
            score += 8.0 + 12.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score -= pressure * (mean_residual / bin_capacity as f64) * 5.0;

    // Time horizon: early in stream, be more willing to open new bins (higher score for new bins);
    // late in stream, consolidate into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 15.0 * (1.0 - progress) + 10.0;
    } else {
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor)
    score += 0.3 * ((bin_residual - item_size) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial base: reward tight fits with cubic decay of post_residual
    let mut score = post
        - 12.0 * (1.0 - norm_post).powi(3) * cap
        + 4.0 * norm_post.powi(2) * cap;

    // Non-linear coupling with stream progress: tighter packing matters more later
    let progress_coupling = 1.0 + 3.0 * progress * (1.0 - progress) * 4.0;
    score -= progress_coupling * 6.0 * (1.0 - norm_post).powi(2);

    // Mean residual interaction: prefer bins near the mean to balance load
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * cap * (0.5 + progress);

    // Lookahead coupling: reward leaving space for the next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let overlap = (post - nx).abs();
        let fit_term = 1.0 - (overlap / cap).min(1.0);
        score -= 10.0 * fit_term * fit_term * (0.5 + progress);
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Congestion pressure: many open bins favors filling existing ones
    let congestion = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).powi(2);
    score -= 10.0 * congestion * (1.0 - norm_post);

    // New-bin candidate: penalize smoothly unless residual is very tight elsewhere
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover is "usable"
    // (large enough for typical small items) should be rewarded.
    let pr = post_residual;
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward leaving a residual in a "good class": >= quarter is reusable,
    // tiny residuals (< quarter) are dead space -> penalize.
    if pr >= quarter {
        score -= 6.0 * (pr as f64 / bin_capacity as f64);
    } else if pr > 0 {
        // dead space: penalize proportionally to how dead it is
        score += 10.0 * (1.0 - pr as f64 / quarter as f64);
    } else {
        // perfect fit: strong reward
        score -= 15.0;
    }

    // Harmonic pairing: if the next item fits exactly (or well) into the
    // post residual, this is a harmonic class match -> strong reward.
    if next_item_size > 0 {
        let n = next_item_size;
        if n == pr {
            score -= 20.0;
        } else if n <= pr {
            let slack = (pr - n) as f64;
            // modulo-style class check: does post residual mod next item leave a tiny tail?
            let tail = pr % n.max(1);
            let tail_bonus = if tail == 0 { 8.0 } else if tail < quarter { 2.0 } else { 0.0 };
            score -= tail_bonus;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; residual is a waiting slot.
            // reward if residual is in a "half-bin" harmonic class (reusable later)
            if pr >= half {
                score -= 3.0;
            } else {
                score += 4.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: neutral-ish baseline, slightly penalized so we
    // prefer existing bins unless they create heavy dead space.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 - 5.0;
        // late in the stream, avoid opening extra bins
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.8 {
            score += 10.0;
        }
    }

    // Prefer tighter bins when many are open (reduce fragmentation)
    if open_bins_count > 3 {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Item size coupling: big items should go into big-residual bins
    if item_size > half && bin_residual >= item_size {
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    // Gaps too small for the next item are also dead weight.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 80.0;
    }

    // Reward tight fits (low post residual relative to capacity).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // If this bin is the last chance, opening new is worse.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Prefer opening a new bin if mean residual is very low (bins nearly full).
        if mean_residual < item_size as f64 * 0.5 {
            score -= 60.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading items thin.
    score += 0.15 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear pressure.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect 2-step lookahead: post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            // next item still fits here: reward proportionally to how well it fills remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
            score += diff * 0.15;
        } else {
            // next item won't fit: penalize leaving awkward small residue
            score += diff * 0.25;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly avoid opening a new bin when only this one fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave bad dead space
    // or when many bins are open and fit is loose.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let dead = if next_item_size > 0 && waste >= next_item_size as f64 { 0.0 } else { waste };
        score = 25.0 + dead * 0.5 + open_bins_count as f64 * 0.5;
        // early in stream, opening fresh bins is cheap; later, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Slight preference to fill bins with less residual overall.
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Superlinear waste penalty: small leftovers are acceptable, large ones are dead space.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead coupling: penalize residuals too small for the next item,
    // reward residuals that can still host the upcoming item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
