    }

    // Mild global pressure: many open bins -> favor consolidation.
    score += 0.05 * open_bins_count as f64;
    score -= 0.02 * mean_residual;

    // New-bin candidate: baseline cost slightly above a decent fit,
    // decreasing over time so late-stream we tolerate fresh bins less.
    if bin_residual == bin_capacity {
        score = 55.0 + 25.0 * progress - 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - post / cap;

    // Non-linear tightness reward: quadratically favor fuller placements.
    score -= 12.0 * fill * fill * fill;

    // Penalize dead space relative to mean residual across open bins.
    let dead = post - mean_residual;
    score += 0.35 * dead * (1.0 + progress);

    // Smooth stream-progress coupling: later in the stream, prefer using existing bins.
    let openness = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * openness * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly reward, decaying with progress.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress) + 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, bonus (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_score = 1.0 - (post - nxt).abs() / cap;
        if match_score > 0.0 {
            score -= 10.0 * match_score * match_score * (1.0 - progress);
        }
        // Penalize leaving a gap smaller than next item (unusable wedge).
        if post < nxt && post > 0.0 {
            score += 6.0 * (1.0 - post / nxt) * (0.5 + progress);
        }
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    let is_new_bin = (bin_residual as u32 == bin_capacity) && (item_size as u32 <= bin_capacity);
    if is_new_bin {
        let waste_if_used = (0.0f64).max(mean_residual - (cap - item_size as f64));
        score = cap - item_size as f64 + 15.0 + 3.0 * openness + waste_if_used * 0.2 - 25.0 * progress * (1.0 - fitting_bins_count.min(3) as f64 / 3.0);
        // If only one fitting bin (last chance), new bin should lose.
        if fitting_bins_count <= 1 {
            score += 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits (small post_residual) non-linearly.
    score -= 60.0 * (-post_residual as f64 / 12.0).exp();

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic classes: post_residual bucketed by modulo-10 classes.
    let pr = post_residual;
    let class = pr % 10;
    // Residuals in classes 1..=9 (non-multiples of 10) are "dead-ish" for
    // integer-sized streams; multiples of 10 are reusable harmonic slots.
    if class != 0 && pr > 0 {
        score += (10 - class) as f64 * 1.5; // worse if just above a multiple of 10
    } else if pr > 0 {
        score -= 8.0; // reusable class reward
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0; // chain placement enabled
            // Harmonic match: next item exactly consumes a harmonic class
            if pr % 10 == 0 && next_item_size % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Dead space created relative to next item
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0;
    }

    // New-bin candidate handling: empty bin (residual == capacity).
    if bin_residual == bin_capacity {
        // Prefer new bin only if no open bin fits well (post_residual would be large)
        // or few bins open. Penalize opening new bins generally.
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        score += pressure;
        score += open_bins_count as f64 * 0.5;
        // If item is small relative to capacity, wasteful to open new bin.
        score += (cap - item_size as f64) * 0.6;
    }

    // Late in stream, consolidate into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64 - mean_residual / cap.max(1.0)) * 2.0;

    // Mild penalty proportional to current bin's slack vs mean (avoid outlier waste).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward very tight fits (item nearly fills the bin).
    if post_residual == 0 {
        score -= 40.0;
    } else if item_size as f64 / bin_capacity as f64 > 0.85 {
        score -= 15.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, keep bins tight; later, allow slight slack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    // New-bin candidate: make it unattractive unless the fit would be terrible elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Mild alignment with mean residual to spread load sensibly.
    score += 0.1 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match between
    // post_residual and the next item's size (perfect two-item packing).
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post == nxt {
            score -= 60.0; // exact two-item fit: ideal
        } else if nxt <= post {
            // next item fits; reward tightness of the chain
            let slack = post - nxt;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // extra reward if chain leaves a small, still-usable remainder
            if slack <= 10.0 {
                score -= 8.0;
            }
        } else {
            // next item does NOT fit here; penalize by the gap size
            let gap = nxt - post;
            score += 0.35 * gap.min(60.0) as f64;
        }

        // If post_residual is dead space (too small for any realistic item),
        // penalize proportionally to how "wasted" it is.
        if post > 0 && post < 10 {
            score += 12.0 * (1.0 - post as f64 / 10.0);
        }
    } else {
        // Last item: just minimize final waste, reward full usage.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins already below mean residual (tight bins get filled first),
    // keeping loose bins available for future large items.
    score += 0.5 * (post_residual as f64 - mean_residual).max(-30.0).min(30.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residual would be tiny or
    // the item is large and current bins are loose.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let loose_bins = mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 1;
        if large_item && loose_bins {
            score -= 5.0; // opening fresh bin for a big item among loose bins is fine
        } else {
            score += 15.0; // default: discourage opening new bins
        }
    }

    // Early in the stream, be slightly more willing to keep bins tight;
    // late in the stream, prioritize closing out bins cleanly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space left after placement (wasted slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use the leftover; penalize proportionally to wasted space
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many competing bins: reward choosing the emptiest (diversity preservation).
    if open_bins_count > 1 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 15.0 * rel;
    }

    // Time horizon: early in the stream, be conservative about filling bins tightly;
    // later, be aggressive to close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * fill_ratio;

    // New-bin candidate handling: opening a new bin is generally costly, but attractive
    // when the item is large and few bins fit it, or late in the stream with slack.
    if bin_residual == bin_capacity {
        let base_penalty = 45.0;
        let scarcity_bonus = if fitting_bins_count <= 2 { 20.0 } else { 0.0 };
        let big_item_bonus = 15.0 * (item_size as f64 / bin_capacity as f64);
        let late_bonus = 10.0 * progress;
        let crowd_penalty = 3.0 * open_bins_count as f64;
        score += base_penalty + scarcity_bonus + big_item_bonus + late_bonus - crowd_penalty;
        // An empty new bin wastes nothing now; slight reward if item is huge.
        if item_size >= 80 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early on, residual waste is cheap; later, tight packing matters more.
    let waste_weight = 0.4 + 1.6 * progress * progress;
    score += waste_weight * (pr * pr) / cap;

    // Reward near-perfect fills with a smooth quartic term.
    let fill = pr / cap;
    score -= 8.0 * (1.0 - fill) * (1.0 - fill) * (1.0 - fill) * (1.0 - fill) * (1.0 - fill);

    // Lookahead: reward residual that exactly (or smoothly) fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let fit_quality = (1.0 - gap / cap).max(0.0);
        let la_weight = 0.5 + 2.0 * progress;
        score -= la_weight * fit_quality * fit_quality * nxt;
        // Penalize residuals too small for anything useful later in the stream.
        if pr < nxt {
            score += (pr - nxt).abs() * (0.2 + 0.8 * progress);
        }
    } else {
        // Last item: strongly reward tightest possible fit.
        score -= 6.0 * (1.0 - fill);
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // New empty bin candidate: penalize opening a new bin unless existing
    // residuals are all too fragmented (smoothly coupled with mean residual).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let fragmentation = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 12.0 * progress - 6.0 * fragmentation - 1.5 * crowd;
        // If the item would leave a nicely reusable residual even in a new bin,
        // soften the penalty slightly (smooth quadratic in post_residual).
        score -= 2.0 * (1.0 - fill) * (1.0 - fill);
    } else {
        // Prefer bins whose residual is close to the item (smooth reward).
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64).clamp(0.0, 1.0);
        score += 1.5 * tightness * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (dead-space taxonomy) ---
    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class A: residual smaller than the minimum item size (1) -> impossible; but
        // residual below the smallest realistic item is near-dead space.
        if post_residual < 10 {
            score += 60.0; // dead-space penalty: nothing may ever fill this
        }
        // Class B: residual in a "harmonic" residue class of capacity —
        // residuals that are multiples of common item granularities are reusable.
        let reusable = (post_residual % 10 == 0)
            || (post_residual % 20 == 0)
            || (post_residual % 25 == 0)
            || (post_residual % 50 == 0);
        if reusable {
            score -= 15.0;
        }
        // Class C: integer-division threshold — residual large enough to host
        // a "half-bin" chunk is structurally valuable.
        if post_residual >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // --- Lookahead coupling: does the next item fit into the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect harmonic match: next item exactly consumes the leftover class.
            if next_item_size == post_residual {
                score -= 120.0;
            } else {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; if post_residual is small it becomes waste.
            if post_residual < next_item_size && post_residual < 15 {
                score += 20.0;
            }
        }
    }

    // --- Tightness reward: relative fill of the bin ---
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill; // quadratic preference for fuller bins

    // --- Last-chance logic: this is the only bin that can take the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0; // strongly prefer using the sole fitting bin
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: high, so we only open when existing
        // placements would be truly wasteful.
        let mut new_bin_score = 150.0;
        // If the item is large, keeping it alone is often fine.
        if item_size >= bin_capacity / 2 {
            new_bin_score -= 30.0;
        }
        // Late in the stream, opening bins is less recoverable — be more reluctant.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 40.0 * progress;
        // If many bins are open with fat residuals, prefer reusing them.
        if mean_residual > item_size as f64 * 1.5 {
            new_bin_score += 25.0;
        }
        // If no existing bin can even fit the item, new bin is the only option.
        if fitting_bins_count == 0 {
            new_bin_score -= 500.0;
        }
        score = new_bin_score;
    }

    // --- Mild dispersion penalty: avoid scattering across too many bins ---
    if bin_residual != bin_capacity {
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can't hold even the smallest
    // plausible future item are pure waste.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 40.0 * (10.0 - dead);
    } else if dead > 0.0 && dead < 30.0 {
        // small gaps are risky: hard to fill with items 10..80
        score += 0.9 * (30.0 - dead);
    } else if dead == 0.0 {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Tight fit reward relative to bin size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            // residual too small for the known next item -> penalize
            score += 0.5 * (post_residual as f64);
        }
    }

    // Mean residual context: bins far below mean residual are more valuable to fill
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: moderate score, beaten by good fits
        score = post_residual as f64 + 25.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space is exponentially better).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + 5.0 * (6 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 60.0 - slack as f64 * 2.0;
            } else {
                score += slack as f64 * 0.3; // leftover after lookahead is future dead space
            }
        } else {
            // next item cannot fit here; post_residual becomes stranded
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: only care about current fill.
        score -= item_size as f64 * 0.1;
    }

    // Compare against mean residual: bins already tighter than average are good targets.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good home.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing bins are preferred unless they fit poorly.
        score += 30.0;
        // In early stream, opening bins is cheap and keeps options open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 25.0;
        // If the item is large and open bins are tight, a fresh bin is valuable.
        if item_size as f64 > mean_residual {
            score -= 45.0;
        }
        // Lookahead: a fresh bin can host both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 55.0;
        }
        // With many open bins, prefer consolidation into existing bins.
        score += open_bins_count as f64 * 2.0;
    }

    // Mild pressure to fill bins deeply rather than spreading across many.
    score += open_bins_count as f64 * 0.5;

    // Prefer keeping moderate residuals (>= 20) that remain usable later.
    if post_residual >= 20 && post_residual < 40 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 + 20.0 * (6 - post_residual) as f64;
    } else {
        // Dead-space penalty grows super-linearly with waste.
        let waste = post_residual as f64;
        score += 0.02 * waste * waste;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 60.0 - 4.0 * gap;
            } else {
                score += 0.05 * gap;
            }
        }
        // If next item cannot fit here anyway, mildly prefer conserving this bin's residual.
        if next_item_size > post_residual {
            score += 5.0;
        }
    } else {
        // Last item: just dump into any fitting bin.
        score -= 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when existing bins would
    // waste a lot or when many bins are open and mean residual is already high.
    if bin_residual == bin_capacity {
        score += 80.0;
        score += 0.5 * mean_residual;
        score += 2.0 * open_bins_count as f64;
        // Early in stream, opening bins is cheaper.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - t);
        // If item is large, a fresh bin is attractive.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    } else {
        // Favor bins with smaller residual overall (best-fit tilt), modulated by mean.
        let diff = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * diff;
        // Many open bins: encourage consolidation into existing space.
        if open_bins_count > 3 {
            score -= 3.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = fit_norm * fit_norm * (1.0 + progress) - fit_norm * progress * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - fit_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins late in the stream
    score += 2.0 * open_bins_count as f64 * progress;

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 15.0 * (1.0 - (pr - ns) / cap) * (1.0 - progress);
        } else {
            score += 10.0 * ((ns - pr) / cap);
        }
    }

    // Mean residual context: prefer bins near the mean early, deviating late
    score += 5.0 * ((pr - mean_residual) / cap).abs() * progress;

    // New-bin candidate: prefer opening only when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 45.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot band" does the leftover fall into?
    // Bands of size cap/4 (25): 0-24 (dead), 25-49 (usable by mid items), 50-74, 75-99 (prime).
    let band = (post_residual * 4) / bin_capacity; // 0..=4 (4 only when empty post impossible here)
    let band_f = band as f64;

    // Reward low post_residual strongly (tight fit), super-linear within band.
    score += 8.0 * (post_residual as f64 / cap);

    // Harmonic class bonus: band 0 (near-full) is excellent, band 3 (75-99) is prime for next items.
    match band {
        0 => { score -= 12.0; }
        1 => { score -= 4.0; }
        2 => { score -= 1.0; }
        _ => { score -= 6.0; }
    }

    // Exact modulo classes on post_residual: multiples of common item sizes (10/20/25/50)
    // leave residuals that future items can fill exactly.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 5.0;
    }
    // Dead space: residual too small for the minimum plausible item.
    if pr > 0 && pr < 10 {
        score += 20.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward if next item exactly fills, or lands in a harmonic class.
            score -= 6.0;
            if pr - next_item_size < 10 { score -= 6.0; }
            if (pr - next_item_size) % 10 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead potential.
            score += 4.0 + 0.05 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which costs a full bin worth of potential).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): it should only win when no
    // open bin fits or all fits are terrible. Give it a base penalty so tight fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, prefer closing out open bins rather than spawning new ones.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
    }

    // Prefer bins below mean residual when many bins are open (balance load,
    // keeping some large-residual bins available for large future items).
    if open_bins_count > 2 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Open-bin pressure: discourage scattering items across many bins
    // unless the fit is genuinely good.
    score += 0.35 * open_bins_count as f64;

    // If this bin is the only one that fits the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the lookahead item.
        score += 5.0;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * tightness;

    // Mild bonus if this bin's residual is above the mean (use the big gaps).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: make an empty bin moderately attractive so we
    // open a new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (waste-free placement).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward small post-residuals non-linearly (prefer tight fits).
    let pr = post_residual as f64;
    score += (pr / bin_capacity as f64).powi(3) * 200.0;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: partial reward scaled by how well it uses the leftover.
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * frac;
        } else {
            // Next item won't fit in the leftover: penalize creating dead space
            // that is too small to be useful (dead space < min item size 1 handled generically).
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += dead * 0.8;
            }
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual is above mean
    // (they have room to absorb), penalize bins already tighter than average creating waste.
    if post_residual as f64 > mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (avoiding bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a decent fit (post_residual would leave large unusable gap) or stream is early.
    if bin_residual == bin_capacity {
        // Empty bin baseline: mild penalty so existing reasonable fits win,
        // but reward when existing bins would be badly fragmented.
        score = 100.0 + pr * 0.1;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin guarantees next item fits too.
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder (penalize new bins implicitly
    // via last-chance bonus already; slightly tighten fit preference over time).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear term.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly enough room for the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (-gap / 20.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild preference for tighter bins among many options (already via tightness).
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Progress-based horizon: early in the stream, be conservative about
    // fragmenting bins; late in the stream, pack greedily into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Global state: if mean residual is high, bins are loose; discourage
    // adding more fragmentation there, encourage filling.
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
    score += 5.0 * mean_tight * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): penalize unless item is large relative
    // to capacity or no good fit exists (post_residual large on open bins).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 12.0 - 18.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream with many open bins, prefer filling existing bins.
        score += 8.0 * progress;
    }

    // Slight penalty for opening many bins relative to progress.
    if open_bins_count > 1 {
        score += 0.5 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: minimize post residual, but with a smooth quadratic penalty on
    // very small residuals (dead space) that grows with stream progress.
    let mut score = post;

    let dead_fraction = post / cap;
    score += dead_fraction * dead_fraction * cap * (0.5 + progress);

    // Reward tight fits (post residual near zero) more strongly later in stream.
    score -= (1.0 - dead_fraction) * (1.0 - dead_fraction) * (2.0 + 4.0 * progress);

    // Lookahead coupling: if the next item fits the post residual, reward;
    // otherwise penalize proportionally to the leftover mismatch, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 3.0 * (1.0 - nxt / post.max(1.0)) * (1.0 + progress);
        } else {
            let over = (nxt - post) / cap;
            score += over * cap * (0.3 + 0.7 * progress);
        }
    }

    // Last chance: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score += 0.05 * (post - mean_residual);

    // Mild penalty for proliferating open bins early; relaxation later.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: neutral baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress) - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual, with a harmonic-class twist.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tight * tight;

    // Harmonic classes on post_residual: dead space in low classes is nearly unusable
    // for typical item sizes; penalize awkward leftovers, reward "clean" ones.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // leftovers that are tiny (1..=9) are dead space unless they equal a common size
        if pr < 10 {
            score += 18.0; // dead residue smaller than any realistic item
        } else if class == 0 {
            score -= 6.0; // multiples of 10 are reusable
        } else if class >= 8 {
            score += 4.0; // awkward near-multiple
        }
        // integer-division thresholds: how many "average" items still fit
        let slots = pr / 25;
        score -= 3.0 * slots as f64;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; a small post_residual is fine, a large one wasted
            score += 0.05 * (pr as f64 - mean_residual).abs();
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are crowded.
    if bin_residual == bin_capacity {
        let avg_crowd = mean_residual / cap;
        // penalize opening new bins generally, less so late in the stream or with many bins
        let mut new_penalty = 20.0 * (1.0 - avg_crowd);
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_penalty *= 1.0 - 0.3 * progress;
        score += new_penalty;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.01 * open_bins_count as f64 * (1.0 - tight);

    // Small phase signal to break ties deterministically across the stream.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: small gaps (< 10, the minimum item size)
    // are permanently unusable -> heavy penalty scaled by how "wasted" they are.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 40.0;
    }

    // Moderately small gaps are risky too (few future items fit).
    if post_residual >= 10 && post_residual < 25 {
        score += (25 - post_residual) as f64 * 2.5;
    }

    // Post-residual that exactly fits the lookahead item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + post_residual as f64 * 0.5;
    }

    // Pressure from number of open bins: prefer consolidating into existing bins
    // when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is below average (tighter bins get filled first),
    // keeping larger residuals available for larger future items.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.8;

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // relative to residuals or no good fit exists; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > mean_residual as u32 { 40.0 } else { 0.0 };
        let desperate = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += 25.0 - large_item_bonus + desperate;
    }

    // Slight late-stream tightening: waste matters more near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64); // next item fits, tighter is better
            if slack <= 10.0 {
                score -= 10.0; // near-perfect chain bonus
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let miss = (next_item_size - post_residual) as f64;
            score += 0.15 * miss;
        }
    } else {
        // last item: minimize residual as much as possible
        score += 0.0;
    }

    // Compare post_residual relative to mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Dead-space penalty: small residuals that cannot fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // opening new bin is attractive if the item leaves a perfect slot for next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
        // if the item would leave large unusable residual in existing bins context, new bin ok
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
        // discourage new bins when plenty of open bins have healthy residuals
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Tightness reward: filling a bin almost completely is great
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Slight preference for bins with lower residual (best-fit flavor)
    score += 0.1 * bin_residual as f64;

    // Mild penalty for proliferating bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that no plausible item could fill.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 30.0 * dead * dead * dead;
    }

    // Lookahead coupling: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // If next item cannot use the leftover, penalize proportionally to waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.25 * overshoot.min(bin_capacity as f64);
        }
    } else {
        // Last item: any bin that fits is fine; prefer the emptiest.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when fits are scarce or item is huge.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Opening a new bin is attractive for large items, scarce fits, early stream.
        let open_bonus = 55.0 * scarcity * item_frac + 12.0 * (1.0 - progress) - 0.15 * open_bins_count as f64;
        score -= open_bonus;
    } else {
        // Slight preference for consolidating into fewer bins.
        score += 0.05 * open_bins_count as f64;
    }

    // Global state: prefer bins whose residual is near the mean (balanced packing),
    // but avoid bins far above mean residual (hoarding emptiness).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Progress-aware small adjustment: late in stream, favor closing bins tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear coupling of post residual with stream progress:
    // early in the stream, tolerate larger residuals (bins stay flexible);
    // late in the stream, penalize dead space super-linearly.
    let late = progress * progress;
    score += 60.0 * x * x * late;
    score += 25.0 * x * x * x * (1.0 - progress);

    // Reward tight fits smoothly (small post residual -> bonus)
    score -= 40.0 * (1.0 - x) * (1.0 - x) * (1.0 - late);

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly into post residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let gap = (pr - nx) / cap;
            score -= 35.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            // next item won't fit; penalize leaving residual it nearly matches
            let miss = (nx - pr) / cap;
            score += 15.0 * (1.0 - miss) * (1.0 - miss) * progress;
        }
    }

    // Prefer bins whose residual is below the mean (compact bins) mildly
    score += 0.1 * (pr - mean_residual).max(-50.0).min(50.0);

    // Slight penalty for accumulating many open bins when a tight fit exists
    score += 0.05 * open_bins_count as f64 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter.max(1)) as f64;
    score += class * 3.0;

    // Exact-ish fit: post_residual in smallest class strongly rewarded
    if post_residual < quarter {
        score -= 25.0;
    }

    // Lookahead harmony: does next item fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here: reward, scaled by how tightly it nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - (slack / bin_capacity as f64) * 10.0;
            // harmonic nesting: next item also leaves a small residue
            let next_post = post_residual - next_item_size;
            if next_post < quarter {
                score -= 10.0;
            }
        } else {
            // next item won't fit: penalize proportionally to mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 20.0;
        }
    } else {
        // last item: prefer minimal post_residual
        score -= 5.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening bins unless current placement is terrible
    if bin_residual == bin_capacity {
        score += 30.0;
        // allow new bin late in stream if mean residual is very low
        if mean_residual < 5.0 {
            score -= 20.0;
        }
    }

    // Waste relative to mean residual: bins below mean residual are worse fits
    score += (mean_residual - post_residual as f64) * 0.3;

    // Progression: early stream, be more open to new bins; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // Penalize many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.15;

    // Integer-division threshold on post_residual: dead space zones
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

