    // Mean residual coupling: if bin residual is far above mean, slightly penalize
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // dead space relative to the known next item
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // New-bin candidate: keep it neutral-ish but discourage early opening
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
        // allow opening when nothing fits well
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
