pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (small post residual)
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain two perfect placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 35.0;
        }
        // Penalize leaving residual that neither fits next item nor is tiny
        if post_residual < next_item_size && post_residual > 8 {
            score += 15.0;
        }
    }

    // Compare residual against mean residual: prefer bins with less residual (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating large dead space relative to smallest item sizes
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0;
    }

    // Late in the stream, be more aggressive about closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * progress;

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64).sqrt() * 2.0;
        // But allow new bin if no tight fit exists anywhere
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 25.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly usable by the lookahead item.
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64)).powi(4);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New empty bin candidate: penalize unless no good fit exists or stream is early.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let tightness = (post_residual as f64 / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score += 90.0 * scarcity * (1.0 - tightness.clamp(0.0, 1.0));
        score += 45.0 * (1.0 - scarcity);
    }

    // Prefer bins whose residual is close to the mean (balanced usage), scaled by openness.
    let dev = ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs();
    score += 12.0 * dev * (open_bins_count.min(20) as f64).ln().max(1.0);

    // Late in the stream, be more conservative: avoid creating tiny unusable residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, but non-linearly (quadratic coupling).
    let mut score = norm_pr * norm_pr * cap;

    // Smooth interaction: wasted space matters more as the stream progresses.
    score += norm_pr * norm_pr * progress * cap * 0.5;

    // Reward tight fits with a smooth saturating term.
    let fit = item_size as f64 / cap;
    score -= (fit * fit) * cap * 0.3;

    // Last-chance bonus: strongly prefer this bin if it is the only one that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= (nxt / cap) * cap * 0.4;
        } else {
            // Dead space relative to next item: penalize smoothly.
            let gap = (nxt - pr) / cap;
            score += gap * gap * cap * 0.5;
        }
    }

    // Prefer bins below mean residual slightly (balance smoothing), smooth in open bin count.
    let mr_norm = mean_residual / cap;
    let open_norm = (open_bins_count as f64).ln_1p();
    score += (norm_pr - mr_norm) * cap * 0.1 * (1.0 / open_norm.max(1.0));

    // New-bin candidate: penalize mildly so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score += cap * 0.35 * (1.0 - progress);
        score += cap * 0.15 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose post-residual lies in
    // "small leftover" classes are valuable; penalize dead space classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional capacity classes (eighths): dead space under 1/4 capacity is bad
    if post_residual > 0 && post_residual * 4 < bin_capacity {
        score += 0.35 * (cap - post) / cap;
    }

    // Perfect or near-perfect fit reward
    if post_residual == 0 {
        score -= 8.0;
    } else if post_residual <= 5 {
        score -= 4.0;
    }

    // Modulo-10 harmonic class of post_residual: leftovers divisible by 10
    // pair well with items in the 10..80 decade classes.
    let post_class = post_residual % 10;
    if post_class == 0 {
        score -= 2.0;
    } else if post_class >= 7 {
        score += 1.5; // awkward leftover class
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 6.0;
        } else if next_item_size < post_residual {
            score -= 1.2 * (next_item_size as f64 / post as f64);
        } else {
            // next item won't fit here; slight penalty if this bin was the only fit
            if fitting_bins_count == 1 && bin_residual >= item_size {
                score -= 0.8;
            }
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // New-bin candidate handling: only prefer fresh bin when stream is early
    // or current bin residual is very small relative to item needs.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (0.5 + 0.4 * progress);
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 2.0;
        }
    }

    // Tightness reward: how well item fills the current residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 3.0 * fill_ratio * fill_ratio;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.5 * (mean_residual - post).clamp(-20.0, 20.0) / cap;

    // Open bin pressure: many open bins -> favor consolidating
    score -= 0.05 * (open_bins_count as f64).ln().max(0.0);

    // Integer-division threshold on post_residual: chunk classes of 25
    let chunk = post_residual / 25;
    match chunk {
        0 => score += 1.0,        // 0..24: nearly dead space
        1 => score -= 0.5,        // 25..49: usable for mid items
        2 => score -= 1.0,        // 50..74: very reusable
        _ => score -= 0.2,        // 75+: large residual, less urgent
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
