    // New-bin candidate: penalize slightly so open bins are preferred unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 5.0;
        // But if no open bin fits well, new bin becomes attractive (handled by above bonuses).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Late in stream: prefer closing out bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (open_bins_count as f64).ln().max(0.0);

