    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves a gap; reward proportionally.
            let next_tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * next_tight;
        } else {
            // next item won't fit here; slight penalty for leaving awkward residue.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 6.0 * (1.0 - gap / bin_capacity as f64);
            }
        }
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large or the stream is early (keeping future flexibility).
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred by default.
        score += 18.0;
        // Early in the stream, opening bins is cheaper (more future to fill them).
        score -= 20.0 * (1.0 - progress);
        // Large items waste less of a fresh bin.
        score -= 0.15 * item_size as f64;
        // If no open bin fits at all (this is effectively forced), relax penalty.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // If many open bins exist with large mean residual, prefer consolidating
        // into them rather than opening yet another bin.
        if open_bins_count > 0 {
            score += 2.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * (open_bins_count as f64).sqrt();
        }
    }

