    // prefer keeping residuals homogeneous for future packing flexibility.
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 4.0 * dev;

    // Late in the stream, consolidate aggressively: reward using existing bins.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
