    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next fits: reward proportional to how well it fills the remainder
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 12.0 * fill;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here: residual becomes dead space for the lookahead
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Harmonic class complementarity: item class + next class == full bin harmony
    if next_item_size > 0 && item_class + next_class == 4 && post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > cap * 0.6 && item_size < bin_capacity / 2;
        if poor_fit {
            score -= 15.0; // open fresh bin rather than waste a big residual
        } else {
            score += 30.0; // discourage opening new bins for good fits
        }
    }

    // Stream progression: early on, be conservative with new bins; late, pack greedily
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    // Crowding: many open bins with high mean residual -> consolidate
    if open_bins_count > 3 && mean_residual > cap * 0.4 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (>=1) can use well.
    if post_residual > 0 {
        // Small unusable gap: heavy penalty, grows as gap gets "wasted"
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64);
        }
        // Gap too small for the likely next item: dead space for lookahead
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward tight fits relative to bin residual (fill fraction)
    let fill = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill;

    // Open bins pressure: prefer reusing existing bins when many are open
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are nearly saturated
    if bin_residual == bin_capacity {
        let saturation = mean_residual / bin_capacity as f64;
        score += 55.0 * (1.0 - saturation);
        // Early in stream, opening a bin is cheaper; later, avoid bin proliferation
        score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Mean-residual coupling: if mean residual is small, bins are tight; avoid waste
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 45.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // penalize residuals that waste space relative to next item
            score += 0.6 * (next_item_size as f64 - post_residual as f64);
        }
        // perfect chain: post residual exactly matches next item
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Tight fit reward: small post residual is good (less dead space)
    score += 1.5 * (post_residual as f64 / bin_capacity as f64).powi(3);

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate penalty: discourage opening new bins unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 70.0;
        // but if next item is large and this item leaves big residual, opening new bin is ok
        if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
            score -= 25.0;
        }
    }

    // Late in stream: be more conservative, keep bins tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize leaving dead space that can't hold the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that can still host the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (slack / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 6.0 * (dead / bin_capacity as f64);
        }
    } else {
        // Last item: just fill as much as possible.
        score -= 8.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            1.0
        } else {
            (mean_residual / bin_capacity as f64).min(1.0)
        };
        // Penalize opening new bins generally; less when open bins are full-ish
        // or the current bin would leave unusable residue.
        let waste = if post_residual < 10 {
            1.0
        } else {
            0.0
        };
        score += 20.0 * (1.0 - pressure) - 18.0 * pressure * waste;
        // Slight preference for new bins early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    // Nudge toward bins with residuals close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement (quadratic to punish dead space super-linearly)
    let mut score = pr + (pr * pr) / (2.0 * cap);

    // Tightness reward: smooth polynomial coupling of fill ratio with stream progress.
    // Early on, prefer loose packing (keep flexibility); late, pack tightly.
    let fill = (bin_residual - post_residual) as f64 / cap;
    let fill_term = fill * fill * (3.0 - 2.0 * fill); // smoothstep in [0,1]
    score -= 30.0 * fill_term * (0.4 + 0.6 * progress);

    // Lookahead: reward if the next item can still fit in the post residual (smooth decay).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits = (pr - nx).max(0.0);
        let slack = 1.0 - (fits / cap).min(1.0);
        score -= 12.0 * slack * slack;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin when a reasonable fit exists).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let waste = pr / cap;
        score -= 25.0 * (1.0 - waste * waste);
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += 0.05 * (open_bins_count as f64) * progress;

    // Pull toward the mean residual: bins far below mean residual (very empty)
    // are slightly deprioritized so fuller bins get used first.
    score += 0.15 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty via integer division thresholds.
    if post_residual > 0 {
        let class = post_residual / eighth; // 0..=8 harmonic class
        // Waste grows super-linearly for small unusable residuals.
        if post_residual < item_size.min(next_item_size.max(1)) {
            score += 12.0;
        }
        // Small residual classes (nearly full bins) are good; reward them.
        if class == 0 {
            score -= 6.0;
        } else if class == 1 {
            score -= 3.0;
        } else if class > 5 {
            // Large residual: fine only if it's a fresh bin.
            if bin_residual != bin_capacity {
                score += 2.0 * (class as f64 - 5.0);
            }
        }
    } else {
        // Perfect fill.
        score -= 10.0;
    }

    // Lookahead coupling: can next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's class divides post_residual nicely.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 4.0;
            } else {
                score -= 1.5;
            }
        } else {
            // Next item won't fit here: penalize more if residual is stranded mid-range.
            if post_residual >= quarter && post_residual < half {
                score += 5.0;
            } else if post_residual > 0 && post_residual < quarter {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Prefer tightest fit generally: relative waste term.
    score += (post_residual as f64 / bin_capacity as f64) * 4.0;

    // New-bin candidate: only attractive when current bin would leave a bad harmonic class
    // and there are many open bins already.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post_residual > 0 && post_residual < quarter;
        if bad_fit && open_bins_count > 1 {
            score -= 1.0 + 3.0 * progress;
        } else {
            score += 6.0; // default: prefer reusing open bins
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small to hold any plausible item (<=10) are pure waste.
    if post_residual < 10 {
        score += 500.0;
    }
    // Small gaps (10..=20) likely to become dead space as stream progresses.
    if post_residual <= 20 {
        score += 40.0 + 60.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Tightness reward relative to bin fill.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: neutral baseline, only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 150.0;
        // If the next item is large, having a fresh bin can be valuable.
        score -= (next_item_size as f64) * 0.3;
    }

    // Prefer bins whose residual is close to the item (best-fit sharpening).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.5;

    // Prefer bins below mean residual (fill emptier bins less, keep large gaps flexible).
    if (bin_residual as f64) > mean_residual {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

