    }

    // Penalize opening a new bin when open bins already fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty scaled by how many bins already fit
        score += 50.0 + 10.0 * fitting_bins_count as f64;
        // but if all fits are poor (large post_residual elsewhere), allow new bin
        if next_item_size > 0 && post_residual == bin_capacity as u32 - item_size {
            if (post_residual as f64) < mean_residual {
                score -= 80.0;
            }
        }
    }

    // Late in stream: tighten packing, avoid waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // Many open bins: prefer consolidating into existing ones
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

