    }

    // New-bin candidate handling: only attractive when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / (bin_capacity as f64);
        // Opening a new bin is penalized unless existing bins are nearly exhausted.
        score += 18.0 - 30.0 * pressure + 5.0 * progress;
        // More open bins -> keep consolidating, penalize opening another.
        score += (open_bins_count as f64).powf(0.5) * 2.0;
    }

    // Mild global regularization: prefer bins with residuals close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

