    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Smooth stream-progress coupling: later in stream, penalize larger residuals more.
    score += progress * 8.0 * (pr / cap) * (1.0 + (pr / cap));

    // Lookahead coupling: reward residual that can host the next item, penalize otherwise.
    if next > 0.0 {
        if pr >= next {
            score -= 6.0 * (1.0 - pr / cap) * (next / cap);
        } else {
            score += 4.0 * (next - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler.
    score -= 2.0 * ((mean_residual - pr) / cap).max(0.0);

    // New-bin candidate: make it unattractive unless residual is huge.
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 12.0 * tight * tight;

    // Harmonic class penalty: post_residuals that are "awkward" (not multiples of common item sizes) are dead space.
    let pr = post_residual;
    if pr > 0 {
        let mut class_penalty = 0.0;
        if pr % 10 != 0 { class_penalty += 2.0; }
        if pr % 20 != 0 { class_penalty += 2.0; }
        if pr % 25 != 0 { class_penalty += 1.5; }
        if pr < 10 { class_penalty += 6.0; } // tiny unusable sliver
        // Dead space worse if next item can't use it.
        if next_item_size > 0 && next_item_size as u32 > pr { class_penalty += 4.0; }
        score += class_penalty;
    } else {
        score -= 8.0; // perfect fit is excellent
    }

    // Lookahead harmony: if next item exactly fills post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size as u32 == pr {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= pr {
        // partial compatibility bonus based on how much of next item fits class-wise
        let waste = pr - next_item_size as u32;
        score -= 5.0 * (1.0 - waste as f64 / cap).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins, more so when decent fits exist or stream is late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
        if fitting_bins_count > 0 { score += 10.0; }
        // Opening a bin is more acceptable early when many bins are open and fragmented.
        score -= (open_bins_count as f64).min(10.0) * 0.5;
    }

    // Prefer bins with below-mean residual (consolidate fragmentation).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(-30.0).min(30.0) * 0.5;

    // Integer-division threshold: bins whose residual falls in [item, item+5) are near-perfect; extra reward.
    let diff = bin_residual - item_size;
    if diff < 5 { score -= 6.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
