    }

    // New-bin candidate handling: an empty bin gets a baseline handicap so
    // it is only chosen when every open bin would create dead space.
    if bin_residual == bin_capacity {
        score += 8.0 + pressure * 3.0;
        // If the item fits with a clean usable remainder, soften the handicap.
        if post_residual >= dead_threshold || post_residual == 0 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // residual can host next item: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit: penalize dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose residual
    // drops near/below the mean (tight packing), penalize keeping outliers loose
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin is a fallback; make it costly unless
    // no open bin fits well (large item, all residuals too small)
    if bin_residual == bin_capacity {
        let can_any_fit = fitting_bins_count > 0;
        if can_any_fit {
            score += 80.0 + post_residual as f64;
        } else {
            score -= 20.0;
        }
    }

    // Late-stream pressure: as stream progresses, prefer reusing existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    // Penalize creating small unusable fragments (below typical minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tightness * tightness * tightness;

    // Perfect fit: near-zero post residual gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if next item exactly fills post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item still fits after this placement: mild reward proportional to fill
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item would NOT fit in this bin afterwards: penalize leaving
            // residual smaller than next item (dead space trap)
            if post_residual < next_item_size {
                score += 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 20.0 * tightness;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin when decent fits exist; the penalty
        // shrinks as the stream progresses (end-of-stream consolidation).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 45.0 * (1.0 - 0.5 * progress);
        // But if open bins are all badly fragmented (high mean residual spread
        // vs item), allow new bin more readily: reduce penalty.
        let fragmentation = (mean_residual - item_size as f64).abs() / cap;
        score -= 20.0 * fragmentation;
        // Never open new bin if a near-perfect fit exists elsewhere; detect via
        // large post_residual here (empty bin always leaves big residual).
        score += 0.1 * post_residual as f64;
    }

    // Penalize placing into bins whose residual far exceeds the item
    // (wasteful large-hole consumption) relative to global mean residual.
    if bin_residual as f64 > mean_residual + cap * 0.3 {
        score += 8.0;
    }

    // Mild preference for filling bins when many bins are open (bin count control).
    score -= (open_bins_count.min(50) as f64) * 0.2 * (1.0 - tightness);

    // Dead-space guard: residual below minimum plausible item size is dead.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic penalty on wasted residual, amplified as stream progresses.
    let mut score = post * (1.0 + 1.5 * progress) + 0.004 * post * post;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post / cap;
    score -= 25.0 * tightness * tightness * tightness;

    // Penalize bins far below mean residual (fragmented bins), reward above-mean fill.
    score += 0.35 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist; prefer keeping flexible bins.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 10.0 * (1.0 - (post - nxt) / cap) * (1.0 + progress);
        } else {
            // Penalize leaving a residual just barely too small for the next item.
            score += 6.0 * (1.0 - (nxt - post).min(cap) / cap) * (1.0 - progress);
        }
    }

    // New-bin candidate: neutral-ish baseline so it's chosen only over poor fits.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.8 * progress) - 8.0;
        // Discourage opening new bins when a good existing option exists late in stream.
        if fitting_bins_count >= 1 && progress > 0.5 {
            score += 10.0 * progress;
        }
    }

    // Mild penalty for accumulating many open bins without consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual as f64;

    // ---- New-bin candidate: baseline cost of opening a fresh bin ----
    if is_new_bin {
        let mut nb = 80.0 + 0.25 * pr;
        // If literally nothing else fits, opening is mandatory-ish.
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            nb -= 5.0;
        }
        // Early in the stream, opening bins builds future flexibility.
        nb -= 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            nb -= 200.0;
        }
        return nb;
    }

    // ---- Existing-bin scoring (harmonic-class flavored) ----
    let mut score = pr;

    // Perfect fit class: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Dead-space class: tiny unusable leftovers (1..=7) are heavily penalized
    // so that opening a new bin becomes preferable to shredding a bin.
    else if post_residual < 8 {
        score += 40.0 * (8 - post_residual) as f64;
    }
    // Harmonic class bands: residual in [8,25) is semi-useful, [25,50) good.
    else if post_residual < 25 {
        score += 6.0;
    } else if post_residual < 50 {
        score -= 4.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.2 * next_item_size as f64;
        }
        // If next item would exactly consume this post-residual, extra reward.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference for consolidating into bins with low mean residual
    // (keeps one tight bin and leaves loose bins for future items).
    score += 0.05 * (mean_residual - pr);

    // Late in the stream, tighten packing (less tolerance for slack).
    score += 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Dead space: penalize residuals too small to ever be useful
    // (below the minimum item size of 1 => only exactly 0 is perfect;
    //  treat small unusable gaps harshly).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Gap that cannot fit the known next item is likely to stay dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        // Reward bins that can also host the lookahead item.
        score -= 15.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading;
    // prefer filling existing bins rather than creating new ones.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when nothing fits well
    // (handled implicitly: empty bin has post_residual = C - item,
    //  which is large, plus pressure term). Give empty-bin a mild
    // penalty so we only open when open bins score badly.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    // Slight preference early in the stream to keep bins openable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect chain fit (next item exactly fills post_residual)
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 100.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits, but leftover after it matters
        let after_next = post_residual - next_item_size;
        score -= 30.0 - (after_next as f64).min(30.0);
        if after_next < 10 {
            score += 15.0; // creates near-dead space for the step after next
        }
    } else if next_item_size > post_residual {
        // next item won't fit here regardless; mild penalty for tight leftover
        if post_residual < 10 {
            score += 20.0; // dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good fits)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Slight preference for reusing bins over opening new ones as stream grows
    if bin_residual == bin_capacity {
        score += 5.0 + (open_bins_count as f64).sqrt() * 2.0;
    }

    // Late in the stream, avoid spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot hold even the smallest item (size 1),
    // i.e. near-zero residuals are fine, but tiny-but-nonzero gaps are waste.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving stranded space.
            score += 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing
    // bins and closing them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > 0.0 {
        let waste_ratio = post_residual as f64 / mean_residual;
        score += 2.0 * (waste_ratio - 1.0).tanh();
    }

    // Late in the stream, be greedier about tight fits; early on, keep bins
    // flexible (prefer larger post-residual for future items).
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, scaled by smooth progress coupling
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty on small post residuals (dead space) that grows with progress
    score += 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Reward tight fits: quadratic reward for small post_residual
    score -= 60.0 * norm_item * norm_item * (1.0 - norm_pr);

    // Lookahead: penalize if post_residual can't fit next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += 15.0 * (-gap / cap) * (1.0 + progress);
        } else {
            score -= 10.0 * (gap / cap) * (1.0 - gap / cap);
        }
    }

    // Last-chance bin bonus (avoid opening new bins when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // New bin candidate: mild penalty, decreasing as stream progresses
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins below mean residual (denser bins)
    score += 5.0 * (mean_residual / cap - norm_pr).tanh();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual via integer division thresholds.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 200.0; // perfect fit
    } else if pr <= 10 {
        score -= 120.0; // near-perfect: dead space unusable by most items
    } else if pr <= 20 {
        score -= 40.0;
    } else if pr <= 50 {
        score -= 10.0;
    } else {
        score += 15.0; // wasteful large leftover
    }

    // Modulo-arithmetic harmonic classes: residuals divisible by small item classes
    // are more reusable (items 1..100 unknown distribution).
    if pr > 0 {
        let reusable = (pr % 10 == 0) as i32 as f64 * 25.0
            + (pr % 25 == 0) as i32 as f64 * 20.0
            + (pr % 50 == 0) as i32 as f64 * 15.0;
        score -= reusable;
    }

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
        if slack == 0.0 {
            score -= 50.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        score += 20.0; // next item won't reuse this bin's leftover
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, few fitting bins) or stream is early with room to grow.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64 / (open_bins_count.max(1) as f64);
        score = 150.0 + 100.0 * pressure - 60.0 * (1.0 - progress);
        if item_size > 70 && fitting_bins_count == 0 {
            score -= 250.0; // big item with no home: new bin is right
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are waste.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: unusable for the lookahead item -> heavy penalty.
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits (post_residual very small relative to capacity).
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 10.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Penalize leaving a residual far from mean (fragmentation signal).
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate baseline: neutral-ish, slightly worse than a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 8.0;
        // Allow opening a new bin when all existing fits are terrible.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect chain: next item exactly fills the bin
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Next item also fits after current placement -> strong pair bonus
        if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Penalize large dead space relative to mean residual
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        let base = 40.0 + post_residual as f64;
        // If item fits tightly nowhere else, new bin is attractive
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= post_residual { 10.0 } else { 0.0 };
        return base - lookahead_bonus;
    }

    // Late in stream: prefer filling existing bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly reward small post_residual relative to item size.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize leaving residual that the next item could waste,
    // reward leaving residual the next item can exactly use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap == 0.0 {
                score -= 40.0; // perfect lookahead chaining
            } else {
                score += gap * 0.3;
            }
        } else {
            // residual too small for next item: mild penalty unless it's tiny dead space
            score += 8.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist with low residual.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let best_possible = mean_residual.max(item_size as f64);
            if mean_residual >= item_size as f64 {
                score += 20.0 + mean_residual * 0.2;
            } else {
                // No bin fits well; opening a new bin is fine, slight reward scaled by time
                score -= 5.0;
            }
        } else {
            score -= 10.0;
        }
        // Late in stream, avoid proliferation of open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins to consolidate.
    if open_bins_count > 2 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= (mean_residual * 0.05).min(6.0);
    }

    // Reward near-perfect fills (residual <= 5)
    if post_residual <= 5 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating large unusable gaps that no plausible item (>=1) could split well
    if post_residual > 0 && post_residual < 10 && bin_residual != bin_capacity {
        score += 5.0; // awkward small gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, waste becomes more costly, so amplify dead space.
    let progress_amplifier = 1.0 + progress * progress * (1.0 + pr / cap);
    score *= progress_amplifier;

    // Reward tight fits: small post_residual relative to capacity gets a bonus.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (cap * 0.5);

    // Penalize leaving a residual that is too small to be useful later
    // (items are >= 1, but a tiny sliver is dead space): smooth penalty.
    let sliver = (pr / (item_size as f64 + 1.0)).sqrt();
    score += (1.0 - sliver.min(1.0)) * (pr * 0.3);

    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            let snug = 1.0 - (pr - n) / cap;
            score -= snug * snug * (cap * 0.4);
        } else {
            // next item won't fit here; mildly penalize
            score += (n - pr) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.8;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // held by other open bins; penalize more as open bins accumulate.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score = cap + waste * 0.5 + progress * cap * 0.5;
        // Exception: very large items leaving a tiny residual are fine in a new bin.
        score -= tightness * tightness * (cap * 0.3);
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that are "usable"
    // (divisible into common item chunks) get rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: perfect packing
    } else {
        // Dead-space class: small unusable slivers are worse than medium gaps.
        let class = pr % 10;
        let harmonic_penalty = match class {
            0 => -10.0,                    // gap is a multiple of 10: reusable
            1 | 2 | 3 => 12.0,             // tiny sliver: nearly dead space
            4 | 5 | 6 => 4.0,              // moderate sliver
            _ => 0.0,
        };
        score += harmonic_penalty;

        // Fractional capacity logic: gap smaller than half capacity but
        // larger than typical small items is risky.
        let frac = pr as f64 / cap;
        if frac < 0.25 {
            score += 18.0 * (0.25 - frac);
        } else if frac > 0.5 {
            score -= 8.0 * (frac - 0.5);
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let left = pr - next_item_size;
            if left % 10 == 0 {
                score -= 15.0;
            } else {
                score += 6.0;
            }
        } else {
            // next item won't fit here anyway; slight reward for absorbing
            // the current item fully.
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.15 * (item_size as f64);
    }

    // New-bin candidate handling: opening a new bin is expensive; only
    // attractive when current fit leaves a nasty sliver or many bins exist.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.5 * open_bins_count as f64
            + 0.1 * mean_residual
            + if pr > 0 && pr < 10 { 30.0 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 12.0; // big next item: fresh bin useful
        }
    }

    // Mild stream-phase modulation: later in the stream, prefer tightening
    // existing bins over spreading.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * phase * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize unusable small gaps: if no future item can plausibly fit the leftover.
    if post_residual > 0 && (post_residual as f64) < 0.5 * mean_residual.max(1.0) {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 35.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits elsewhere: open new bin
        }
    }

    // Lookahead: favor leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the leftover space exactly chains with the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        // Perfect chain: huge bonus.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leftovers that are too small to ever be useful (dead space).
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Prefer bins whose residual was below average (already well-utilized bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only on poor fits,
    // but scale penalty down as stream progresses / many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 35.0 - 15.0 * progress;
        score += new_bin_penalty;
        // If next item is large and this item is small, opening fresh may be good.
        if next_item_size > 60 && item_size < 40 {
            score -= 25.0;
        }
    }

    // Reward filling bins very tightly overall.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: penalize large post_residual quadratically.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item can use the post_residual (chain packing),
    // penalize dead space the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 18.0 + 0.2 * nxt;
        } else {
            // Dead space relative to lookahead.
            score += 0.5 * (pr - nxt).abs();
            // Small dead space is truly wasted.
            if pr > 0.0 && pr < nxt {
                score += 10.0 * (1.0 - pr / nxt);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins with residual below mean (tighter bins first),
    // keeps looser bins available for larger future items.
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be conservative with new bins;
    // later, allow more freedom since distribution knowledge accumulates.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let horizon = 1.0 + 0.8 * progress;

    // New-bin candidate handling: opening a new bin is attractive when
    // existing fits are loose or the item is large.
    if bin_residual == bin_capacity {
        let fit_quality = if fitting_bins_count > 0 {
            (bin_capacity as f64 - item_size as f64) / bin_capacity as f64
        } else {
            1.0
        };
        // Penalize opening new bins when a decent fit exists.
        score += 55.0 * horizon - 45.0 * (1.0 - fit_quality);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic penalty on residual: dead space grows super-linearly in cost.
    let pr = post_residual as f64;
    score += 0.02 * pr * pr / bin_capacity as f64;

    // Tight fits are strongly favored: reward small post_residual.
    score -= 40.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Smooth non-linear coupling with stream progress: as the stream advances,
    // prefer tighter packing (dead space becomes costlier to leave behind).
    score += progress * (pr * pr) / (bin_capacity as f64 * 2.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize bins far from the mean residual (fragmentation avoidance).
    score += 0.3 * ((post_residual as f64 - mean_residual).abs());

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Mild penalty on opening many new bins early.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic class: modulo classes of post_residual vs next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect lookahead fit: strongly favor.
            score -= 20.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            // Harmonic pairing: residual divisible-ish by next item.
            if gap < 10 {
                score -= 8.0;
            } else {
                // penalize leaving a large awkward gap
                score += (gap as f64).ln() * 3.0;
            }
            // modulo harmony: post_residual % next_item_size small => chainable
            let m = post_residual % next_item_size.max(1);
            if m == 0 {
                score -= 6.0;
            } else if m < 10 {
                score -= 2.0;
            }
        } else {
            // next item can't fit here anyway; slight penalty unless last-chance bin
            score += 4.0;
        }
    }

    // Last-chance bin: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    // accumulated in open bins, unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 8.0;
        // More open bins with slack => opening new bin is more wasteful.
        score += 0.5 * open_bins_count as f64;
        // But if item is huge relative to mean residual, a fresh bin is fine.
        let mean_r = mean_residual.max(0.0);
        if item_size as f64 > mean_r + 15.0 {
            score -= 14.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * progress;
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= 0.05 * (bin_capacity - bin_residual) as f64 * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        // A residual that cannot fit even the smallest plausible item is pure waste.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 30 {
            score += 8.0;
        }
        // Dead space relative to capacity (non-linear coupling).
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;
    } else {
        // Perfect fit is highly desirable.
        score -= 50.0;
    }

    // Lookahead: reward leaving space that fits the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Bonus if the next item would fill the leftover almost exactly.
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 12.0;
            }
        } else {
            // Leftover too small for next item: mild penalty.
            score += 4.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a tight fit exists.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        let mean_pressure = (mean_residual - item_size as f64).max(0.0);
        score = score - 5.0 + mean_pressure * 0.3 - poor_fit_pressure;
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Many open bins: opening another is costly.
        score += open_bins_count as f64 * 1.5;
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably from mean.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        let match_quality = 1.0 - (gap / bin_capacity as f64);
        score -= 25.0 * match_quality * match_quality;
        // Perfect chain (post_residual == next_item_size) heavily rewarded.
        if gap == 0.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize leaving residue too small for the next item (dead space risk).
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Compare against mean residual across open bins: prefer bins whose
    // resulting residual deviates favorably (smaller) from the mean.
    score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when good fits exist,
    // unless the item fits perfectly (keep fresh bin attractive for big items).
    if bin_residual == bin_capacity {
        score += 12.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, consolidate: prefer filling existing bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight penalty proportional to number of open bins to discourage sprawl.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but discount small residuals that are likely dead space.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: residuals too small for the smallest plausible item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post as f64 * 4.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Chain bonus scaled by how snugly the next item will also fit.
            let chain_tightness = 1.0 - (post - nxt) / cap;
            score -= 25.0 + 20.0 * chain_tightness;
        } else {
            // Post-residual cannot host next item: penalize proportionally to wasted potential.
            score += 8.0 + 15.0 * (nxt / cap);
        }
        // Perfect two-item packing: post_residual == next_item_size exactly.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 10.0;
    }

    // Global state: many open bins -> discourage spreading, favor filling existing bins.
    let crowding = open_bins_count as f64;
    score += 0.35 * crowding * (post / cap);
    score -= 0.15 * crowding * (1.0 - post / cap);

    // Mean-residual divergence: bins far from the mean residual are either outliers
    // (good to fill) or nearly empty (better to leave for future large items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.20 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: empty bin is attractive only when no good fit exists
    // or early in the stream with few bins open.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 20.0;
        score += 45.0 - early_bonus - 3.0 * (fitting_bins_count == 0) as i32 as f64;
        // Late in stream, opening new bins is costly.
        score += 30.0 * progress;
    }

    // Time horizon: as the stream progresses, tighten packing (reward low residuals more).
    score *= 1.0 + 0.5 * progress;

    // Mild non-linear squash of extreme residuals to avoid pathological swings.
    score += 0.02 * (post * post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * fit_ratio.powf(3.0);

    // Penalize dead space non-linearly: small residuals are less useful.
    let dead = post_residual as f64;
    score += 0.15 * (dead * dead) / bin_capacity as f64;

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let chain = next_item_size as f64 / (post_residual as f64).max(1.0);
        score -= 12.0 * chain * (1.0 - progress);
    } else if next_item_size > 0 {
        // Penalize post residuals that cannot host the next item, scaled by progress.
        score += 6.0 * (1.0 - progress) * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // but allow it late in the stream or when few bins fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 8.0 * (1.0 - progress) + 10.0 * pressure * (1.0 - progress);
        score -= 5.0 * progress;
    }

    // Crowd penalty: many open bins with large mean residual -> prefer filling existing ones.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += 0.5 * crowd * (mean_residual / bin_capacity as f64) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: reward residuals that are "useful"
    // for common item sizes (multiples of 10 and small values).
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr < 10 {
        score -= 25.0; // nearly dead space but tiny
    } else if pr % 10 == 0 {
        score -= 15.0; // harmonic class: aligned residual
    } else if pr % 5 == 0 {
        score -= 7.0;
    } else {
        score += 10.0; // non-aligned residual, likely dead space
    }

    // Integer-division thresholds: residuals that can host mid-size items.
    if pr >= 40 {
        score -= 8.0;
    }
    if pr >= 70 {
        score -= 6.0;
    }
    if pr > 80 {
        score += 20.0; // huge leftover suggests this bin was wasted on a small item
    }

    // Lookahead: reward if next item fits the post residual well.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let nxt_fit = (pr - next_item_size) as f64;
            score -= 12.0 - 0.15 * nxt_fit;
            if (next_item_size % 10 == 0) && (pr % 10 == 0) {
                score -= 6.0; // harmonic chain: both aligned
            }
        } else {
            score += 5.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins when many are open (bin consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Tie-break toward bins below mean residual (denser bins).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // is a good fit; otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= 60 && item_size <= 40 {
            score -= 10.0; // pair large next item with fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in (0,10) are unusable for items >=10... but sizes can be 1..100,
    // so treat gaps below the plausible minimum item size as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual > 0 && post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward placements that leave room for the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual blocks the next item: mild penalty
        score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more when many bins already open
        score += 30.0 + 10.0 * pressure;
        // but if mean residual is low (all bins nearly full), new bin is fine
        score -= (mean_residual / 10.0).min(40.0);
    } else {
        // slight reward for filling existing bins when pressure is high
        score -= pressure;
    }

    // Prefer bins whose residual is close to item_size (tight fit)
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            if post_residual >= next_item_size {
                // Next item can also fit here: good chaining.
                score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
            } else {
                // Post-residual too small for the next item: dead space risk.
                score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
            }
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full / poor fits.
    if bin_residual == bin_capacity {
        score += 80.0;
        if fitting_bins_count == 1 {
            score -= 70.0; // still prefer the lone fitting bin over a new bin
        }
        if mean_residual < 20.0 {
            score -= 30.0; // open bins are cramped; new bin is reasonable
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    score += 0.05 * (step_index as f64 / (total_items.max(1) as f64)) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (non-linearly).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that can't serve the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        } else {
            score -= 4.0 * (1.0 - (next_item_size as f64 / post_residual as f64).min(1.0));
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin, more so when many bins already fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).ln() + 1.0
        } else {
            0.0
        };
        score += 25.0 + 8.0 * pressure;
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If mean residual across open bins is large, avoid new bins.
        if mean_residual > item_size as f64 {
            score += 0.15 * (mean_residual - item_size as f64);
        }
    } else {
        // Reward bins whose residual is close to the item (good harvest).
        let waste = (bin_residual as f64 - item_size as f64).abs();
        score -= 6.0 / (1.0 + waste * 0.1);
    }

    // Slight preference for filling more-open bins when few remain usable.
    if fitting_bins_count > 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) are rewarded more aggressively.
    let tightness = 1.0 - pr / cap; // 0 = empty, 1 = perfectly full
    let progress_coupling = tightness * tightness * (0.5 + 2.0 * progress);
    score -= 30.0 * progress_coupling;

    // Penalize large dead space quadratically, scaled by how much room remains stream-wise.
    let dead = pr / cap;
    score += 40.0 * dead * dead * (1.0 - 0.5 * progress);

    // Reward bins whose residual also accommodates the lookahead item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack) * (0.5 + progress);
        } else {
            // post_residual is useless for the next item; penalize proportionally.
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin unless the fit is truly tight,
    // with the penalty easing late in the stream.
    if bin_residual == bin_capacity {
        let base = 20.0 + 10.0 * (1.0 - progress);
        score += base + 15.0 * (1.0 - tightness);
        // A fresh bin is more acceptable when open bins are crowded overall.
        score -= 5.0 * (mean_residual / cap);
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on small
    // "dead zones" (mod classes) are penalized; perfectly tight fits rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: always excellent
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space almost unusable anyway
    } else {
        // modulo-10 harmonic class: residual divisible by 10 is reusable
        // by the widest range of item sizes (items are integers 1..100).
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        } else {
            score += 6.0; // awkward residual, likely dead space
        }
        // integer-division threshold: residual below 20 can only host tiny items
        if pr < 20 {
            score += 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let slack = post_residual as f64 - nxt;
            if slack == 0.0 {
                score -= 45.0;
            } else if slack <= 5.0 {
                score -= 18.0;
            } else {
                score -= 6.0 * (1.0 - slack / cap);
            }
        } else {
            // next item cannot follow here: mild penalty
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins fit poorly.
    // Its raw score is cap - item_size = post_residual for an empty bin; make it
    // lose unless the item fits badly everywhere (handled by penalties above).
    if bin_residual == bin_capacity {
        score += 30.0;
        // early in the stream, opening bins is cheap and useful for future items
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // if many open bins but none fit well, opening may still be right
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate fullness).
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual && bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual - bin_res_f) / cap;
    }

    // Slight preference for bins that will become well-packed relative to count
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 2.0 / open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but practically treat gaps < next_item_size as dead) get a heavy penalty.
    let dead_threshold = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 2.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to item size (small post_residual normalized).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 8.0;

    // Open-bin pressure: discourage spreading into many bins unless the fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Mean residual coupling: prefer bins whose residual is below mean (more filled),
    // penalize dipping into bins with large residuals unless the fit is very tight.
    let bin_res_f = bin_residual as f64;
    if bin_res_f > mean_residual {
        score += (bin_res_f - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - bin_res_f) * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual > 20 {
            score += post_residual as f64 * 0.3;
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the current
    // item is large relative to typical residuals or fits are poor.
    if bin_residual == bin_capacity {
        score -= 15.0;
        if item_size >= 50 {
            score -= 10.0;
        }
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
            score += 25.0; // this new bin would immediately become dead-ish
        }
        score += open_bins_count as f64 * 1.5;
    }

    // Lookahead: if placing here leaves exactly room for the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size * 2 {
        score += 10.0; // awkward gap for the lookahead item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Perfect chaining bonus: next item exactly fills the remainder.
        let slack_after_next = post_residual - next_item_size;
        score -= 25.0 + 0.5 * (next_item_size as f64) - 0.3 * (slack_after_next as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow: dead space risk grows with post_residual.
        score += 0.25 * (post_residual as f64);
        // Penalize more heavily if the leftover is too small for typical future items.
        if post_residual < 10 {
            score += 8.0;
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // prefer bins whose leftover stays far below the mean (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.4 * (mean_residual - pr);
    } else {
        score += 0.6 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and no good chaining is possible.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 50 && (next_item_size == 0 || next_item_size > 50) {
            score -= 25.0;
        }
    }

    // Slight preference early in the stream for keeping bins balanced.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64 / cap).powf(2.0) * 20.0;

    // Bonus for perfect fit.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Small residual that cannot fit even the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (next_item_size as f64 / cap);
        } else {
            // Next item won't fit here; slight penalty if we leave a large gap.
            score += 2.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Favor bins that are already relatively full (small residual relative to mean).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Many open bins: encourage consolidation; few open bins: allow spreading.
    let spread = (open_bins_count as f64).ln() + 1.0;
    score += spread * (post_residual as f64 / cap) * 3.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize cramming); late, conserve by filling existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0 * (post_residual as f64 / cap)
        - progress * 3.0 * (post_residual as f64 / cap);

    // New-bin candidate: mild penalty so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 6.0 + (open_bins_count as f64) * 0.5;
        // But if no open bin fits well, new bin becomes attractive:
        if post_residual >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear coupling of post_residual with stream progress
    let smooth = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * (norm_pr * norm_pr) * (1.0 - smooth);

    // Penalize residuals that are too small to be useful later (dead space)
    let dead = 1.0 - (pr / cap).tanh();
    score += 8.0 * dead * smooth;

    // Reward tight fits: interaction between item size and residual
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * (1.0 - norm_pr) * (0.5 + 0.5 * smooth);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 - pr).max(0.0);
        score += 0.08 * fits_next;
        score -= 0.05 * (1.0 - fits_next / cap).max(0.0);
    }

    // Mean residual alignment term
    score += 0.03 * (pr - mean_residual).abs();

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are multiples of common
    // item sizes are more reusable, reward them (subtract).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // perfectly harmonic residual
        } else if pr % 5 == 0 {
            score -= 6.0;
        } else if pr % 25 == 0 {
            score -= 10.0;
        }
        // Small unusable dead space is bad: penalize tiny residuals hard.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Integer-division threshold: residual in [10, 30] is prime real estate
        // for medium items; keep it if next item can use it.
        if next_item_size > 0 && next_item_size <= pr {
            let gap = pr - next_item_size;
            score -= 15.0;
            if gap % 10 == 0 {
                score -= 8.0; // next placement leaves harmonic residual too
            }
            if gap < 10 && gap > 0 {
                score += gap as f64 * 2.0; // avoid near-miss chain
            }
        } else if next_item_size > 0 {
            // next item won't fit here: residual likely dead
            score += 6.0;
        }
    } else {
        score -= 20.0; // perfect closure, strongly favored
    }

    // Capacity-fraction coupling: item filling a harmonic fraction of the bin.
    let frac = (item_size * 4) as f64 / bin_capacity as f64; // 0.04..4
    if (frac - frac.round()).abs() < 0.01 {
        score -= 4.0; // item is 25/50/75/100% of capacity
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Never prefer a fresh bin over a decent fit unless the fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
        if post_residual >= 10 {
            score -= 10.0; // new bin still leaves useful space
        }
    }

    // Late in stream: tighten packing, prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.3;

    // Mean residual alignment: placing here to reduce variance is good.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure loss; the smaller the gap, the worse the dead space per unit.
    if post_residual > 0 {
        // Non-linear penalty exploding for tiny gaps (unusable slivers).
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 40.0 * (1.0 - dead) * (1.0 - dead) * (1.0 - dead);
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Reward tight fits relative to current residual (fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill * fill;

    // Lookahead coupling: if post_residual can exactly host the next item, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Gap too small for the known next item: extra dead-space penalty.
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.05 * open_bins_count as f64;
    }

    // New-bin candidate handling: opening a new bin is justified when all open
    // bins would leave bad dead space (post_residual small but nonzero) or when
    // open-bin pressure is low and the item is large.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: moderate, so only beaten by bad fits.
        score = 35.0 + 0.5 * open_bins_count as f64;
        // A fresh bin is attractive for large items into empty space with good
        // pairing potential against the next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
        if post_residual == 0 {
            score -= 30.0; // item exactly fills a fresh bin: excellent
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; mild additive pressure already included above.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight preference to keep mean residual balanced (avoid one bin hoarding).
    score += 0.1 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is highly usable).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: if the next item fits the post residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 + 0.5 * (bin_capacity as f64 - slack).min(50.0);
        if slack == 0.0 {
            score -= 40.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize dead space
        // proportionally to how "wasted" it is.
        let dead = post_residual as f64;
        score += 0.6 * dead;
        if dead > 30.0 {
            score += 15.0;
        }
    }

    // Compare residual against the mean residual across open bins:
    // placing into a tighter-than-average bin preserves large residuals elsewhere.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.3 * (mean_residual - resid_f);
    } else {
        score += 0.3 * (resid_f - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is
    // huge relative to open residuals or nothing else fits well.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Large items benefit from a fresh bin.
        if item_size > 60 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can chain large items
        }
    }

    // Early in the stream, opening bins is cheaper (more future items to fill them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Slight penalty when too many bins are already open and residual is large.
    if open_bins_count > 8 && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 40.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward leaving exactly room for next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many open bins can fit the item
    if bin_residual == bin_capacity {
        score += 15.0 + (fitting_bins_count as f64) * 8.0;
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Prefer bins below mean residual (keeps residuals balanced)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Reward filling bins nearly full to close them out
    if post_residual < 10 {
        score -= 20.0;
    }

    // Slight preference for bins with more residual among fitting bins (best-fit tension relief)
    score += (bin_residual as f64) * 0.1;

    // Mild penalty for accumulating many open bins
    score += open_bins_count as f64 * 0.5 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to stream progress.
    let mut score = r * (1.0 + 0.5 * rn * rn) + 12.0 * t * rn * rn;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    let tightness = 1.0 - rn;
    score -= 30.0 * t * tightness * tightness * tightness;

    // Penalize waste relative to mean residual across open bins (smooth quadratic).
    let waste = r - mean_residual;
    score += 0.15 * waste * waste / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * t;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless residual is huge
    // or the current item leaves a very usable space for the lookahead item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 15.0 * (1.0 - t);
        // If next item fits well in the post-residual, soften the penalty.
        if next_item_size > 0 && (next_item_size as f64) <= r {
            score -= 18.0 * (1.0 - (next_item_size as f64) / cap);
        }
    } else {
        // Lookahead synergy: reward post-residual that accommodates the next item exactly.
        if next_item_size > 0 {
            let diff = (r - next_item_size as f64).abs();
            score -= 10.0 * (1.0 - diff / cap).max(0.0);
        }
        // Crowding: many open bins -> prefer filling existing ones (mild).
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes
    // (10/20/25/50) are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 8.0; }
        if pr % 20 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 5.0; }
        if pr % 50 == 0 { bonus += 7.0; }
        score -= bonus;
    } else {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post residual (chain packing).
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0 + 0.1 * (pr - next_item_size) as f64;
        // Harmonic match between next item and post residual.
        if pr % next_item_size == 0 {
            score -= 10.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Dead space that the next item cannot use: penalize.
        score += 6.0 + 0.05 * (next_item_size - pr) as f64;
    }

    // Tightness: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize new-bin drift.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 25.0 + 2.0 * open_bins_count as f64;
        if mean_residual > next_item_size as f64 && next_item_size > 0 {
            score += 10.0; // existing bins have room; opening new bin is wasteful
        }
    }

    // Late in stream: tighten up, avoid leaving scattered residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: residuals in awkward mid ranges are penalized.
    let class = pr / 10;
    if class >= 3 && class <= 6 && pr % 10 != 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize small-but-nonzero gaps more aggressively.
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    } else if post_residual < 10 {
        score += 25.0; // tiny unusable gap penalty
    }

    // Prefer bins whose post_residual can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow opening a fresh bin when the fit is mediocre.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    score += pressure * (post_residual as f64) * 0.05;

    // New-bin candidate: only attractive when the current fit is bad
    // (large post_residual) and few bins are open.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        score = 100.0 - bad_fit * 40.0 - 5.0 * pressure;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // next item still fits after this placement
        score -= (post_residual - next_item_size) as f64 * 0.5;
    } else if next_item_size > 0 {
        // next item won't fit in residual -> dead space unless residual is tiny
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize residual far from mean residual (fragmentation of the pool)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins could reasonably fit the item
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.5;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 120.0; // new bin can host current + next item pair
        }
    }

    // Early stream: be more liberal with opening bins (better long-run packing)
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= (1.0 - progress) * 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.94;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post * (1.0 + 0.8 * progress * progress + 0.6 * progress * pr);

    // Reward tight fits, smoothly scaled by progress
    score -= (cap - post) * (0.35 + 0.45 * progress) * (1.0 - pr * pr);

    // Penalize near-full bins less as stream ends
    score += 4.0 * pr * pr * (1.0 - progress);

    // Lookahead coupling: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 6.0 * (1.0 - post / nxt.max(1.0)) * (0.5 + progress);
        } else {
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this fit is wasteful
    score += 0.15 * open_bins_count as f64 * pr * progress;

    // New-bin candidate: prefer opening a new bin early or when fit is poor
    if bin_residual == bin_capacity {
        score = 8.0 + 6.0 * (1.0 - progress) + 25.0 * (1.0 - (bin_residual - item_size) as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into residue classes
    let capacity_frac = bin_capacity / 10; // 10-unit granularity
    let post_class = post_residual / capacity_frac; // 0..10 harmonic class

    // Reward near-perfect fits strongly (small post_residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Modulo arithmetic on post_residual: residues divisible by 5 are more "reusable"
    let mod5 = post_residual % 5;
    score -= match mod5 {
        0 => 12.0,
        1 => -6.0, // worst residue: leaves 1-unit unusable slivers
        4 => 4.0,
        _ => 0.0,
    };

    // Integer-division thresholds: post_residual in [next_item_size, next_item_size+10)
    // means the lookahead item fits exactly in the leftover -> big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
            if post_residual - next_item_size <= 10 {
                score -= 15.0;
            }
        } else {
            // post_residual smaller than next item but still "harmonically" reusable
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 8.0; // almost reusable, mild penalty
            } else {
                score += 10.0; // dead space relative to lookahead
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating large dead space (post_residual in awkward mid range 11..=30)
    if post_residual > 10 && post_residual < 30 {
        score += 10.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many items remain
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 20.0 * progress;
        // if only one fitting bin exists, opening new bin is rarely good
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
        // if mean residual across open bins is large, prefer reusing them
        if mean_residual > item_size as f64 + 15.0 {
            score += 20.0;
        }
    } else {
        // Favor bins whose residual is harmonically aligned with the item size class
        let item_class = item_size / capacity_frac;
        let residual_class = bin_residual / capacity_frac;
        if residual_class == item_class + 1 {
            score -= 10.0; // item exactly fills one class of the residual
        }
        // Slight preference for fuller bins (smaller residual) to compact packing
        score += (bin_residual as f64) * 0.05;
        // Spread control: avoid too many open bins
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band
    // (too small for typical items) are heavily penalized.
    let dead_lo = 1.0f64;
    let dead_hi = 10.0f64;
    let pr = post_residual as f64;
    if pr > dead_lo && pr < dead_hi {
        // Nonlinear spike: worst just above dead_lo, tapering to dead_hi
        let t = (pr - dead_lo) / (dead_hi - dead_lo);
        score += 40.0 * (1.0 - t) * (1.0 - t);
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }
    // Tight-but-usable fit bonus (small residual that could still take a small item)
    if post_residual >= 1 && post_residual <= 20 {
        score -= 5.0;
    }

    // Prefer bins with larger residual capacity consumed relative to mean state
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage
    // consolidation into existing bins (penalize new-bin opening).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: default penalty grows with open bins and mean residual
        score += 15.0 + 3.0 * pressure;
        // But if this bin is the last chance, opening a new bin is attractive
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance existing bin: strongly favor using it
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits into the post residual, reward
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // Next item won't fit: mild penalty proportional to wasted lookahead opportunity
        score += 3.0;
    }

    // Stream progression: late in the stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual), with non-linear emphasis.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Lookahead: penalize bins whose post_residual is too small for the next item
    // (wasting the remaining space), but reward bins that can also host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-fit reward: this bin can absorb the next item too.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // Dead-space penalty scaled by how far the next item misses this gap.
            let miss = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 10.0 * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good fit, or when mean residual across open bins is already small
    // (fragmented state) late in the stream.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // Late in the stream, prefer consolidating into open bins even more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open but mean residual is low (fragmentation), opening
        // a fresh bin becomes relatively more acceptable.
        let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 8.0 * frag * (open_bins_count as f64).ln().max(0.0);
        // Perfect fit of the item into a fresh bin is neutral-ish.
        score -= 6.0 * tight;
    } else {
        // Mild preference for using already-open bins, stronger when many are open.
        score -= 2.0 + 0.5 * (open_bins_count as f64).min(10.0);
    }

    // Penalize leaving residuals that no plausible future item (>=1) can use well:
    // very small post_residual gaps (1..=3) are nearly dead space unless exact.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Dynamic time horizon: early in the stream, keep bins flexible (prefer larger
    // post_residual slightly); late, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress.
    // Early on, keep bins tight (small residual good); later, residual waste matters more.
    let tightness = (pr / cap).powi(2);
    score += 25.0 * progress * tightness * cap;

    // Reward near-perfect fills with a smooth bump around post_residual ~ 0.
    score -= 18.0 * (-pr / 12.0).exp();

    // Penalize residuals that are too small for the lookahead item (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = nx - pr;
        if gap > 0.0 {
            score += 10.0 * (gap / cap) * (1.0 + progress);
        } else {
            // Smooth reward when the next item fits this residual.
            score -= 6.0 * (1.0 - (pr / cap)) * (nx / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize opening bins late in the stream,
    // but allow it when residual of this bin would be highly fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: penalize residuals in "awkward" classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Modulo classes on post_residual relative to small item sizes (10..80 range hints)
        let r = post_residual;
        // Residuals that are multiples of 10 are "usable" by typical items
        if r % 10 == 0 {
            score -= 8.0;
        }
        // Very small unusable dead space (1..=9) is heavily penalized
        if r < 10 {
            score += 25.0;
        }
        // Residuals that cannot fit the smallest plausible item
        if r < 15 {
            score += 10.0;
        }
        // Harmonic division: how well does residual divide into future capacity
        let q = bin_capacity / r.max(1);
        if q >= 2 {
            score -= 4.0 * (q as f64).min(4.0);
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
            // next item would leave another perfect-ish residual
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; slight penalty if residual is tiny
            if post_residual < 20 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction
    let fill_frac = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_frac;

    // New-bin candidate handling: opening a new bin is expensive unless
    // current fit is terrible or we're early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin
        score += 45.0;
        // Early in the stream with few bins, fresh bins are more acceptable
        score -= 15.0 * (1.0 - progress) * (1.0 - (open_bins_count as f64 / 20.0).min(1.0));
        // If no open bin fits well (post_residual large relative to capacity), new bin is fine
        if post_residual > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (keeps balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference to keep number of open bins from exploding
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fills relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins early,
    // encourage consolidation when many bins are already open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * (0.15 + 0.35 * progress);

    // Penalize bins whose residual is far below the mean residual (fragmented bin).
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if next item cannot use post-residual, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate (empty bin): must be worse than any reasonable fit,
    // but better than placing into a bin creating tiny dead space.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If no existing bin can fit the item, the new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: less waste after placement.
    score -= 2.5 * (1.0 - (post_residual as f64 / cap)).max(0.0) * 10.0;

    // Aggressive 2-step lookahead: if the next item fits exactly into
    // the post residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 40.0; // perfect chain: item + next item fill this bin
        } else {
            score -= 25.0 * (1.0 - gap / cap);
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space,
        // scaled by how large the leftover is relative to next item.
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 8.0 * (dead / cap) * (next_item_size as f64 / cap);
        }
    }

    // Compare post residual to mean residual: leaving a bin far below
    // mean residual wastes space elsewhere; leaving it near mean is fine.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin is a good fit
    // (large post_residual relative to capacity on existing bins) or
    // when next item is large and current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit_penalty = (post_residual as f64 / cap) * 12.0;
        score = cap * 0.55 + poor_fit_penalty - 10.0 * progress;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 20.0; // new bin can chain item + next item
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't open new bin when a last-chance bin exists
        }
    }

    // Mild pressure against proliferating bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: minimize post_residual (tight fit), normalized.
    score = post_residual as f64 * 1.0;

    // Reward bins where the lookahead item also fits into the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64 / bin_capacity as f64) * 18.0;
    } else if next_item_size > 0 {
        // Penalize leaving a gap that the next item cannot use but is awkwardly sized.
        let gap_uselessness = post_residual as f64 / (next_item_size.max(1) as f64);
        score += gap_uselessness * 4.0;
    }

    // Penalize near-perfect-but-wasted residual: dead space that is too small for anything.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly or are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score = bin_capacity as f64 * 0.55
            + congestion * 6.0
            + progress * 15.0;
        // If many bins can fit the item, opening a new bin is wasteful.
        score += fitting_bins_count as f64 * 20.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Mild global pressure: when mean residual is high, prefer using emptier bins
    // (large residual) to consolidate waste.
    if bin_residual != bin_capacity {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    // Late-stream tightening: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // Small bonus for filling bins toward fullness (encourages bin closure).
    score -= (item_size as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * (bin_capacity as f64) * (0.5 + progress);

    // Reward filling bins that are almost full already (post_residual small).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * fill * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across many open bins late in the stream.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    // Discourage placing into bins whose residual is far above mean (keeps bins balanced).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * dev * 0.01;

    // Lookahead: if the next item fits nicely into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + gap * 0.1);
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // New-bin candidate: keep it competitive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class logic on post_residual ---
    // Items whose post_residual falls into "nice" harmonic classes (multiples of
    // common item sizes) leave space that is likely reusable. Reward those.
    let pr = post_residual;
    if pr > 0 {
        // post_residual divisible by common size classes => reusable residue
        if pr % 10 == 0 { score -= 6.0; }          // perfect decimal class
        else if pr % 25 == 0 { score -= 4.5; }     // quarter-class
        else if pr % 20 == 0 { score -= 3.5; }     // fifth-class
        else if pr % 5 == 0 { score -= 2.0; }      // coarse harmonic
        // Small residues (< 10) are near-dead space; penalize mildly.
        if pr < 10 { score += 4.0; }
        // Integer-division threshold bands: residue in [10,30) is a sweet spot
        // (fits the smallest item class exactly-ish).
        if pr >= 10 && pr < 30 { score -= 3.0; }
    } else {
        // Perfect closure: bin exactly filled — strongly reward.
        score -= 12.0;
    }

    // --- Tightness ratio: reward high fill fraction (non-linear coupling) ---
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill * fill; // quadratic preference for fuller bins

    // --- Lookahead coupling: can next_item_size land in post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by how well it pairs.
            let pair_waste = (pr - next_item_size) as f64;
            score -= 7.0 * (1.0 - pair_waste / bin_capacity as f64);
            // Harmonic bonus if next item exactly closes the bin.
            if next_item_size == pr { score -= 5.0; }
        } else {
            // Next item won't fit here: slight penalty for stranding residue.
            score += 1.5;
        }
    }

    // --- Last-chance logic: this is the only bin that fits ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0; // avoid opening a new bin if this is the sole fit
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Base cost of a fresh bin, discounted by stream position and load.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_score = 55.0;
        // Late in the stream, prefer consolidation into open bins.
        new_bin_score += 20.0 * progress;
        // Many open bins with high mean residual => keep packing into them.
        new_bin_score += (open_bins_count as f64).sqrt() * 4.0;
        new_bin_score += (mean_residual - pr as f64).max(0.0) * 0.3;
        // If item is large, a fresh bin is relatively more sensible.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // If nothing else fits, new bin becomes the fallback.
        if fitting_bins_count == 0 { new_bin_score -= 60.0; }
        score = score.min(new_bin_score);
    }

    // --- Mild dispersion penalty: keep residuals near the mean when bins abound ---
    if open_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum item size of 1..100 streams, use a conservative 12)
    // are heavily penalized as unusable dead space.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 4.0;
    }
    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual can still fit the lookahead item after placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading to new bins;
    // the empty-bin candidate (residual == capacity) gets a mild penalty so we
    // prefer existing bins unless the fit is poor.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But allow opening a new bin late in the stream if current fit is bad.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if post_residual as f64 > mean_residual {
            score -= 5.0 * progress;
        }
    } else {
        // Mild preference for bins with residual close to item (tight fit).
        score += (bin_residual - item_size) as f64 * 0.1;
        // Coupling with mean residual: prefer bins tighter than average.
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 8.0;

    // 2-step lookahead: reward if the next item fits exactly in the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize wasted residual unless it's tiny
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
        // bonus if next item exactly fills residual making bin fully closed
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Relative to mean residual: prefer bins already below-average residual (consolidation)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Penalize dead space that no future small item (min size 1) could still use
    if post_residual < 10 && post_residual > 0 {
        score -= 5.0; // nearly closed bin is good
    }
    if post_residual == 0 {
        score -= 15.0; // perfectly closed bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin offers
    // a decent fit (post_residual too small to be useful)
    if bin_residual == bin_capacity {
        // fresh bin baseline: neutral residual, no wasted space yet
        score = 60.0;
        // prefer opening a new bin late in the stream when many bins are open
        score -= 2.0 * open_bins_count as f64;
        // if lookahead item is large, a fresh bin is more valuable
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
        // if this item would leave a big residual in any bin anyway, new bin ok
        if post_residual as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild progression term: early on, be slightly greedy with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize large dead space: residuals too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // New-bin candidate logic: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin (fragmentation cost).
        score += 25.0 + 2.0 * open_bins_count as f64;
        // If this item is a poor fit everywhere (few fitting bins), opening new is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Perfect fit for a large item in a fresh bin is good.
        if item_size >= 50 {
            score -= 8.0;
        }
    } else {
        // Last-chance bin: strong reward to use it rather than open a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Global pressure: when many open bins exist, prefer consolidating into
    // bins with below-mean residual (reduce spread).
    if !is_new_bin && open_bins_count > 1 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Time horizon: early in the stream, be conservative (keep space flexible);
    // late in the stream, pack aggressively (tightness matters more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_fit = (fitting_bins_count as f64).ln1p();
    let open_norm = (open_bins_count as f64).ln1p();

    // Base: waste (post_residual), smoothed with quadratic coupling to progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Strong reward for tight fits: penalize large residuals super-linearly
    score += 0.9 * (pr / capacity).powi(3) * capacity;

    // Reward bins that leave room for the lookahead item
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = pr - next;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / capacity);
        } else {
            score += 0.5 * (-gap / capacity) * capacity * 0.1;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        score -= 2.0 * norm_fit;
    }

    // Mild pressure to reuse existing bins rather than open new ones
    score -= 1.5 * open_norm / (1.0 + progress);

    // New-bin candidate: penalize so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (1.0 - progress);
    }

    // Coupling with mean residual: avoid bins far from the fleet mean
    score += 0.4 * (pr - mean_residual).abs() / capacity * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod arithmetic on capacity) ---
    // Residuals that are "harmonic" (divisible into common item sizes) are valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let harmonic: f64 = if pr == 0 {
        -40.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        -6.0  // residual divisible by 10 pairs with any future item
    } else if pr % 5 == 0 {
        -2.0
    } else {
        4.0 + (pr % 5) as f64 // awkward residual: penalize
    };
    score += harmonic;

    // --- Integer-division threshold on post_residual: dead-space bands ---
    let quarter = bin_capacity / 4;
    if pr < quarter && pr > 0 {
        score += 10.0; // tiny unusable sliver
    } else if pr > 3 * quarter {
        score -= 4.0;  // large residual kept alive is good
    }

    // --- Lookahead coupling with next_item_size ---
    if next_item_size > 0 && (next_item_size as u64) <= (pr as u64) {
        // this bin could also host the next item: reward exact/near match
        let gap = pr - next_item_size;
        score -= 8.0 - (gap as f64).min(8.0) * 0.5;
        if gap == 0 {
            score -= 15.0; // perfect two-item chain
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot go here anyway; if residual is small, fine
        if pr < next_item_size && pr < bin_capacity / 10 {
            score += 3.0;
        }
    }

    // --- Last-chance bonus: only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // with multiple options, prefer tightest fit via post_residual (already) plus mild crowding bonus
        score -= 2.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: only attractive when current bins are crowded or fit is bad.
        let crowded = mean_residual / cap; // fraction of free space on average
        score = 55.0 + 30.0 * (1.0 - crowded) + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big item coming: a fresh bin is useful
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
    } else {
        // Prefer filling bins below the mean residual (balancing pressure)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // --- Capacity-fraction tightness term ---
    let fill_fraction = item_size as f64 / cap;
    score -= 12.0 * fill_fraction; // reward placing large items into partially filled bins

    // --- Stream progression: tighten packing late in the stream ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * (pr as f64 / cap) * (1.0 - progress); // early: keep flexibility; late: penalize waste more via base term
    score -= 5.0 * progress * (1.0 - pr as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: neutral baseline, penalize if an open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 0.3;
        if post_residual == 0 { score -= 40.0; }
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if next item cannot use the leftover gap at all.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual.min(15)) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual) with a mild non-linear bonus.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Aggressive 2-step lookahead: reward if the next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // next item fits; the smaller the leftover after that, the better
            let second_left = post_residual - next_item_size;
            score -= 25.0 - (second_left as f64 / bin_capacity as f64) * 25.0;
        } else {
            // next item cannot use the residual: penalize wasted space proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.4;
        }
    } else {
        // Last item: only the immediate residual matters; strongly favor tight fit.
        score -= 15.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // placing here when it barely fits is risky.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score += (mean_residual - resid) * 0.15;
    } else {
        score -= (resid - mean_residual) * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is huge
    // and would leave a badly fragmented open bin set.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 35.0 + progress * 10.0 + open_pressure * 20.0;
        // Attractive to open a new bin when item is large and next item is also large
        if item_size >= 70 {
            new_bin_score -= 25.0;
        }
        if next_item_size >= 60 {
            new_bin_score -= 10.0;
        }
        // If many bins can fit, discourage new bin
        new_bin_score += fitting_bins_count as f64 * 5.0;
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tight) * (1.0 - tight);

    // Perfect fit dominates everything.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item fits in the post residual (chaining),
    // penalize if next item would be blocked by a large dead remainder.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Dead space that blocks the known next item.
            score += 0.3 * (post_residual as f64);
        }
        // Bonus if next item exactly fills the post residual.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item
    // is large relative to capacity (good use of fresh space).
    if bin_residual == bin_capacity {
        let fill = (item_size as f64) / (bin_capacity as f64);
        score += 45.0 - 40.0 * fill;
        // If no open bin alternatives exist, opening is fine.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Global state: with many open bins and high mean residual,
    // prefer consolidating into existing bins rather than spreading.
    if bin_residual != bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 0.05 * mean_residual * (1.0 - progress);
        score -= 0.5 * open_bins_count as f64 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is more costly
    let p = progress;
    score += pr * (p * p) * 1.5;

    // Cubic interaction: residual^3 normalized, penalizes large dead space increasingly
    score += (pr * pr * pr) / (cap * cap) * 0.01;

    // Lookahead: reward residuals that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        let k = (-((diff / cap).powi(2)) * 6.0).exp();
        score -= 8.0 * k;
        // penalize leaving residual slightly below next item (near-miss waste)
        score += 5.0 * (-((diff / cap).powi(2)) * 1.5).exp() * (diff < 0.0) as u8 as f64;
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * (1.0 - p);
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 6.0;

    // Slight preference for already-open bins vs opening new bins
    score += 2.0;

    // Encourage high fill ratio with a saturating bonus
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity/16 bands. Small classes (tight fits) are rewarded strongly.
    let band = (bin_capacity as f64 / 16.0).max(1.0);
    let class = (post_residual as f64 / band).floor() as i32;
    score -= (16 - class.min(16)) as f64 * 6.0;

    // Perfect / near-perfect fit: huge reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Modular coupling: if next item can exactly fill the post-residual
    // (residual % next == 0), this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && (post_residual % next_item_size) == 0 {
            score -= 15.0;
        }
        // Penalize leaving a residual that is awkwardly just below next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 8.0;
        }
    }

    // Integer-division thresholds on item size classes (harmonic bins).
    let item_class = item_size / 10; // 1..=10
    let res_class = bin_residual / 10;
    // Reward pairing large items into mostly-full bins.
    if item_class >= 6 && res_class <= 4 {
        score -= 10.0;
    }

    // Last-chance bin: only one bin fits, strongly favor using it
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual > 40 {
            score += 15.0;
        }
    }

    // Prefer filling bins with below-average residual (consolidate).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so existing bins are preferred, scaled by how many
        // bins already fit the item.
        score += 30.0 + 5.0 * fitting_bins_count as f64;
        // Late in the stream, opening new bins is less costly (fewer
        // future consolidation opportunities needed).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If the new bin will be nearly empty of usable leftover structure,
        // i.e. item is small, penalize more.
        if item_size < 30 {
            score += 15.0;
        }
    }

    // Slight preference for bins with residual close to item size
    // (best-fit flavor via harmonic proximity).
    let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.1 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (likely unusable gaps) are heavily penalized.
    // Dead zone: post_residual in [1, 15] -> quadratic penalty.
    if post_residual > 0 && post_residual < 15 {
        let gap = (15 - post_residual) as f64;
        score += 6.0 * gap * gap / 15.0;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward snug fits: small post_residual above dead zone still good.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Open bins pressure: penalize placements that spread load when many
    // bins are open; encourage filling existing bins.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // the item cannot be placed snugly anywhere (large residual waste would
    // otherwise occur) or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 20.0;
        // Attractive if the item is large (would leave little residual anyway)
        // or if open bins are nearly full (mean residual low).
        if item_size >= 70 || (open_bins_count > 0 && mean_residual < 20.0) {
            score -= 35.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 10.0 * progress;
        }
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward the placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would NOT fit in the post residual but would fit a fresh bin,
    // mildly penalize leaving a near-miss gap.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect/near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // exact chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after hypothetical next placement
            score += slack * 0.5;
            // bonus if chain leaves small remainder
            if slack <= 5.0 {
                score -= 100.0;
            }
        } else {
            // next item cannot follow here: penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.3;
        }
    } else {
        // last item: prefer minimal residual strongly
        score += post_residual as f64 * 0.5;
    }

    // Compare residual against mean residual of open bins:
    // favor bins with residual close to item (below mean residual => tight bin)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a brand-new bin when good open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline penalty, relaxed if many open bins are fragmented
        let mut penalty = 120.0;
        if open_bins_count > 0 {
            penalty *= 1.0 + (open_bins_count as f64).ln().max(0.0) * 0.1;
        }
        // if next item is large and current item is small, opening fresh bin is ok
        if next_item_size >= 50 && item_size <= 30 {
            penalty -= 60.0;
        }
        score += penalty;
    }

    // Slight preference to fill older bins as stream progresses (reduce open-bin count)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            let slack = (post_residual - next_item_size) as f64;
            score += 0.15 * slack; // prefer exact two-item packing
        } else {
            score += 20.0; // dead space for next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Time horizon: early on, be picky; later, consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (100.0 - waste) / 100.0;

    // Prefer fuller bins relative to fleet mean residual
    let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 20.0 * fullness;
    score += 5.0 * (mean_residual - bin_residual as f64).abs() / 100.0;

    // New-bin candidate: make it attractive only when fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = waste > 30.0 || (next_item_size > 0 && next_item_size > post_residual);
        if poor_fit {
            score -= 45.0;
        } else {
            score += 35.0; // keep using open bins when fit is decent
        }
        // Fewer open bins -> cheaper to open new
        score -= 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: reward small post_residual more strongly as stream progresses.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    score -= 30.0 * (1.0 - pr_norm).powi(2) * (0.5 + progress);

    // Non-linear tight-fit bonus scaled by stream progress.
    score -= 20.0 * ((pr_norm * std::f64::consts::PI).sin().abs()) * progress;

    // Penalize large dead space non-linearly, stronger early in stream.
    score += 15.0 * pr_norm.powi(3) * (1.0 - progress);

    // Last-chance bin: reward strongly to avoid opening new bins.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    }

    // Lookahead: penalize leaving residual that barely fits next item (wasteful), reward leaving room.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - fit_quality).powi(2);
        } else {
            score += 12.0 * (1.0 - pr / nxt.max(1.0));
        }
    }

    // Mean residual divergence penalty: prefer bins near mean (balance).
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;

    // Mild reward for consolidating into few bins.
    score -= 2.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste penalty grows quadratically for small residuals.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.35;
    } else {
        score -= 60.0; // perfect fill
    }

    // Harmonic class: post_residual divisible classes mod capacity fractions
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    if pr % 25 == 0 && pr > 0 { score += 8.0; }      // leaves quarter-slots
    if pr % 20 == 0 && pr > 0 { score += 4.0; }
    if pr % 10 == 0 && pr > 0 { score += 2.0; }
    if pr > 0 && pr < 10 { score += 25.0; }          // dead space < 10

    // Lookahead: reward if next item fits exactly in the leftover
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8;
        } else {
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score = 55.0 + fragmentation * 0.3 - (open_bins_count as f64).min(10.0) * 0.5 + progress * 10.0;
        if item_size >= 60 { score -= 15.0; } // big items start fresh bins
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity { score -= 10.0; }
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (size 1) are pure waste; small unusable gaps
    // (1..=8) get a heavy nonlinear penalty.
    if post_residual >= 1 && post_residual <= 8 {
        score += 60.0 * (9.0 - post_residual as f64);
    } else if post_residual > 8 && post_residual < 14 {
        // gray zone: likely dead space for typical item sizes
        score += 20.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Perfect pre-fit (residual equals item): extremely desirable.
    if bin_residual == item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage scattering across many bins when a
    // tight fit exists; encourage consolidation when bins are few.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0;

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // reward; if next item cannot fit but post_residual is large-ish, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && post_residual >= 1 && post_residual < 10 {
            score += 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins) to keep large residuals available for big items.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.3;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // New-bin candidate: only attractive when no good fit exists anywhere.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40.0 || (post_residual >= 1 && post_residual <= 8);
        if poor_fit {
            score -= 35.0; // opening a new bin beats wasting space
        } else {
            score += 25.0; // prefer reusing an open bin with decent fit
        }
    }

    // Slight late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // Next item fits: good, but penalize large leftover slack after that.
            let second_left = post_residual as f64 - next_item_size as f64;
            score -= 40.0 - second_left * 0.5;
        } else {
            // Next item does NOT fit after placement: penalize proportionally to overshoot.
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += overshoot * 0.8;
        }
    }

    // Compare post_residual against mean residual: prefer leaving residuals
    // that are small relative to the average open space (compact bins).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless this is a great fit
    // or the item barely fits anywhere else.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 60.0; // item nearly fills a fresh bin anyway
        }
        // Early in the stream, opening bins is cheaper (more future freedom).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 40.0;
    }

    // Slight preference for filling already-open bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space that few common items can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 40 {
        score += 0.5 * (post_residual as f64 - 10.0); // mildly awkward zone
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are already open (fragmentation risk).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 15.0 * progress + 0.3 * open_bins_count as f64;
        // But if lookahead item won't fit anywhere well anyway, soften slightly.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 5.0;
        }
    }

    // Lookahead coupling: bonus if next item fits into post_residual exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual as f64 - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize if next item is stranded just above post_residual.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
    }

    // Global state: when mean residual is high, prefer using fuller bins.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: early on, be conservative about tight fits; later, exploit them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr) + 40.0 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, waste matters more
    score += 30.0 * progress * norm_pr * norm_pr;

    // Dead-space penalty: residual too small to fit typical future items
    let dead = if pr > 0 && pr < 10 { 1.0 } else { 0.0 };
    score += 15.0 * dead * (0.5 + progress);

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let tightness = next_item_size as f64 / pr.max(1.0);
        score -= 12.0 * (1.0 - 0.5 * tightness) * (1.0 - 0.5 * progress);
    } else if next_item_size > post_residual {
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins with residual far from mean (fragmentation avoidance)
    score += 0.15 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate baseline: neutral-ish, slightly penalized early, more attractive if open bins are fragmented
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * (1.0 - progress) - 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic class of post_residual: mod 10 buckets
    let pr = post_residual;
    let class = pr % 10;
    // Dead space classes: residuals 1..=9 are hard to fill; 10,20,30 are semi-useful
    if pr > 0 && pr <= 9 {
        score += 60.0 - 5.0 * class as f64;
    } else if pr >= 10 && pr <= 20 {
        score += 10.0;
    }

    // Integer-division thresholds: post_residual in [51..=60] leaves room for medium items
    if pr / 10 == 5 || pr / 10 == 6 {
        score -= 15.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains perfectly: strong reward, tighter if exact
            let gap = pr - next_item_size;
            score -= 40.0 + gap as f64 * 0.2;
        } else {
            // next item won't fit here: penalize small unusable leftovers more
            score += (next_item_size - pr) as f64 * 0.5;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is only attractive if no open bin
    // offers a good fit. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // neutral base for new bin; add cost proportional to open bins to discourage
        // proliferation, but reward it when current fit would create tiny dead space
        score = bin_capacity as f64 * 0.75 + open_bins_count as f64 * 4.0;
        if pr > 0 && pr <= 9 {
            score -= 100.0; // opening new bin beats leaving dead space
        }
        if next_item_size > 0 && next_item_size <= pr {
            score += 50.0; // an open bin chains the next item: keep it there
        }
    }

    // Late-stream tightening: prefer compact packing as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual)
    score += post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 - 2.0 * post_residual as f64;
    }
    // Perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Post-residual that can still fit the lookahead item is valuable
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: mild penalty scaled by gap size
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // opening a new bin is fine for large items, costly for small ones
        score += 20.0 * (1.0 - tightness);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Mild drift with stream progression: early on, be conservative with bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Favor bins whose residual is close to the item (relative fit)
    if bin_residual >= item_size {
        score -= 8.0 * (1.0 - (item_size as f64 / bin_residual as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) non-linearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Quadratic dead-space penalty scaled by fill fraction.
        let waste = post_residual as f64 / cap;
        score += waste * waste * 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item exactly or nearly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= (30.0 * (1.0 - gap / cap)).max(0.0);
        } else {
            // Post-residual too small for next item: mild penalty unless tiny.
            score += gap * 0.15;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 20.0 * (1.0 - post_residual as f64 / cap);
    }

    // Compare against mean residual across open bins: prefer bins that
    // are already tighter than average (consolidation).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // current bins fit poorly; stronger penalty when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_penalty = 15.0 + 2.5 * open_bins_count as f64;
        score += open_penalty * (0.5 + 0.5 * progress);
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if next item fits into post_residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
    }
    // Penalize if next item cannot fit anywhere after this placement (dead end).
    if next_item_size > 0 && post_residual < next_item_size && next_item_size <= bin_capacity {
        score += 5.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are already open, unless the item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut penalty = 25.0 + progress * 15.0 + (open_bins_count as f64) * 1.5;
        // Large items are hard to place later; soften the penalty.
        penalty -= item_frac * 20.0;
        // If mean residual across open bins is small, new bin is more attractive.
        penalty -= (mean_residual / bin_capacity as f64).max(0.0) * 20.0;
        score += penalty.max(0.0);
    }

    // Slight preference for filling bins with higher residuals (consolidation).
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    // Small time-dependent nudge toward consolidation early, exploration late.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let post_residual = post_residual as f64;
    let mut score = post_residual;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit and small-dead-space classes rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 15 {
        score -= 10.0;
    } else if pr <= 30 {
        score -= 3.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes are reusable.
    for &m in &[10u32, 20, 25, 30, 40, 50] {
        if pr >= m && pr % m == 0 {
            score -= 8.0;
        }
    }

    // Dead-space penalty: residuals that no plausible item (1..=80) can pair with well.
    if pr > 0 && pr < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 15.0;
        } else if next_item_size > pr {
            score += 6.0; // next item won't fit here anyway; slight penalty
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: prefer it only when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost grows with number of open bins.
        score = cap * 0.85 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with large next item
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // Mild preference for fuller bins (tight fit) via mean residual contrast.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;
    }

    // Progress drift: slightly favor tight fits as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals that are too small to be useful are heavily penalized.
    // A residual below the minimum plausible item size is nearly dead space.
    if post_residual > 0 {
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
        // Residuals that cannot fit a mid-sized item are semi-dead.
        if post_residual < item_size.saturating_sub(1) {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual as f64 <= bin_capacity as f64 * (1.0 - fill_ratio) * 0.05 + 1.0 {
        score -= 12.0;
    }

    // Prefer bins whose residual was already small (best-fit flavor).
    score += (bin_residual as f64 - post_residual as f64) * 0.0;
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Open bins pressure: with many open bins, avoid spreading; favor filling.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Lookahead: if next item fits the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item is large and this bin would be emptied anyway, encourage packing here.
    if next_item_size > post_residual && next_item_size > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If existing bins are fragmented (high mean residual but poor fits), new bin is fine.
        if mean_residual > 0.0 && item_size as f64 > mean_residual {
            score -= 35.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmentation.
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/near-exact matches with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits after this placement: reward tightness of that fit.
            score -= 60.0 - gap.min(60.0);
            if post_residual == next_item_size {
                score -= 40.0; // perfect chain: this bin becomes exactly filled next step
            }
        } else {
            // Dead space: next item cannot follow in this bin.
            score += gap * 0.5;
        }
    } else {
        // Last item: reward filling the bin as tightly as possible.
        score -= 50.0;
    }

    // Penalize residuals that are too small to ever hold a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    // Compare against mean residual across open bins: prefer bins that get closer to zero residual.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: discourage opening yet another bin; prefer consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, cheaper only when few bins can fit or lookahead says so.
        let mut open_cost = 30.0 + (open_bins_count as f64) * 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            open_cost -= 25.0; // fresh bin can chain with next item
        }
        if fitting_bins_count <= 1 && bin_residual < bin_capacity {
            open_cost += 20.0;
        }
        score = open_cost + score * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let wasted = (next_item_size - post_residual) as f64;
            score += 0.6 * wasted;
        } else {
            // Reward bins whose leftover can host the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.25 * slack;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // fits badly everywhere (large item) and future items may need fresh space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let poor_fit = mean_residual > 0.0 && (item_size as f64) > mean_residual;
        let mut penalty = 45.0;
        if big_item {
            penalty -= 20.0;
        }
        if poor_fit {
            penalty -= 15.0;
        }
        // Early in the stream, opening bins is cheaper (more future to fill them).
        penalty *= 1.0 - 0.3 * progress;
        // If many bins are open, discourage spreading further.
        penalty += 1.5 * open_bins_count as f64;
        score += penalty;
    }

    // Mild bonus for bins below mean residual (consolidate emptier bins).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // Time-horizon modulation: late in stream, prioritize minimizing residual now.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap; // quadratic waste penalty

    // smooth non-linear coupling of waste with stream progress
    score += 12.0 * (post / cap).powi(3) * (0.5 + 0.5 * progress);

    // reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * (1.0 - post / cap);

    // lookahead: reward bins whose residual accommodates the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / cap) * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress); // next item won't fit here
    }

    // last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // new-bin candidate: penalize opening new bins when good fits exist
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 0 { 1.0 / (1.0 + fitting_bins_count as f64) } else { 1.0 };
        score += 10.0 + 10.0 * fit_pressure * (1.0 - progress);
        // early in stream, opening bins is cheaper
        score -= 6.0 * (1.0 - progress);
    }

    // mild penalty for proliferation of open bins with large mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins grouped by capacity fractions.
    // Residuals in the lowest quarter are "harmonically tight" — reward them.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual < quarter {
        score -= 12.0; // near-full bin, excellent fit
    } else if post_residual < half {
        score -= 4.0;
    } else {
        score += 3.0; // wasteful placement, leaves big hole
    }

    // Modulo classes on post_residual: residuals that are multiples of small
    // harmonic units (e.g. 10, 25) are more reusable by future items.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }
    // Odd, awkward residuals are dead space.
    if post_residual % 2 == 1 && post_residual < quarter {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement is perfect — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot class.
            let overshoot = (next_item_size - post_residual) / 10;
            score += overshoot as f64 * 1.5;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins
    // would leave very poor fits or when bins are plentiful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a bin is cheap early, expensive late.
        score += 30.0 - 20.0 * progress;
        if open_bins_count > 3 {
            score -= 8.0; // many open bins: consolidation preferred, keep this as fallback
        }
        if item_size >= bin_capacity - quarter {
            score -= 15.0; // big item: fresh bin is natural
        }
    }

    // Mean residual coupling: placing into a bin whose residual is below the
    // mean tightens the distribution — reward it.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.05;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap is "dead" if no plausible future item (min size 1..=10) can be assumed;
    // treat gaps below the smallest realistic item (<= 10) as total waste.
    let gap = post_residual;
    if gap > 0 && gap < 10 {
        score += 60.0 * (10.0 - gap as f64);
    } else if gap >= 10 && gap < 20 {
        score += 12.0 * (20.0 - gap as f64) / 10.0;
    }

    // Perfect fit reward.
    if gap == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= gap {
        let slack = (gap - next_item_size) as f64;
        score -= 30.0 - 0.6 * slack;
        if gap == next_item_size {
            score -= 50.0;
        }
    } else if next_item_size > gap && gap > 0 {
        // Next item won't fit here: mild penalty proportional to wasted lookahead.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += 3.0 * pressure;

    // Prefer bins tighter than the mean residual (good packing).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive if existing bins would leave big dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * open_bins_count as f64;
        if item_size == bin_capacity {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 120.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space that the next item cannot use — penalize proportionally.
            let dead = post_residual as f64;
            let next = next_item_size as f64;
            if dead < next {
                score += 30.0 + 0.5 * (next - dead);
            }
        }
    }

    // Penalize leaving large unusable residual relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny residual is nearly a full fit
    }
    if post_residual > 50 {
        // Large leftover: only acceptable if it can host the next item.
        if next_item_size == 0 || post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual is above average (absorbs item into emptier bins less wastefully).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= 0.3 * (residual_f - mean_residual);
    } else {
        score += 0.3 * (mean_residual - residual_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
        if post_residual <= 15 {
            score -= 40.0;
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early in the
    // stream and when many bins are already open with slack.
    if bin_residual == bin_capacity {
        score += 80.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            // Next item is bigger: a fresh bin might serve it better — soften penalty.
            score -= 30.0;
        }
    }

    // Slight preference to fill fuller bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else if next_item_size > 0 && (next_item_size as f64) > dead {
            // residual can't fit the lookahead item: mild penalty
            score += 4.0 * (1.0 - dead / (next_item_size as f64));
        } else if next_item_size > 0 {
            // residual can host the next item: reward
            score -= 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins over emptier ones when multiple fit.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * fill;

    // Global pressure: many open bins with low mean residual -> consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if (mean_residual - bin_residual as f64).abs() > 1e-9 {
        // prefer bins below mean residual (fuller than average)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0 * (1.0 - progress);
        } else {
            score += 2.0 * progress;
        }
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // base cost of opening a new bin, softened late in the stream
        score += 18.0 + 25.0 * desperation * (1.0 - progress);
        // if item is large, opening fresh is less wasteful
        score -= 0.15 * (item_size as f64);
        // if lookahead is large too, a fresh bin is valuable
        if next_item_size >= item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, with non-linear penalty on dead space
    let mut score = post;
    score += 30.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: later in the stream, tighten more
    let tightness = (post - item_size as f64).max(0.0) / cap;
    score -= 25.0 * progress * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 8.0 * norm_post * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let desperation = (mean_residual - item_size as f64).max(0.0) / cap;
        score = cap * (0.6 + 0.4 * progress) - 30.0 * desperation;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Penalize bins far from mean residual (fragmentation)
    score += 5.0 * ((post - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near capacity fractions
    // (0, cap/4, cap/2, 3cap/4) are more "reusable" for future items.
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let three_quarter = 3.0 * quarter;

    // Distance to nearest harmonic grid point (cap/4 spacing).
    let grid_dist = (pr / quarter).round() * quarter - pr;
    let harm_bonus = -12.0 * (1.0 - grid_dist / (quarter / 2.0)).max(0.0);
    score += harm_bonus;

    // Integer-division thresholds on post_residual:
    // zero residual is perfect; tiny residuals (<10, min item size) are dead space.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score += 40.0; // unusable dead space penalty
    }

    // Class of post_residual by integer division by item-size quantum.
    let class = post_residual / 10;
    match class {
        0 => score += 25.0,
        1 => score -= 5.0,
        2 => score -= 10.0,
        3 => score -= 8.0,
        4 => score -= 12.0,
        5 => score -= 10.0,
        6 => score -= 6.0,
        7 => score -= 3.0,
        8 => score -= 1.0,
        _ => {}
    }

    // Lookahead coupling: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 80.0; // perfect harmonic match with next item
        } else if next_item_size <= post_residual {
            score -= 15.0 * (nx / cap);
        } else {
            // next item won't fit here; penalize more if post_residual is small
            score += 8.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer using bins below mean residual (tighter bins).
    score += 0.15 * (pr - mean_residual);

    // New-bin candidate: neutral-ish baseline, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.85 + 20.0;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps (1..=9) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer placing into existing bins over opening new ones
    // when many bins are open.
    score += 2.5 * open_bins_count as f64;

    // New-bin candidate: baseline competitive score, penalized more when
    // existing bins fit well (post_residual of new bin = capacity - item).
    if bin_residual == bin_capacity {
        score += 55.0;
        // If lookahead item could fill this new bin's residual later, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead synergy: if next item exactly fits the resulting residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }

    // Prefer bins whose residual is close to mean (keeps bin balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
