pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Exact fill is golden.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space: penalize residuals too small for any item (min size 1 => residual 0 only),
    // but penalize small awkward residuals relative to typical item size.
    let awkward = (post_residual as f64) < 12.0 && post_residual > 0;
    if awkward {
        score += 8.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Extra reward when next item fills the remainder almost exactly.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here: mild penalty for leaving a medium residual.
            score += 3.0;
        }
    } else {
        // Last item: prefer fullest fill, new bins are worthless.
        if bin_residual == bin_capacity {
            score += 1000.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (item barely fits anywhere) or few fitting bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fit_ratio = (item_size as f64) / (bin_residual as f64);
        // Penalize new bins generally, but less late in the stream or when fit is poor.
        let mut new_bin_penalty = 12.0;
        if fit_ratio > 0.85 {
            new_bin_penalty -= 6.0; // item almost fills a fresh bin: acceptable
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 20.0; // no alternative
        }
        new_bin_penalty += progress * 5.0; // late stream: consolidating matters more
        score += new_bin_penalty;
    } else {
        // Existing-bin bonus scaled by how crowded the bin already is.
        let used_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 2.0 * used_ratio;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into fuller-than-average bins.
    if open_bins_count > 2 {
        let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += 4.0 * rel; // lower residual than average => lower score => favored
    }

    // Time horizon: early stream, be picky about waste; late stream, just fill.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual) with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: later in the stream, waste matters more (convex penalty).
    let prog_term = progress * progress;
    score += 8.0 * prog_term * norm_pr * norm_pr;
    score -= 3.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 5.0 * progress;
    }

    // Mean-residual coupling: prefer bins below mean residual (consolidate emptier bins).
    score += 0.15 * (pr - mean_residual);

    // Slight penalty for too many open bins relative to remaining stream.
    let open_norm = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 20.0 * open_norm * open_norm;

    // New-bin candidate bias: mildly discourage opening a fresh bin unless residuals are tight.
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress + 0.05 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 classes.
    // Residuals that are "useless" (very small but nonzero) are heavily penalized;
    // residuals that are perfect multiples of common item sizes are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let dead = if pr < 10 { 3.0 } else { 0.0 };
        score += dead * (1.0 + (cap - pr as f64) / cap);

        // Reward residuals divisible by 10 / 20 / 25 / 50 (harmonic with capacity)
        if pr % 50 == 0 { score -= 6.0; }
        else if pr % 25 == 0 { score -= 4.0; }
        else if pr % 10 == 0 { score -= 3.0; }
        else if pr % 5 == 0 { score -= 1.0; }
        else { score += 1.5; }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let new_pr = pr - next_item_size;
            if new_pr % 10 == 0 { score -= 5.0; }
            score -= 2.0 * (next_item_size as f64 / cap);
        } else {
            // Next item won't fit here: penalize leaving residual it could nearly use.
            if pr > 0 && next_item_size > pr {
                score += (next_item_size - pr) as f64 * 0.05;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // gives a good fit (post_residual small) or when bins are scarce/early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins with decent fits win.
        score += 30.0;
        // If the item leaves a bad residual in every open bin (post_residual tiny
        // but nonzero), a new bin may be better: relax the penalty.
        if pr > 0 && pr < 10 {
            score -= 35.0;
        }
        // Early in the stream or many open bins with high mean residual:
        // spreading load is fine.
        if progress < 0.2 { score -= 5.0; }
        if mean_residual > cap * 0.5 { score -= 3.0; }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.02 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64).abs() * 0.05;

    // Exact-fill fraction coupling: reward high fill ratio.
    score -= 10.0 * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item (1..10 range guard, assume min item ~10) are wasted forever.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // hard dead-space penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill reward
    }

    // Reward tight fits (small fraction of capacity wasted)
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_frac * waste_frac;

    // Open-bin pressure: discourage proliferation of bins
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // If the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post residual and residual is small, penalize
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Mean residual coupling: bins far below mean residual are fresher;
    // prefer filling bins whose residual deviates from mean (consolidation)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Slight stream progression effect: early on, be conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-match with lookahead (waste <= 10)
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= (10.0 - gap) * 2.0;
        } else {
            // penalize leaving a residual that's too small for the next item (dead space)
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins with residual far below mean residual (fragmented bins)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Slight preference for tighter bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        let bad_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 25.0 };
        let new_bin_penalty = 55.0 + crowded * 3.0 + bad_fit;
        score += new_bin_penalty;
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening new bin is fine if no good alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when the lookahead item also fits in the post-residual (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Lookahead fits the bin now but not after us: mild penalty for wasting space.
        score += 6.0;
    }

    // Penalize tiny dead space that nothing (min size 1..100 stream) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin, more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 30.0 * (1.0 - progress);
        // But if the item fits poorly in every open bin, new bin becomes attractive:
        if post_residual < 20 && fitting_bins_count <= 1 {
            score -= 35.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit reward).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Slight preference for bins below mean residual (consolidate fuller bins).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    // Mild pressure to use many open bins when they accumulate.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits with a smooth non-linear term.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fit_ratio.powf(4.0) * (1.0 + 0.5 * progress);

    // Penalize dead space relative to mean residual across open bins.
    score += 0.15 * ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs();

    // Lookahead coupling: bonus if next item fits smoothly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * next_fit.powf(3.0);
    }
    // Penalize if post_residual is small but nonzero (unusable sliver).
    if post_residual > 0 && next_item_size > post_residual {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: penalize opening a new bin when other bins fit,
    // but allow it when it's the only option (last-chance).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual falling in "small dead space" classes is bad
    // Class boundaries at capacity fractions: 0, cap/8, cap/4, cap/2, 3cap/4
    let eighth = cap / 8.0;
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let threeq = 3.0 * cap / 4.0;

    if post > 0.0 && post <= eighth {
        score += 30.0; // tiny unusable sliver
    } else if post <= quarter {
        score += 10.0;
    } else if post <= half {
        score -= 5.0;
    } else if post <= threeq {
        score -= 12.0;
    }

    // Integer division thresholds: post_residual / 10 class
    let post_class = post_residual / 10;
    match post_class {
        0 => score += 40.0,
        1 | 2 => score += 15.0,
        3 | 4 => score -= 8.0,
        5 | 6 => score -= 15.0,
        _ => score -= 20.0,
    }

    // Modulo coupling with next item: reward residuals that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + (next_item_size as f64) * 0.2;
        // extra reward if residual is a near-harmonic multiple of next item size
        if post_residual % next_item_size.max(1) <= 2 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // dead space relative to the lookahead item
        score += (next_item_size as f64 - post as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post).abs();
        if open_bins_count > 0 && mean_residual >= item_size as f64 * 1.5 {
            score += 45.0 + fragmentation * 0.1;
        } else {
            score += 5.0;
        }
    }

    // Progress-scaled tie-breaking: prefer tighter bins later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - item_size as f64) * 0.1;
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1..100 range),
    // so gaps below ~10 are nearly worthless; scale penalty quadratically.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64 * 2.0;
    } else if post_residual < 35 {
        score += 10.0 + (35 - post_residual) as f64 * 0.8;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement heavily (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0 - slack;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to gap smallness.
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // penalize placements that leave large residuals when bin count is high.
    let obp = open_bins_count as f64;
    score += (post_residual as f64 / bin_capacity as f64) * obp * 1.5;

    // Progress-aware mild tightening: later in the stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    // New-bin candidate must not be chosen too eagerly: penalize slightly,
    // but allow it when this bin's fit would be terrible.
    if bin_residual == bin_capacity {
        score += 12.0 - (post_residual as f64).min(12.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: strongly reward bins whose post residual
    // exactly matches the next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Near-match: reward small |post_residual - next_item_size| gaps.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 / (1.0 + gap / 8.0);
    }

    // Penalize leaving dead space below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with residual below the mean residual (tighter packing),
    // but only mildly, so lookahead matches dominate.
    let residual_f = post_residual as f64;
    score += 0.3 * (residual_f - mean_residual);

    // Progress-based pressure: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * residual_f * 0.2;

    // Slight bias against opening new bins when many bins are already open
    // and this bin is empty.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * tightness * tightness * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit, unless the item
    // would leave a large unusable residual everywhere.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost so it is only chosen when fits are bad.
        score += 15.0;
        // Lookahead: if next item fits well in the leftover of this fresh bin,
        // opening is more attractive.
        if next_item_size > 0 {
            let lookahead_fit = if post_residual >= next_item_size {
                (post_residual - next_item_size) as f64
            } else {
                post_residual as f64 + 20.0
            };
            score += 0.3 * lookahead_fit;
        }
        // Fewer open bins => cheaper to open a new one.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead for existing bins: if the residual left here cannot hold the
    // next item, penalize proportionally; if it can, reward.
    if next_item_size > 0 && bin_residual != bin_capacity {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins whose residual deviates favorably from the mean: bins with
    // more room than average can absorb large future items; tight bins should
    // be filled now.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Small nudge: prefer bins with smaller residual early (best-fit-like).
    score += 0.05 * bin_residual as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth stream-progress coupling: early on, tolerate larger residuals;
    // late in the stream, penalize them more strongly (polynomial in progress)
    let progress_coupling = 1.0 + 1.5 * progress * progress + 2.0 * progress * x;
    score *= progress_coupling;

    // Dead-space term: residuals too small to ever fit another item are wasted
    let min_item = 1.0f64;
    if pr < min_item {
        score += 50.0;
    } else {
        // smooth unusability: fraction of item sizes that could fit shrinks
        let usable = (pr / cap).clamp(0.0, 1.0);
        score += (1.0 - usable) * (1.0 - usable) * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if the next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // penalty scaled by how much the next item overshoots
            let over = (nxt - pr) / cap;
            score += 8.0 * over * over;
        }
    }

    // Crowding: many open bins with high mean residual -> prefer consolidating
    let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    let mean_gap = (mean_residual - pr) / cap;
    score += 5.0 * crowding * mean_gap * mean_gap;

    // New-bin candidate: mildly discourage unless residual structure is bad
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in small classes is worse.
    let pr = post_residual;
    let class = pr / 10; // coarse harmonic class
    match class {
        0 => score -= 25.0,               // near-perfect fit (0..9 dead)
        1 => score -= 10.0,               // good fit
        2 => score -= 3.0,                // moderate
        3 => score += 6.0,                // wasteful
        _ => score += 12.0,               // large dead space
    }

    // Modulo coupling: post_residual divisible by 10 aligns with future items
    // (items 1..100; multiples of 10 are common anchor sizes).
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 2.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize leaving medium residuals
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        // If current bin would leave a tiny residual, opening fresh is fine.
        if bin_capacity - item_size <= 10 {
            score -= 25.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual relative to mean).
    if mean_residual > 0.0 {
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    // Early in the stream, be more willing to open bins (keeps options open).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score -= (1.0 - progress) * 8.0;
        }
    }

    // Many open bins: discourage spreading, encourage consolidation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // Dead space = post_residual that is too small for typical future items.
    if post_residual > 0 {
        // Threshold: smallest possible item is 1, but treat gaps below a
        // conservative "useful gap" band as dead space.
        let dead_threshold: f64 = 12.0;
        let pr = post_residual as f64;
        if pr < dead_threshold {
            // Quadratic penalty ramping up as the gap shrinks toward zero.
            let severity = (dead_threshold - pr) / dead_threshold;
            score += 40.0 * severity * severity;
        }
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward fits that leave exactly a small-but-still-usable gap? No:
    // instead reward placements where the gap can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0; // chain-friendly placement
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap cannot host next item: mild penalty proportional to next item size.
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Tightness reward: item filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one
    // and encourage consolidating into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 30.0 + 50.0 * open_pressure;
        // But if no open bin can fit at all, new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If the next item is huge and this item is small, prefer existing bins.
        if next_item_size > 60 && item_size < 40 {
            score += 10.0;
        }
    } else {
        // Existing bin: slight reward scaling with open-bin pressure (consolidation).
        score -= 10.0 * open_pressure;
        // Prefer bins with residual below mean (tighter bins first).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Late in the stream, favor closing bins tightly (less future to plan for).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step chain: this bin absorbs item AND next item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Reward if the next item fits into the post residual (good lookahead match).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
    }
    // Penalize dead space that neither this stream nor the next item can use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Prefer keeping residuals near the mean (balanced packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral-ish but slightly penalized so we prefer reusing open bins
    // unless the fit in existing bins is very poor (large post_residual there wins this out).
    if bin_residual == bin_capacity {
        score += 40.0;
        // If no open bin fits at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    // Mild reward for tight fits overall.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Slight preference to fill bins early in the stream (keep flexibility later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect-fit reward: eliminate dead space aggressively.
    if post_residual == 0 {
        score -= cap * 2.0;
    } else {
        // Squared waste penalty: small residuals are strongly preferred.
        score += (post_residual as f64) * (post_residual as f64) / cap;
    }

    // Lookahead: if the next item fits in the post-residual, this bin stays useful.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * nxt; // reward leaving a usable gap
            // Extra reward if next item exactly fills the leftover.
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Leftover too small for the next item: penalize proportionally to tightness.
            let tight = (post_residual as f64) / cap;
            if tight < 0.10 {
                score += 15.0 * (1.0 - tight / 0.10);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 1.5;
    }

    // New-bin candidate: make it expensive unless it's genuinely the best option.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress (fewer future chances to consolidate).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = cap * (0.55 + 0.45 * progress);
        // Cheaper to open a new bin when many open bins have poor residuals (fragmentation).
        if mean_residual < 0.25 * cap {
            open_cost -= 10.0;
        }
        // Discard perfect-fit / last-chance rewards for the empty bin.
        score = open_cost + (post_residual as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0; // a fresh bin naturally accommodates the next item
        }
    }

    // Mild pressure against accumulating many open bins when this placement is mediocre.
    if open_bins_count > 4 && post_residual > 0 {
        score += 0.5 * (open_bins_count.min(20) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + t) - norm_pr * (1.0 - t);
    score += poly * cap * 0.5;
    // Penalize dead space more as stream progresses
    score += norm_pr * norm_pr * cap * t * 2.0;
    // Reward tight fits (small post_residual) via smooth saturating term
    let tight = 1.0 - (norm_pr * std::f64::consts::PI / 2.0).min(std::f64::consts::FRAC_PI_2).cos();
    score -= tight * cap * (1.0 - t) * 0.6;
    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (1.0 + t);
    }
    // Lookahead coupling: prefer bins whose leftover matches next item smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let norm_gap = gap / cap;
        score += norm_gap * norm_gap * cap * 0.8;
        // exact-fit lookahead reward
        if pr >= next_item_size as f64 {
            score -= (1.0 - norm_gap) * next_item_size as f64 * 0.3;
        }
    }
    // Mild preference to fill bins below mean residual (balance avoidance)
    score -= (mean_residual - pr) * 0.05;
    // New-bin candidate: penalize slightly unless current bin leaves bad residue
    if bin_residual == bin_capacity {
        score += cap * 0.15 * (1.0 - t) + norm_pr * cap * 0.1;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Residuals near multiples of small "class" sizes are reusable.
    let class = post_residual % 25; // coarse harmonic class
    score += (class as f64) * 0.35; // penalize residuals off-class

    // Perfect/near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead space: residual too small for typical items (1..=100, min item 1).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Coupling with lookahead: reward residual that can host next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 10.0; // next item won't fit here
        }
        // Harmonic pairing: post_residual and next_item in same residue class mod 20
        if post_residual >= next_item_size && (post_residual - next_item_size) % 20 == 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (item leaves large residual spread across many bins).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = (fitting_bins_count as f64).ln().max(0.0);
        let poor_fit = (post_residual as f64) / cap; // = 1.0 for new bin
        score = 100.0 - 30.0 * fit_pressure - 20.0 * progress;
        // discourage new bins when a tight fit exists elsewhere is handled
        // by that bin's low score; keep new-bin score moderate.
        let _ = poor_fit;
        let _ = mean_residual;
    }

    // Slight preference for filling bins with above-average fullness.
    let fullness = (bin_capacity as f64 - post) / cap;
    score -= fullness * 5.0;

    // Integer-division threshold: bins whose residual falls in "harmonic"
    // bands (multiples of 10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild penalty for spreading across many open bins late in stream.
    if open_bins_count > 10 {
        score += (open_bins_count as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below minimum item size 1..~10)
    // are worthless, so heavily penalize post_residual that falls into a dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits (post_residual close to 0 but still usable).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: penalize spreading across many bins; encourage filling
    // existing bins rather than opening new ones when pressure is high.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement strongly (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If next item cannot fit in post_residual but the residual is large,
    // mildly penalize leaving big-but-mismatched gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual >= 10 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (tighter than average) to consolidate space.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild stream-progression term: later in the stream, be more conservative
    // about opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    // New-bin candidate baseline: empty bins should only win when nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot follow here; penalize proportionally to leftover
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual across open bins
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let ratio = pr / mean_residual;
        score += 20.0 * (ratio - 1.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item
    // would leave a large dead space in every existing fit
    if bin_residual == bin_capacity {
        let waste = pr;
        // Opening a new bin is attractive if this item is small relative to capacity
        let openness = 1.0 - (item_size as f64) / (bin_capacity as f64);
        score = 50.0 + waste - 80.0 * openness;
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            // fresh bin can also host the next item: very attractive
            score -= 250.0;
        }
        if fitting_bins_count == 1 {
            // an existing bin is a last chance: discourage opening a new one
            score += 400.0;
        }
    }

    // Early in stream: slightly prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual relative to capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size {
            // Could place next item here instead; slight penalty for wasting that option.
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it attractive only when the fit in
    // existing bins is poor or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let poor_fit = mean_residual - item_size as f64;
        // Base cost of opening a bin, reduced by stream maturity and bin pressure.
        let mut open_cost = 55.0
            - 30.0 * (step_index as f64 / total_items.max(1) as f64)
            - 20.0 * pressure;
        if poor_fit < 15.0 {
            open_cost += 30.0; // existing bins fit well; discourage opening
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            open_cost -= 10.0; // fresh bin accommodates lookahead
        }
        if open_bins_count == 0 {
            open_cost = -100.0;
        }
        score += open_cost;
    }

    // Mild penalty for bin sprawl when many bins are open with large residuals.
    if open_bins_count > 3 && mean_residual > 40.0 && bin_residual >= mean_residual {
        score += 4.0;
    }

    // Slight preference for bins with residual close to item size (perfect fit).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), non-linearly
    let mut score = post;
    score += 40.0 * pr * pr * (1.0 - pr);

    // Smooth coupling: as stream progresses, penalize leftover dead space more strongly
    score += 30.0 * progress * pr * pr;

    // Reward perfect-ish fits with a smooth dip around pr ~ 0
    score -= 25.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - progress);

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize mildly unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 20.0 * (1.0 - fill) * (1.0 - progress);
        score -= 10.0 * fill * progress;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 8.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 5.0 * (next_item_size as f64 / cap);
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to item size.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / item_size as f64;
        score += waste_ratio * 6.0;
    } else {
        score -= 25.0; // perfect fill
    }

    // Harmonic classes: bucket post_residual by capacity/8 classes.
    // Residuals in the smallest class (< item_size/2) are likely dead space.
    let dead_threshold = item_size / 2;
    if post_residual > 0 && post_residual < dead_threshold.max(1) {
        score += 18.0; // unusable sliver for typical future items
    }
    // Mid-class residuals (cap/4 .. cap/2) are attractive for medium items.
    if post_residual >= bin_capacity / 4 && post_residual <= bin_capacity / 2 {
        score -= 5.0;
    }

    // Lookahead: strongly favor bins where the next item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills remaining space tightly.
        let next_leftover = post_residual - next_item_size;
        if next_leftover <= 4 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys a chance to fit the next item here.
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when existing fits are all poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins waste a lot.
        score = bin_capacity as f64 * 0.55
            + post_residual as f64 * 0.1
            - (open_bins_count as f64) * 0.5;
        // If mean residual across open bins is large, opening fresh is fine.
        score -= mean_residual * 0.35;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 8.0;
        // If next item is large and would need a fresh bin anyway, open now.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Slight preference to fill already-open bins when many are open.
    score += (open_bins_count as f64) * 0.15;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create fragmented states.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += (21.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last chance: strongly favor using this bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size > bin_capacity - item_size {
        // Next item can't fit in post_residual: dead space risk, penalize moderate gaps.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Open bins pressure: with many open bins, discourage spreading; with few, opening new bins is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: baseline cost plus pressure, but attractive if no good fit exists.
        score = bin_capacity as f64 * 0.9 + pressure * 2.0;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            // Large next item: fresh bin preserves room.
            score -= 6.0;
        }
    } else {
        score += pressure * 0.5;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (consolidating).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: perfect 2-step fill is the best outcome.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-step match: bin perfectly closed
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.8; // penalize leftover after lookahead placement
        } else {
            // next item cannot follow into this bin: dead space penalty grows
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    } else {
        // last item: prefer tightest fit
        score += (post_residual as f64) * 0.3;
    }

    // Relative-to-mean residual: bins with more free space than average
    // should absorb big items; bins below mean are precious closers.
    let residual_f = post_residual as f64;
    let mean_gap = residual_f - mean_residual;
    score += mean_gap * 0.25;

    // Penalize creating unusable dead space (< smallest plausible item).
    if residual_f > 0.0 && residual_f < 10.0 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New empty bin candidate: baseline preference, better late in stream
    // when mean residuals are already low.
    if bin_residual == bin_capacity {
        let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = (bin_capacity as f64) * 0.5 + progress * 20.0
            + (residual_f - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strong when post_residual is a small fraction of capacity
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: reward residual that can still host the next item,
    // penalize residual just below next_item_size (dead zone)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Penalize creating very small unusable slivers (< 10 dead space)
    if post > 0.0 && post < 10.0 {
        score += 20.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + progress);

    // Prefer bins whose residual is below mean residual (fill the emptier ones)
    score += 5.0 * (post - mean_residual) / cap;

    // New-bin candidate: only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty to prefer existing bins
        score += 40.0;
        // but if current bin would leave a bad fit or huge dead space, allow opening
        let waste = post / cap;
        if waste > 0.5 {
            score -= 35.0 * waste;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidating into open bins
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: quadratic + cubic in normalized post_residual, modulated by progress
    score += 12.0 * (norm_pr * norm_pr) * (0.5 + progress);
    score -= 6.0 * (norm_pr * norm_pr * norm_pr) * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize dead space relative to next item lookahead (smooth interaction)
    if next_item_size > 0 {
        let next_n = next_item_size as f64 / cap;
        let gap = norm_pr - next_n;
        if gap > 0.0 {
            score += 8.0 * gap * gap * (1.0 - progress);
        } else {
            score -= 4.0 * gap * gap;
        }
    }

    // Last-chance bonus: smooth in fitting_bins_count
    if fitting_bins_count > 0 {
        let scarcity = 1.0 / fitting_bins_count as f64;
        score -= 9.0 * scarcity * scarcity * (0.5 + 0.5 * progress);
    }

    // Mild pressure coupling with mean residual and open bins
    let mr = mean_residual / cap;
    score += 3.0 * (norm_pr - mr) * (norm_pr - mr);
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize slightly so it's only chosen when genuinely better
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: perfect fits (0), small dead space (1..10),
    // medium (10..=30), large (>30). Penalize dead space non-linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 30 {
        score += 5.0 + (post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64) * 0.6;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // next item won't fit here after placement: slight penalty for chaining badly
        score += 3.0;
    }

    // Last chance: only one open bin can fit the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // fits well. Make the empty bin moderately attractive only if residuals are tiny.
    if bin_residual == bin_capacity {
        // Empty bin: score = capacity; adjust by stream progress and congestion.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64 * (0.55 + 0.45 * congestion) - 8.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    } else {
        // Prefer tighter bins: reward small bin_residual relative to capacity.
        score -= 0.35 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Harmonic modulo class of post_residual in units of 10: favor leftovers that
    // align with typical small item sizes (multiples of 10).
    let pr = post_residual as i64;
    if pr > 0 {
        let m = pr % 10;
        if m == 0 {
            score -= 4.0;
        } else {
            score += m as f64 * 0.8;
        }
    }

    // Mild preference for reusing existing bins as stream grows.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize "unusable" small gaps: residuals that few future items can use.
    // Items are >= 1, but small residuals (< ~10-15) are hard to reuse.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 4.0;
    }

    // Penalize moderate leftovers less if they can host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Dead space relative to bin: large waste fraction penalized.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 20.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (avoid opening new bins); with few open bins, new bins are cheaper.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when many bins already fit poorly.
        score = bin_capacity as f64 + 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        } else if mean_residual > 0.0 && item_size as f64 > mean_residual {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidation.
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits after this placement: strong reward
        score -= (next_item_size as f64) * 0.5;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportional to wasted lookahead potential
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
    }

    // Dead-space penalty: residual too small to ever hold a plausible item
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0;
    }

    // Prefer bins tighter than the fleet average (best-fit flavor)
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: be slightly conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer small post_residual relative to capacity.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever be useful
    // (smaller than the minimum conceivable item size).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further waste: mild reward scaled by fit quality
            let nx_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nx_fit;
        } else {
            // next item cannot use the residual: penalize proportionally to leftover
            score += 0.15 * (post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: be pickier about poor fits.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidating into existing space rather than spreading.
    if open_bins_count > 0 {
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        // favor bins that are fuller than average
        score -= 8.0 * (fill_ratio - mean_fill);
    }

    // Time horizon: early in the stream, be conservative (mild penalty for
    // opening new bins is implicit); late in the stream, prioritize closing
    // out bins cleanly (larger residual penalty shrinks).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate handling: an empty bin has full residual; make it
    // attractive only when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        // neutral base; let item size modulate: large items prefer fresh bins
        score += 5.0 - 0.05 * item_size as f64;
        // if current item nearly fills a bin, fresh bin is excellent
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // non-linear polynomial coupling with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 25.0 * poly * (0.5 + progress);
    // penalize large post_residual as stream progresses (wasted space)
    score += 15.0 * norm_pr * norm_pr * progress;
    // reward tight fits (small post_residual) especially early
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 8.0 * (1.0 - diff / cap) * (1.0 - progress);
        if pr < nxt {
            score += 6.0 * (1.0 - progress);
        }
    }
    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }
    // avoid fragmenting many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;
    // mean residual alignment
    score += 0.3 * (pr - mean_residual).abs() / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes modulo 10 and via integer-division thirds of capacity.
    let pr = post_residual;
    let mod10 = (pr % 10) as f64;
    let third_class = (pr * 3 / bin_capacity) as f64; // 0..=2 integer division class

    // Penalize awkward remainders (dead space that few item sizes can use).
    score += mod10 * 0.8;

    // Reward leaving space in the "large-item usable" band (20..50).
    if pr >= 20 && pr <= 50 {
        score -= 12.0;
    } else if pr > 60 {
        score += (pr as f64 - 60.0) * 0.5;
    }

    // Third-class coupling: middle-class leftovers are least useful.
    if third_class == 1.0 {
        score += 6.0;
    } else if third_class == 0.0 && pr > 0 {
        score -= 4.0; // tiny leftover is fine, bin nearly full
    }

    // Lookahead coupling: if next item fits exactly into the post residual
    // (same harmonic class), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty for stranding space
            score += 3.0;
        }
        // modulo harmony between next item and post residual
        if pr > 0 && (next_item_size % 10) == (pr % 10) && next_item_size <= pr {
            score -= 5.0;
        }
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: fresh empty bin should only win when the
    // item is large relative to capacity or few bins are open.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bin by default; discount when item is big or stream early
        score += 18.0 - 30.0 * frac - 8.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Mild pressure to consolidate across many open bins.
    score += (open_bins_count as f64) * 0.05;
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: tight fit reward (lower post_residual is better).
    score += post_residual as f64;

    // Strict dead-space avoidance: post_residuals in the "unusable" zone
    // (small gaps that few items can fill) get a heavy extra penalty.
    if post_residual > 0 {
        let dead_zone_low = 1.0;
        let dead_zone_high = 12.0;
        if (post_residual as f64) >= dead_zone_low && (post_residual as f64) <= dead_zone_high {
            score += (dead_zone_high - post_residual as f64 + 1.0) * 8.0;
        }
        // Perfect fit is heavily rewarded.
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward using bins whose residual is close to item_size (good packing ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from many open bins: prefer filling existing bins rather
    // than spreading out; penalize placements that leave bins fragmented.
    score += open_bins_count as f64 * 1.5;

    // If this bin's residual is far below mean residual, it's a "junk" bin:
    // prefer dumping items into it to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; slightly penalize leaving large gaps
            // that neither this item nor the next one can use efficiently.
            score += (post_residual as f64) * 0.3;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a decent fit. Make the empty bin moderately
    // attractive by default, but less attractive than tight fits.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; subtract a little so it beats terrible fits,
        // but add pressure so tight fits in open bins win.
        score += 10.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is required
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh bin is good if next item is large
            if next_item_size >= 50 {
                score -= 8.0;
            }
        }
    }

    // Mild stream-position adaptation: late in the stream, be more
    // conservative (favor existing bins) since fewer items remain to
    // fill leftover space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: exact-fit reward — dead space is the enemy.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well (chained packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can also be placed here afterwards.
            score -= 60.0 - gap * 0.5;
        } else {
            // Next item would not fit; penalize proportionally to overshoot.
            score += gap * 0.8;
        }
        // Perfect chain: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    // (best-fit flavor), penalize bins with unusually large residual
    // relative to the fleet.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when this bin would
    // otherwise leave large dead space or the fit is very loose.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score += 70.0;
        // But if the item fits poorly everywhere, a fresh bin gives a
        // clean residual equal to capacity - item_size; reward exact
        // large fits slightly.
        if post_residual <= 20 {
            score -= 90.0;
        }
    }

    // Late in the stream, prefer closing bins out (reduce open count pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for the smallest plausible item are worthless.
    if post_residual < 10 {
        score -= 15.0; // perfect closure bonus
    } else if post_residual < 20 {
        score -= 6.0;
    } else if post_residual > 60 {
        score += 8.0; // leaving a huge hole when a smaller-fit bin may exist
    }

    // Lookahead coupling: reward if the next item fits into the post residual (chaining),
    // penalize if the next item is large and would need a fresh bin anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            let wasted_chain = (next_item_size - post_residual) as f64;
            score += 0.05 * wasted_chain;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless it's a terrible fit).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins would leave bad residuals, or when many bins are already open and mean
    // residual is large (fragmented state).
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 40.0;
        // If open bins are fragmented (high mean residual), a new bin is more acceptable.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Early in the stream, keep bins consolidated; later, allow spreading.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // Large items pair well with fresh bins.
        if item_size >= 60 { score -= 15.0; }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // fresh bin can host a perfect pair
        }
    }

    // Mild penalty for proliferating open bins when this bin is already sparse.
    if open_bins_count > 4 && post_residual > 50 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), slightly super-linear
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Smooth non-linear coupling with stream progress: prefer tight fits later in the stream
    let progress_coupling = (1.0 - progress) * (norm_pr * 12.0) - progress * (norm_pr * norm_pr * 30.0);
    score += progress_coupling;

    // Reward using nearly-full bins smoothly (small post residual)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 15.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Deviation from mean residual: prefer bins whose residual differs from mean (keep diversity of sizes)
    let mean_dev = (pr - mean_residual) / cap;
    score -= mean_dev * mean_dev * 8.0;

    // Lookahead: penalize leaving residual that fits next item too loosely (wasted slack)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = pr - ni;
        if slack >= 0.0 {
            let ns = slack / cap;
            score += ns * ns * 20.0;
        } else {
            score += 5.0; // next item won't fit here either
        }
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 6.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual (integer division into capacity/10 buckets)
    let class = post_residual / 10;
    score += (class as f64).powi(2) * 0.8;

    // Reward near-perfect fits: post_residual in the smallest harmonic class
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Modulo coupling: post_residual divisible by common item sizes is reusable
    let pr = post_residual;
    if pr > 0 {
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                score -= 6.0;
            }
        }
    }

    // Lookahead: penalize residuals that cannot fit the next item, reward exact match
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            if post_residual == next_item_size {
                score -= 30.0; // perfect two-item closure
            } else {
                score -= (next_item_size as f64) * 0.25;
            }
        } else {
            score += 18.0; // dead space for the lookahead item
        }
        // harmonic class of next item size vs post residual
        let nc = next_item_size / 10;
        let pc = pr / 10;
        if nc == pc && next_item_size > 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // opening early in stream is cheaper (more future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins with residual below mean (compact bins), penalize scattered large residuals
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.3;

    // Many open bins: prefer filling existing ones tighter
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size) are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable dead space: worst outcome, waste of capacity.
            score += 200.0;
        } else {
            // Usable residual: reward tight fits proportionally.
            let fit_fraction = post_residual as f64 / bin_capacity as f64;
            score -= 40.0 * (1.0 - fit_fraction);
        }
    } else {
        // Perfect fill: strong reward.
        score -= 120.0;
    }

    // Extra penalty if the dead space cannot accommodate the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 30.0;
    }
    // Reward if the residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin for this item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    }

    // Mild preference toward bins below mean residual (tighter bins).
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward leaving exactly the space the next item needs.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Residual big enough for the next item but not exact: mild penalty
            // proportional to the leftover after the follow-up placement.
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Residual too small for the next item: dead-space penalty scaled
            // by how far the next item is from fitting.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.05;
        }
    }

    // Compare against mean residual: bins with unusually small residual are
    // good consolidation targets; bins with large residual should stay open.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize creating tiny unusable slivers (below minimum item size 1..100
    // heuristic: slivers under ~10 are dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // New-bin candidate: neutral-ish score that competes with bad fits.
    // Encourage opening a new bin when many bins are open and residual
    // fragmentation is high; slightly discourage it early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = bin_capacity as f64 * 0.75;
        nb += open_bins_count as f64 * 2.0;
        nb -= progress * 50.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            nb -= 20.0; // fresh bin fits anything next round
        }
        // If this is the only fitting bin, opening new is wasteful.
        if fitting_bins_count == 1 {
            nb += 400.0;
        }
        score = score.max(nb);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight_fit * tight_fit;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual < next_item_size) as i32 as f64
        } else {
            0.5
        };
        score += 10.0 * dead * (post_residual as f64 / 20.0).min(2.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    } else if fitting_bins_count > 1 {
        // mild competition normalization
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: reward leaving room for the next item in this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: opening a new bin costs; only attractive
    // when current bin fit is poor (large post_residual waste) or few fit options.
    if bin_residual == bin_capacity {
        let open_cost = 30.0 + 0.5 * open_bins_count as f64;
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = 1 - item/C for new bin
        score = open_cost + 40.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: must open
        }
        // Early in stream, opening bins is cheaper (builds pool for future items).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is low (all bins fullish), opening is better.
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Global pressure: many open bins with slack -> prefer consolidating into
    // bins with residual near mean (avoid fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    // Late in stream: be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tight_fit;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Tight fits rewarded: quadratic dead-space penalty
    let tight = (pr / cap).powi(2);
    score += 8.0 * tight * cap * 0.01;

    // Smooth progress coupling: prefer filling existing bins more aggressively later
    score -= 6.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);

    // Last-chance bin gets strong reward
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: reward leaving residual compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.05 * gap;
        if pr >= nx {
            score -= 2.0;
        }
    }

    // Penalize opening new bins when many bins are already open and residual is high
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64 + mean_residual * 0.02 * (1.0 - progress);
    }

    // Mean-residual alignment bonus
    score -= 0.03 * (mean_residual - pr).abs().recip().min(1.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tiny post residual).
    if post_residual <= 5 {
        score -= 18.0;
    }
    score -= (post_residual as f64 / cap).powi(3) * 12.0;

    // Lookahead synergy: reward if the next item can reuse the leftover space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if post_residual > 0 && (next_item_size == 0 || next_item_size > post_residual) {
        // Dead-space penalty: leftover too small for the next item.
        score += 4.0;
        if post_residual < 10 {
            score += 12.0;
        }
    }

    // Harmonic class logic: multiples of 10 leave "clean" residuals that pair
    // well with typical item sizes; odd remainders are penalized proportionally.
    let m = post_residual % 10;
    if m == 0 {
        score -= 4.0;
    } else {
        score += m as f64 * 0.35;
    }

    // New-bin candidate: penalize opening a bin when existing bins fit,
    // but allow it when nothing fits or the item is large.
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * fitting_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if item_size >= 60 {
            score -= 8.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the last chance bin before opening a new one: prefer it.
        score -= 10.0;
    }

    // Late-stream consolidation: favor filling bins with large residuals
    // so the tail of the stream doesn't spread across many bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if t > 0.8 {
        score -= mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~10) are essentially wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item (k=2 coupling).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + next_item_size as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // gap cannot host the next item: mild dead-space penalty scaled by gap size
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than opening new ones (new-bin candidate gets residual = capacity,
    // so this also penalizes it relative to good fits).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Prefer bins whose residual is below the mean residual (tighter bins first),
    // which preserves large-residual bins for larger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 2.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is large
    // relative to every open residual (handled implicitly, but tilt slightly).
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward when next item fills post_residual.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if (post_residual as i64 - next_item_size as i64) >= 0 {
            // Next item could fit exactly: reward near-exact matches.
            score -= 15.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        } else {
            // Next item cannot fit: penalize leftover that becomes dead space,
            // scaled by how badly it misses.
            score += 0.5 * diff;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Penalize creating unusable tiny residuals (< 10) that waste space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when few fitting bins exist or
    // item is large and no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count > 0 {
            (post_residual as f64) // post_residual == capacity - item for empty bin
        } else {
            0.0
        };
        let base = 45.0
            + 0.5 * open_bins_count as f64
            + poor_fit
            + 10.0 * (1.0 - (step_index as f64 / (total_items as f64).max(1.0)));
        if fitting_bins_count > 0 {
            // discourage opening a new bin when one exists that fits
            score = base + 10.0;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;
    }

    // Penalize dead space: residuals too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= (1.0 - slack as f64 / bin_capacity as f64) * 12.0;
        } else if next_item_size <= bin_residual && next_item_size > item_size {
            // Next item would have fit here now but won't after placement — mild penalty.
            score += 6.0;
        }
    }

    // New-bin candidate handling: only open a new bin when current bins are crowded
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.1;
        if fitting_bins_count > 0 && !crowded {
            score += 40.0 + 15.0 * (1.0 - progress);
        } else {
            score -= 8.0;
        }
    }

    // Mild preference for filling bins that are already fairly full (consolidation).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Slight global pressure: many open bins -> prefer consolidation into existing bins.
    score += open_bins_count as f64 * 0.15;

    // Small tie-break noise-free coupling with mean residual: prefer bins below mean residual
    // (keeps larger residuals available for larger future items).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * tightness * tightness);

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    score += 30.0 * progress * (pr / cap) * (pr / cap);

    // Reward filling a bin almost exactly (smooth gaussian-like term)
    score -= 40.0 * (-((pr / 12.0) * (pr / 12.0))).exp();

    // Lookahead: penalize if post_residual too small for next item, reward if it fits
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 15.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 10.0 * ((n - pr) / cap) * ((n - pr) / cap) * 50.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate emptier bins usage)
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let residual_before = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual_before.max(1.0);
    score -= 14.0 * fill_ratio * fill_ratio;

    // Penalize dead space: post_residual that cannot hold typical future items
    // (harmonic classes via integer division on post_residual).
    let pr = post_residual;
    if pr > 0 {
        // Class of unusable slivers: post_residual < smallest plausible item
        if pr < 10 {
            score += 25.0;
        } else {
            // Quantize post_residual into harmonic classes of capacity/8
            let class_size = bin_capacity / 8;
            let class = pr / class_size;
            let waste_in_class = pr - class * class_size;
            score += 0.9 * waste_in_class as f64;
            // Very small classes are nearly dead space
            if class == 0 {
                score += 12.0;
            }
        }
    }

    // New-bin candidate handling: opening a new bin is expensive; only attractive
    // if all existing fits are poor (many bins, high mean residual mismatch).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let new_bin_penalty = 55.0
            - 0.6 * open_bins_count as f64
            - (mean_residual / bin_capacity as f64) * 30.0;
        score += new_bin_penalty.max(-10.0);
        // If this is the only fitting option, opening a new bin is fine.
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strong reward to avoid opening a new bin.
        score -= 30.0;
    }

    // Lookahead coupling: reward leaving post_residual that fits the next item
    // exactly; penalize leaving space that nearly-but-not-quite fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            let next_fill = nxt / pr as f64;
            score -= 10.0 * next_fill;
            // Perfect pairing: post_residual == next_item_size
            if (pr as f64 - nxt).abs() < 0.5 {
                score -= 18.0;
            }
        } else {
            // Residual too small for the next item: mild penalty scaled by closeness
            let miss = (nxt - pr as f64) / nxt;
            score += 8.0 * (1.0 - miss);
        }
    }

    // Harmonic modulo threshold on post_residual: multiples of 10 are reusable.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Slight preference to keep many bins consolidating as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (open_bins_count as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit a future
    // item (below the minimum item size) are pure waste -> heavy penalty.
    if post_residual < 1 {
        score += 1000.0;
    } else if post_residual < 10 {
        // Unusable micro-gap: penalize proportionally to how close it is to zero.
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual < next_item_size as f64 {
        // Gap cannot fit the known next item: likely dead space.
        score += 15.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    score -= 40.0 * (item_size as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        score += 30.0 - 20.0 * pressure.min(1.5);
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

    // Late in the stream, waste matters more (no time to recover gaps).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if this bin's post-residual fits the next item exactly, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item can also fit here: strong reward scaled by tightness.
            score -= 60.0 * (1.0 - diff / bin_capacity as f64);
        }
        // Penalize residuals that are just below next item size (dead space for lookahead).
        if (post_residual as f64) < nxt && post_residual > 0 {
            score += 0.5 * diff;
        }
    }

    // Prefer bins with residuals below mean (compact them first).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0 && (post_residual as f64) <= next_item_size as f64;
        if fitting_bins_count > 0 && !tight_fit_exists {
            score += 25.0;
        } else if fitting_bins_count > 0 {
            score += 60.0;
        }
        // Late in stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual amplifies wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize creating dead space that no known item size (10..80) could use,
    // unless it's a fresh bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin && post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.5;
        } else {
            // Next item won't fit here; slight penalty for blocking large residual use.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // New-bin candidate: penalize opening new bins proportionally to how many
    // open bins exist and how much mean residual is available (encourage consolidation).
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let consolidation_pressure = mean_residual / (bin_capacity as f64);
        score += 60.0 + 40.0 * progress + 50.0 * consolidation_pressure + (open_bins_count as f64).sqrt() * 5.0;
        // If item is large relative to capacity, a new bin is more acceptable.
        score -= (item_size as f64) * 0.3;
        // If no other bin truly fits (this is the only candidate), reduce penalty.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }
    }

    // Mild time-horizon term: early in the stream, be more conservative with
    // residual waste; late in the stream, just get items packed.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: squared dead space (heavily penalizes large leftovers, smooth non-linear).
    let mut score = (pr * pr) / cap;

    // Non-linear coupling of post_residual with stream progress:
    // early on, waste matters less; late, tight packing is critical.
    let prog_coupling = (pr / cap) * (0.5 + 2.0 * progress * progress);
    score += prog_coupling * cap * 0.35;

    // Smooth saturation of residual relative to mean residual across open bins:
    // leaving more than the mean residual is increasingly bad (dead-space divergence).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * (1.0 + dev * dev) * 12.0;

    // Lookahead coupling: if next item fits into post_residual, reward strongly (smooth).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = (pr - nxt).max(0.0) / cap;
        let tight = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= fit * 30.0 * (0.4 + 0.6 * progress) + tight * 8.0;
        // If next item won't fit here, mild penalty proportional to wasted opportunity.
        if nxt > pr {
            score += (nxt - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate (empty bin): penalize opening a new bin, but relax the
    // penalty when the item fits badly everywhere (large post_residual elsewhere
    // is captured by base terms). Smooth penalty decaying with progress.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score += (60.0 - 25.0 * progress) * openness;
    }

    // Mild reward for many open bins (consolidation preference), smooth.
    score -= (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes capture typical item sizes (multiples of 10)
    let pr = post_residual as i64;
    let cls = pr % 10;
    // Penalize residuals that are "almost but not quite" reusable (dead space)
    if pr > 0 && pr < 10 {
        score += 25.0; // tiny unusable sliver
    } else if cls == 0 {
        score -= 12.0; // perfectly aligned residual, highly reusable
    } else if cls <= 3 {
        score += 6.0;  // awkward small remainder
    }

    // Integer-division thresholds on post_residual: which next-item classes it can host
    if next_item_size > 0 {
        let n = next_item_size as i64;
        if pr >= n {
            score -= 15.0; // can host the lookahead item: strong reward
            // bonus if residual is close to next item (tight fit)
            let slack = (pr - n) as f64;
            score -= (10.0 - slack.min(10.0)) * 0.8;
        } else {
            score += 8.0; // lookahead cannot fit here
        }
        // harmonic coupling: (post_residual / next_item_size) integer division
        if n > 0 {
            let k = pr / n;
            score -= (k as f64).min(3.0) * 4.0; // more future placements possible
        }
    } else {
        // last item: just minimize waste
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // but if mean residual is tiny (all bins nearly full), opening is fine
        score -= mean_residual.clamp(0.0, 40.0) * 0.3;
    }

    // Tight fits are excellent
    if post_residual == 0 {
        score -= 20.0;
    }

    // Progress-scaled pressure to consolidate late in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< ~35% capacity) are hard to fill.
    let dead_threshold = 0.35 * bin_capacity as f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        let severity = (dead_threshold - pr) / dead_threshold; // 0..1, worst near zero
        score += 12.0 * severity * severity;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using a bin whose residual is nearly exhausted (tight packing).
    let fill_fraction = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_fraction * fill_fraction;

    // Last-chance bonus: only one fitting bin, avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (post_residual - next_item_size) as f64 / 100.0;
        } else {
            // next item won't fit here: penalize leaving gaps it nearly fits
            let miss = (next_item_size - post_residual) as f64;
            if miss < 20.0 {
                score += 4.0 * (1.0 - miss / 20.0);
            }
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones
    // (penalize new-bin candidate relatively more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * pressure; // new bin penalty
    } else {
        score -= 2.0 * pressure;
    }

    // Prefer bins with below-average residual (denser bins) when many bins open.
    let dev = mean_residual - pr;
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: small post_residual strongly favored (non-linear)
    score -= 40.0 * (-post_residual as f64 / 20.0).exp();

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover slack after the pair
            let pair_leftover = post_residual - next_item_size;
            score -= 30.0 - 0.5 * pair_leftover as f64;
        } else {
            // next item won't fit here: penalize wasted lookahead potential
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: only tightness matters
        score -= 20.0;
    }

    // Relative to mean residual: bins with residual below mean are "sparser waste" candidates
    let rel = bin_residual as f64 - mean_residual;
    score += 0.4 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless it promises a very tight future pair
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress;
        if next_item_size > 0 && post_residual <= 15 {
            score -= 50.0;
        }
    }

    // Mild pressure to close bins early when many are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Strongly favor last-chance bins to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 10.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a residual just below the next item size (wasted sliver).
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 8.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 70.0 + 30.0 * (1.0 - progress);
        // Cheaper to open a bin if open bins are already crowded with small residuals.
        score -= 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // If the item fits many bins, opening a new one is wasteful.
        score += 6.0 * fitting_bins_count as f64;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= 0.2 * next_item_size as f64;
        }
        // Perfect-fit potential: a fresh bin with a large item is fine.
        if item_size >= 80 {
            score -= 25.0;
        }
    } else {
        // Mild preference for bins with larger residuals (fill emptier bins first)
        // but only when several bins can fit the item.
        if fitting_bins_count > 2 {
            score += 0.05 * (bin_capacity as f64 - bin_residual as f64);
        }
        // Penalize leaving tiny unusable residuals.
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Stream-progress coupling: penalize residual more aggressively later in the stream
    let prog_coupling = 1.0 + 0.5 * progress * (1.0 - progress) * 4.0; // smooth bump mid-stream
    score *= prog_coupling;

    // Lookahead: reward residual that can fit the next item (smooth affinity)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let tight = (n / cap) * (1.0 - (pr - n) / cap);
            score -= 18.0 * tight * (0.5 + progress);
        } else {
            // smooth penalty for residual that cannot host the next item
            let gap = (n - pr) / cap;
            score += 6.0 * gap * (1.0 + gap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.6 + 0.4 * progress);
    } else {
        // slight preference for bins with more competition when fits are abundant
        score += 2.0 / (1.0 + fitting_bins_count as f64);
    }

    // Penalize bins whose residual deviates strongly from mean (fragmentation control)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: make it moderately unattractive unless residual is very tight
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
        // opening a new bin is fine if item is large relative to capacity
        score -= 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (usable by typical items) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    // Reward tight fits strongly.
    score -= 40.0 * (1.0 - frac * frac);

    // Harmonic classes via modulo: post_residual mod small moduli.
    // Leftovers that are exact multiples of common item sizes are reusable.
    let m16 = (pr % 16) as f64;
    let m10 = (pr % 10) as f64;
    score -= 6.0 * (1.0 - m16 / 16.0);          // near-multiple-of-16 leftover is good
    score -= 4.0 * (1.0 - m10 / 10.0);          // near-multiple-of-10 leftover is good
    if pr % 20 == 0 { score -= 8.0; }
    if pr % 25 == 0 { score -= 6.0; }
    if pr == 0 { score -= 50.0; }               // perfect fill

    // Penalize dead space: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 { score += 25.0; }

    // Coupling with lookahead item: if next item fits exactly into post_residual,
    // strongly reward; if next item nearly fits, small reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr as f64);
        } else {
            // leftover cannot host the next item: mild penalty scaled by waste
            score += 5.0 * (1.0 - pr as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity or no open bin is tight; penalize opening bins early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if item_size > bin_capacity / 2 { score -= 25.0; }
        if fitting_bins_count == 0 { score -= 40.0; }
        if open_bins_count == 0 { score -= 30.0; }
        // discourage new bin if mean residual across open bins is large
        score += 0.3 * mean_residual;
    }

    // Mild preference to fill bins with low mean residual (consolidation).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Small penalty for very large leftovers that fragment the bin.
    if frac > 0.7 && pr > 0 { score += 5.0 * frac; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny sliver gaps are almost unusable (items >= 1 though, so soften)
        score += (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strongly reward zero residual.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward residual that can still host typical items (>= 10 in classic streams, small here).
    if post_residual >= 10 {
        score -= 12.0;
    } else if post_residual > 0 {
        score -= 2.0; // partial credit for any leftover usefulness
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Dead-space penalty relative to capacity: unusable fraction of the bin.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Open-bin pressure: prefer spreading when many bins are open, but
    // discourage opening new bins when open count is low.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with open bins and mean residual.
        score += 15.0 + 2.5 * open_bins_count as f64 + 0.3 * mean_residual;
        // If only this bin can fit the item, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Late in the stream, avoid proliferation of nearly-empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strong reward to use it instead of opening a new bin.
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 8.0;
        }
    }

    // Mild preference for bins with below-mean residual (consolidate fuller bins).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual is already favored by base term).

    // Aggressive 2-step lookahead: strongly reward when the next item exactly
    // fills the post residual, or nearly fills it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how close next item comes to filling remainder
            score -= 40.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot use the remainder: penalize dead space
            let dead = post_residual as f64;
            score += 0.15 * dead;
        }
    }

    // Relative to mean residual: prefer bins whose residual is tighter than average
    let resid = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (resid - mean_residual) / mean_residual;
        score += 10.0 * rel; // larger-than-average residual penalized
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits very poorly in existing bins (this call is the empty-bin call).
    if bin_residual == bin_capacity {
        // base score equals capacity (worst); grant a bonus only if item is large
        // relative to capacity, making fragmentation likely elsewhere.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 35.0 * (frac - 0.6) / 0.4;
        }
        // discourage opening new bins when plenty of slack exists in open bins
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins fully
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for proliferating open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that is too small for the smallest plausible future item
    if post_residual > 0 && post_residual < 25 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 35.0; // next item fits exactly afterwards
        } else if gap > 0 && gap < 20 {
            score -= 15.0; // next item fits reasonably
        } else if gap < 0 && (-gap) < 15 {
            score += 12.0; // next item just barely won't fit: wasted capacity
        }
    }

    // Global state: many open bins -> prefer consolidating into existing bins
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.8 * open_pressure;

    // Mean residual coupling: if open bins are already full-ish, opening new bin is fine
    if (mean_residual < 20.0) && bin_residual == bin_capacity {
        score -= 10.0;
    }

    // Time horizon: late in the stream, be conservative (avoid new bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress); // early: new bins cheap-ish
        score -= 10.0 * progress;         // late: discourage new bins
    } else {
        score -= 6.0 * progress;          // late: favor filling existing bins
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: prefer minimal post_residual, with a smooth non-linear penalty
    // for both very small and very large leftover space (dead-space avoidance).
    let mut score = pr;
    score += 20.0 * norm_post * (1.0 - norm_post) * (norm_post - 0.5).abs() * 2.0;

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, tighten fits more aggressively.
    let coupling = (norm_post - 0.35) * (norm_post - 0.35) * (1.0 + 3.0 * progress);
    score += 30.0 * coupling * cap * 0.01;

    // Lookahead: reward bins whose residual after placement pairs well with the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
        // Perfect chain fit bonus (post_residual exactly fits next item)
        if pr == n {
            score -= 15.0;
        }
        // If next item fits current residual before placement, slight penalty for wasting it
        if bin_residual as f64 >= n + item_size as f64 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more strongly late in the stream
    // (consolidation matters more as we approach the end), but relieve penalty
    // when many bins are open and mean residual is small (fragmentation).
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).max(0.0).min(1.0);
        let new_bin_penalty = 15.0 + 20.0 * progress - 10.0 * frag;
        score += new_bin_penalty.max(5.0);
    }

    // Slight preference for bins whose residual is near the mean (balance load)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in low residue classes.
    let pr = post_residual;
    if pr > 0 {
        let class = match pr {
            0..=5 => 0.0,
            6..=15 => 0.5,
            16..=30 => 1.0,
            _ => 1.5,
        };
        score += class * 6.0;

        // Modulo structure: residuals that are "nice" (multiples of 10 / 25) are more reusable.
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 20 == 0 { score -= 3.0; }
    } else {
        // Perfect fit is heavily rewarded.
        score -= 40.0;
    }

    // Tight fit reward relative to capacity fractions.
    let tightness = (bin_residual - item_size) as f64 / cap;
    score -= (1.0 - tightness) * 15.0;

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // Extra reward for near-exact pairing (harmonic coupling).
            let gap = pr - next_item_size;
            if gap <= 10 { score -= 8.0; }
        } else {
            // Penalize blocking next item only mildly.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins with less residual among many candidates.
        score += (bin_residual as f64 - item_size as f64) * 0.1;
    }

    // New-bin candidate: penalize opening a new bin unless everything else is bad.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if progress < 0.15 && open_bins_count < 4 {
            score -= 30.0;
        }
        // If next item is large, a fresh bin is attractive.
        if next_item_size > 60 { score -= 10.0; }
    }

    // Prefer bins whose residual deviates favorably from the mean (pack fuller bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to residual (low waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) as f64;
        // Base cost of opening a new bin, softened if current bins are crowded.
        score += 30.0 - 6.0 * open_bins_count as f64 + 0.15 * mean_residual;
        // If the next item would fit in this fresh bin's residual, slight bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size > 0 {
            score += 5.0;
        }
        let _ = poor_fit;
    }

    // Lookahead: penalize leaving a residual that neither wastes nor helps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // gap is reusable by next item
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Mild stream-phase adjustment: early on, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 200.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 300.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large residuals slightly less
            score += 20.0;
        }
    }

    // Prefer bins with residual below mean (tight bins) when fit is decent
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 50.0 * tightness;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        let good_fit = post_residual == 0 || (next_item_size > 0 && next_item_size == post_residual);
        if good_fit {
            score -= 400.0;
        } else {
            score += 400.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Late in stream: prefer tighter packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 100.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor near-exact fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Lookahead: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 25.0 * chain_quality;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving dead space the next item cannot use.
        if post_residual < next_item_size {
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many options: mildly penalize this bin to encourage comparing fits.
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented
    // (large mean residual spread vs. this item) or few bins can fit the item.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = 1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
        let early = 1.0 - (step_index as f64 / total_items.max(1) as f64);
        score += 55.0 - 30.0 * pressure - 20.0 * fragmentation / bin_capacity as f64 - 10.0 * early;
    } else {
        // Existing bin: reward bins that are already relatively full.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 15.0 * fill;
        // Penalize opening pressure mismatch: if mean residual is huge, prefer consolidating.
        score += 5.0 * (mean_residual / bin_capacity as f64 - fill).abs();
    }

    // Late-stream consolidation: as stream ends, avoid leaving many partially-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 {
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer minimal post-residual, with smooth non-linear penalty
    let mut score = pr;

    // Non-linear coupling: waste grows super-linearly for small residuals
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Lookahead: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let slack = pr - next_item_size as f64;
        if slack < 0.0 {
            score += 4.0 * (-slack / cap);
        } else {
            score -= 2.0 * (slack / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more so mid-stream or when fits exist
    if bin_residual == bin_capacity {
        let open_penalty = (open_bins_count as f64).ln1p();
        score += 6.0 + 4.0 * open_penalty * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // A new bin is attractive only if item is large relative to capacity
        score -= 10.0 * (item_size as f64 / cap) * (item_size as f64 / cap);
    }

    // Mild mean-residual balancing: avoid bins far from the mean residual
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let nx = next_item_size as f64;

    // Perfect fit: strongest reward
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the leftover still serve the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // harmonic class: leftover in a "reusable" class for the next item
            score -= 12.0 + 4.0 * ((pr / next_item_size.max(1)) as f64).min(2.0);
        } else {
            // dead space relative to lookahead: penalize proportionally
            score += 10.0 + 20.0 * (nx - pr as f64) / cap;
        }
    }

    // Integer-division thresholds on post_residual:
    // residuals below 10 are nearly unusable (min item size ~10 in classic streams)
    if pr > 0 && pr < 10 {
        score += 9.0; // tiny dead-space penalty
    } else if pr >= 10 && pr < 25 {
        score -= 2.0; // marginal but reusable class
    } else if pr >= 25 && pr < 50 {
        score -= 5.0; // good reusable class
    } else if pr >= 50 {
        score -= 1.0; // large leftover: half-empty bin, mild bonus
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Fragmentation pressure: bins already below mean residual are more fragmented;
    // prefer spreading into bins with more room than average.
    if (bin_residual as f64) < mean_residual - 5.0 {
        score += 4.0;
    } else if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 2.0;
    }

    // Stream progression: late in the stream, consolidation matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * progress;

    // New-bin candidate baseline: only chosen when all open fits score worse.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative at all: opening is fine
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin perfectly accommodates the lookahead
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are unusable dead space.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Mid-range gaps (11..=25) are only usable for small items; penalize if next item can't use them.
    if post_residual >= 11 && post_residual <= 25 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += 12.0;
        } else {
            score -= 8.0; // next item plugs the gap: reward
        }
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and encourage closing out existing ones (tight fills).
    let ob = open_bins_count as f64;
    score += ob * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (tight fit relative to mean residual).
    score += (bin_residual as f64 - item_size as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate logic: opening a fresh bin is attractive early in the stream
    // or when nothing fits well; make the empty bin's score competitive but not dominant
    // when decent fits exist.
    if bin_residual == bin_capacity {
        // base cost of a new bin, amortized by stream progress
        score = 55.0 + 0.3 * (post_residual as f64);
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // if only this bin can fit, new bin is fine
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead: if placing here leaves exactly the next item's size, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact / tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness relative to capacity: small dead space favored super-linearly.
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score += tightness * tightness * 120.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mildly reward, scaled by leftover slack after next item.
            let slack_after_next = post_residual - next_item_size;
            score -= 150.0 - (slack_after_next as f64) * 0.5;
        } else {
            // Next item cannot use this residual: penalize if residual is small-ish (dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }

        // If next item fits better in this bin than the mean residual suggests, reward.
        if (post_residual as f64) >= (next_item_size as f64)
            && (mean_residual as f64) < (post_residual as f64) {
            score -= 30.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual (already well packed),
    // which concentrates waste into few bins.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.6;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // gives a decent fit (post_residual large relative to capacity) or many bins are open.
    if bin_residual == bin_capacity {
        // Brand-new bin: base penalty so it loses to any reasonable existing fit.
        score = bin_capacity as f64 * 1.5;
        // If the item leaves a huge hole in every existing bin (item is small), new bin is fine.
        if post_residual as f64 > 0.7 * (bin_capacity as f64) {
            score -= 80.0;
        }
        // If the next item is large and won't fit anywhere typical, opening fresh helps.
        if next_item_size >= 60 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 50.0;
    }

    // Mild preference to fill bins earlier in the stream (close bins sooner).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0;

    // Slight penalty for too many open bins to encourage consolidation.
    score += (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize bins whose residual is far above the mean (they are already "loose").
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap.max(0.0);

    // Lookahead: if the next item fits exactly or well in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            score -= 10.0 * (1.0 - pair_waste as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overflow gap.
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive only when
    // no open bin offers a decent fit (post_residual large) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base_penalty = 30.0 + 15.0 * (1.0 - progress);
        // If item leaves a big hole in an existing bin anyway, new bin becomes competitive.
        let hole_in_existing = (bin_capacity - item_size) as f64;
        score = base_penalty + 0.1 * hole_in_existing - (open_bins_count as f64).min(10.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild time-horizon shaping: early in the stream, be slightly more conservative about
    // fragmenting bins (long stream ahead needs flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * tightness;

    // Small penalty per extra open bin to discourage needless bin proliferation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * cap;
    score += 0.6 * coupling;

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_pr).powi(3) * (20.0 + 40.0 * progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).abs();

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, 10, 20, 25, 50) are more reusable -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modular harmony: post_residual divisible by common item sizes (10, 20, 25, 50)
    let harmonics: [u32; 5] = [10, 20, 25, 40, 50];
    let mut harmony = 0.0;
    for h in harmonics.iter() {
        if post_residual % h == 0 {
            harmony += 1.0;
        }
    }
    score -= harmony * 15.0;

    // Penalize small dead space (1..=9) hard: unusable sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Coupling with lookahead item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snug
            let snug = (next_item_size as f64 / pr.max(1.0)) - 0.5;
            score -= snug * 80.0;
        } else {
            // next item won't fit here: mild penalty scaled by wasted potential
            score += 0.2 * (next_item_size as f64 - pr);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if the item is huge relative to mean residual, opening fresh is fine.
        let mean_r = if mean_residual > 0.0 { mean_residual } else { cap };
        if (item_size as f64) > mean_r * 0.8 {
            score -= 200.0;
        }
    }

    // Tightness reward: prefer bins where the item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Late in the stream, prefer closing bins (low post_residual) more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * pr * 0.3;

    // Prefer bins whose residual is below mean residual (denser bins).
    if (pr < mean_residual) && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Integer-division threshold: post_residual in [10,25] band is sweet spot.
    let band = post_residual / 25;
    score -= match band {
        0 => 20.0,      // 0..24
        1 => 35.0,      // 25..49
        2 => 10.0,      // 50..74
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // to any plausible future item are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Perfect fit or near-perfect: strong reward.
        score -= 200.0;
    } else if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize residuals in the "unusable gap" band (1..10) quadratically.
        let gap = 10u32.saturating_sub(post_residual);
        score += (gap * gap) as f64 * 4.0;
    }

    // Reward tight packing: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably (below mean) so we drain the emptiest space first.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading into new
    // bins; when few bins are open, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; allow it when the fit
        // elsewhere would create large dead space (handled by other terms).
        score = 120.0 + pressure * 2.0;
        // Slight bonus for new bin if lookahead item is large and this item
        // would leave an awkward gap.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 25.0;
        }
    } else {
        // Mild penalty for using an already-open bin when many are open,
        // counterbalanced by fit quality terms above.
        score += pressure * 0.3;
        // Lookahead synergy: if the post-residual exactly accommodates the
        // next item, reward strongly.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 80.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else if next_item_size > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            // Favor chains that leave small chain residual.
            score -= 200.0 / (1.0 + chain_residual as f64);
            if chain_residual == 0 {
                score -= 250.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual of open bins: bins tighter than average are
    // good targets; bins looser than average waste capacity if used.
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // Penalize opening a new bin when open bins exist, more so early in the stream.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 150.0 + 20.0 * open_f * (1.0 - progress);
        // A new bin is acceptable if item is large and nothing fits well.
        if item_size >= 60 && (fitting_bins_count == 0 || post_residual as f64 > 0.4 * bin_capacity as f64) {
            score -= 100.0;
        }
    }

    // Small late-stream penalty for leaving large dead space.
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward placements that leave room for the next item exactly.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // next item fills this bin perfectly
        } else if gap > 0 && gap < 10 {
            score -= 12.0; // next item fits snugly afterwards
        } else if gap < 0 && (-gap) < 10 {
            score += 10.0; // next item barely misses: bad dead space
        }
    }

    // New-bin candidate: only prefer a fresh bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when it beats alternatives.
        score += 15.0;
        // More attractive to open a new bin late in the stream when many bins
        // are open and mean residual is low (poor global fit quality).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Discourage proliferating bins when few exist and mean residual is high.
        if open_bins_count < 3 || mean_residual > 50.0 {
            score += 25.0;
        }
    }

    // Mild preference for bins already below mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (bins get refilled later).
    // Late in the stream: strongly penalize residual (wasted space matters).
    let prn = pr / cap; // normalized residual in [0,1]
    let tightness = 0.5 + 1.5 * progress; // grows smoothly over the stream
    score += tightness * prn * prn * cap * 0.5;

    // Reward tight fits: subtract a smooth quadratic bonus near zero residual.
    let fit_bonus = (1.0 - prn) * (1.0 - prn);
    score -= 12.0 * fit_bonus;

    // Lookahead: penalize residuals that cannot host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // reward proportionally to how well next item also fits snugly
            let nxt_fit = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - nxt_fit) * (1.0 - nxt_fit);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure toward consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * prn;

    // Penalize bins far from the mean residual (prefer homogeneous fill levels).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap;

    // New-bin candidate: make it moderately attractive only when the fit is bad
    // and stream is early; otherwise discourage wasting fresh capacity.
    if bin_residual == bin_capacity {
        let bad_fit = item_size as f64 / cap;
        score = 10.0 + 40.0 * bad_fit * (1.0 - progress);
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues that pair well with
    // common item sizes (multiples of 10 and small remainders) are rewarded.
    let pr = post_residual;
    let residue_class = (pr % 10) as f64;
    if pr > 0 {
        // Perfect complementarity (residue divisible by 10) gets a bonus.
        if residue_class == 0.0 {
            score -= 4.0;
        } else {
            // Penalize awkward remainders proportionally to how far from a
            // multiple of 10 they land.
            score += residue_class * 0.6;
        }
    }

    // Harmonic tier of post_residual via integer division thresholds.
    if pr == 0 {
        score -= 25.0; // perfect fit: strongly favored
    } else if pr <= 10 {
        score -= 12.0; // nearly full: excellent
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 30 {
        score += 2.0;
    } else if pr <= 50 {
        score += 8.0;
    } else {
        score += 15.0; // wasteful placement
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 6.0; // chains nicely
            // Extra reward when the follow-up leaves another harmonic residue.
            let npr = pr - next_item_size;
            if npr % 10 == 0 { score -= 3.0; }
            if npr == 0 { score -= 4.0; }
        } else {
            score += 3.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, prefer tighter fits.
        score += (fitting_bins_count as f64) * 0.3;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well (poor fit / large item).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else if item_size >= 70 || tightness > 0.7 {
            score -= 8.0; // big item: fresh bin is fine
        } else {
            score += 18.0; // small item: prefer existing bins
        }
    }

    // Mean-residual pressure: if open bins are generally loose, penalize
    // leaving this bin loose too; encourage consolidation.
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Mild late-stream consolidation bias.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64).sqrt() * 0.5;

    // Fractional capacity coupling of the item itself.
    let frac = (item_size as f64 * 100.0 / cap).fract();
    score += frac * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize large leftover space being wasted on a small item when a better fit may exist.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * waste_ratio * waste_ratio;

    // Open bins pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= 3.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item cannot fit in post_residual but post_residual is small, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Stream progression: later in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean (tighter packing).
    score += 2.0 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is good, already covered by base.
    // Aggressive 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact match bonus for the two-step chain
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual that is unusable for the next item but small (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    }

    // Penalize bins far below mean residual (wasteful use of a fuller bin when others are empty-ish)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: prefer it only if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If next item is large, opening fresh bin is more attractive
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild late-stream conservatism: pack tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating small, hard-to-fill dead space (< next item size).
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.5 * (post_residual as f64);
        }
        // Very small residuals are near-wasted capacity.
        if post_residual < 10 {
            score -= 8.0; // but finishing a bin is fine: it's fully used
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: reward if next item fits exactly in post_residual (pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when fits are poor or many bins open.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64 / (bin_capacity as f64)
        } else { 0.0 };
        let penalty = 90.0
            - 40.0 * poor_fit
            - 20.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64))
            - 30.0 * (mean_residual / (bin_capacity as f64));
        score += penalty.max(-20.0);
    }

    // Late in stream: consolidate; early: allow spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post-residual, amplified by progress
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post-residual) with smooth exponential-style shaping
    score -= 12.0 * (-norm_pr * 6.0).exp();

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Coupling with mean residual: penalize bins far from mean (fragmentation)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / (1.0 + progress);

    // Lookahead: reward leaving space that exactly accommodates next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 10.0 * (-gap / 20.0).exp();
        } else {
            score += 0.08 * (nxt - pr);
        }
    }

    // New-bin candidate: mild discount early, penalty later in stream
    if bin_residual == bin_capacity {
        score += 6.0 * progress - 4.0 * (1.0 - progress);
        score += 0.5 * open_bins_count as f64;
    }

    // Smooth polynomial progress coupling on fill ratio
    let fill = 1.0 - norm_pr;
    score -= 8.0 * fill * fill * fill * (1.0 + 2.0 * progress * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 classify "usable" leftover space.
    let post = post_residual;
    let residue = post % 10;
    // Dead-space penalty: residuals that are small but nonzero are worst (unusable slivers).
    if post > 0 && post < 10 {
        score += 25.0; // tiny sliver = wasted capacity
    } else if residue == 0 {
        score -= 8.0; // perfectly divisible leftover: likely reusable by future items
    } else if residue <= 3 {
        score += 6.0; // awkward small remainder
    } else if residue >= 7 {
        score -= 3.0; // large-ish remainder class, more flexible
    }

    // Reward exact fills strongly.
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 12.0; // chain placement possible: great
            // Harmonic bonus if next item divides post_residual evenly (perfect chain)
            if post > 0 && post % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow here; penalize more if post_residual is a sliver.
            if post > 0 && post < 10 {
                score += 10.0;
            }
            score += (next_item_size - post) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is expensive unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score = 100.0 - (item_size as f64) * 0.5;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits, must open
        }
        if post > 0 && post < 10 {
            score += 0.0; // fresh bin, no sliver logic
        }
    }

    // Prefer bins with below-mean residual (tighter packing pressure).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Early stream: be slightly greedy to keep bins tight; late stream: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 range, so anything < ~10 is dead)
    // become quadratic penalties.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Near-full bins are excellent: reward tight packing.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Dead-space zone: residual in (0, item min) is wasted; also penalize
    // residuals that cannot fit the lookahead item if they are small.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 25.0;
    }
    // Reward bins that could still host the next item (keeps chains alive).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // Perfect-fit reward when residual exactly matches the item.
    if bin_residual == item_size {
        score -= 100.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, opening a new one is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate (empty bin): make it attractive only when existing
    // bins would leave bad dead space; otherwise it should lose.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a decent fit, better than a bad one.
        score = bin_capacity as f64 * 0.9 + pressure;
        if post_residual < 10 {
            // empty bin always has huge residual, so this branch won't fire;
            // kept for symmetry with archetype.
        }
        // If the item perfectly fills a fresh bin, that's ideal.
        if item_size == bin_capacity {
            score -= 150.0;
        }
        // If no existing bin fits well (all fits would strand space), the
        // caller compares scores; make new bin moderately appealing when
        // mean residual across open bins is small (bins are nearly full).
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Slight stream-progression tilt: late in the stream, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
    score -= progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * gap;
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            score -= 8.0; // next item can still fit here
        } else {
            score += 6.0; // next item won't fit; dead space risk
        }
    }

    // Relative-to-mean dead-space penalty: residuals far below mean waste space.
    score += 0.25 * (mean_residual - post_residual as f64).abs();

    // Last-chance bonus: strongly prefer the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if item_size <= bin_capacity / 2 {
            score += 20.0; // small items should go into existing bins
        }
    }

    // Tight fits are always good.
    if post_residual < 5 {
        score -= 15.0;
    }

    // Late-stream pressure: consolidate more aggressively as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit bonus: strongly favor placements leaving small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            score -= 0.3 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives exist, to keep options open.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = 1 - item/C
        // Opening a new bin costs ~1 bin; penalize unless item is small (wastes capacity).
        score += 8.0 + 55.0 * (1.0 - fit_quality);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
        // Early in stream, more willing to open bins (future packing flexibility).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins with below-average residual (keep large holes for large items).
    if bin_residual as f64 > mean_residual {
        score += 0.25 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - bin_residual as f64);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Late-stream urgency: fill existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.35 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (pr / cap);
    let mut score = pr;

    // Non-linear coupling: squared tightness scaled by stream progress
    score -= 24.0 * tightness * tightness * (0.5 + progress);

    // Cubic term: strongly reward near-full fills late in the stream
    score -= 18.0 * tightness.powi(3) * (0.3 + 0.7 * progress);

    // Interaction: post residual vs mean residual — prefer bins tighter than average
    let rel = pr - mean_residual;
    score += 0.15 * rel;
    score += 0.05 * rel * rel / cap;

    // Lookahead coupling: penalize residuals too small for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 12.0 * (1.0 - pr / nx.max(1.0)) * (0.5 + progress);
        } else {
            score -= 6.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (0.5 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a fresh bin unless no good fit exists
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 10.0;
        if pr < 20.0 {
            score -= 15.0;
        }
    }

    // Mild penalty for many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "friendly"
    // for future items (multiples of common size classes).
    let pr = post_residual as u32;
    let mut harmony_bonus = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if pr % m == 0 {
            harmony_bonus += 6.0;
        }
    }
    if pr == 0 {
        harmony_bonus += 25.0; // perfect fit
    }
    // Penalize dead space in awkward bands (1..10, 11..19 mod classes)
    if pr > 0 && pr < 10 {
        harmony_bonus -= 8.0;
    }
    score -= harmony_bonus;

    // Tightness reward: how well the item fills the bin.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill * fill;

    // Lookahead coupling: does post_residual accommodate next_item_size?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the final fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins have plenty of room.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Stream progression: become more conservative late in stream.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 5.0 * t * (post_residual as f64 / cap);
    }

    // Small tie-break noise via harmonic phase (deterministic).
    score += ((post_residual as i64 * 31 + step_index as i64) % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 60.0;
    }

    // Penalize wasting a large residual on a small item (poor space utilization).
    let waste_ratio = item_size as f64 / bin_residual as f64;
    score -= waste_ratio * 25.0;

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = (open_bins_count as f64 / (1.0 + total_items as f64).max(1.0)) * 30.0;
    score += pressure;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits the post-residual (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the upcoming item.
        score += 12.0;
    }

    // Deviation from mean residual: bins far below mean residual are tighter fits, reward them.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate handling: slightly penalize opening a new bin unless it is a big item
    // that fits poorly elsewhere.
    if bin_residual == bin_capacity {
        if item_size >= 50 {
            score += 5.0; // mild penalty; existing bins usually preferred
        } else {
            score += 25.0; // small items should go into open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: if next item exactly fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how well it uses leftover
            score -= 0.5 * (next_item_size as f64 / post_residual as f64) * 100.0;
        } else {
            // next item cannot use the leftover: penalize dead space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste.min(100.0);
        }
    }

    // Reward bins tighter than the mean residual (good packing), penalize loose bins
    score += 0.4 * ((post_residual as f64) - mean_residual);

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive if current fit is very poor
    if bin_residual == bin_capacity {
        score += 250.0;
        // but if item is huge relative to capacity, opening fresh is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 200.0;
        }
    }

    // Slight late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * progress * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits, more strongly late in the stream.
    score -= (bin_capacity as f64 - post_residual as f64) * (1.0 + 0.8 * progress);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 8.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if this bin becomes stranded.
        score += 4.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        // Many options: prefer the bin that leaves the most usable space.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global residual balance: avoid bins far from the mean residual unless tight fit.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Early stream: encourage opening new bins when current bins fit poorly.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early and when few bins open.
        let new_bin_cost = 20.0 - 10.0 * (1.0 - progress) - 2.0 * (open_bins_count as f64).min(5.0);
        // Prefer new bin if best existing fit is bad (large post_residual relative to next item).
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            score -= 15.0;
        }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pre = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer small post-residual (tight fit).
    let mut score = post;

    // Smooth non-linear fit-quality term: strongly reward very small leftovers.
    let fit_ratio = post / cap; // 0 = perfect fit
    score -= 30.0 * (1.0 - fit_ratio).powi(6) * (1.0 - fit_ratio);

    // Penalize large dead space with a cubic ramp.
    score += 0.002 * post.powi(3) / cap;

    // Reward filling bins deeply relative to mean residual state.
    let fill_frac = item / cap;
    score -= 25.0 * fill_frac * (1.0 - progress);

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let compat = 1.0 / (1.0 + gap / cap);
        // Reward compatibility; penalize if next item barely misses (wasted tight fit).
        score -= 20.0 * compat * compat;
        if nxt > post {
            score += 8.0 * (nxt - post) / cap; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * (1.0 - progress);
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    // Mean-residual coupling: prefer bins whose residual is near the mean (balanced packing)
    // but only when it yields a tight fit.
    let dev = (pre - mean_residual).abs() / cap;
    score += 10.0 * dev * fit_ratio;

    // New-bin candidate (empty bin): penalize mildly so it's chosen only for poor fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + 0.5 * (1.0 - fit_ratio) * 0.0;
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement (capacity fractions / 10 bands)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / (cap / 10.0)).floor(); // 0..10 harmonic class

    // Dead-space penalty: residuals in awkward middle classes (e.g. 3..7) are hard to fill
    if class >= 3.0 && class <= 6.0 {
        score += 12.0 * (class - 2.0);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Near-perfect fits (small harmonics)
    if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match with next item is excellent
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                score -= 10.0 + (post_residual - next_item_size) as f64;
            }
        } else {
            // next item cannot use this residual: penalize leftover more
            score += 8.0 + post * 0.15;
        }
    }

    // Integer-division thresholds on post_residual vs next_item_size
    let next_chunk = if next_item_size > 0 { post_residual / next_item_size.max(1) } else { 0 };
    if next_chunk >= 2 {
        score -= 5.0 * next_chunk as f64; // residual can host multiple future items
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer filling existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost grows with number of open bins and progress
        score += 40.0 + 10.0 * open_bins_count as f64 + 40.0 * progress;
        // but opening a fresh bin is fine if the item is large and bins are fragmented
        if item_size as f64 > cap * 0.7 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
    } else {
        // mild reward for using bins whose residual is already small (tight packing)
        score -= 0.1 * (cap - bin_residual as f64);
    }

    // Mean-residual divergence: avoid placing into bins far from the mean (keeps class balance)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 range,
    // but treat small gaps < 10 as pure waste) are heavily penalized.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Penalize residuals too small for the lookahead item (likely dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect fit for the next item: strong reward.
        score -= 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no open bin
    // fits well. Base cost for opening a new bin grows with open bin count.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 2.0;
        // But if the current item is huge relative to typical residuals, new bin is fine.
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Mild bonus for bins already below mean residual (consolidating emptier bins).
    if (post_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual == next_item_size is perfect.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for tight match with next item
        score -= 60.0 * (1.0 - diff / bin_capacity as f64).max(0.0).powi(3);
        // Bonus if next item fits exactly after this placement
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer minimal leftover
        score += 10.0;
    }

    // Compare post_residual to mean residual across open bins: keep balance
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else {
            0.0
        };
        score = bin_capacity as f64 + 0.3 * open_bins_count as f64
            - 20.0 * poor_fit / bin_capacity as f64
            + 30.0 * progress;
        if fitting_bins_count <= 2 {
            score -= 15.0; // few alternatives, new bin acceptable
        }
    }

    // Prefer filling tighter bins early
    score += 0.2 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the space.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * fill_ratio * fill_ratio * (item_size as f64);

    // Lookahead: penalize leaving a residual that cannot host the next item,
    // creating dead space; reward residuals that can still accommodate it.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space for the next item: penalize proportionally to its size.
            score += 0.8 * (next_item_size as f64) * (1.0 - (post_residual as f64) / (next_item_size as f64));
        } else if post_residual >= next_item_size && post_residual > 0 {
            // Residual remains useful; mild reward scaled by how snugly next item fits.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 0.5 * snug * (next_item_size as f64);
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bins are crowded or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when genuinely beneficial.
        score += 25.0;
        // Few fitting bins -> this placement is scarce; discourage new bin less.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            score -= 5.0;
        }
        // Crowded state: many open bins with low mean residual -> prefer new bin.
        if open_bins_count > 0 {
            let crowding = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
            score -= 15.0 * crowding;
        }
        // Late in the stream, avoid proliferating bins with little future use.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Penalize leaving residuals that are small but nonzero (hard-to-fill slivers),
    // except when they exactly match common small-item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual == 0 {
        // Perfect fit: big reward.
        score -= 15.0;
    }

    // Mild global balance: prefer bins whose residual is below the mean
    // (concentrate filling into emptier-relative bins) to consolidate space.
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - (pr / cap).powf(1.0 + 2.0 * progress);
    score -= tightness * (2.0 + 6.0 * progress) * (it / cap);

    // Reward near-perfect fits with smooth quadratic term.
    let fit_ratio = it / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio * (1.0 - progress * 0.5);

    // Penalize dead space that is too small for typical future items.
    if pr > 0.0 && next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += gap * (0.5 + progress);
        } else {
            score -= 3.0 * (-gap) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening new bins late.
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty when many bins are open and this one is much above mean residual.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score = cap - 4.0 * progress * openness - (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction buckets.
    // Perfect fits (small residuals) are strongly rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class 0: near-perfect fit (<= 5% of capacity)
    if post_residual * 20 <= bin_capacity {
        score -= 60.0;
    } else if post_residual * 10 <= bin_capacity {
        // Class 1: <= 10% residual
        score -= 25.0;
    } else if post_residual * 5 <= bin_capacity {
        // Class 2: <= 20%
        score -= 5.0;
    } else if post_residual * 2 <= bin_capacity {
        // Class 3: <= 50% — half-open space, moderately usable
        score += 8.0;
    } else {
        // Class 4: > 50% residual, wasteful placement
        score += 30.0;
    }

    // Lookahead coupling: reward if next item fits the post residual well.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack * 10 <= bin_capacity {
            score -= 40.0; // next item would nearly fill this bin
        } else {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward gaps
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize opening new bins mildly.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt();
        // If mean residual across open bins is large, opening new bin is bad
        score += mean_residual * 0.3;
    } else {
        // Slight reward for using existing bins proportional to their tightness
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Progress term: early in stream, be more willing to open bins;
    // late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Modular harmonic penalty on post_residual: residue classes mod 10
    // that are hard to fill (e.g. 1..9 leaving odd gaps) get graded.
    let m = post_residual % 10;
    if m > 0 && m <= 3 {
        score -= 6.0; // small gap, likely unusable anyway but bin is full-ish
    } else if m >= 7 {
        score += 4.0; // awkward mid gap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are pure waste.
    // Zero residual is perfect; residuals below the minimum item size are heavily penalized
    // proportionally to how much usable space was destroyed.
    if post_residual > 0 {
        score += 25.0 * (1.0 - (post_residual as f64) / 100.0);
    } else {
        score -= 10.0; // perfect fill reward
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Penalize leaving a residual that no plausible item can use well:
    // gaps just above small-item sizes are awkward.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 2.0; // next item won't fit here; deprioritize this bin slightly
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open,
    // but allow it when few bins exist (early stream / good fit).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 4.0 * (open_bins_count as f64).sqrt() - 5.0 * progress;
        // Opening a new bin is acceptable if this item would leave a tiny dead gap otherwise.
        if post_residual > 0 && post_residual < 10 {
            score -= 18.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    // Mild preference toward bins with below-average residual (keep large gaps
    // available for large future items).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the residual left behind.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item can still fit here
        } else {
            // dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual is tight relative to the item being placed.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 15.0;

    // Penalize bins with residual far above mean residual (wasteful large holes),
    // reward tighter-than-average bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 20.0 + poor_fit * 30.0 - (open_bins_count as f64) * 2.0;
        // early in stream, opening bins is cheap; late, prefer consolidation
        if total_items > 0 {
            score += (step_index as f64 / total_items as f64) * 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 30.0 * (fit_ratio - 0.85);
    }

    // Penalize leaving dead space that few future items could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 3.0; // awkward mid-range gap
    }

    // Lookahead: reward if next item exactly matches post_residual (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 40.0;
        } else if nxt <= post_residual as f64 {
            score -= 10.0 * (nxt / (post_residual as f64 + 1.0));
        } else {
            score += 4.0; // next item won't fit here anyway; residual likely dead
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Cost of a fresh bin: high when many bins already open and residual is usable.
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 20.0 + 30.0 * pressure;
        // But if mean residual is small (open bins nearly full), new bin is fine.
        score -= 25.0 * (1.0 - (mean_residual / cap)).min(1.0).max(0.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
    }

    // Time horizon: early in the stream, be conservative with new bins (long future to regret waste).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (fit_ratio - 0.5).max(0.0);

    // Prefer bins whose residual is below average (consolidate emptier bins for future items).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.3 + 0.7 * t * t);

    // Tight fit reward: smooth term rewarding small post_residual
    score -= (1.0 - norm_pr).powi(3) * 8.0 * (1.0 - 0.5 * t);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
