    }

    // Crowding penalty: many open bins with high mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap).powi(2);

    // New-bin candidate: penalize mildly so we prefer reusing bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

