    // Harmonic class of post_residual: residue classes modulo 10 / 25.
    // Small residues (< 10) are dead space (min item size 1) -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * (10.0 - post) / 10.0;
    }
    // Residues in [10, 20) can still host small items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Exact-fill reward via integer division thresholds.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual % 10 == 0 {
        // Post residual aligned to harmonic class of 10: highly reusable.
        score -= 8.0;
    } else if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Coupling with lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here regardless; slight penalty scaled by how far off.
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * (over / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but relax as stream progresses (more open bins -> keep consolidation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        // If no open bin fits well, opening is fine: reduce penalty when item is large.
        score -= (item_size as f64) * 0.05;
    }

    // Prefer bins whose residual is close to mean (balance load) slightly.
    score += 0.02 * (post - mean_residual).abs();

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
