    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item is large and mean residual is small (poor fits likely), ease the penalty.
        if mean_residual < item_size as f64 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    score
}

