    // Reward tight fits: post_residual near zero is ideal.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 8.0 * tightness * tightness;

    // Penalize residuals that are small but "dead" — too small for typical items (>= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward residuals that can host the next item, penalize those that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0 * (next_item_size - post_residual.min(next_item_size)) as f64 / 10.0;
        }
        // Bonus if post_residual fits next item almost exactly.
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 && gap <= 5 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be more willing to spread items (favor new bins
    // to build flexibility); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus dynamic penalty depending on progress and load.
        let mut new_bin_score = 55.0 + 40.0 * progress;
        // If many open bins with large mean residual, opening new bin is less attractive.
        new_bin_score += 0.8 * open_bins_count as f64;
        new_bin_score += 0.5 * (mean_residual - (bin_capacity as f64) / 2.0).max(0.0);
        // If no bin can fit (fitting_bins_count == 0 semantics via last chance absent), new bin needed.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        score = new_bin_score.min(score + 30.0);
    } else {
        // Existing bin: slight preference for bins with below-mean residual (tighter bins).
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Perfect fit override.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate moderate residuals; late: punish residual growth quadratically.
    let prn = pr / cap;
    let prog = progress.clamp(0.0, 1.0);
    score += prn * prn * (50.0 + 150.0 * prog) * cap * 0.01;
    score += prn * (1.0 - prn) * 20.0 * (1.0 - prog);

    // Tight fit reward: strongly favor small post_residual, superlinearly.
    if pr == 0.0 {
        score -= 60.0;
    } else if pr <= 10.0 {
        score -= 25.0 - pr as f64;
    }

    // Lookahead: reward leaving space that can still fit the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 10.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 8.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing residuals are large.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).max(1.0);
        let avg_fit = mean_residual.max(0.0);
        let urgency = (avg_fit / cap).powi(2);
        score += 55.0 + 15.0 * (openness.sqrt()) - 70.0 * urgency.min(1.0);
    }

    // Mild penalty for spreading across many bins when residuals are ample.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residues divisible by small numbers
    // (5, 10, 20) are more reusable by typical item sizes.
    let class = if post_residual == 0 { 0 }
        else if post_residual % 10 == 0 { 1 }
        else if post_residual % 5 == 0 { 2 }
        else { 3 };
    let class_reward: [f64; 4] = [60.0, 30.0, 12.0, 0.0];
    score -= class_reward[class as usize];

    // Perfect fit is supreme.
    if post_residual == 0 { score -= 200.0; }

    // Dead-space penalty: small unusable leftovers (below min item size 1
    // can't happen, but tiny leftovers relative to capacity are waste).
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.05 { score += 40.0; }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item fits exactly or into same class.
            score -= 25.0;
            if post_residual % next_item_size.max(1) == 0 { score -= 20.0; }
        } else if next_item_size <= bin_residual {
            // This bin could host both but only if we place current item well.
            score += 5.0;
        }
        // Penalize leaving a residual that is *just barely* too small for next item.
        let gap = post_residual as i64 - next_item_size as i64;
        if gap < 0 && gap > -10 { score += 15.0; }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 10.0 * open_bins_count as f64;
        // Open a fresh bin if current best fit would be very tight/wasteful.
        if post_residual < 10 && fitting_bins_count >= 1 { score -= 15.0; }
        if next_item_size > 0 && next_item_size >= item_size * 2 { score -= 10.0; }
    }

    // Slight pressure to consolidate into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (open_bins_count as f64) * 0.05;

    // Prefer bins with residual close to item size (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Tie-break with mean residual: filling below-average-residual bins
    // balances the pool.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // Strict dead-space avoidance: small leftover gaps are penalized super-linearly.
    // A residual gap is "unusable" if it's below a plausible minimum item footprint.
    let dead_threshold = (item_size.min(bin_capacity / 2)).max(1);
    if post_residual > 0 && post_residual < dead_threshold {
        // Quadratic dead-space penalty scaled by how close to perfectly-full we got.
        let tightness = 1.0 - (post_residual as f64 / dead_threshold as f64);
        score += 30.0 * tightness * tightness;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, this is a
    // chaining opportunity; reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: the leftover is likely dead space for the future.
        score += 8.0;
    }

    // Last-chance bin: if this is the only open bin that fits, filling it avoids
    // opening a new bin — heavily favor using it.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize new-bin opening proportionally.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        // Opening a new bin while other bins could fit is costly.
        if fitting_bins_count > 0 {
            score += 20.0 + 5.0 * open_bins_count as f64;
        }
        // Early in the stream, new bins are cheaper; late in the stream, avoid them.
        score += 10.0 * (1.0 - progress);
    } else {
        // Mild reward for using an existing bin, stronger when many bins are open.
        score -= 3.0 + 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, its
    // space is scarcer — using scarce space now is good.
    let residual_diff = mean_residual - bin_residual as f64;
    score -= 0.3 * residual_diff;

    // Prefer bins whose post-residual stays close to the mean residual
    // (keeps the fleet homogeneous and future-fit).
    let post_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * post_diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if the next item exactly fills the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: small residual waste is better
            score -= 80.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item does not fit: penalize large dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Prefer bins whose residual is below mean residual (tighter packing)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Discourage opening new bins when open bins already fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 60.0 + 0.2 * mean_residual;
    }

    // Early in stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize dead space: residual too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect pair
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty if we leave huge gap
            score += 0.02 * (post_residual as f64 - next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins with high mean residual: discourage fragmenting further,
    // encourage consolidating into existing bins.
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score -= 2.0 * consolidation;
    }

    // New-bin candidate logic: opening a new bin is attractive when the item
    // fits poorly everywhere else or open bins are very full on average.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 / bin_capacity as f64) * 10.0;
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin when existing bins are crowded and fit is bad;
        // penalize new bin when a good fit exists elsewhere.
        score = 25.0 + poor_fit - 30.0 * avg_fullness * (1.0 - progress) + 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0; // room for lookahead in fresh bin
        }
        return score;
    }

    // Time horizon: late in stream, be more conservative (fill bins fully).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight preference for fuller bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual (tight fit), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighten tolerance as stream advances
    score *= 1.0 + 0.6 * progress * (1.0 - norm_pr);

    // Penalize very small dead space that wastes capacity (non-linear bump)
    if post_residual > 0 {
        let dead = norm_pr;
        score += 30.0 * dead * (1.0 - dead) * (1.0 - dead);
    }

    // New-bin candidate: smooth penalty growing with progress and open bins
    score += is_new_bin * (40.0 + 60.0 * progress + 2.0 * open_bins_count as f64);

    // Last-chance bonus: smooth reward when few fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 25.0 * scarcity * (1.0 - is_new_bin) * (1.0 + progress);

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr >= nx) as f64;
        let slack = ((pr - nx) / cap).max(0.0);
        score -= fit_next * 20.0 * (1.0 - slack * slack);
    }

    // Mild mean-residual coupling: favor bins deviating from mean toward fullness
    score += 0.3 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes.
    let class = (post_residual * 10 / bin_capacity) as f64;
    score += class * 0.7;

    // Dead space penalty: very small post_residual is excellent (tight fit).
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Modulo coupling: post_residual that pairs with common item sizes (10..80)
    // is reusable. Check if next item fits exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect lookahead fit
        } else if next_item_size < post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item cannot fit here; slightly penalize leaving big gap unused
            score += 1.5;
        }
        // Harmonic complement: post_residual + next_item_size near multiples of capacity fractions
        let sum = post_residual + next_item_size;
        if sum > bin_capacity {
            score += 2.0;
        }
    } else {
        // Last item: minimize waste directly
        score = post_residual as f64 * 1.2;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: opening a new bin should only win when existing residuals are poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = bin_capacity as f64 * 0.85;
        // open a new bin if existing mean residual is small (bad fits everywhere)
        if mean_residual < item_size as f64 * 1.1 {
            score -= 10.0;
        }
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
        // early stream: allow more bins; late stream: prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    } else if post_residual as f64 > mean_residual + 10.0 {
        // creating an outlier large residual wastes capacity
        score += 3.0;
    }

    // Integer-division threshold on post_residual: residual >= half capacity is a
    // "healthy" bin (can host medium items); residual in dead zone (30..49) is bad.
    if post_residual >= bin_capacity / 2 {
        score += 2.0; // leaving too much is wasteful when a tighter bin exists
    } else if post_residual >= 30 && post_residual < 50 {
        score -= 1.0; // awkward zone: still usable for mid items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize small-but-usable gaps less harshly than exact dead space.
    if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter fills first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Stream progression: early on, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover space exactly fits the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Leftover can host the next item; reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover too small for next item: penalize dead space, worse if tiny.
            let waste = post_residual as f64;
            let tiny = if waste < 10.0 { 200.0 } else { 0.0 };
            score += tiny + 0.5 * waste;
        }
    }

    // Prefer bins whose residual is already below mean (tight bins) for tight fits.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Mild penalty for opening a new bin early in the stream when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 100.0 * (1.0 - progress);
    }

    // Reward filling large items into large-residual bins (avoid fragmenting small bins).
    score -= 0.2 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear penalty on waste.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        // Extra reward if the leftover can still hold small future items.
        if post_residual >= 10 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Later in the stream, be more conservative: reusing bins matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins are open with slack, discourage opening yet another one.
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Lookahead: penalize leaving a residual that exactly traps the next item size
    // in an awkward way; reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            // Next item fits snugly here later: good.
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Global state coupling: prefer placing into bins whose residual is below the
    // mean (draining the fullest bins first keeps the bin set compact).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference for filling bins with large items when residuals are small.
    if item_size >= bin_residual / 2 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Penalize extremely tiny leftovers that are likely unusable (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = post_norm * (1.0 + 2.0 * post_norm * post_norm);
    let progress_coupled = poly * (0.6 + 0.8 * progress * (1.0 - progress) * 4.0);

    let mut score = post * 0.01 + progress_coupled * cap * 0.05;

    // Penalize dead space more as stream progresses
    score += (post_norm * post_norm) * cap * (0.02 + 0.06 * progress);

    // Reward tight fits smoothly
    let fit_quality = 1.0 - post_norm;
    score -= fit_quality * fit_quality * cap * 0.03;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= cap * 0.05 * (1.0 - 0.5 * progress);
    }

    // Lookahead: penalize if post_residual cannot fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post < nx {
            score += (nx - post) * 0.04;
        } else {
            score -= 0.01 * nx;
        }
    }

    // New-bin candidate calibration: empty bin should be chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += cap * 0.12 + mean_residual * 0.05 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln1p() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: leftovers divisible into common
    // small-item sizes (10/20/25/50 classes) are reusable, odd remainders are dead space.
    let pr = post_residual;
    let reusable = (pr % 10 == 0) as f64 * 6.0
        + (pr % 20 == 0) as f64 * 4.0
        + (pr % 25 == 0) as f64 * 3.0
        + (pr % 50 == 0) as f64 * 3.0;
    score -= reusable;

    // Penalize tiny unusable slivers (< 10 cannot hold any item).
    if pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            // Reward proportionally, extra if it lands on a harmonic class.
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 - slack * 0.15;
            if (pr % next_item_size == 0) && next_item_size >= 10 {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here; penalize wasting a large residual chunk.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or the stream is early and we want fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins when good fitting options exist.
        score += 30.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open a new bin
        } else if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // Pairing with next item won't fit anywhere; fresh bin helps big items.
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins overall (waste minimization).
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Spread-awareness: when mean residual is high, prefer filling fuller bins.
    score += (mean_residual - post_residual as f64) * 0.1;

    // Harmonic threshold on integer division: bins whose post residual falls in
    // [10,20) are the most flexible for typical item sizes; slight reward.
    if pr / 10 == 1 {
        score -= 3.0;
    } else if pr / 10 == 0 && pr > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used.
    let fill = (bin_residual - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Dead space is worse late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // If next item cannot fit the post residual but could fit a fuller bin, penalize wasting space.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Deviation from mean residual: prefer bins that keep residuals balanced unless it's a tight fit.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // New bin candidate: mildly penalize so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0;
        // But if the item is large relative to residual capacity of open bins, opening is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post_residual relative to capacity is better.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = post_residual - next_item_size;
        score -= (next_fit == 0) as i32 as f64 * 25.0;
        score -= (next_item_size as f64 / post_residual as f64) * 8.0;
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover; penalize dead space more.
        score += (post_residual as f64).min(next_item_size as f64) * 0.3;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Penalize leaving very small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for opening new bins early in the stream when fits are poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 18.0;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here anyway; slight penalty if we waste a very large bin.
            score += 2.0;
        }
    }

    // Prefer filling bins that are already relatively full (consolidate waste).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 10.0;

    // Time horizon: later in the stream, be more conservative (favor tighter fits,
    // avoid opening new bins unnecessarily).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - tightness);

    // Global state: if many bins are open with large mean residual, encourage
    // using existing bins rather than spreading items.
    if open_bins_count > 0 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += spread * 0.15;
    }

    // New-bin candidate: make empty bins less attractive unless item is large
    // or no good fits exist.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * (item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mean_res_n = mean_residual / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let progress_weight = 4.0 * t * (1.0 - t); // peaks mid-stream
    score -= progress_weight * 12.0 * norm_pr * norm_pr;

    // Reward tight fits, penalize dead space non-linearly
    score += 20.0 * norm_pr * norm_pr * norm_pr;

    // Interaction: item size vs residual (prefer filling large chunks)
    score -= 8.0 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus (only one fitting bin)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - t);
    }

    // Encourage balance with mean residual across open bins
    score += 5.0 * (norm_pr - mean_res_n) * (norm_pr - mean_res_n);

    // Lookahead: favor bins whose post-residual can host next item
    if next_item_size > 0 {
        let next_n = next_item_size as f64 / cap;
        if pr >= next_item_size as f64 {
            score -= 6.0 * next_n * (1.0 - norm_pr);
        } else {
            score += 4.0 * next_n * norm_pr;
        }
    }

    // Mild new-bin penalty early, weaker late (smooth in t)
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" fractions of capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Modulo-10 harmonic bands: residuals divisible by 10 pair well with typical item sizes
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 6.0;
    } else if mod10 <= 2 || mod10 >= 8 {
        score += 3.0; // near-dead-space residuals penalized
    }

    // Integer-division thresholds: post_residual in (0,10] is nearly dead space
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Exact fit is gold
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: does next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward proportionally to how well next item uses leftover
            let fit_ratio = next_item_size as f64 / pr.max(1.0);
            score -= 8.0 * fit_ratio;
            // harmonic bonus if post_residual - next_item_size lands on a multiple of 10
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is truly bad
    if bin_residual == bin_capacity {
        // fresh bin baseline: its post_residual equals capacity - item_size
        // prefer new bin only if item leaves a highly usable residual and existing bins are fragmented
        score += 15.0;
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
        if item_size >= 50 {
            score -= 8.0; // big items go to fresh bins more readily
        }
        score += (open_bins_count as f64) * 0.5;
    }

    // Stream progression: tighten packing toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.05 * (1.0 - progress);
    score -= pr * 0.02 * progress;

    // Fragmentation pressure: if mean residual is high, prefer filling the tightest bin
    score -= (mean_residual - pr).clamp(-50.0, 50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (< 10) are almost unusable later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += (20.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we prefer existing bins unless fit is terrible.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * -1.5;
        // If the next item could use this bin's perfect residual, opening is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Pressure from many open bins: prefer filling existing bins harder.
    score += open_bins_count as f64 * 2.0;

    // If next item fits exactly in post_residual, reward leaving that usable gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but with leftover: mild reward scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 50.0 - tight.min(50.0);
        } else {
            // next item will NOT fit in this bin's leftover: penalize dead space,
            // especially when the leftover is too small for typical items.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 60.0; // unusable sliver
            } else {
                score += 10.0;
            }
        }
    }

    // Compare post_residual against mean residual: avoid creating an outlier
    // tiny residual when the mean is large (fragmenting a good bin).
    if (post_residual as f64) < mean_residual * 0.5 && post_residual > 0 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit (post_residual too small to be useful
    // for the next item) or when the item fits perfectly in an empty bin.
    if bin_residual == bin_capacity {
        // Empty bin: baseline score = full capacity. Make it slightly worse
        // than a perfect fit on an open bin, but better than wasting space.
        score = bin_capacity as f64;
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 400.0; // chain potential in fresh bin
        }
        if fitting_bins_count >= 1 {
            // An open bin can fit the item; only prefer the new bin if the
            // best open-bin outcome would be a bad fit. Encourage via penalty.
            score += 5.0;
        }
        // Late in the stream, avoid hoarding fresh bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Mild bonus for keeping residual aligned with common item sizes
    // (multiples of 10) to leave reusable gaps.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Slight preference for tighter fits overall (waste-based adjustment).
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Penalize large leftover dead space non-linearly
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits strongly
    if post_residual == 0 { score -= 40.0; }
    else if post_residual <= 10 { score -= 20.0; }

    // Lookahead: if next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.5 * next_item_size as f64;
        } else {
            score += 6.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins with tighter fit among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.0 && post_residual < 10;
        if poor_fit || (next_item_size > 0 && next_item_size > post_residual && post_residual > 0) {
            score -= 15.0; // opening new bin is reasonable
        } else {
            score += 30.0 + 20.0 * (1.0 - progress); // early on, reuse open bins
        }
    }

    // Global state coupling: many open bins with high mean residual -> reuse bins
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.15 * residual_gap;
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Time horizon: late in stream, prefer filling bins nearly completely
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer small post-residual, with smooth non-linear emphasis.
    let mut score = post + 0.035 * (post * post) / cap;

    // Reward tight fits more as stream progresses (late items need efficiency).
    let tightness = 1.0 - (post / cap);
    score -= (item_size as f64 / cap) * tightness * (1.0 + progress) * 18.0;

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - gap / cap);
        } else {
            score += gap.abs().min(cap) * 0.5;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly, less when open bins are crowded or residuals are large.
    if bin_residual == bin_capacity {
        score += 12.0 + 6.0 * (1.0 - progress) - (mean_residual / cap).min(1.0) * 8.0;
    } else {
        // Reward using existing bins relative to mean residual (prefer below-average residual bins).
        score += (bin_residual as f64 - mean_residual) * 0.08;
    }

    // Smooth non-linear coupling: quadratic in open bins count dampens bin proliferation late.
    score += (open_bins_count as f64).powi(2) * 0.004 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals in "awkward" harmonic bands (small unusable slivers)
    let band = (pr as u32 / 10) % 10; // integer division thresholds
    let band_penalty = match band {
        0 => -20.0,                    // perfect fit
        1..=2 => 25.0,                 // tiny dead space, useless
        3..=5 => 5.0,                  // mid-range, moderately reusable
        6..=8 => -3.0,                 // large residual, still flexible
        _ => -10.0,                    // near-empty bin, very flexible
    };
    score += band_penalty;

    // Reward tight fits proportionally to how well item divides capacity harmonics
    let fit_ratio = item_size as f64 / cap;
    let harmonic_bonus = if (bin_capacity % item_size.max(1)) == 0 {
        -15.0 // item divides capacity evenly -> likely reusable residual pattern
    } else {
        0.0
    };
    score -= fit_ratio * 10.0 + harmonic_bonus;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize leaving medium residual
            score += (next_item_size - post_residual).min(30) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer only when residuals are fragmented or stream is early
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap; // low mean residual => open bins are full-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap as f64 * 0.35 + pressure * 60.0 - progress * 5.0;
        if open_bins_count == 0 {
            score = -100.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits anywhere
        }
    }

    // Mild global regularization: keep scores comparable across bins
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // since items are >= 1 but small gaps rarely match; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that cannot fit the lookahead item are less useful.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0;
    }
    // Reward exact-ish fits (small but nonzero leftover is fine if gap is tiny).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect-fit bonus when bin residual matches item exactly.
    if post_residual == 0 && bin_residual == item_size {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more costly.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: residual == capacity. Make it moderately attractive
    // only when existing bins would leave bad dead space; otherwise penalize
    // so we prefer filling open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
        // If only this bin fits, opening is necessary: soften penalty.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // If the item is large relative to capacity, a fresh bin gives a clean fit.
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Slight preference for bins whose residual deviates from the mean:
    // filling below-mean-residual bins balances residuals.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight 2-step packing: strong bonus for small slack after next item.
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward for perfect chain (post_residual == next_item_size).
            if slack == 0.0 {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for next item: penalize dead space scaled by gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap.min(30.0);
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let mean_post = mean_residual - item_size as f64;
    score += 0.3 * (post_residual as f64 - mean_post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But allow new bin if item leaves a large residual that matches lookahead poorly.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) as f64 <= 5.0 {
            score -= 20.0;
        }
    }

    // Penalize leaving tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference for tighter fits overall.
    score -= 0.2 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly for small residuals.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Penalize bins that are already quite full relative to capacity (avoid wasting large holes).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score += fill_ratio * fill_ratio * 10.0;

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + (next_item_size as f64 / 100.0) * 6.0;
        } else {
            // Penalize leaving a residual that is too small for the next item (dead space risk).
            score += (post_residual as f64 / 100.0) * 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty spread across many candidates to encourage discrimination.
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowdedness = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        // Prefer new bin when existing residuals are small (mean_residual low) or many bins open.
        score -= 15.0 + crowdedness * 0.5 + progress * 5.0;
        // But discourage opening new bins when the item would leave a large usable hole anyway.
        score += (item_size as f64 / 100.0) * 12.0;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Encourage balancing residuals toward the mean residual (avoid extreme fragmentation).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.15;

    // Slight time-based pressure: later in the stream, prefer tighter fits (small post_residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on residual
    let mut score = pr as f64;

    // Smooth non-linear coupling: residual squared normalized, modulated by progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;
    score += 0.5 * poly;

    // Reward good fit relative to mean residual (smooth interaction)
    score -= (mean_residual - pr) * (0.5 + progress);

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: reward if next item fits well in post_residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_err = (pr - nx) / cap;
        score += 20.0 * fit_err * fit_err * cap - 10.0 * (1.0 - fit_err.abs()).max(0.0);
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln() * (2.0 + 4.0 * progress);

    // Prefer filling bins tighter as stream progresses
    score -= progress * (cap - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues near "useful" chunk sizes
    // (multiples of 10, 25, 50) are more reusable -> reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fill is excellent
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward proportional to how well it nests
            let nest = (pr - next_item_size) as f64;
            score -= 6.0 - (nest / bin_capacity as f64) * 4.0;
        } else {
            // next item won't fit here: penalize tiny dead space
            let waste = (next_item_size - pr) as f64;
            score += (waste / 20.0).min(8.0);
        }
    } else {
        // last item: any bin that fits is fine, prefer fullest
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, more when stream is
    // early or many bins already open with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 18.0 + 10.0 * progress;
        if open_bins_count > 0 {
            new_bin_penalty += (mean_residual / 20.0).min(12.0);
        }
        // Exception: huge item with no good existing fit class
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            new_bin_penalty *= 0.4;
        }
        score += new_bin_penalty;
    }

    // Mild tightness reward: smaller post_residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    }

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with the next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item fits in the post residual, mild reward.
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Next item won't fit here: penalize proportionally to wasted space.
            score += (next_item_size - post_residual.min(bin_capacity)) as f64 * 0.3;
        }
    } else {
        // Last item: just minimize post residual.
        score += 2.0;
    }

    // Penalize large post residuals relative to mean residual (dead space creation).
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel > 1.0 {
            score += (rel - 1.0) * 5.0;
        } else {
            score -= (1.0 - rel) * 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 12.0;
        if post_residual == 0 {
            score -= 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or stream is early and building a diverse bin pool helps.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual as f64 > 0.35 * bin_capacity as f64;
        if poor_fit {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 30.0;
        }
        // Prefer opening new bins when open bins are mostly full (high mean fill).
        score -= (bin_capacity as f64 - mean_residual) * 0.1;
    }

    // Slight preference for filling bins as the stream progresses.
    score -= (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on post_residual normalized.
    let pr = post_residual as f64;
    score += 0.8 * (pr / cap) * (pr / cap) * cap;

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation.
    score += (open_bins_count as f64).sqrt() * 1.5;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 4.0;
        }
    }

    // Global residual alignment: prefer bins close to mean residual (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, prefer filling bins tightly, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, costly late; also costly when item is small.
        let small_item_penalty = (item_size as f64 / cap) * 10.0;
        score += 20.0 * progress + small_item_penalty - (1.0 - progress) * 5.0;
    } else {
        score -= 8.0 * progress;
    }

    // Prefer placing larger items into fuller bins (best-fit with size coupling).
    score -= (item_size as f64 / cap) * (bin_residual as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;
    let nr = next_item_size as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = pr / cap;
    let poly = t * t * (1.0 - t) * (1.0 - progress);
    score -= 6.0 * poly * cap;

    // Tight fit reward, smoothed quadratic in fill ratio
    let fill = fit_ratio;
    score -= 8.0 * fill * fill * (1.0 - fill);

    // Lookahead: reward if next item fits post-residual smoothly
    if nr > 0.0 {
        let gap = pr - nr;
        if gap >= 0.0 {
            score -= 4.0 * (gap / cap) * (1.0 - progress);
        } else {
            score += 3.0 * ((-gap) / cap);
        }
    }

    // Penalize dead space relative to mean residual
    score += 0.5 * (pr - mean_residual) * (pr / cap);

    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - t);
    }

    // Mild new-bin aversion that grows with progress
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by small bin classes
    // (e.g. multiples of 10/20/25) remain usable by typical item sizes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that are "harmonic" with capacity fractions.
    let harmonic_bonus = if post_residual % 50 == 0 {
        60.0
    } else if post_residual % 25 == 0 {
        40.0
    } else if post_residual % 10 == 0 {
        25.0
    } else if post_residual % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize tiny dead space that nothing (min size 1..10) can use later:
    // small nonzero residuals are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let chain_residual = post_residual - next_item_size;
            if chain_residual % 10 == 0 {
                score -= 60.0;
            }
            score -= 10.0;
        } else {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with reasonable fits win.
        score += 120.0;
        // But if existing residuals are all fragmented (mean residual low relative
        // to item), opening fresh is fine: reduce penalty.
        let frag = mean_residual / cap;
        if frag < (item_size as f64) / cap {
            score -= 90.0;
        }
        // Early in the stream, having a fresh bin around is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins overall (waste minimization baseline).
    score += 0.1 * (bin_residual as f64 - pr);

    // Penalize leaving residual far from harmonic classes: distance to nearest
    // multiple of 10.
    let dist = (post_residual % 10).min(10 - post_residual % 10) as f64;
    score += 2.0 * dist;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;

    // Strict dead-space avoidance: gaps too small to hold even the
    // smallest plausible item are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 + 0.5 * progress);
    }
    // Very small gaps that only fit tiny items: moderate penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits (low post residual relative to capacity).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage proliferation of bins.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Default: penalize opening a new bin when one exists that fits.
        score += 45.0;
        if fitting_bins_count <= 1 {
            // No (or only this) fitting bin -> opening a new bin is fine.
            score -= 50.0;
        }
        // Lookahead: if the next item pairs well with the current one in a
        // fresh bin, opening a new bin is attractive.
        if next_item_size > 0
            && next_item_size + item_size <= bin_capacity
            && next_item_size + item_size > bin_residual - item_size + item_size.min(next_item_size)
        {
            score -= 15.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        score += 10.0 * progress;
    }

    // Lookahead coupling: keep room for the next item when possible.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Mild preference for bins whose residual is near the mean (balanced use).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual as u32 >= next_item_size {
            // Next item can chain into this bin: reward tight chain.
            score -= 150.0 / (1.0 + diff as f64);
        }
        // Penalize leaving a gap slightly larger than next_item_size (dead space).
        if post_residual as u32 > next_item_size && diff <= 8 {
            score += 30.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize the brand-new empty bin unless it enables a perfect future chain.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual as i64 - next_item_size as i64 == 0 {
            score -= 200.0;
        }
    }

    // Mild pressure to consolidate early in the stream.
    let progress = step_index as f64 / total_items as f64;
    score -= 20.0 * (1.0 - progress) / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (low dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving awkward residuals that few future items can use.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            1.0
        } else if post_residual > 80 {
            1.0
        } else {
            0.35
        };
        score += 18.0 * dead * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra bonus if the leftover after the next item would also be tight.
        let chain_left = post_residual - next_item_size;
        if chain_left < 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; mild penalty proportional to wasted lookahead.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // existing bins fit well or the stream is early/short.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 20.0 + 15.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            new_bin_penalty += 22.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Opening a bin is more acceptable when mean residual is high (bins full).
        new_bin_penalty -= 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        score += new_bin_penalty.max(0.0);
    }

    // Slight preference for fuller bins among ties (larger item_size consumed).
    score -= 0.05 * item_size as f64;

    // Mild diversification with stream progress and open-bin pressure.
    score += 0.01 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize post-residual, more strongly late in the stream
    let mut score = pr * (0.6 + 0.8 * progress);

    // Non-linear polynomial coupling: dead-space penalty grows quadratically/cubically
    // for small residuals (unusable space), smoothed to avoid piecewise constants
    let dead = (1.0 - fit_norm).powi(2);
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits: subtract for small post-residual via smooth inverse coupling
    score -= 25.0 * (1.0 - fit_norm).powi(3);

    // Lookahead: reward bins whose post-residual fits the next item (chain packing)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 18.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            // post-residual too small for next item: smooth penalty for stranded space
            score += 12.0 * (nx / cap) * (1.0 - fit_norm);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress * 0.5);
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score -= 5.0 * (mean_residual - pr) / cap;

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly,
    // with the penalty relaxing late in the stream when hoarding bins is pointless
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but weight dead space nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction left over

    // Harmonic class of post_residual: which "slot" does the leftover fall in?
    // Small leftovers (0..=10) are near-perfect fills -> big reward.
    // Mid leftovers (11..=40) are reusable by typical items -> mild reward.
    // Large leftovers (>40) suggest we should have opened a new bin -> penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 45.0 + 0.5 * pr;
    } else if post_residual <= 20 {
        score -= 20.0 + 0.3 * pr;
    } else if post_residual <= 40 {
        score -= 0.2 * pr;
    } else {
        score += 15.0 + 0.4 * (pr - 40.0); // dead space penalty
    }

    // Modulo-arithmetic harmonic classes on post_residual:
    // leftovers divisible by common item sizes (10, 20, 25, 50) are reusable.
    if post_residual > 0 {
        let r = post_residual;
        if r % 10 == 0 { score -= 8.0; }
        if r % 25 == 0 { score -= 6.0; }
        if r % 50 == 0 { score -= 6.0; }
        // Odd, prime-ish leftovers are hard to fill later.
        if r % 10 != 0 && r < 10 { score += 4.0; }
    }

    // Lookahead: does this leftover fit the next item exactly / well?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 35.0; // chains perfectly into next item
        } else if post_residual >= next_item_size {
            score -= 10.0; // next item still fits here
        } else {
            score += 6.0; // next item won't fit -> bin closes anyway
        }
        // Harmonic class of next_item_size: multiples of 10 chain well
        if next_item_size % 10 == 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        let _ = n;
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large dead space (post_residual high relative to capacity).
    if bin_residual == bin_capacity {
        // Fresh bin: residual after placement = cap - item_size.
        // Penalize slightly so it only wins when open bins are truly bad.
        score += 30.0;
        // But reward opening fresh for very large items that would fragment bins.
        let ifrac = item_size as f64 / cap;
        if ifrac > 0.6 {
            score -= 20.0;
        }
        // Early stream: opening bins early is fine (more bins to work with).
        let prog = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - prog);
    }

    // Mean residual coupling: if open bins are already loose on average,
    // discourage adding more slack to this bin.
    if mean_residual > cap * 0.5 && post_residual > cap * 0.4 {
        score += 8.0;
    } else if mean_residual < cap * 0.25 && post_residual < cap * 0.25 {
        score -= 5.0; // tight-packing regime: reward tight fits further
    }

    // Many open bins: prefer consolidating into existing ones over spreading.
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64 - 4.0).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps that likely cannot host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0; // gap can't fit the known next item
    }

    // Reward tight fits (waste relative to item size).
    score -= (item_size as f64) / (1.0 + post_residual as f64);

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 3.0;

    // Prefer bins below mean residual (fill emptier bins less).
    score += ((bin_residual as f64) - mean_residual) * 0.2;

    // New-bin candidate: only attractive when current bin leaves a bad gap.
    if bin_residual == bin_capacity {
        let bad_gap = post_residual < 10
            || (next_item_size > 0 && post_residual < next_item_size);
        if bad_gap {
            score -= 45.0; // opening fresh bin beats creating dead space
        } else {
            score += 20.0; // good fit exists; discourage new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let match_gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item can follow: reward proportional to how exact the match is.
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize dead space that blocks lookahead.
            score += 0.5 * match_gap;
        }
    }

    // Penalize bins whose residual deviates strongly from mean residual
    // (prefer balanced packing unless it's an exact lookahead match).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bins mildly attractive only when
    // the item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 10.0 + 20.0 * (1.0 - frac);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin can also host next item
        }
    }

    // Early in the stream, allow more liberal new-bin opening (build a portfolio).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.35 * tightness * (item_size as f64);

    // Penalize dead space that no future item can plausibly use.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 6.0 + 0.15 * (post_residual as f64);
        } else if (post_residual as u32) >= next_item_size {
            // Reward bins that can also host the lookahead item.
            score -= 3.0 + 0.05 * (next_item_size as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * ((fitting_bins_count - 1) as f64).ln().max(0.0);
    }

    // New-bin candidate handling: only attractive when open bins are quite full
    // or residuals are fragmented relative to item size.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / (bin_capacity as f64);
        let pressure = avg_fullness * (1.0 + 0.5 * progress);
        score += 14.0 - 12.0 * pressure;
        // If the item is large and mean residual can't absorb it well, new bin ok.
        if (item_size as f64) > mean_residual {
            score -= 4.0;
        }
    }

    // Prefer bins with below-average residual (denser bins first) to consolidate waste.
    score += 0.08 * ((bin_residual as f64) - mean_residual);

    // Mild time decay: late in the stream, waste tolerance shrinks.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.10 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear tightening late in stream.
    let mut score = pr * (1.0 + 0.5 * progress * norm_pr);

    // Polynomial coupling: reward very tight fits (small pr) superlinearly.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 10.0;

    // Penalize dead space that no plausible next item can use, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (pr - nxt).max(0.0);
        score += waste * waste / cap;
    } else {
        score += pr * 0.2;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins vs consolidation.
    score += open_bins_count as f64 * 0.05 * norm_pr;

    // Deviation from mean residual: prefer bins whose residual is unusual (smaller).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Residuals that are multiples of 10 are "harmonic" — highly reusable by items
    // drawn on a 10-grid; penalize odd/dead residuals.
    let harmonic = (post_residual % 10) == 0;
    if harmonic {
        score -= 8.0;
    } else if post_residual % 10 >= 5 {
        score += 4.0; // half-class residues: moderately dead
    } else {
        score += 9.0; // small dead space is worst
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to bin capacity fraction.
    let fit_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up (harmonic chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if post_residual < next_item_size {
            score += 6.0; // next item won't fit here; bin likely closes
        }
    }

    // Prefer filling nearly-full bins (low residual) over fresh ones,
    // but penalize creating tiny unusable slivers relative to mean residual.
    if (post_residual as f64) < mean_residual * 0.3 && post_residual > 0 {
        score += 5.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // open bins would leave large dead space; otherwise discourage.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64;
        if item_size % 10 == 0 {
            score -= 10.0; // grid-aligned items pair well with fresh bins
        }
    }

    // Early in the stream, allow more bins; late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps (below minimum item size 1..=10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (wasting little space)
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (0.5 + progress * 0.5);

    // Prefer bins whose residual is below the mean (consolidate space)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // New-bin candidate: penalize unless current bins are genuinely poor fits
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (small post_residual) is good.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // 2-step lookahead coupling: reward when next item exactly fills post_residual,
    // penalize when post_residual is a small unusable dead space relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if (post - nxt).abs() < 1.0 {
            score -= 40.0; // perfect match: next item fills this bin exactly
        } else if post >= nxt {
            let slack = post - nxt;
            score -= 10.0;
            score += 0.3 * slack; // mild penalty for leftover after the lookahead
        } else {
            // next item won't fit here: dead space penalty grows as post_residual shrinks
            score += 0.8 * (nxt - post).min(60.0);
            if post < 10.0 {
                score += 25.0; // nearly unusable sliver
            }
        }
    }

    // Relative-to-mean-residual term: prefer bins whose residual deviates favorably.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it attractive only when few bins fit or fit is terrible;
    // otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 45.0;
        if fitting_bins_count <= 1 {
            nb -= 60.0; // opening a new bin is necessary/last-resort
        }
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            nb += 5.0; // slight penalty: could have paired with next item elsewhere
        }
        nb += 10.0 * (1.0 - progress);
        score += nb;
    }

    // Slight preference for fuller bins among many open bins.
    score -= 0.1 * (bin_capacity - bin_residual) as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * tightness * 40.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item would fit perfectly in the post residual,
    // this placement sets up a great follow-up; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap < 10.0 {
                score -= 20.0 * (1.0 - gap / 10.0);
            }
        } else {
            // next item cannot fit here; slight penalty for awkward residual
            score += 5.0;
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // Base new-bin cost; cheaper later in the stream and when bins are full.
        score += 50.0 + 30.0 * (1.0 - progress) + crowd;
        // If item is large and leaves small post_residual in a fresh bin, that's fine.
        if item_size >= 60 {
            score -= 25.0;
        }
        // If next item is large too, a fresh bin may serve both.
        if next_item_size >= 50 && item_size + next_item_size <= bin_capacity {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins with larger residual among open bins.
        score -= (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Time-horizon coupling: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Smooth non-linear coupling: tightness of fit weighted by progress
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Penalize large dead space superlinearly (wasted capacity)
    let dead = post_residual as f64 / cap;
    score += 40.0 * dead * dead * dead;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when item is large
    // relative to mean residual or few bins fit the item.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 15.0 * large_item * large_item + 20.0 * scarcity;
        score += 10.0 * (1.0 - progress); // early on, new bins are fine
    } else {
        // Prefer bins whose residual is close to mean (spread load evenly)
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 8.0 * dev;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 5.0 + 10.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        // Reward residuals that leave room close to next item size
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack * slack);
    }

    // Mild preference for reusing bins as stream matures
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (eighths)
    let eighth = (bin_capacity / 8).max(1);
    let class = (post_residual / eighth) as f64;
    // Penalize residuals that are "awkward" classes (small slivers)
    score += match post_residual {
        0 => -50.0, // perfect fit heavily rewarded
        r if r < eighth => 20.0 + (eighth - r) as f64, // tiny dead space penalty
        r if r < 2 * eighth => 6.0,
        r if r < 4 * eighth => -2.0, // half-ish residuals are useful
        _ => 0.0,
    };

    // Modulo-class coupling: residuals divisible by common item sizes are reusable
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // harmonic class match between next item and post_residual
        let nclass = (next_item_size / eighth) as f64;
        score -= 4.0 * (1.0 - (class - nclass).abs() / 8.0).max(0.0);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty for wasting the slot
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // prefer tighter bins among many candidates (implicit via post_residual)
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: only attractive when open bins are very full / fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / cap;
        // new bin baseline: slightly above a perfect fit, below awkward fits
        score = 12.0 - 10.0 * (1.0 - fragmentation.min(1.0)) - 8.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: fresh bin useful
        }
    }

    // Mild preference for filling fuller bins overall
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (<10) are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit reward: item fills most of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 15.0 * fill_ratio;
    }

    // Last chance: only this bin can fit the item -> strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // If the next item fits in the post residual, reward leaving useful space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // Next item nearly fits: mild penalty for wasting the gap.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; favor compact bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when fits are poor or few fitting bins.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 25.0 || fitting_bins_count <= 1;
        if bad_fit {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins whose post-residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // 2-step lookahead: strongly reward a bin whose post-residual can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fills this bin exactly or nearly.
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space penalty scaled by how badly the next item misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.3 * miss;
        }
    } else {
        // Last item: pure tightness matters.
        score -= 10.0 * tightness;
    }

    // Relative to mean residual: bins with residual far above mean have more room to waste.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 15.0 * dev;

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // or no open bin fits well. Penalize opening new bins when many bins exist
    // and the item fits elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 35.0 + 20.0 * progress + 2.0 * pressure;
        // If item nearly fills a fresh bin, opening one is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 45.0;
        }
        // If next item would fit perfectly in a fresh bin with this item, boost.
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            let gap = (bin_capacity - item_size - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Mild preference for consolidating into fewer bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more strongly (non-linear).
    if post_residual > 0 {
        score -= 12.0 * (bin_capacity as f64 / (post_residual as f64 + 1.0)).sqrt();
    } else {
        score -= 40.0; // perfect fill is excellent
    }

    // Penalize dead space that is too small for typical future items.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - t); // early tiny dead space is worse
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item won't fit here; mild penalty proportional to wasted opportunity
        score += 0.15 * (next_item_size as f64 - post_residual as f64).min(30.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Slight preference for reusing existing bins vs opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity; its high post_residual
    // already scores high, add a small extra penalty to discourage premature opening).
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - t);
    }

    // Encourage consolidation when many bins are open.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let mut score = pr * (1.0 + 0.9 * progress * norm_pr);

    // Cubic smoothing term: penalize large dead space non-linearly.
    score += 4.0 * norm_pr * norm_pr * norm_pr * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Reward bins that also fit the lookahead item (chaining placements).
    if next_item_size > 0 {
        if (pr as u32) >= next_item_size {
            score -= 6.0 + 8.0 * progress;
        } else {
            // Penalize blocking the next item into unusable residual.
            score += 3.0 * (1.0 - pr / (next_item_size as f64).max(1.0));
        }
    }

    // Deviation from mean residual: prefer bins that keep residuals balanced,
    // with strength growing as the stream progresses.
    score += 2.5 * progress * (pr - mean_residual).abs() / cap;

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Slight preference for filling existing bins over opening new ones,
    // unless the new-bin residual would be perfectly tight.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 12.0 * norm_pr * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual mod 10 defines "waste class".
    // Leftovers that are multiples of 10 (or small) are reusable; odd classes are dead space.
    let pr = post_residual as u32;
    let class = pr % 10;
    let class_penalty = match class {
        0 => -6.0,
        1 => 4.0,
        2 => 2.0,
        3 => 5.0,
        4 => 1.0,
        5 => 3.0,
        6 => 4.5,
        7 => 6.0,
        8 => 5.5,
        _ => 3.5,
    };
    score += class_penalty;

    // Integer-division thresholds: reward near-exact fits (post_residual <= 10).
    if pr == 0 {
        score -= 30.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= 20 {
        score -= 4.0;
    }

    // Capacity fraction coupling: waste proportional to residual fraction squared.
    let res_frac = post_residual as f64 / cap;
    score += 20.0 * res_frac * res_frac;

    // Lookahead: if next item fits the post residual exactly or well, reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this leftover: penalize large leftovers slightly
            score += 3.0 * res_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Mean residual coupling: if this bin is far below mean residual (already tight),
    // prefer it; spread waste across bins is bad.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Stream progression: late in the stream, be conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        let base = 25.0 - 20.0 * crowding;
        score += base + 10.0 * progress;
    }

    // Slight preference for tighter bins overall.
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 13 {
        // Usable leftover space is mildly rewarded proportional to its size.
        score -= (post_residual as f64 - 12.0) * 0.35;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: more open bins -> prefer filling existing ones, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (2.0 + 3.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by open-bin pressure so it's chosen only when
        // all open bins have bad fits (their dead-space penalties exceed this).
        score += 15.0 + pressure;
    } else {
        score -= pressure.min(12.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if post_residual is nonzero but too small for the next item (creates stranded gap).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins whose residual is close to the mean residual (balanced filling),
    // but only mildly, so tight fits dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item fits here afterwards: strong reward, best if perfect match.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 25.0; // perfect two-item chain fill
            }
        } else {
            // Next item won't fit after this placement; penalize leftover dead space,
            // scaled by how close the next item is to fitting (near-miss is worst).
            let near_miss = 1.0 - (nxt - pr) / nxt.max(1.0);
            score += 12.0 * near_miss;
        }
    }

    // Compare this bin's residual to the fleet mean: prefer bins with residual
    // close to the item (tight fit) especially when residual is below mean.
    let br = bin_residual as f64;
    if mean_residual > 0.0 {
        let tightness = 1.0 - (br - item_size as f64) / bin_capacity as f64;
        if br < mean_residual {
            score -= 8.0 * tightness;
        } else {
            score += 3.0 * (br - mean_residual) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Never prefer opening a new bin when this placement leaves a usable residual.
    if bin_residual == bin_capacity {
        score += 15.0 + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: penalize wasted space superlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Small dead space (< 10) is nearly unusable given item sizes; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in this bin's post-residual, reward the pairing.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0 + 0.05 * next_item_size as f64;
    }
    // If next item would leave this bin with tiny unusable remainder, penalize.
    if next_item_size > 0 && post_residual >= next_item_size
        && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 6.0;
    }

    // New-bin candidate: only attractive when current bin would leave large awkward
    // residual or when this bin is a poor fit overall.
    if bin_residual == bin_capacity {
        // Bias toward open bins for good fits; new bin base score is post_residual (=capacity).
        score += 5.0;
        if fit_ratio < 0.5 {
            // item is small relative to a fresh bin: opening a new bin wastes capacity
            score += 30.0;
        }
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Many open bins with high mean residual: prefer consolidation into existing bins.
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 10.0;
        }
    }

    // Prefer bins already below mean residual (balancing keeps large gaps available).
    if (bin_residual as f64) < mean_residual && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Slight preference for fuller bins (smaller residual) among comparable fits.
    score += 0.02 * (bin_capacity as f64 - bin_residual as f64).recip() * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (low post_residual)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly.
    let pn = post / cap;
    let coupling = pn * pn * (0.5 + 2.5 * progress) * cap;
    score += coupling;

    // Penalty for new empty bin candidate unless item is large relative to capacity
    let is_new_bin = (res - cap).abs() < 0.5;
    if is_new_bin {
        let fill_ratio = item / cap;
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        // Reward opening a new bin when fill is large or few bins open / few alternatives
        let alt_bonus = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        let last_chance = if fitting_bins_count == 1 { 15.0 } else { 0.0 };
        score += 10.0 - 60.0 * fill_ratio * (0.4 + openness) - alt_bonus - last_chance;
    } else {
        // Reward using existing bins, especially when they are the last chance
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Reward bins whose residual deviates from the mean (consolidation)
        let dev = (res - mean_residual).abs();
        score -= 0.15 * dev * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            score -= 20.0 * (1.0 - gap / cap);
        } else {
            score += 0.05 * (nxt - post);
        }
    }

    // Mild penalty when many bins are open (encourage closing bins)
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item-size divisors are more reusable, so reward them.
    let cap = if bin_capacity == 0 { 100 } else { bin_capacity };
    let pr = post_residual;

    // Best-fit core: exact fit is perfect.
    if pr == 0 {
        score -= 1000.0;
    }

    // Harmonic reward: post_residual divisible by small integers (likely
    // future item sizes or sums) is reusable.
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 3.0; }
        if pr % 50 == 0 { harmonic_bonus += 3.0; }
        // GCD-like coupling with next item: if next item fits exactly into
        // post_residual, huge reward (k=2 lookahead chaining).
        if next_item_size > 0 && next_item_size <= pr {
            if pr == next_item_size {
                harmonic_bonus += 25.0;
            } else if pr % next_item_size == 0 {
                harmonic_bonus += 12.0;
            } else if next_item_size % 10 == 0 && pr % 10 == 0 {
                harmonic_bonus += 5.0;
            }
        }
        // Dead space penalty: tiny unusable leftovers (below min plausible item).
        if pr < 5 {
            score += 20.0;
        } else if pr < 10 {
            score += 8.0;
        }
    }
    score -= harmonic_bonus;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < cap {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we
    // only open a new bin when fits are bad, but reward it when the item is
    // large relative to capacity (large items deserve fresh space) or when
    // existing residuals are too tight on average.
    if bin_residual == cap {
        let large_item = item_size as f64 > 0.7 * cap as f64;
        let tight_bins = mean_residual < item_size as f64 * 0.5;
        let mut nb = 30.0;
        if large_item { nb -= 12.0; }
        if tight_bins { nb -= 10.0; }
        if next_item_size > 0 && next_item_size >= item_size {
            // big-big stream: fresh bin keeps harmonic alignment
            nb -= 5.0;
        }
        if open_bins_count > 0 && fitting_bins_count == 0 {
            nb -= 25.0; // no alternative anyway
        }
        score += nb;
    }

    // Prefer tighter existing residuals slightly (waste minimization).
    let tightness = (bin_residual as f64 - item_size as f64) / cap as f64;
    score += tightness * 5.0;

    // Early in the stream, allow more bins (future flexibility); later,
    // consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.6 {
        score += open_bins_count as f64 * 0.5;
    } else {
        score -= 1.0;
    }

    // Penalize spreading across many bins when a decent fit exists.
    if open_bins_count > 3 && fitting_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any gap below the minimum item size is unusable.
    let dead_threshold = 9u32; // min item size 10 minus 1
    if post_residual <= dead_threshold && post_residual > 0 {
        score += 60.0; // heavy penalty: creating dead space
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward
    }

    // Tight-fit reward: small post_residual relative to capacity
    score -= 25.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate
        score += 15.0 + 2.0 * open_bins_count as f64 * (0.5 + progress);
        // but if next item would fit into the leftover of a new bin, slight relief
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    } else {
        // mild bonus for using an existing bin when few bins are open
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Residual balance: prefer bins whose residual is close to the item (best fit)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Lookahead: if next item fits exactly in post_residual, reward
    if next_item_size > 0 && post_residual > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 35.0;
        } else if diff > 0 && (diff as u32) <= dead_threshold {
            score += 20.0; // next item would leave dead space anyway; avoid
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches (or tightly accommodates) the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Exact match: near-perfect packing across two steps -> strong reward.
        if (post - nxt).abs() < 0.5 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: partial reward proportional to tightness.
            let tight = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 25.0 * tight;
        } else {
            // Next item does NOT fit: penalize wasted lookahead potential,
            // scaled by how badly it misses.
            let miss = (nxt - post) / bin_capacity as f64;
            score += 30.0 * miss;
        }

        // Bonus when this bin plus next item would leave a very small remnant.
        if next_item_size <= post_residual {
            let rem2 = post - nxt;
            if rem2 < 10.0 {
                score -= (10.0 - rem2) * 1.5;
            }
        }
    }

    // Tightness of the current placement: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Relative to mean residual: prefer bins tighter than the average,
    // but avoid creating dead space far below the mean.
    if post_residual as f64 > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.20 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
        if post_residual < 5 {
            score += 25.0; // terrible fit, don't burn the bin
        }
    }

    // New-bin candidate: only attractive when existing fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (post_residual as f64 > mean_residual + 0.5 * mean_residual.max(1.0));
        if poor_fits {
            score -= 12.0;
        } else {
            score += 18.0; // discourage opening new bins when decent fits exist
        }
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: reward near-exact fits non-linearly.
    let fit_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the upcoming item.
        let waste = (post_residual as f64 - (next_item_size as f64 * 0.0).max(0.0)).max(0.0);
        score += 0.05 * waste;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let mut penalty = 25.0;
        if fitting_bins_count == 0 {
            penalty = -5.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 15.0 * progress;
        // Many open bins with large mean residual: reuse them instead.
        if mean_residual > item_size as f64 + 10.0 && open_bins_count > 2 {
            penalty += 10.0;
        }
        score += penalty;
    }

    // Mild penalty for leaving residuals too small to be useful (below min item size 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for filling bins that are already partially loaded.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prn = pr / cap;

    // Base: prefer small post residual, but with diminishing returns (quadratic in prn)
    let mut score = pr - 12.0 * prn * (1.0 - prn);

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more.
    let prog_curve = prog * prog * (3.0 - 2.0 * prog);
    score += 25.0 * prog_curve * prn * prn;

    // Penalize dead space that next item cannot use (smooth coupling)
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap);
        let waste = (pr - nx).max(0.0) / cap;
        score += 18.0 * waste * waste * (1.0 - prog_curve);
    }

    // Last-chance bonus: strong reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * prog_curve;
    } else {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Mild preference for bins tighter than average (smooth deviation coupling)
    let dev = (mean_residual - pr) / cap;
    score -= 6.0 * dev / (1.0 + dev.abs());

    // Mild pressure against accumulating too many open bins
    score += 1.5 * (open_bins_count as f64).sqrt() * prn;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers in "nice" residue classes
    // (multiples of small common item sizes) are more reusable.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r % m == 0 {
                bonus += 3.0;
            }
        }
        if r % 5 == 0 { bonus += 1.0; }
        bonus
    };
    score -= reusable(post_residual);

    // Penalize dead space that no plausible item (>=1) can even partially use well:
    // very small leftovers are dead weight.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit: leftover smaller than half the smallest plausible item.
    if post_residual > 0 && post_residual <= 5 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual % next_item_size.max(1) == 0 {
            score -= 8.0; // next item divides leftover -> future perfect fits
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0; // this bin will be unusable next step
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fits are poor
    // or the stream is early (room to consolidate later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - item_size as f64) / bin_capacity as f64;
        score = bin_capacity as f64 * (0.9 + 0.2 * progress) - 25.0 * pressure.max(0.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits: new bin is necessary
        }
    }

    // Slight nudge toward fuller bins overall.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Harmonic capacity-fraction tiebreak: bins whose residual sits at simple
    // fractions of capacity are more attractive targets.
    let frac = bin_residual as f64 / bin_capacity as f64;
    for &f in &[0.25f64, 0.5, 0.75] {
        if (frac - f).abs() < 0.01 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item are pure waste -> heavy penalty.
    let min_item = 1u32; // unknown distribution: smallest possible size
    if post_residual < min_item {
        score += 50.0; // perfect fill, actually great -> reward instead
        score -= 100.0;
    } else {
        // Non-linear "unusable gap" penalty: gaps below ~15 are hard to fill.
        if post_residual < 15 {
            score += (15.0 - post_residual as f64) * 3.0;
        } else if post_residual < 30 {
            score += (30.0 - post_residual as f64) * 0.8;
        }
    }

    // Reward tight fits: fraction of residual consumed.
    let fill_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= fill_ratio * 40.0;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // and penalize opening yet another bin.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when residuals elsewhere are large
        // or the fit is terrible (big post_residual in an existing bin).
        score += pressure * 4.0;
        score += mean_residual * 0.5;
        // Lookahead: if next item is large, a fresh bin is more valuable.
        score -= next_item_size as f64 * 0.3;
        // Late in the stream, avoid proliferation of new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 25.0;
    } else {
        // Existing bin: mild reward scaled by pressure to consolidate.
        score -= pressure * 1.5;
        // If next item fits exactly in the post residual, big bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        // Penalize leaving a gap that next item barely misses.
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
            score += (post_residual as f64) * 0.6;
        }
    }

    // Prefer bins whose residual is below average (consolidate fuller bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (post_residual small).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Prefer tight chains: small slack after also placing the next item.
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            if slack <= 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
        // If next item is large, favor conserving space in bins that could host it.
        if next_item_size >= 50 && post_residual < next_item_size && bin_residual >= next_item_size {
            score += 8.0;
        }
    }

    // Compare post_residual against mean residual: leaving far less than average is good (tight packing),
    // leaving much more than average suggests wasteful placement.
    if post_residual as f64 > mean_residual + 15.0 {
        score += 0.5 * (post_residual as f64 - mean_residual - 15.0);
    } else if (post_residual as f64) < mean_residual - 10.0 {
        score -= 0.3 * (mean_residual - post_residual as f64 - 10.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the item
    // is large or no tight fit exists; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if item_size >= 60 || fitting_bins_count == 0 {
            score -= 12.0;
        } else {
            score += 20.0;
        }
    }

    // Early in stream, allow more bins to spread items; late in stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty scaled by many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * fit_ratio;
    } else if fit_ratio > 0.6 {
        score -= 6.0 * fit_ratio;
    }

    // Penalize large dead space relative to typical item scale.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score -= 5.0; // tiny slivers are effectively dead anyway, but cheap
    } else {
        score += 0.35 * (dead / 10.0).powf(1.6);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
            // perfect pairing bonus
            if post_residual as i64 - next_item_size as i64 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving medium-size gaps if a new bin is cheap
            let progress = step_index as f64 / total_items.max(1) as f64;
            let open_pressure = (open_bins_count as f64 / (1.0 + progress * 10.0)).min(3.0);
            score += 2.5 * open_pressure;
        }
    }

    // New-bin candidate handling: make an empty bin moderately attractive only when
    // existing residuals are large or fragmented, otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - post_residual as f64; // how much worse open bins are
        let progress = step_index as f64 / total_items.max(1) as f64;
        // late in the stream, opening fresh bins is safer (avoids stranding)
        let late_bonus = 14.0 * progress;
        if mean_gap > 0.0 {
            score -= mean_gap.min(30.0) * 0.6 + late_bonus;
        } else {
            score += 10.0 - late_bonus * 0.5;
        }
        // avoid proliferating bins when many are already open with slack
        score += 1.2 * (open_bins_count as f64).sqrt();
    }

    // Mild preference for bins below mean residual (keep residual distribution tight).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(-50.0).abs().min(50.0) * 0.0
        + 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer filling more-open bins slightly (balance load, close bins early).
    if open_bins_count > 4 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let tight = 1.0 - pr / cap; // fullness after placement

    // Non-linear polynomial coupling: fullness valued more as stream progresses
    let coupling = pr * (1.0 - progress) + pr * pr / cap * progress;

    let mut score = coupling;

    // Reward tight fits with a smooth non-linear term
    score -= 30.0 * tight * tight * (0.5 + progress);

    // Lookahead: penalize if next item cannot use the resulting residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 8.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            score -= 6.0 * (1.0 - (nx - pr).abs() / cap);
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Penalize extreme dead space (small unusable residual)
    if pr > 0.0 && pr < 10.0 {
        score += 12.0 * (10.0 - pr) / 10.0;
    }

    // New-bin candidate: prefer it early or when open bins are all loose
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score = cap - 15.0 * progress - 2.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "usable"
    // classes (>= 10 or exactly 0) are rewarded; dead space in (0,10) is penalized.
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else if post_residual < 10 {
        score += 40.0; // dead space: unusable for min-size items
    } else {
        // Reward leftover proportional to how well next item could slot in
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else if next_item_size > 0 {
            score += 8.0;
        }
    }

    // Integer-division threshold classes on post_residual (capacity = 100)
    let q = post_residual / 25; // classes 0..4
    score -= match q {
        0 => 0.0,
        1 => 5.0,
        2 => 10.0,
        3 => 15.0,
        _ => 20.0,
    } as f64;

    // Modulo arithmetic on post_residual: multiples of 10 harmonize with item sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins more when open bins have plenty of room
        score += 55.0 * pressure.max(0.0) + 5.0;
        if post_residual >= 20 {
            score -= 10.0; // fresh bin keeps large usable space
        }
    }

    // Slight preference for tight fills as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    // Prefer bins below mean residual (consolidating emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        // dead space threshold: gaps too small for typical future items
        let dead_thresh = 10.0f64.min(post_residual as f64);
        if post_residual < 10 {
            // unusable gap (min item size 10) -> heavy penalty
            score += (10 - post_residual) as f64 * 12.0;
        } else {
            // larger gaps: mild super-linear penalty to prefer tight fits
            score += (post_residual as f64).powf(1.15) * 0.35;
        }
        let _ = dead_thresh;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, allow opening new bins for better fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += open_pressure * 0.15;

    // New-bin candidate: neutral baseline with slight bias toward tight fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin; scale with remaining stream
        score = 55.0 + (1.0 - progress) * 10.0;
        // prefer new bin if it would create a very tight fit
        if post_residual <= 5 {
            score -= 30.0;
        }
        // discourage new bin if a current bin fits perfectly well
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual - next_item_size < 5 {
            score -= 25.0; // enables a perfect follow-up fit
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot use the residual and residual is small, penalize
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Mild tie-break toward bins below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 60.0;

    // Aggressive 2-step lookahead: if the next item exactly matches post_residual,
    // this placement is a chain of perfect fits -> huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterward: reward proportionally to how well it fills.
            let next_fill = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= next_fill.powi(4) * 40.0;
        } else {
            // Next item won't fit after this placement: penalize creating dead space.
            score += 15.0;
        }
    } else {
        // Last item: minimize post residual as much as possible.
        score -= 30.0 * (1.0 - fit_ratio);
    }

    // Penalize large post_residual relative to mean residual (wasteful leftover).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mildly penalize so we only open when open fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Early in stream: be slightly more willing to open bins for future flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (0..1), clamped defensively.
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).min(1.0)
    } else {
        0.0
    };

    // Fill ratio of this bin before placement.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // Reward bins that are already well-filled (best-fit flavor): subtract
    // proportional to how full the bin is, so high-fill bins win ties.
    score -= 8.0 * fill;

    // Perfect or near-perfect fit: strong reward for tiny post_residual.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is unusable.
        score += 6.0;
    }

    // Lookahead coupling (k=2): if the next item fits exactly into the
    // post-residual, this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // Partial credit scaled by how much of the leftover is used.
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * usage;
        } else {
            // Next item cannot use the leftover at all: mild penalty for
            // stranding space, stronger late in the stream when fewer
            // future chances remain to recover.
            score += 4.0 + 6.0 * progress;
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 5.0 * fill;
    }

    // Last-chance bonus: if this is the only open bin that fits the item,
    // avoid opening a new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
        // Extra pull when the fit is decent.
        if post_residual < item_size {
            score -= 8.0;
        }
    }

    // Penalize bins whose residual deviates far from the mean residual:
    // keeps the bin portfolio balanced and avoids fragmenting one bin
    // while others stay fat.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time-horizon term: early in the stream, keep bins flexible (mild
    // penalty for very low post-residual that isn't a perfect fit); late
    // in the stream, aggressively consolidate into existing bins.
    if progress < 0.3 {
        if post_residual > 0 && post_residual < 10 {
            score += 5.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score is post_residual = capacity - item_size, which is
    // often large; add a fixed opening cost, but discount it when the
    // item is huge and no open bin fits well (fitting_bins_count small
    // and post_residual large means poor fits elsewhere).
    if bin_residual == bin_capacity {
        score += 18.0;
        // If the item is large relative to capacity, opening fresh is
        // less painful (big items otherwise leave big holes).
        if item_size >= 60 {
            score -= 10.0;
        }
        // Late in the stream, opening new bins wastes capacity: penalize.
        score += 15.0 * progress;
    }

    // Mild penalty for contributing to bin sprawl when many bins are open.
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (2.0 - norm_pr);
    score += 40.0 * poly * (0.5 + progress);
    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= (pr - nxt).min(pr) * 0.3;
        }
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }
    // Prefer tighter bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.4;
    // Mild penalty for spreading across many bins late in stream
    score += open_bins_count as f64 * 0.15 * progress;
    // New-bin candidate: neutral baseline with slight progress-aware bias
    if bin_residual == bin_capacity {
        score = cap * (0.9 - 0.5 * progress) + mean_residual * 0.2;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual as i64;
    let nxt = next_item_size as i64;

    // Penalize post_residual that is dead space: too small for typical items (1..100).
    if post > 0 && post < 10 {
        score += 80.0; // unusable sliver
    }

    // Reward if next item fits exactly into post_residual (perfect chain).
    if nxt > 0 && nxt == post {
        score -= 300.0;
    } else if nxt > 0 && nxt <= post {
        // Reward proportionally to how well next item fills leftover.
        let fill_ratio = nxt as f64 / post as f64;
        score -= 60.0 * fill_ratio;
        // Harmonic class bonus: post_residual - next_item_size small
        let chain_left = post - nxt;
        if chain_left <= 10 {
            score -= 40.0;
        } else if chain_left < 10 {
            score += 0.0;
        }
    } else if nxt > post && nxt > 0 {
        // Next item won't fit here; leftover becomes potential dead space.
        score += 25.0;
    }

    // Modulo-class logic on post_residual: residues near capacity/2 are reusable.
    let r2 = post % (half as i64).max(1);
    if r2 == 0 {
        score -= 30.0; // exact half-class: versatile
    }
    let r4 = post % (quarter as i64).max(1);
    if r4 == 0 && post > 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when item is large
    // relative to mean residual (poor fits everywhere).
    if bin_residual == bin_capacity {
        let tight_elsewhere = mean_residual < item_size as f64 * 1.15;
        if tight_elsewhere {
            score -= 90.0; // opening fresh is fine
        } else {
            score += 150.0; // discourage wasting a fresh bin
        }
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 * (min_useful - post_residual) as f64;
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize mid-range dead space proportionally (non-linear).
    if post_residual >= min_useful && post_residual <= 30 {
        score += 0.35 * (30 - post_residual) as f64 * (30 - post_residual) as f64 / 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += 1.5 * open_bins_count as f64;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New bin candidate: only attractive when current bin would leave bad dead space
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0;
        if post_residual >= 50 { score -= 12.0; }
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 { score += 15.0; }
    }

    // Lookahead: reward if next item fits the post residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        score -= (8.0 - 0.1 * gap as f64).max(0.0);
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter packing).
    score += 0.4 * (mean_residual - bin_residual as f64).max(0.0);

    // Stream progression: later in stream, be greedier about exact fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual == 0) as u8 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= (1.0 - slack / bin_capacity as f64) * 25.0;
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize leaving awkward dead space
        let dead = post_residual as f64;
        if dead < next_item_size as f64 && dead > 0.0 {
            score += dead * 0.4;
        }
    }

    // Penalize bins with residuals far from mean_residual (avoid fragmenting)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin mildly unattractive unless
    // no good fit exists (post_residual would be huge waste elsewhere)
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; reduced late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 15.0 * progress;
        // If lookahead would pair well with a fresh bin, soften penalty
        if next_item_size > 0 && (bin_capacity - next_item_size) as f64 >= item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (dead space minimization)
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tightness * tightness;

    // Penalize residual gaps that no plausible future item can use
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 1.0 - 0.6 * t;
    if post_residual > 0 {
        let gap = post_residual as f64;
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // lookahead fits here: strong reward
            let slack = post_residual - next_item_size;
            score -= 10.0 + 0.15 * slack as f64;
        } else if next_item_size > 0 {
            // lookahead cannot use this bin's leftover: penalize dead space more
            score += horizon * 0.35 * gap;
        }
        // unusable micro-gap penalty
        if post_residual < 10 {
            score += 6.0 * (10 - post_residual as i32) as f64 * horizon;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage opening new ones, encourage consolidation
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / cap);
        score += 8.0 + 2.0 * pressure;
        // late in stream, opening new bins is costlier
        score += 20.0 * t;
    } else {
        // prefer bins with residual close to mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer filling bins that are already low (avoid spreading)
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fill;

    // Small item into large residual: mild penalty (wasteful pairing)
    if (item_size as f64) < 0.4 * (bin_residual as f64) && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let mean_res = mean_residual.max(0.0);

    // Base: prefer minimal post residual, with quadratic sharpening.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth non-linear coupling: post residual value weighted by stream progress.
    // Late in the stream, tight fits matter more.
    score += 0.9 * progress * (pr / cap) * (cap - pr) / cap;

    // Penalize leaving residuals that no future item can plausibly use
    // (smooth ramp around mean residual scale).
    let unusable = (pr - mean_res) / cap;
    score += 2.0 * (unusable * unusable) * cap * 0.05;

    // Reward last-chance bins (fitting_bins_count == 1) smoothly.
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 6.0 * last_chance;

    // Lookahead: bonus if next item fits exactly into post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 3.0 * (1.0 - gap / cap);
        } else {
            score += 1.5 * (gap / cap);
        }
    }

    // Mild penalty for proliferation of open bins late in the stream.
    score += 0.02 * (open_bins_count as f64).ln() * (1.0 + progress);

    // New-bin candidate: post_residual = cap - item_size is large; add a
    // smooth opening cost that shrinks when the item is big (near cap).
    if bin_residual == bin_capacity {
        score += 4.0 + 0.5 * (it / cap) * (cap - it);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    score -= 0.35 * (cap - post_residual as f64) / cap * 10.0;

    // Harmonic class of post_residual: residues near multiples of 10 are reusable.
    let r = post_residual % 10;
    if r == 0 {
        score -= 6.0;
    } else if r <= 2 {
        score -= 3.0;
    } else if r >= 8 {
        score += 4.0; // awkward residue, dead space
    } else {
        score += 1.5;
    }

    // Integer-division threshold: post_residual buckets of 20.
    let bucket = post_residual / 20;
    score += bucket as f64 * 1.2;

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let nr = post_residual - next_item_size;
            score -= 4.0 * (1.0 - nr as f64 / cap);
            if nr % 10 == 0 { score -= 3.0; }
        } else {
            // next item won't fit here; penalize leaving large gaps less if unavoidable
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    } else {
        // last item: just fill tightest
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: neutral-to-slightly-high baseline, but attractive
    // when existing bins have poor fits (large post_residual waste).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 0.55 * cap + 4.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // item can only go in a fresh bin anyway
        }
        if post_residual % 10 == 0 { score -= 2.0; }
    }

    // Mild pressure toward consolidating bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.4;

    // Deviation from mean residual: prefer bins that absorb surplus space.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 25.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 8.0; // nearly-full gap is fine
    } else if post_residual < 20 {
        score += 12.0; // small unusable gap: strong penalty
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward tight fits: relative fill of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill * fill;

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mean-residual coupling: penalize placing into bins far from mean residual
    // (keeps residual distribution tight, avoids stranding large gaps).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: make it attractive only when current bin fits are poor
    // (large post_residual gaps) or no open bin fits well.
    if bin_residual == bin_capacity {
        let best_gap_pressure = if post_residual == bin_capacity { 0.0 } else { 0.0 };
        let _ = best_gap_pressure;
        // Base cost of a fresh bin; offset by how bad the alternatives likely are.
        score = 30.0 + 0.2 * open_bins_count as f64 - 18.0 * (1.0 - fill.min(1.0));
        // If the item is huge, opening a fresh bin is often wise.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening bins (no future to amortize).
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for perfect / near-perfect fills.
    if post_residual == 0 {
