    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let tight_fit = post_residual < 15;
        if tight_fit {
            score += 50.0; // still allow new bin for near-perfect fits
        } else {
            score += 300.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Mild pressure to prefer fuller bins relative to the mean residual.
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, tighten packing (waste matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual), with a superlinear penalty on waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits in the post-residual (good pairing).
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 12.0;
            // Perfect chain: next item exactly fills remaining space.
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // Dead space for the next item: penalize proportionally.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.25 * gap;
        }
    }

    // Avoid consuming large-residual bins with tiny items; prefer filling them later.
    let rel_item = item_size as f64 / bin_capacity as f64;
    let rel_res = bin_residual as f64 / bin_capacity as f64;
    if rel_item < 0.35 && rel_res > 0.6 {
        score += 10.0 * (rel_res - rel_item);
    }

    // New-bin candidate: only attractive when item is large or existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (post_residual as f64 / bin_capacity as f64) > 0.45;
        if item_size >= 50 || poor_fits {
            score -= 6.0 + 8.0 * progress;
        } else {
            score += 15.0;
        }
    }

    // Mild preference for bins below the mean residual (balance the pool).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Late in the stream: consolidate aggressively, discourage opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling with stream progress:
    // late in the stream, dead space becomes more costly
    let late = progress * progress;
    score += 20.0 * late * norm_pr * norm_pr;

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack) * (1.0 - 0.5 * progress);
        } else {
            // cannot host next item: penalize proportionally to the gap
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mean residual context: prefer bins whose residual is near the mean
    // (keeps a balanced portfolio of open bins)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Mild preference for already-open bins over opening new ones
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    // Small regularization on item size coupling (larger items prefer fuller bins)
    score += 0.02 * item_size as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // "usable" vs "dead" buckets via integer division thresholds.
    let cap = bin_capacity as f64;

    // Post-residual as fraction of capacity.
    let post_frac = post_residual as f64 / cap;

    // Dead-space penalty: residuals that no plausible item (1..=100) can
    // split well are heavily penalized. Very small residuals (< 10) are
    // essentially dead; large residuals are fine.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Harmonic classes: residuals congruent to small values mod common
    // item sizes (e.g. mod 10, mod 25) are more reusable.
    let mod10 = post_residual % 10;
    let mod25 = post_residual % 25;
    if mod10 == 0 {
        score -= 8.0; // aligns with typical round sizes
    }
    if mod25 == 0 {
        score -= 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: penalize if this placement leaves a residual that can't
    // fit the next item while other structure would.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // keeps the bin useful for the next item
        } else if post_residual > 0 {
            score += 12.0; // wastes space given known lookahead
        }
        // Harmonic coupling: if next item exactly divides residual, reward.
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // offer poor fits. Give the empty bin a mild penalty that grows with
    // how good the average open-bin fit is.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If mean residual across open bins is large, open bins are roomy:
        // discourage new bin.
        score += (mean_residual / cap) * 40.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If many bins already fit the item, new bin is clearly wasteful.
        if fitting_bins_count > 2 {
            score += 15.0 * (fitting_bins_count as f64 - 2.0);
        }
    }

    // Mild penalty for spreading across many open bins when residual is
    // tight relative to mean.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
