pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual already does this).

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly host the next item, or at least fit it well.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr == n {
            // Perfect chain: this bin will be exactly filled next step.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly.
            let slack = pr - n;
            score -= 30.0 - (slack / bin_capacity as f64) * 25.0;
        } else {
            // Next item won't fit here: penalize leaving awkward residue,
            // especially if the leftover is small and unusable.
            let dead = pr / bin_capacity as f64;
            if pr < 10.0 {
                score += 15.0 * (1.0 - dead);
            } else {
                score += 5.0 * dead;
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than average are precious;
    // filling them is good, leaving them idle wastes them.
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.05 * diff;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many candidates, discriminate harder on fit quality.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin is a costly commitment.
    // Only allow it (via low score) when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut new_bin_penalty = 40.0;
        // As the stream progresses, consolidating matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 30.0 * progress;
        // If the item is large relative to typical residual space and
        // few bins fit it, opening fresh may be justified.
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if large_item > 0.7 {
            new_bin_penalty -= 20.0 * large_item;
        }
        if fitting_bins_count == 0 {
            new_bin_penalty -= 100.0;
        }
        // Lookahead: a fresh bin can host item + next item comfortably.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Small stabilizer: prefer filling nearly-full bins completely.
    if post_residual < 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
