        score -= 3.0 * large_item;
        if fitting_bins_count == 1 {
            score += 15.0; // discourage opening new bin if existing bin is last chance
        }
        if post_residual > 40 {
            score += 10.0; // opening a bin that stays too empty is bad
        }
    }

