            score += 5.0;
        }
        // harmonic class match: (post_residual - next) leaves a clean class
        if post_residual >= next_item_size {
            let r = (post_residual - next_item_size) % 10;
            if r == 0 { score -= 6.0; }
            else if r < 5 { score += 2.0; }
        }
    } else {
        // last item: prefer filling as tightly as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count == 0) as i32;
        if pressure == 1 {
            score -= 20.0;
        } else {
            score += 30.0;
        }
    }

    // Progress-aware tightening: late in the stream, waste is costlier
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 / bin_capacity as f64) * 20.0 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward filling large fractions of the bin (tight packing).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer existing bins over new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, this placement is synergistic.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        // Residual becomes dead space relative to the lookahead item.
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins below mean residual (balance-aware), but mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover dead space after the pair
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let overshoot = next_item_size - post_residual;
            score += overshoot as f64 * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than the mean.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 150.0 + item_size as f64 * 0.5;
        if next_item_size > 0 && next_item_size == item_size {
            score -= 100.0; // pairing identical items in a fresh bin is fine
        }
    }

    // Progression: later in stream, be slightly more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is naturally low, but amplify near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: excellent, especially a near-exact chain.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 15.0 - slack.min(20.0) * 0.5;
        } else {
            // Next item won't fit here after placement: penalize wasting a large
            // residual that could have held the next item.
            if bin_residual >= next_item_size && post_residual > 0 {
                score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
            }
        }
    }

    // Dead-space penalty: residuals too small for the minimum item size (1) are fine,
    // but mid-range dead space (e.g. 20-45) is the classic waste zone.
    if post_residual >= 20 && post_residual <= 45 && (next_item_size == 0 || next_item_size > post_residual) {
        score += 10.0;
    }

    // New-bin candidate handling: bin_residual == bin_capacity means an empty bin.
    // Default: penalize opening a new bin when open bins exist and fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = (bin_capacity - item_size) as f64 + 30.0;
        // Early in the stream, opening bins is cheap and keeps options open.
        new_bin_score -= (1.0 - progress) * 15.0;
        // If many bins are open, discourage fragmentation.
        new_bin_score += open_bins_count as f64 * 1.5;
        // If next item exactly complements this item in a fresh bin, allow it.
        if next_item_size > 0 && next_item_size + item_size == bin_capacity {
            new_bin_score -= 40.0;
        }
        // If no other bin fits well (large post_residual everywhere), opening up is fine.
        if mean_residual < item_size as f64 {
            new_bin_score -= 20.0;
        }
        score = score.min(score + new_bin_score);
        score += new_bin_score * 0.0; // keep base tightness signal
        return score.max(new_bin_score) * 0.0 + new_bin_score;
    }

    // Global state coupling: prefer bins with residuals below the mean (consolidate
    // waste into few bins rather than spreading it).
    score += (mean_residual - bin_residual as f64).clamp(-30.0, 30.0) * 0.2;

    // Slight time decay: late in the stream, be more conservative (favor tight fits harder).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 40.0 * poly;

    // Reward tight fits, stronger late in the stream
    let tight = 1.0 - norm_pr;
    score -= 60.0 * tight * tight * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth coupling)
    let dead = (pr as f64 - mean_residual) / cap;
    score += 20.0 * dead * dead.abs();

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let fit_next = next_item_size as f64 / cap;
        score -= 25.0 * fit_next * (1.0 - fit_next) * (0.3 + progress);
    } else if next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // Mildly discourage proliferation of open bins early
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: prefer opening a new bin only when residuals are fragmented
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 20.0 * mean_residual / cap - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that land on "useful" sizes
    // (multiples of 10 and small residuals are reusable; odd dead space is penalized).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else {
        let class = pr % 10;
        if class == 0 {
            score -= 12.0; // round residual, easy to fill later
        } else if class <= 3 {
            score += 6.0; // awkward sliver -> dead space
        }
        if pr < 10 {
            score += 8.0; // tiny unusable remainder
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0 * (next_item_size as f64 / pr.max(1) as f64);
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item is
    // large relative to capacity or existing bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - progress);
        score = 55.0 - 30.0 * pressure - 20.0 * crowded * (mean_residual / bin_capacity as f64).min(1.0);
    }

    // Mild exploration / tie-breaking via harmonic phase of step index.
    score -= (step_index % 7) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0; // unusable sliver penalty
    }
    if post_residual > 0 && post_residual < 5 {
        score += 25.0; // extreme dead space
    }

    // Reward perfect and near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0; // next item won't fit here: bin likely closes
        }
    }

    // Last-chance bin: using the only fitting bin avoids opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and discourage opening yet another bin.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly with open bins and stream progress.
        score += open_pressure + 20.0 + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // Allow a new bin only if the item is large relative to capacity and
        // existing residuals are small (mean_residual low).
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        if item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Existing bin: small bonus for being below mean residual (tighter bin).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits: penalize wasted space quadratically.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score += (1.0 - fit_ratio) * 12.0;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: this bin becomes exactly full next step
        } else if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            score += 6.0 + 0.25 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        }
    } else {
        // Last item: prefer filling bins as tightly as possible
        score += post_residual as f64 * 0.5;
    }

    // Compare leftover against mean residual across open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score -= 8.0; // leaving less slack than average is good consolidation
    } else if (post_residual as f64) > mean_residual {
        score += 5.0; // creating unusually large slack
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    // (i.e., item is large relative to typical residual or many bins already open).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - item_size) as f64 <= mean_residual * 0.6;
        if good_fit_exists {
            score += 40.0; // discourage opening new bin when a good open fit exists
        } else {
            score -= 10.0 + 10.0 * (1.0 - progress); // early stream: open bins more freely
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
