pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fills (low post_residual). Later: dead space
    // becomes costlier, so penalize quadratic/quartic growth of residual.
    let quad = norm_pr * norm_pr;
    let quart = quad * quad;
    score += progress * 40.0 * quad + progress * progress * 25.0 * quart;

    // Smooth reward for near-perfect fits, stronger as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= progress * 12.0 * tightness * tightness;

    // Penalize residuals too small for the lookahead item (dead space coupling).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        let waste = if next_item_size as u32 > post_residual {
            next_item_size as f64 - pr
        } else {
            0.0
        };
        score += waste * (0.5 + 0.5 * progress);
        score -= gap / cap * 6.0 * (1.0 - progress);
    }

    // Last-chance bin bonus (smooth, avoids hard piecewise behavior).
    if fitting_bins_count <= 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (balance).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    // Slight preference for consolidating into fewer bins early.
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    // New-bin candidate: neutralize its raw post_residual advantage smoothly.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity/4 tiers.
    let quarter = (bin_capacity / 4).max(1);
    let class = (post_residual / quarter) as f64;
    score += class * 4.0; // larger residual classes are worse unless next item fits

    // Reward when lookahead item fits into post_residual (chained placement).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.15 * (cap - chain_tightness);
    } else if next_item_size > 0 {
        // Lookahead cannot use this residual: penalize harmonic-dead classes.
        let dead = post_residual % quarter;
        score += 6.0 + 0.1 * dead as f64;
    }

    // Integer-division threshold: post_residual below 10 is near-perfect fill.
    if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score = cap * 1.5 - 5.0 * crowded.min(5.0);
        if fitting_bins_count <= 1 {
            score -= 10.0; // no real alternative, new bin is fine
        }
    }

    // Late-stream consolidation: tighten fits as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post_residual as f64) * 0.05;

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.2 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold any item (min size 1,
    // but tiny gaps < 12 are statistically hard to fill) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 25.0;
    }

    // Reward tight fits (post_residual small relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 30.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this bin is the only one that fits the item, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this placement; if post_residual is too small for next item,
    // penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += (open_bins_count as f64) * 2.0;

    // Mean residual coupling: if this bin's residual is well below the mean,
    // it is a good candidate to fill (reduces spread of residuals).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // New-bin candidate scoring: an empty bin has high residual; make it
    // attractive only when the item is large relative to capacity or when
    // no existing bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Large items are fine to start a new bin with.
        if item_size >= 60 {
            score -= 40.0;
        }
        // If this is the last chance bin, opening a new bin is worse.
        if fitting_bins_count == 1 {
            score += 200.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward bins that end nearly full.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // Chain feasibility: residual left after hypothetically placing next item.
            let chain_left = post_residual - next_item_size;
            score -= 25.0 - (chain_left as f64) * 0.35;
        } else {
            // Next item cannot follow into this bin: penalize wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.30;
        }
    }

    // Compare post_residual against mean residual: avoid creating outlier dead space.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.25;
    } else {
        score -= (mean_residual - pr) * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 45.0 - (open_bins_count as f64) * 2.0 - crowding * 25.0;
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Penalize dead space: residuals too small for any item (min size 1, but tiny scraps are risky)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Reward leaving room for the lookahead item (k=2 lookahead chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for next item: mild penalty for stranding space
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Coupling with global state: many open bins with high mean residual -> consolidate
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }

    // Time horizon: early in stream, be pickier about tight fits; late, just fill anything
    score -= 6.0 * progress * (1.0 - tightness);

    // New-bin candidate: baseline waste is its post_residual; add a fixed opening cost
    // so we only open a new bin when no open bin offers a decent fit.
    if is_new_bin {
        score += 25.0 - 10.0 * progress;
        // If the item is large, a fresh bin is fine (little waste possible)
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
        // If many bins are open, discourage spreading
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // tight fits (small post_residual) are rewarded more strongly later in the stream.
    let norm_post = post / cap;
    let coupling = norm_post * norm_post * (1.0 + progress) + norm_post * progress * 0.5;
    score += 30.0 * coupling;

    // Reward near-perfect fills with a smooth exponential term.
    score -= 12.0 * (-(post / cap * 4.0)).exp();

    // Lookahead: reward if the next item fits the post residual exactly-ish,
    // penalize if post residual is a "dead" sliver smaller than the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste = post - nxt;
            score -= 8.0 * (1.0 - waste / cap).max(0.0);
        } else {
            // dead space for the known next item: penalize proportionally
            score += 6.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so late in the
    // stream or when many bins are open with slack that could absorb the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // but if mean residual of open bins is too small to fit item, new bin is fine
        if mean_residual < item_size as f64 {
            score -= 18.0;
        }
    }

    // Slight preference for bins whose residual deviates from the mean
    // (consolidate slack): penalize bins much emptier than average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the item (modulo arithmetic on capacity) ---
    let cap_class = bin_capacity / 4; // 25 for C=100
    let item_class = (item_size % cap_class) as f64 / cap_class as f64; // 0..~1

    // Reward near-perfect fills: post_residual in a small "harmonic" residue band
    if post_residual <= 2 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 18.0;
    }

    // Penalize dead space that no future item can plausibly fill.
    // Items are 1..100; small residues < min plausible item are dead.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 + (dead_threshold - post_residual) as f64;
    }

    // Harmonic-class coupling: reward bins whose residual is congruent
    // to a "useful" class given the item class.
    let res_class = (bin_residual % cap_class) as f64 / cap_class as f64;
    score -= 6.0 * (1.0 - (item_class - res_class).abs());

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap_class as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 4.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing fit is terrible.
    if bin_residual == bin_capacity {
        // Opening fresh: neutral baseline plus pressure against bin proliferation.
        score += 12.0 + 0.05 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If the item fits snugly into a fresh bin (near-full packing), allow it.
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
    } else {
        // Reward tight fits into existing bins: waste ratio penalty.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 10.0 * waste;
        // Prefer fuller bins (small residual before placement).
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual steering: if this bin's residual is far below the mean,
    // it's an outlier worth closing out with a tight fit.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 3.0 * (dev / bin_capacity as f64);
    }

    // Integer-division threshold on post_residual: quantized usefulness tiers.
    let tier = post_residual / (bin_capacity / 10); // deciles
    score += 2.0 * (tier % 2) as f64; // odd deciles slightly penalized (awkward leftovers)

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 3.0;
    } else {
        score -= 5.0; // reward leaving usable space
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Pressure on number of open bins: mildly discourage spreading across many bins,
    // but relax pressure late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - 0.5 * progress);

    // Prefer bins whose residual is close to item size (tight fit relative to mean).
    score += ((bin_residual as f64) - (item_size as f64)).abs() * 0.3;
    score -= (mean_residual - (bin_residual as f64)).abs() * 0.2;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // New-bin candidate: keep it competitive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
        // If nothing else fits well, opening fresh is attractive.
        if post_residual >= next_item_size.max(1) as u32 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (1.0 - match_gap / bin_capacity as f64).max(0.0);

        // Perfect chain: item + next item fills bin exactly
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Next item fits exactly after this one, leaving small dead space
        else if post_residual > next_item_size {
            score -= 6.0;
        }
        // Next item won't fit here: penalize large post_residuals that become dead space
        else {
            score += 0.05 * post_residual as f64;
        }
    }

    // Penalize bins far from mean residual (avoid stranding outliers)
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: only one bin fits the item, strongly favor it over new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tight fits generally
    score += 0.4 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it unattractive unless item fits poorly everywhere
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * item_size as f64;
    }

    // Late in stream: be more conservative, keep residuals usable
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage consolidation
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low dead space after placement).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose post-residual is small but nonzero (unusable slivers),
    // unless it perfectly matches the lookahead item.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual >= next_item_size {
            // Reward leaving room for the next item exactly.
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= 15.0 / (1.0 + gap);
        } else if next_item_size == 0 || post_residual < next_item_size {
            // Dead space that the next item cannot use.
            score += 12.0;
        }
    } else {
        // Perfect closure of the bin is excellent.
        score -= 25.0;
    }

    // Prefer fuller bins over emptier ones among open bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: make opening a new bin costly unless the item
    // is large relative to what open bins waste, or many bins already fit it poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Cost grows with number of open bins; slight relief late in stream.
        score += 35.0 + open_bins_count as f64 * 2.0 - progress * 10.0;
        // If the item fits poorly anywhere (few fitting bins) and is large,
        // opening a fresh bin becomes more attractive.
        if fitting_bins_count <= 1 {
            score -= 20.0 + item_size as f64 * 0.2;
        }
        // If lookahead is large and this bin would be nearly full anyway,
        // a fresh bin may serve the pair better.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Mild time-horizon modulation: tighten packing as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post_residual as f64 / bin_capacity as f64;

    // Non-linear penalty on dead space that grows with stream progress
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual), stronger late in stream
    let tightness = 1.0 - norm_post;
    score -= 25.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead coupling: bonus if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let fit_quality = 1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 20.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        // Penalize wasted space the next item cannot use
        score += 8.0 * norm_post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Mild penalty when bin residual deviates from mean residual (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 10.0 * dev * dev;

    // New-bin candidate: neutral baseline, slightly penalized so it is only
    // chosen when existing bins score poorly
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: how well does leftover space partition the capacity?
    // Class by gcd with capacity and by divisibility bands.
    let g = gcd(post_residual, bin_capacity);
    if g > 1 {
        // residual shares structure with capacity -> potentially reusable
        score -= (g as f64) * 0.5;
    }

    // Dead-space bands: tiny residuals (<10) are nearly useless since min item is 1..100
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    } else if post_residual >= 50 && post_residual <= 60 {
        // mid band: fits half the common range
        score -= 10.0;
    }

    // Lookahead: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual -> penalize leftover
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
        // harmonic coupling: next item shares divisor with post_residual
        let g2 = gcd(next_item_size.max(1), post_residual.max(1));
        if g2 > 5 {
            score -= g2 as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        score = 70.0 - 0.1 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild consolidation pressure via mean residual
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Early stream: keep bins open/loose; late stream: tighten packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0;

    score
}

fn gcd(a: u32, b: u32) -> u32 {
    if b == 0 { a } else { gcd(b, a % b) }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residuals that can still host a typical future item (>= 10 or next item).
    if post_residual >= next_item_size && next_item_size > 0 {
        score -= 6.0;
    }
    if post_residual >= 10 {
        score -= 2.0;
    } else if post_residual > 0 {
        // residual below smallest possible item is wasted space
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize so we only open when fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
    }

    // Tight-fit reward relative to residual.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits after this placement: reward tight chains
            score -= 60.0 / (1.0 + diff / 20.0);
        } else {
            // Next item won't fit: penalize wasted residual relative to capacity
            score += 0.3 * post_residual as f64;
        }
    }

    // Prefer tight fits overall
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins far from mean residual (favor consolidation around mean)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely needed
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 0.0; // no-op, next item can never exceed capacity
        }
    }

    // Mild pressure to close nearly-full bins
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit emphasis: reward tight fits non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if post residual is just barely too small for
    // the next item, penalize the wasted near-miss space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 {
            (mean_residual / (bin_capacity as f64)).max(0.0).min(1.0)
        } else {
            1.0
        };
        score = 0.5 * (bin_capacity as f64) - 40.0 * pressure;
        // Early in the stream, opening bins is cheap and diversifies state.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // Too many open bins with large residuals: discourage yet another bin.
        score += 0.8 * open_bins_count as f64 * (mean_residual / (bin_capacity as f64));
        return score;
    }

    // Mild bonus for filling bins that deviate from mean residual (consolidation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev * (bin_residual as f64 - mean_residual).signum();

    // Slight preference to use older/more-filled bins when many bins are open.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_res = mean_residual;

    // Base: prefer small post_residual, with non-linear (quadratic) penalty
    let mut score = post + (post / cap) * (post / cap) * 20.0;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Coupling with mean residual: if this bin's post-residual is far below
    // the mean residual, it's a good consolidation -> reward.
    let mean_gap = mean_res - post;
    score -= 0.15 * mean_gap;

    // Lookahead: bonus if the leftover space can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else {
            // leftover too small for next item -> dead space penalty
            score += 0.1 * post;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize mildly early, more when many
    // bins already open and stream is late; allow it when post_residual of
    // alternatives would be large anyway.
    if bin_residual == bin_capacity {
        score = post + 5.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: near-zero post_residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of post_residual: classify leftover into usable classes.
    // Residuals that can host common small items (<= 20) are less "dead".
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        // Fractional dead-space penalty scaled by how unusable it is.
        let unusable = 1.0 - (post_residual as f64) / (dead_threshold as f64);
        score += 8.0 * unusable;
    }

    // Modulo arithmetic on post_residual vs typical item classes (10/20/25/50).
    let classes = [10u32, 20, 25, 50];
    let mut class_bonus = 0.0;
    for &c in &classes {
        if post_residual >= c {
            class_bonus += 6.0; // can host a canonical class exactly or better
        }
        if post_residual % c == 0 && post_residual > 0 {
            class_bonus += 3.0; // exact multiple: perfect future packing
        }
    }
    score -= class_bonus;

    // Integer-division threshold: post_residual bucket quality.
    let bucket = post_residual / 10;
    score -= (bucket.min(5)) as f64 * 2.0;

    // Lookahead: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * fit_ratio;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and many bins are open with slack.
    if bin_residual == bin_capacity {
        let slack = mean_residual - (bin_capacity - item_size) as f64;
        let base = 55.0;
        score += base
            - 0.5 * open_bins_count as f64
            - slack.max(0.0).min(40.0);
        // Early in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // If item is large, new bin is more acceptable.
        score -= (item_size as f64 / cap) * 20.0;
    }

    // Prefer bins with residual close to item (best-fit core), softly.
    let waste_ratio = post_residual as f64 / cap;
    score += 10.0 * waste_ratio * waste_ratio;

    // Mild pressure to fill bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are pure waste.
    // Penalize unusable slivers harshly (post_residual < 10 means nothing can ever go there).
    if post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual < 20 {
        // Semi-dead zone: only tiny items fit; mild penalty.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 10.0);
    }

    // Reward very tight fits (post_residual near zero but still usable is ideal).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else {
        score -= 20.0 * (1.0 - post_residual as f64 / 40.0).max(0.0);
    }

    // Fit quality relative to item size: small items in huge bins waste capacity.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: with many bins open, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Residual spread: favor bins below mean residual (tighter bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate handling: opening fresh is only attractive when no open bin
    // offers a decent fit (residual too small relative to item) or pressure is low.
    if bin_residual == bin_capacity {
        // Baseline cost of a new bin: high when many bins already open.
        score = bin_capacity as f64 * 0.9 + 3.0 * open_bins_count as f64;
        // If the current item would leave dead space everywhere, a new bin is competitive.
        if post_residual >= item_size {
            score -= 10.0;
        }
        // Early in the stream, new bins are cheap-ish; late, expensive.
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    // 2-step lookahead: perfect match with next item is excellent.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leftover dead space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: keep balance.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    // Last-chance bin: strong reward to use it rather than open new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize unless residuals of open bins are all too small.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0; // fresh bin pairs well with upcoming items
        }
    }

    // Late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tightness * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits into this bin's post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving awkward leftover.
        score += 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer bins with smaller residual (best-fit bias).
        score += 0.35 * (bin_residual as f64 - mean_residual);
    }

    // Prefer bins already below mean residual (consolidate space).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in stream, be more willing to open new bins;
    // late in stream, squeeze into existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading; few open bins: allow new bins.
    let bin_pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += bin_pressure * 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        // Perfect fit elsewhere should beat new bin; new bin gets mid-range score.
        score = (bin_capacity - item_size) as f64 + 12.0 - 25.0 * bin_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 + 2.0 * progress) + pr_norm * progress * progress;
    score += 0.6 * poly * cap;

    // Reward tight fits, amplified late in the stream
    let tightness = 1.0 - pr_norm;
    score -= 1.5 * tightness * tightness * (0.5 + progress);

    // Penalize small unusable residuals (dead space) with smooth quadratic
    let dead = if pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 4.0 * dead * dead;

    // Last-chance bin: strong smooth bonus to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 3.0 * progress;
    }

    // Lookahead coupling: favor bins whose post_residual can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = ((pr - nxt).abs()) / cap;
        score -= 2.0 * fits * (1.0 - gap * gap);
        score += 1.5 * (1.0 - fits) * (1.0 - gap);
    }

    // Mild preference for consolidating into fewer bins when residuals are large
    let mean_gap = (mean_residual - pr) / cap;
    score += 0.5 * mean_gap * mean_gap * (1.0 + open_bins_count as f64 * 0.05);

    // Smooth new-bin anchor: make empty bin slightly less attractive as stream matures
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (25, 50, 75, 0) are more reusable — reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let frac = (pr % quarter) / quarter; // in [0,1)
    let harmonic_bonus = if post_residual == 0 {
        -60.0 // perfect closure: best possible outcome
    } else if frac < 0.05 || frac > 0.95 {
        -25.0 // near quarter-boundary residual: highly reusable
    } else if frac < 0.15 || frac > 0.85 {
        -10.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division threshold on post_residual: small unusable slivers
    // (< 10, the minimum item size) are dead space — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with lookahead: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward, scaled by tightness.
            let tight = (next_item_size as f64) / (post_residual as f64);
            score -= 30.0 + 20.0 * tight;
        } else {
            // Next item won't fit here: mild penalty, worse if residual is mid-range.
            let mid = 1.0 - ((pr - cap * 0.25).abs() / (cap * 0.75)).min(1.0);
            score += 8.0 * mid;
        }
        // Modulo harmony: next_item_size in the same residue class (mod 10)
        // as post_residual suggests future divisibility.
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 6.0;
        }
    } else {
        // Last item: any residual is pure waste; prefer exact fill.
        score += 10.0 * (pr / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the item
    // is large and open bins are scarce of space.
    if bin_residual == bin_capacity {
        let scarcity = if open_bins_count == 0 { 1.0 }
            else { (mean_residual / cap).max(0.0).min(1.0) };
        score += 55.0 * scarcity - 20.0 * (item_size as f64 / cap);
        // Opening a bin is more attractive early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the item (tight fit) —
    // standard best-fit flavor via post_residual already, add mild refinement:
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    // Slight preference for fewer open bins being consumed efficiently:
    if open_bins_count > 0 && post_residual > 0 {
        score += (pr - mean_residual).abs() * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Usable residual: mild reward for tighter fits.
        score -= 0.3 * post_residual as f64;
    }

    // Reward bins whose residual is consumed to a large fraction.
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: prefer fewer open bins, but mildly (so bad fits still lose).
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would leave a tiny gap again, penalize.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 10 {
            score += 30.0;
        }
    }

    // New-bin candidate: attractive early or when current bin fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 15.0 + 10.0 * progress + 0.5 * mean_residual;
        // Allow new bin when almost nothing fits anywhere well.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near-exact fits (dead-space avoidance).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
        // Extra reward if next item fills the bin almost completely after this placement.
        let second_post = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - second_post / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize creating residual that is too small for the known next item.
        score += 15.0;
    }

    // Compare residual against mean residual across open bins: prefer leaving
    // residuals near the mean (keeps flexibility), penalize outliers.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive if the item is huge relative
    // to capacity (no open bin would keep useful space) or many bins already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let usage = item_size as f64 / bin_capacity as f64;
        // Reward opening a new bin when the item fills most of it.
        score -= 60.0 * usage * usage;
        // Penalize opening new bins when existing bins fit decently.
        if fit_ratio >= 0.5 {
            score += 45.0;
        }
        // Discard excess open-bin proliferation late in the stream.
        score += 2.0 * open_bins_count as f64;
    }

    // Slight early-stream bias toward consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via squared residual term.
    let norm_post = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * norm_post * norm_post;

    // Strongly penalize opening a new bin when it already fits somewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 120.0 + 15.0 * (fitting_bins_count as f64).ln();
        } else {
            // Only option: opening new bin is fine.
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits in post_residual, big reward (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 35.0;
            // Perfect chain: next item exactly fills the bin.
            if next_item_size == post_residual {
                score -= 50.0;
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            // Dead space risk: leftover too small for the next item.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 45.0 * waste;
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer filling bins with large residuals when many bins are open (bin consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    if !is_new_bin {
        score -= 0.15 * residual_gap;
    }

    // Time horizon: early in stream, be conservative about opening bins;
    // late in stream, close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += 25.0 * progress * (1.0 - progress) * 0.0; // neutralized
        score -= 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Penalize leaving residuals in the awkward 1..=10 range (unusable dead space).
    if post_residual >= 1 && post_residual <= 10 {
        score += 55.0;
    }

    // Mild bonus for near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large residuals are fine (bins can be filled later); late in the
    // stream, leftover space is increasingly costly, so we amplify it.
    let amp = 1.0 + 1.6 * progress * progress + 0.8 * progress * (1.0 - progress);
    score *= amp;

    // Quadratic dead-space penalty: residuals that are too small to ever fit a
    // typical item are wasted; penalize sharply as post_residual shrinks.
    let dead = (cap - post) / cap;
    score += 12.0 * post * post / (cap * cap) * (1.0 - dead);

    // Perfect fit reward: strongly subtract when the item nearly fills the bin.
    let tightness = 1.0 - post / cap;
    score -= 30.0 * tightness * tightness * tightness;

    // Lookahead coupling: reward if the next item fits the resulting residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let pair_fill = (item_size as f64 + nxt) / cap;
            score -= 14.0 * pair_fill * (1.0 - (post - nxt) / cap);
        } else {
            // Next item won't fit here: mildly penalize leaving a residual
            // just below the next item's size (near-miss waste).
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * (1.0 - progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (0.5 + progress);
    }

    // New-bin candidate handling: opening a bin is expensive early (many items
    // remain to fill it) but cheap late. Compare against mean residual quality.
    if bin_residual == bin_capacity {
        let early_benefit = (1.0 - progress).powi(2);
        let mean_waste = (cap - mean_residual) / cap;
        score = cap * (1.0 - 0.9 * early_benefit) + 8.0 * mean_waste * progress;
        // Never open a new bin when a perfect-ish fit exists elsewhere.
        if post_residual == 0 && item_size as f64 / cap > 0.9 {
            score += 1000.0;
        }
    }

    // Slight tie-break toward consolidating into fewer bins.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual via integer division
    let tight_class = post_residual / (bin_capacity / 10); // classes 0..=10
    score -= (10 - tight_class.min(10)) as f64 * 8.0;

    // Perfect fill
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no future item (min size 1) can use well:
    // residual below the small-item threshold is "usable", above is waste
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // near-perfect: small leftover is fine
    }

    // Modulo-harmonic coupling: reward residuals that match common item sizes
    let r = post_residual % 25;
    if r == 0 && post_residual > 0 {
        score -= 6.0;
    } else if r >= 20 {
        score -= 3.0;
    }

    // Lookahead: if next item fits the post-residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // extra reward if next item nearly fills remainder
        if post_residual - next_item_size < 10 {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; leftover likely wasted
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should be costly unless
    // the current fit is terrible or stream is early with few bins
    if bin_residual == bin_capacity {
        // base penalty for new bin
        score += 70.0;
        // early in stream: new bins cheaper (building diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 30.0;
        // if item is large relative to capacity, new bin is natural
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 25.0;
        }
        // if many bins fit the item, opening new is bad
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    } else {
        // favor bins whose residual is close to item (relative tightness)
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= tightness * 15.0;

        // prefer bins below mean residual (already partly filled)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Penalize spreading across too many open bins when a good fit exists
    if open_bins_count > 4 && post_residual > 0 && post_residual < 20 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest conceivable item are pure waste — penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tight-fit bonus: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Dead-space penalty scaled by how unusable the gap is for the lookahead item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 10.0; // gap likely reusable by the next item
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing
    // bins rather than opening new ones.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: must overcome consolidation pressure; penalize more
        // when many bins are already open.
        score += 25.0 + open_pressure;
        // Slightly cheaper to open a new bin early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= open_pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (best-fit behavior relative
    // to the fleet mean).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u32 == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual as u32 > next_item_size {
            let slack = post_residual as f64 - next;
            score -= 25.0 * (-slack / 15.0).exp(); // next item still fits, decaying bonus
        } else {
            let dead = next - post_residual as f64;
            score += 10.0 * (dead / 20.0).min(1.0); // next item won't fit; penalize dead space
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Compare against mean residual across open bins: prefer bins that become below-average residual
    // (concentrate packing), but penalize extreme fragmentation.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 5.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 8.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty for opening a new bin; reduced if the item leaves a large residual
        // that could match the next item, or when few bins fit the item.
        let mut new_bin_score = 40.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_score -= 15.0; // guaranteed 2-item fill in a fresh bin
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 50.0;
        }
        new_bin_score -= 10.0 * progress; // later in stream, consolidation matters less
        score = new_bin_score + pr;
    }

    // Mild fragmentation penalty: very small leftovers are hard to reuse.
    if pr > 0 && pr < 10.0 {
        score += 12.0 - pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.5 * tightness * tightness * bin_capacity as f64;

    // Penalize dead space: residuals too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: reward if the next item fits exactly into the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if this leaves large stranded space
            let stranded = post_residual as f64;
            if stranded > next_item_size as f64 * 0.0 + 15.0 && stranded < 30.0 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are chosen only for poor fits in open bins
        score += 20.0;
        // More open bins -> keep filling them; fewer -> cheaper to open new
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If item is large relative to capacity, opening fresh bin is more attractive
        score -= 0.15 * item_size as f64;
        // Late in stream, avoid opening bins (closing cost dominates)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    } else {
        // Reward using bins whose residual is below mean (consolidate small leftovers)
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high
    if mean_residual > 25.0 && !is_new_bin {
        score += 0.05 * (mean_residual - 25.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, scaled non-linearly (dead space gets worse quadratically)
    let mut score = pr * (1.0 + pr / cap);

    // Smooth coupling: as stream progresses, tight fits (small post_residual) become more valuable
    let tightness = 1.0 - pr / cap;
    score -= progress * tightness * tightness * 30.0;

    // Penalize bins whose residual deviates from mean residual (fragmentation spreading)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 10.0;

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * tightness;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling with post_residual)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        let fit_next = 1.0 / (1.0 + (gap / cap).abs() * 4.0);
        score -= fit_next * 8.0 * (1.0 - progress * 0.5);
        // If next item fits perfectly, big reward
        if gap == 0.0 {
            score -= 15.0;
        }
    }

    // Mild penalty on opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // But late in the stream, prefer consolidating: raise new-bin cost with progress
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional capacity features
    let frac = post_residual as f64 / bin_capacity as f64;
    let item_frac = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: bonus proportional to how little space remains
    let tightness = 1.0 - frac;
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover can host the lookahead item
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty, worse for large unusable leftovers
            score += 15.0 + 0.4 * post_residual as f64;
        }
    }

    // Harmonic class logic: bucket post_residual by integer division thresholds
    let class = post_residual / 10; // 10-wide harmonic classes
    match class {
        0 => score -= 40.0,                       // near-perfect fit
        1 => score -= 20.0,                       // good fit
        2 | 3 => score -= 5.0,                    // usable mid-range
        4 | 5 => score += 10.0,                   // awkward leftover
        _ => score += 20.0,                       // large leftover, wasteful
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 55.0;
        // More acceptable early in stream or with many open bins already fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        if open_bins_count == 0 { score -= 60.0; }
    }

    // Prefer bins with below-average residual (denser bins) to consolidate waste
    score += 0.15 * (mean_residual - post_residual as f64);

    // Mild penalty for very large items leaving large residues (coupling)
    if item_frac > 0.7 && post_residual > 0 {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward tight fits relative to bin size.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize bins whose residual deviates badly from the mean (fragmentation pressure).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full/fragmented.
    if bin_residual == bin_capacity {
        score = 60.0 + 3.0 * open_bins_count as f64 - 0.4 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // lookahead: big item next, keep space fresh
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0; // existing bins nearly exhausted, opening is fine
        }
    }

    // Mild pressure against hoarding many open bins.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead reward: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.5 * slack.min(30.0);
    } else if next_item_size > 0 {
        // Penalize creating residual too small for the next item (dead space).
        score += 8.0;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(40.0) * 0.6;
    } else {
        score += (pr - mean_residual).min(40.0) * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin, unless it enables a
    // perfect lookahead chain or current bins are nearly full on average.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            new_bin_penalty -= 20.0; // chain both items in a fresh bin
        }
        if mean_residual < item_size as f64 * 1.2 {
            new_bin_penalty -= 25.0; // open bins nearly exhausted anyway
        }
        score += new_bin_penalty;
    }

    // Slight preference for compacting bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Mild penalty for spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        let wasted = if (post_residual as u32) < next_item_size {
            post_residual as f64
        } else {
            0.0
        };
        score += 3.0 * wasted;
        // Reward bins whose post_residual still fits the next item well.
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if post_residual as u32 == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: heavily favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Scarcity pressure: many open bins with low mean residual -> avoid fragmenting.
    let pressure = mean_residual / bin_capacity as f64;
    if pressure < 0.3 {
        score += 12.0 * (0.3 - pressure);
    }

    // Early in stream: encourage opening/using fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it when item is large or fits are scarce.
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * large_item_bonus;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // Late in stream, prefer existing bins to avoid stranded capacity.
        score += 10.0 * progress;
    }

    // Mild preference for bins with residual close to item size (near-exact fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap * gap / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: reward low post residual, with smooth polynomial coupling to progress.
    // Early in the stream, keep bins flexible (penalize tiny post_residual more);
    // later, pack tightly (post_residual dominates).
    let mut score = post * (1.0 + 0.8 * (1.0 - progress) * (1.0 - progress));

    // Smooth non-linear penalty for "awkward" residuals that few future items can use.
    let awkward = (norm_post * std::f64::consts::PI).sin();
    score += 12.0 * awkward.abs() * (1.0 - norm_post) * (0.5 + 0.5 * progress);

    // Lookahead coupling: reward if the next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let fit_quality = 1.0 - (post - nx) / cap;
            score -= 10.0 * fit_quality * fit_quality;
        } else {
            score += 5.0 * (nx - post) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many open bins exist relative to mean residual (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: make it unattractive unless post_residual is large and
    // no tight fit is achievable (smooth logistic-like gate).
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-8.0 * (norm_post - 0.3)).exp());
        score += 25.0 * gate + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in "nice" classes
    // (multiples of 10 / exact halves / exact quarters) are more reusable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill is best
    } else if pr % 10 == 0 {
        -12.0 // decile residual: highly reusable
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 40 {
        -3.0 // still roomy, tolerable
    } else {
        8.0 * (10 - (pr % 10)) as f64 / 10.0 // awkward small residual penalty
    };
    score += class_bonus;

    // Integer-division threshold: penalize post_residual in the "dead zone"
    // (1..=9) where almost no item (min size 1, typical >=10) fits.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Coupling with the lookahead item: if the next item fits the post
    // residual exactly or comfortably, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // perfect chain
        } else if next_item_size <= pr {
            let fit_ratio = next_item_size as f64 / pr as f64;
            score -= 20.0 * fit_ratio; // tighter next-fit is better
        } else {
            // next item won't fit here; slight penalty proportional to gap
            let gap = (next_item_size - pr) as f64;
            score += (gap / 50.0).min(10.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give the fresh bin a moderate base score so
    // decent open bins beat it, but poor fits (large post_residual spread
    // vs. mean) do not.
    if bin_residual == bin_capacity {
        score = 55.0 + (item_size as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large items coming: a fresh bin is fine
        }
    } else {
        // Prefer bins whose residual is already below the mean (consolidation)
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev; // lower residual than mean => subtract => favored
    }

    // Late-stream pressure: as the stream progresses, discourage opening
    // extra bins by slightly favoring existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 8.0 * progress;
    }

    // Many open bins: penalize spreading into the emptiest bins less;
    // encourage closing tight bins first via modulo class of residual.
    if open_bins_count > 4 && pr % 2 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that can only fit tiny items are nearly dead too.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tight fits proportionally.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 30.0 * tightness;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
        // Extra reward if next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    } else if next_item_size > 0 && next_item_size <= item_size {
        // Next item won't fit here but is small; mild penalty for wasting space.
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: only prefer a fresh bin when all open bins
    // would leave large unusable gaps.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 95.0;
        if fitting_bins_count == 0 {
            // No alternative: new bin is fine.
            score -= 100.0;
        } else if post_residual < 10 && next_item_size > post_residual && next_item_size >= 10 {
            // Existing bins would create dead space; opening is better.
            score -= 80.0;
        }
        // Late in the stream, opening new bins is less harmful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        return score;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual means tight packing already).
    if mean_residual > 0.0 {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that will be left with little wasted space,
    // but reward a residual that exactly matches the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 45.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: this placement leaves exactly the next item's size.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Placement that strands a tiny unusable residual (< 10) is bad.
        if post_residual > 0 && post_residual < 10 {
            score += 15.0;
        }
    }

    // Compare against the average slack of open bins: filling an
    // above-average-slack bin is preferable.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we only open a new
    // bin when no decent fit exists, but keep it competitive when the item
    // is large (little to gain from squeezing into a partial bin).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = 95.0 - 20.0 * fill_ratio - 10.0 * progress;
    }

    // Slight bonus for tighter fits overall (small item in small residual).
    score -= 0.3 * (item_size as f64 / bin_residual.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit bonus: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot host a typical future item.
    if post_residual > 0 {
        let dead = (post_residual as f64 / 100.0).powf(2.2);
        score += 10.0 * dead;
    }

    // Lookahead: if the next item fits the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward when the pairing nearly exhausts the bin.
        let pair_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * pair_fill;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; penalize leaving awkward slivers.
        let sliver = post_residual as f64 / next_item_size.max(1) as f64;
        if sliver < 0.5 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless
    // existing bins fit poorly or are heavily fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else {
            0.0
        };
        // Base penalty for opening a new bin.
        score += 30.0 + 25.0 * (1.0 - progress);
        // If open bins are fragmented (high mean residual relative to item),
        // opening a fresh bin becomes more attractive.
        if fragmentation > 0.35 {
            score -= 20.0 * (fragmentation - 0.35);
        }
        // If many bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count.min(5) as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Slight preference to fill bins with larger residual when many bins open.
    score += 0.05 * (open_bins_count.min(20) as f64) * (bin_residual as f64 / bin_capacity as f64);

    // Time-horizon modulation: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * tightness;

    // Small tie-breaker favoring bins whose residual is close to mean residual
    // (keeps bin residuals balanced for future flexibility).
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize stream progress and residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_mean = mean_residual / cap;

    // Smooth non-linear coupling: quadratic in normalized post residual,
    // modulated by stream progress. Early on, prefer tight fills mildly;
    // late in the stream, dead space is more costly (waste accumulates).
    let progress_coupling = norm_post * norm_post * (0.5 + progress);
    score += 20.0 * progress_coupling;

    // Lookahead synergy: if the next item fits exactly into the post residual,
    // strongly reward this placement (smoothly decaying as gap shrinks).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let lookahead_bonus = (-gap / (0.25 * cap)).exp();
        score -= 15.0 * lookahead_bonus * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: if this is the only fitting bin, penalize rejection
    // (opening a new bin) unless the fit is very poor.
    if fitting_bins_count == 1 {
        let fit_quality = 1.0 - norm_post;
        score -= 8.0 * fit_quality;
    }

    // New-bin candidate handling: an empty bin has high post residual; make
    // its score depend on how fragmented the open bins are (mean residual).
    // If open bins are already fragmented (high mean residual), opening a new
    // bin is relatively more attractive.
    if bin_residual == bin_capacity {
        let fragmentation = (norm_mean - 0.5).clamp(0.0, 1.0);
        score += 5.0 - 10.0 * fragmentation;
    }

    // Mild penalty for bins whose residual deviates far from the mean,
    // encouraging balanced residual distribution across open bins.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Small smooth reward for tight fits overall.
    score -= 6.0 * (1.0 - norm_post).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as u32;

    // Reward near-perfect fits: post_residual in small harmonic classes
    if post == 0 {
        score -= 50.0;
    } else if post <= eighth {
        score -= 20.0;
    } else if post <= quarter {
        score -= 8.0;
    } else if post <= 2 * quarter {
        score -= 2.0;
    } else {
        // large dead space penalty, worse for big leftovers
        score += (post - 2 * quarter) as f64 * 0.15;
    }

    // Integer-division class: post_residual divisible by small moduli is more reusable
    if post > 0 && (post % 10 == 0 || post % 5 == 0) {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            score -= (post - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += (next_item_size - post).min(30) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is a fallback, not a preference
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of a fresh bin
        score += 30.0;
        // cheaper to open early when few bins exist; costlier when many open bins idle
        score += open_bins_count as f64 * 2.0;
        // if plenty of bins can fit, opening new is bad
        if fitting_bins_count > 1 {
            score += 20.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (tighter bins get filled first)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Mild preference for more-filled bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (items in 1..=100) are effectively wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable gap
    } else if post_residual >= 10 && post_residual < 30 {
        score += 18.0; // risky gap, only fits small items
    }

    // Reward tight fits strongly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item cannot use this residual -> it is more likely dead space
            score += (post_residual.min(next_item_size) as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 55.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin
    // only for very poor fits; otherwise encourage consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 4.0;

    // Relative-to-mean residual shaping: bins below mean residual are "fuller",
    // favor them slightly; bins far above mean risk fragmentation.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate calibration: an empty bin gets score = bin_capacity
    // adjusted below; make new bin attractive only when current fit is bad.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 20.0 - 45.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative anyway
        }
        if post_residual < 10 {
            score += 0.0; // empty bin never creates dead space
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Core: prefer small post_residual (tight fit)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 30.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large residual that invites fragmentation
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading; prefer filling existing bins
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate (empty bin): only attractive when current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        // penalize opening new bin normally, but less when item leaves big residual elsewhere? 
        // Actually new bin: post_residual = capacity - item_size.
        score += 15.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain with next item
        }
        let _ = bad_fit;
    }

    // Penalize dead space that nothing (min size 1) could reasonably use later
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post-residuals.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residual too small to ever be useful
    // (smaller than the minimum plausible item, or smaller than the next item).
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead synergy: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly awful.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: an empty bin has a neutral-to-high score so that
    // it is chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened late in the stream or when
        // existing residuals are large (open bins are crowded anyway).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let mut new_bin_score = 45.0 - 15.0 * progress - 20.0 * crowding;
        // If the item is large, filling a fresh bin is more attractive.
        new_bin_score -= 0.1 * item_size as f64;
        // If no open bin can fit at all, opening is mandatory: make it cheap.
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    // Mild penalty for proliferating bins when existing bins still have room.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score += 0.3 * open_bins_count as f64 * (1.0 - tightness);
    }

    // Small time-horizon modulation: early in the stream, slightly favor
    // consolidating into fewer bins; late, prefer tight fits aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear penalty on wasted residual, growing with stream progress
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= 8.0 * (1.0 - norm_pr).exp() * (0.4 + 0.6 * progress);

    // If next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 / cap;
            score -= 10.0 * (1.0 - slack).exp();
        } else {
            // next item won't fit: mild penalty scaled by overflow size
            score += 0.05 * (nx - pr).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Crowding: with many open bins, prefer filling existing ones
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // Align with mean residual: bins far from mean residual get slight penalty
    score += 0.02 * (pr - mean_residual).abs();

    // New-bin candidate: make it attractive only when current bins would waste a lot
    if bin_residual == bin_capacity {
        score = pr - 3.0 + 6.0 * norm_pr * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes capture dead-space structure
    let post_class = post_residual % 10;
    let class_penalty: f64 = match post_class {
        0 => -6.0,          // perfect / reusable decade residual
        1 | 9 => 2.0,       // nearly-dead slivers
        2 | 3 | 4 => 1.0,   // awkward mid slivers
        5 => -2.0,          // half-bin residual is highly reusable
        _ => 0.5,
    };
    score += class_penalty;

    // Reward tight fits: small post_residual relative to item
    let tightness = (post_residual as f64) / (item_size.max(1) as f64);
    score -= 8.0 * (1.0 / (1.0 + tightness));

    // Lookahead: strongly favor bins whose residual pairs with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect two-item closure
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 / (1.0 + slack / 10.0));
        } else {
            // next item cannot use this residual: penalize by leftover gap
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / 50.0);
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post_residual as f64).max(0.0);
        let pressure = open_bins_count as f64;
        // opening a fresh bin is penalized mildly, more so with many open bins
        score += 15.0 - 0.8 * pressure;
        // but rewarded if mean residual across open bins is large (fragmentation)
        score -= (mean_residual / cap) * 10.0;
        let _ = mean_gap;
    }

    // Progress-based tuning: later in the stream, prefer consolidating
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 / (1.0 + post_residual as f64 / 20.0));

    // Small tie-break noise-free coupling with bin fill level
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 2.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (unusable gaps).
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins whose residual is already
    // below average (they are "worse" bins that should be filled up),
    // penalize drawing down above-average residuals.
    let resid = bin_residual as f64;
    score += (resid - mean_residual) * 0.35;

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins as open_bins_count grows.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward;
    // if post_residual is just below the next item (dead space), penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 20.0;
        } else if (post_residual as f64) < nxt && post_residual > 0 {
            score += (nxt - post_residual as f64) * 0.8;
        }
    }

    // New-bin candidate: base score for an empty bin; only attractive when
    // no open bin offers a decent fit (poor fits already penalized above).
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild stream-progression tilt: later in the stream, close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linearly.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64); // quadratic dead-space penalty
    }

    // 2-step lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 45.0;
        } else if (next_item_size as u32) < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 20.0 - (leftover as f64) * 0.25; // good chain, penalize slack
        } else {
            score += 10.0; // next item cannot follow here
        }
        // small lookahead coupling with mean residual
        score += 0.15 * (pr - mean_residual);
    }

    // Penalize waste relative to mean residual of open bins.
    score += 0.3 * ((post_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild pressure against proliferating open bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.0 - progress) * 0.4;

    // New-bin candidate: neutral-ish baseline with slight penalty so it is
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a nonlinear bonus.
    score -= 8.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize dead space that cannot hold the next item (lookahead k=2).
    if next_item_size > 0 {
        let slack = post_residual as f64 - next_item_size as f64;
        if slack < 0.0 {
            score += 2.5 * (-slack);
        } else {
