            score -= 1.5 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage fragmenting further; few bins: allow spreading.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates below the mean (consolidate emptier space usage).
    score += 0.6 * (bin_residual as f64 - mean_residual);

    // Early in the stream: be more tolerant of opening new bins (explore);
    // late: strongly prefer packing into existing bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 6.0 + 18.0 * progress;
        // Opening a new bin is fine if item is large and no tight fit exists.
        if item_size >= 60 && post_residual <= 40 {
            score -= 8.0 * (1.0 - progress);
        }
    }

    // Slight preference for bins that end exactly full.
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear penalty growth.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is penalized more aggressively.
    let progress_coupling = (1.0 + progress * progress) * (1.0 + 0.8 * progress * norm_pr);
    score *= progress_coupling;

    // Lookahead: reward residual that can host the next item (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 } else { (pr / nxt).max(0.0) };
        score -= 12.0 * fits_next * (1.0 - progress * 0.5);
        // Penalize residuals just below next item size (dead space pattern).
        let gap = nxt - pr;
        if gap > 0.0 {
            score += 6.0 * (gap / cap) * (gap / cap) * 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 8.0 * open_norm * norm_pr;

    // Align with mean residual: bins far from mean residual are slightly deprioritized
    // (smooth quadratic deviation).
    let dev = (pr as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score = pr + 20.0 - 18.0 * (fitting_bins_count == 0) as f64 * (1.0 + progress);
        // If other bins fit, make new bin clearly worse than a decent fit.
        if fitting_bins_count > 1 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals in "usable" classes
    // (divisible into common small item sizes), penalize dead-space classes.
    let pr = post_residual as i64;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if pr <= 10 {
        -30.0 // near-perfect, nearly dead anyway
    } else if pr % 10 == 0 {
        -18.0 // aligns with typical item granularity
    } else if pr % 5 == 0 {
        -10.0
    } else {
        4.0 // awkward residual
    };
    score += class_bonus;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // fraction of post residual consumed by next item
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot use this residual: mild penalty scaled by leftover size
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this bin would
    // leave a large awkward residual and many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let awkward = (bin_residual - item_size) as f64;
        let threshold = 0.35 * bin_capacity as f64 * (0.5 + 0.5 * progress);
        if awkward > threshold && open_bins_count > 2 {
            score -= 12.0; // fresh bin competitive
        } else {
            score += 35.0; // prefer existing bins
        }
    }

    // Tightness reward: reward high fill ratio of the bin.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Mild preference to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins below-mean residual (tighter bins).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
