    }

    // Reward bins whose residual is close to the mean (typicality) slightly,
    // and penalize extreme outliers that fragment capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild early-stream aggressiveness: fill bins tighter early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

