        // open new bin when item is large and would leave tiny gap elsewhere
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Progress-aware: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / 100.0);

    // Mean residual coupling: prefer bins deviating from mean toward tighter
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Modulo-based class shaping on item size vs residual
    if bin_residual % 25 == 0 && item_size % 25 == 0 {
        score -= 15.0;
    }
    if r == 0 && pr > 0 {
        score -= 5.0 * (q as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Dead space = post_residual too small to ever fit a plausible item (min size 1,
    // but practically gaps under ~20 are hard to fill). Penalize quadratically.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate and bins that waste space).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocks the next item -> penalize
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: make it moderately attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.3;
        // But if nothing fits well (this item would leave a tiny gap elsewhere),
        // opening fresh is fine.
        if post_residual >= 20 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty proportional to wasted space, quadratic for dead space.
    let waste = post_residual as f64;
    score += 0.5 * waste + 0.004 * waste * waste;

    // 2-step lookahead: reward if the NEXT item can fit into the post residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            // Perfect two-item packing: post_residual exactly matches next item.
            let gap = (post_residual as f64 - n).abs();
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            score -= 10.0; // lookahead bonus
        } else {
            // Next item won't fit here: penalize leftovers that are too small to be useful.
            let useless = post_residual as f64;
            score += 0.3 * useless * (1.0 + useless / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // prefer filling bins whose residual is close to the item (tight fit).
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tight;

    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual.max(1.0);
        // Favor bins tighter than average (below-mean residual => negative rel => lower score)
        score += 8.0 * rel;
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 10.0 * (open_bins_count as f64).sqrt() - 5.0 * progress;
        // But if no open bin can fit (this new-bin call is the only fitting candidate), allow it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for consolidating: fewer open bins is better.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space that cannot hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 12.0;
        if mean_residual < item_size as f64 + 5.0 {
            score -= 15.0; // existing bins are nearly full; new bin is fine
        }
        if open_bins_count > 20 {
            score += 3.0 * (open_bins_count as f64 / 20.0);
        }
    }

    // Global state: prefer filling bins when many are open and residuals are large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * (mean_residual / cap) * (1.0 - progress);

    // Slight preference to keep residual aligned with common item sizes.
    let r = post_residual as f64;
    if r >= 10.0 && r <= 80.0 {
        score -= 3.0 * (1.0 - (r / 80.0).abs() - (r / 10.0).abs()).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = item_size as f64 / cap;
    let norm_pr = pr / cap;

    let mut score = norm_pr * (1.0 + 0.8 * progress);

    // smooth coupling: penalize large residual more as stream progresses
    score += 0.6 * norm_pr * norm_pr * (0.5 + progress);

    // reward tight fits (small post_residual) with smooth term
    score -= 1.5 * (1.0 - norm_pr) * (1.0 - norm_pr) * fill;

    // lookahead: favor bins whose residual matches next item size (smooth Gaussian-like)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let d = (pr - nxt) / cap;
        score -= 1.2 * (-d * d * 12.0);
    }

    // last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // new-bin candidate: mildly penalize so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * progress + 0.3 * open_bins_count as f64 / (1.0 + mean_residual / cap);
    }

    // mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.4 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: penalize opening a bin unless residual is very tight.
    if bin_residual == bin_capacity {
        score += 18.0 - 0.05 * post_residual as f64;
    }

    // Last-chance bin: reward strongly to avoid opening new bins unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }

    // Mean residual alignment: prefer bins close to the mean residual.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chains two items).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * next_item_size as f64;
        if post_residual == next_item_size {
            score -= 40.0; // exact two-item fill
        }
    }
    // If next item cannot fit in post_residual, penalize leaving awkward space.
    else if next_item_size > 0 {
        score += 0.25 * (next_item_size as f64 - pr).min(50.0);
    }

    // Compare post_residual against mean residual: avoid creating outliers.
    score += 0.4 * (pr - mean_residual).abs();

    // Penalize waste relative to mean residual.
    if pr > mean_residual {
        score += 0.3 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    score -= 0.15 * open_bins_count as f64;

    // Early in stream: slightly favor opening new bins (keeps options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately so it's chosen only when fits are bad.
        score += 20.0 - 15.0 * progress;
        if pr == 0.0 { score += 0.0; } // no-op guard
        // If no good fit exists (large dead space avoided by new bin), new bin wins.
        if post_residual > 40 {
            score -= 5.0;
        }
    }

    // Penalize bins that would leave residual smaller than the minimum item size (dead space),
    // unless it's exactly zero.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small unusable leftovers (dead space below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward leaving room for the lookahead item if it would fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        let lookahead_fit = next_item_size as f64 / post_residual as f64;
        score -= 6.0 * lookahead_fit;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize creating a residual too small for the next item.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fill_ratio > 0.7 || (fitting_bins_count == 1 && bin_residual != bin_capacity) {
            score += 40.0;
        }
        // Later in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins with less residual relative to the mean (pack fuller bins first).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild pressure to keep bin count low: reward placing into existing bins
    // proportionally to how many are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let x = pr / cap;

    // Smooth non-linear coupling: penalize tiny residuals more as stream progresses
    let dead = (1.0 - x).powf(2.0 + 3.0 * progress);
    score += 8.0 * dead * (x * (1.0 - x)).sqrt().max(0.0) * (1.0 - x);

    // Reward tight fits, stronger early
    score -= 6.0 * (1.0 - x) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - x);
    }

    // Lookahead: reward residuals matching next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let match_term = 1.0 - ((pr - n).abs() / cap);
        score -= 4.0 * match_term.max(0.0) * (pr / n.max(1.0)).min(1.0);
    }

    // Mild penalty for spreading across many bins
    score += 0.3 * open_bins_count as f64 * x;

    // Prefer bins below mean residual (balance)
    score += 0.5 * (pr - mean_residual);

    // New-bin candidate: penalize unless residuals are all poor
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / cap;
        score += 10.0 - 12.0 * avg_fit * avg_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: post_residual buckets via integer division.
    let pr = post_residual as i64;
    let class = pr / 10; // decile classes of residual
    match class {
        0 => score -= 60.0,        // residual 0..9: nearly full bin, great
        1 => score -= 25.0,        // 10..19
        2 => score -= 5.0,         // 20..29
        3 => score += 15.0,        // 30..39
        4 => score += 30.0,        // 40..49
        5 => score += 40.0,        // 50..59
        _ => score += 50.0,        // large leftovers
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Modulo arithmetic on capacity fractions: residual that cannot combine with
    // common small items is penalized.
    let cap_frac = bin_capacity / 4; // 25
    if post_residual >= 1 && post_residual < cap_frac {
        // residual in (0,25): only useful if next item fits
        if next_item_size == 0 || next_item_size > post_residual {
            score += 20.0;
        }
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 35.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin only before this placement
        score += 10.0;
    }

    // Harmonic pairing: post_residual + next_item_size close to capacity is great.
    if next_item_size > 0 {
        let combo = post_residual + next_item_size as i64;
        if combo == bin_capacity as i64 {
            score -= 80.0;
        } else if combo > bin_capacity as i64 {
            score += 15.0;
        }
    }

    // Last-chance bin: avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: keep it attractive only when current open bins are crowded
    // or this placement would waste a lot.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        if mean_residual >= item_size as f64 * 2.0 && open_bins_count > 0 && crowding > 0.35 {
            score += 120.0; // prefer existing bins
        } else {
            score -= 30.0; // opening fresh bin is fine
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    // Prefer bins with residual below mean (tighter bins get filled first).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals that are too small for any plausible item (min item size 1..100, but
    // small gaps < 10 are effectively dead space) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }
    // Penalize residuals that cannot fit the next item (lookahead-aware dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward residuals that exactly fit the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Reward near-perfect fits (post_residual small but usable)
    if post_residual >= 10 && post_residual <= 25 {
        score -= 8.0;
    }

    // --- Tight fit reward: fraction of bin consumed by this placement ---
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // --- Open bins pressure ---
    // When many bins are open, prefer consolidating into existing bins
    // (raise new-bin score); when few bins are open, opening is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = (open_bins_count as f64).ln() * 6.0 * (0.4 + 0.6 * progress);
    score += open_pressure;

    // --- Mean residual coupling: if this bin's residual is far below mean, it's a
    // good "garbage collector" bin; if far above mean, placing here wastes space ---
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin; grows with number of open bins.
        let mut new_bin_score = 35.0 + 8.0 * open_bins_count as f64;
        // If no open bin can fit (this is the only candidate), opening is fine.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // If the current item is large and the next item is also large, a fresh bin
        // is valuable (keeps large items together cleanly).
        if item_size > 50 && next_item_size > 50 {
            new_bin_score -= 30.0;
        }
        // Early in the stream, opening bins is cheap.
        new_bin_score -= 15.0 * (1.0 - progress);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to zero is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize dead space that no plausible item (min size 1) can fill later;
        // weight by fraction of capacity wasted.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += waste_frac * 40.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: residual after chain is post_residual - next_item_size.
            let chain_residual = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement: mild penalty,
            // scaled by how much we overshoot.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / bin_capacity as f64).min(1.0);
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual is below average (they are already "tight"); penalize bins
    // with large residual relative to mean (encourages consolidating into
    // already-loose bins only when it pays off).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * residual_gap;

    // Last-chance bin: if this is the only bin that can fit the item,
    // using it avoids opening a new bin — reward it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual.
    // Prefer reusing an existing bin unless the fit there is poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus a term that decreases as
        // open bins grow (encourages closing out stream by not over-opening).
        score = (bin_capacity as f64) * 0.9
            + 3.0 * (open_bins_count as f64).sqrt()
            + 5.0 * (step_index as f64 / (total_items.max(1) as f64));
        // If no existing bin fits well (post_residual of best alternative is
        // unknown here), make new bin less attractive generally; lookahead:
        // a fresh bin is good if the next item is large.
        if next_item_size > 0 {
            score -= 0.2 * next_item_size as f64;
        }
    }

    // Mild preference to fill older/more bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}
